function getOnlineFxInvocationFromRef(ref) {
  if (!ref || ref.unitId == null || ref.playerId == null) return null;
  const unit = getUnitById(Number(ref.playerId), ref.unitId);
  return unit ? { ownerPlayerId: Number(ref.playerId), unit } : null;
}

function shouldSuppressOnlineFxForHiddenOpponent(type, payload = {}) {
  if (!isOnlineMatchActive() || LOCAL_PLAYER_ID == null) return false;
  const sourceRef = getOnlineFxInvocationFromRef(payload.source || payload);
  const targetRef = getOnlineFxInvocationFromRef(payload.target || null);
  const sourceHidden = sourceRef && isOnlineUnitConcealedFromViewer(sourceRef.ownerPlayerId, sourceRef.unit);
  const targetHidden = targetRef && isOnlineUnitConcealedFromViewer(targetRef.ownerPlayerId, targetRef.unit);
  if (sourceHidden) return true;
  if (targetHidden) {
    const targetRevealingTypes = new Set([
      'floating-text', 'floating-damage', 'critical-damage', 'critical-slash',
      'armor-reduction', 'blindness-debuff', 'kurayami-execution-cue',
      'kurayami-execution-damage', 'shirahadori-redirect', 'minokage-hit-slash'
    ]);
    if (targetRevealingTypes.has(String(type || ''))) return true;
  }
  return false;
}

function getOnlineFxPolicy(type) {
  const definition = ONLINE_FX_DEFINITIONS[String(type || '')];
  if (!definition) return null;
  return {
    playbackMode: definition.playbackMode === 'parallel' ? 'parallel' : 'serial',
    maxReplayAgeMs: Math.max(1000, Number(definition.maxReplayAgeMs || 9000)),
  };
}

async function playOnlineVisualEvent(event = {}) {
  const type = String(event.type || '');
  const definition = ONLINE_FX_DEFINITIONS[type];
  if (!definition) {
    ONLINE_FX_RUNTIME_STATS.unsupported += 1;
    return false;
  }
  const generation = ONLINE_FX_RUNTIME_GENERATION;
  const payload = event.payload || {};
  if (shouldSuppressOnlineFxForHiddenOpponent(type, payload)) return false;
  let playbackResult;
  ONLINE_FX_REPLAY_DEPTH += 1;
  try {
    if (generation !== ONLINE_FX_RUNTIME_GENERATION) return false;
    // Los handlers emiten, si corresponde, al inicio síncrono de la función.
    // El guard solo cubre ese tramo para no silenciar acciones LOCALES mientras
    // una animación remota larga continúa con awaits o timers.
    playbackResult = definition.play(payload, event);
  } catch (error) {
    ONLINE_FX_RUNTIME_STATS.failed += 1;
    try { reportDebugError(`online-fx-play:${type}`, error); } catch (_) {}
    return false;
  } finally {
    ONLINE_FX_REPLAY_DEPTH = Math.max(0, ONLINE_FX_REPLAY_DEPTH - 1);
  }
  try {
    await playbackResult;
    if (generation !== ONLINE_FX_RUNTIME_GENERATION) {
      removeOnlineVisualFxNodes();
      return false;
    }
    registerOnlineFxPlay(type);
    return true;
  } catch (error) {
    ONLINE_FX_RUNTIME_STATS.failed += 1;
    try { reportDebugError(`online-fx-play:${type}`, error); } catch (_) {}
    return false;
  }
}


window.ROK_ONLINE_FX = {
  play: playOnlineVisualEvent,
  getPolicy: getOnlineFxPolicy,
  cancelAll: cancelOnlineVisualFxRuntime,
  getStats: () => ({ ...ONLINE_FX_RUNTIME_STATS, byType: { ...ONLINE_FX_RUNTIME_STATS.byType }, generation: ONLINE_FX_RUNTIME_GENERATION }),
  resetStats: () => {
    ONLINE_FX_RUNTIME_STATS.played = 0;
    ONLINE_FX_RUNTIME_STATS.cancelled = 0;
    ONLINE_FX_RUNTIME_STATS.unsupported = 0;
    ONLINE_FX_RUNTIME_STATS.failed = 0;
    ONLINE_FX_RUNTIME_STATS.byType = {};
  },
  getSupportedTypes: () => Object.keys(ONLINE_FX_DEFINITIONS),
};

// PvP v9.46 · Visor público y efímero de la acción rival. Este runtime nunca
// serializa handTabs, candidatos completos ni HTML del Spellbook: transmite
// exclusivamente la carta ya activada, la etapa y selecciones que son públicas
// para el oponente.
const opponentActionViewerRuntime = {
  local: null,
  remote: null,
  serial: 0,
  monitor: 0,
  remoteTimer: 0,
};

function safeOpponentActionViewText(value, fallback = '', maxLength = 92) {
  const text = String(value ?? '').replace(/\s+/g, ' ').trim();
  return (text || fallback).slice(0, Math.max(1, Number(maxLength || 92)));
}

function sanitizeOpponentActionViewSelection(selection = {}, viewerPlayerId = getOpponentId(LOCAL_PLAYER_ID)) {
  const kind = safeOpponentActionViewText(selection.kind || selection.type, 'status', 18).toLowerCase();
  if (kind === 'unit' || kind === 'invocation') {
    const ownerPlayerId = Number(selection.playerId || selection.ownerPlayerId || 0);
    const unitId = safeOpponentActionViewText(selection.unitId, '', 72);
    const unit = ownerPlayerId && unitId ? getUnitById?.(ownerPlayerId, unitId) : null;
    if (!unit || isOnlineUnitConcealedFromViewer?.(ownerPlayerId, unit, viewerPlayerId)) {
      return { kind: 'hidden', label: 'Objetivo oculto' };
    }
    const card = CARD_LIBRARY?.[unit.cardId];
    return {
      kind: 'unit',
      playerId: ownerPlayerId,
      unitId,
      label: safeOpponentActionViewText(selection.label, card?.shortName || card?.name || 'Invocación', 58),
      row: Number.isFinite(Number(unit.row)) ? Number(unit.row) : null,
      col: Number.isFinite(Number(unit.col)) ? Number(unit.col) : null,
    };
  }
  if (kind === 'cell' || kind === 'casilla') {
    const row = Number(selection.row);
    const col = Number(selection.col);
    if (!Number.isFinite(row) || !Number.isFinite(col)) return null;
    return {
      kind: 'cell', row, col,
      label: safeOpponentActionViewText(selection.label, `Casilla ${coordLabel?.(row, col) || `${row + 1},${col + 1}`}`, 58),
    };
  }
  const label = safeOpponentActionViewText(selection.label || selection.text, '', 58);
  return label ? { kind: 'status', label } : null;
}

function sanitizeOpponentActionViewPayload(payload = {}, viewerPlayerId = getOpponentId(LOCAL_PLAYER_ID)) {
  const status = ['open', 'update', 'close'].includes(String(payload.status || '')) ? String(payload.status) : 'update';
  const selections = (Array.isArray(payload.selections) ? payload.selections : [])
    .map(selection => sanitizeOpponentActionViewSelection(selection, viewerPlayerId))
    .filter(Boolean)
    .slice(-6);
  return {
    schemaVersion: 1,
    status,
    actionId: safeOpponentActionViewText(payload.actionId, '', 80),
    actorPlayer: Number(payload.actorPlayer || 0),
    cardId: safeOpponentActionViewText(payload.cardId, '', 80),
    title: safeOpponentActionViewText(payload.title, 'Acción activa', 72),
    step: safeOpponentActionViewText(payload.step, 'El rival está eligiendo.', 110),
    selections,
    emittedAt: Math.max(0, Number(payload.emittedAt || Date.now())),
  };
}

function getOpponentActionViewCardImage(cardId = '') {
  const card = CARD_LIBRARY?.[String(cardId || '')];
  if (!card) return '';
  try { return getQuickReactionIndicatorImage?.(card) || card.artImage || card.image || card.tokenImage || ''; }
  catch (_) { return card.artImage || card.image || card.tokenImage || ''; }
}

function hideRemoteOpponentActionView(reason = 'closed') {
  clearTimeout(opponentActionViewerRuntime.remoteTimer);
  opponentActionViewerRuntime.remoteTimer = 0;
  const root = document.getElementById('opponentActionViewer');
  if (!root) return false;
  const closingActionId = opponentActionViewerRuntime.remote?.actionId || '';
  root.classList.add('remote-closing');
  root.setAttribute('aria-hidden', 'true');
  setTimeout(() => {
    root.classList.remove('visible', 'remote-closing');
    if (!opponentActionViewerRuntime.remote || opponentActionViewerRuntime.remote.actionId === closingActionId) {
      opponentActionViewerRuntime.remote = null;
    }
  }, 210);
  return true;
}

function renderRemoteOpponentActionView(rawPayload = {}) {
  if (!isOnlineMatchActive?.()) return false;
  const payload = sanitizeOpponentActionViewPayload(rawPayload, LOCAL_PLAYER_ID);
  const current = opponentActionViewerRuntime.remote;
  if (payload.status === 'close') {
    if (!current || !payload.actionId || current.actionId === payload.actionId) {
      if (current) current.reason = safeOpponentActionViewText(rawPayload.reason, 'closed', 30);
      return hideRemoteOpponentActionView(current?.reason || 'closed');
    }
    return false;
  }
  if (!payload.actionId || Number(payload.actorPlayer) === Number(LOCAL_PLAYER_ID)) return false;

  const root = document.getElementById('opponentActionViewer');
  const title = document.getElementById('opponentActionViewerTitle');
  const step = document.getElementById('opponentActionViewerStep');
  const selectionHost = document.getElementById('opponentActionViewerSelection');
  const cardHost = document.getElementById('opponentActionViewerCard');
  if (!root || !title || !step || !selectionHost || !cardHost) return false;

  opponentActionViewerRuntime.remote = payload;
  title.textContent = payload.title;
  step.textContent = payload.step;
  selectionHost.replaceChildren();
  payload.selections.forEach(selection => {
    const chip = document.createElement('span');
    chip.className = `opponent-action-viewer-selection-chip opponent-action-viewer-selection-chip--${selection.kind}`;
    chip.textContent = selection.label;
    selectionHost.appendChild(chip);
  });

  cardHost.replaceChildren();
  const cardImage = getOpponentActionViewCardImage(payload.cardId);
  if (cardImage) {
    const image = document.createElement('img');
    image.src = cardImage;
    image.alt = '';
    cardHost.appendChild(image);
  }
  cardHost.setAttribute('aria-hidden', cardImage ? 'false' : 'true');
  root.classList.remove('remote-closing');
  root.classList.add('visible');
  root.setAttribute('aria-hidden', 'false');

  clearTimeout(opponentActionViewerRuntime.remoteTimer);
  opponentActionViewerRuntime.remoteTimer = setTimeout(() => {
    if (opponentActionViewerRuntime.remote?.actionId === payload.actionId) hideRemoteOpponentActionView('stale-timeout');
  }, 16000);
  try { window.ROK_LAYOUT_SCALE?.fitVisibleModals?.(); } catch (_) {}
  return true;
}

function emitLocalOpponentActionView(status = 'update', patch = {}) {
  const current = opponentActionViewerRuntime.local;
  if (!current || !isOnlineMatchActive?.()) return false;
  const payload = sanitizeOpponentActionViewPayload({ ...current, ...patch, status, emittedAt: Date.now() }, getOpponentId(LOCAL_PLAYER_ID));
  opponentActionViewerRuntime.local = { ...current, ...payload };
  return emitOnlineVisualEvent('opponent-action-view', payload);
}

function beginLocalOpponentActionView(meta = {}) {
  if (!isOnlineMatchActive?.() || !isBattleHudScreenActive?.()) return null;
  if (opponentActionViewerRuntime.local) endLocalOpponentActionView('replaced');
  const card = CARD_LIBRARY?.[String(meta.cardId || '')];
  const actionId = `action_view_${Date.now()}_${++opponentActionViewerRuntime.serial}`;
  opponentActionViewerRuntime.local = {
    schemaVersion: 1,
    status: 'open',
    actionId,
    actorPlayer: Number(LOCAL_PLAYER_ID),
    cardId: safeOpponentActionViewText(meta.cardId, '', 80),
    title: safeOpponentActionViewText(meta.title, card?.name || 'Acción activa', 72),
    step: safeOpponentActionViewText(meta.step, 'Eligiendo cómo ejecutar la acción.', 110),
    selections: [],
    startedAt: Date.now(),
    lastInteractionAt: Date.now(),
  };
  emitLocalOpponentActionView('open');
  startOpponentActionViewMonitor();
  return actionId;
}

function updateLocalOpponentActionView(patch = {}) {
  const current = opponentActionViewerRuntime.local;
  if (!current) return false;
  const next = { ...current };
  if (patch.cardId) next.cardId = safeOpponentActionViewText(patch.cardId, next.cardId, 80);
  if (patch.title) next.title = safeOpponentActionViewText(patch.title, next.title, 72);
  if (patch.step) next.step = safeOpponentActionViewText(patch.step, next.step, 110);
  if (patch.selection) {
    const sanitized = sanitizeOpponentActionViewSelection(patch.selection, getOpponentId(LOCAL_PLAYER_ID));
    if (sanitized) {
      const signature = JSON.stringify(sanitized);
      const selections = (Array.isArray(next.selections) ? next.selections : []).filter(item => JSON.stringify(item) !== signature);
      next.selections = [...selections, sanitized].slice(-6);
    }
  }
  if (Array.isArray(patch.selections)) {
    next.selections = patch.selections
      .map(selection => sanitizeOpponentActionViewSelection(selection, getOpponentId(LOCAL_PLAYER_ID)))
      .filter(Boolean)
      .slice(-6);
  }
  next.lastInteractionAt = Date.now();
  opponentActionViewerRuntime.local = next;
  return emitLocalOpponentActionView('update');
}

function endLocalOpponentActionView(reason = 'completed') {
  const current = opponentActionViewerRuntime.local;
  if (!current) return false;
  emitLocalOpponentActionView('close', { reason: safeOpponentActionViewText(reason, 'completed', 30) });
  opponentActionViewerRuntime.local = null;
  if (opponentActionViewerRuntime.monitor) {
    clearInterval(opponentActionViewerRuntime.monitor);
    opponentActionViewerRuntime.monitor = 0;
  }
  return true;
}

function hasLocalOpponentActionViewInteraction() {
  const flow = state?.quickReactionWindow || {};
  if (flow.phaseIntro || flow.locked || flow.active || flow.executing || flow.actionSelectionActive) return true;
  if (state?.pendingPowerAction) return true;
  if (state?.offTurnCasterReposition?.active) return true;
  if (state?.gloriaLatenteReactionCurrent || state?.gloriaLatenteQuickCastMode) return true;
  if (typeof tacticalSpellbookRuntime !== 'undefined' && tacticalSpellbookRuntime?.spellAction?.active) return true;
  if (typeof realtimeQuickCastRailRuntime !== 'undefined' && realtimeQuickCastRailRuntime?.executingKey) return true;
  return Boolean(document.querySelector(
    '#quickReactionModal.visible, #quickReactionCommandDock.visible, .quick-reaction-execution-layer, '
    + '#interceptarSelectionOverlay.visible, #emboscadaSelectionOverlay.visible, #kouutenRecastOverlay.visible, '
    + '#tacticaGuerraSelectionOverlay.visible, #hattoriAbilityOverlay.visible, #tokugawaAbilityOverlay.visible'
  ));
}

function getOpponentActionViewPendingStep() {
  const kind = safeOpponentActionViewText(state?.pendingPowerAction?.kind, '', 64);
  if (!kind) return '';
  const labels = {
    interceptarAlliedSelection: 'Seleccionando la invocación aliada que bloqueará.',
    interceptarRivalSelection: 'Seleccionando la invocación rival que será bloqueada.',
    kouutenRecastLocation: 'Seleccionando una casilla de la Arena.',
    gloriaLatenteTarget: 'Seleccionando la carta y el objetivo de la reacción.',
    smokeBomb: 'Seleccionando una zona de la Arena.',
  };
  if (labels[kind]) return labels[kind];
  if (/target|selection|location|cell|placement/i.test(kind)) return 'Seleccionando un objetivo o casilla pública.';
  return 'Resolviendo la acción seleccionada.';
}

function startOpponentActionViewMonitor() {
  if (opponentActionViewerRuntime.monitor) return;
  let lastStep = '';
  opponentActionViewerRuntime.monitor = setInterval(() => {
    const current = opponentActionViewerRuntime.local;
    if (!current) {
      clearInterval(opponentActionViewerRuntime.monitor);
      opponentActionViewerRuntime.monitor = 0;
      return;
    }
    const step = getOpponentActionViewPendingStep();
    if (step && step !== lastStep) {
      lastStep = step;
      updateLocalOpponentActionView({ step });
    }
    const age = Date.now() - Number(current.startedAt || 0);
    const quiet = Date.now() - Number(current.lastInteractionAt || current.startedAt || 0);
    if (age > 650 && quiet > 520 && !hasLocalOpponentActionViewInteraction()) {
      try { syncLocalQuickReactionGameplayPause(); } catch (_) {}
      try { syncRealtimeSpellActionPauseState(); } catch (_) {}
      endLocalOpponentActionView('resolved');
    }
  }, 140);
}

function describeOpponentActionViewPointerTarget(target) {
  if (!target?.closest) return null;
  const unitNode = target.closest('.unit[data-unit-id], [data-player-id][data-unit-id]');
  if (unitNode) {
    return {
      kind: 'unit',
      playerId: Number(unitNode.dataset.playerId || unitNode.dataset.ownerPlayerId || unitNode.dataset.player || 0),
      unitId: unitNode.dataset.unitId || '',
    };
  }
  const cellNode = target.closest('[data-row][data-col]');
  if (cellNode && cellNode.closest('#board, #moveOptionsLayer, .tactica-guerra-selection-overlay, .kouuten-recast-overlay')) {
    return { kind: 'cell', row: Number(cellNode.dataset.row), col: Number(cellNode.dataset.col) };
  }
  const publicControl = target.closest(
    '#interceptarSelectionOverlay button, #emboscadaSelectionOverlay button, #kouutenRecastOverlay button, '
    + '#tacticaGuerraSelectionOverlay button, .quick-reaction-target-btn, .selected-unit-command-btn'
  );
  if (publicControl) return { kind: 'status', label: 'Opción pública seleccionada' };
  return null;
}

document.addEventListener('pointerdown', event => {
  if (!opponentActionViewerRuntime.local) return;
  const selection = describeOpponentActionViewPointerTarget(event.target);
  if (!selection) return;
  setTimeout(() => updateLocalOpponentActionView({ selection, step: 'Confirmando la selección pública.' }), 0);
}, true);

window.ROK_OPPONENT_ACTION_VIEW = {
  begin: beginLocalOpponentActionView,
  update: updateLocalOpponentActionView,
  end: endLocalOpponentActionView,
  playRemote: renderRemoteOpponentActionView,
  getState: () => ({
    local: opponentActionViewerRuntime.local ? { ...opponentActionViewerRuntime.local } : null,
    remote: opponentActionViewerRuntime.remote ? { ...opponentActionViewerRuntime.remote } : null,
  }),
};

