function getFactorProfile(factorId) {
  return FACTOR_DB[factorId] || null;
}

function getCardAttackFactors(card) {
  return Array.isArray(card?.attackProfile?.factors) ? card.attackProfile.factors : [];
}

function getCardAttackFactor(card, factorId) {
  return getCardAttackFactors(card).find(factor => factor?.id === factorId) || null;
}

function getCardDefenseFactors(card) {
  return Array.isArray(card?.defenseProfile?.factors) ? card.defenseProfile.factors : [];
}

function getCardDefenseFactor(card, factorId) {
  return getCardDefenseFactors(card).find(factor => factor?.id === factorId) || null;
}

function getCardUtilityFactors(card) {
  return Array.isArray(card?.utilityFactors) ? card.utilityFactors : [];
}

function getCardUtilityFactor(card, factorId) {
  return getCardUtilityFactors(card).find(factor => factor?.id === factorId) || null;
}

function getCardAllFactors(card) {
  return [...getCardAttackFactors(card), ...getCardDefenseFactors(card), ...getCardUtilityFactors(card)];
}

function mergeFactorEntriesForDisplay(entries = []) {
  const merged = [];
  const byId = new Map();
  (Array.isArray(entries) ? entries : []).forEach(entry => {
    if (!entry?.id) return;
    const id = String(entry.id);
    const level = Math.max(0, Number(entry.level || 0));
    const existingIndex = byId.get(id);
    if (existingIndex == null) {
      merged.push({ ...entry });
      byId.set(id, merged.length - 1);
      return;
    }
    const current = merged[existingIndex] || {};
    const currentLevel = Math.max(0, Number(current.level || 0));
    const preferIncoming = level >= currentLevel;
    const combined = preferIncoming
      ? { ...current, ...entry, level: Math.max(currentLevel, level) }
      : { ...entry, ...current, level: Math.max(currentLevel, level) };
    combined.hidePersistentIcon = Boolean(current.hidePersistentIcon) || Boolean(entry.hidePersistentIcon);
    merged[existingIndex] = combined;
  });
  return merged;
}

function getCardFactorEntry(card, factorId, preferredSourceId = '') {
  const runtimeFactors = Array.isArray(card?.__runtime?.activeFactors) ? card.__runtime.activeFactors : [];
  const staticFactors = getCardAllFactors(card);
  const allFactors = [...runtimeFactors, ...staticFactors];
  if (preferredSourceId) {
    const preferred = allFactors.find(factor => factor?.id === factorId && getFactorEntrySourceId(factor) === preferredSourceId);
    if (preferred) return preferred;
  }
  return allFactors.find(factor => factor?.id === factorId) || null;
}

function getFactorDamageNatureId(factorEntry = {}) {
  return factorEntry.damageNature || factorEntry.nature || factorEntry.damageType || '';
}

function getFactorDisplayLevel(factorEntry = {}) {
  return Math.max(1, Number(factorEntry.level || 1) || 1);
}

function shouldShowFactorLevelBadge(factorId, factorEntry = {}) {
  return factorId === 'extraWeapon' || factorId === 'armor' || Object.prototype.hasOwnProperty.call(factorEntry || {}, 'level');
}

function getLethalityConfig(level = 1) {
  const factor = getFactorProfile('lethality');
  const safeLevel = Math.max(1, Math.min(5, Number(level) || 1));
  return {
    level: safeLevel,
    pda: Number(factor?.pdaByLevel?.[safeLevel] ?? 0),
    threshold: Number(factor?.executionThresholdByLevel?.[safeLevel] ?? 0),
    directThreshold: Number(factor?.directThresholdByLevel?.[safeLevel] ?? 0),
  };
}

function getFactorPda(factorId, level = 1) {
  const factor = getFactorProfile(factorId);
  const safeLevel = Math.max(1, Number(level) || 1);
  if (factorId === 'criticalHit') return Number(factor?.pdaByLevel?.[safeLevel] ?? (safeLevel + 1));
  return Number(factor?.pdaByLevel?.[safeLevel] ?? safeLevel ?? 0);
}

function getEffectiveFactorPda(factorId, level = 1, source = null, factorEntry = null) {
  const explicitOverride = Number(factorEntry?.pdaOverride ?? factorEntry?.pda);
  const base = Number.isFinite(explicitOverride) ? Math.max(0, Math.min(6, explicitOverride)) : getFactorPda(factorId, level);
  const unit = source?.unit || null;
  const sourceCard = source?.card || CARD_LIBRARY[unit?.cardId];
  if (
    unit &&
    Number(unit.kageNoMichiPdaOverride || 0) > 0 &&
    factorEntry?.source === 'assassin' &&
    Array.isArray(sourceCard?.qualities) &&
    sourceCard.qualities.includes('assassin')
  ) {
    return Math.max(base, Number(unit.kageNoMichiPdaOverride || 0));
  }
  return base;
}


function getCardRuntimeKageDamageBonus(card = null) {
  return Math.max(0, Number(card?.__runtime?.kageNoMichiDamageBonus || 0));
}

function getEffectiveUnitDamageValue(unit = null, card = null, playerId = null) {
  return Math.max(0, Number(getEffectiveAttackProfile(card, unit, playerId)?.damage ?? unit?.damage ?? card?.attackProfile?.damage ?? card?.stats?.damage ?? 0) || 0);
}

function getRuntimeSourceForCardInfo(card = null) {
  const runtime = card?.__runtime || {};
  if (!runtime?.unitId || !runtime?.playerId) return null;
  const unit = getUnitById(runtime.playerId, runtime.unitId);
  if (!unit) return null;
  return { playerId: runtime.playerId, unit, card };
}

function buildStasisBuffSnapshotForUnit(playerId, unit) {
  if (!unit?.cardId) return null;
  const card = CARD_LIBRARY[unit.cardId] || null;
  if (!card) return null;

  const attackBonusSources = getAttackBonusSourcesForUnit(unit, card, playerId).map(source => ({ ...source }));
  const defenseFactors = getEffectiveDefenseFactorsForUnit(unit, card, playerId).map(factor => ({ ...factor }));
  const activeFactors = Array.isArray(unit.activeFactors) ? unit.activeFactors.map(factor => ({ ...factor })) : [];

  if (unitReceivesNobunagaExtraAttack(unit, playerId) && !activeFactors.some(entry => entry?.id === 'extraAttack')) {
    activeFactors.push({
      id: 'extraAttack',
      level: 1,
      source: 'confianzaTransmitida',
      sourceType: 'power',
      powerId: 'confianzaTransmitida',
      sourceName: 'Confianza transmitida - Oda Nobunaga',
    });
  }

  const boostedEvasion = defenseFactors.find(factor => factor?.id === 'evasion' && factor?.source === 'senjinNoKosei');
  if (boostedEvasion && !activeFactors.some(entry => entry?.id === 'evasion' && entry?.source === 'senjinNoKosei')) {
    activeFactors.push({ ...boostedEvasion });
  }

  return {
    capturedAt: Date.now(),
    playerId,
    unitId: unit.id,
    source: 'stasis',
    attackBonusSources,
    defenseFactors,
    activeFactors,
    precisionBonusSources: getMusashiLegacyPrecisionBonusSources(card).map(source => ({ ...source })),
  };
}

function getStasisBuffSnapshot(unit = null) {
  return unit?.status === 'restoring' && unit?.stasisBuffSnapshot ? unit.stasisBuffSnapshot : null;
}


function getFactorMultiplier(factorId, level = 1) {
  const factor = getFactorProfile(factorId);
  const safeLevel = Math.max(1, Number(level) || 1);
  if (factorId === 'criticalHit') return Number(factor?.multiplierByLevel?.[safeLevel] ?? (safeLevel + 1));
  return Number(factor?.multiplierByLevel?.[safeLevel] ?? 1);
}

function rollPda(pda = 0) {
  // Los factores usan la misma escala visible de 0 a 6 PDA.
  // Antes se lanzaba un d8 oculto: Desarmar 5 mostraba 6 PDA, pero podía fallar
  // silenciosamente y Kurokagi se restauraba sin habilitar Buki Utsushi.
  const value = Math.max(0, Math.min(6, Number(pda) || 0));
  if (value >= 6) return true;
  if (value <= 0) return false;
  return Math.floor(Math.random() * 6) + 1 <= value;
}

function rollPrecisionPda(pda = 0) {
  const value = Math.max(0, Math.min(6, Number(pda) || 0));
  if (value >= 6) return true;
  if (value <= 0) return false;
  return Math.floor(Math.random() * 6) + 1 <= value;
}

function buildTagListHtml(tags = []) {
  if (!Array.isArray(tags) || tags.length === 0) return '';
  const [rootTag, ...childTags] = tags;
  const rootHtml = rootTag ? `<span class="meta-info-tag-root">${rootTag}</span>` : '';
  const arrowHtml = rootTag && childTags.length ? '<span class="meta-info-tag-arrow" aria-hidden="true"></span>' : '';
  const childHtml = childTags.map(tag => `<span class="meta-info-tag-child">${tag}</span>`).join('');
  return `<div class="meta-info-tags">${rootHtml}${arrowHtml}${childHtml}</div>`;
}


// v572 · Cadena semántica reutilizable. A diferencia del listado legado,
// conserva la jerarquía explícita de cada nivel: raíz → identidad → enfoques.
// Más adelante Factores/Poderes reutilizan el mismo componente con más capas.
function buildSemanticTagChainHtml(levels = [], options = {}) {
  const normalized = (Array.isArray(levels) ? levels : [])
    .map((entry, index) => {
      if (entry == null) return null;
      if (typeof entry === 'string') return { label: entry, depth: index };
      return { ...entry, label: String(entry.label || '').trim(), depth: index };
    })
    .filter(entry => entry && entry.label);
  if (!normalized.length) return '';
  const items = normalized.map((entry, index) => {
    const interactive = entry.infoKind && entry.infoId;
    const attrs = interactive
      ? ` type="button" data-info-kind="${entry.infoKind}" data-info-id="${entry.infoId}"`
      : '';
    const tagName = interactive ? 'button' : 'span';
    const cls = `meta-semantic-tag meta-semantic-tag-depth-${Math.min(index, 6)}${interactive ? ' meta-semantic-tag-link' : ''}`;
    const node = `<${tagName}${attrs} class="${cls}" style="--semantic-depth:${index}">${entry.label}</${tagName}>`;
    const arrow = index < normalized.length - 1 ? '<span class="meta-semantic-arrow" aria-hidden="true">›</span>' : '';
    return node + arrow;
  }).join('');
  return `<div class="meta-semantic-tags${options.compact ? ' meta-semantic-tags-compact' : ''}">${items}</div>`;
}

function getProfileFocusTags(profile = {}, rootLabel = '', identityLabel = '') {
  const raw = Array.isArray(profile?.tags) ? profile.tags : [];
  const excluded = new Set([rootLabel, identityLabel].filter(Boolean).map(value => String(value).trim().toLocaleLowerCase('es')));
  return raw.filter(tag => !excluded.has(String(tag).trim().toLocaleLowerCase('es')));
}


// =========================================================
// ETAPA 6 · TAG GENERAL AUTOMÁTICO DE CARTA
// El perfil general deja de estimarse mediante una puntuación arbitraria de
// stats. Se construye exclusivamente con reglas explícitas y con el ENFOQUE
// semántico final de Factores/Poderes/Habilidades ya normalizados.
// =========================================================
const CARD_GENERAL_TAG_RULES = Object.freeze({
  damageLifeDominanceGap: 5,
  strongDamageLifeThreshold: 5,
  fastSpeedThreshold: 6,
});

function normalizeGeneralTagKey(value = '') {
  return String(value || '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .trim()
    .toLocaleLowerCase('es');
}

function appendUniqueGeneralTag(target = [], seen = new Set(), label = '') {
  const clean = String(label || '').trim();
  const key = normalizeGeneralTagKey(clean);
  if (!clean || !key || seen.has(key)) return;
  seen.add(key);
  target.push(clean);
}

function getCardBaseGeneralFocusTags(card = null) {
  if (!card) return [];
  const stats = card.stats || {};
  const attack = getAttackProfile(card) || {};
  const damage = Math.max(0, Number(attack.damage ?? stats.damage ?? stats.atk ?? 0) || 0);
  const life = Math.max(0, Number(stats.life ?? stats.def ?? 0) || 0);
  const speed = Math.max(0, Number(stats.mov ?? 0) || 0);
  const tags = [];
  const seen = new Set();
  const gap = CARD_GENERAL_TAG_RULES.damageLifeDominanceGap;
  const strong = CARD_GENERAL_TAG_RULES.strongDamageLifeThreshold;

  // Ataque/Vida solo definen el perfil cuando existe una dominancia clara de
  // 5 puntos o cuando AMBOS valores ya alcanzan el umbral fuerte. Kurayami
  // (Daño 1 / Vida 2), por ejemplo, no recibe ni Daño ni Resistencia por stats.
  if (damage >= strong && life >= strong) {
    appendUniqueGeneralTag(tags, seen, 'Daño');
    appendUniqueGeneralTag(tags, seen, 'Resistencia');
  } else if (life - damage >= gap) {
    appendUniqueGeneralTag(tags, seen, 'Resistencia');
  } else if (damage - life >= gap) {
    appendUniqueGeneralTag(tags, seen, 'Daño');
  }

  // La Velocidad solo asciende al tag general cuando supera la franja normal
  // establecida: 6 o más casillas de movimiento.
  if (speed >= CARD_GENERAL_TAG_RULES.fastSpeedThreshold) {
    appendUniqueGeneralTag(tags, seen, 'Velocidad');
  }
  return tags;
}

function getCardFactorGeneralFocusTags(card = null) {
  if (!card) return [];
  const tags = [];
  const seen = new Set();
  mergeFactorEntriesForDisplay(getCardAllFactors(card)).forEach(entry => {
    getFactorSemanticFocusLabels(entry?.id || entry).forEach(label => appendUniqueGeneralTag(tags, seen, label));
  });
  return tags;
}

function getCardPowerGeneralFocusTags(card = null) {
  if (!card) return [];
  const tags = [];
  const seen = new Set();
  getCardPowerProfiles(card).forEach(power => {
    // Los Poderes heredados todavía no revisados NO alimentan el perfil desde
    // su clasificación antigua. Solo entra una rama semántica explícita.
    if (!Array.isArray(power?.semanticBranches) || !power.semanticBranches.length) return;
    getPowerSemanticFocusLabels(power).forEach(label => appendUniqueGeneralTag(tags, seen, label));
  });
  return tags;
}

function getCardAbilityGeneralFocusTags(card = null) {
  if (!card) return [];
  const tags = [];
  const seen = new Set();
  (Array.isArray(card.abilities) ? card.abilities : []).forEach(entry => {
    const profile = getAbilityProfile(entry?.id || entry);
    // La infraestructura queda preparada para Habilidades migradas, pero no
    // interpreta tags/prosa legados. Cuando una Habilidad reciba semanticBranches
    // entrará automáticamente al mismo perfil sin reconstruir esta función.
    const branches = Array.isArray(profile?.semanticBranches) ? profile.semanticBranches : [];
    branches.forEach(branch => {
      (Array.isArray(branch?.focuses) ? branch.focuses : []).forEach(focusId => {
        const label = FACTOR_SEMANTIC_TAXONOMY?.focuses?.[focusId] || String(focusId || '');
        appendUniqueGeneralTag(tags, seen, label);
      });
    });
  });
  return tags;
}

function getCardFocusTags(card) {
  if (!card) return [];
  const tags = [];
  const seen = new Set();

  // Orden estable: stats realmente dominantes → Factores → Poderes → Habilidades.
  // Los duplicados se colapsan; no se fuerzan tres tags ni se inventa Equilibrio.
  [
    ...getCardBaseGeneralFocusTags(card),
    ...getCardFactorGeneralFocusTags(card),
    ...getCardPowerGeneralFocusTags(card),
    ...getCardAbilityGeneralFocusTags(card),
  ].forEach(label => appendUniqueGeneralTag(tags, seen, label));

  return tags;
}

function getCardSemanticSearchTerms(card = null) {
  if (!card) return [];
  const terms = [];
  const seen = new Set();
  const add = value => appendUniqueGeneralTag(terms, seen, value);

  getCardFocusTags(card).forEach(add);

  const family = getFamilyProfile?.(card.family);
  if (family) {
    add(family.label);
    (Array.isArray(family.tags) ? family.tags : []).forEach(add);
  }
  (Array.isArray(card.races) ? card.races : []).forEach(id => {
    const profile = getRaceProfile?.(id);
    add(profile?.label || id);
    (Array.isArray(profile?.tags) ? profile.tags : []).forEach(add);
  });
  (Array.isArray(card.qualities) ? card.qualities : []).forEach(id => {
    const profile = getQualityProfile?.(id);
    add(profile?.label || id);
    (Array.isArray(profile?.tags) ? profile.tags : []).forEach(add);
  });

  mergeFactorEntriesForDisplay(getCardAllFactors(card)).forEach(entry => {
    const semantic = getFactorSemanticProfile(entry?.id || entry);
    add('Factor');
    add(FACTOR_SEMANTIC_TAXONOMY.activations?.[semantic.activation]?.label || semantic.activation);
    add(FACTOR_SEMANTIC_TAXONOMY.categories?.[semantic.category]?.label || semantic.category);
    add(FACTOR_SEMANTIC_TAXONOMY.orientations?.[semantic.orientation]?.label || semantic.orientation);
    getFactorSemanticFocusLabels(entry?.id || entry).forEach(add);
  });

  getCardPowerProfiles(card).forEach(power => {
    if (!Array.isArray(power?.semanticBranches) || !power.semanticBranches.length) return;
    add('Poder');
    add(power.label || power.name);
    getPowerSemanticBranches(power).forEach(branch => {
      (branch.activations?.length ? branch.activations : [branch.activation]).forEach(id => add(FACTOR_SEMANTIC_TAXONOMY.activations?.[id]?.label || id));
      (branch.categories?.length ? branch.categories : [branch.category]).forEach(id => add(FACTOR_SEMANTIC_TAXONOMY.categories?.[id]?.label || id));
      (branch.orientations?.length ? branch.orientations : [branch.orientation]).forEach(id => add(FACTOR_SEMANTIC_TAXONOMY.orientations?.[id]?.label || id));
      (branch.focuses || []).forEach(id => add(FACTOR_SEMANTIC_TAXONOMY.focuses?.[id] || id));
    });
  });

  (Array.isArray(card.abilities) ? card.abilities : []).forEach(entry => {
    const ability = getAbilityProfile?.(entry?.id || entry);
    if (!Array.isArray(ability?.semanticBranches) || !ability.semanticBranches.length) return;
    add('Habilidad');
    add(ability.label || ability.name);
    getAbilitySemanticBranches(ability).forEach(branch => {
      (branch.activations?.length ? branch.activations : [branch.activation]).forEach(id => add(FACTOR_SEMANTIC_TAXONOMY.activations?.[id]?.label || id));
      (branch.categories?.length ? branch.categories : [branch.category]).forEach(id => add(FACTOR_SEMANTIC_TAXONOMY.categories?.[id]?.label || id));
      if (branch.orientationLabel) add(branch.orientationLabel);
      else (branch.orientations?.length ? branch.orientations : [branch.orientation]).forEach(id => add(FACTOR_SEMANTIC_TAXONOMY.orientations?.[id]?.label || id));
      (branch.focuses || []).forEach(id => add(FACTOR_SEMANTIC_TAXONOMY.focuses?.[id] || id));
    });
  });

  // Alias naturales para que buscar "ofensiva/defensiva" encuentre los tags
  // canónicos Ofensivo/Defensivo sin duplicarlos visualmente en la carta.
  const normalized = new Set(terms.map(normalizeGeneralTagKey));
  if (normalized.has('ofensivo')) add('Ofensiva');
  if (normalized.has('defensivo')) add('Defensiva');

  return terms;
}

function getUnitFromInfoMeta(meta = {}) {
  if (meta?.source !== 'arena' || !meta.unitId || meta.playerId == null) return null;
  return state.players?.[meta.playerId]?.units?.find(unit => unit.id === meta.unitId) || null;
}

function buildCardModalCooldownMaps(unit, runtimeActiveFactors = []) {
  const maps = { power: {}, ability: {}, factor: {} };
  if (!unit) return maps;

  const assignMap = (target, source) => {
    if (!source || typeof source !== 'object') return;
    Object.entries(source).forEach(([id, value]) => {
      const remaining = Math.max(0, Number(value?.remaining ?? value?.cooldownRemaining ?? value ?? 0));
      if (remaining > 0) target[id] = remaining;
    });
  };

  assignMap(maps.power, unit.powerCooldowns);
  assignMap(maps.ability, unit.abilityCooldowns);
  assignMap(maps.factor, unit.factorCooldowns);

  if (isKurayamiUnit(unit)) {
    const remaining = getKurayamiPowerCooldownRemaining(unit);
    if (remaining > 0) maps.power.shizukesaNoShiin = remaining;
  }
  if (isKaguyaUnit(unit)) {
    const remaining = getKaguyaPowerCooldownRemaining(unit);
    if (remaining > 0) maps.power.disparoEnergizado = remaining;
  }
  if (isMinokageUnit(unit)) {
    const remaining = getMinokagePowerCooldownRemaining(unit);
    if (remaining > 0) maps.power.shippuUgachi = remaining;
  }

  runtimeActiveFactors.forEach(entry => {
    if (!entry?.id) return;
    const remaining = Math.max(0, Number(entry.cooldownRemaining ?? entry.cooldownPhasesRemaining ?? 0));
    if (remaining > 0) maps.factor[entry.id] = remaining;
  });

  return maps;
}

function getCardModalCooldownRemaining(card, kind, id, entry = null) {
  if (!id) return 0;
  const direct = Math.max(0, Number(entry?.cooldownRemaining ?? entry?.cooldownPhasesRemaining ?? 0));
  if (direct > 0) return direct;
  const map = card?.__runtime?.cooldowns?.[kind];
  return Math.max(0, Number(map?.[id] ?? 0));
}

function renderCardModalCooldownBadge(card, kind, id, entry = null) {
  const remaining = getCardModalCooldownRemaining(card, kind, id, entry);
  if (remaining <= 0) return '';
  return `<span class="card-modal-cooldown-badge" title="Enfriamiento: ${remaining} fase${remaining === 1 ? '' : 's'} restante${remaining === 1 ? '' : 's'}"><span class="card-modal-cooldown-hourglass" aria-hidden="true">${RESTORE_ICON_INLINE_SVG}</span><span class="card-modal-cooldown-count">${remaining}</span></span>`;
}

function getCooldownEntryRemaining(entry = null) {
  return Math.max(0, Number(entry?.remaining ?? entry?.cooldownRemaining ?? entry?.cooldownPhasesRemaining ?? entry?.durationRemaining ?? entry?.durationPhases ?? 0));
}

function buildCardInfoCooldownEntries(card) {
  const runtime = card?.__runtime || null;
  if (!runtime || runtime.source !== 'arena') return [];
  const entries = [];
  const seen = new Set();
  const pushEntry = (kind, id, label, remaining, extra = {}) => {
    const safeRemaining = Math.max(0, Number(remaining || 0));
    if (!id || !label || safeRemaining <= 0) return;
    const key = `${kind}:${id}:${extra.source || ''}`;
    if (seen.has(key)) return;
    seen.add(key);
    entries.push({ kind, id, label, remaining: safeRemaining, ...extra });
  };

  const powerMap = runtime.cooldowns?.power || {};
  Object.entries(powerMap).forEach(([id, remaining]) => {
    const power = getPowerProfile(id) || getPowerProfile(card?.power) || null;
    pushEntry('power', id, power?.name || power?.label || id, remaining);
  });

  const abilities = Array.isArray(card?.abilities) ? card.abilities : [];
  const abilityMap = runtime.cooldowns?.ability || {};
  Object.entries(abilityMap).forEach(([id, remaining]) => {
    const ability = abilities.find(entry => String(entry?.id || '') === String(id));
    const info = getAbilityProfile(ability?.id || id);
    pushEntry('ability', id, info?.label || info?.name || id, remaining);
  });

  const runtimeFactors = Array.isArray(runtime.activeFactors) ? runtime.activeFactors : [];
  runtimeFactors.forEach(entry => {
    if (!entry?.id) return;
    const remaining = getCooldownEntryRemaining(entry);
    const factor = getFactorProfile(entry.id);
    pushEntry('factor', entry.id, factor?.label || entry.id, remaining, {
      factorLevel: entry.level || 1,
      factorSource: getFactorEntrySourceId(entry),
      source: getFactorEntrySourceId(entry),
    });
  });

  const factorMap = runtime.cooldowns?.factor || {};
  Object.entries(factorMap).forEach(([id, remaining]) => {
    const factor = getFactorProfile(id);
    pushEntry('factor', id, factor?.label || id, remaining, { factorLevel: 1 });
  });

  const kindOrder = { power: 0, ability: 1, factor: 2 };
  entries.sort((a, b) => {
    const byKind = (kindOrder[a.kind] ?? 99) - (kindOrder[b.kind] ?? 99);
    if (byKind) return byKind;
    if (b.remaining !== a.remaining) return b.remaining - a.remaining;
    return String(a.label).localeCompare(String(b.label), 'es', { sensitivity: 'base' });
  });
  return entries;
}

let cardInfoStatScrollCueFrame = 0;

function clearCardInfoStatRowScrollCues() {
  const lower = els.cardInfoOverlay?.querySelector('.card-info-lower');
  if (!lower) return;
  lower.querySelectorAll('.card-info-stat-scroll-cue').forEach(node => node.remove());
}

function syncCardInfoStatRowScrollCues() {
  cardInfoStatScrollCueFrame = 0;
  const overlay = els.cardInfoOverlay;
  const lower = overlay?.querySelector('.card-info-lower');
  if (!overlay || !lower
    || !overlay.classList.contains('open')
    || overlay.classList.contains('spell-card-info')
    || overlay.classList.contains('guardian-info-open')
    || window.matchMedia('(max-width: 900px)').matches) {
    clearCardInfoStatRowScrollCues();
    return;
  }

  const rows = Array.from(lower.querySelectorAll(
    '.card-info-stats.card-info-stats-grouped > .stat-row'
  ));
  const lowerRect = lower.getBoundingClientRect();
  const activeIndexes = new Set();

  rows.forEach((row, index) => {
    const hasOverflow = row.scrollHeight > row.clientHeight + 2;
    const hasMoreBelow = hasOverflow
      && row.scrollTop + row.clientHeight < row.scrollHeight - 2;
    let cue = lower.querySelector(`.card-info-stat-scroll-cue[data-row-index="${index}"]`);

    if (!hasOverflow) {
      cue?.remove();
      return;
    }

    activeIndexes.add(String(index));
    if (!cue) {
      cue = document.createElement('span');
      cue.className = 'card-info-stat-scroll-cue';
      cue.dataset.rowIndex = String(index);
      cue.setAttribute('aria-hidden', 'true');
      lower.appendChild(cue);
    }

    const rowRect = row.getBoundingClientRect();
    cue.style.left = `${Math.max(0, rowRect.right - lowerRect.left - 18)}px`;
    cue.style.top = `${Math.max(0, rowRect.bottom - lowerRect.top - 15)}px`;
    cue.hidden = !hasMoreBelow;

    if (row.dataset.cardInfoScrollCueBound !== '1') {
      row.dataset.cardInfoScrollCueBound = '1';
      row.addEventListener('scroll', scheduleCardInfoStatRowScrollCueSync, { passive: true });
    }
  });

  lower.querySelectorAll('.card-info-stat-scroll-cue').forEach(cue => {
    if (!activeIndexes.has(cue.dataset.rowIndex || '')) cue.remove();
  });
}

function scheduleCardInfoStatRowScrollCueSync() {
  if (cardInfoStatScrollCueFrame) cancelAnimationFrame(cardInfoStatScrollCueFrame);
  cardInfoStatScrollCueFrame = requestAnimationFrame(() => {
    requestAnimationFrame(syncCardInfoStatRowScrollCues);
  });
}

window.addEventListener('resize', scheduleCardInfoStatRowScrollCueSync, { passive: true });

function renderCardInfoCooldownTray(card, options = {}) {
  if (!els.cardInfoCooldownTray) return;
  const show = options.show !== false;
  if (!show) {
    els.cardInfoCooldownTray.innerHTML = '';
    els.cardInfoCooldownTray.closest('.stat-row-cooldowns')?.setAttribute('hidden', 'hidden');
    return;
  }
  const entries = buildCardInfoCooldownEntries(card);
  const row = els.cardInfoCooldownTray.closest('.stat-row-cooldowns');
  row?.removeAttribute('hidden');
  if (!entries.length) {
    els.cardInfoCooldownTray.innerHTML = '<div class="card-info-cooldown-tray empty"><span>Sin enfriamientos activos</span></div>';
    return;
  }
  const chips = entries.map(entry => {
    const attrs = [
      `type="button"`,
      `class="card-info-cooldown-chip"`,
      `data-info-kind="${entry.kind}"`,
      `data-info-id="${entry.id}"`,
      `title="${entry.label} · ${entry.remaining} fase${entry.remaining === 1 ? '' : 's'} restante${entry.remaining === 1 ? '' : 's'}"`,
    ];
    if (entry.kind === 'factor') {
      attrs.push(`data-factor-level="${Number(entry.factorLevel || 1)}"`);
      if (entry.factorSource) attrs.push(`data-factor-source="${entry.factorSource}"`);
    }
    return `<button ${attrs.join(' ')}><span class="card-info-cooldown-chip-icon" aria-hidden="true">${RESTORE_ICON_INLINE_SVG}</span><span class="card-info-cooldown-chip-name">${entry.label}</span><span class="card-info-cooldown-chip-count">${entry.remaining}</span></button>`;
  }).join('');
  els.cardInfoCooldownTray.innerHTML = `<div class="card-info-cooldown-tray">${chips}</div>`;
  bindInlineInfoButtons(els.cardInfoCooldownTray, card);
}

function normalizeMaxHpBonusSource(source = null) {
  if (!source) return null;
  const amount = Math.max(0, Number(source.amount || 0));
  if (amount <= 0) return null;
  return {
    id: source.id || 'maxHpBonus',
    amount,
    label: source.label || `+${amount} vida máxima`,
    sourceName: source.sourceName || source.name || 'Modificador de vida máxima',
    sourceKind: source.sourceKind || 'effect',
    sourceId: source.sourceId || '',
    reason: source.reason || 'Aumento temporal o permanente aplicado a la vida máxima.',
  };
}

function getMaxHpBonusSourcesForUnit(unit = null, card = null, playerId = null) {
  if (!unit) return [];
  const unitCard = card || CARD_LIBRARY[unit.cardId] || null;
  const ownerId = playerId ?? unit.owner ?? null;
  const baseMax = Math.max(1, Number(unit.baseHp ?? unitCard?.stats?.life ?? unit.maxHp ?? unit.hp ?? 1));
  const effectiveMax = Math.max(baseMax, Number(unit.maxHp ?? baseMax));
  const totalBonus = Math.max(0, effectiveMax - baseMax);
  const sources = [];

  const gloriaLinks = ownerId == null
    ? []
    : getActiveGloriaLatenteLinks(ownerId).filter(link => String(link.targetUnitId) === String(unit.id));
  gloriaLinks.forEach((link, index) => {
    const spell = CARD_LIBRARY[link.cardId || GLORIA_LATENTE_CARD_ID];
    sources.push(normalizeMaxHpBonusSource({
      id: `gloriaLatenteMaxHp_${index + 1}`,
      amount: GLORIA_LATENTE_HP_BONUS_PER_LINK,
      sourceName: spell?.name || 'Gloria latente',
      sourceKind: 'spell',
      sourceId: spell?.id || GLORIA_LATENTE_CARD_ID,
      reason: 'El vínculo activo aumenta el límite de vida máxima sin curar automáticamente la vida actual.',
    }));
  });

  const knownTotal = sources.reduce((sum, source) => sum + Math.max(0, Number(source?.amount || 0)), 0);
  const untracked = Math.max(0, totalBonus - knownTotal);
  if (untracked > 0) {
    sources.push(normalizeMaxHpBonusSource({
      id: 'otherMaxHpBonus',
      amount: untracked,
      sourceName: 'Otro modificador de vida máxima',
      reason: 'Bono de vida máxima activo registrado en la unidad.',
    }));
  }
  return sources.filter(Boolean);
}

function getCardRuntimeMaxHpBonusSources(card = null) {
  const sources = Array.isArray(card?.__runtime?.maxHpBonusSources) ? card.__runtime.maxHpBonusSources : [];
  return sources.map(normalizeMaxHpBonusSource).filter(Boolean);
}

function getCardRuntimeMaxHpBonusTotal(card = null) {
  return getCardRuntimeMaxHpBonusSources(card).reduce((sum, source) => sum + Math.max(0, Number(source.amount || 0)), 0);
}

function buildMaxHpBonusDetailsHtml(card = null) {
  const runtime = card?.__runtime || {};
  const baseMax = Math.max(1, Number(runtime.baseHp ?? card?.stats?.life ?? card?.stats?.def ?? 1));
  const effectiveMax = Math.max(baseMax, Number(runtime.maxHp ?? baseMax));
  const current = Math.max(0, Number(runtime.hp ?? effectiveMax));
  const sources = getCardRuntimeMaxHpBonusSources(card);
  const totalBonus = getCardRuntimeMaxHpBonusTotal(card);
  if (!sources.length || totalBonus <= 0) {
    return `<p><strong>Resumen:</strong> esta carta no tiene bonos de vida máxima activos.</p>${buildTagListHtml(['vida', 'máximo base', 'sin bono'])}<p>Su límite actual es <strong>${effectiveMax}</strong> y su vida actual es <strong>${current}</strong>.</p>`;
  }
  const list = sources.map(source => `<li><strong>+${source.amount}</strong> · <span>${source.sourceName}</span><br><span>${source.reason}</span></li>`).join('');
  return `<p><strong>Resumen:</strong> la vida máxima base sigue siendo <strong>${baseMax}</strong>. Los bonos activos suman <strong>+${totalBonus}</strong>, por lo que el límite actual es <strong>${effectiveMax}</strong>. La vida actual permanece en <strong>${current}</strong> hasta que la carta se cure.</p>${buildTagListHtml(['vida máxima', 'bono activo', 'límite ampliado', 'desglose'])}<p><strong>Detalle de fuentes:</strong></p><ul class="attack-bonus-source-list">${list}</ul><p><strong>Regla:</strong> el bono de vida máxima no cura por sí mismo. Cuando desaparece, la vida actual solo se reduce si excede el nuevo máximo.</p>`;
}

function buildCardInfoViewModel(card, meta = {}) {
  const unit = getUnitFromInfoMeta(meta);
  if (!unit) return card;
  const stats = {
    ...(card.stats || {}),
    atk: unit.atk ?? card.stats?.atk,
    def: unit.def ?? card.stats?.def,
    damage: unit.damage ?? card.stats?.damage,
    life: unit.hp ?? unit.maxHp ?? card.stats?.life,
    mov: unit.mov ?? card.stats?.mov,
    restore: unit.restoreTime ?? card.stats?.restore,
  };
  const visualAttackBonusSources = getVisualAttackBonusSourcesForUnit(unit, card, meta.playerId);
  const visualAttackBonusTotal = visualAttackBonusSources.reduce((sum, item) => sum + Math.max(0, Number(item.amount || 0)), 0);
  const attackProfile = getEffectiveAttackProfile(card, unit, meta.playerId);
  const defenseProfile = { ...(card.defenseProfile || {}), factors: getEffectiveDefenseFactorsForUnit(unit, card, meta.playerId) };
  const effectiveAttackBonusTotal = Math.max(0, Number(attackProfile?.attackBonusTotal || 0));
  const baseAttackDamage = Math.max(0, (Number(attackProfile?.damage ?? unit.damage ?? card?.attackProfile?.damage ?? card?.stats?.damage ?? card?.stats?.atk ?? 0) || 0) - effectiveAttackBonusTotal);
  attackProfile.damage = baseAttackDamage + visualAttackBonusTotal;
  attackProfile.attackBonusTotal = visualAttackBonusTotal;
  attackProfile.attackBonusSources = visualAttackBonusSources;
  stats.atk = attackProfile.damage;
  stats.damage = attackProfile.damage;
  const attackBonusSources = visualAttackBonusSources;
  const precisionBonusSources = getMusashiLegacyPrecisionBonusSources(card);
  const effectivePrecisionBonusTotal = Math.max(0, Number(attackProfile?.precisionBonusTotal || 0));
  const baseAttackPrecision = Math.max(0, (Number(attackProfile?.precision ?? card?.attackProfile?.precision ?? 0) || 0) - effectivePrecisionBonusTotal);
  const precisionBonusTotal = precisionBonusSources.reduce((sum, item) => sum + Math.max(0, Number(item.amount || 0)), 0);
  const effectiveMovementType = getEffectiveMovementTypeForUnit(meta.playerId, unit);
  const runtimeActiveFactors = Array.isArray(unit.activeFactors) ? unit.activeFactors.filter(entry => entry?.id !== 'disarm').map(entry => ({ ...entry })) : [];
  const stasisSnapshot = getStasisBuffSnapshot(unit);
  if (stasisSnapshot && Array.isArray(stasisSnapshot.activeFactors)) {
    stasisSnapshot.activeFactors.forEach(entry => {
      if (entry?.id && !runtimeActiveFactors.some(item => item?.id === entry.id && getFactorEntrySourceId(item) === getFactorEntrySourceId(entry))) {
        runtimeActiveFactors.push({ ...entry });
      }
    });
  }
  if (unitReceivesNobunagaExtraAttack(unit, meta.playerId) && !runtimeActiveFactors.some(entry => entry?.id === 'extraAttack')) {
    runtimeActiveFactors.push({ id: 'extraAttack', level: 1, source: 'confianzaTransmitida', sourceType: 'power', powerId: 'confianzaTransmitida' });
  }
  const capturedWeaponProfile = getKurokagiCapturedWeaponProfile(unit);
  const runtimeExtraWeapons = capturedWeaponProfile
    ? [...getCardExtraWeapons(card).filter(entry => String(entry?.id || '') !== 'capturedWeapon'), { ...capturedWeaponProfile, id: 'capturedWeapon' }]
    : getCardExtraWeapons(card);
  const runtimeWeaponConditions = capturedWeaponProfile
    ? { ...(card.weaponConditions || {}), [capturedWeaponProfile.weaponType]: { consumable: false, note: `Arma equipada mediante Buki Utsushi. ${capturedWeaponProfile.label}: ${capturedWeaponProfile.combatMode}, alcance ${capturedWeaponProfile.range}, precisión ${capturedWeaponProfile.precision}, daño ${capturedWeaponProfile.damage}. No transmite factores ni poderes.` } }
    : (card.weaponConditions || {});
  const maxHpBonusSources = getMaxHpBonusSourcesForUnit(unit, card, meta.playerId);
  migrateLegacyAbilityCardEntries(unit);
  const runtimeAbilities = Array.isArray(card.abilities) ? card.abilities.map(entry => ({ ...entry })) : [];
  getUnitLearnedAbilityEntries(unit).forEach(entry => {
    if (!runtimeAbilities.some(item => item?.id === entry.id)) runtimeAbilities.push({ ...entry });
  });
  if (unitReceivesOSenseiShirahadori(unit, meta.playerId) && !runtimeAbilities.some(entry => entry?.id === SHIRAHADORI_ABILITY_ID)) {
    runtimeAbilities.push({ id: SHIRAHADORI_ABILITY_ID, sourcePower: 'habilidadDefinitiva', sourceType: 'power' });
  }
  const shirahadoriRuntime = runtimeAbilities.some(entry => entry?.id === SHIRAHADORI_ABILITY_ID)
    ? getShirahadoriRuntimeAvailability(meta.playerId, unit)
    : null;
  if (shirahadoriRuntime && !shirahadoriRuntime.available) {
    runtimeAbilities.forEach(entry => {
      if (entry?.id !== SHIRAHADORI_ABILITY_ID) return;
      entry.runtimeBlocked = true;
      entry.runtimeBlockedReason = shirahadoriRuntime.reason;
    });
  }
  return {
    ...card,
    abilitySlots: Math.max(Number(card.abilitySlots || 0), runtimeAbilities.length),
    abilities: runtimeAbilities,
    weaponType: attackProfile?.weaponType || card.weaponType,
    weaponConditions: runtimeWeaponConditions,
    extraWeapons: runtimeExtraWeapons,
    stats,
    attackProfile,
    defenseProfile,
    movementType: effectiveMovementType,
    __runtime: {
      unitId: unit.id,
      playerId: meta.playerId,
      source: 'arena',
      hp: unit.hp,
      maxHp: unit.maxHp,
      baseHp: unit.baseHp ?? card?.stats?.life,
      maxHpBonusSources,
      maxHpBonusTotal: maxHpBonusSources.reduce((sum, source) => sum + Math.max(0, Number(source?.amount || 0)), 0),
      movesLeft: unit.movesLeft,
      status: unit.status,
      restoreRemaining: unit.restoreRemaining,
      row: unit.row,
      col: unit.col,
      effects: unit.effects || unit.activeEffects || [],
      focusScoreModifiers: unit.focusScoreModifiers || {},
      smokeBombsLeft: unit.smokeBombsLeft ?? null,
      activeFactors: runtimeActiveFactors,
      baseAttackDamage,
      attackBonusSources,
      precisionBonusSources,
      baseAttackPrecision,
      precisionBonusTotal,
      attackBonusTotal: attackBonusSources.reduce((sum, item) => sum + Math.max(0, Number(item.amount || 0)), 0),
      totalAttackDamage: baseAttackDamage + attackBonusSources.reduce((sum, item) => sum + Math.max(0, Number(item.amount || 0)), 0),
      kageNoMichiDamageBonus: Math.max(0, Number(unit.kageNoMichiDamageBonus || 0)),
      kageNoMichiPdaOverride: Math.max(0, Number(unit.kageNoMichiPdaOverride || 0)),
      kurokagiWeaponMode: unit.kurokagiWeaponMode || 'primary',
      capturedWeapon: capturedWeaponProfile ? { ...capturedWeaponProfile } : null,
      learnedAbilities: getUnitLearnedAbilityEntries(unit),
      spellbookCooldown: getUnitSpellbookCooldownBreakdown(unit, card),
      cooldowns: buildCardModalCooldownMaps(unit, runtimeActiveFactors),
    },
  };
}

function buildSpellbookPersistentCardInfoViewModel(card, playerId, tab, slot) {
  if (!card || getCardTypeId(card) !== 'invocation') return card;
  const persistent = getSpellbookCardPersistentState(playerId, tab, slot, card.id);
  if (!persistent?.learnedAbilities?.length) return card;
  const learned = normalizeLearnedAbilityEntries(persistent.learnedAbilities);
  const abilities = Array.isArray(card.abilities) ? card.abilities.map(entry => ({ ...entry })) : [];
  learned.forEach(entry => {
    if (!abilities.some(item => item?.id === entry.id)) abilities.push({ ...entry });
  });
  const baseCooldown = getInvocationBaseSpellbookCooldown(card);
  const learnedCooldown = getLearnedAbilitiesSpellbookCooldownTotal(learned);
  return {
    ...card,
    abilitySlots: Math.max(Number(card.abilitySlots || 0), abilities.length),
    abilities,
    __runtime: {
      ...(card.__runtime || {}),
      source: 'spellbook',
      learnedAbilities: learned,
      spellbookCooldown: { base: baseCooldown, learned: learnedCooldown, total: baseCooldown + learnedCooldown },
    },
  };
}

function buildCastQueuePersistentCardInfoViewModel(card, playerId, item = null) {
  if (!card) return card;
  const learned = getCardTypeId(card) === 'invocation'
    ? normalizeLearnedAbilityEntries(item?.persistentCardState?.learnedAbilities)
    : [];
  const abilities = Array.isArray(card.abilities) ? card.abilities.map(entry => ({ ...entry })) : [];
  learned.forEach(entry => {
    if (!abilities.some(itemAbility => itemAbility?.id === entry.id)) abilities.push({ ...entry });
  });
  const baseCooldown = getCardTypeId(card) === 'invocation' ? getInvocationBaseSpellbookCooldown(card) : 0;
  const learnedCooldown = getLearnedAbilitiesSpellbookCooldownTotal(learned);
  return {
    ...card,
    abilitySlots: Math.max(Number(card.abilitySlots || 0), abilities.length),
    abilities,
    __runtime: {
      ...(card.__runtime || {}),
      source: 'castQueue',
      playerId: Number(playerId || 0),
      spawnId: item?.spawnId || '',
      castRemaining: Math.max(0, Number(item?.remaining || 0)),
      learnedAbilities: learned,
      spellbookCooldown: { base: baseCooldown, learned: learnedCooldown, total: baseCooldown + learnedCooldown },
    },
  };
}

function renderCardInfoSummaryTags(card) {
  if (!els.cardInfoSummaryTags) return;
  const tags = getCardFocusTags(card);
  if (!tags.length) {
    els.cardInfoSummaryTags.innerHTML = '';
    return;
  }
  const color = getElementColorById(getCardElementId(card));
  const [primary, ...secondary] = tags;
  els.cardInfoSummaryTags.style.setProperty('--summary-tag-color', color || '#5400FF');
  els.cardInfoSummaryTags.innerHTML = `
    <div class="card-summary-tags">
      <span class="card-summary-tag card-summary-tag-primary">${primary}</span>
      ${secondary.map(tag => `<span class="card-summary-tag card-summary-tag-secondary">${tag}</span>`).join('')}
    </div>`;
}


function renderCardInfoTraits(card) {
  if (!els.cardInfoTraits) return;
  const traits = getCardTraitProfiles(card);
  if (!traits.length) {
    els.cardInfoTraits.innerHTML = '';
    els.cardInfoTraits.hidden = true;
    return;
  }
  els.cardInfoTraits.hidden = false;
  els.cardInfoTraits.innerHTML = `<div class="card-info-trait-list">${traits.map(trait => `
    <button type="button" class="card-info-trait-chip" data-info-kind="trait" data-info-id="${trait.id}" title="${trait.category}: ${trait.label}">
      <img src="${trait.icon}" alt="${trait.label}">
      <span class="sr-only">${trait.label}</span>
    </button>`).join('')}</div>`;
  bindInlineInfoButtons(els.cardInfoTraits, card);
}

function createLibraryBuilderTraitBadge(card) {
  // La miniatura exterior de Biblioteca muestra únicamente rasgos que
  // modifican el uso o la construcción dentro de la propia Biblioteca.
  // Los rasgos de kasteo siguen visibles al abrir el modal de la carta.
  const traits = getCardTraitProfiles(card).filter(trait => trait.id === SPELLBOOK_FORCED_LIMITS_TRAIT_ID);
  if (!traits.length) return null;
  const wrapper = document.createElement('span');
  wrapper.className = 'library-builder-trait-badges';
  wrapper.setAttribute('aria-label', traits.map(trait => trait.label).join(', '));
  traits.forEach(trait => {
    const badge = document.createElement('span');
    badge.className = 'library-builder-trait-badge';
    badge.title = `${trait.category}: ${trait.label}`;
    badge.innerHTML = `<img src="${trait.icon}" alt="${trait.label}">`;
    wrapper.appendChild(badge);
  });
  return wrapper;
}

