function getNextBoosterDebugSampleCard(collection, avoidIds = []) {
  if (!ROK_BOOSTER_DEBUG_SAMPLE_MODE) return null;
  const avoid = new Set((avoidIds || []).map(String));
  const pool = ROK_BOOSTER_DEBUG_SAMPLE_IDS
    .map(cardId => CARD_LIBRARY[cardId])
    .filter(card => card && getCardTypeId(card) === ROK_BOOSTER_DEBUG_SAMPLE_TYPE)
    .filter(card => {
      const origin = getRokCardOriginId(card);
      return origin === 'neutral' || origin === collection?.originId;
    });
  if (!pool.length) return null;
  for (let offset = 0; offset < pool.length; offset += 1) {
    const index = (rokBoosterDebugSampleCursor + offset) % pool.length;
    const card = pool[index];
    if (!card || avoid.has(String(card.id))) continue;
    rokBoosterDebugSampleCursor = (index + 1) % pool.length;
    return card;
  }
  const fallback = pool[rokBoosterDebugSampleCursor % pool.length] || pool[0];
  rokBoosterDebugSampleCursor = (rokBoosterDebugSampleCursor + 1) % pool.length;
  return fallback || null;
}

const boosterStoreState = {
  step: 'collections',
  collectionId: null,
  purchaseMode: '',
  bundleCount: 1,
  lastAcquiredAmount: 0,
  returnContext: 'main',
  openingRemaining: 0,
  openingTotal: 0,
  currentPackCards: [],
  openedCardsSession: [],
  openedPacksSession: 0,
  animationToken: 0,
};

function getRokUserBoosterCount(collectionId) {
  return Math.max(0, Math.floor(Number(rokUserProfile?.boosters?.[collectionId]) || 0));
}

function grantRokUserBoosters(collectionId, amount = 1) {
  if (!ROK_BOOSTER_COLLECTIONS[collectionId]) return 0;
  const increment = Math.max(0, Math.floor(Number(amount) || 0));
  if (!increment) return getRokUserBoosterCount(collectionId);
  rokUserProfile.boosters = normalizeRokUserBoosters(rokUserProfile.boosters);
  rokUserProfile.boosters[collectionId] = getRokUserBoosterCount(collectionId) + increment;
  persistRokUserProfile();
  return rokUserProfile.boosters[collectionId];
}

function getTotalRokUserBoosters() {
  return Object.keys(ROK_BOOSTER_COLLECTIONS).reduce((total, id) => total + getRokUserBoosterCount(id), 0);
}

function consumeRokUserBoosters(collectionId, amount = 1) {
  const current = getRokUserBoosterCount(collectionId);
  const decrement = Math.max(0, Math.min(current, Math.floor(Number(amount) || 0)));
  if (!decrement) return current;
  rokUserProfile.boosters = normalizeRokUserBoosters(rokUserProfile.boosters);
  const next = current - decrement;
  if (next > 0) rokUserProfile.boosters[collectionId] = next;
  else delete rokUserProfile.boosters[collectionId];
  persistRokUserProfile();
  return next;
}

function getBoosterCardRarityId(card) {
  const allowForcedRarity = card?.boosterDebugSample === true || card?.allowForcedRarity === true || card?.rarityOverrideMode === 'debug';
  if (allowForcedRarity && card?.forceRarityId) return normalizeCardRarityId(card.forceRarityId);
  try { return getLibraryBuilderCardRarityId(card) || 'ordinary'; }
  catch (_) {
    try { return getCardVisualRarity(card)?.id || 'ordinary'; }
    catch (_) { return normalizeCardRarityId(card?.rarity) || 'ordinary'; }
  }
}

function getBoosterRarityRank(cardOrId) {
  const card = typeof cardOrId === 'string' ? CARD_LIBRARY[cardOrId] : cardOrId;
  const index = ROK_BOOSTER_RARITY_ORDER.indexOf(getBoosterCardRarityId(card));
  return index >= 0 ? index + 1 : 1;
}

function getBoosterEligibleCards(collection, typeId) {
  if (!collection) return [];
  return Object.values(CARD_LIBRARY).filter(card => {
    if (!card || card.upcoming || card.spellbookLocked) return false;
    if (getCardTypeId(card) !== typeId) return false;
    if (typeId === 'kaster' && !ROK_BOOSTER_INCLUDE_KASTERS) return false;
    const origin = getRokCardOriginId(card);
    return origin === 'neutral' || origin === collection.originId;
  });
}

function weightedPick(items, weightGetter) {
  const prepared = (items || []).map(item => ({ item, weight: Math.max(0, Number(weightGetter(item)) || 0) })).filter(entry => entry.weight > 0);
  if (!prepared.length) return null;
  const total = prepared.reduce((sum, entry) => sum + entry.weight, 0);
  let roll = Math.random() * total;
  for (const entry of prepared) {
    roll -= entry.weight;
    if (roll <= 0) return entry.item;
  }
  return prepared[prepared.length - 1].item;
}

function pickBoosterRarityId(cards, avoidIds = []) {
  const avoid = new Set((avoidIds || []).map(String));
  const source = (cards || []).filter(Boolean);
  const available = source.filter(card => !avoid.has(String(card.id)));
  const pool = available.length ? available : source;
  if (!pool.length) return null;

  // v452: la rareza se tira primero. La cantidad de cartas existentes en una
  // rareza ya no multiplica su probabilidad de aparecer. Solo participan las
  // rarezas que realmente tienen al menos una carta válida para este slot.
  const rarityIds = ROK_BOOSTER_RARITY_ORDER.filter(rarityId =>
    pool.some(card => getBoosterCardRarityId(card) === rarityId)
  );
  if (!rarityIds.length) return null;
  return weightedPick(rarityIds, rarityId => ROK_BOOSTER_RARITY_WEIGHTS[rarityId] || 0) || rarityIds[0];
}

function pickBoosterCardByRarity(cards, avoidIds = []) {
  const avoid = new Set((avoidIds || []).map(String));
  const source = (cards || []).filter(Boolean);
  const available = source.filter(card => !avoid.has(String(card.id)));
  const pool = available.length ? available : source;
  if (!pool.length) return null;

  // Primera tirada: rareza. Segunda tirada: una carta uniforme dentro de esa
  // rareza. Así 20 cartas Ordinarias no hacen que Ordinaria sea 20 veces más
  // probable que si solo hubiese una carta Ordinaria.
  const rarityId = pickBoosterRarityId(pool);
  if (!rarityId) return null;
  const rarityPool = pool.filter(card => getBoosterCardRarityId(card) === rarityId);
  if (!rarityPool.length) return null;
  return rarityPool[Math.floor(Math.random() * rarityPool.length)] || rarityPool[0];
}

function pickBoosterTokenType(collection) {
  const types = ['invocation', 'structure', ...(ROK_BOOSTER_INCLUDE_KASTERS ? ['kaster'] : [])]
    .filter(typeId => getBoosterEligibleCards(collection, typeId).length > 0);
  if (!types.length) return 'invocation';
  return weightedPick(types, typeId => ROK_BOOSTER_TOKEN_CATEGORY_WEIGHTS[typeId] || 1) || types[0];
}

function pickBoosterComplementaryType(collection) {
  const types = ROK_BOOSTER_COMPLEMENTARY_TYPES.filter(typeId => getBoosterEligibleCards(collection, typeId).length > 0);
  if (!types.length) return 'spell';
  return types[Math.floor(Math.random() * types.length)] || types[0];
}

function generateRokBoosterPack(collection) {
  const chosen = [];
  for (let i = 0; i < 2; i += 1) {
    const typeId = pickBoosterTokenType(collection);
    const card = pickBoosterCardByRarity(getBoosterEligibleCards(collection, typeId), chosen);
    if (card) chosen.push(card.id);
  }
  for (let i = 0; i < 3; i += 1) {
    const typeId = pickBoosterComplementaryType(collection);
    const card = pickBoosterCardByRarity(getBoosterEligibleCards(collection, typeId), chosen);
    if (card) chosen.push(card.id);
  }
  while (chosen.length < 5) {
    const fallback = Object.values(CARD_LIBRARY).filter(card => card && !card.upcoming && !card.spellbookLocked && getCardTypeId(card) !== 'kaster' && ['neutral', collection.originId].includes(getRokCardOriginId(card)));
    const card = pickBoosterCardByRarity(fallback, chosen);
    if (!card) break;
    chosen.push(card.id);
  }
  const debugSample = getNextBoosterDebugSampleCard(collection, chosen);
  if (debugSample?.id) {
    const replaceIndex = Math.max(0, Math.min(ROK_BOOSTER_DEBUG_SAMPLE_SLOT_INDEX, chosen.length - 1));
    if (chosen.length) chosen[replaceIndex] = debugSample.id;
    else chosen.push(debugSample.id);
  }
  return chosen.slice(0, 5);
}

function createBoosterRevealCardNode(cardId, options = {}) {
  const card = CARD_LIBRARY[cardId];
  if (!card) return document.createElement('span');
  const rarityId = getBoosterCardRarityId(card);
  const rank = getBoosterRarityRank(card);
  const rarity = (() => { try { return getCardVisualRarity(card); } catch (_) { return { id: rarityId, label: CARD_RARITY_LABELS?.[rarityId] || rarityId }; } })();
  const wrap = document.createElement('article');
  wrap.className = `booster-reveal-card rarity-${rarityId} rarity-rank-${rank}${options.compact ? ' compact' : ''}`;
  wrap.dataset.cardId = cardId;
  wrap.dataset.rarity = rarityId;
  wrap.dataset.rarityRank = String(rank);
  const visual = document.createElement('div');
  visual.className = 'booster-reveal-card-visual';
  const cardNode = createCardElement(card);
  cardNode.classList.add('booster-reveal-card-art');
  visual.appendChild(cardNode);

  // v460 · El foil principal se dibuja clonando el skin real de la carta.
  // Como el PNG del skin es transparente fuera de su marco/zona inferior,
  // el reflejo queda recortado exactamente a esa geometría y no al arte.
  const skinSource = cardNode.querySelector('.card-skin');
  const addSkinFoil = (kind) => {
    if (!skinSource) return null;
    const skinFoil = skinSource.cloneNode(true);
    skinFoil.className = `booster-rarity-skin-foil booster-rarity-skin-foil-${kind}`;
    skinFoil.alt = '';
    skinFoil.setAttribute('aria-hidden', 'true');
    skinFoil.removeAttribute('onerror');
    visual.appendChild(skinFoil);
    return skinFoil;
  };

  if (rarityId !== 'ordinary') addSkinFoil('basic');
  if (['singular','infrequent','unusual','strange','mythic','legendary'].includes(rarityId)) addSkinFoil('spark');

  // Extraña en adelante añade destellos de color que recorren la carta completa,
  // pero de forma translúcida. Legendaria además irradia partículas hacia fuera.
  if (['strange','mythic','legendary'].includes(rarityId)) {
    const streaks = document.createElement('i');
    streaks.className = 'booster-rarity-high-streaks';
    streaks.setAttribute('aria-hidden', 'true');
    visual.appendChild(streaks);
  }

  // Se conservan estos nodos por compatibilidad, pero v460 los anula visualmente.
  const pattern = document.createElement('i');
  pattern.className = 'booster-card-rarity-pattern';
  pattern.setAttribute('aria-hidden', 'true');
  visual.appendChild(pattern);
  const aura = document.createElement('i');
  aura.className = 'booster-card-rarity-aura';
  aura.setAttribute('aria-hidden', 'true');
  visual.appendChild(aura);
  const particles = document.createElement('i');
  particles.className = 'booster-card-rarity-particles';
  particles.setAttribute('aria-hidden', 'true');
  visual.appendChild(particles);
  const flare = document.createElement('i');
  flare.className = 'booster-card-rarity-flare';
  flare.setAttribute('aria-hidden', 'true');
  visual.appendChild(flare);
  wrap.appendChild(visual);

  if (['strange','mythic','legendary'].includes(rarityId)) {
    const outerGlow = document.createElement('i');
    outerGlow.className = 'booster-rarity-outer-glow';
    outerGlow.setAttribute('aria-hidden', 'true');
    wrap.appendChild(outerGlow);
  }
  if (rarityId === 'legendary') {
    const outerBorder = document.createElement('i');
    outerBorder.className = 'booster-rarity-legendary-border';
    outerBorder.setAttribute('aria-hidden', 'true');
    wrap.appendChild(outerBorder);
    const outerParticles = document.createElement('i');
    outerParticles.className = 'booster-rarity-legendary-particles';
    outerParticles.setAttribute('aria-hidden', 'true');
    wrap.appendChild(outerParticles);
  }
  if (card.boosterDebugSample) wrap.classList.add('booster-debug-sample-card');
  const copy = document.createElement('div');
  copy.className = 'booster-reveal-card-copy';
  copy.innerHTML = `<strong>${escapeHtml(card.name || cardId)}</strong><span>${escapeHtml(rarity?.label || CARD_RARITY_LABELS?.[rarityId] || rarityId)}</span>`;
  wrap.appendChild(copy);
  return wrap;
}

function getBoosterRevealTier(cardIds = []) {
  const highest = Math.max(1, ...(cardIds || []).map(getBoosterRarityRank));
  if (highest >= 9) return 'legendary';
  if (highest >= 7) return 'high';
  if (highest >= 4) return 'mid';
  return 'basic';
}

function getBoosterPurchaseCost(mode = boosterStoreState.purchaseMode, bundleCount = boosterStoreState.bundleCount) {
  if (mode === 'single') return ROK_BOOSTER_SINGLE_COST;
  if (mode === 'bundle5') return Math.max(1, Math.floor(Number(bundleCount) || 1)) * ROK_BOOSTER_BUNDLE5_COST;
  return 0;
}

function purchaseRokUserBoosters(collectionId, mode, bundleCount = 1) {
  if (!ROK_BOOSTER_COLLECTIONS[collectionId]) return { ok: false, reason: 'Colección no disponible.', amount: 0, cost: 0 };
  const normalizedMode = mode === 'bundle5' ? 'bundle5' : 'single';
  const bundles = Math.max(1, Math.floor(Number(bundleCount) || 1));
  const amount = normalizedMode === 'bundle5' ? bundles * 5 : 1;
  const cost = normalizedMode === 'bundle5' ? bundles * ROK_BOOSTER_BUNDLE5_COST : ROK_BOOSTER_SINGLE_COST;
  const balance = getRokUserPureCrystal();
  if (balance < cost) return { ok: false, reason: `Cristal Puro insuficiente: necesitas ${formatRokPureCrystalAmount(cost)} y tienes ${formatRokPureCrystalAmount(balance)}.`, amount, cost };
  rokUserProfile.pureCrystal = balance - cost;
  rokUserProfile.boosters = normalizeRokUserBoosters(rokUserProfile.boosters);
  rokUserProfile.boosters[collectionId] = getRokUserBoosterCount(collectionId) + amount;
  persistRokUserProfile();
  updateRokPureCrystalUi();
  return { ok: true, amount, cost, balance: getRokUserPureCrystal(), boosterCount: getRokUserBoosterCount(collectionId) };
}

function buildBoosterFoilPackMarkup(collection, className = '') {
  const maskUrl = `url('${collection.packImage}')`;
  return `<span class="booster-pack-visual ${className}" style="--booster-pack-mask:${maskUrl}"><img src="${collection.packImage}" alt="Booster pack ${collection.name}"><i class="booster-pack-foil" aria-hidden="true"></i><i class="booster-pack-foil-soft" aria-hidden="true"></i></span>`;
}

function buildBoosterFanMarkup(collection) {
  const rotations = [-18, -9, 0, 9, 18];
  return `<span class="booster-pack-fan" aria-hidden="true">${rotations.map((angle, index) => `<span class="booster-pack-fan-card" style="--fan-index:${index};--fan-angle:${angle}deg;--fan-x:${(index - 2) * 15}px">${buildBoosterFoilPackMarkup(collection, 'booster-pack-visual-small')}</span>`).join('')}</span>`;
}

function buildBoosterBoxParticlesMarkup(count = 28) {
  return Array.from({ length: count }, (_, index) => {
    const angle = (index / Math.max(1, count)) * Math.PI * 2;
    const radius = 36 + ((index * 17) % 48);
    const x = 50 + Math.cos(angle) * radius;
    const y = 52 + Math.sin(angle) * (radius * .52);
    const delay = (index % 9) * .13;
    const duration = 1.8 + ((index % 7) * .18);
    return `<i class="booster-box-particle" style="--particle-left:${x.toFixed(2)}%;--particle-top:${y.toFixed(2)}%;--particle-delay:${delay.toFixed(2)}s;--particle-duration:${duration.toFixed(2)}s"></i>`;
  }).join('');
}

function updateBoosterStoreHeader(collection = null) {
  updateRokPureCrystalUi();
  if (els.boosterStoreScreen) els.boosterStoreScreen.dataset.storeStep = boosterStoreState.step;
  if (els.boosterStoreInventory) {
    const total = getTotalRokUserBoosters();
    els.boosterStoreInventory.textContent = collection
      ? `${collection.name}: ${getRokUserBoosterCount(collection.id)} pack${getRokUserBoosterCount(collection.id) === 1 ? '' : 's'} sin abrir`
      : `Packs sin abrir: ${total}`;
  }
  if (els.boosterStoreTitle) {
    const titles = {
      collections: 'Adquirir booster packs',
      acquired: 'Booster packs adquiridos',
      opening: 'Apertura de booster',
      reveal: 'Cartas obtenidas',
      results: 'Apertura completada',
    };
    els.boosterStoreTitle.textContent = titles[boosterStoreState.step] || collection?.label || 'Booster box';
  }
  if (els.boosterStoreSubtitle) {
    const subtitles = {
      collections: 'Selecciona una booster box para entrar a su colección.',
      acquired: 'Tus packs están listos. Puedes abrirlos ahora o guardarlos para después.',
      opening: 'El sobre se abrirá y las cinco cartas saldrán desde su interior.',
      reveal: 'Revisa las cinco cartas. Después abre el siguiente booster o todos los restantes.',
      results: 'Todas las cartas abiertas en esta sesión ya forman parte de tu colección.',
    };
    els.boosterStoreSubtitle.textContent = subtitles[boosterStoreState.step] || 'Selecciona si quieres adquirir un pack o grupos de cinco.';
  }
}

