  grantBoosters: (collectionId, amount = 1) => grantRokUserBoosters(collectionId, amount),
  openBoosters: (collectionId, amount = 1) => { const collection = ROK_BOOSTER_COLLECTIONS[collectionId]; if (collection) beginBoosterOpeningSession(collection, amount); },
  getPureCrystal: () => getRokUserPureCrystal(),
