const REALTIME_CARD_COMPATIBILITY_NOTES = Object.freeze({
  kiaraFaroleraUmbral: ['Farol Enlazado usa la IA activa de RT-05; su portal sigue siendo resolución del motor existente.'],
  ninjaMinokageNoKurai: ['Shippū Ugachi conserva canalización/alcance propios; Salto ofensivo y Salto evasivo son pasivas independientes. La IA adapta Shippū a Asesinato/Ofensivo/Cacería/Asedio.'],
  miyamotoMusashi: ['Vigilia habilita retención automática de posición en modo Defensivo dentro del lado aliado.'],
  gioshoninMercaderErrante: ['Campeo/Retroceso no usa Modos: retrocede automáticamente hasta el límite trasero propio y permanece allí.'],
  samuraiOSenseiUeshiba: ['Campeo/Retroceso no usa Modos; Shirahadori continúa como disparador event-driven y sus pasivas permanecen activas mientras sostiene la retaguardia.'],
});
const realtimeStage1Runtime = {
  timer: null,
  generation: 0,
  nextTempoTickAtMs: 0,
  lastRenderedElapsedSecond: -1,
  lastThoughtBroadcastSecond: -1,
  lastThoughtActivePlayerId: 0,
  thoughtCommandPending: false,
};
const realtimeStage3Runtime = {
  entityLocks: new Set(),
  pairLocks: new Set(),
  aiCastBusy: false,
  lastCasterMoveAt: 0,
  lastProcessedSecond: 0,
  combatPowerCache: new Map(),
};
const realtimeStage5Runtime = {
  temporalBusy: false,
  abilityBusy: false,
  autoAbilityDepth: 0,
  lastProcessedSecond: 0,
  lastAbilityDecisionSecond: 0,
  lastLegacyTurnBucket: 0,
  unitAbilityNextSecond: new Map(),
  currentAbilityLabel: '',
};


function normalizeRealtimeTimingTuning(value = null) {
  const source = value && typeof value === 'object' ? value : {};
  const numeric = (key, fallback, min, max, precision = 1) => {
    const raw = Number(source[key]);
    const safe = Number.isFinite(raw) ? raw : fallback;
    return Number(Math.max(min, Math.min(max, safe)).toFixed(precision));
  };
  const normalized = {
    resourceGrowthMinSeconds: numeric('resourceGrowthMinSeconds', REALTIME_TIMING_TUNING_DEFAULTS.resourceGrowthMinSeconds, 1, 120, 1),
    resourceGrowthMaxSeconds: numeric('resourceGrowthMaxSeconds', REALTIME_TIMING_TUNING_DEFAULTS.resourceGrowthMaxSeconds, 1, 180, 1),
    resourceRefillSeconds: numeric('resourceRefillSeconds', REALTIME_TIMING_TUNING_DEFAULTS.resourceRefillSeconds, 1, 60, 1),
    pureElementPulseSeconds: numeric('pureElementPulseSeconds', REALTIME_TIMING_TUNING_DEFAULTS.pureElementPulseSeconds, 1, 120, 1),
    aiDecisionSeconds: numeric('aiDecisionSeconds', REALTIME_TIMING_TUNING_DEFAULTS.aiDecisionSeconds, 0.5, 20, 1),
    attackPrepSeconds: numeric('attackPrepSeconds', REALTIME_TIMING_TUNING_DEFAULTS.attackPrepSeconds, 0, 10, 1),
    meleeAttackSeconds: numeric('meleeAttackSeconds', REALTIME_TIMING_TUNING_DEFAULTS.meleeAttackSeconds, 1, 30, 1),
    rangedAttackSeconds: numeric('rangedAttackSeconds', REALTIME_TIMING_TUNING_DEFAULTS.rangedAttackSeconds, 1, 40, 1),
    heavyAttackSeconds: numeric('heavyAttackSeconds', REALTIME_TIMING_TUNING_DEFAULTS.heavyAttackSeconds, 1, 60, 1),
    progressiveCooldownSeconds: numeric('progressiveCooldownSeconds', REALTIME_TIMING_TUNING_DEFAULTS.progressiveCooldownSeconds, 0, 30, 1),
    progressiveWindowSeconds: numeric('progressiveWindowSeconds', REALTIME_TIMING_TUNING_DEFAULTS.progressiveWindowSeconds, 1, 30, 1),
  };
  if (normalized.resourceGrowthMaxSeconds < normalized.resourceGrowthMinSeconds) {
    normalized.resourceGrowthMaxSeconds = normalized.resourceGrowthMinSeconds;
  }
  return normalized;
}

function loadRealtimeTimingTuning() {
  if (realtimeTimingTuningRuntime.loaded && realtimeTimingTuningRuntime.values) {
    return realtimeTimingTuningRuntime.values;
  }
  realtimeTimingTuningRuntime.loaded = true;
  let parsed = null;
  try {
    const raw = localStorage.getItem(REALTIME_TIMING_TUNING_STORAGE_KEY);
    parsed = raw ? JSON.parse(raw) : null;
  } catch (_) {}
  realtimeTimingTuningRuntime.values = normalizeRealtimeTimingTuning(parsed || REALTIME_TIMING_TUNING_DEFAULTS);
  return realtimeTimingTuningRuntime.values;
}

function persistRealtimeTimingTuning() {
  const values = normalizeRealtimeTimingTuning(realtimeTimingTuningRuntime.values || REALTIME_TIMING_TUNING_DEFAULTS);
  realtimeTimingTuningRuntime.values = values;
  try { localStorage.setItem(REALTIME_TIMING_TUNING_STORAGE_KEY, JSON.stringify(values)); } catch (_) {}
  return values;
}

function ensureRealtimeTimingTuningState() {
  const localValues = loadRealtimeTimingTuning();
  if (!state.realtime || typeof state.realtime !== 'object') return localValues;
  if (!state.realtime.timingTuning || typeof state.realtime.timingTuning !== 'object') {
    state.realtime.timingTuning = { ...localValues };
  } else {
    state.realtime.timingTuning = normalizeRealtimeTimingTuning(state.realtime.timingTuning);
  }
  return state.realtime.timingTuning;
}

function getRealtimeTimingTuning() {
  if (state?.realtime?.active && state?.realtime?.timingTuning) {
    return normalizeRealtimeTimingTuning(state.realtime.timingTuning);
  }
  return loadRealtimeTimingTuning();
}

function getRealtimeTimingValue(key) {
  const tuning = getRealtimeTimingTuning();
  return Number(tuning?.[key] ?? REALTIME_TIMING_TUNING_DEFAULTS[key] ?? 0);
}

// v9.88 · tempoPause ya descuenta sus pausas del reloj activo. Las pausas
// globales (desconexión, menú, editor o una decisión dura) necesitan el mismo
// tratamiento, pero solo durante el tramo que NO esté cubierto por tempoPause;
// de lo contrario una pausa táctica se descontaría dos veces.
function ensureRealtimeGlobalPauseClock() {
  if (!state?.realtime || typeof state.realtime !== 'object') return null;
  if (!state.realtime.globalPauseClock || typeof state.realtime.globalPauseClock !== 'object') {
    state.realtime.globalPauseClock = { active: false, startedAt: 0, accumulatedMs: 0 };
  }
  const clock = state.realtime.globalPauseClock;
  clock.active = clock.active === true;
  clock.startedAt = Math.max(0, Number(clock.startedAt || 0));
  clock.accumulatedMs = Math.max(0, Number(clock.accumulatedMs || 0));
  return clock;
}

function syncRealtimeGlobalPauseClock(now = Date.now()) {
  if (!isRealtimePlayStyle?.() || !state?.realtime?.active) return false;
  const clock = ensureRealtimeGlobalPauseClock();
  if (!clock) return false;
  const shouldTrack = Boolean(isGlobalGameplayPaused?.() && !isRealtimeTempoPaused?.());
  if (shouldTrack && !clock.active) {
    clock.active = true;
    clock.startedAt = Number(now);
    return true;
  }
  if (!shouldTrack && clock.active) {
    clock.accumulatedMs += Math.max(0, Number(now) - Number(clock.startedAt || now));
    clock.active = false;
    clock.startedAt = 0;
    return true;
  }
  return false;
}

function getRealtimeActiveElapsedMs() {
  // La réplica PvP no interpreta startedAt del Host con su propio reloj local.
  // Muestra exactamente el último elapsedSeconds autoritativo recibido.
  if (isRealtimeOnlineReplica?.()) {
    return Math.max(0, Number(state?.realtime?.elapsedSeconds || 0) * 1000);
  }
  const startedAt = Math.max(0, Number(state?.realtime?.startedAt || 0));
  if (!startedAt) return Math.max(0, Number(state?.realtime?.elapsedSeconds || 0) * 1000);
  syncRealtimeGlobalPauseClock(Date.now());
  const pause = state?.realtime?.tempoPause || {};
  const accumulated = Math.max(0, Number(pause.accumulatedMs || 0));
  const activePause = pause.active ? Math.max(0, Date.now() - Number(pause.startedAt || Date.now())) : 0;
  const globalPause = ensureRealtimeGlobalPauseClock() || {};
  const globalAccumulated = Math.max(0, Number(globalPause.accumulatedMs || 0));
  const activeGlobalPause = globalPause.active
    ? Math.max(0, Date.now() - Number(globalPause.startedAt || Date.now()))
    : 0;
  return Math.max(0, Date.now() - startedAt - accumulated - activePause - globalAccumulated - activeGlobalPause);
}

function rescheduleRealtimeSystemsAfterTimingChange() {
  if (!isRealtimePlayStyle() || !state?.realtime?.active) return false;
  const nowSecond = Math.max(0, getRealtimeActiveElapsedMs() / 1000);
  const resourceSystem = ensureRealtimeResourceSystemState();
  Object.values(resourceSystem.players || {}).forEach(rtPlayer => {
    if (!rtPlayer) return;
    rtPlayer.refillIntervalSeconds = Math.max(.25, Number(getRealtimeTimingValue('resourceRefillSeconds') || REALTIME_RESOURCE_REFILL_SECONDS));
    rtPlayer.nextRefillAt = nowSecond + rtPlayer.refillIntervalSeconds;
    if (!Number.isFinite(Number(rtPlayer.refillRotationIndex))) rtPlayer.refillRotationIndex = 0;
    if (!Number.isFinite(Number(rtPlayer.capacityRotationIndex))) rtPlayer.capacityRotationIndex = 0;
    scheduleNextRealtimePlayerCapacityGrowth(rtPlayer, nowSecond);
    (rtPlayer.elementIds || []).forEach(elementId => {
      const track = rtPlayer.tracks?.[elementId];
      if (!track) return;
      // Compatibilidad con estados anteriores: los relojes ya son globales.
      track.nextRefillAt = 0;
      track.nextGrowthAt = 0;
      track.growthIntervalSeconds = 0;
    });
  });
  if (!state.realtime.pureElementSystem || typeof state.realtime.pureElementSystem !== 'object') {
    state.realtime.pureElementSystem = { initialized: true, nextPulseAt: 0, pulses: 0 };
  }
  state.realtime.pureElementSystem.nextPulseAt = nowSecond + getRealtimeTimingValue('pureElementPulseSeconds');
  for (const playerId of [1, 2]) {
    for (const unit of state.players?.[playerId]?.units || []) {
      unit.realtimeNextDecisionAtMs = getRealtimeActiveElapsedMs() + getRealtimeTimingValue('aiDecisionSeconds') * 1000;
      if (unit.realtimeAttackTelegraph) unit.realtimeAttackTelegraph = null;
    }
  }
  renderAll('realtime-timing-rescheduled');
  return true;
}

function setRealtimeTimingTuningValue(key, value, options = {}) {
  const current = { ...loadRealtimeTimingTuning(), [key]: Number(value) };
  const normalized = normalizeRealtimeTimingTuning(current);
  realtimeTimingTuningRuntime.values = normalized;
  persistRealtimeTimingTuning();
  if (state?.realtime?.active) {
    if (isOnlineMatchActive() && !isRealtimeOnlineAuthority()) return normalized;
    state.realtime.timingTuning = { ...normalized };
    if (options.reschedule !== false) rescheduleRealtimeSystemsAfterTimingChange();
    if (isOnlineMatchActive() && isRealtimeOnlineAuthority()) {
      try { markOnlineStateDirty(`rt-timing:${key}`); } catch (_) {}
    }
  }
  syncRealtimeTimingTuningControls();
  return normalized;
}

function resetRealtimeTimingTuning() {
  realtimeTimingTuningRuntime.values = { ...REALTIME_TIMING_TUNING_DEFAULTS };
  persistRealtimeTimingTuning();
  if (state?.realtime?.active && (!isOnlineMatchActive() || isRealtimeOnlineAuthority())) {
    state.realtime.timingTuning = { ...REALTIME_TIMING_TUNING_DEFAULTS };
    rescheduleRealtimeSystemsAfterTimingChange();
    if (isOnlineMatchActive()) {
      try { markOnlineStateDirty('rt-timing-reset'); } catch (_) {}
    }
  }
  syncRealtimeTimingTuningControls();
}

function getRealtimeMoveIntervalSecondsForUnit(unit) {
  const speed = Math.max(1, Math.floor(Number(getUnitBaseMoveValue?.(unit) || unit?.mov || CARD_LIBRARY?.[unit?.cardId]?.stats?.mov || 3)));
  // La primera prueba reglada llega hasta Velocidad 5. Por encima de 5 no se
  // acumulan pasos en el mismo frame todavía: permanece en 1 s por casilla.
  return REALTIME_MOVE_INTERVAL_BY_SPEED[Math.min(5, speed)] || 5;
}

function getRealtimeAttackTimingClass(playerId, unit) {
  const card = CARD_LIBRARY?.[unit?.cardId];
  const profile = card ? (getEffectiveAttackProfile?.(card, unit, playerId) || getAttackProfile?.(card) || {}) : {};
  const range = Math.max(1, Number(profile.range ?? 1));
  const damage = Math.max(0, Number(profile.damage ?? unit?.atk ?? 0));
  const searchable = [
    card?.name, card?.summary, card?.description,
    ...(Array.isArray(card?.tags) ? card.tags : []),
    ...(Array.isArray(card?.qualities) ? card.qualities : []),
  ].filter(Boolean).join(' ').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
  if (/(artiller|canon|cannon|pesad|asedio|bombard)/.test(searchable) || range >= 5 || damage >= 5) return 'heavy';
  if (range > 1) return 'ranged';
  return 'melee';
}

function getRealtimeAttackCadenceSeconds(playerId, unit) {
  const type = getRealtimeAttackTimingClass(playerId, unit);
  if (type === 'heavy') return getRealtimeTimingValue('heavyAttackSeconds');
  if (type === 'ranged') return getRealtimeTimingValue('rangedAttackSeconds');
  return getRealtimeTimingValue('meleeAttackSeconds');
}

function ensureRealtimeStage5State() {
  if (!state.realtime || typeof state.realtime !== 'object') {
    state.realtime = { active: false, startedAt: 0, elapsedSeconds: 0, tickSerial: 0, phaseEquivalentSeconds: 1 };
  }
  if (!state.realtime.tempoPause || typeof state.realtime.tempoPause !== 'object') {
    state.realtime.tempoPause = {
      active: false,
      source: '',
      reason: '',
      startedAt: 0,
      accumulatedMs: 0,
    };
  }
  if (!state.realtime.temporalSystem || typeof state.realtime.temporalSystem !== 'object') {
    state.realtime.temporalSystem = {
      initialized: false,
      phaseSeconds: getRealtimeTempoSeconds(),
      legacyTurnSeconds: REALTIME_LEGACY_TURN_SECONDS,
      lastProcessedSecond: 0,
      legacyTurnSerial: 1,
    };
  }
  if (!state.realtime.abilitySystem || typeof state.realtime.abilitySystem !== 'object') {
    state.realtime.abilitySystem = {
      initialized: false,
      decisionSeconds: REALTIME_ABILITY_DECISION_SECONDS,
      retrySeconds: REALTIME_ABILITY_RETRY_SECONDS,
      lastDecisionSecond: 0,
      activations: 0,
      lastAbility: '',
    };
  }
  return state.realtime;
}


function ensureRealtimeThoughtTimeState() {
  if (!state.realtime || typeof state.realtime !== 'object') {
    state.realtime = {
      active: false,
      startedAt: 0,
      elapsedSeconds: 0,
      tickSerial: 0,
      phaseEquivalentSeconds: REALTIME_DEFAULT_TEMPO_SECONDS,
    };
  }
  if (!state.realtime.thoughtTime || typeof state.realtime.thoughtTime !== 'object') {
    state.realtime.thoughtTime = {
      maxMs: REALTIME_THOUGHT_TIME_MAX_MS,
      remainingMs: { p1: REALTIME_THOUGHT_TIME_MAX_MS, p2: REALTIME_THOUGHT_TIME_MAX_MS },
      activePlayerId: 0,
      startedAt: 0,
      lastAccountedAt: 0,
    };
  }
  const thought = state.realtime.thoughtTime;
  thought.maxMs = REALTIME_THOUGHT_TIME_MAX_MS;
  if (!thought.remainingMs || typeof thought.remainingMs !== 'object') {
    thought.remainingMs = { p1: REALTIME_THOUGHT_TIME_MAX_MS, p2: REALTIME_THOUGHT_TIME_MAX_MS };
  }
  for (const playerId of [1, 2]) {
    const key = `p${playerId}`;
    const raw = Number(thought.remainingMs[key]);
    thought.remainingMs[key] = Number.isFinite(raw)
      ? Math.max(0, Math.min(REALTIME_THOUGHT_TIME_MAX_MS, raw))
      : REALTIME_THOUGHT_TIME_MAX_MS;
  }
  thought.activePlayerId = [1, 2].includes(Number(thought.activePlayerId)) ? Number(thought.activePlayerId) : 0;
  thought.startedAt = Math.max(0, Number(thought.startedAt || 0));
  thought.lastAccountedAt = Math.max(0, Number(thought.lastAccountedAt || 0));
  return thought;
}

function resetRealtimeThoughtTimeState() {
  if (!state.realtime || typeof state.realtime !== 'object') return false;
  state.realtime.thoughtTime = {
    maxMs: REALTIME_THOUGHT_TIME_MAX_MS,
    remainingMs: { p1: REALTIME_THOUGHT_TIME_MAX_MS, p2: REALTIME_THOUGHT_TIME_MAX_MS },
    activePlayerId: 0,
    startedAt: 0,
    lastAccountedAt: 0,
  };
  realtimeStage1Runtime.lastThoughtBroadcastSecond = -1;
  realtimeStage1Runtime.lastThoughtActivePlayerId = 0;
  realtimeStage1Runtime.thoughtCommandPending = false;
  return true;
}

function getRealtimeThoughtTimeRemainingMs(playerId = LOCAL_PLAYER_ID, options = {}) {
  const resolvedPlayerId = Number(playerId || 0);
  if (![1, 2].includes(resolvedPlayerId)) return 0;
  const thought = ensureRealtimeThoughtTimeState();
  const key = `p${resolvedPlayerId}`;
  let remaining = Math.max(0, Number(thought.remainingMs[key] || 0));
  const live = options.live !== false;
  if (live
      && canRunRealtimeSimulation()
      && Number(thought.activePlayerId) === resolvedPlayerId
      && Number(thought.lastAccountedAt || 0) > 0) {
    remaining = Math.max(0, remaining - Math.max(0, Date.now() - Number(thought.lastAccountedAt)));
  }
  return remaining;
}

function formatRealtimeThoughtClock(milliseconds = 0) {
  const totalSeconds = Math.max(0, Math.ceil(Number(milliseconds || 0) / 1000));
  const minutes = Math.floor(totalSeconds / 60);
  const seconds = totalSeconds % 60;
  return `${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}`;
}

function isRealtimeThoughtPauseActive() {
  if (!isRealtimePlayStyle() || !state?.realtime?.active) return false;
  const thought = ensureRealtimeThoughtTimeState();
  return [1, 2].includes(Number(thought.activePlayerId));
}

function getRealtimeThoughtPausePlayerId() {
  return isRealtimeThoughtPauseActive()
    ? Number(ensureRealtimeThoughtTimeState().activePlayerId || 0)
    : 0;
}

function isRealtimeThoughtPauseOwnedByLocalPlayer() {
  return Number(getRealtimeThoughtPausePlayerId()) === Number(LOCAL_PLAYER_ID);
}

function canStartRealtimeThoughtPause(playerId = LOCAL_PLAYER_ID) {
  if (!isRealtimePlayStyle() || !state?.realtime?.active || state.gameOver) return false;
  const resolvedPlayerId = Number(playerId || 0);
  if (![1, 2].includes(resolvedPlayerId)) return false;
  const thought = ensureRealtimeThoughtTimeState();
  if (Number(thought.activePlayerId || 0) !== 0) return false;
  if (getRealtimeThoughtTimeRemainingMs(resolvedPlayerId, { live: false }) <= 0) return false;
  const pause = state?.realtime?.tempoPause || {};
  if (pause.active) return false;
  if (state.pendingCard || state.pendingPlacement || state.pendingPowerAction) return false;
  if (state.quickReactionWindow?.active || state.quickReactionWindow?.locked || state.quickReactionWindow?.executing) return false;
  if (state.actionExecutionLock || state.opponentActionResolving || state.castTravelResolving) return false;
  return true;
}

function markRealtimeThoughtTimeDirty(reason = 'thought-time') {
  if (!isOnlineMatchActive() || !isRealtimeOnlineAuthority()) return;
  try { markOnlineStateDirty(reason); } catch (_) {}
}

function startRealtimeThoughtPauseForPlayer(playerId, options = {}) {
  if (!isRealtimePlayStyle() || !state?.realtime?.active || state.gameOver) return false;
  const resolvedPlayerId = Number(playerId || 0);
  if (![1, 2].includes(resolvedPlayerId)) return false;
  if (!canStartRealtimeThoughtPause(resolvedPlayerId)) return false;

  const thought = ensureRealtimeThoughtTimeState();
  const now = Date.now();
  thought.activePlayerId = resolvedPlayerId;
  thought.startedAt = now;
  thought.lastAccountedAt = now;
  realtimeStage1Runtime.lastThoughtBroadcastSecond = Math.ceil(
    getRealtimeThoughtTimeRemainingMs(resolvedPlayerId, { live: false }) / 1000
  );

  setRealtimeTempoPause(
    true,
    resolvedPlayerId === Number(LOCAL_PLAYER_ID) ? 'TIEMPO DE PENSAMIENTO' : 'RIVAL PENSANDO',
    'thought',
  );

  markRealtimeThoughtTimeDirty(`rt-thought-start:p${resolvedPlayerId}`);
  if (isOnlineMatchActive() && isRealtimeOnlineAuthority() && options.commit !== false) {
    void window.ROK_ONLINE_PVP?.commitStateBarrier?.(`rt-thought-start:p${resolvedPlayerId}`);
  }
  renderRealtimeStage1Status();
  return true;
}

function accountRealtimeThoughtTime(now = Date.now()) {
  if (!canRunRealtimeSimulation()) return false;
  const thought = ensureRealtimeThoughtTimeState();
  const playerId = Number(thought.activePlayerId || 0);
  if (![1, 2].includes(playerId)) return false;

  const key = `p${playerId}`;
  const last = Math.max(0, Number(thought.lastAccountedAt || thought.startedAt || now));
  const delta = Math.max(0, Number(now) - last);
  if (delta > 0) {
    thought.remainingMs[key] = Math.max(0, Number(thought.remainingMs[key] || 0) - delta);
    thought.lastAccountedAt = Number(now);
  }

  const remainingMs = Math.max(0, Number(thought.remainingMs[key] || 0));
  const remainingSecond = Math.ceil(remainingMs / REALTIME_THOUGHT_TIME_SYNC_STEP_MS);
  if (remainingSecond !== realtimeStage1Runtime.lastThoughtBroadcastSecond) {
    realtimeStage1Runtime.lastThoughtBroadcastSecond = remainingSecond;
    markRealtimeThoughtTimeDirty(`rt-thought:p${playerId}:${remainingSecond}s`);
    renderRealtimeStage1Status();
  }

  if (remainingMs <= 0) {
    endRealtimeThoughtPauseForPlayer(playerId, 'exhausted', { account: false, commit: true });
  }
  return true;
}

function endRealtimeThoughtPauseForPlayer(playerId, reason = 'manual', options = {}) {
  if (!isRealtimePlayStyle() || !state?.realtime?.active) return false;
  const resolvedPlayerId = Number(playerId || 0);
  const thought = ensureRealtimeThoughtTimeState();
  if (![1, 2].includes(resolvedPlayerId) || Number(thought.activePlayerId || 0) !== resolvedPlayerId) return false;

  if (options.account !== false && canRunRealtimeSimulation()) {
    const key = `p${resolvedPlayerId}`;
    const now = Date.now();
    const last = Math.max(0, Number(thought.lastAccountedAt || thought.startedAt || now));
    thought.remainingMs[key] = Math.max(0, Number(thought.remainingMs[key] || 0) - Math.max(0, now - last));
  }

  thought.activePlayerId = 0;
  thought.startedAt = 0;
  thought.lastAccountedAt = 0;
  realtimeStage1Runtime.lastThoughtBroadcastSecond = -1;

  if (state?.realtime?.tempoPause?.active && state.realtime.tempoPause.source === 'thought') {
    setRealtimeTempoPause(false, '', 'thought');
  }

  // La ficha informativa es de consulta durante la pausa; al reanudar no debe
  // quedarse cubriendo el combate rápido.
  try { closeCardInfo(); } catch (_) {}

  markRealtimeThoughtTimeDirty(`rt-thought-end:p${resolvedPlayerId}:${reason}`);
  if (isOnlineMatchActive() && isRealtimeOnlineAuthority() && options.commit !== false) {
    void window.ROK_ONLINE_PVP?.commitStateBarrier?.(`rt-thought-end:p${resolvedPlayerId}:${reason}`);
  }
  renderRealtimeStage1Status();
  return true;
}

async function toggleRealtimeThoughtPauseForLocalPlayer() {
  if (!isRealtimePlayStyle() || !state?.realtime?.active || state.gameOver) return false;
  const playerId = Number(LOCAL_PLAYER_ID || 0);
  if (![1, 2].includes(playerId)) return false;
  const activePlayerId = getRealtimeThoughtPausePlayerId();

  if (activePlayerId) {
    if (activePlayerId !== playerId) return false;
    if (isOnlineMatchActive() && !isRealtimeOnlineAuthority()) {
      if (realtimeStage1Runtime.thoughtCommandPending) return true;
      realtimeStage1Runtime.thoughtCommandPending = true;
      renderRealtimeStage1Status();
      try {
        return Boolean(await window.ROK_ONLINE_PVP?.sendRealtimeCommand?.('thought-pause', { action: 'stop' }));
      } finally {
        realtimeStage1Runtime.thoughtCommandPending = false;
        renderRealtimeStage1Status();
      }
    }
    return endRealtimeThoughtPauseForPlayer(playerId, 'manual');
  }

  if (!canStartRealtimeThoughtPause(playerId)) return false;
  if (isOnlineMatchActive() && !isRealtimeOnlineAuthority()) {
    if (realtimeStage1Runtime.thoughtCommandPending) return true;
    realtimeStage1Runtime.thoughtCommandPending = true;
    renderRealtimeStage1Status();
    try {
      return Boolean(await window.ROK_ONLINE_PVP?.sendRealtimeCommand?.('thought-pause', { action: 'start' }));
    } finally {
      realtimeStage1Runtime.thoughtCommandPending = false;
      renderRealtimeStage1Status();
    }
  }
  return startRealtimeThoughtPauseForPlayer(playerId);
}

function renderRealtimeThoughtTimeUi() {
  const activeRealtime = isRealtimePlayStyle() && Boolean(state?.realtime?.active);
  const thought = activeRealtime ? ensureRealtimeThoughtTimeState() : null;
  const localPlayerId = Number(LOCAL_PLAYER_ID || 1);
  const activePlayerId = Number(thought?.activePlayerId || 0);
  const previousActivePlayerId = Number(realtimeStage1Runtime.lastThoughtActivePlayerId || 0);

  // En el cliente réplica el fin de la pausa llega por snapshot. Cerramos la
  // inspección local en esa transición para que la partida vuelva visible.
  if (previousActivePlayerId && !activePlayerId && activeRealtime) {
    try { closeCardInfo(); } catch (_) {}
  }
  realtimeStage1Runtime.lastThoughtActivePlayerId = activePlayerId;

  const localRemainingMs = activeRealtime
    ? getRealtimeThoughtTimeRemainingMs(localPlayerId, { live: true })
    : REALTIME_THOUGHT_TIME_MAX_MS;
  const activeRemainingMs = activePlayerId
    ? getRealtimeThoughtTimeRemainingMs(activePlayerId, { live: true })
    : 0;

  if (els.realtimeThoughtBank) {
    els.realtimeThoughtBank.textContent = formatRealtimeThoughtClock(localRemainingMs);
  }

  if (els.realtimeThoughtBtn) {
    const owned = activePlayerId === localPlayerId;
    const rivalActive = Boolean(activePlayerId && !owned);
    const pending = Boolean(realtimeStage1Runtime.thoughtCommandPending);
    const canStart = activeRealtime && !activePlayerId && canStartRealtimeThoughtPause(localPlayerId);
    els.realtimeThoughtBtn.hidden = !activeRealtime;
    els.realtimeThoughtBtn.disabled = pending || rivalActive || (!owned && !canStart);
    els.realtimeThoughtBtn.classList.toggle('is-active', owned);
    els.realtimeThoughtBtn.classList.toggle('is-rival', rivalActive);
    if (pending) els.realtimeThoughtBtn.textContent = 'SINCRONIZANDO…';
    else if (owned) els.realtimeThoughtBtn.textContent = `CONTINUAR · ${formatRealtimeThoughtClock(activeRemainingMs)}`;
    else if (rivalActive) els.realtimeThoughtBtn.textContent = `RIVAL PENSANDO · ${formatRealtimeThoughtClock(activeRemainingMs)}`;
    else if (localRemainingMs <= 0) els.realtimeThoughtBtn.textContent = 'PENSAR · 00:00';
    else els.realtimeThoughtBtn.textContent = `PENSAR · ${formatRealtimeThoughtClock(localRemainingMs)}`;
  }

  const showOverlay = activeRealtime && Boolean(activePlayerId);
  if (els.realtimeThoughtOverlay) {
    els.realtimeThoughtOverlay.classList.toggle('is-open', showOverlay);
    els.realtimeThoughtOverlay.setAttribute('aria-hidden', showOverlay ? 'false' : 'true');
  }
  document.body.classList.toggle('rok-realtime-thought-active', showOverlay);

  if (!showOverlay) return;
  const owned = activePlayerId === localPlayerId;
  if (els.realtimeThoughtTitle) {
    els.realtimeThoughtTitle.textContent = owned ? 'ESTÁS PENSANDO' : 'EL RIVAL ESTÁ PENSANDO';
  }
  if (els.realtimeThoughtClock) {
    els.realtimeThoughtClock.textContent = formatRealtimeThoughtClock(activeRemainingMs);
  }
  if (els.realtimeThoughtCopy) {
    els.realtimeThoughtCopy.textContent = owned
      ? 'El combate está congelado. Puedes inspeccionar cartas, estudiar la arena y ajustar Modos de combate.'
      : 'El combate está congelado para ambos jugadores hasta que el rival continúe o agote su reserva.';
  }
  if (els.realtimeThoughtResumeBtn) {
    els.realtimeThoughtResumeBtn.hidden = !owned;
    els.realtimeThoughtResumeBtn.disabled = !owned || realtimeStage1Runtime.thoughtCommandPending;
  }
}

function processRealtimeThoughtTimePoll() {
  if (!isRealtimeThoughtPauseActive()) return false;
  if (!canRunRealtimeSimulation()) {
    renderRealtimeThoughtTimeUi();
    return true;
  }
  return accountRealtimeThoughtTime(Date.now());
}

function isRealtimeAbilityContext(playerId = null) {
  if (!canRunRealtimeSimulation()) return false;
  return playerId == null || Boolean(state.players?.[Number(playerId)]);
}

function isRealtimeTempoPaused() {
  return Boolean(isRealtimePlayStyle() && state?.realtime?.active && state?.realtime?.tempoPause?.active);
}

function setRealtimeTempoPause(active, reason = '', source = 'ability') {
  if (!isRealtimePlayStyle() || !state?.realtime?.active) return false;
  ensureRealtimeStage5State();
  const pause = state.realtime.tempoPause;
  const now = Date.now();
  // Cierra o abre el tramo de pausa global-no-Tempo exactamente en el borde
  // de esta transición para que ambos relojes representen una unión, no una suma.
  syncRealtimeGlobalPauseClock(now);
  if (active) {
    if (!pause.active) {
      pause.active = true;
      pause.startedAt = now;
    }
    pause.source = String(source || 'ability');
    pause.reason = String(reason || 'Habilidad');
  } else if (pause.active) {
    // RT-08.12 · Una rutina solo puede liberar la pausa que ella misma posee.
    // Antes el finally de una habilidad podía levantar, por ejemplo, la pausa
    // de AJUSTES VISUALES o Tiempo de Pensamiento.
    const requestedSource = String(source || '');
    if (requestedSource && pause.source && requestedSource !== pause.source) return false;
    pause.accumulatedMs = Math.max(0, Number(pause.accumulatedMs || 0)) + Math.max(0, now - Number(pause.startedAt || now));
    pause.active = false;
    pause.startedAt = 0;
    pause.source = '';
    pause.reason = '';
    // Reanudar nunca dispara acciones acumuladas: empieza un ciclo maestro nuevo.
    scheduleNextRealtimeTempoTick(now);
  }
  syncRealtimeGlobalPauseClock(now);
  try {
    recordRokMatchDiagnostic('tempo-pause', active ? 'PAUSE' : 'RESUME', {
      source: String(source || ''),
      reason: String(reason || ''),
      active: Boolean(state?.realtime?.tempoPause?.active),
      liveSource: String(state?.realtime?.tempoPause?.source || ''),
    });
  } catch (_) {}
  renderRealtimeStage1Status();
  return true;
}

function hasRealtimeManualAbilityInteraction() {
  if (!isRealtimeAbilityContext(LOCAL_PLAYER_ID) || realtimeStage5Runtime.autoAbilityDepth > 0) return false;
  const pendingKind = String(state.pendingPowerAction?.kind || '');
  if (REALTIME_MANUAL_ABILITY_PENDING_KINDS.has(pendingKind)
      && Number(state.pendingPowerAction?.playerId ?? LOCAL_PLAYER_ID) === Number(LOCAL_PLAYER_ID)) return true;
  const paymentMode = String(state.randomCostPayment?.mode || '');
  return REALTIME_MANUAL_ABILITY_PAYMENT_MODES.has(paymentMode)
    && Number(state.randomCostPayment?.playerId ?? LOCAL_PLAYER_ID) === Number(LOCAL_PLAYER_ID);
}


function cancelRealtimeInvocationInteractionSafely(reason = 'stale') {
  if (!isRealtimePlayStyle() || !state?.realtime?.active) return false;
  const pending = state.pendingPowerAction;
  if (!pending) return false;
  const kind = String(pending.kind || '');
  if (!REALTIME_MANUAL_ABILITY_PENDING_KINDS.has(kind)) return false;

  let cancelled = false;
  if (kind === 'smokeBomb') cancelled = completeSmokeBombFlow(pending, 'cancelled');
  else if (kind === 'minokageShippuUgachi') cancelled = cancelMinokagePowerTargeting('');
  else if (kind === 'kaguyaChargedShot') cancelled = cancelKaguyaChargedShotTargeting('');
  else if (kind === 'farolEnlazadoCircle' || kind === 'farolEnlazadoLamp') cancelled = cancelFarolEnlazadoTargeting('');
  else if (kind === 'seyranDistorsionTarget') cancelled = cancelSeyranDistortionTargeting('');
  else if (kind === 'maerynDominationTarget') cancelled = cancelMaerynDominationTargeting('');
  else if (kind === 'yasuganaBlindness' || kind === 'yasuganaVigilia') cancelled = cancelYasuganaPowerTargeting('');
  else if (kind === 'kurayamiMark') cancelled = cancelKurayamiPowerTargeting('');
  else if (kind === 'gioshoninSupply') cancelled = cancelGioshoninSupplyTargeting('');
  else if (kind === 'kurokagiBukiPickup') cancelled = cancelKurokagiBukiPickupTargeting('');
  else if (kind === 'shirahadoriAbilityTarget') cancelled = cancelShirahadoriAbilityTargeting('');

  if (!cancelled && state.pendingPowerAction === pending) {
    const resolver = typeof pending.reactionResolve === 'function' ? pending.reactionResolve : null;
    state.pendingPowerAction = null;
    try { resolver?.('cancelled'); } catch (_) {}
    forceReleaseQuickReactionManualPowerFlow('cancelled');
    clearCombatMenus();
    cancelled = true;
  }

  if (cancelled) {
    try { log(`RT · Interacción de Invocación liberada (${kind || 'desconocida'} · ${reason}).`); } catch (_) {}
    releaseQuickReactionStateIfIdle(`rt-stall-${kind || 'power'}`);
  }
  return cancelled;
}

function cleanupRealtimeAutomatedAbilityResidue(playerId, unitId, reason = 'auto-ability-finally') {
  const pending = state.pendingPowerAction;
  if (!pending) return false;
  if (Number(pending.playerId ?? playerId) !== Number(playerId)) return false;
  if (String(pending.unitId || '') !== String(unitId || '')) return false;
  return cancelRealtimeInvocationInteractionSafely(reason);
}


function getRealtimePendingActionOrphanReason(pending = state.pendingPowerAction) {
  if (!pending) return '';
  const kind = String(pending.kind || '');
  const playerId = Number(pending.playerId || LOCAL_PLAYER_ID);
  try {
    if (kind === 'smokeBomb') {
      const unit = getUnitById(playerId, pending.unitId);
      if (!unit || unit.status === 'restoring' || Number(unit.smokeBombsLeft || 0) <= 0) return 'Bomba de humo perdió su fuente o ya no tiene bombas.';
    }
    if (kind === 'minokageShippuUgachi') {
      const unit = getUnitById(playerId, pending.unitId);
      if (!unit || !getMinokagePowerTargets(playerId, unit).length) return 'Shippū Ugachi ya no tiene objetivo legal.';
    }
    if (kind === 'kaguyaChargedShot') {
      const unit = getUnitById(playerId, pending.unitId);
      if (!unit || !getKaguyaChargedShotTargets(playerId, unit).length) return 'Disparo energizado ya no tiene objetivo legal.';
    }
    if (['farolEnlazadoCircle','farolEnlazadoLamp'].includes(kind)) {
      const unit = getUnitById(playerId, pending.unitId);
      if (!unit || unit.status === 'restoring' || !unitCanActivateFarolEnlazado(playerId, unit)) return 'Farol Enlazado perdió su fuente o ya no está disponible.';
      const cells = kind === 'farolEnlazadoCircle'
        ? getFarolCirclePlacementCells(playerId, unit)
        : getFarolLanternDestinationCells(playerId, unit);
      if (!cells.length) return 'Farol Enlazado ya no tiene casillas legales.';
    }
    if (kind === 'seyranDistorsionTarget') {
      const unit = getUnitById(playerId, pending.unitId);
      if (!unit || unit.status === 'restoring' || !unitCanActivateSeyranDistortion(playerId, unit)) return 'Distorsión Espacial perdió a Seyran o ya no tiene desplazamientos legales.';
      if (!getSeyranDistortionTargets(playerId, unit).length) return 'Distorsión Espacial ya no tiene Invocaciones objetivo dentro de Alcance 4.';
    }
    if (kind === 'maerynDominationTarget') {
      const unit = getUnitById(playerId, pending.unitId);
      if (!unit || unit.status === 'restoring' || !unitCanActivateMaerynDomination(playerId, unit)) return 'Dominación Mental perdió a Maeryn o ya no tiene objetivo legal.';
      if (!getMaerynDominationTargets(playerId, unit).length) return 'Dominación Mental ya no tiene Invocaciones rivales válidas.';
    }
    if (['yasuganaBlindness','yasuganaVigilia'].includes(kind)) {
      const unit = getUnitById(playerId, pending.unitId);
      if (!unit) return 'Yasugana perdió su fuente.';
      const targets = kind === 'yasuganaBlindness'
        ? getYasuganaBlindnessTargets(playerId, unit)
        : getYasuganaVigiliaTargets(playerId, unit);
      if (!targets.length) return 'Genyutsu ya no tiene objetivo legal.';
    }
    if (kind === 'kurayamiMark') {
      const unit = getUnitById(playerId, pending.unitId);
      if (!unit || !getKurayamiPowerTargets(playerId, unit).length) return 'Shizukesa no Shi-in ya no tiene objetivo legal.';
    }
    if (kind === 'gioshoninSupply') {
      const unit = getUnitById(playerId, pending.unitId);
      if (!unit) return 'Mercancía de guerra perdió a Gioshonin.';
      if (!getAffordableGioshoninSupplyTargets(playerId, unit).length && !state.randomCostPayment) return 'Mercancía de guerra ya no tiene aliado válido.';
    }
    if (kind === 'kurokagiBukiPickup') {
      const unit = getUnitById(playerId, pending.unitId);
      if (!unit || !getKurokagiBukiPickupCandidates(unit).length) return 'Buki Utsushi ya no tiene arma caída válida.';
    }
    if (kind === 'shirahadoriAbilityTarget' && !getEligibleShirahadoriAbilityUsers(playerId).length) return 'Shirahadori ya no tiene usuario elegible.';
    if (kind === 'despliegueAnticipadoTarget' && !getEligibleDespliegueAnticipadoTargets(playerId).length) return 'Despliegue anticipado ya no tiene Caudillo elegible.';
    if (kind === 'gloriaLatenteTarget') {
      const a = getGloriaLatenteCastAvailability(playerId);
      if (!a.available || !a.targets?.length) return 'Gloria latente ya no tiene objetivo elegible.';
    }
    if (kind === 'interceptarAlliedSelection'
        && !getInterceptarAlliedCandidates(playerId).some(unit => getInterceptarRivalCandidates(playerId, unit).length)) {
      return 'Interceptar ya no tiene pareja válida.';
    }
    if (kind === 'interceptarRivalSelection') {
      const ally = getUnitById(playerId, pending.selectedAlliedUnitId);
      if (!ally || !getInterceptarRivalCandidates(playerId, ally).length) return 'Interceptar perdió su invasora legal.';
    }
    if (kind === 'tacticaGuerraSelection') {
      const selected = (pending.selectedUnitIds || []).length;
      const eligible = getEligibleTacticaGuerraTargets(playerId, { quickOnly: pending.quickDefense === true, requirePayable: false });
      if (!selected && !eligible.length) return 'Táctica de guerra ya no tiene unidad elegible.';
    }
    if (kind === 'tacticaGuerraDestination') {
      const unit = getTacticaGuerraCurrentUnit(pending);
      if (!unit || !getTacticaGuerraDestinationCells(playerId, unit, pending).length) return 'Táctica de guerra perdió su destino legal.';
    }
    if (kind === 'emboscadaRivalSelection' && !getEmboscadaRivalCandidates(playerId).length) return 'Emboscada ya no tiene invasora elegible.';
    if (kind === 'emboscadaAlliedSelection') {
      const rival = getUnitById(getEnemyPlayerId(playerId), pending.selectedRivalUnitId);
      if (!rival) return 'Emboscada perdió la invasora seleccionada.';
      if (!(pending.selectedUnitIds || []).length && !getEmboscadaAlliedCandidates(playerId).length) return 'Emboscada ya no tiene aliado elegible.';
    }
    if (kind === 'emboscadaDestination') {
      const unit = getEmboscadaCurrentUnit(pending);
      if (!unit || !getEmboscadaDestinationCells(playerId, pending).length) return 'Emboscada perdió una casilla de nexo legal.';
    }
  } catch (error) {
    reportDebugError(`stage6-orphan-check:${kind}`, error);
  }
  return '';
}

function cancelRealtimePendingActionByKind(reason = 'interacción huérfana') {
  const kind = String(state.pendingPowerAction?.kind || '');
  if (!kind) return false;
  let cancelled = REALTIME_MANUAL_ABILITY_PENDING_KINDS.has(kind)
    ? cancelRealtimeInvocationInteractionSafely(reason)
    : cancelCurrentCancelableAction();
  if (cancelled) {
    const key = `${kind}:${reason}`;
    const now = Date.now();
    if (key !== realtimeStage6AuditRuntime.lastOrphanRecoveryKey
        || now - realtimeStage6AuditRuntime.lastOrphanRecoveryAt > 2500) {
      realtimeStage6AuditRuntime.lastOrphanRecoveryKey = key;
      realtimeStage6AuditRuntime.lastOrphanRecoveryAt = now;
      try {
        recordRokMatchDiagnostic('stage6-orphan-recovery', reason, { kind }, { persistNow: true });
        recordRokTacticalTelemetry('orphan-recovery', { kind, reason });
        window.ROK_DEBUG_RIBBON?.show?.('INTERACCIÓN LIBERADA', 'warn', `${kind} · ${reason}`);
      } catch (_) {}
    }
  }
  return cancelled;
}

function recoverRealtimeOrphanedInteraction() {
  const pending = state.pendingPowerAction;
  if (!pending) return false;
  const reason = getRealtimePendingActionOrphanReason(pending);
  return reason ? cancelRealtimePendingActionByKind(reason) : false;
}

function recoverKnownOrphanedExecutionLocks() {
  let repaired = false;
  const now = Date.now();

  if (state.actionExecutionLock) {
    const reason = String(state.actionExecutionLockReason || '');
    const ageMs = Math.max(0, now - Number(state.actionExecutionLockStartedAt || now));
    if (reason === GIOSHONIN_PRIORITY_LOCK_REASON && ageMs > 7000) {
      const owns = Boolean(
        state.gioshoninSupplyPrompt?.active
        || state.pendingPowerAction?.kind === 'gioshoninSupply'
        || state.randomCostPayment?.mode === 'gioshoninSupply'
        || document.getElementById('gioshoninSupplyPrompt')
        || document.getElementById('gioshoninSupplyOverlay')
      );
      if (!owns) { setActionExecutionLock(false, GIOSHONIN_PRIORITY_LOCK_REASON); repaired = true; }
    }
    if (reason === 'kurokagi-buki-pickup' && ageMs > 12000) {
      const owns = Boolean(
        state.pendingPowerAction?.kind === 'kurokagiBukiPickup'
        || document.getElementById('kurokagiDropChoiceModal')
      );
      if (!owns) { setActionExecutionLock(false, 'kurokagi-buki-pickup'); repaired = true; }
    }
  }

  if (state.opponentActionResolving) {
    const reason = String(state.opponentActionLockReason || '');
    const ageMs = Math.max(0, now - Number(state.opponentActionLockStartedAt || now));
    if (reason === 'quick-reaction-window' && ageMs > 9000) {
      const owns = Boolean(
        state.quickReactionWindow?.active || state.quickReactionWindow?.locked
        || state.quickReactionWindow?.executing || state.quickReactionWindow?.phaseIntro
        || els.quickReactionWindow?.classList?.contains('visible')
        || els.quickReactionModal?.classList?.contains('visible')
      );
      if (!owns) {
        state.opponentActionLockDepth = 1;
        setOpponentActionLock(false, 'quick-reaction-window');
        repaired = true;
      }
    }
    if (reason === 'opponent-action-notice' && ageMs > 9000) {
      const owns = Boolean(state.opponentActionNoticeAwaiting || document.getElementById('opponentActionNotice'));
      if (!owns) {
        state.opponentActionLockDepth = 1;
        setOpponentActionLock(false, 'opponent-action-notice');
        repaired = true;
      }
    }
  }

  if (repaired) {
    try {
      recordRokMatchDiagnostic('stage6-lock-recovery', 'Se liberó un lock conocido sin dueño.', {
        actionExecutionLock: state.actionExecutionLock,
        actionExecutionLockReason: state.actionExecutionLockReason,
        opponentActionResolving: state.opponentActionResolving,
        opponentActionLockReason: state.opponentActionLockReason,
      }, { persistNow: true });
    } catch (_) {}
  }
  return repaired;
}

function processRealtimeStallRecovery() {
  if (!isRealtimePlayStyle() || !state?.realtime?.active) return false;
  let repaired = false;
  try { syncRealtimeSpellActionPauseState(); } catch (error) { reportDebugError('spell-action-pause-sync', error); }

  // 1) Si la Promise defensiva pierde su menú o vence el watchdog,
  //    nunca se inventa una Guardia. Sin respuesta explícita = el golpe entra.
  const casterPending = state.pendingCasterDefense;
  if (casterPending) {
    const hasMenu = Boolean(document.querySelector('.caster-defense-menu'));
    const ageMs = Math.max(0, Date.now() - Number(casterPending.startedAt || Date.now()));
    if (!hasMenu || ageMs > REALTIME_CASTER_DEFENSE_WINDOW_MS + 750) {
      repaired = settlePendingCasterDefenseSafely('none', hasMenu ? 'timeout watchdog' : 'menú perdido') || repaired;
    }
  }

  // 2) Selecciones manuales de Poder de Invocación no deben quedar infinitas
  //    en Tiempo real. Las automáticas se limpian inmediatamente en finally;
  //    las excepcionales/interactivas reciben una ventana corta antes del
  //    watchdog.
  const pending = state.pendingPowerAction;
  const pendingKind = String(pending?.kind || '');
  if (pending && REALTIME_MANUAL_ABILITY_PENDING_KINDS.has(pendingKind) && realtimeStage5Runtime.autoAbilityDepth <= 0) {
    if (!Number(pending.realtimeInteractionStartedAt || 0)) pending.realtimeInteractionStartedAt = Date.now();
    const ageMs = Date.now() - Number(pending.realtimeInteractionStartedAt);
    const protectedBySpellAction = Boolean(
      tacticalSpellbookRuntime?.spellAction?.active
      && state?.realtime?.tempoPause?.active
      && state.realtime.tempoPause.source === REALTIME_SPELL_ACTION_PAUSE_SOURCE
    );
    if (!protectedBySpellAction && ageMs >= REALTIME_MANUAL_INVOCATION_INTERACTION_MAX_MS) {
      repaired = cancelRealtimeInvocationInteractionSafely('watchdog') || repaired;
    }
  }

  try { if (recoverRealtimeOrphanedInteraction()) repaired = true; }
  catch (error) { reportDebugError('stage6-orphan-recovery', error); }

  try { if (recoverKnownOrphanedExecutionLocks()) repaired = true; }
  catch (error) { reportDebugError('stage6-lock-recovery', error); }

  // 3) Un token quick-reaction residual sin modal/dock/pending real no puede
  //    bloquear waitForAutonomousGameplayResume().
  try {
    if (releaseQuickReactionStateIfIdle('realtime-stall-watchdog')) repaired = true;
  } catch (_) {}

  // 4) Si manual-ability quedó marcado pero ya no existe interacción manual,
  //    liberar únicamente esa pausa.
  const pause = state?.realtime?.tempoPause;
  if (pause?.active && pause.source === 'manual-ability' && !hasRealtimeManualAbilityInteraction()) {
    setRealtimeTempoPause(false, '', 'manual-ability');
    repaired = true;
  }

  return repaired;
}


function syncRealtimeManualAbilityPauseState() {
  if (!isRealtimeAbilityContext() || realtimeStage5Runtime.autoAbilityDepth > 0) return false;
  const manualPending = hasRealtimeManualAbilityInteraction();
  const pause = ensureRealtimeStage5State().tempoPause;
  if (manualPending && !pause.active) {
    setRealtimeTempoPause(true, 'Decisión de habilidad', 'manual-ability');
    return true;
  }
  if (!manualPending && pause.active && pause.source === 'manual-ability') {
    setRealtimeTempoPause(false, '', 'manual-ability');
    return true;
  }
  return manualPending;
}

function resetRealtimeStage5Runtime() {
  realtimeStage5Runtime.temporalBusy = false;
  realtimeStage5Runtime.abilityBusy = false;
  realtimeStage5Runtime.autoAbilityDepth = 0;
  realtimeStage5Runtime.lastProcessedSecond = 0;
  realtimeStage5Runtime.lastAbilityDecisionSecond = 0;
  realtimeStage5Runtime.lastLegacyTurnBucket = 0;
  realtimeStage5Runtime.unitAbilityNextSecond.clear();
  realtimeStage5Runtime.currentAbilityLabel = '';
  if (state?.realtime) {
    state.realtime.tempoPause = { active: false, source: '', reason: '', startedAt: 0, accumulatedMs: 0 };
    state.realtime.temporalSystem = {
      initialized: true,
      phaseSeconds: getRealtimeTempoSeconds(),
      legacyTurnSeconds: REALTIME_LEGACY_TURN_SECONDS,
      lastProcessedSecond: 0,
      legacyTurnSerial: 1,
    };
    state.realtime.abilitySystem = {
      initialized: true,
      decisionSeconds: REALTIME_ABILITY_DECISION_SECONDS,
      retrySeconds: REALTIME_ABILITY_RETRY_SECONDS,
      lastDecisionSecond: 0,
      activations: 0,
      lastAbility: '',
    };
  }
}

function normalizeRealtimeResourceDomainIds(ids = []) {
  const normalized = [];
  (Array.isArray(ids) ? ids : []).forEach(id => {
    const value = String(id || '').trim();
    if (!value || value === 'random' || value === CATALYST_DOMAIN_ID || normalized.includes(value)) return;
    if (!ELEMENTS.some(element => element.id === value)) return;
    normalized.push(value);
  });
  return normalized.slice(0, SPELLBOOK_MAX_DOMAINS);
}

function getRealtimeResourceMaxCapacityForDomainCount(domainCount = 1) {
  const count = Math.max(1, Math.min(SPELLBOOK_MAX_DOMAINS, Math.floor(Number(domainCount) || 1)));
  return Math.floor(REALTIME_RESOURCE_TOTAL_CAPACITY / count);
}


function getRealtimeResourceGrowthProgress(capacity, maxCapacity) {
  const initial = REALTIME_RESOURCE_INITIAL_CAPACITY;
  const current = Math.max(initial, Math.floor(Number(capacity) || initial));
  const maximum = Math.max(current + 1, Math.floor(Number(maxCapacity) || REALTIME_RESOURCE_MAX_CAPACITY));

  // Hay (max - initial) desbloqueos. Para que el PRIMER desbloqueo sea 3 s y
  // el ÚLTIMO sea exactamente 30 s, el progreso del último paso debe ser 1.
  const totalGrowthSteps = Math.max(1, maximum - initial);
  if (totalGrowthSteps <= 1) return 1;
  const completedGrowthSteps = Math.max(0, current - initial);
  return Math.max(0, Math.min(1, completedGrowthSteps / Math.max(1, totalGrowthSteps - 1)));
}

function getRealtimeResourceGrowthIntervalSeconds(capacity, maxCapacity) {
  if (Number(capacity || 0) >= Number(maxCapacity || 0)) return 0;
  const progress = getRealtimeResourceGrowthProgress(capacity, maxCapacity);
  const eased = Math.pow(progress, REALTIME_RESOURCE_GROWTH_CURVE_EXPONENT);
  const minSeconds = getRealtimeTimingValue('resourceGrowthMinSeconds');
  const maxSeconds = Math.max(minSeconds, getRealtimeTimingValue('resourceGrowthMaxSeconds'));
  const span = maxSeconds - minSeconds;
  return Math.max(
    minSeconds,
    Math.min(
      maxSeconds,
      Number((minSeconds + span * eased).toFixed(1)),
    ),
  );
}

function scheduleNextRealtimeResourceGrowth(track, fromSecond) {
  if (!track) return 0;
  const capacity = Math.max(0, Number(track.capacity || 0));
  const maxCapacity = Math.max(capacity, Number(track.maxCapacity || REALTIME_RESOURCE_MAX_CAPACITY));
  if (capacity >= maxCapacity) {
    track.nextGrowthAt = 0;
    track.growthIntervalSeconds = 0;
    return 0;
  }
  const interval = getRealtimeResourceGrowthIntervalSeconds(capacity, maxCapacity);
  track.growthIntervalSeconds = interval;
  track.nextGrowthAt = Math.max(0, Number(fromSecond || 0)) + interval;
  return track.nextGrowthAt;
}

function getRealtimeResourceClockSecond() {
  // getRealtimeElapsedSeconds() ya descuenta pause.accumulatedMs y la pausa
  // actualmente activa. Es por tanto el reloj correcto para recursos.
  return Math.max(0, Number(getRealtimeElapsedSeconds() || 0));
}

function buildRealtimeAutomaticElementDistribution(casterCardId, cards = []) {
  const ids = normalizeRealtimeResourceDomainIds(
    getSpellbookElementOptionIds(casterCardId, Array.isArray(cards) ? cards : []),
  );
  // El Kaster siempre debe aportar al menos su dominio base, incluso si el
  // Spellbook todavía no contiene otra carta de ese elemento.
  if (!ids.length) {
    const base = getSpellbookCountedDomainId(casterCardId);
    if (base) ids.push(base);
  }
  const activeIds = ids.slice(0, SPELLBOOK_MAX_DOMAINS);
  const perDomain = getRealtimeResourceMaxCapacityForDomainCount(activeIds.length || 1);
  return Object.fromEntries(activeIds.map(id => [id, perDomain]));
}

function getRealtimeAutomaticElementDistributionForPlayer(playerId) {
  const player = state.players?.[playerId];
  if (!player) return {};
  const cards = Array.isArray(player.handTabs) ? player.handTabs.flat().filter(Boolean) : [];
  return buildRealtimeAutomaticElementDistribution(player.caster?.cardId, cards);
}

function ensureRealtimeResourceSystemState() {
  if (!state.realtime || typeof state.realtime !== 'object') {
    state.realtime = { active: false, startedAt: 0, elapsedSeconds: 0, tickSerial: 0, phaseEquivalentSeconds: 1 };
  }
  if (!state.realtime.resourceSystem || typeof state.realtime.resourceSystem !== 'object') {
    state.realtime.resourceSystem = {
      initialized: false,
      distributionMode: 'automatic-round-robin-30',
      totalCapacity: REALTIME_RESOURCE_TOTAL_CAPACITY,
      initialCapacity: REALTIME_RESOURCE_INITIAL_CAPACITY,
      refillSeconds: REALTIME_RESOURCE_REFILL_SECONDS,
      growthStartSeconds: REALTIME_RESOURCE_GROWTH_START_SECONDS,
      growthEndSeconds: REALTIME_RESOURCE_GROWTH_END_SECONDS,
      growthCurveExponent: REALTIME_RESOURCE_GROWTH_CURVE_EXPONENT,
      timingMode: 'active-seconds-progressive',
      maxCapacity: REALTIME_RESOURCE_MAX_CAPACITY,
      stealAccelerationSeconds: REALTIME_RESOURCE_STEAL_ACCELERATION_SECONDS,
      players: {},
    };
  }
  if (!state.realtime.resourceSystem.players || typeof state.realtime.resourceSystem.players !== 'object') {
    state.realtime.resourceSystem.players = {};
  }
  return state.realtime.resourceSystem;
}

function getRealtimePlayerDomainIds(playerId) {
  const player = state.players?.[playerId];
  if (!player) return [];
  const primary = getPlayerDomainId(playerId) || player.elementId || 'oscuridad';
  const ids = [];
  const add = id => {
    if (!id || id === 'random' || id === CATALYST_DOMAIN_ID || ids.includes(id)) return;
    if (!ELEMENTS.some(element => element.id === id)) return;
    ids.push(id);
  };
  add(primary);

  // RT-08.2: en Tiempo real la Fuente NO usa la distribución manual guardada.
  // Los dominios salen únicamente de la composición real del Spellbook y se
  // reparten automáticamente sobre el total fijo de 30 elementos.
  try {
    const cards = Array.isArray(player.handTabs) ? player.handTabs.flat().filter(Boolean) : [];
    getSpellbookElementOptionIds(player.caster?.cardId, cards).forEach(add);
  } catch (_) {}
  return normalizeRealtimeResourceDomainIds(ids);
}

function getRealtimeResourcePlayerState(playerId, create = false) {
  const system = ensureRealtimeResourceSystemState();
  const key = String(Number(playerId));
  if (!system.players[key] && create) {
    system.players[key] = {
      playerId: Number(playerId),
      primaryElementId: getPlayerDomainId(playerId) || state.players?.[playerId]?.elementId || 'oscuridad',
      elementIds: getRealtimePlayerDomainIds(playerId),
      tracks: {},
    };
  }
  return system.players[key] || null;
}

function getRealtimeResourceTrack(playerId, elementId) {
  return getRealtimeResourcePlayerState(playerId, false)?.tracks?.[elementId] || null;
}

function countPlayerResourcesByElement(playerId, elementId) {
  return (state.players?.[playerId]?.resources || []).filter(resource => resource?.id === elementId).length;
}

function createRealtimeResourceToken(playerId, elementId, source = 'refill') {
  const player = state.players?.[playerId];
  const element = getElementById(elementId) || ELEMENTS.find(entry => entry.id === elementId);
  if (!player || !element) return null;
  const serial = `${Date.now()}_${Math.random().toString(16).slice(2)}`;
  const token = {
    ...element,
    icon: getElementCostIcon(elementId),
    uid: `rt_${source}_${playerId}_${elementId}_${serial}`,
    createdAt: Date.now(),
    realtimeGenerated: true,
  };
  player.resources.push(token);
  return token;
}


function createRealtimeFountainDropletFx(playerId, elementId, startPoint) {
  const element = getElementById(elementId) || ELEMENTS.find(entry => entry.id === elementId) || getPlayerElement(playerId);
  const droplet = document.createElement('div');
  droplet.className = 'rt-fountain-droplet-fx';
  const viewport = viewportPointFromBoardLocal(startPoint);
  droplet.style.left = `${viewport.x}px`;
  droplet.style.top = `${viewport.y}px`;
  droplet.style.setProperty('--resource-color', element?.color || getPlayerElementColor(playerId));
  droplet.innerHTML = `<img src="${getElementCostIcon(element?.id || elementId)}" alt="${element?.label || elementId}">`;
  getGlobalFxLayer().appendChild(droplet);
  return droplet;
}

async function animateRealtimeFountainDropletToCaster(playerId, elementId, startPoint, casterPoint, index = 0) {
  const droplet = createRealtimeFountainDropletFx(playerId, elementId, startPoint);
  const startViewport = viewportPointFromBoardLocal(startPoint);
  const endViewport = viewportPointFromBoardLocal(casterPoint);
  const sideOffset = (index - 1) * 14;
  await animateCss(droplet, [
    { left: `${startViewport.x + sideOffset}px`, top: `${startViewport.y - 8}px`, transform: 'translate(-50%, -50%) scale(.35)', opacity: 0 },
    { left: `${startViewport.x + sideOffset}px`, top: `${startViewport.y - 34}px`, transform: 'translate(-50%, -50%) scale(.95)', opacity: 1, offset: .2 },
    { left: `${(startViewport.x + endViewport.x) / 2}px`, top: `${Math.min(startViewport.y, endViewport.y) - 46}px`, transform: 'translate(-50%, -50%) scale(.86)', opacity: .95, offset: .68 },
    { left: `${endViewport.x}px`, top: `${endViewport.y}px`, transform: 'translate(-50%, -50%) scale(.52)', opacity: .98 },
  ], REALTIME_FOUNTAIN_DROPLET_TRAVEL_MS, 'cubic-bezier(.22,.74,.19,1)');
  safeRemove(droplet);
}

function getRealtimeCasterBoardPoint(playerId) {
  const caster = state.players?.[playerId]?.caster;
  if (caster && Number.isFinite(Number(caster.row)) && Number.isFinite(Number(caster.col))) {
    return cellCenter(Number(caster.row), Number(caster.col));
  }
  return getExtractionSourcePoint(playerId) || getExtractionCenterPoint();
}


function getRealtimePendingResourceAnimationStore() {
  if (!state.realtime) state.realtime = {};
  if (!state.realtime.pendingResourceAnimations || typeof state.realtime.pendingResourceAnimations !== 'object') {
    state.realtime.pendingResourceAnimations = {};
  }
  return state.realtime.pendingResourceAnimations;
}

function getRealtimePendingResourceAnimationCount(playerId, elementId) {
  const store = getRealtimePendingResourceAnimationStore();
  return Math.max(0, Number(store[`${Number(playerId)}:${String(elementId)}`] || 0));
}

function changeRealtimePendingResourceAnimationCount(playerId, elementId, delta) {
  const store = getRealtimePendingResourceAnimationStore();
  const key = `${Number(playerId)}:${String(elementId)}`;
  const next = Math.max(0, Number(store[key] || 0) + Number(delta || 0));
  if (next > 0) store[key] = next;
  else delete store[key];
  return next;
}

function enqueueRealtimeFountainExtraction(playerId, elementId, source = 'refill') {
  if (!enqueueRealtimeFountainExtraction.queues) enqueueRealtimeFountainExtraction.queues = {};
  const queues = enqueueRealtimeFountainExtraction.queues;
  changeRealtimePendingResourceAnimationCount(playerId, elementId, 1);
  const previous = queues[playerId] || Promise.resolve();
  const task = previous.catch(() => {}).then(async () => {
    const sourcePoint = getExtractionSourcePoint(playerId) || getExtractionCenterPoint();
    const casterPoint = getRealtimeCasterBoardPoint(playerId);
    setFountainExtracting(playerId, true);
    // La Fuente usa primero exactamente su estado animado de extracción normal.
    // Se deja tiempo suficiente para que los círculos/agua mágica sean legibles.
    await sleep(REALTIME_FOUNTAIN_PRELUDE_MS);
    const droplets = [];
    for (let i = 0; i < REALTIME_FOUNTAIN_DROPLET_COUNT; i += 1) {
      droplets.push(animateRealtimeFountainDropletToCaster(playerId, elementId, sourcePoint, casterPoint, i));
      if (i < REALTIME_FOUNTAIN_DROPLET_COUNT - 1) await sleep(REALTIME_FOUNTAIN_DROPLET_STAGGER_MS);
    }
    await Promise.all(droplets);
    const casterViewport = viewportPointFromBoardLocal(casterPoint);
    createElementBurstAtViewport(casterViewport.x, casterViewport.y, getElementColorById(elementId, getPlayerElementColor(playerId)), { kind: 'resource-land', count: 9, duration: 480 });
    await sleep(REALTIME_FOUNTAIN_CASTER_HOLD_MS);
    // Solo AQUÍ viaja el elemento al stock; animateExtractionOrb lo añade al final.
    await animateExtractionOrb(playerId, casterPoint, 0, elementId);
  }).catch(error => {
    console.error('[RT extraction FX] No se pudo completar la animación Fuente → Kaster → HUD:', error);
    // Fallback de seguridad: el recurso no se pierde si falla únicamente el FX.
    createRealtimeResourceToken(playerId, elementId, source);
    renderResources();
    renderEnemyMiniHud();
  }).finally(() => {
    changeRealtimePendingResourceAnimationCount(playerId, elementId, -1);
    setFountainExtracting(playerId, false);
  });
  queues[playerId] = task;
  return task;
}

function grantRealtimeResourceToken(playerId, elementId, source = 'refill', options = {}) {
  const animate = options?.animate !== false;
  if (animate && isRealtimePlayStyle()) {
    enqueueRealtimeFountainExtraction(playerId, elementId, source);
    return true;
  }
  return Boolean(createRealtimeResourceToken(playerId, elementId, source));
}

function initializeRealtimeResourceSystem() {
  const system = ensureRealtimeResourceSystemState();
  system.initialized = true;
  system.distributionMode = 'automatic-round-robin-30';
  system.totalCapacity = REALTIME_RESOURCE_TOTAL_CAPACITY;
  system.initialCapacity = REALTIME_RESOURCE_INITIAL_TOTAL;
  system.refillSeconds = getRealtimeTimingValue('resourceRefillSeconds');
  system.growthStartSeconds = getRealtimeTimingValue('resourceGrowthMinSeconds');
  system.growthEndSeconds = getRealtimeTimingValue('resourceGrowthMaxSeconds');
  system.growthCurveExponent = REALTIME_RESOURCE_GROWTH_CURVE_EXPONENT;
  system.timingMode = 'global-round-robin-progressive-capacity';
  delete system.growthSeconds;
  system.maxCapacity = REALTIME_RESOURCE_TOTAL_CAPACITY;
  system.stealAccelerationSeconds = REALTIME_RESOURCE_STEAL_ACCELERATION_SECONDS;
  system.players = {};

  [1, 2].forEach(playerId => {
    const player = state.players?.[playerId];
    if (!player) return;
    const rtPlayer = getRealtimeResourcePlayerState(playerId, true);
    rtPlayer.elementIds = getRealtimePlayerDomainIds(playerId);
    rtPlayer.primaryElementId = getPlayerDomainId(playerId) || player.elementId || rtPlayer.elementIds[0] || 'oscuridad';
    rtPlayer.totalCapacity = REALTIME_RESOURCE_TOTAL_CAPACITY;
    rtPlayer.perElementMax = getRealtimeResourceMaxCapacityForDomainCount(rtPlayer.elementIds.length || 1);
    rtPlayer.tracks = {};
    rtPlayer.capacityRotationIndex = 0;
    rtPlayer.refillRotationIndex = 0;
    rtPlayer.refillIntervalSeconds = isTestMatchActive()
      ? 0.25
      : Math.max(.25, Number(system.refillSeconds || REALTIME_RESOURCE_REFILL_SECONDS));
    rtPlayer.nextRefillAt = rtPlayer.refillIntervalSeconds;
    rtPlayer.nextCapacityGrowthAt = 0;
    rtPlayer.generatedSerial = 0;

    player.elementDistribution = Object.fromEntries(rtPlayer.elementIds.map(id => [id, rtPlayer.perElementMax]));
    player.elementDistributionConfigured = true;
    player.resources = [];

    rtPlayer.elementIds.forEach(elementId => {
      rtPlayer.tracks[elementId] = {
        elementId,
        capacity: 0,
        maxCapacity: rtPlayer.perElementMax,
        nextRefillAt: 0,
        nextGrowthAt: 0,
        growthIntervalSeconds: 0,
        lastRefillAt: 0,
        lastGrowthAt: 0,
        timingMode: 'global-round-robin-progressive-capacity',
      };
    });

    // En modo de prueba RT ambos Kasters arrancan con toda la Fuente disponible.
    // En partidas normales se conserva la apertura homogénea de 2 elementos.
    const openingTotal = isTestMatchActive()
      ? Math.min(REALTIME_RESOURCE_TOTAL_CAPACITY, rtPlayer.perElementMax * Math.max(1, rtPlayer.elementIds.length))
      : Math.min(REALTIME_RESOURCE_INITIAL_TOTAL, REALTIME_RESOURCE_TOTAL_CAPACITY);
    for (let openingIndex = 0; openingIndex < openingTotal; openingIndex += 1) {
      const elementId = rtPlayer.elementIds[openingIndex % Math.max(1, rtPlayer.elementIds.length)];
      const track = rtPlayer.tracks[elementId];
      if (!track || Number(track.capacity || 0) >= Number(track.maxCapacity || 0)) continue;
      track.capacity = Number(track.capacity || 0) + 1;
      createRealtimeResourceToken(playerId, elementId, isTestMatchActive() ? 'test-opening' : 'opening');
    }
    rtPlayer.capacityRotationIndex = openingTotal % Math.max(1, rtPlayer.elementIds.length || 1);

    scheduleNextRealtimePlayerCapacityGrowth(rtPlayer, 0);
  });
  return system;
}

function addRealtimeResourceIfMissing(playerId, track, source = 'refill') {
  if (!track) return false;
  const available = countPlayerResourcesByElement(playerId, track.elementId)
    + getRealtimePendingResourceAnimationCount(playerId, track.elementId);
  if (available >= Number(track.capacity || 0)) return false;
  // El modo de prueba prioriza disponibilidad inmediata: 4 recursos/s por reloj.
  // Se ve el gasto real, pero no queda bloqueado detrás de la cola larga de FX.
  if (isTestMatchActive() && isRealtimePlayStyle()) {
    return Boolean(createRealtimeResourceToken(playerId, track.elementId, 'test-refill'));
  }
  return Boolean(grantRealtimeResourceToken(playerId, track.elementId, source, { animate: true }));
}

function getRealtimePlayerTotalCapacity(rtPlayer) {
  return (rtPlayer?.elementIds || []).reduce((sum, elementId) => {
    return sum + Math.max(0, Number(rtPlayer?.tracks?.[elementId]?.capacity || 0));
  }, 0);
}

function getRealtimePlayerTotalCapacityMax(rtPlayer) {
  return (rtPlayer?.elementIds || []).reduce((sum, elementId) => {
    return sum + Math.max(0, Number(rtPlayer?.tracks?.[elementId]?.maxCapacity || 0));
  }, 0) || REALTIME_RESOURCE_TOTAL_CAPACITY;
}

function getRealtimePlayerGrowthIntervalSeconds(rtPlayer, totalCapacityOverride = null) {
  const domainCount = Math.max(1, Number(rtPlayer?.elementIds?.length || 1));
  const initialTotal = Math.min(REALTIME_RESOURCE_INITIAL_TOTAL, getRealtimePlayerTotalCapacityMax(rtPlayer));
  const totalCapacity = totalCapacityOverride == null
    ? getRealtimePlayerTotalCapacity(rtPlayer)
    : Math.max(0, Number(totalCapacityOverride || 0));
  const totalMax = Math.max(initialTotal + 1, getRealtimePlayerTotalCapacityMax(rtPlayer));
  if (totalCapacity >= totalMax) return 0;
  const steps = Math.max(1, totalMax - initialTotal);
  const completed = Math.max(0, totalCapacity - initialTotal);
  const progress = steps <= 1 ? 1 : Math.max(0, Math.min(1, completed / Math.max(1, steps - 1)));
  const eased = Math.pow(progress, REALTIME_RESOURCE_GROWTH_CURVE_EXPONENT);
  const minSeconds = Math.max(.25, Number(getRealtimeTimingValue('resourceGrowthMinSeconds') || REALTIME_RESOURCE_GROWTH_START_SECONDS));
  const maxSeconds = Math.max(minSeconds, Number(getRealtimeTimingValue('resourceGrowthMaxSeconds') || REALTIME_RESOURCE_GROWTH_END_SECONDS));
  return Number((minSeconds + ((maxSeconds - minSeconds) * eased)).toFixed(1));
}

function scheduleNextRealtimePlayerCapacityGrowth(rtPlayer, fromSecond) {
  if (!rtPlayer) return 0;
  const totalCapacity = getRealtimePlayerTotalCapacity(rtPlayer);
  const totalMax = getRealtimePlayerTotalCapacityMax(rtPlayer);
  if (totalCapacity >= totalMax) {
    rtPlayer.nextCapacityGrowthAt = 0;
    return 0;
  }
  const interval = getRealtimePlayerGrowthIntervalSeconds(rtPlayer, totalCapacity);
  rtPlayer.nextCapacityGrowthAt = Math.max(0, Number(fromSecond || 0)) + interval;
  return rtPlayer.nextCapacityGrowthAt;
}

function ensureRealtimeRoundRobinPlayerState(rtPlayer, nowSecond = 0) {
  if (!rtPlayer) return null;
  const ids = Array.isArray(rtPlayer.elementIds) ? rtPlayer.elementIds : [];
  const count = Math.max(1, ids.length || 1);
  if (!Number.isFinite(Number(rtPlayer.capacityRotationIndex))) rtPlayer.capacityRotationIndex = 0;
  if (!Number.isFinite(Number(rtPlayer.refillRotationIndex))) rtPlayer.refillRotationIndex = 0;
  rtPlayer.capacityRotationIndex = ((Math.floor(Number(rtPlayer.capacityRotationIndex) || 0) % count) + count) % count;
  rtPlayer.refillRotationIndex = ((Math.floor(Number(rtPlayer.refillRotationIndex) || 0) % count) + count) % count;
  rtPlayer.refillIntervalSeconds = Math.max(.25, Number(rtPlayer.refillIntervalSeconds || getRealtimeTimingValue('resourceRefillSeconds') || REALTIME_RESOURCE_REFILL_SECONDS));
  if (!(Number(rtPlayer.nextRefillAt) > 0)) rtPlayer.nextRefillAt = Math.max(0, Number(nowSecond || 0)) + rtPlayer.refillIntervalSeconds;
  if (!(Number(rtPlayer.nextCapacityGrowthAt) > 0) && getRealtimePlayerTotalCapacity(rtPlayer) < getRealtimePlayerTotalCapacityMax(rtPlayer)) {
    scheduleNextRealtimePlayerCapacityGrowth(rtPlayer, nowSecond);
  }
  return rtPlayer;
}

function getRealtimeRoundRobinCandidates(playerId, rtPlayer, mode = 'refill') {
  const ids = Array.isArray(rtPlayer?.elementIds) ? rtPlayer.elementIds : [];
  if (!ids.length) return [];
  const cursorKey = mode === 'growth' ? 'capacityRotationIndex' : 'refillRotationIndex';
  const start = ((Math.floor(Number(rtPlayer[cursorKey]) || 0) % ids.length) + ids.length) % ids.length;
  const ordered = [];
  for (let offset = 0; offset < ids.length; offset += 1) {
    const index = (start + offset) % ids.length;
    const elementId = ids[index];
    const track = rtPlayer.tracks?.[elementId];
    if (!track) continue;
    const available = countPlayerResourcesByElement(playerId, elementId)
      + getRealtimePendingResourceAnimationCount(playerId, elementId);
    const capacity = Math.max(0, Number(track.capacity || 0));
    const maxCapacity = Math.max(capacity, Number(track.maxCapacity || 0));
    const eligible = mode === 'growth' ? capacity < maxCapacity : available < capacity;
    if (eligible) ordered.push({ elementId, index, track, available, capacity, maxCapacity });
  }
  return ordered;
}

function processRealtimeGlobalCapacityGrowthAt(rtPlayer, playerId, deadline) {
  const ids = Array.isArray(rtPlayer?.elementIds) ? rtPlayer.elementIds : [];
  if (!ids.length) return false;
  const candidates = getRealtimeRoundRobinCandidates(playerId, rtPlayer, 'growth');
  if (!candidates.length) {
    rtPlayer.nextCapacityGrowthAt = 0;
    return false;
  }
  const chosen = candidates[0];
  chosen.track.capacity = Math.min(chosen.maxCapacity, chosen.capacity + 1);
  chosen.track.lastGrowthAt = deadline;
  rtPlayer.capacityRotationIndex = (chosen.index + 1) % ids.length;

  // El crecimiento crea el nuevo elemento inmediatamente. La recarga de huecos
  // consumidos sigue siendo un reloj aparte de 10 s (o el valor configurado).
  grantRealtimeResourceToken(playerId, chosen.elementId, 'growth', { animate: true });
  rtPlayer.generatedSerial = Math.max(0, Number(rtPlayer.generatedSerial || 0)) + 1;
  scheduleNextRealtimePlayerCapacityGrowth(rtPlayer, deadline);
  return true;
}

function processRealtimeGlobalRefillAt(rtPlayer, playerId, deadline) {
  const ids = Array.isArray(rtPlayer?.elementIds) ? rtPlayer.elementIds : [];
  if (!ids.length) return false;
  const candidates = getRealtimeRoundRobinCandidates(playerId, rtPlayer, 'refill');
  let changed = false;
  if (candidates.length) {
    const chosen = candidates[0];
    if (addRealtimeResourceIfMissing(playerId, chosen.track, 'refill')) {
      chosen.track.lastRefillAt = deadline;
      rtPlayer.refillRotationIndex = (chosen.index + 1) % ids.length;
      changed = true;
    }
  }
  rtPlayer.nextRefillAt = deadline + Math.max(.25, Number(rtPlayer.refillIntervalSeconds || REALTIME_RESOURCE_REFILL_SECONDS));
  return changed;
}

function processRealtimeResourceSecond(second) {
  if (!isRealtimePlayStyle() || !state?.realtime?.active || isRealtimeTempoPaused()) return false;
  const system = ensureRealtimeResourceSystemState();
  if (!system.initialized) initializeRealtimeResourceSystem();
  const nowSecond = Math.max(0, Number(second || 0));
  let changed = false;

  Object.values(system.players || {}).forEach(rtPlayer => {
    const playerId = Number(rtPlayer?.playerId || 0);
    if (!playerId || !state.players?.[playerId]) return;
    ensureRealtimeRoundRobinPlayerState(rtPlayer, nowSecond);

    let guard = 0;
    while (guard < 512) {
      guard += 1;
      const growthAt = Number(rtPlayer.nextCapacityGrowthAt || 0) > 0 ? Number(rtPlayer.nextCapacityGrowthAt) : Infinity;
      const refillAt = Number(rtPlayer.nextRefillAt || 0) > 0 ? Number(rtPlayer.nextRefillAt) : Infinity;
      const nextEventAt = Math.min(growthAt, refillAt);
      if (!Number.isFinite(nextEventAt) || nextEventAt > nowSecond + 1e-6) break;

      // Si coinciden, primero nace la nueva capacidad/recurso y luego se atiende
      // una posible recarga consumida. Son dos mecanismos distintos.
      if (growthAt <= refillAt + 1e-6) {
        if (processRealtimeGlobalCapacityGrowthAt(rtPlayer, playerId, growthAt)) changed = true;
      }
      if (refillAt <= growthAt + 1e-6) {
        if (processRealtimeGlobalRefillAt(rtPlayer, playerId, refillAt)) changed = true;
      }
    }
  });

  if (changed) renderAll('realtime-resource-clock');
  return changed;
}

function getRealtimeResourceEstimatedGrowthDeadline(playerId, elementId) {
  const rtPlayer = getRealtimeResourcePlayerState(playerId, false);
  if (!rtPlayer) return 0;
  ensureRealtimeRoundRobinPlayerState(rtPlayer, getRealtimeResourceClockSecond());
  const candidates = getRealtimeRoundRobinCandidates(playerId, rtPlayer, 'growth');
  const position = candidates.findIndex(entry => entry.elementId === elementId);
  if (position < 0) return 0;
  let deadline = Number(rtPlayer.nextCapacityGrowthAt || 0);
  let hypotheticalTotal = getRealtimePlayerTotalCapacity(rtPlayer);
  for (let step = 0; step < position; step += 1) {
    hypotheticalTotal += 1;
    deadline += getRealtimePlayerGrowthIntervalSeconds(rtPlayer, hypotheticalTotal);
  }
  return deadline;
}

function getRealtimeResourceEstimatedRefillDeadline(playerId, elementId) {
  const rtPlayer = getRealtimeResourcePlayerState(playerId, false);
  if (!rtPlayer) return 0;
  ensureRealtimeRoundRobinPlayerState(rtPlayer, getRealtimeResourceClockSecond());
  const candidates = getRealtimeRoundRobinCandidates(playerId, rtPlayer, 'refill');
  const position = candidates.findIndex(entry => entry.elementId === elementId);
  if (position < 0) return 0;
  const interval = Math.max(.25, Number(rtPlayer.refillIntervalSeconds || REALTIME_RESOURCE_REFILL_SECONDS));
  return Number(rtPlayer.nextRefillAt || 0) + (position * interval);
}

function getRealtimeResourceCountdown(playerId, elementId, type = 'refill') {
  const track = getRealtimeResourceTrack(playerId, elementId);
  if (!track) return null;
  const nowSecond = getRealtimeResourceClockSecond();
  const deadline = type === 'growth'
    ? getRealtimeResourceEstimatedGrowthDeadline(playerId, elementId)
    : getRealtimeResourceEstimatedRefillDeadline(playerId, elementId);
  if (!deadline) return null;
  return Math.max(0, Math.ceil(deadline - nowSecond));
}

function accelerateRealtimeResourceTimers(playerId, preferredElementId = null, seconds = REALTIME_RESOURCE_STEAL_ACCELERATION_SECONDS) {
  if (!isRealtimePlayStyle()) return false;
  const rtPlayer = getRealtimeResourcePlayerState(playerId, false);
  if (!rtPlayer) return false;
  const amount = Math.max(0, Number(seconds || 0));
  if (amount <= 0) return false;
  const nowSecond = getRealtimeResourceClockSecond();
  ensureRealtimeRoundRobinPlayerState(rtPlayer, nowSecond);

  // Ambos relojes son globales por jugador. Nunca se acelera un color aislado.
  if (Number(rtPlayer.nextRefillAt || 0) > 0) {
    rtPlayer.nextRefillAt = Math.max(nowSecond, Number(rtPlayer.nextRefillAt) - amount);
  }
  if (Number(rtPlayer.nextCapacityGrowthAt || 0) > 0) {
    rtPlayer.nextCapacityGrowthAt = Math.max(nowSecond, Number(rtPlayer.nextCapacityGrowthAt) - amount);
  }
  processRealtimeResourceSecond(nowSecond);
  renderRealtimeStage1Status();
  return true;
}

function buildRealtimeRandomCostSelection(playerId, card) {
  const needed = getRandomCostNeeded(card);
  if (needed <= 0) return null;
  const player = state.players?.[playerId];
  const rtPlayer = getRealtimeResourcePlayerState(playerId, false);
  if (!player) return null;
  const pool = removeSpecificCostFromPool(player.resources, card, playerId);
  const counts = pool.reduce((acc, resource) => {
    acc[resource.id] = (acc[resource.id] || 0) + 1;
    return acc;
  }, {});
  const order = rtPlayer?.elementIds?.length ? rtPlayer.elementIds : getRealtimePlayerDomainIds(playerId);
  const primary = rtPlayer?.primaryElementId || getPlayerDomainId(playerId) || player.elementId;
  const ids = Object.keys(counts).filter(id => counts[id] > 0);
  ids.sort((a, b) => {
    // El dominio principal se conserva todo lo posible para costos obligatorios futuros.
    if (a === primary && b !== primary) return 1;
    if (b === primary && a !== primary) return -1;
    if (counts[a] !== counts[b]) return counts[b] - counts[a];
    const ai = order.indexOf(a); const bi = order.indexOf(b);
    return (ai < 0 ? 999 : ai) - (bi < 0 ? 999 : bi);
  });
  let remaining = needed;
  const selection = {};
  ids.forEach(elementId => {
    if (remaining <= 0) return;
    const take = Math.min(Number(counts[elementId] || 0), remaining);
    if (take > 0) {
      selection[elementId] = take;
      remaining -= take;
    }
  });
  return remaining === 0 ? selection : null;
}



