function getDefaultInvocationPowerAutomationMode(playerId = LOCAL_PLAYER_ID) {
  if (Number(playerId) !== Number(LOCAL_PLAYER_ID)) return INVOCATION_POWER_AUTOMATION_MODES.AUTO;
  return isRealtimePlayStyle() ? INVOCATION_POWER_AUTOMATION_MODES.AUTO : INVOCATION_POWER_AUTOMATION_MODES.MANUAL;
}
function normalizeInvocationPowerAutomationMode(value, playerId = LOCAL_PLAYER_ID) {
  const mode = String(value || '').toLowerCase();
  return ['auto', 'manual'].includes(mode) ? mode : getDefaultInvocationPowerAutomationMode(playerId);
}
function unitHasConfigurableActivePower(playerId, unit) {
  if (!unit || unit.status === 'restoring') return false;
  if (CONFIGURABLE_INVOCATION_POWER_CARD_IDS.has(String(unit.cardId || ''))) return true;
  const power = getPowerDefinitionForUnit(playerId, unit);
  if (power?.id && CONFIGURABLE_INVOCATION_POWER_IDS.has(String(power.id))) return true;
  return Boolean(isKishimotoUnit?.(unit) || isTakedaUnit?.(unit));
}
function getInvocationPowerAutomationMode(playerId, unit) {
  if (!unit) return getDefaultInvocationPowerAutomationMode(playerId);
  // v9.49 · En una partida RT local el segundo bando es IA, no otro humano.
  // Un ajuste MANUAL guardado en la copia del Spellbook no puede apagar sus
  // poderes activos. En PvP online conservamos el modo sincronizado del remoto.
  const localAiControlled = isRealtimePlayStyle()
    && Number(playerId) !== Number(LOCAL_PLAYER_ID)
    && !isOnlineMatchActive();
  if (localAiControlled) {
    if (unit.powerAutomationMode !== INVOCATION_POWER_AUTOMATION_MODES.AUTO) {
      unit.powerAutomationMode = INVOCATION_POWER_AUTOMATION_MODES.AUTO;
      unit.realtimePowerArmed = false;
    }
    return INVOCATION_POWER_AUTOMATION_MODES.AUTO;
  }
  const mode = normalizeInvocationPowerAutomationMode(unit.powerAutomationMode, playerId);
  if (unit.powerAutomationMode !== mode) unit.powerAutomationMode = mode;
  return mode;
}
function setInvocationPowerAutomationMode(playerId, unitId, mode, options = {}) {
  const unit = getUnitById(Number(playerId), unitId);
  if (!unit || !unitHasConfigurableActivePower(playerId, unit)) return false;
  const resolved = normalizeInvocationPowerAutomationMode(mode, playerId);
  if (isOnlineMatchActive() && isRealtimePlayStyle() && state?.realtime?.active
      && Number(playerId) === Number(LOCAL_PLAYER_ID) && !isRealtimeOnlineAuthority()
      && options.fromOnlineCommand !== true) {
    void window.ROK_ONLINE_PVP?.sendRealtimeCommand?.('power-automation', { unitId: String(unitId), mode: resolved });
    return true;
  }
  unit.powerAutomationMode = resolved;
  if (resolved === 'auto') unit.realtimePowerArmed = false;
  if (isOnlineMatchActive() && isRealtimeOnlineAuthority()) {
    try { markOnlineStateDirty(`rt-power-automation:p${playerId}:${unit.id}:${resolved}`); } catch (_) {}
  }
  renderRealtimeCombatModePanel();
  renderSelectedUnitCommandPanel();
  return true;
}
function setInvocationRealtimePowerArmed(playerId, unitId, armed = true, options = {}) {
  const unit = getUnitById(Number(playerId), unitId);
  if (!unit || !isRealtimePlayStyle() || !unitHasConfigurableActivePower(playerId, unit)) return false;
  if (getInvocationPowerAutomationMode(playerId, unit) !== 'manual') return false;
  if (isOnlineMatchActive() && state?.realtime?.active
      && Number(playerId) === Number(LOCAL_PLAYER_ID) && !isRealtimeOnlineAuthority()
      && options.fromOnlineCommand !== true) {
    void window.ROK_ONLINE_PVP?.sendRealtimeCommand?.('power-arm', { unitId: String(unitId), armed: Boolean(armed) });
    return true;
  }
  unit.realtimePowerArmed = Boolean(armed);
  if (isOnlineMatchActive() && isRealtimeOnlineAuthority()) {
    try { markOnlineStateDirty(`rt-power-arm:p${playerId}:${unit.id}:${unit.realtimePowerArmed ? 1 : 0}`); } catch (_) {}
  }
  renderRealtimeCombatModePanel();
  return true;
}
function getNearestEnemyDistanceForInvocation(playerId, unit) {
  const enemy = state.players?.[getOpponentId(playerId)];
  if (!enemy || !unit) return Infinity;
  const positions = [];
  if (enemy.caster) positions.push(enemy.caster);
  for (const u of enemy.units || []) if (u && u.status !== 'restoring' && Number(u.hp ?? 0) > 0) positions.push(u);
  for (const g of enemy.guardians || []) if (g && g.active !== false && !g.destroying && Number(g.resistance ?? 0) > 0) positions.push(g);
  if (!positions.length) return Infinity;
  return Math.min(...positions.map(p => ringDistance(unit.row, unit.col, p.row, p.col)));
}
function getInvocationPowerReadinessState(playerId, unit) {
  if (!unitHasConfigurableActivePower(playerId, unit)) return { state: 'none', ready: false, near: false, armed: false, actions: [] };
  const actions = getVoluntaryPowerActionDescriptorsNow(playerId, unit, { shortLabel: true });
  const armed = isRealtimePlayStyle() && getInvocationPowerAutomationMode(playerId, unit) === 'manual' && Boolean(unit.realtimePowerArmed);
  if (actions.length) return { state: armed ? 'armed-ready' : 'ready', ready: true, near: true, armed, actions };
  const card = CARD_LIBRARY?.[unit.cardId];
  const power = getPowerDefinitionForUnit(playerId, unit) || {};
  const attack = getEffectiveAttackProfile?.(card, unit, playerId) || getAttackProfile?.(card) || {};
  const range = Math.max(0, Number(power.throwRange ?? 0), Number(power.range ?? 0), Number(power.radius ?? 0), Number(attack.range ?? 0));
  const distance = getNearestEnemyDistanceForInvocation(playerId, unit);
  const near = Number.isFinite(distance) && distance <= Math.max(1, range) + 3;
  return { state: armed ? 'armed' : (near ? 'near' : 'idle'), ready: false, near, armed, actions: [], nearestDistance: distance };
}

function ensureRealtimeCombatModeSystemState() {
  if (!state.realtime || typeof state.realtime !== 'object') {
    state.realtime = { active: false, startedAt: 0, elapsedSeconds: 0, tickSerial: 0, phaseEquivalentSeconds: 1 };
  }
  if (!state.realtime.combatModeSystem || typeof state.realtime.combatModeSystem !== 'object') {
    state.realtime.combatModeSystem = {
      initialized: false,
      selectedPlayerId: Number(LOCAL_PLAYER_ID || 1),
      selectedUnitId: '',
      selectedSpawnId: '',
      changes: 0,
    };
  }
  return state.realtime.combatModeSystem;
}

function initializeRealtimeCombatModeSystem() {
  const system = ensureRealtimeCombatModeSystemState();
  system.initialized = true;
  system.selectedPlayerId = Number(LOCAL_PLAYER_ID || 1);
  system.selectedUnitId = '';
  system.selectedSpawnId = '';
  system.changes = 0;
  realtimeStage3Runtime.combatPowerCache.clear();
  for (const playerId of [1, 2]) {
    (state.players?.[playerId]?.units || []).forEach(unit => normalizeRealtimeCombatModeForUnit(playerId, unit));
  }
  return system;
}

function getRealtimeCombatModeQualityIds(unit) {
  const card = CARD_LIBRARY?.[unit?.cardId];
  return [...new Set((Array.isArray(card?.qualities) ? card.qualities : []).filter(Boolean).map(id => String(id)) )];
}

function normalizeRealtimeCombatModeId(modeId = '') {
  const raw = String(modeId || '').trim();
  return REALTIME_COMBAT_MODE_LEGACY_ALIASES[raw] || raw;
}


function isRealtimeRangedInvocationForSiege(playerId, unit) {
  const card = CARD_LIBRARY?.[unit?.cardId];
  if (!card || getCardTypeId(card) !== 'invocation') return false;
  let profile = null;
  try { profile = getEffectiveAttackProfile(card, unit, playerId); } catch (_) {}
  profile = profile || getAttackProfile(card);
  const mode = String(profile?.combatMode || profile?.type || '').toLowerCase();
  const range = Math.max(0, Number(profile?.range ?? 0));
  return ['distance', 'range', 'ranged'].includes(mode) || range > 1;
}

function getRealtimeCombatModeAllowedIds(playerId, unit) {
  if (!unit) return [];

  const cardRule = REALTIME_COMBAT_MODE_CARD_RULES[String(unit.cardId || '')] || null;
  if (cardRule?.noCombatModes === true) return [];
  if (cardRule && Array.isArray(cardRule.allowed) && cardRule.allowed.length) {
    const curatedSet = new Set(
      cardRule.allowed
        .map(normalizeRealtimeCombatModeId)
        .filter(modeId => Boolean(REALTIME_COMBAT_MODE_DB[modeId]))
    );
    if (isRealtimeRangedInvocationForSiege(playerId, unit)) curatedSet.add('siege');
    const curated = [...curatedSet];
    if (curated.length) {
      return REALTIME_COMBAT_MODE_ORDER.filter(modeId => curated.includes(modeId));
    }
  }

  const allowed = new Set();
  const qualityIds = getRealtimeCombatModeQualityIds(unit);
  qualityIds.forEach(qualityId => {
    (REALTIME_COMBAT_MODE_QUALITY_RULES[qualityId] || []).forEach(modeId => allowed.add(normalizeRealtimeCombatModeId(modeId)));
  });

  const card = CARD_LIBRARY?.[unit.cardId];
  const baseMovement = String(card?.movementType || 'basic');
  const effectiveMovement = String(getEffectiveMovementTypeForUnit?.(playerId, unit) || baseMovement || 'basic');
  (REALTIME_COMBAT_MODE_MOVEMENT_RULES[baseMovement] || []).forEach(modeId => allowed.add(normalizeRealtimeCombatModeId(modeId)));
  (REALTIME_COMBAT_MODE_MOVEMENT_RULES[effectiveMovement] || []).forEach(modeId => allowed.add(normalizeRealtimeCombatModeId(modeId)));

  if (unitHasAbility?.(unit, 'vigilia') || unitHasAbility?.(unit, 'stalk')) allowed.add('defensive');
  if (isRealtimeRangedInvocationForSiege(playerId, unit)) allowed.add('siege');

  if (!allowed.size) allowed.add('offensive');
  return REALTIME_COMBAT_MODE_ORDER.filter(modeId => allowed.has(modeId));
}

function getDefaultRealtimeCombatModeId(playerId, unit, allowedIds = null) {
  const explicitAllowed = Array.isArray(allowedIds) ? allowedIds : null;
  const allowed = explicitAllowed ?? getRealtimeCombatModeAllowedIds(playerId, unit);
  if (!allowed.length) return '';
  const qualityIds = getRealtimeCombatModeQualityIds(unit);
  const movement = String(CARD_LIBRARY?.[unit?.cardId]?.movementType || 'basic');
  const cardRule = REALTIME_COMBAT_MODE_CARD_RULES[String(unit?.cardId || '')] || null;
  if (cardRule?.default && allowed.includes(cardRule.default)) return cardRule.default;

  if ((unitHasAbility?.(unit, 'vigilia') || ['sentinel', 'healer', 'extractor'].some(id => qualityIds.includes(id)) || ['retreat', 'lateral'].includes(movement)) && allowed.includes('defensive')) {
    return 'defensive';
  }
  if (['assassin', 'stalker', 'bandit', 'vampire'].some(id => qualityIds.includes(id)) && allowed.includes('assassination')) return 'assassination';
  if (allowed.includes('offensive')) return 'offensive';
  if (allowed.includes('hunt')) return 'hunt';
  if (allowed.includes('assassination')) return 'assassination';
  return allowed[0] || 'offensive';
}

function normalizeRealtimeCombatModeForUnit(playerId, unit, preferredModeId = '') {
  if (!unit) return '';
  const allowed = getRealtimeCombatModeAllowedIds(playerId, unit);
  if (!allowed.length) {
    unit.realtimeCombatMode = '';
    return '';
  }
  const preferred = normalizeRealtimeCombatModeId(preferredModeId || unit.realtimeCombatMode || '');
  const resolved = allowed.includes(preferred)
    ? preferred
    : getDefaultRealtimeCombatModeId(playerId, unit, allowed);
  unit.realtimeCombatMode = resolved;
  return resolved;
}

function getRealtimeCombatModeProfileForUnit(playerId, unit) {
  if (!unit) return null;
  const allowedIds = getRealtimeCombatModeAllowedIds(playerId, unit);
  const activeId = normalizeRealtimeCombatModeForUnit(playerId, unit, unit.realtimeCombatMode);
  return {
    activeId,
    active: activeId ? (REALTIME_COMBAT_MODE_DB[activeId] || null) : null,
    allowedIds,
    allowed: allowedIds.map(id => REALTIME_COMBAT_MODE_DB[id]).filter(Boolean),
  };
}



function auditKiaraTacticalRuntimeInvariants() {
  const issues = [];
  const warnings = [];
  const details = {
    forcedLimits: {},
    nexusCastReservations: [],
    farolPortals: [],
    seyran: [],
  };

  // Etapa 1 · Los dos Hechizos nuevos deben conservar Límites forzados.
  for (const cardId of ['spellKiaraNo', 'spellKiaraRegresa']) {
    const card = CARD_LIBRARY?.[cardId];
    const traits = Array.isArray(card?.traits) ? card.traits.map(String) : [];
    const hasForcedLimits = traits.includes(SPELLBOOK_FORCED_LIMITS_TRAIT_ID);
    details.forcedLimits[cardId] = { exists: Boolean(card), hasForcedLimits, traits };
    if (!card) issues.push({ code: 'kiara-card-missing', cardId });
    else if (!hasForcedLimits) issues.push({ code: 'kiara-forced-limits-missing', cardId });
  }

  // Etapa 1 · Todo Nexo/respawn debe reservar su casilla para Kasteo, sin
  // importar a qué jugador pertenezca. La locomoción RT no se audita aquí.
  for (const ownerId of [1, 2]) {
    for (const marker of state.players?.[ownerId]?.spawnMarkers || []) {
      if (!marker || marker.row == null || marker.col == null) continue;
      const row = Number(marker.row);
      const col = Number(marker.col);
      const blockedForP1 = isCastPlacementBlockedForPlayer(row, col, 1);
      const blockedForP2 = isCastPlacementBlockedForPlayer(row, col, 2);
      details.nexusCastReservations.push({ ownerId, markerId: String(marker.id || ''), row, col, blockedForP1, blockedForP2 });
      if (!blockedForP1 || !blockedForP2) {
        issues.push({ code: 'nexus-not-reserved-for-cast', ownerId, markerId: String(marker.id || ''), row, col, blockedForP1, blockedForP2 });
      }
    }
  }

  // Etapa 2 · Los portales existentes deben conservar una geometría coherente.
  for (const portal of state.farolPortals || []) {
    if (!portal) continue;
    const source = getUnitById(Number(portal.playerId), portal.sourceUnitId);
    const originValid = portal.originRow != null && portal.originCol != null && isInside(Number(portal.originRow), Number(portal.originCol));
    const destinationRequired = String(portal.stage || '') === 'complete';
    const destinationValid = !destinationRequired || (portal.destinationRow != null && portal.destinationCol != null && isInside(Number(portal.destinationRow), Number(portal.destinationCol)));
    const sameCell = destinationRequired
      && Number(portal.originRow) === Number(portal.destinationRow)
      && Number(portal.originCol) === Number(portal.destinationCol);
    const originOnNexus = originValid && hasSpawnMarkerAtForPlayer(Number(portal.originRow), Number(portal.originCol), null);
    const destinationOnNexus = destinationRequired && destinationValid && hasSpawnMarkerAtForPlayer(Number(portal.destinationRow), Number(portal.destinationCol), null);
    const snapshot = {
      key: String(portal.key || ''),
      playerId: Number(portal.playerId || 0),
      sourceUnitId: String(portal.sourceUnitId || ''),
      sourcePresent: Boolean(source),
      stage: String(portal.stage || ''),
      origin: originValid ? { row: Number(portal.originRow), col: Number(portal.originCol) } : null,
      destination: destinationRequired && destinationValid ? { row: Number(portal.destinationRow), col: Number(portal.destinationCol) } : null,
      originOnNexus,
      destinationOnNexus,
      sameCell,
    };
    details.farolPortals.push(snapshot);
    if (!originValid) issues.push({ code: 'farol-origin-invalid', key: snapshot.key });
    if (!destinationValid) issues.push({ code: 'farol-destination-invalid', key: snapshot.key });
    if (sameCell) issues.push({ code: 'farol-origin-destination-collision', key: snapshot.key });
    if (originOnNexus || destinationOnNexus) issues.push({ code: 'farol-on-nexus', key: snapshot.key, originOnNexus, destinationOnNexus });
    if (!source && !['throwing'].includes(String(portal.stage || ''))) warnings.push({ code: 'farol-source-missing', key: snapshot.key });
  }

  // Etapa 3 · Para cada Seyran activo dejamos constancia de cuántos aliados y
  // rivales son candidatos reales y de cuántos tienen al menos una operación
  // legal. Esto hace visible en telemetría cualquier regresión del selector.
  for (const playerId of [1, 2]) {
    for (const unit of state.players?.[playerId]?.units || []) {
      if (!isSeyranUnit(unit) || unit.status === 'restoring' || Number(unit.hp ?? 0) <= 0) continue;
      const targets = getSeyranDistortionTargets(playerId, unit);
      const targetSnapshots = targets.map(target => {
        const ownerId = Number(target.owner || getOwnerPlayerIdForUnit?.(target) || 0);
        const pull = computeSeyranDistortionDestination(ownerId, unit, target, 'pull');
        const push = computeSeyranDistortionDestination(ownerId, unit, target, 'push');
        return {
          ownerId,
          unitId: String(target.id || ''),
          relation: ownerId === Number(playerId) ? 'ally' : 'enemy',
          pull: pull ? { row: pull.row, col: pull.col, moved: pull.moved } : null,
          push: push ? { row: push.row, col: push.col, moved: push.moved } : null,
        };
      });
      const allies = targetSnapshots.filter(entry => entry.relation === 'ally');
      const enemies = targetSnapshots.filter(entry => entry.relation === 'enemy');
      const legalAllies = allies.filter(entry => entry.pull || entry.push);
      const legalEnemies = enemies.filter(entry => entry.pull || entry.push);
      details.seyran.push({
        playerId,
        unitId: String(unit.id || ''),
        row: Number(unit.row),
        col: Number(unit.col),
        modeId: String(getRealtimeCombatModeProfileForUnit(playerId, unit)?.activeId || ''),
        allies: allies.length,
        enemies: enemies.length,
        legalAllies: legalAllies.length,
        legalEnemies: legalEnemies.length,
        targets: targetSnapshots,
      });
      if (targets.some(target => !Number(target.owner || getOwnerPlayerIdForUnit?.(target) || 0))) {
        issues.push({ code: 'seyran-target-owner-missing', playerId, unitId: String(unit.id || '') });
      }
    }
  }

  return {
    format: 'ROK_KIARA_TACTICAL_AUDIT_V1',
    at: Date.now(),
    ok: issues.length === 0,
    issues,
    warnings,
    details,
  };
}

function runRealtimeStage6CompatibilityAudit(options = {}) {
  const issues = [];
  const warnings = [];
  const roster = [];
  const invocationCards = Object.values(CARD_LIBRARY || {})
    .filter(card => getCardTypeId(card) === 'invocation')
    .sort((a, b) => String(a.id || '').localeCompare(String(b.id || '')));

  for (const card of invocationCards) {
    const cardId = String(card.id || '');
    const rule = REALTIME_COMBAT_MODE_CARD_RULES[cardId] || null;
    const allowed = rule?.allowed ? [...rule.allowed] : [];
    const defaultMode = String(rule?.default || '');
    if (!rule) issues.push({ code:'missing-card-mode-rule', cardId, name:card.name || cardId });
    else {
      const invalid = allowed.filter(modeId => !REALTIME_COMBAT_MODE_DB[normalizeRealtimeCombatModeId(modeId)]);
      if (invalid.length) issues.push({ code:'invalid-mode-id', cardId, modes:invalid });
      if (!allowed.length) issues.push({ code:'empty-mode-list', cardId });
      if (defaultMode && !allowed.includes(defaultMode)) issues.push({ code:'default-not-allowed', cardId, defaultMode, allowed });
    }

    const configurable = CONFIGURABLE_INVOCATION_POWER_CARD_IDS.has(cardId);
    const activeAudit = REALTIME_STAGE6_POWER_AUDIT[cardId] || null;
    if (configurable && !activeAudit) issues.push({ code:'configurable-power-not-audited', cardId });
    if (!configurable && activeAudit) warnings.push({ code:'audit-entry-not-configurable', cardId });
    if (activeAudit) {
      for (const kind of activeAudit.pendingKinds || []) {
        if (!REALTIME_STAGE6_CANCELABLE_PENDING_KINDS.has(kind)) issues.push({ code:'pending-kind-not-cancelable', cardId, kind });
      }
    }

    roster.push({
      cardId,
      name: card.name || cardId,
      qualities: Array.isArray(card.qualities) ? card.qualities.map(String) : [],
      movementType: String(card.movementType || 'basic'),
      modes: allowed,
      defaultMode,
      configurablePower: configurable,
      powerAudit: activeAudit ? safeDiagnosticClone(activeAudit, null) : null,
      compatibilityNotes: REALTIME_CARD_COMPATIBILITY_NOTES[cardId] || [],
    });
  }

  for (const kind of REALTIME_MANUAL_ABILITY_PENDING_KINDS) {
    if (!REALTIME_STAGE6_CANCELABLE_PENDING_KINDS.has(kind)) issues.push({ code:'manual-pending-not-cancelable', kind });
  }

  const kiaraTactical = auditKiaraTacticalRuntimeInvariants();
  for (const issue of kiaraTactical.issues || []) issues.push({ scope: 'kiara-tactical', ...issue });
  for (const warning of kiaraTactical.warnings || []) warnings.push({ scope: 'kiara-tactical', ...warning });

  const result = {
    format:'ROK_REALTIME_STAGE6_AUDIT_V1',
    build:GAME_VERSION,
    balanceProfile:REALTIME_BALANCE_PROFILE_ID,
    at:Date.now(),
    rosterCount:roster.length,
    explicitModeRules:roster.filter(entry => entry.modes.length > 0).length,
    configurablePowerCount:roster.filter(entry => entry.configurablePower).length,
    issues,
    warnings,
    ok:issues.length === 0,
    kiaraTactical,
    roster,
  };
  realtimeStage6AuditRuntime.last = result;

  if (options.record !== false) {
    try {
      recordRokMatchDiagnostic(
        'stage6-compatibility-audit',
        result.ok ? 'Auditoría RT S6 OK.' : `Auditoría RT S6: ${issues.length} problema(s).`,
        result,
        { persistNow:true }
      );
      recordRokTacticalTelemetry('stage6-compatibility-audit', result);
    } catch (_) {}
  }

  if (!result.ok) {
    try { window.ROK_DEBUG_RIBBON?.show?.('AUDITORÍA RT', 'warn', `${issues.length} inconsistencia(s). Exporta debug.`); } catch (_) {}
  }
  return result;
}


function auditOdaNoKageRangeProfile(playerId = LOCAL_PLAYER_ID) {
  const card = CARD_LIBRARY?.ninjaOdaNoKage;
  const units = (state.players?.[playerId]?.units || []).filter(unit => unit?.cardId === 'ninjaOdaNoKage');
  return {
    cardId: card?.id || 'ninjaOdaNoKage',
    name: card?.name || 'Oda no Kage',
    canonicalPrimaryRange: Number(card?.attackProfile?.range ?? 0),
    secondaryRange: Number(card?.extraWeapons?.[0]?.range ?? 0),
    units: units.map(unit => {
      const profile = getEffectiveAttackProfile(card, unit, playerId);
      return {
        unitId: unit.id,
        row: unit.row,
        col: unit.col,
        activeWeaponType: unit.activeWeaponType || card?.weaponType || '',
        shadowBound: Boolean(unit.odaNoKageShadowBound),
        effectiveRange: Number(profile?.range ?? 0),
      };
    }),
  };
}

window.ROK_STAGE6_AUDIT = {
  run: runRealtimeStage6CompatibilityAudit,
  getLast: () => safeDiagnosticClone(realtimeStage6AuditRuntime.last, null),
  kiaraTactical: () => safeDiagnosticClone(auditKiaraTacticalRuntimeInvariants(), null),
  odaNoKageRange: auditOdaNoKageRangeProfile,
};

function getSelectedRealtimeCombatModeUnit() {
  const system = ensureRealtimeCombatModeSystemState();
  const playerId = Number(system.selectedPlayerId || LOCAL_PLAYER_ID || 1);
  const unit = getUnitById?.(playerId, system.selectedUnitId);
  if (!unit) return null;
  return { playerId, unit };
}

function selectRealtimeCombatModeUnit(playerId, unitId, source = 'nexus') {
  if (!isRealtimePlayStyle() || !state?.realtime?.active) return false;
  const resolvedPlayerId = Number(playerId || 0);
  if (resolvedPlayerId !== Number(LOCAL_PLAYER_ID)) return false;
  const unit = getUnitById?.(resolvedPlayerId, unitId);
  if (!unit) return false;
  const system = ensureRealtimeCombatModeSystemState();
  system.initialized = true;
  system.selectedPlayerId = resolvedPlayerId;
  system.selectedUnitId = String(unit.id || '');
  system.selectedSpawnId = String(unit.spawnId || '');
  normalizeRealtimeCombatModeForUnit(resolvedPlayerId, unit);
  renderRealtimeCombatModePanel();
  renderSpawnMarkers();
  renderUnits();
  if (source === 'nexus') {
    const card = CARD_LIBRARY?.[unit.cardId];
    log(`Modo de combate: ${card?.name || 'Invocación'} seleccionada desde su Nexo.`);
  }
  return true;
}

function setRealtimeCombatModeForUnit(playerId, unitId, modeId) {
  if (!isRealtimePlayStyle() || !state?.realtime?.active) return false;
  const resolvedPlayerId = Number(playerId || 0);
  if (resolvedPlayerId !== Number(LOCAL_PLAYER_ID)) return false;
  const unit = getUnitById?.(resolvedPlayerId, unitId);
  if (!unit) return false;
  const allowed = getRealtimeCombatModeAllowedIds(resolvedPlayerId, unit);
  const normalizedModeId = normalizeRealtimeCombatModeId(modeId);
  if (!allowed.includes(normalizedModeId) || !REALTIME_COMBAT_MODE_DB[normalizedModeId]) return false;
  if (isOnlineMatchActive() && !isRealtimeOnlineAuthority()) {
    void window.ROK_ONLINE_PVP?.sendRealtimeCommand?.('combat-mode', { unitId: String(unitId || ''), modeId: normalizedModeId });
    // UI local: refleja la intención de inmediato; el snapshot del Host la confirma.
    unit.realtimeCombatMode = normalizedModeId;
    const system = ensureRealtimeCombatModeSystemState();
    system.selectedPlayerId = resolvedPlayerId;
    system.selectedUnitId = String(unit.id || '');
    system.selectedSpawnId = String(unit.spawnId || '');
    renderAll('realtime-combat-mode-pending-online');
    return true;
  }
  const applied = applyRealtimeCombatModeForPlayer(resolvedPlayerId, unitId, normalizedModeId, { markDirty: true, selectLocal: true });
  if (!applied) return false;
  const card = CARD_LIBRARY?.[unit.cardId];
  log(`${card?.name || 'Invocación'} cambia a modo ${REALTIME_COMBAT_MODE_DB[normalizedModeId].label}.`);
  renderAll('realtime-combat-mode-change');
  return true;
}

function getRealtimeCombatPowerForCard(cardId) {
  const id = String(cardId || '');
  if (!id) return 0;
  if (realtimeStage3Runtime.combatPowerCache.has(id)) return realtimeStage3Runtime.combatPowerCache.get(id);
  const card = CARD_LIBRARY?.[id];
  let score = 0;
  try { score = Math.max(0, Number(calculateCardBattleScore?.(card)?.battlePoints || 0)); } catch (_) {}
  if (!score && card) {
    const attack = getAttackProfile?.(card) || {};
    score = Math.max(1, Number(attack.damage ?? card.stats?.damage ?? card.stats?.atk ?? 0) * 20 + Number(card.stats?.life ?? 0) * 10);
  }
  realtimeStage3Runtime.combatPowerCache.set(id, score);
  return score;
}

function isRealtimeCombatModeTargetConcealed(unit) {
  if (!unit) return true;
  return Boolean(
    unitHasActiveFactor?.(unit, 'hidden')
    || unitHasCamuflajeHidden?.(unit)
    || unitHasSaqueadorSigiloHidden?.(unit)
  );
}

function getRealtimeEnemyInvocationCandidates(playerId) {
  const enemyId = getEnemyPlayerId(playerId);
  return (state.players?.[enemyId]?.units || [])
    .filter(unit => unit && unit.status !== 'restoring' && Number(unit.hp ?? 0) > 0)
    .filter(unit => !isRealtimeCombatModeTargetConcealed(unit))
    .map(unit => ({ playerId: enemyId, unit, card: CARD_LIBRARY?.[unit.cardId] }))
    .filter(entry => entry.card);
}

function buildRealtimeTargetFromUnitEntry(entry) {
  if (!entry?.unit) return null;
  return buildTarget('invocation', entry.playerId, { unitId: entry.unit.id });
}

function getRealtimeOffensiveFeasibilityScore(playerId, sourceUnit, entry) {
  if (!sourceUnit || !entry?.unit) return 0;
  const sourceCard = CARD_LIBRARY?.[sourceUnit.cardId];
  const attack = sourceCard
    ? (getEffectiveAttackProfile?.(sourceCard, sourceUnit, playerId) || getAttackProfile?.(sourceCard) || {})
    : {};
  const damage = Math.max(0, Number(attack.damage ?? sourceUnit.atk ?? sourceCard?.stats?.atk ?? 0));
  const range = Math.max(1, Number(attack.range ?? 1));
  const targetHp = Math.max(1, Number(entry.unit.hp ?? entry.card?.stats?.life ?? 1));
  const targetDefense = Math.max(
    0,
    Number(entry.unit.defense ?? entry.unit.resistance ?? entry.card?.stats?.defense ?? entry.card?.stats?.resistance ?? 0),
  );
  const distance = ringDistance(sourceUnit.row, sourceUnit.col, entry.unit.row, entry.unit.col);
  const estimatedEffectiveDamage = damage > 0
    ? Math.max(0.25, damage - Math.min(Math.max(0, damage - 0.25), targetDefense * 0.2))
    : 0;
  const hits = estimatedEffectiveDamage > 0 ? Math.max(1, Math.ceil(targetHp / estimatedEffectiveDamage)) : 99;

  let score = 0;
  if (damage > 0) score += 34;
  if (distance <= range) score += 26;
  else score += Math.max(0, 20 - (distance - range) * 4);
  score += Math.max(0, 24 - hits * 3);

  const tacticalText = [
    entry.card?.power,
    entry.card?.summary,
    ...(entry.card?.tags || []),
    ...(entry.card?.effectStructure?.modifiers || []),
  ].filter(Boolean).join(' ').toLowerCase();
  if (/atur|atadur|cegu|paral|control|empuj|ocult|debuff/.test(tacticalText)) score += 12;
  return score;
}

function getRealtimeLiveThreatScore(playerId, sourceUnit, entry) {
  if (!entry?.unit || !entry?.card) return -Infinity;
  const enemyId = Number(entry.playerId || getEnemyPlayerId(playerId));
  const unit = entry.unit;
  const attack = getEffectiveAttackProfile?.(entry.card, unit, enemyId) || getAttackProfile?.(entry.card) || {};
  const pb = Math.max(0, getRealtimeCombatPowerForCard(unit.cardId));
  const hp = Math.max(0, Number(unit.hp ?? 0));
  const damage = Math.max(0, Number(attack.damage ?? unit.atk ?? entry.card?.stats?.atk ?? 0));
  const range = Math.max(1, Number(attack.range ?? 1));
  const alliedCaster = state.players?.[Number(playerId)]?.caster;
  const casterDistance = alliedCaster ? ringDistance(unit.row, unit.col, alliedCaster.row, alliedCaster.col) : 999;
  const immediateCasterPressure = alliedCaster && casterDistance <= range + 1 ? REALTIME_OFFENSIVE_CASTER_PRESSURE_WEIGHT : 0;
  const sourceDistance = sourceUnit ? ringDistance(sourceUnit.row, sourceUnit.col, unit.row, unit.col) : 0;
  const feasibility = getRealtimeOffensiveFeasibilityScore(playerId, sourceUnit, entry);
  return (
    pb * REALTIME_OFFENSIVE_PB_WEIGHT
    + damage * REALTIME_OFFENSIVE_DAMAGE_WEIGHT
    + range * REALTIME_OFFENSIVE_RANGE_WEIGHT
    + hp * REALTIME_OFFENSIVE_HP_WEIGHT
    + immediateCasterPressure
    + feasibility
    - Math.min(12, sourceDistance) * 2
  );
}

function getRealtimeHuntScore(playerId, sourceUnit, entry) {
  if (!entry?.unit || !entry?.card) return Infinity;
  const hp = Math.max(0, Number(entry.unit.hp ?? 0));
  const maxHp = Math.max(1, Number(entry.unit.maxHp ?? entry.unit.baseHp ?? entry.card?.stats?.life ?? 1));
  const defense = Math.max(
    0,
    Number(entry.unit.defense ?? entry.unit.resistance ?? entry.card?.stats?.defense ?? entry.card?.stats?.resistance ?? 0),
  );
  const sourceCard = CARD_LIBRARY?.[sourceUnit?.cardId];
  const sourceAttack = sourceUnit && sourceCard
    ? (getEffectiveAttackProfile?.(sourceCard, sourceUnit, playerId) || getAttackProfile?.(sourceCard) || {})
    : {};
  const sourceDamage = Math.max(1, Number(sourceAttack.damage ?? sourceUnit?.atk ?? sourceCard?.stats?.atk ?? 1));
  const effectiveDamage = Math.max(0.25, sourceDamage - Math.min(Math.max(0, sourceDamage - 0.25), defense * 0.2));
  const hitsToKill = Math.max(1, Math.ceil(hp / effectiveDamage));
  const hpRatio = hp / maxHp;
  const distance = sourceUnit ? ringDistance(sourceUnit.row, sourceUnit.col, entry.unit.row, entry.unit.col) : 999;
  const pb = Math.max(0, getRealtimeCombatPowerForCard(entry.unit.cardId));
  const negativeStateCount = [
    unitHasActiveFactor?.(entry.unit, 'blindness'),
    unitHasActiveFactor?.(entry.unit, 'burn'),
    unitHasActiveFactor?.(entry.unit, 'binding'),
    unitHasParalysis?.(entry.unit),
  ].filter(Boolean).length;

  return (
    hitsToKill * 1000
    + hp * 68
    + hpRatio * 140
    + defense * 75
    + distance * 14
    + pb * 0.015
    - negativeStateCount * 110
  );
}

function chooseRealtimeStrongestEnemyInvocation(playerId, sourceUnit) {
  const candidates = getRealtimeEnemyInvocationCandidates(playerId);
  return [...candidates].sort((a, b) => {
    const threatA = getRealtimeLiveThreatScore(playerId, sourceUnit, a);
    const threatB = getRealtimeLiveThreatScore(playerId, sourceUnit, b);
    if (threatA !== threatB) return threatB - threatA;
    return ringDistance(sourceUnit?.row ?? 0, sourceUnit?.col ?? 0, a.unit.row, a.unit.col)
      - ringDistance(sourceUnit?.row ?? 0, sourceUnit?.col ?? 0, b.unit.row, b.unit.col);
  })[0] || null;
}

function chooseRealtimeMostPowerfulEnemyInvocation(playerId, sourceUnit) {
  const candidates = getRealtimeEnemyInvocationCandidates(playerId);
  return [...candidates].sort((a, b) => {
    const powerA = Math.max(0, Number(getRealtimeCombatPowerForCard(a.unit.cardId) || 0));
    const powerB = Math.max(0, Number(getRealtimeCombatPowerForCard(b.unit.cardId) || 0));
    if (powerA !== powerB) return powerB - powerA;
    const threatA = getRealtimeLiveThreatScore(playerId, sourceUnit, a);
    const threatB = getRealtimeLiveThreatScore(playerId, sourceUnit, b);
    if (threatA !== threatB) return threatB - threatA;
    return ringDistance(sourceUnit?.row ?? 0, sourceUnit?.col ?? 0, a.unit.row, a.unit.col)
      - ringDistance(sourceUnit?.row ?? 0, sourceUnit?.col ?? 0, b.unit.row, b.unit.col);
  })[0] || null;
}

function chooseRealtimeWeakestEnemyInvocation(playerId, sourceUnit) {
  const candidates = getRealtimeEnemyInvocationCandidates(playerId);
  return [...candidates].sort((a, b) => {
    const huntA = getRealtimeHuntScore(playerId, sourceUnit, a);
    const huntB = getRealtimeHuntScore(playerId, sourceUnit, b);
    return huntA - huntB;
  })[0] || null;
}


function chooseRealtimeNearestEnemyInvocation(playerId, sourceUnit) {
  const candidates = getRealtimeEnemyInvocationCandidates(playerId);
  return [...candidates].sort((a, b) => {
    const da = ringDistance(sourceUnit?.row ?? 0, sourceUnit?.col ?? 0, a.unit.row, a.unit.col);
    const db = ringDistance(sourceUnit?.row ?? 0, sourceUnit?.col ?? 0, b.unit.row, b.unit.col);
    if (da !== db) return da - db;
    // A igual distancia, prioriza la amenaza más importante para que Ofensivo
    // no cambie de objetivo de forma arbitraria entre piezas adyacentes.
    return getRealtimeLiveThreatScore(playerId, sourceUnit, b)
      - getRealtimeLiveThreatScore(playerId, sourceUnit, a);
  })[0] || null;
}


function chooseRealtimeOdaOffensiveInvocation(playerId, sourceUnit) {
  if (!isOdaNoKageUnit(sourceUnit)) return null;
  const card = CARD_LIBRARY?.[sourceUnit.cardId] || null;
  const attack = getEffectiveAttackProfile?.(card, sourceUnit, playerId) || card?.attackProfile || {};
  // Ofensivo no convierte a Oda en Cacería global: solo desvía su marcha hacia
  // una Invocación que esté razonablemente cerca. Con Alcance 2, cinco casillas
  // dan margen para aproximarse, ejecutar el barrido y volver a presionar.
  const chaseRadius = Math.max(5, Number(attack.range || 1) + 3);
  const nearest = chooseRealtimeNearestEnemyInvocation(playerId, sourceUnit);
  if (!nearest) return null;
  const distance = ringDistance(sourceUnit.row, sourceUnit.col, nearest.unit.row, nearest.unit.col);
  return distance <= chaseRadius ? nearest : null;
}


function getRealtimeEnemyCasterTarget(playerId) {
  const enemyId = getEnemyPlayerId(playerId);
  const caster = state.players?.[enemyId]?.caster;
  if (!caster || Number(caster.life ?? 0) <= 0) return null;
  return buildTarget('caster', enemyId);
}

function getRealtimeOffensivePathLaneScore(playerId, sourceUnit, enemyUnit) {
  if (!sourceUnit || !enemyUnit) return Infinity;
  const enemyCaster = state.players?.[getEnemyPlayerId(playerId)]?.caster;
  if (!enemyCaster || Number(enemyCaster.life ?? 0) <= 0) return Infinity;

  const sr = Number(sourceUnit.row);
  const sc = Number(sourceUnit.col);
  const cr = Number(enemyCaster.row);
  const cc = Number(enemyCaster.col);
  const tr = Number(enemyUnit.row);
  const tc = Number(enemyUnit.col);
  const vr = cr - sr;
  const vc = cc - sc;
  const wr = tr - sr;
  const wc = tc - sc;
  const len2 = vr * vr + vc * vc;
  if (len2 <= 0) return Infinity;

  // Debe estar delante de la unidad y entre ella y la presión hacia el Kaster.
  const projection = (wr * vr + wc * vc) / len2;
  if (projection <= 0 || projection > 1.15) return Infinity;
  const sourceCasterDistance = ringDistance(sr, sc, cr, cc);
  const targetCasterDistance = ringDistance(tr, tc, cr, cc);
  if (targetCasterDistance > sourceCasterDistance) return Infinity;

  // Corredor de aproximadamente una casilla y media alrededor de la línea de avance.
  // Así Ofensivo limpia lo que está en su paso sin desviarse para cazar todo el mapa.
  const perpendicular = Math.abs(vr * wc - vc * wr) / Math.sqrt(len2);
  if (perpendicular > 1.5) return Infinity;

  const sourceTargetDistance = ringDistance(sr, sc, tr, tc);
  return perpendicular * 100 + sourceTargetDistance * 12 + projection * 4;
}

function chooseRealtimeOffensivePathEnemy(playerId, sourceUnit, targetPool = null) {
  if (!sourceUnit) return null;
  const candidates = getRealtimeEnemyInvocationCandidates(playerId)
    .map(entry => ({ entry, laneScore: getRealtimeOffensivePathLaneScore(playerId, sourceUnit, entry.unit) }))
    .filter(item => Number.isFinite(item.laneScore));
  if (!candidates.length) return null;

  let allowedIds = null;
  if (Array.isArray(targetPool)) {
    allowedIds = new Set(targetPool
      .filter(target => target?.type === 'invocation')
      .map(target => `${Number(target.playerId)}:${String(target.unitId || '')}`));
  }

  return candidates
    .filter(item => !allowedIds || allowedIds.has(`${Number(item.entry.playerId)}:${String(item.entry.unit.id)}`))
    .sort((a, b) => {
      if (a.laneScore !== b.laneScore) return a.laneScore - b.laneScore;
      const threatA = getRealtimeLiveThreatScore(playerId, sourceUnit, a.entry);
      const threatB = getRealtimeLiveThreatScore(playerId, sourceUnit, b.entry);
      return threatB - threatA;
    })[0]?.entry || null;
}

function getRealtimeUnitAttackTargetDescriptor(unit) {
  if (!unit) return null;
  if (unit.realtimeAttackTelegraph?.target) return unit.realtimeAttackTelegraph.target;
  if (unit.structureAttackTarget) return unit.structureAttackTarget;
  if (unit.engagedWith?.unitId != null) {
    return {
      type: 'invocation',
      playerId: Number(unit.engagedWith.playerId),
      unitId: unit.engagedWith.unitId,
    };
  }
  return null;
}

function isRealtimeEnemyActivelyThreateningPlayer(playerId, enemyUnit) {
  if (!enemyUnit) return false;
  const descriptor = getRealtimeUnitAttackTargetDescriptor(enemyUnit);
  if (descriptor && Number(descriptor.playerId) === Number(playerId)) return true;

  const alliedCaster = state.players?.[playerId]?.caster;
  const enemyCard = CARD_LIBRARY?.[enemyUnit.cardId];
  if (alliedCaster && enemyCard) {
    const enemyId = getEnemyPlayerId(playerId);
    const attack = getEffectiveAttackProfile?.(enemyCard, enemyUnit, enemyId) || getAttackProfile?.(enemyCard) || {};
    const range = Math.max(1, Number(attack.range ?? 1));
    if (ringDistance(enemyUnit.row, enemyUnit.col, alliedCaster.row, alliedCaster.col) <= range) return true;
  }
  return false;
}

function getRealtimeDefensiveThreatScore(playerId, sourceUnit, entry) {
  if (!entry?.unit || !isRealtimeEnemyActivelyThreateningPlayer(playerId, entry.unit)) return -Infinity;
  const distance = ringDistance(sourceUnit?.row ?? 0, sourceUnit?.col ?? 0, entry.unit.row, entry.unit.col);
  return getRealtimeLiveThreatScore(playerId, sourceUnit, entry) - distance * 6;
}

function chooseRealtimeNearestDefensiveThreat(playerId, sourceUnit) {
  const candidates = getRealtimeEnemyInvocationCandidates(playerId)
    .map(entry => ({ entry, score: getRealtimeDefensiveThreatScore(playerId, sourceUnit, entry) }))
    .filter(item => Number.isFinite(item.score));
  return candidates.sort((a, b) => b.score - a.score)[0]?.entry || null;
}


function chooseRealtimeEnemyStructureTarget(playerId, sourceUnit) {
  const enemyId = getEnemyPlayerId(playerId);
  const guardians = (state.players?.[enemyId]?.guardians || [])
    .filter(g => g && g.active !== false && !g.destroying && Number(g.resistance ?? 0) > 0)
    .map(g => ({
      target: buildTarget('guardian', enemyId, { guardianId: g.id }),
      guardian: g,
      distance: ringDistance(sourceUnit?.row ?? 0, sourceUnit?.col ?? 0, g.row, g.col),
    }));
  return guardians.sort((a, b) => {
    if (a.distance !== b.distance) return a.distance - b.distance;
    return Number(a.guardian.resistance ?? 0) - Number(b.guardian.resistance ?? 0);
  })[0]?.target || null;
}

function buildRealtimeRiskZoneDestination(playerId) {
  const enemyId = getEnemyPlayerId(playerId);
  return {
    row: getEnemyRiskRow(playerId),
    col: 4,
    type: 'riskZone',
    playerId: enemyId,
    label: 'zona de riesgo rival',
  };
}


// RT-08.17 S2 · Arena Affordances.
// El terreno expone capacidades universales para que distintas cartas puedan
// producir la misma oportunidad táctica sin duplicar IA por nombre de carta.
const ARENA_TACTICAL_AFFORDANCE_DB = Object.freeze({
  concealment_zone: { id: 'concealment_zone', label: 'Zona de Oculto', tags: ['concealment', 'protection', 'positioning'] },
  concealment_route: { id: 'concealment_route', label: 'Ruta de Oculto', tags: ['concealment', 'route', 'positioning'] },
  reveal_zone: { id: 'reveal_zone', label: 'Zona de Revelado', tags: ['reveal', 'antiConcealment', 'control'] },
  movement_zone: { id: 'movement_zone', label: 'Zona de Movilidad', tags: ['mobility', 'positioning'] },
  portal_link: { id: 'portal_link', label: 'Enlace de reposicionamiento', tags: ['reposition', 'mobility', 'positioning'] },
  hazard_zone: { id: 'hazard_zone', label: 'Zona peligrosa', tags: ['hazard', 'avoidance'] },
  support_zone: { id: 'support_zone', label: 'Zona de soporte', tags: ['support', 'protection'] },
});

function getArenaAffordanceCells(affordance) {
  if (!affordance) return [];
  const explicit = Array.isArray(affordance.cells) && affordance.cells.length
    ? affordance.cells
    : (Array.isArray(affordance.zone?.hazeCells) && affordance.zone.hazeCells.length
      ? affordance.zone.hazeCells
      : null);
  if (explicit) {
    return explicit
      .filter(cell => cell && isInside(Number(cell.row), Number(cell.col)))
      .map(cell => ({ row: Number(cell.row), col: Number(cell.col) }));
  }
  if (affordance.row == null || affordance.col == null) return [];
  return getCellsInRadius(
    Number(affordance.row),
    Number(affordance.col),
    Math.max(0, Number(affordance.radius || 0)),
    true,
  ).map(cell => ({ row: cell.row, col: cell.col }));
}

function getArenaTacticalAffordances(playerId = null) {
  const result = [];

  for (const zone of (state.smokeZones || [])) {
    if (!zone || Number(zone.phasesRemaining ?? 0) <= 0) continue;
    const isKage = zone.type === 'kageNoMichi';
    result.push({
      id: String(zone.id || `${isKage ? 'kage' : 'smoke'}:${zone.playerId}:${zone.row}:${zone.col}`),
      type: isKage ? 'concealment_route' : (zone.affordanceType || 'concealment_zone'),
      ownerPlayerId: Number(zone.playerId),
      sourceType: String(zone.sourceType || (isKage ? 'spell' : 'ability')),
      sourceCardId: String(zone.sourceCardId || ''),
      sourceUnitId: zone.sourceUnitId ?? zone.bombOwnerUnitId ?? null,
      row: Number(zone.row),
      col: Number(zone.col),
      radius: Math.max(0, Number(zone.radius ?? 0)),
      cells: Array.isArray(zone.hazeCells) ? zone.hazeCells : null,
      tags: Array.isArray(zone.affordanceTags)
        ? zone.affordanceTags
        : ['concealment', 'positioning', isKage ? 'route' : 'smoke'],
      zone,
    });
  }

  for (const portal of (state.farolPortals || [])) {
    if (!portal || portal.stage !== 'complete' || portal.destinationRow == null || portal.destinationCol == null) continue;
    result.push({
      id: String(portal.key || `portal:${portal.playerId}:${portal.sourceUnitId}`),
      type: 'portal_link',
      ownerPlayerId: Number(portal.playerId),
      sourceType: 'ability',
      sourceUnitId: portal.sourceUnitId ?? null,
      row: Number(portal.originRow),
      col: Number(portal.originCol),
      radius: 0,
      cells: [
        { row: Number(portal.originRow), col: Number(portal.originCol) },
        { row: Number(portal.destinationRow), col: Number(portal.destinationCol) },
      ],
      tags: ['reposition', 'mobility', 'portal'],
      portal,
    });
  }

  for (const lamp of (state.celestialLamps || [])) {
    if (!lamp || lamp.active === false || Number(lamp.remainingPhases ?? 0) <= 0) continue;
    const cells = getCellsInRadius(Number(lamp.row), Number(lamp.col), Number(lamp.radius ?? 1), true);
    result.push({
      id: `lamp-reveal:${lamp.id}`,
      type: 'reveal_zone',
      ownerPlayerId: Number(lamp.playerId),
      sourceType: 'spell',
      sourceCardId: String(lamp.sourceCardId || 'spellTentoro'),
      row: Number(lamp.row),
      col: Number(lamp.col),
      radius: Number(lamp.radius ?? 1),
      cells,
      tags: ['reveal', 'antiConcealment', 'control'],
      lamp,
    });
    result.push({
      id: `lamp-move:${lamp.id}`,
      type: 'movement_zone',
      ownerPlayerId: Number(lamp.playerId),
      sourceType: 'spell',
      sourceCardId: String(lamp.sourceCardId || 'spellTentoro'),
      row: Number(lamp.row),
      col: Number(lamp.col),
      radius: Number(lamp.radius ?? 1),
      cells,
      tags: ['mobility', 'positioning'],
      lamp,
    });
  }

  return playerId == null
    ? result
    : result.filter(item =>
        Number(item.ownerPlayerId) === Number(playerId)
        || item.type === 'reveal_zone');
}

function canUnitBenefitFromConcealmentAffordance(playerId, unit, affordance, cell = null) {
  if (!unit || !affordance || !['concealment_zone', 'concealment_route'].includes(affordance.type)) return false;
  if (Number(affordance.ownerPlayerId) !== Number(playerId)) return false;
  const card = CARD_LIBRARY?.[unit.cardId];
  if (!card || unit.status === 'restoring') return false;

  const probe = cell || { row: unit.row, col: unit.col };
  if (isCellProtectedByGuardianAura(probe.row, probe.col, playerId)) return false;
  if (isCellRevealedByEnemyCelestialLamp(probe.row, probe.col, playerId)) return false;

  const zone = affordance.zone || {};
  if (zone.type === 'kageNoMichi') {
    const elements = Array.isArray(zone.targetElements) && zone.targetElements.length
      ? zone.targetElements
      : ['oscuridad'];
    const unitElement = unit.elementId || getCardElementId(card);
    if (!elements.includes(unitElement)) return false;
    const qualities = Array.isArray(zone.targetQualities) && zone.targetQualities.length
      ? zone.targetQualities
      : ['assassin', 'bandit', 'stalker'];
    if (!(card.qualities || []).some(id => qualities.includes(id))) return false;
    return true;
  }

  const families = Array.isArray(zone.eligibleFamilies) ? zone.eligibleFamilies : null;
  const qualities = Array.isArray(zone.targetQualities) ? zone.targetQualities : null;
  const elements = Array.isArray(zone.targetElements) ? zone.targetElements : null;

  if (families?.length && !families.includes(card.family)) return false;
  if (qualities?.length && !(card.qualities || []).some(id => qualities.includes(id))) return false;
  if (elements?.length && !elements.includes(unit.elementId || getCardElementId(card))) return false;

  // Compatibilidad hacia atrás: una cortina histórica sin metadata sigue
  // permitiendo Oculto a la familia Ninja.
  if (!families && !qualities && !elements) return isNinjaFamilyCard(card);
  return true;
}

function isRealtimeAffordanceCellUsable(playerId, unit, cell) {
  if (!cell || !isInside(cell.row, cell.col)) return false;
  if (Number(unit.row) === Number(cell.row) && Number(unit.col) === Number(cell.col)) return true;
  if (isOccupied(cell.row, cell.col)) return false;
  return !isCastPlacementBlockedForPlayer(cell.row, cell.col, playerId);
}

function getRealtimeTacticalTargetPosition(intent) {
  return getTargetBoardPosition(intent?.target || intent?.destination || null);
}

function scoreRealtimeConcealmentCell(playerId, unit, affordance, cell, baseIntent) {
  if (!canUnitBenefitFromConcealmentAffordance(playerId, unit, affordance, cell)) return -Infinity;
  if (!isRealtimeAffordanceCellUsable(playerId, unit, cell)) return -Infinity;

  const modeId = String(baseIntent?.modeId || unit.realtimeCombatMode || 'offensive');
  const targetPos = getRealtimeTacticalTargetPosition(baseIntent);
  const currentDistance = targetPos ? ringDistance(unit.row, unit.col, targetPos.row, targetPos.col) : 0;
  const nextDistance = targetPos ? ringDistance(cell.row, cell.col, targetPos.row, targetPos.col) : 0;
  const progress = currentDistance - nextDistance;
  const travel = ringDistance(unit.row, unit.col, cell.row, cell.col);
  const ownSide = isRealtimeRowOnOwnSide(playerId, cell.row);

  let score = 70 - travel * 5;
  if (!unitHasActiveFactor(unit, 'hidden')) score += 34;

  if (modeId === 'defensive') {
    score += ownSide ? 95 : -65;
    score += getRealtimeDefensiveSafetyMarginAt(
      cell.row,
      cell.col,
      getRealtimeDefensiveThreatEntries(playerId),
    ) * 12;
  } else if (modeId === 'assassination') {
    score += progress * 42 + (!ownSide ? 34 : 0);
  } else if (modeId === 'offensive') {
    score += progress * 30 + (!ownSide ? 28 : 0);
  } else if (modeId === 'hunt') {
    score += progress * 34 + (!ownSide ? 20 : 0);
  } else if (modeId === 'siege') {
    score += progress * 32 + (!ownSide ? 24 : 0);
  }

  if (affordance.type === 'concealment_route') score += 18;
  return score;
}

function chooseRealtimeConcealmentAffordanceDestination(playerId, unit, baseIntent) {
  if (!unit || unit.status === 'restoring') return null;

  const affordances = getArenaTacticalAffordances(playerId)
    .filter(item => ['concealment_zone', 'concealment_route'].includes(item.type))
    .filter(item => Number(item.ownerPlayerId) === Number(playerId));

  let best = null;
  for (const affordance of affordances) {
    for (const cell of getArenaAffordanceCells(affordance)) {
      const score = scoreRealtimeConcealmentCell(playerId, unit, affordance, cell, baseIntent);
      if (!Number.isFinite(score)) continue;
      if (!best || score > best.score) best = { affordance, cell, score };
    }
  }
  if (!best) return null;

  const currentAffordance = affordances.find(affordance =>
    getArenaAffordanceCells(affordance).some(cell =>
      Number(cell.row) === Number(unit.row)
      && Number(cell.col) === Number(unit.col)
      && canUnitBenefitFromConcealmentAffordance(
        playerId,
        unit,
        affordance,
        { row: unit.row, col: unit.col },
      )));

  const modeId = String(baseIntent?.modeId || unit.realtimeCombatMode || 'offensive');
  if (currentAffordance && modeId !== 'defensive') {
    const currentScore = scoreRealtimeConcealmentCell(
      playerId,
      unit,
      currentAffordance,
      { row: unit.row, col: unit.col },
      baseIntent,
    );
    if (best.score <= currentScore + 8) return null;
  }

  return {
    row: best.cell.row,
    col: best.cell.col,
    type: 'arenaAffordance',
    affordanceType: best.affordance.type,
    affordanceId: best.affordance.id,
    label: ARENA_TACTICAL_AFFORDANCE_DB[best.affordance.type]?.label || 'oportunidad táctica',
    score: best.score,
  };
}

function applyRealtimeArenaAffordanceIntent(playerId, unit, baseIntent) {
  if (!baseIntent || !unit) return baseIntent;
  const destination = chooseRealtimeConcealmentAffordanceDestination(playerId, unit, baseIntent);
  if (!destination) return baseIntent;

  unit.realtimeTacticalAffordance = {
    id: destination.affordanceId,
    type: destination.affordanceType,
    score: Number(destination.score || 0),
    modeId: String(baseIntent.modeId || unit.realtimeCombatMode || ''),
  };

  return {
    ...baseIntent,
    destination,
    affordanceDestination: true,
    affordanceType: destination.affordanceType,
    avoidCombat: ['defensive', 'assassination'].includes(baseIntent.modeId)
      ? true
      : baseIntent.avoidCombat,
  };
}


// v9.87 · Naito Sutoka: Acechar no se usa como una simple mejora de movimiento.
// En Asesinato, una vez dentro del lado rival, intenta rodear al Kaster por un
// flanco y colocarse detrás de él antes de ejecutar el golpe.
function getRealtimeSutokaAssassinationFlankDestination(playerId, unit) {
  if (!isNaitoSutokaUnit(unit) || !isStalkAbilityActive(playerId, unit)) return null;
  const enemyId = getEnemyPlayerId(playerId);
  const caster = state.players?.[enemyId]?.caster;
  if (!caster || Number(caster.life ?? 0) <= 0) return null;

  const backDir = Number(playerId) === 1 ? -1 : 1;
  const candidates = [];
  for (const depth of [2, 1]) {
    for (const lateral of [-2, 2, -1, 1]) {
      const row = Number(caster.row) + backDir * depth;
      const col = Number(caster.col) + lateral;
      if (!isInside(row, col)) continue;
      if (!isUnitInEnemySide(playerId, { row, col })) continue;
      if (Number(unit.row) !== row || Number(unit.col) !== col) {
        if (isOccupied(row, col)) continue;
        if (isMovementStepBlockedForPlayer(row, col, playerId, 1, true)) continue;
      }
      const strikeDistance = ringDistance(row, col, caster.row, caster.col);
      if (strikeDistance > 2) continue;
      const safety = getKurayamiAssassinationCellSafety(playerId, row, col);
      const travel = ringDistance(unit.row, unit.col, row, col);
      const score = depth * 90
        + Math.abs(lateral) * 28
        + Math.min(6, Number(safety.minDistance || 0)) * 14
        - Number(safety.attackCoverage || 0) * 120
        - Number(safety.nearby || 0) * 22
        - travel * 2;
      candidates.push({ row, col, score, depth, lateral, strikeDistance });
    }
  }
  return candidates.sort((a, b) => b.score - a.score)[0] || null;
}

function isRealtimeSutokaFlankStrikePosition(playerId, unit) {
  if (!isNaitoSutokaUnit(unit) || !isStalkAbilityActive(playerId, unit)) return false;
  const caster = state.players?.[getEnemyPlayerId(playerId)]?.caster;
  if (!caster || Number(caster.life ?? 0) <= 0) return false;
  const backDir = Number(playerId) === 1 ? -1 : 1;
  const behindDepth = (Number(unit.row) - Number(caster.row)) * backDir;
  const lateral = Math.abs(Number(unit.col) - Number(caster.col));
  return behindDepth >= 1
    && lateral >= 1
    && ringDistance(unit.row, unit.col, caster.row, caster.col) <= 2;
}

function getRealtimeCombatIntent(playerId, unit) {
  const profile = getRealtimeCombatModeProfileForUnit(playerId, unit);
  const modeId = profile?.activeId || 'offensive';
  const enemyId = getEnemyPlayerId(playerId);

  const provocationSource = getProvocationSourceUnit(unit);
  if (provocationSource) {
    const provocationRouteNow = Date.now();
    if ((provocationRouteNow - Number(unit.naelProvocationRoutePulseAt || 0)) > 650) {
      unit.naelProvocationRoutePulseAt = provocationRouteNow;
      unit.naelProvocationRoutePulseSerial = Math.max(0, Number(unit.naelProvocationRoutePulseSerial || 0)) + 1;
    }
    const forcedTarget = buildTarget('invocation', provocationSource.playerId, { unitId: provocationSource.unit.id });
    return {
      modeId: 'offensive',
      profile: REALTIME_COMBAT_MODE_DB.offensive,
      target: forcedTarget,
      destination: forcedTarget,
      avoidCombat: false,
      provocation: true,
      forcedTarget: true,
      sourceFactorLevel: Number(provocationSource.entry?.level || 1),
    };
  }

  if (unitHasNativeCampeo(unit)) {
    const edgeRow = getCampeoRetreatEdgeRow(playerId);
    return {
      modeId: 'campeo',
      profile: null,
      target: null,
      destination: { row: edgeRow, col: Number(unit.col), type: 'campEdge', playerId: Number(playerId), label: 'límite trasero propio' },
      avoidCombat: true,
      campeoRetreat: true,
    };
  }

  if (isNaelUnit(unit) && naelHasProvokedEnemy(playerId, unit)) {
    const destination = buildRealtimeRiskZoneDestination(playerId);
    return {
      modeId: 'defensive',
      profile: profile?.active || REALTIME_COMBAT_MODE_DB.defensive,
      target: null,
      destination,
      avoidCombat: true,
      naelBaiting: true,
      affordanceDestination: true,
    };
  }

  const faroleraStrategicIntent = getRealtimeFaroleraStrategicIntent(
    playerId,
    unit,
    modeId,
    profile?.active,
  );
  if (faroleraStrategicIntent) return faroleraStrategicIntent;

  const seyranStrategicIntent = getRealtimeSeyranStrategicIntent(
    playerId,
    unit,
    modeId,
    profile?.active,
  );
  if (seyranStrategicIntent) return seyranStrategicIntent;

  let intent = null;

  if (modeId === 'defensive') {
    const entry = chooseRealtimeNearestDefensiveThreat(playerId, unit);
    const target = buildRealtimeTargetFromUnitEntry(entry);
    intent = { modeId, profile: profile?.active, target, destination: null, avoidCombat: true, reactiveDefense: true };
  } else if (modeId === 'siege') {
    const structureTarget = chooseRealtimeEnemyStructureTarget(playerId, unit);
    if (structureTarget) {
      intent = { modeId, profile: profile?.active, target: structureTarget, destination: structureTarget, avoidCombat: false, siege: true };
    } else {
      const riskDestination = buildRealtimeRiskZoneDestination(playerId);
      intent = { modeId, profile: profile?.active, target: null, destination: riskDestination, avoidCombat: true, siege: true, attackRiskZone: true };
    }
  } else if (modeId === 'assassination') {
    const target = getRealtimeEnemyCasterTarget(playerId);
    const sutokaFlank = isNaitoSutokaUnit(unit)
      ? getRealtimeSutokaAssassinationFlankDestination(playerId, unit)
      : null;
    intent = {
      modeId,
      profile: profile?.active,
      target,
      destination: sutokaFlank || target,
      avoidCombat: true,
      forcedCombatOnly: true,
      assassination: true,
      kurayamiAssassination: isKurayamiUnit(unit),
      sutokaFlankAssassination: Boolean(sutokaFlank),
      sutokaFlankDestination: sutokaFlank || null,
    };
  } else if (modeId === 'hunt') {
    const entry = chooseRealtimeWeakestEnemyInvocation(playerId, unit);
    const target = buildRealtimeTargetFromUnitEntry(entry) || getRealtimeEnemyCasterTarget(playerId);
    intent = { modeId, profile: profile?.active, target, destination: target, avoidCombat: false };
  } else if (modeId === 'offensive' && isRealtimeSimplePriorityNinja(unit)) {
    // v9.82 · Goemon/Junkai/Kurokage comparten el patrón ofensivo estándar de
    // presión sobre la Invocación de mayor poder. El Kaster sigue teniendo
    // prioridad de victoria si ya está legalmente a tiro; esta rama solo evita
    // que su movimiento Ofensivo se comporte como Asesinato permanente.
    const entry = chooseRealtimeMostPowerfulEnemyInvocation(playerId, unit);
    const target = buildRealtimeTargetFromUnitEntry(entry) || getRealtimeEnemyCasterTarget(playerId);
    intent = {
      modeId: 'offensive',
      profile: REALTIME_COMBAT_MODE_DB.offensive,
      target,
      destination: target || getRealtimeDefaultDestination(playerId, unit),
      avoidCombat: false,
      simpleNinjaOffensiveTarget: Boolean(entry),
    };
  } else if (modeId === 'offensive' && isKaguyaUnit(unit)) {
    const entry = chooseRealtimeMostPowerfulEnemyInvocation(playerId, unit);
    const target = buildRealtimeTargetFromUnitEntry(entry) || getRealtimeEnemyCasterTarget(playerId);
    intent = {
      modeId: 'offensive',
      profile: REALTIME_COMBAT_MODE_DB.offensive,
      target,
      destination: target || getRealtimeDefaultDestination(playerId, unit),
      avoidCombat: false,
      kaguyaOffensiveTarget: Boolean(entry),
    };
  } else if (modeId === 'offensive' && isRealtimeReviewedSamuraiPriorityUnit(unit)) {
    const entry = chooseRealtimeMostPowerfulEnemyInvocation(playerId, unit);
    const target = buildRealtimeTargetFromUnitEntry(entry) || getRealtimeEnemyCasterTarget(playerId);
    intent = {
      modeId: 'offensive',
      profile: REALTIME_COMBAT_MODE_DB.offensive,
      target,
      destination: target || getRealtimeDefaultDestination(playerId, unit),
      avoidCombat: false,
      reviewedSamuraiOffensiveTarget: Boolean(entry),
    };
  } else if (modeId === 'offensive' && isMinokageUnit(unit)) {
    const entry = chooseRealtimeMostPowerfulEnemyInvocation(playerId, unit);
    const target = buildRealtimeTargetFromUnitEntry(entry) || getRealtimeEnemyCasterTarget(playerId);
    intent = {
      modeId: 'offensive',
      profile: REALTIME_COMBAT_MODE_DB.offensive,
      target,
      destination: target || getRealtimeDefaultDestination(playerId, unit),
      avoidCombat: false,
      minokagePowerTarget: Boolean(entry),
    };
  } else if (modeId === 'offensive' && isOdaNoKageUnit(unit)) {
    // v9.61 · Sombra del clan Oda: la IA reevalúa en cada decisión automática si Nobunaga aliado está activo.
// Si la casilla posterior queda libre, Oda no Kage prioriza inmediatamente el vínculo; no exige proximidad previa.
// v9.60 · Oda no Kage Ofensivo no hereda el eje casi-Asesinato del perfil
    // genérico. Si existe una Invocación rival cercana, la persigue hasta entrar
    // en su Alcance 2 y ejecutar Oscilación; si no, continúa presionando al Kaster.
    const entry = chooseRealtimeOdaOffensiveInvocation(playerId, unit);
    const target = buildRealtimeTargetFromUnitEntry(entry) || getRealtimeEnemyCasterTarget(playerId);
    intent = {
      modeId: 'offensive',
      profile: REALTIME_COMBAT_MODE_DB.offensive,
      target,
      destination: target || getRealtimeDefaultDestination(playerId, unit),
      avoidCombat: false,
      odaOffensivePressure: Boolean(entry),
    };
  } else {
    // Ofensivo no caza la Invocación de mayor PB por todo el tablero. Su eje de
    // avance es el Kaster rival; las Invocaciones se limpian cuando realmente
    // quedan en el corredor de presión o bloquean físicamente la ruta.
    const casterTarget = getRealtimeEnemyCasterTarget(playerId);
    intent = {
      modeId: 'offensive',
      profile: REALTIME_COMBAT_MODE_DB.offensive,
      target: casterTarget,
      destination: casterTarget || getRealtimeDefaultDestination(playerId, unit),
      avoidCombat: false,
      clearPath: true,
    };
  }

  return applyRealtimeArenaAffordanceIntent(playerId, unit, intent);
}

function realtimeTargetsMatch(a, b) {
  if (!a || !b || String(a.type || '') !== String(b.type || '') || Number(a.playerId) !== Number(b.playerId)) return false;
  if (a.type === 'caster') return true;
  if (a.type === 'invocation') return String(a.unitId || '') === String(b.unitId || '');
  if (a.type === 'guardian') return String(a.guardianId || '') === String(b.guardianId || '');
  return false;
}

function getRealtimeDefensiveThreatEntries(playerId) {
  const enemyId = getEnemyPlayerId(playerId);
  const entries = getRealtimeEnemyInvocationCandidates(playerId).map(entry => {
    const attack = getEffectiveAttackProfile?.(entry.card, entry.unit, enemyId) || getAttackProfile?.(entry.card) || {};
    return {
      type: 'invocation',
      row: Number(entry.unit.row),
      col: Number(entry.unit.col),
      range: Math.max(1, Number(attack.range ?? 1)),
    };
  });
  const caster = state.players?.[enemyId]?.caster;
  if (caster && Number(caster.life ?? 0) > 0) {
    const casterCard = CARD_LIBRARY?.[caster.cardId];
    const attack = getEffectiveAttackProfile?.(casterCard, caster, enemyId) || getAttackProfile?.(casterCard) || {};
    entries.push({ type: 'caster', row: Number(caster.row), col: Number(caster.col), range: Math.max(1, Number(attack.range ?? 1)) });
  }
  return entries;
}

function getRealtimeDefensiveSafetyMarginAt(row, col, threats) {
  if (!Array.isArray(threats) || !threats.length) return 999;
  return threats.reduce((lowest, threat) => {
    const margin = ringDistance(row, col, threat.row, threat.col) - Math.max(1, Number(threat.range || 1));
    return Math.min(lowest, margin);
  }, 999);
}

function isRealtimeRowOnOwnSide(playerId, row) {
  return Number(playerId) === 1 ? Number(row) >= 9 : Number(row) <= 8;
}

function chooseRealtimeDefensiveStep(playerId, unit) {
  if (!unit) return null;
  // Si la unidad ya está Oculta, Defensivo no rompe voluntariamente la postura
  // moviéndose por rutina. Sigue siendo alcanzable por reglas de área existentes.
  if (isRealtimeCombatModeTargetConcealed(unit)) return null;
  unit.movesLeft = 1;
  const options = getInvocationMovementOptionsForUnit(playerId, unit);
  if (!options.length) return null;
  const threats = getRealtimeDefensiveThreatEntries(playerId);
  if (!threats.length) return null;
  const restoreRow = Number(unit.restoreRow ?? unit.row);
  const restoreCol = Number(unit.restoreCol ?? unit.col);
  const hasVigilia = Boolean(unitHasAbility?.(unit, 'vigilia'));
  const hasAcechar = Boolean(unitHasAbility?.(unit, 'stalk'));
  const startsOwnSide = isRealtimeRowOnOwnSide(playerId, unit.row);
  const tacticalSide = hasVigilia && startsOwnSide ? 'own' : (hasAcechar && !startsOwnSide ? 'enemy' : '');
  const preservesTacticalSide = row => (
    tacticalSide === 'own' ? isRealtimeRowOnOwnSide(playerId, row)
      : tacticalSide === 'enemy' ? !isRealtimeRowOnOwnSide(playerId, row)
        : true
  );
  const scoreAt = (row, col) => {
    const safety = getRealtimeDefensiveSafetyMarginAt(row, col, threats);
    const ownSideBonus = isRealtimeRowOnOwnSide(playerId, row) ? 12 : 0;
    const tacticalSideBonus = preservesTacticalSide(row) ? (tacticalSide ? 55 : 0) : -90;
    const nexusDistance = ringDistance(row, col, restoreRow, restoreCol);
    const setupScore = getRealtimeDefensiveSetupPositionScore(playerId, unit, row, col);
    return {
      safety,
      setupScore,
      score: safety * 100 + ownSideBonus + tacticalSideBonus + setupScore * 0.72 - nexusDistance * 0.35,
    };
  };
  const current = scoreAt(unit.row, unit.col);
  const sameSideOptions = options.filter(option => preservesTacticalSide(option.row));
  const candidateOptions = tacticalSide && sameSideOptions.length ? sameSideOptions : options;
  const ranked = candidateOptions
    .map(option => ({ ...option, ...scoreAt(option.row, option.col) }))
    .sort((a, b) => b.score - a.score);
  const best = ranked[0];
  if (!best) return null;

  if (current.safety >= REALTIME_DEFENSIVE_SAFE_MARGIN) {
    const setupGain = Number(best.setupScore || 0) - Number(current.setupScore || 0);
    if (setupGain < 32 || best.safety < REALTIME_DEFENSIVE_SAFE_MARGIN) return null;
  }

  if (best.score <= current.score + 0.01) return null;
  if (Number(best.setupScore || 0) > Number(current.setupScore || 0) + 20) {
    unit.realtimeSupportPlan = {
      actionId: 'defensiveSetupMove',
      targetUnitId: unit.id,
      targetCardId: unit.cardId,
      score: Number(best.setupScore || 0),
      modeId: 'defensive',
      destination: { row: best.row, col: best.col },
      tags: ['support', 'enable_setup', 'positioning'],
    };
  }
  return best;
}


const invocationControlOrderRuntime = {
  order: [],
  pinnedUnitId: null,
};

function syncInvocationControlStableOrder(units = []) {
  const liveIds = (Array.isArray(units) ? units : [])
    .map(unit => String(unit?.id ?? ''))
    .filter(Boolean);
  const liveSet = new Set(liveIds);

  invocationControlOrderRuntime.order = invocationControlOrderRuntime.order
    .filter(id => liveSet.has(String(id)));

  liveIds.forEach(id => {
    if (!invocationControlOrderRuntime.order.includes(id)) {
      invocationControlOrderRuntime.order.push(id);
    }
  });

  if (invocationControlOrderRuntime.pinnedUnitId
      && !liveSet.has(String(invocationControlOrderRuntime.pinnedUnitId))) {
    invocationControlOrderRuntime.pinnedUnitId = null;
  }
  return invocationControlOrderRuntime.order;
}

function pinInvocationControlUnit(playerId, unitId, options = {}) {
  if (Number(playerId) !== Number(LOCAL_PLAYER_ID) || unitId == null) return false;
  const id = String(unitId);
  invocationControlOrderRuntime.pinnedUnitId = id;
  if (!invocationControlOrderRuntime.order.includes(id)) {
    invocationControlOrderRuntime.order.push(id);
  }
  if (options.render !== false) {
    window.requestAnimationFrame(() => {
      try { renderRealtimeCombatModePanel(); } catch (_) {}
    });
  }
  return true;
}

function getOrderedInvocationControlUnits(units = []) {
  syncInvocationControlStableOrder(units);
  const byId = new Map((Array.isArray(units) ? units : []).map(unit => [String(unit.id), unit]));
  const ordered = invocationControlOrderRuntime.order.map(id => byId.get(String(id))).filter(Boolean);
  const pinnedId = invocationControlOrderRuntime.pinnedUnitId ? String(invocationControlOrderRuntime.pinnedUnitId) : '';
  if (!pinnedId) return ordered;
  const pinnedIndex = ordered.findIndex(unit => String(unit.id) === pinnedId);
  if (pinnedIndex <= 0) return ordered;
  const [pinned] = ordered.splice(pinnedIndex, 1);
  ordered.unshift(pinned);
  return ordered;
}

function buildPersistentInvocationPanelContext(playerId, unit) {
  const card = unit ? CARD_LIBRARY?.[unit.cardId] : null;
  if (!unit || !card) return null;
  return {
    selectionType: 'invocation',
    playerId,
    unitId: unit.id,
    unit,
    card,
    label: card.name || 'Invocación',
    statusOnly: false,
    linkedSpellLinks: getUnitLinkedSpellLinks(playerId, unit.id),
  };
}


function createInvocationPanelPowerControls(playerId, unit) {
  const wrap = document.createElement('div');
  wrap.className = 'invocation-panel-power-section';

  if (isNeruUnit(unit)) {
    const cooldown = getNeruEscapeCooldownRemaining(unit);
    const silenced = unitHasSilence(unit);
    const status = document.createElement('div');
    status.className = `neru-escape-panel${cooldown <= 0 && !silenced ? ' is-ready' : ''}`;
    status.innerHTML = `
      <span>SALTO INSTINTIVO</span>
      <b>${silenced ? 'SILENCIADO' : (cooldown > 0 ? `CD ${cooldown}` : 'LISTO')}</b>
      <small>SILENCIO 3 · 4 PDA · RANGO 3</small>
    `;
    status.title = silenced
      ? 'Silencio impide activar Salto Instintivo.'
      : (cooldown > 0
        ? `Salto Instintivo vuelve a estar disponible en ${cooldown} fase${cooldown === 1 ? '' : 's'}.`
        : 'La próxima Invocación rival que seleccione a Neru para atacarlo puede hacer que se teletransporte hasta 3 casillas.');
    wrap.appendChild(status);
    return wrap;
  }

  if (isEdranUnit(unit)) {
    const points = getEdranResonancePoints(unit);
    const bonus = getEdranDamageBonus(unit);
    const radius = getEdranAreaRadius(unit);

    const status = document.createElement('div');
    status.className = `edran-resonance-panel${radius > 0 ? ' is-area' : ''}`;
    status.innerHTML = `
      <span>RESONANCIA</span>
      <b>${points} pts · DAÑO +${bonus}</b>
      <small>${radius > 0 ? `ATAQUE EN ÁREA · RADIO ${radius}` : `FALTAN ${Math.max(0, 4 - points)} pts PARA ÁREA`}</small>
    `;
    status.title = radius > 0
      ? `Daño actual ${Number(getEffectiveAttackProfile(CARD_LIBRARY[unit.cardId], unit, playerId)?.damage || 0)} · área radio ${radius}. La carga se conserva mientras Edran permanezca en Arena.`
      : 'Cada 2 puntos de Resonancia otorgan +1 Daño. Con +2 Daño acumulado se activa el ataque en área.';
    wrap.appendChild(status);
    return wrap;
  }

  if (!unitHasConfigurableActivePower(playerId, unit)) {
    wrap.hidden = true;
    return wrap;
  }

  const mode = getInvocationPowerAutomationMode(playerId, unit);
  const readiness = getInvocationPowerReadinessState(playerId, unit);

  const row = document.createElement('div');
  row.className = 'invocation-power-toggle-row';
  const label = document.createElement('span');
  label.className = 'invocation-power-toggle-label';
  label.textContent = 'PODER AUTOMÁTICO';

  const toggle = document.createElement('button');
  toggle.type = 'button';
  toggle.className = `invocation-power-toggle is-${mode}`;
  toggle.setAttribute('role', 'switch');
  toggle.setAttribute('aria-checked', mode === 'auto' ? 'true' : 'false');
  toggle.innerHTML = `<span class="invocation-power-toggle-track"><i></i></span><b>${mode === 'auto' ? 'AUTO' : 'MANUAL'}</b>`;
  toggle.addEventListener('click', event => {
    event.preventDefault();
    event.stopPropagation();
    setInvocationPowerAutomationMode(playerId, unit.id, mode === 'auto' ? 'manual' : 'auto');
  });
  row.append(label, toggle);
  wrap.appendChild(row);

  const maerynCooldown = isMaerynUnit(unit) ? getMaerynDominationCooldownRemaining(unit) : 0;
  if (isMaerynUnit(unit)) {
    const dominated = getMaerynDominatedCount(playerId, unit);
    const influence = getMaerynInfluencePoints(unit);
    const totalInfluence = getMaerynInfluenceTotal(unit);
    const supremacy = isMaerynSupremacyActive(playerId, unit);
    const status = document.createElement('div');
    status.className = `maeryn-mind-panel${supremacy ? ' is-supremacy' : ''}`;
    status.innerHTML = `
      <span>MENTE COLECTIVA</span>
      <b>${influence}/${MAERYN_INFLUENCE_PER_REDUCTION} · TOTAL ${totalInfluence}</b>
      <small>CONTROL ${dominated} · ${supremacy ? 'SUPREMACÍA · ALC 6 · ÁREA 1' : `DOMINACIÓN CD ${maerynCooldown}`}</small>
    `;
    status.title = supremacy
      ? 'Supremacía Psíquica activa: 2 o más Invocaciones rivales dominadas. Alcance 6 y área radio 1.'
      : `Dominación Mental: CD ${maerynCooldown}. Cada 3 Influencias reducen 3 fases adicionales.`;
    wrap.appendChild(status);
  }

  const seyranCooldown = isSeyranUnit(unit) ? getSeyranDistortionCooldownRemaining(unit) : 0;
  if (seyranCooldown > 0) {
    const cooldown = document.createElement('small');
    cooldown.className = 'invocation-power-readiness is-cooldown invocation-seyran-cooldown';
    cooldown.innerHTML = `<span>ENFRIAMIENTO</span><b>${seyranCooldown}</b>`;
    cooldown.title = `Distorsión Espacial · ${seyranCooldown} fase${seyranCooldown === 1 ? '' : 's'} restante${seyranCooldown === 1 ? '' : 's'}`;
    wrap.appendChild(cooldown);
  }

  if (maerynCooldown > 0) {
    const cooldown = document.createElement('small');
    cooldown.className = 'invocation-power-readiness is-cooldown invocation-maeryn-cooldown';
    cooldown.innerHTML = `<span>DOMINACIÓN · ENFRIAMIENTO</span><b>${maerynCooldown}</b>`;
    cooldown.title = `Dominación Mental · ${maerynCooldown} fase${maerynCooldown === 1 ? '' : 's'} restante${maerynCooldown === 1 ? '' : 's'}`;
    wrap.appendChild(cooldown);
  }

  const minokageCooldown = isMinokageUnit(unit) ? getMinokagePowerCooldownRemaining(unit) : 0;
  if (minokageCooldown > 0) {
    const cooldown = document.createElement('small');
    cooldown.className = 'invocation-power-readiness is-cooldown invocation-minokage-cooldown';
    cooldown.innerHTML = `<span>ENFRIAMIENTO</span><b>${minokageCooldown}</b>`;
    cooldown.title = `Shippū Ugachi · ${minokageCooldown} fase${minokageCooldown === 1 ? '' : 's'} restante${minokageCooldown === 1 ? '' : 's'}`;
    wrap.appendChild(cooldown);
  }

  if (mode === 'manual') {
    const btn = document.createElement('button');
    btn.type = 'button';
    if (isRealtimePlayStyle()) {
      if (minokageCooldown > 0) {
        btn.className = 'invocation-manual-power-btn is-cooldown';
        btn.textContent = `ENFRIAMIENTO · ${minokageCooldown}`;
        btn.disabled = true;
        btn.title = `Shippū Ugachi vuelve a estar disponible en ${minokageCooldown} ciclo${minokageCooldown === 1 ? '' : 's'} de Tempo.`;
        const status = document.createElement('small');
        status.className = 'invocation-power-readiness is-cooldown';
        status.textContent = `BLOQUEADA · ${minokageCooldown} RESTANTE${minokageCooldown === 1 ? '' : 'S'}`;
        wrap.append(btn, status);
      } else {
        const stateId = readiness.armed ? 'armed' : (readiness.ready ? 'ready' : (readiness.near ? 'near' : 'idle'));
        btn.className = `invocation-manual-power-btn is-${stateId}`;
        btn.textContent = readiness.armed ? 'HABILIDAD ARMADA' : (readiness.ready ? 'ACTIVAR HABILIDAD' : 'PREPARAR HABILIDAD');
        btn.addEventListener('click', event => {
          event.preventDefault();
          event.stopPropagation();
          setInvocationRealtimePowerArmed(playerId, unit.id, !readiness.armed);
        });
        const status = document.createElement('small');
        status.className = `invocation-power-readiness is-${stateId}`;
        status.textContent = readiness.armed
          ? (readiness.ready ? 'ARMADA · DISPONIBLE' : 'ARMADA · EN STANDBY')
          : (readiness.ready ? 'DISPONIBLE AHORA' : (readiness.near ? 'PRÓXIMA A RANGO/CONDICIÓN' : 'ESPERANDO OPORTUNIDAD'));
        wrap.append(btn, status);
      }
    } else {
      const action = readiness.actions[0] || null;
      btn.className = `invocation-manual-power-btn ${action ? 'is-ready' : 'is-idle'}`;
      btn.textContent = action?.label || 'PODER';
      btn.disabled = !action;
      if (action) btn.addEventListener('click', event => {
        event.preventDefault();
        event.stopPropagation();
        action.execute?.(event);
      });
      wrap.appendChild(btn);
    }
  }
  return wrap;
}

function createInvocationPanelModeControls(playerId, unit) {
  const wrap = document.createElement('div');
  wrap.className = 'invocation-panel-mode-section';
  if (!isRealtimePlayStyle()) return wrap;

  const profile = getRealtimeCombatModeProfileForUnit(playerId, unit);
  if (!profile || !profile.allowedIds?.length) {
    wrap.hidden = true;
    return wrap;
  }

  const title = document.createElement('div');
  title.className = 'invocation-panel-mode-title';
  const label = document.createElement('span');
  label.textContent = 'MODO';
  const current = document.createElement('b');
  current.textContent = profile.active?.label || 'Ofensiva';
  title.append(label, current);
  wrap.appendChild(title);

  const buttons = document.createElement('div');
  buttons.className = 'invocation-panel-mode-buttons';
  (profile.allowed || []).forEach(mode => {
    const button = document.createElement('button');
    button.type = 'button';
    button.className = `realtime-combat-mode-btn invocation-panel-mode-btn${mode.id === profile.activeId ? ' is-active' : ''}`;
    button.setAttribute('aria-pressed', mode.id === profile.activeId ? 'true' : 'false');
    button.title = mode.description;
    const strong = document.createElement('strong');
    strong.textContent = mode.label;
    const small = document.createElement('small');
    small.textContent = mode.shortLabel;
    button.append(strong, small);
    button.addEventListener('click', event => {
      event.preventDefault();
      event.stopPropagation();
      setRealtimeCombatModeForUnit(playerId, unit.id, mode.id);
    });
    buttons.appendChild(button);
  });
  wrap.appendChild(buttons);

  const description = document.createElement('small');
  description.className = 'invocation-panel-mode-description';
  description.textContent = profile.active?.description || '';
  wrap.appendChild(description);
  return wrap;
}


function getInvocationPanelTargetVisual(target, viewerPlayerId = LOCAL_PLAYER_ID) {
  if (!target) return null;

  if (target.type === 'invocation') {
    const unit = getUnitById(target.playerId, target.unitId);
    if (!unit) return null;
    const concealed = isOnlineUnitConcealedFromViewer(target.playerId, unit, viewerPlayerId);
    if (concealed) {
      return {
        type: 'invocation',
        label: 'OBJETIVO OCULTO',
        sublabel: 'Identidad protegida por Oculto',
        image: '',
        value: '',
        concealed: true,
      };
    }
    const card = CARD_LIBRARY?.[unit.cardId];
    return {
      type: 'invocation',
      label: card?.shortName || card?.name || 'Invocación',
      sublabel: `VIDA ${Math.max(0, Number(unit.hp ?? 0))}`,
      image: card?.tokenImage || card?.artImage || '',
      value: Math.max(0, Number(unit.hp ?? 0)),
      concealed: false,
    };
  }

  if (target.type === 'guardian') {
    const guardian = state.players?.[target.playerId]?.guardians?.find(item => String(item.id) === String(target.guardianId));
    if (!guardian) return null;
    return {
      type: 'guardian',
      label: 'GUARDIÁN',
      sublabel: `RESISTENCIA ${Math.max(0, Number(guardian.resistance ?? 0))}`,
      image: getGuardianAssetForPlayer(target.playerId),
      value: Math.max(0, Number(guardian.resistance ?? 0)),
      concealed: false,
    };
  }

  if (target.type === 'caster') {
    const caster = state.players?.[target.playerId]?.caster;
    return {
      type: 'caster',
      label: getCasterDisplayName(caster, `Kaster J${target.playerId}`),
      sublabel: `VIDA ${Math.max(0, Number(caster?.hp ?? caster?.life ?? 0))}`,
      image: caster ? getCasterTokenImage(caster) : '',
      value: Math.max(0, Number(caster?.hp ?? caster?.life ?? 0)),
      concealed: false,
    };
  }

  return null;
}

function getInvocationPanelCombatState(playerId, unit) {
  if (!unit || unit.status === 'restoring') return null;

  if (unit.engagedWith?.unitId != null) {
    const target = {
      type: 'invocation',
      playerId: Number(unit.engagedWith.playerId),
      unitId: unit.engagedWith.unitId,
    };
    const visual = getInvocationPanelTargetVisual(target, LOCAL_PLAYER_ID);
    if (visual) {
      const combatMode = String(unit.engagedWith.combatMode || '').toLowerCase();
      return {
        kind: 'engagement',
        title: 'EN COMBATE',
        detail: combatMode === 'range' ? 'ENFRENTAMIENTO A RANGO' : 'ENFRENTAMIENTO DIRECTO',
        target,
        visual,
      };
    }
  }

  if (unit.structureAttackTarget?.type === 'guardian') {
    const target = {
      type: 'guardian',
      playerId: Number(unit.structureAttackTarget.playerId),
      guardianId: unit.structureAttackTarget.guardianId,
    };
    const visual = getInvocationPanelTargetVisual(target, LOCAL_PLAYER_ID);
    if (visual) {
      return {
        kind: 'structure',
        title: 'ATACANDO ESTRUCTURA',
        detail: 'ANCLAJE DE ATAQUE ACTIVO',
        target,
        visual,
      };
    }
  }

  if (isRealtimePlayStyle() && unit.realtimeAttackTelegraph?.target) {
    const descriptor = unit.realtimeAttackTelegraph.target;
    const target = {
      type: descriptor.type,
      playerId: Number(descriptor.playerId || 0),
      unitId: descriptor.unitId || null,
      guardianId: descriptor.guardianId || null,
    };
    const visual = getInvocationPanelTargetVisual(target, LOCAL_PLAYER_ID);
    if (visual) {
      const remainingMs = Math.max(0, Number(unit.realtimeAttackTelegraph.readyAtMs || 0) - getRealtimeActiveElapsedMs());
      return {
        kind: 'preparing',
        title: 'PREPARANDO ATAQUE',
        detail: `${(remainingMs / 1000).toFixed(1)}s`,
        target,
        visual,
      };
    }
  }

  return null;
}

function createInvocationPanelCombatSection(playerId, unit) {
  const stateInfo = getInvocationPanelCombatState(playerId, unit);
  const section = document.createElement('div');
  section.className = 'invocation-panel-combat-section';
  if (!stateInfo) {
    section.hidden = true;
    return section;
  }

  section.classList.add(`is-${stateInfo.kind}`);

  const head = document.createElement('div');
  head.className = 'invocation-panel-combat-head';
  const title = document.createElement('strong');
  title.textContent = stateInfo.title;
  const detail = document.createElement('small');
  detail.textContent = stateInfo.detail;
  head.append(title, detail);

  const target = document.createElement('button');
  target.type = 'button';
  target.className = `invocation-panel-combat-target target-${stateInfo.visual.type}${stateInfo.visual.concealed ? ' is-concealed' : ''}`;
  target.title = stateInfo.visual.label;

  const art = document.createElement('span');
  art.className = 'invocation-panel-combat-target-art';
  if (stateInfo.visual.image && !stateInfo.visual.concealed) {
    const img = document.createElement('img');
    img.src = stateInfo.visual.image;
    img.alt = stateInfo.visual.label;
    art.appendChild(img);
  } else {
    art.textContent = '?';
  }

  const copy = document.createElement('span');
  copy.className = 'invocation-panel-combat-target-copy';
  const name = document.createElement('b');
  name.textContent = stateInfo.visual.label;
  const sub = document.createElement('small');
  sub.textContent = stateInfo.visual.sublabel;
  copy.append(name, sub);
  target.append(art, copy);

  if (!stateInfo.visual.concealed) {
    target.addEventListener('click', event => {
      event.preventDefault();
      event.stopPropagation();
      if (stateInfo.target.type === 'invocation') {
        const targetUnit = getUnitById(stateInfo.target.playerId, stateInfo.target.unitId);
        if (targetUnit?.cardId) {
          openCardInfo(targetUnit.cardId, null, null, {
            source: 'arena',
            playerId: stateInfo.target.playerId,
            unitId: targetUnit.id,
          });
        }
      } else if (stateInfo.target.type === 'caster') {
        openKasterInfo(stateInfo.target.playerId);
      }
    });
  } else {
    target.disabled = true;
  }

  section.append(head, target);
  return section;
}

function renderInvocationPanelThreats() {
  const host = els.invocationControlThreats;
  if (!host) return false;
  const localGuardianGroups = getGuardianCombatGroups().filter(group =>
    Number(group?.guardianSide?.playerId) === Number(LOCAL_PLAYER_ID)
    && (group.targets || []).some(target => Number(target.playerId) !== Number(LOCAL_PLAYER_ID))
  );

  host.replaceChildren();
  if (!localGuardianGroups.length) {
    host.hidden = true;
    return false;
  }

  host.hidden = false;
  const title = document.createElement('div');
  title.className = 'invocation-control-subhead invocation-control-threat-head';
  title.innerHTML = `<span>AMENAZAS</span><b>${localGuardianGroups.reduce((sum, group) => sum + group.targets.filter(t => Number(t.playerId) !== Number(LOCAL_PLAYER_ID)).length, 0)}</b>`;
  host.appendChild(title);

  localGuardianGroups.forEach(group => {
    const enemies = group.targets.filter(target => Number(target.playerId) !== Number(LOCAL_PLAYER_ID));
    enemies.forEach(target => {
      const card = CARD_LIBRARY?.[target.unit?.cardId];
      const row = document.createElement('div');
      row.className = 'invocation-control-threat-row';

      const imgWrap = document.createElement('span');
      imgWrap.className = 'invocation-control-threat-art';
      const concealed = isOnlineUnitConcealedFromViewer(target.playerId, target.unit, LOCAL_PLAYER_ID);
      if (!concealed && card) {
        const img = document.createElement('img');
        img.src = card.tokenImage || card.artImage || '';
        img.alt = card.name || 'Invocación';
        imgWrap.appendChild(img);
      } else {
        imgWrap.textContent = '?';
      }

      const copy = document.createElement('span');
      const name = document.createElement('b');
      name.textContent = concealed ? 'INVOCACIÓN OCULTA' : (card?.shortName || card?.name || 'Invocación');
      const sub = document.createElement('small');
      sub.textContent = Number.isFinite(target.remaining)
        ? `GUARDIÁN BAJO ATAQUE · RAYO EN ${target.remaining}`
        : 'GUARDIÁN BAJO ATAQUE';
      copy.append(name, sub);
      row.append(imgWrap, copy);
      host.appendChild(row);
    });
  });
  return true;
}

function syncInvocationPanelEffectCount() {
  if (!els.invocationControlEffectCount || !els.arenaEffectTrackers) return;
  const count = els.arenaEffectTrackers.children.length;
  els.invocationControlEffectCount.textContent = String(count);
  const section = els.invocationControlEffectsHost?.closest?.('.invocation-control-arena-effects');
  if (section) section.hidden = count <= 0;
}

function createInvocationPanelArtPreview(context) {
  const card = context?.card;
  const wrap = document.createElement('div');
  wrap.className = 'invocation-panel-art-preview';
  if (!card) return wrap;

  const candidates = [card.artImage, card.tokenImage, card.bgImage].filter(Boolean);
  if (!candidates.length) {
    wrap.classList.add('invocation-panel-art-preview--empty');
    return wrap;
  }

  const img = document.createElement('img');
  img.className = 'invocation-panel-art-preview-image';
  img.alt = card.name || 'Arte de la Invocación';
  let assetIndex = 0;
  img.src = candidates[assetIndex];
  img.addEventListener('error', () => {
    assetIndex += 1;
    if (assetIndex < candidates.length) {
      img.src = candidates[assetIndex];
      return;
    }
    img.remove();
    wrap.classList.add('invocation-panel-art-preview--empty');
  });
  wrap.appendChild(img);
  return wrap;
}

function createPersistentInvocationPanelItem(playerId, unit) {
  const context = buildPersistentInvocationPanelContext(playerId, unit);
  if (!context) return null;

  const item = document.createElement('article');
  item.className = 'invocation-control-item invocation-control-card-item invocation-control-card-item--structured';
  item.dataset.playerId = String(playerId);
  item.dataset.unitId = String(unit.id);
  item.dataset.cardId = String(unit.cardId || '');
  item.title = context.label;
  if (String(invocationControlOrderRuntime.pinnedUnitId || '') === String(unit.id)) {
    item.classList.add('is-pinned');
  }

  const layout = document.createElement('div');
  layout.className = 'invocation-control-structured-layout';

  // La miniatura es la ÚNICA identificación visual de la carta dentro del panel.
  const thumb = document.createElement('div');
  thumb.className = 'invocation-control-structured-thumb invocation-control-art-host';
  thumb.appendChild(createInvocationPanelArtPreview(context));

  const operations = document.createElement('div');
  operations.className = 'invocation-control-structured-operations';

  const utilityRow = document.createElement('div');
  utilityRow.className = 'invocation-control-structured-utility';

  const infoAction = createSelectedUnitCommandActionDescriptors(context, { includeInfo: true, includePower: false })
    .find(action => action.id === 'info');
  const infoBtn = document.createElement('button');
  infoBtn.type = 'button';
  infoBtn.className = 'invocation-panel-overlay-btn invocation-panel-info-btn invocation-control-structured-info';
  infoBtn.textContent = 'INFO';
  infoBtn.title = 'Información de la carta';
  infoBtn.addEventListener('click', event => {
    event.preventDefault();
    event.stopPropagation();
    if (infoAction?.onClick) infoAction.onClick(event);
    else openCardInfo(unit.cardId, null, null, { source: 'arena', playerId, unitId: unit.id });
  });
  utilityRow.appendChild(infoBtn);

  const statusRow = document.createElement('div');
  statusRow.className = 'selected-unit-command-statuses invocation-control-statuses invocation-control-structured-statuses';
  buildSelectedUnitCommandStatusEntries(context).forEach(entry => {
    const node = document.createElement('button');
    node.type = 'button';
    node.className = `selected-unit-command-status selected-unit-command-status-${entry.kind}`;
    node.title = entry.title || entry.label;
    if (entry.icon) {
      const img = document.createElement('img');
      img.src = entry.icon;
      img.alt = entry.label;
      img.className = 'selected-unit-command-status-icon';
      node.appendChild(img);
    } else if (entry.iconSvg) {
      const iconWrap = document.createElement('span');
      iconWrap.className = 'selected-unit-command-status-svg';
      iconWrap.innerHTML = entry.iconSvg;
      node.appendChild(iconWrap);
    }
    if (entry.count != null) {
      const bubble = document.createElement('span');
      bubble.className = 'selected-unit-command-status-count';
      bubble.textContent = String(entry.count);
      node.appendChild(bubble);
    }
    if (typeof entry.onClick === 'function') node.addEventListener('click', entry.onClick);
    statusRow.appendChild(node);
  });

  const power = createInvocationPanelPowerControls(playerId, unit);
  power.classList.add('invocation-control-structured-power');

  const combat = createInvocationPanelCombatSection(playerId, unit);
  combat.classList.add('invocation-control-structured-combat');

  operations.append(utilityRow, statusRow, power, combat);

  const modes = createInvocationPanelModeControls(playerId, unit);
  modes.classList.add('invocation-control-structured-modes');

  layout.append(thumb, operations, modes);
  item.appendChild(layout);

  // En Manual, tocar una zona libre de la ficha selecciona la Invocación.
  // En RT los controles permanecen operativos sin necesidad de seleccionar el Nexo.
  item.addEventListener('click', event => {
    if (event.target.closest('button')) return;
    if (!isRealtimePlayStyle()
        && currentPhase().id === 'resolution'
        && Number(state.activePlayer) === Number(playerId)
        && Number(playerId) === Number(LOCAL_PLAYER_ID)) {
      selectMover('invocation', playerId, unit.id);
      renderAll();
    }
  });

  return item;
}

function renderRealtimeCombatModePanel() {
  const panel = els.realtimeCombatModePanel;
  const dock = els.realtimeCombatModeDock;
  const list = els.invocationControlList;
  if (!panel || !dock || !list) return;

  const active = document.body.classList.contains('rok-battle-mode');
  panel.setAttribute('aria-hidden', active ? 'false' : 'true');
  dock.setAttribute('aria-hidden', active ? 'false' : 'true');
  if (!active) {
    list.replaceChildren();
    return;
  }

  const localColor = getPlayerElementColor?.(LOCAL_PLAYER_ID) || '#00ffe4';
  panel.style.setProperty('--rt-mode-color', localColor);
  dock.style.setProperty('--rt-mode-color', localColor);

  const liveUnits = (state.players?.[LOCAL_PLAYER_ID]?.units || [])
    .filter(unit => unit && unit.status !== 'restoring' && Number(unit.hp ?? 1) > 0);
  const units = getOrderedInvocationControlUnits(liveUnits);

  if (els.realtimeCombatModeCurrent) {
    els.realtimeCombatModeCurrent.textContent = `${units.length} EN ARENA`;
  }
  if (els.realtimeCombatModeHint) {
    els.realtimeCombatModeHint.textContent = isRealtimePlayStyle()
      ? 'Info, estados y Modo de combate quedan visibles sin seleccionar el Nexo.'
      : 'Info, Poder y estados de tus Invocaciones quedan visibles durante el turno.';
  }

  renderInvocationPanelThreats();
  syncInvocationPanelEffectCount();

  if (!units.length) {
    const empty = document.createElement('div');
    empty.className = 'invocation-control-empty';
    const strong = document.createElement('strong');
    strong.textContent = 'SIN INVOCACIONES';
    const small = document.createElement('small');
    small.textContent = 'Cuando kastees una Invocación, su ficha aparecerá aquí.';
    empty.append(strong, small);
    list.replaceChildren(empty);
    return;
  }

  const fragment = document.createDocumentFragment();
  units.forEach(unit => {
    const item = createPersistentInvocationPanelItem(LOCAL_PLAYER_ID, unit);
    if (item) fragment.appendChild(item);
  });
  list.replaceChildren(fragment);
}


// v9.21 · Suavizado visual del desplazamiento en Tiempo Real.
// La lógica continúa siendo estrictamente de casilla a casilla. Esta capa solo
// interpola left/top del token entre el centro de la casilla anterior y la nueva.
// De este modo no se alteran alcance, colisiones, rutas ni ocupación del tablero.
const realtimeSmoothMotionRuntime = {
  tracks: new Map(),
  logical: new Map(),
};

function getRealtimeSmoothMotionKey(type, playerId, entityId = null) {
  if (type === 'caster') return `caster:${Number(playerId || 0)}`;
  if (type === 'invocation') return `invocation:${Number(playerId || 0)}:${String(entityId || '')}`;
  return '';
}

function resetRealtimeSmoothMotionRuntime() {
  realtimeSmoothMotionRuntime.tracks.clear();
  realtimeSmoothMotionRuntime.logical.clear();
  if (realtimeBoundFxSyncRuntime?.raf) {
    cancelAnimationFrame(realtimeBoundFxSyncRuntime.raf);
    realtimeBoundFxSyncRuntime.raf = 0;
  }
  realtimeBoundFxSyncRuntime.finalFramePending = false;
  clearRealtimeCasterDestinationCue();
}


// v9.37 · Restauración y teletransportes no son locomoción. Al sacar una
// Invocación del campo cancelamos cualquier tramo suave que estuviera vivo y
// reanclamos el cache lógico directamente al destino. Así, cuando la ficha
// reaparece en el Nexo, nunca intenta recorrer la distancia usando su Velocidad.
function anchorRealtimeInvocationMotion(playerId, unitId, row, col) {
  if (!unitId) return false;
  const key = getRealtimeSmoothMotionKey('invocation', Number(playerId), unitId);
  if (!key) return false;
  realtimeSmoothMotionRuntime.tracks.delete(key);
  if (Number.isFinite(Number(row)) && Number.isFinite(Number(col))) {
    realtimeSmoothMotionRuntime.logical.set(key, { row: Number(row), col: Number(col) });
  } else {
    realtimeSmoothMotionRuntime.logical.delete(key);
  }
  return true;
}

// v9.22 · Indicador de destino inmediato del Kaster local. La casilla iluminada
// es la casilla a la que el Kaster se está desplazando VISUALMENTE en este
// instante, no una casilla futura de la ruta. Esto permite cambiar de W/A/S/D
// con precisión mientras el paso de 2 s todavía está en curso.
const realtimeCasterDestinationCueRuntime = {
  timer: 0,
  serial: 0,
  row: null,
  col: null,
};

function clearRealtimeCasterDestinationCue() {
  realtimeCasterDestinationCueRuntime.serial += 1;
  if (realtimeCasterDestinationCueRuntime.timer) {
    window.clearTimeout(realtimeCasterDestinationCueRuntime.timer);
    realtimeCasterDestinationCueRuntime.timer = 0;
  }
  document.querySelectorAll('.cell.rt-caster-destination-cue').forEach(cell => {
    cell.classList.remove('rt-caster-destination-cue');
    cell.style.removeProperty('--rt-caster-destination-color');
  });
  realtimeCasterDestinationCueRuntime.row = null;
  realtimeCasterDestinationCueRuntime.col = null;
}

function renderRealtimeCasterDestinationCue() {
  // Limpiar la marca anterior sin invalidar el serial hasta conocer la nueva.
  document.querySelectorAll('.cell.rt-caster-destination-cue').forEach(cell => {
    cell.classList.remove('rt-caster-destination-cue');
    cell.style.removeProperty('--rt-caster-destination-color');
  });
  if (realtimeCasterDestinationCueRuntime.timer) {
    window.clearTimeout(realtimeCasterDestinationCueRuntime.timer);
    realtimeCasterDestinationCueRuntime.timer = 0;
  }
  if (!isRealtimePlayStyle() || !state?.realtime?.active || state.gameOver) {
    realtimeCasterDestinationCueRuntime.row = null;
    realtimeCasterDestinationCueRuntime.col = null;
    return false;
  }

  const playerId = Number(LOCAL_PLAYER_ID || 1);
  const key = getRealtimeSmoothMotionKey('caster', playerId, 'caster');
  const track = realtimeSmoothMotionRuntime.tracks.get(key);
  const now = performance.now();
  if (!track || now >= Number(track.endsAt || 0)) {
    realtimeCasterDestinationCueRuntime.row = null;
    realtimeCasterDestinationCueRuntime.col = null;
    return false;
  }

  const row = Number(track.toRow);
  const col = Number(track.toCol);
  const cell = getCellElement?.(row, col);
  if (!cell) return false;
  cell.classList.add('rt-caster-destination-cue');
  cell.style.setProperty('--rt-caster-destination-color', getPlayerElementColor?.(playerId) || '#00ffe4');
  realtimeCasterDestinationCueRuntime.row = row;
  realtimeCasterDestinationCueRuntime.col = col;

  const serial = ++realtimeCasterDestinationCueRuntime.serial;
  const remaining = Math.max(1, Number(track.endsAt || now) - now);
  realtimeCasterDestinationCueRuntime.timer = window.setTimeout(() => {
    if (serial !== realtimeCasterDestinationCueRuntime.serial) return;
    const activeTrack = realtimeSmoothMotionRuntime.tracks.get(key);
    const activeNow = performance.now();
    // Si ya arrancó el siguiente paso, renderizar de nuevo mueve el indicador
    // directamente a la nueva casilla sin parpadeo entre direcciones.
    if (activeTrack && activeNow < Number(activeTrack.endsAt || 0)) {
      renderRealtimeCasterDestinationCue();
      return;
    }
    document.querySelectorAll('.cell.rt-caster-destination-cue').forEach(node => {
      node.classList.remove('rt-caster-destination-cue');
      node.style.removeProperty('--rt-caster-destination-color');
    });
    realtimeCasterDestinationCueRuntime.timer = 0;
    realtimeCasterDestinationCueRuntime.row = null;
    realtimeCasterDestinationCueRuntime.col = null;
  }, remaining + 34);
  return true;
}

function getRealtimeSmoothMoveDurationMs(type, playerId, entityId = null) {
  // v9.22 · La animación ocupa TODA la cadencia real del paso. En v9.21 el
  // token llegaba visualmente demasiado pronto a la siguiente casilla y luego
  // quedaba quieto esperando el siguiente tick, lo que seguía pareciendo lag.
  // Ahora, si una unidad tarda 5 s por casilla, el tramo visual dura 5 s; si
  // tarda 1 s, dura 1 s. El Kaster usa su propia cadencia de teclado (2 s).
  if (type === 'caster') return Math.max(120, Number(REALTIME_CASTER_MOVE_COOLDOWN_MS || 2000));
  const unit = type === 'invocation' ? getUnitById?.(Number(playerId), entityId) : null;
  const intervalSeconds = unit ? getRealtimeMoveIntervalSecondsForUnit(unit) : 2;
  return Math.max(120, Math.round(Math.max(0.12, Number(intervalSeconds || 2)) * 1000));
}

function queueRealtimeSmoothMotion(type, playerId, entityId, fromRow, fromCol, toRow, toCol, durationMs = null) {
  if (!isRealtimePlayStyle() || !state?.realtime?.active) return false;
  const key = getRealtimeSmoothMotionKey(type, playerId, entityId);
  if (!key) return false;
  const startCell = cellCenter(Number(fromRow), Number(fromCol));
  const endCell = cellCenter(Number(toRow), Number(toCol));
  const now = performance.now();
  const existing = realtimeSmoothMotionRuntime.tracks.get(key);
  let start = startCell;
  if (existing && now < Number(existing.endsAt || 0)) {
    const span = Math.max(1, Number(existing.endsAt) - Number(existing.startedAt));
    const t = Math.max(0, Math.min(1, (now - Number(existing.startedAt)) / span));
    start = {
      x: Number(existing.fromX) + (Number(existing.toX) - Number(existing.fromX)) * t,
      y: Number(existing.fromY) + (Number(existing.toY) - Number(existing.fromY)) * t,
    };
  }
  const duration = Math.max(120, Number(durationMs ?? getRealtimeSmoothMoveDurationMs(type, playerId, entityId)) || 600);
  realtimeSmoothMotionRuntime.tracks.set(key, {
    fromX: Number(start.x),
    fromY: Number(start.y),
    toX: Number(endCell.x),
    toY: Number(endCell.y),
    startedAt: now,
    endsAt: now + duration,
    fromRow: Number(fromRow),
    fromCol: Number(fromCol),
    toRow: Number(toRow),
    toCol: Number(toCol),
  });
  // En movimientos locales explícitos ya conocemos el nuevo destino lógico.
  // Esto evita que renderUnit interprete el mismo paso una segunda vez.
  realtimeSmoothMotionRuntime.logical.set(key, { row: Number(toRow), col: Number(toCol) });
  scheduleRealtimeBoundFxMotionSync();
  return true;
}

function getRealtimeSmoothMotionSample(key, row, col) {
  const target = cellCenter(Number(row), Number(col));
  const track = key ? realtimeSmoothMotionRuntime.tracks.get(key) : null;
  if (!track) return { x: target.x, y: target.y, active: false, remainingMs: 0 };
  const now = performance.now();
  if (now >= Number(track.endsAt || 0)) {
    realtimeSmoothMotionRuntime.tracks.delete(key);
    return { x: target.x, y: target.y, active: false, remainingMs: 0 };
  }
  const span = Math.max(1, Number(track.endsAt) - Number(track.startedAt));
  const t = Math.max(0, Math.min(1, (now - Number(track.startedAt)) / span));
  return {
    x: Number(track.fromX) + (Number(track.toX) - Number(track.fromX)) * t,
    y: Number(track.fromY) + (Number(track.toY) - Number(track.fromY)) * t,
    active: true,
    remainingMs: Math.max(1, Number(track.endsAt) - now),
    targetX: Number(track.toX),
    targetY: Number(track.toY),
  };
}

// v9.36 · Todos los FX ligados a una Invocación móvil deben consultar la
// posición VISUAL interpolada, nunca la casilla lógica futura. La casilla sigue
// siendo autoritativa para reglas/alcance; este helper solo gobierna geometría.
function getRealtimeRenderedInvocationPoint(playerId, unit, fallbackRow = null, fallbackCol = null) {
  const row = Number(fallbackRow ?? unit?.row ?? 0);
  const col = Number(fallbackCol ?? unit?.col ?? 0);
  if (!unit || !isRealtimePlayStyle() || !state?.realtime?.active) return cellCenter(row, col);
  const key = getRealtimeSmoothMotionKey('invocation', Number(playerId), unit.id);
  return getRealtimeSmoothMotionSample(key, row, col);
}

const realtimeBoundFxSyncRuntime = { raf: 0, finalFramePending: false };

function hasActiveRealtimeSmoothMotionTracks() {
  if (!isRealtimePlayStyle() || !state?.realtime?.active) return false;
  const now = performance.now();
  let active = false;
  for (const [key, track] of [...realtimeSmoothMotionRuntime.tracks.entries()]) {
    if (!track || now >= Number(track.endsAt || 0)) {
      realtimeSmoothMotionRuntime.tracks.delete(key);
      continue;
    }
    active = true;
  }
  return active;
}

function syncRealtimeBoundFxMotionFrame() {
  realtimeBoundFxSyncRuntime.raf = 0;
  if (!isRealtimePlayStyle() || !state?.realtime?.active || state.gameOver) return;
  try { renderMaerynDominationAuras?.(); } catch (_) {}
  try { renderNaelProvocationAuras?.(); } catch (_) {}
  try { renderMinokageAuras?.(); } catch (_) {}
  try { renderGuardianChannelFx?.(); } catch (_) {}
  try { renderKaguyaChargeFxLayer?.(); } catch (_) {}
  try { renderParalysisLinksLayer?.(); } catch (_) {}
  // v9.42 · Dominación Mental vive en una capa independiente del token y se
  // reancla a su posición renderizada en cada frame de locomoción suave.
  try { syncMaerynDominationPersistentFxPositions?.(); } catch (_) {}
  // v9.41 · Las flechas direccionales no solo deben viajar con el nodo: su
  // ángulo depende también de otra pieza móvil, así que se recalcula por frame.
  try { syncRealtimeDirectionalUnitFx?.(); } catch (_) {}
  // Los FX persistentes que viven dentro del nodo visual se mueven solos.
  // Solo las capas absolutas del tablero y direcciones relativas requieren seguimiento.
  if (hasActiveRealtimeSmoothMotionTracks()) {
    realtimeBoundFxSyncRuntime.raf = requestAnimationFrame(syncRealtimeBoundFxMotionFrame);
  } else if (!realtimeBoundFxSyncRuntime.finalFramePending) {
    // v9.45 · Un último frame después de que expire el track captura el endpoint
    // físico de la transición CSS y evita que la flecha quede con el ángulo del
    // penúltimo frame si Nael o el objetivo terminaron el paso entre rafs.
    realtimeBoundFxSyncRuntime.finalFramePending = true;
    requestAnimationFrame(() => {
      realtimeBoundFxSyncRuntime.finalFramePending = false;
      try { syncRealtimeDirectionalUnitFx?.(); } catch (_) {}
    });
  }
}

function scheduleRealtimeBoundFxMotionSync() {
  if (!isRealtimePlayStyle() || !state?.realtime?.active || realtimeBoundFxSyncRuntime.raf) return;
  realtimeBoundFxSyncRuntime.raf = requestAnimationFrame(syncRealtimeBoundFxMotionFrame);
}

function applyRealtimeSmoothMotionToRenderedNode(node, type, playerId, entityId, row, col) {
  const target = cellCenter(Number(row), Number(col));
  if (!node || !isRealtimePlayStyle() || !state?.realtime?.active || !['caster', 'invocation'].includes(type)) {
    if (node) {
      node.style.left = `${target.x}%`;
      node.style.top = `${target.y}%`;
    }
    return target;
  }
  const key = getRealtimeSmoothMotionKey(type, playerId, entityId);
  if (!key) {
    node.style.left = `${target.x}%`;
    node.style.top = `${target.y}%`;
    return target;
  }

  // Réplicas PvP reciben snapshots y no ejecutan moveRealtimeInvocationOneStep.
  // Si el cambio recibido es exactamente una casilla, inferimos el tramo visual.
  // Saltos mayores (portales, respawn, restauración) NO se interpolan.
  const previous = realtimeSmoothMotionRuntime.logical.get(key);
  const activeTrack = realtimeSmoothMotionRuntime.tracks.get(key);
  const trackAlreadyTargetsCell = activeTrack
    && Number(activeTrack.toRow) === Number(row)
    && Number(activeTrack.toCol) === Number(col);
  if (!trackAlreadyTargetsCell && previous
      && (Number(previous.row) !== Number(row) || Number(previous.col) !== Number(col))) {
    const dr = Math.abs(Number(previous.row) - Number(row));
    const dc = Math.abs(Number(previous.col) - Number(col));
    if (Math.max(dr, dc) === 1) {
      queueRealtimeSmoothMotion(type, playerId, entityId, previous.row, previous.col, row, col);
    } else {
      realtimeSmoothMotionRuntime.tracks.delete(key);
    }
  }
  realtimeSmoothMotionRuntime.logical.set(key, { row: Number(row), col: Number(col) });

  const sample = getRealtimeSmoothMotionSample(key, row, col);
  node.classList.add('rt-smooth-grid-motion');
  node.style.left = `${sample.x}%`;
  node.style.top = `${sample.y}%`;
  if (sample.active) {
    node.dataset.rtSmoothTargetLeft = String(sample.targetX);
    node.dataset.rtSmoothTargetTop = String(sample.targetY);
    node.dataset.rtSmoothRemaining = String(Math.max(1, Math.round(sample.remainingMs)));
  }
  return sample;
}

function resumeRealtimeSmoothTransitionsInLayer() {
  if (!els.unitsLayer || !isRealtimePlayStyle() || !state?.realtime?.active) return;
  const nodes = [...els.unitsLayer.querySelectorAll('.unit.rt-smooth-grid-motion[data-rt-smooth-target-left]')];
  if (!nodes.length) return;
  requestAnimationFrame(() => {
    nodes.forEach(node => {
      if (!node.isConnected) return;
      const remaining = Math.max(1, Number(node.dataset.rtSmoothRemaining || 1));
      const targetLeft = Number(node.dataset.rtSmoothTargetLeft);
      const targetTop = Number(node.dataset.rtSmoothTargetTop);
      if (!Number.isFinite(targetLeft) || !Number.isFinite(targetTop)) return;
      node.style.transition = `left ${remaining}ms linear, top ${remaining}ms linear`;
      node.style.left = `${targetLeft}%`;
      node.style.top = `${targetTop}%`;
    });
  });
}

function ensureRealtimeMovementSystemState() {
  if (!state.realtime || typeof state.realtime !== 'object') {
    state.realtime = { active: false, startedAt: 0, elapsedSeconds: 0, tickSerial: 0, phaseEquivalentSeconds: 1 };
  }
  if (!state.realtime.movementSystem || typeof state.realtime.movementSystem !== 'object') {
    state.realtime.movementSystem = {
      initialized: false,
      invocationStepSeconds: REALTIME_INVOCATION_STEP_SECONDS,
      castCounterStepSeconds: REALTIME_CAST_COUNTER_STEP_SECONDS,
      restoreCounterStepSeconds: REALTIME_RESTORE_COUNTER_STEP_SECONDS,
      aiCastCheckSeconds: REALTIME_AI_CAST_CHECK_SECONDS,
      lastProcessedSecond: 0,
      movedUnits: 0,
      automaticAttacks: 0,
      sustainedCombats: 0,
      casterKeyboardMoves: 0,
      attackIntervalSeconds: REALTIME_ATTACK_INTERVAL_SECONDS,
      tempoSeconds: REALTIME_DEFAULT_TEMPO_SECONDS,
      balanceProfile: REALTIME_BALANCE_PROFILE_ID,
    };
  }
  return state.realtime.movementSystem;
}

function initializeRealtimeMovementSystem() {
  const system = ensureRealtimeMovementSystemState();
  system.initialized = true;
  system.invocationStepSeconds = REALTIME_INVOCATION_STEP_SECONDS;
  system.castCounterStepSeconds = REALTIME_CAST_COUNTER_STEP_SECONDS;
  system.restoreCounterStepSeconds = REALTIME_RESTORE_COUNTER_STEP_SECONDS;
  system.aiCastCheckSeconds = REALTIME_AI_CAST_CHECK_SECONDS;
  system.attackIntervalSeconds = REALTIME_ATTACK_INTERVAL_SECONDS;
  system.tempoSeconds = getRealtimeTempoSeconds();
  system.balanceProfile = REALTIME_BALANCE_PROFILE_ID;
  system.lastProcessedSecond = 0;
  system.movedUnits = 0;
  system.automaticAttacks = 0;
  system.sustainedCombats = 0;
  system.casterKeyboardMoves = 0;
  realtimeStage3Runtime.entityLocks.clear();
  realtimeStage3Runtime.pairLocks.clear();
  realtimeStage3Runtime.aiCastBusy = false;
  realtimeStage3Runtime.lastCasterMoveAt = 0;
  realtimeStage3Runtime.lastProcessedSecond = 0;
  realtimeStage3Runtime.combatPowerCache.clear();
  resetRealtimeSmoothMotionRuntime();
  return system;
}

function realtimeEntityKey(playerId, entityId, type = 'unit') {
  return `${String(type || 'unit')}:${Number(playerId)}:${String(entityId || '')}`;
}

function realtimeUnitEntityKey(playerId, unitId) {
  return realtimeEntityKey(playerId, unitId, 'unit');
}

function realtimeCasterEntityKey(playerId) {
  return realtimeEntityKey(playerId, 'caster', 'caster');
}

function isRealtimeEntityLocked(key) {
  return Boolean(key && realtimeStage3Runtime.entityLocks.has(key));
}

function getRealtimeTargetEntityKey(target) {
  if (!target) return '';
  if (target.type === 'caster') return realtimeCasterEntityKey(target.playerId);
  if (target.type === 'invocation') return realtimeUnitEntityKey(target.playerId, target.unitId);
  if (target.type === 'guardian') return realtimeEntityKey(target.playerId, target.guardianId, 'guardian');
  return '';
}

function getRealtimeDefaultDestination(playerId, unit) {
  const enemyId = getEnemyPlayerId(playerId);
  const caster = state.players?.[enemyId]?.caster;
  if (caster && Number(caster.life ?? 0) > 0) {
    return { row: Number(caster.row), col: Number(caster.col), type: 'caster', playerId: enemyId, label: 'Kaster rival' };
  }
  return { row: getEnemyRiskRow(playerId), col: 4, type: 'cell', playerId: enemyId, label: 'frente rival' };
}

function isRealtimeAutomaticTargetSelectable(target) {
  if (!target) return false;
  if (target.type !== 'invocation') return true;
  const unit = getUnitById?.(Number(target.playerId), target.unitId);
  if (!unit || unit.status === 'restoring' || Number(unit.hp ?? 0) <= 0) return false;
  // Oculto/Camuflaje/Sigilo nunca se convierte en objetivo directo de la IA.
  // Los efectos de área/barrido conservan sus reglas propias en el motor de daño.
  return !isRealtimeCombatModeTargetConcealed(unit);
}

function isRealtimeAttackReady(unit, activeMs = null) {
  if (!unit) return false;
  const nowMs = Math.max(0, Number(activeMs ?? getRealtimeActiveElapsedMs()));
  const legacySecond = Math.max(0, Number(unit.realtimeNextAttackSecond || 0));
  const legacyMs = legacySecond > 0 ? legacySecond * 1000 : 0;
  return nowMs >= Math.max(legacyMs, Number(unit.realtimeNextAttackAtMs || 0));
}

function markRealtimeAttackCadence(unit, playerId = null, activeMs = null) {
  if (!unit) return 0;
  const nowMs = Math.max(0, Number(activeMs ?? getRealtimeActiveElapsedMs()));
  const ownerId = Number(playerId || getOwnerPlayerIdForUnit?.(unit) || 0);
  const cadenceSeconds = getRealtimeAttackCadenceSeconds(ownerId, unit);
  unit.realtimeNextAttackAtMs = nowMs + cadenceSeconds * 1000;
  unit.realtimeNextAttackSecond = Math.ceil(unit.realtimeNextAttackAtMs / 1000);
  return unit.realtimeNextAttackAtMs;
}


function serializeRealtimeAttackTarget(target) {
  if (!target) return null;
  return {
    type: String(target.type || ''),
    playerId: Number(target.playerId || 0),
    unitId: target.unitId || null,
    guardianId: target.guardianId || null,
  };
}

function resolveRealtimeAttackTargetDescriptor(descriptor) {
  if (!descriptor?.type || !descriptor.playerId) return null;
  if (descriptor.type === 'caster') return buildTarget('caster', descriptor.playerId);
  if (descriptor.type === 'invocation') return buildTarget('invocation', descriptor.playerId, { unitId: descriptor.unitId });
  if (descriptor.type === 'guardian') return buildTarget('guardian', descriptor.playerId, { guardianId: descriptor.guardianId });
  return null;
}

function startRealtimeAttackPreparation(playerId, unit, target, activeMs = null) {
  if (!unit || !target || unit.realtimeAttackTelegraph) return false;
  const nowMs = Math.max(0, Number(activeMs ?? getRealtimeActiveElapsedMs()));
  const prepMs = Math.max(0, getRealtimeTimingValue('attackPrepSeconds') * 1000);
  unit.realtimeAttackTelegraph = {
    target: serializeRealtimeAttackTarget(target),
    startedAtMs: nowMs,
    readyAtMs: nowMs + prepMs,
  };
  unit.movesLeft = 0;
  renderUnits();
  return true;
}

function cancelRealtimeAttackPreparation(unit) {
  if (!unit?.realtimeAttackTelegraph) return false;
  unit.realtimeAttackTelegraph = null;
  return true;
}

function resolveRealtimeAttackPreparation(playerId, unit, activeMs = null) {
  const telegraph = unit?.realtimeAttackTelegraph;
  if (!unit || !telegraph) return false;
  const nowMs = Math.max(0, Number(activeMs ?? getRealtimeActiveElapsedMs()));
  if (nowMs < Number(telegraph.readyAtMs || 0)) return false;

  const target = resolveRealtimeAttackTargetDescriptor(telegraph.target);
  if (!target || !isRealtimeAutomaticTargetSelectable(target)) {
    unit.realtimeAttackTelegraph = null;
    return false;
  }

  // v9.66 · Si dos Invocaciones están listas para golpearse en el mismo
  // instante de Tiempo Real, la Velocidad de ataque universal decide cuál
  // resuelve primero. La más lenta conserva su preparación y podrá responder
  // después si sigue activa.
  if (target.type === 'invocation') {
    const rival = getUnitById(Number(target.playerId), target.unitId);
    const rivalTelegraph = rival?.realtimeAttackTelegraph;
    if (rival && rivalTelegraph && nowMs >= Number(rivalTelegraph.readyAtMs || 0) && isRealtimeAttackReady(rival, nowMs)) {
      const reciprocal = resolveRealtimeAttackTargetDescriptor(rivalTelegraph.target);
      if (reciprocal?.type === 'invocation'
          && Number(reciprocal.playerId) === Number(playerId)
          && String(reciprocal.unitId || '') === String(unit.id || '')) {
        if (compareRealtimeAttackInitiative(playerId, unit, target.playerId, rival) < 0) return false;
      }
    }
  }

  unit.realtimeAttackTelegraph = null;

  const card = CARD_LIBRARY?.[unit.cardId];
  if (!card) return false;
  const currentTargets = getTargetsInRangeForSource({ playerId, unit, card }).filter(isRealtimeAutomaticTargetSelectable);
  const liveTarget = currentTargets.find(candidate => realtimeTargetsMatch(candidate, target));
  if (!liveTarget || !isRealtimeAttackReady(unit, nowMs)) return false;

  return startRealtimeAutomaticAttack(playerId, unit, liveTarget, nowMs);
}

function getRealtimeAutomaticAttackDecision(playerId, unit, intent = null) {
  if (!unit || unit.status === 'restoring' || isUnitEngaged(unit) || unitHasParalysis(unit) || unitBindingBlocksAttack(unit)) {
    return { target: null, wait: false, intent: intent || null };
  }
  if (unitHasNativeCampeo(unit)) {
    return { target: null, wait: false, intent: intent || getRealtimeCombatIntent(playerId, unit), campeoRetreat: true };
  }
  const card = CARD_LIBRARY[unit.cardId];
  if (!card) return { target: null, wait: false, intent: intent || null };
  const resolvedIntent = intent || getRealtimeCombatIntent(playerId, unit);
  const attackReady = isRealtimeAttackReady(unit);
  const targets = getTargetsInRangeForSource({ playerId, unit, card }).filter(isRealtimeAutomaticTargetSelectable);
  const desired = resolvedIntent?.target || null;
  const modeId = String(resolvedIntent?.modeId || 'offensive');

  const makeAttackDecision = (target, extra = {}) => {
    if (!target) return null;
    if (!attackReady) return { target: null, wait: true, intent: resolvedIntent, cadence: true, ...extra };
    const targetKey = getRealtimeTargetEntityKey(target);
    return isRealtimeEntityLocked(targetKey)
      ? { target: null, wait: true, intent: resolvedIntent, ...extra }
      : { target, wait: false, intent: resolvedIntent, ...extra };
  };

  // v9.52 · Farolera estratégica: completar Farol sigue siendo prioritario,
  // pero desplazarse hacia el punto táctico NO la vuelve pacífica. Mientras no
  // esté exactamente retenida para resolver Círculo/Farol/recasteo, puede usar
  // su ataque mágico normal contra rivales que ya estén legalmente en alcance.
  // Así se defiende durante el avance sin abandonar la ruta estratégica.
  if (resolvedIntent?.faroleraStrategy) {
    if (!resolvedIntent?.faroleraHold && targets.length) {
      const enemyId = getEnemyPlayerId(playerId);
      const desiredInRange = desired
        ? targets.find(target => realtimeTargetsMatch(target, desired))
        : null;
      const enemyCaster = targets.find(target =>
        target.type === 'caster' && Number(target.playerId) === Number(enemyId)
      );
      const enemyInvocations = targets
        .filter(target => target.type === 'invocation' && Number(target.playerId) === Number(enemyId))
        .filter(target => !isRealtimeEntityLocked(getRealtimeTargetEntityKey(target)))
        .sort((a, b) => {
          const da = ringDistance(unit.row, unit.col, a.row, a.col);
          const db = ringDistance(unit.row, unit.col, b.row, b.col);
          if (da !== db) return da - db;
          return Number(a.hp ?? 999) - Number(b.hp ?? 999);
        });
      const tacticalTarget = desiredInRange || enemyCaster || enemyInvocations[0] || null;
      const tacticalDecision = makeAttackDecision(tacticalTarget, {
        faroleraStrategy: true,
        faroleraCoverFire: true,
      });
      if (tacticalDecision) return tacticalDecision;
    }

    const destination = resolvedIntent.destination;
    if (destination && !chooseRealtimeInvocationStep(playerId, unit, destination)) {
      const blocker = targets
        .filter(target => target.type === 'invocation' && Number(target.playerId) === Number(getEnemyPlayerId(playerId)))
        .filter(target => !isRealtimeEntityLocked(getRealtimeTargetEntityKey(target)))
        .sort((a, b) => ringDistance(unit.row, unit.col, a.row, a.col) - ringDistance(unit.row, unit.col, b.row, b.col))[0];
      const blockerDecision = makeAttackDecision(blocker, { faroleraStrategy: true, forcedBlocker: true });
      if (blockerDecision) return blockerDecision;
    }
    return { target: null, wait: false, intent: resolvedIntent, faroleraStrategy: true };
  }

  // Defensivo no abre fuego solo porque un rival esté cerca. Únicamente responde
  // a una amenaza que ya está comprometiendo nuestro lado.
  if (modeId === 'defensive') {
    if (desired) {
      const directThreat = targets.find(target => realtimeTargetsMatch(target, desired));
      const decision = makeAttackDecision(directThreat, { reactiveDefense: true });
      if (decision) return decision;
    }
    return { target: null, wait: false, intent: resolvedIntent, reactiveDefense: true };
  }

  // Neru Ofensivo conserva Invocaciones como prioridad normal, pero puede invertir
  // la decisión cuando existe una ventana táctica real para Silenciar al Kaster.
  if (modeId === 'offensive' && isNeruUnit(unit)) {
    const neruTarget = chooseRealtimeNeruOffensiveAttackTarget(playerId, unit, targets);
    const neruDecision = makeAttackDecision(neruTarget, {
      neruSilenceTactics: true,
      casterPriority: neruTarget?.type === 'caster',
    });
    if (neruDecision) return neruDecision;
  }

  // Minokage Ofensivo conserva la Invocación más poderosa como eje de presión.
  // Si esa pieza entra en su aura 3, el ataque normal puede disparar Salto ofensivo
  // en lugar de desviarse hacia el Kaster por la prioridad genérica de Ofensivo.
  if (modeId === 'offensive' && isMinokageUnit(unit)) {
    const desiredInvocation = desired
      ? targets.find(target => realtimeTargetsMatch(target, desired) && target.type === 'invocation')
      : null;
    const strongestInRange = targets
      .filter(target => target.type === 'invocation' && Number(target.playerId) === Number(getEnemyPlayerId(playerId)))
      .filter(target => !isRealtimeEntityLocked(getRealtimeTargetEntityKey(target)))
      .sort((a, b) => {
        const ua = getUnitById(a.playerId, a.unitId);
        const ub = getUnitById(b.playerId, b.unitId);
        const pa = Math.max(0, Number(getRealtimeCombatPowerForCard(ua?.cardId) || 0));
        const pb = Math.max(0, Number(getRealtimeCombatPowerForCard(ub?.cardId) || 0));
        return pb - pa;
      })[0] || null;
    const minokageDecision = makeAttackDecision(desiredInvocation || strongestInRange, {
      minokageOffensivePressure: true,
    });
    if (minokageDecision) return minokageDecision;
  }

  // v9.60 · Oda no Kage Ofensivo respeta su objetivo de presión cercano.
  // Aunque el Kaster también entre en Alcance, primero completa el barrido sobre
  // la Invocación que está cazando. Esto separa de verdad Ofensivo de Asesinato.
  if (modeId === 'offensive' && isOdaNoKageUnit(unit)) {
    const odaTarget = desired
      ? targets.find(target => realtimeTargetsMatch(target, desired) && target.type === 'invocation')
      : null;
    const nearestFallback = targets
      .filter(target => target.type === 'invocation' && Number(target.playerId) === Number(getEnemyPlayerId(playerId)))
      .filter(target => !isRealtimeEntityLocked(getRealtimeTargetEntityKey(target)))
      .sort((a, b) => ringDistance(unit.row, unit.col, a.row, a.col) - ringDistance(unit.row, unit.col, b.row, b.col))[0] || null;
    const odaDecision = makeAttackDecision(odaTarget || nearestFallback, {
      odaOffensivePressure: true,
    });
    if (odaDecision) return odaDecision;
  }

  // v9.87 · Sutoka con Acechar no corta la infiltración apenas el Kaster entra
  // en Alcance 2. Si existe una casilla de flanco válida, primero llega detrás
  // del Kaster; desde allí sí ejecuta el ataque. Si el tablero no ofrece flanco,
  // cae de forma segura a la regla normal de Asesinato.
  if (modeId === 'assassination' && isNaitoSutokaUnit(unit) && resolvedIntent?.sutokaFlankAssassination) {
    if (!isRealtimeSutokaFlankStrikePosition(playerId, unit)) {
      const destination = resolvedIntent?.destination;
      const hasFlankStep = destination ? Boolean(chooseRealtimeInvocationStep(playerId, unit, destination)) : false;
      if (hasFlankStep) {
        return { target: null, wait: false, intent: resolvedIntent, assassination: true, sutokaFlanking: true };
      }
    }
  }

  // Ofensivo y Asesinato comparten una regla de victoria para el resto del roster:
  // si el Kaster rival ya está legalmente dentro del alcance, se ataca de inmediato.
  // Neru y Oda tienen prioridades tácticas específicas antes de esta regla.
  if ((modeId === 'offensive' && !isNeruUnit(unit) && !isOdaNoKageUnit(unit) && !isMinokageUnit(unit) && !isKaguyaUnit(unit)) || modeId === 'assassination') {
    const casterTarget = targets.find(target => target.type === 'caster' && Number(target.playerId) === Number(getEnemyPlayerId(playerId)));
    const casterDecision = makeAttackDecision(casterTarget, { casterPriority: true });
    if (casterDecision) return casterDecision;
  }

  if (modeId === 'offensive' && isRealtimeSimplePriorityNinja(unit)) {
    const desiredInvocation = desired
      ? targets.find(target => realtimeTargetsMatch(target, desired) && target.type === 'invocation')
      : null;
    const strongestInRange = targets
      .filter(target => target.type === 'invocation' && Number(target.playerId) === Number(getEnemyPlayerId(playerId)))
      .filter(target => !isRealtimeEntityLocked(getRealtimeTargetEntityKey(target)))
      .sort((a, b) => {
        const ua = getUnitById(a.playerId, a.unitId);
        const ub = getUnitById(b.playerId, b.unitId);
        const pa = Math.max(0, Number(getRealtimeCombatPowerForCard(ua?.cardId) || 0));
        const pb = Math.max(0, Number(getRealtimeCombatPowerForCard(ub?.cardId) || 0));
        if (pa !== pb) return pb - pa;
        return getRealtimeLiveThreatScore(playerId, unit, { playerId: b.playerId, unit: ub, card: CARD_LIBRARY?.[ub?.cardId] })
          - getRealtimeLiveThreatScore(playerId, unit, { playerId: a.playerId, unit: ua, card: CARD_LIBRARY?.[ua?.cardId] });
      })[0] || null;
    const decision = makeAttackDecision(desiredInvocation || strongestInRange, {
      simpleNinjaOffensiveTarget: true,
    });
    if (decision) return decision;
  }

  if (modeId === 'offensive' && isRealtimeReviewedSamuraiPriorityUnit(unit)) {
    const desiredInvocation = desired
      ? targets.find(target => realtimeTargetsMatch(target, desired) && target.type === 'invocation')
      : null;
    const strongestInRange = targets
      .filter(target => target.type === 'invocation' && Number(target.playerId) === Number(getEnemyPlayerId(playerId)))
      .filter(target => !isRealtimeEntityLocked(getRealtimeTargetEntityKey(target)))
      .sort((a, b) => {
        const ua = getUnitById(a.playerId, a.unitId);
        const ub = getUnitById(b.playerId, b.unitId);
        const pa = Math.max(0, Number(getRealtimeCombatPowerForCard(ua?.cardId) || 0));
        const pb = Math.max(0, Number(getRealtimeCombatPowerForCard(ub?.cardId) || 0));
        if (pa !== pb) return pb - pa;
        return getRealtimeLiveThreatScore(playerId, unit, { playerId: b.playerId, unit: ub, card: CARD_LIBRARY?.[ub?.cardId] })
          - getRealtimeLiveThreatScore(playerId, unit, { playerId: a.playerId, unit: ua, card: CARD_LIBRARY?.[ua?.cardId] });
      })[0] || null;
    const decision = makeAttackDecision(desiredInvocation || strongestInRange, {
      reviewedSamuraiOffensiveTarget: true,
    });
    if (decision) return decision;
  }

  if (modeId === 'assassination') {
    // Evita combates laterales. Solo golpea una Invocación cuando de verdad no
    // existe un paso legal hacia el Kaster y esa pieza es el bloqueador inmediato.
    const destination = resolvedIntent?.destination || desired;
    if (destination && !chooseRealtimeInvocationStep(playerId, unit, destination)) {
      const blocker = targets
        .filter(target => target.type === 'invocation')
        .filter(target => !isRealtimeEntityLocked(getRealtimeTargetEntityKey(target)))
        .sort((a, b) => ringDistance(unit.row, unit.col, a.row, a.col) - ringDistance(unit.row, unit.col, b.row, b.col))[0];
      const blockerDecision = makeAttackDecision(blocker, { forcedBlocker: true, assassination: true });
      if (blockerDecision) return blockerDecision;
    }
    return { target: null, wait: false, intent: resolvedIntent, assassination: true };
  }

  if (modeId === 'offensive') {
    // Mientras el Kaster todavía no esté a tiro, limpia únicamente enemigos que
    // estén en el corredor real de avance. No abandona la ruta para cazar piezas
    // lejanas aunque tengan más PB o daño.
    const pathEntry = chooseRealtimeOffensivePathEnemy(playerId, unit, targets);
    const pathTarget = buildRealtimeTargetFromUnitEntry(pathEntry);
    const pathDecision = makeAttackDecision(pathTarget, { clearPath: true });
    if (pathDecision) return pathDecision;

    // Edran y futuros receptores aliados conservan su interacción, pero nunca
    // por encima de un Kaster alcanzable ni de un enemigo que bloquee la presión.
    const alliedReceiver = targets.find(target =>
      Number(target.playerId) === Number(playerId)
      && target.type === 'invocation'
      && isAlliedAttackReceiverTarget({ playerId, unit, card }, target)
      && !isRealtimeEntityLocked(getRealtimeTargetEntityKey(target))
    );
    const alliedDecision = makeAttackDecision(alliedReceiver, { alliedCharge: true });
    if (alliedDecision) return alliedDecision;
  }

  // Cacería y Asedio respetan su objetivo explícito. Cacería persigue la pieza
  // vulnerable; Asedio la Estructura/Guardián seleccionada.
  if (desired && !resolvedIntent?.avoidCombat) {
    const direct = targets.find(target => realtimeTargetsMatch(target, desired));
    const directDecision = makeAttackDecision(direct);
    if (directDecision) return directDecision;
  }

  if (resolvedIntent?.avoidCombat) {
    return { target: null, wait: false, intent: resolvedIntent };
  }

  // Una prioridad no debe convertir a la unidad en un objeto inmóvil si un rival
  // bloquea físicamente todas las rutas hacia su objetivo. Solo en ese caso se
  // permite atacar al bloqueador más cercano como acción forzada.
  const destination = resolvedIntent?.destination || desired;
  if (destination && !chooseRealtimeInvocationStep(playerId, unit, destination)) {
    const blocker = targets
      .filter(target => target.type === 'invocation')
      .filter(target => !isRealtimeEntityLocked(getRealtimeTargetEntityKey(target)))
      .sort((a, b) => ringDistance(unit.row, unit.col, a.row, a.col) - ringDistance(unit.row, unit.col, b.row, b.col))[0];
    const blockerDecision = makeAttackDecision(blocker, { forcedBlocker: true });
    if (blockerDecision) return blockerDecision;
  }

  return { target: null, wait: false, intent: resolvedIntent };
}

function getRealtimeHechiceroPortalShortcut(playerId, unit, destination) {
  if (!unit || !destination || !cardIsHechicero(CARD_LIBRARY?.[unit.cardId])) return null;

  const isFarolera = isFaroleraUmbralUnit(unit);
  const faroleraMode = isFarolera
    ? (getRealtimeCombatModeProfileForUnit(playerId, unit)?.activeId || 'defensive')
    : '';
  // Defensivo construye infraestructura para el resto del equipo, pero la
  // Farolera no se mete voluntariamente en su propio círculo.
  if (isFarolera && faroleraMode === 'defensive') return null;

  const currentDistance = ringDistance(unit.row, unit.col, destination.row, destination.col);
  const portals = (state.farolPortals || []).filter(portal =>
    portal?.stage === 'complete'
    && Number(portal.playerId) === Number(playerId)
    && portal.originRow != null && portal.originCol != null
    && portal.destinationRow != null && portal.destinationCol != null
  );
  if (!portals.length) return null;

  const minimumGain = isFarolera && faroleraMode === 'offensive' ? 0 : 2;
  return portals.map(portal => {
    const entranceDistance = ringDistance(unit.row, unit.col, portal.originRow, portal.originCol);
    const exitDistance = ringDistance(portal.destinationRow, portal.destinationCol, destination.row, destination.col);
    const estimated = entranceDistance + 1 + exitDistance;
    const gain = currentDistance - estimated;
    return { portal, entranceDistance, exitDistance, estimated, gain };
  }).filter(entry => entry.gain >= minimumGain)
    .sort((a, b) => b.gain - a.gain || a.entranceDistance - b.entranceDistance)[0] || null;
}

function getRealtimeFarolRescueRoutingPortal(playerId, unit) {
  if (!unit || unit.status === 'restoring' || !cardIsHechicero(CARD_LIBRARY?.[unit.cardId])) return null;
  return (state.farolPortals || []).find(portal => {
    if (!portal || portal.stage !== 'complete' || Number(portal.playerId) !== Number(playerId)) return false;
    if (portal.rescueTargetUnitId == null || String(portal.rescueTargetUnitId) !== String(unit.id)) return false;
    if (portal.originRow == null || portal.originCol == null || portal.destinationRow == null || portal.destinationCol == null) return false;
    // El rescate deja de tener sentido si la unidad ya apareció en la salida.
    if (Number(unit.row) === Number(portal.destinationRow) && Number(unit.col) === Number(portal.destinationCol)) return false;
    return true;
  }) || null;
}

function chooseRealtimeInvocationStep(playerId, unit, destination) {
  if (!unit || !destination) return null;
  // Una unidad recibe exactamente 1 paso de movimiento por segundo. La función
  // histórica de movilidad sigue decidiendo qué direcciones son legales.
  unit.movesLeft = 1;
  const options = getInvocationMovementOptionsForUnit(playerId, unit);
  if (!options.length) return null;

  const shortcut = getRealtimeHechiceroPortalShortcut(playerId, unit, destination);
  const routedDestination = shortcut
    ? { row: Number(shortcut.portal.originRow), col: Number(shortcut.portal.originCol) }
    : destination;

  unit.realtimePortalPlan = shortcut ? {
    type: 'farolEnlazado',
    portalKey: String(shortcut.portal.key || ''),
    entrance: { row: Number(shortcut.portal.originRow), col: Number(shortcut.portal.originCol) },
    exit: { row: Number(shortcut.portal.destinationRow), col: Number(shortcut.portal.destinationCol) },
    gain: Number(shortcut.gain || 0),
  } : null;

  return [...options].sort((a, b) => {
    const da = ringDistance(a.row, a.col, routedDestination.row, routedDestination.col);
    const db = ringDistance(b.row, b.col, routedDestination.row, routedDestination.col);
    if (da !== db) return da - db;
    // Empates: conservar la línea del objetivo y después el centro del tablero.
    const laneA = Math.abs(Number(a.col) - Number(routedDestination.col));
    const laneB = Math.abs(Number(b.col) - Number(routedDestination.col));
    if (laneA !== laneB) return laneA - laneB;
    return Math.abs(Number(a.col) - 4) - Math.abs(Number(b.col) - 4);
  })[0] || null;
}

function moveRealtimeInvocationOneStep(playerId, unit, second, intent = null) {
  if (!unit || unit.status === 'restoring' || isUnitEngaged(unit) || hasStructureAttackAnchor(unit)) return false;
  if (isKurayamiUnit(unit) && unit.kurayamiChanneling) return false;
  if (unitHasParalysis(unit) || unitBindingBlocksMovement(unit) || isOdaNoKageShadowBound(unit)) return false;
  const unitKey = realtimeUnitEntityKey(playerId, unit.id);
  if (isRealtimeEntityLocked(unitKey)) return false;
  const resolvedIntent = intent || getRealtimeCombatIntent(playerId, unit);
  if (resolvedIntent?.faroleraHold) {
    unit.movesLeft = 0;
    return false;
  }
  if (!resolvedIntent?.affordanceDestination) unit.realtimeTacticalAffordance = null;
  const rescuePortal = getRealtimeFarolRescueRoutingPortal(playerId, unit);
  if (rescuePortal) {
    unit.realtimePortalPlan = {
      type: 'farolEnlazadoRescue',
      portalKey: String(rescuePortal.key || ''),
      entrance: { row: Number(rescuePortal.originRow), col: Number(rescuePortal.originCol) },
      exit: { row: Number(rescuePortal.destinationRow), col: Number(rescuePortal.destinationCol) },
      rescue: true,
    };
  }
  const chosen = rescuePortal
    ? chooseRealtimeInvocationStep(playerId, unit, { row: Number(rescuePortal.originRow), col: Number(rescuePortal.originCol) })
    : (resolvedIntent?.affordanceDestination
      ? chooseRealtimeInvocationStep(playerId, unit, resolvedIntent.destination)
      : (resolvedIntent?.modeId === 'defensive'
        ? chooseRealtimeDefensiveStep(playerId, unit)
        : (resolvedIntent?.kurayamiAssassination
          ? chooseRealtimeKurayamiAssassinationStep(playerId, unit, resolvedIntent?.destination || getRealtimeDefaultDestination(playerId, unit))
          : chooseRealtimeInvocationStep(playerId, unit, resolvedIntent?.destination || getRealtimeDefaultDestination(playerId, unit)))));
  if (!chosen) {
    unit.movesLeft = 0;
    return false;
  }
  if (isMovementStepBlockedForPlayer(chosen.row, chosen.col, playerId, 1, true)) {
    unit.movesLeft = 0;
    return false;
  }
  const hiddenAtDestination = getHiddenOpponentUnitAtForPlayer(chosen.row, chosen.col, playerId);
  if (hiddenAtDestination && !displaceHiddenOpponentIfNeeded(chosen.row, chosen.col, playerId)) {
    unit.movesLeft = 0;
    return false;
  }

  const previousRow = Number(unit.row);
  const previousCol = Number(unit.col);
  queueRealtimeSmoothMotion('invocation', playerId, unit.id, previousRow, previousCol, chosen.row, chosen.col, getRealtimeMoveIntervalSecondsForUnit(unit) * 1000);
  markCamuflajeMovement(unit, previousRow, previousCol, chosen.row, chosen.col);
  unit.row = chosen.row;
  unit.col = chosen.col;
  unit.movesLeft = 0;
  unit.realtimeLastMoveSecond = Math.floor(Number(second || state.realtime?.elapsedSeconds || 0));
  unit.realtimeLastCombatMode = String(resolvedIntent?.modeId || unit.realtimeCombatMode || 'offensive');
  refreshGoemonLegendaryInfiltrationState(playerId, unit);
  refreshKurayamiNinjaEnemySideBonus(playerId, unit);
  syncOdaNoKageShadowAfterNobunagaMove(playerId, unit, previousRow, previousCol);
  refreshGuardianAuraState({ announceNew: true });
  tryRecoverDroppedWeaponForUnit(unit);

  // RT-08.11 · Tiempo real vuelve a ejecutar la misma resolución reglada de
  // zona de riesgo que Manual. Esto habilita extracción/robo/restauración y
  // Campeo cuando la IA consigue llegar físicamente a la última fila.
  if (Number(unit.row) === Number(getEnemyRiskRow(playerId))
      || (unitHasNativeCampeo(unit) && Number(unit.row) === Number(getCampeoRetreatEdgeRow(playerId)))) {
    checkRiskZoneAttack(playerId, unit);
  }

  const system = ensureRealtimeMovementSystemState();
  system.movedUnits = Math.max(0, Number(system.movedUnits || 0)) + 1;
  return true;
}

function startRealtimeAutomaticAttack(playerId, unit, target, activeMs = null) {
  if (!unit || !target || unit.status === 'restoring' || !isRealtimeAutomaticTargetSelectable(target)) return false;
  if (unitHasNativeCampeo(unit)) return false;
  if (isKurayamiUnit(unit) && unit.kurayamiChanneling) return false;
  const card = CARD_LIBRARY[unit.cardId];
  if (!card) return false;
  const liveSource = { playerId, unit, card, realtimeAutomatic: true };
  const effectiveProfile = getEffectiveAttackProfile(card, unit, playerId);
  if (!guardInvocationAttackRange(liveSource, target, 'realtime-auto-start', effectiveProfile)) return false;
  const nowMs = Math.max(0, Number(activeMs ?? getRealtimeActiveElapsedMs()));
  if (!isRealtimeAttackReady(unit, nowMs)) return false;
  const sourceKey = realtimeUnitEntityKey(playerId, unit.id);
  const targetKey = getRealtimeTargetEntityKey(target);
  if (isRealtimeEntityLocked(sourceKey) || isRealtimeEntityLocked(targetKey)) return false;
  realtimeStage3Runtime.entityLocks.add(sourceKey);
  if (targetKey) realtimeStage3Runtime.entityLocks.add(targetKey);
  unit.realtimeLastAttackSecond = Math.floor(nowMs / 1000);
  markRealtimeAttackCadence(unit, playerId, nowMs);
  unit.movesLeft = 0;
  const system = ensureRealtimeMovementSystemState();
  system.automaticAttacks = Math.max(0, Number(system.automaticAttacks || 0)) + 1;

  const source = { playerId, unit, card, realtimeAutomatic: true };
  const runtimeEpoch = captureBattleRuntimeEpoch();
  const profile = getEffectiveAttackProfile(card, unit, playerId);
  const damage = Number(profile?.damage ?? getAttackProfile(card)?.damage ?? 0);
  void Promise.resolve(executeAttackDamage(source, target, damage))
    .catch(error => reportDebugError('realtime-auto-attack', error))
    .finally(() => {
      realtimeStage3Runtime.entityLocks.delete(sourceKey);
      if (targetKey) realtimeStage3Runtime.entityLocks.delete(targetKey);
      if (!isBattleRuntimeEpochValid(runtimeEpoch)) return;
      try { renderAll('realtime-auto-attack-settled'); } catch (_) {}
    });
  return true;
}

function scheduleRealtimeSustainedCombats(activeMs = null) {
  const nowMs = Math.max(0, Number(activeMs ?? getRealtimeActiveElapsedMs()));
  const pairs = getActiveCombatPairs();
  pairs.forEach(pair => {
    const a = pair?.a;
    const b = pair?.b;
    if (!a?.unit || !b?.unit) return;
    const pairKey = [realtimeUnitEntityKey(a.playerId, a.unit.id), realtimeUnitEntityKey(b.playerId, b.unit.id)].sort().join('|');
    const aKey = realtimeUnitEntityKey(a.playerId, a.unit.id);
    const bKey = realtimeUnitEntityKey(b.playerId, b.unit.id);
    if (realtimeStage3Runtime.pairLocks.has(pairKey) || isRealtimeEntityLocked(aKey) || isRealtimeEntityLocked(bKey)) return;
    if (a.unit.status === 'restoring' || b.unit.status === 'restoring') return;
    // Un combate sostenido se resuelve como intercambio completo. Esperamos a
    // que ambos participantes hayan cumplido la cadencia RT-07 para impedir
    // que una entrada en combate reciba un segundo intercambio al segundo siguiente.
    if (!isRealtimeAttackReady(a.unit, nowMs) || !isRealtimeAttackReady(b.unit, nowMs)) return;

    realtimeStage3Runtime.pairLocks.add(pairKey);
    realtimeStage3Runtime.entityLocks.add(aKey);
    realtimeStage3Runtime.entityLocks.add(bKey);
    a.unit.movesLeft = 0;
    b.unit.movesLeft = 0;
    markRealtimeAttackCadence(a.unit, a.playerId, nowMs);
    markRealtimeAttackCadence(b.unit, b.playerId, nowMs);
    const link = a.unit.engagedWith || {};
    const firstPlayerId = Number(link.initiatorPlayerId || a.playerId) || a.playerId;
    const system = ensureRealtimeMovementSystemState();
    system.sustainedCombats = Math.max(0, Number(system.sustainedCombats || 0)) + 1;

    const runtimeEpoch = captureBattleRuntimeEpoch();
    void Promise.resolve(resolveCombatPair(
      a.playerId,
      a.unit.id,
      b.playerId,
      b.unit.id,
      firstPlayerId,
      { respectAttackSpent: true, markAttacksSpent: true, resolutionReason: `segundo ${Math.floor(nowMs / 1000)} de Tiempo real`, runtimeEpoch },
    ))
      .catch(error => { if (isBattleRuntimeEpochValid(runtimeEpoch)) reportDebugError('realtime-sustained-combat', error); })
      .finally(() => {
        realtimeStage3Runtime.pairLocks.delete(pairKey);
        realtimeStage3Runtime.entityLocks.delete(aKey);
        realtimeStage3Runtime.entityLocks.delete(bKey);
        if (!isBattleRuntimeEpochValid(runtimeEpoch)) return;
        try { renderAll('realtime-combat-settled'); } catch (_) {}
      });
  });
}

function chooseRealtimeAiInvocationCandidate(playerId) {
  const candidates = getAiCastCandidates(playerId)
    .filter(candidate => candidate?.card?.type === 'invocation');
  if (!candidates.length) return null;
  // Prototipo: primero la invocación que entra antes; en empate, la más barata.
  return [...candidates].sort((a, b) => {
    const ca = getEffectiveCastPhasesForCard(a.card, playerId);
    const cb = getEffectiveCastPhasesForCard(b.card, playerId);
    if (ca !== cb) return ca - cb;
    return totalCost(getEffectiveCardCost(a.card, playerId)) - totalCost(getEffectiveCardCost(b.card, playerId));
  })[0] || null;
}

function scheduleRealtimeAiInvocationCast(second) {
  if (!isRealtimePlayStyle() || !state?.realtime?.active || !state.aiEnabled || isOnlineMatchActive()) return false;
  if (realtimeStage3Runtime.aiCastBusy) return false;
  if (Number(second || 0) <= 0 || Number(second) % REALTIME_AI_CAST_CHECK_SECONDS !== 0) return false;
  const playerId = getEnemyPlayerId(LOCAL_PLAYER_ID);
  const player = state.players?.[playerId];
  if (!player || hasAiPendingInvocationCast(playerId)) return false;
  const limit = getInvocationLimitDisplayState(playerId);
  if (Number(limit?.effectiveUsage || 0) >= Number(limit?.effectiveCapacity || 0) && !hasZeroSlotInvocationOpportunity(playerId)) return false;
  const candidate = chooseRealtimeAiInvocationCandidate(playerId);
  if (!candidate) return false;
  const cell = chooseAiCastCell(playerId, candidate);
  if (!cell) return false;

  realtimeStage3Runtime.aiCastBusy = true;
  void Promise.resolve(aiConfirmCast(playerId, candidate, cell))
    .catch(error => reportDebugError('realtime-ai-cast', error))
    .finally(() => {
      realtimeStage3Runtime.aiCastBusy = false;
      try { renderAll('realtime-ai-cast-settled'); } catch (_) {}
    });
  return true;
}


function buildRealtimeFlexibleCostSelection(playerId, needed) {
  let remaining = Math.max(0, Number(needed || 0));
  if (remaining <= 0) return {};
  const player = state.players?.[playerId];
  if (!player) return null;
  const counts = (player.resources || []).reduce((acc, resource) => {
    if (resource?.id) acc[resource.id] = (acc[resource.id] || 0) + 1;
    return acc;
  }, {});
  const rtPlayer = getRealtimeResourcePlayerState(playerId, false);
  const primary = rtPlayer?.primaryElementId || getPlayerDomainId(playerId) || player.elementId;
  const ids = Object.keys(counts).filter(id => Number(counts[id] || 0) > 0);
  ids.sort((a, b) => {
    if (a === primary && b !== primary) return 1;
    if (b === primary && a !== primary) return -1;
    if (counts[a] !== counts[b]) return counts[b] - counts[a];
    return String(a).localeCompare(String(b));
  });
  const selection = {};
  for (const id of ids) {
    if (remaining <= 0) break;
    const take = Math.min(remaining, Number(counts[id] || 0));
    if (take > 0) {
      selection[id] = take;
      remaining -= take;
    }
  }
  return remaining === 0 ? selection : null;
}

function getRealtimeTargetUnitFromAny(target) {
  if (!target) return null;
  if (target.cardId && target.id && target.row != null && target.col != null) return target;
  if (target.type === 'invocation') return getUnitById(target.playerId, target.unitId);
  return null;
}

function isYasuganaSutokaUnit(unit) {
  return Boolean(unit && ['ninjaNaitoSutoka', 'naitoSutoka'].includes(String(unit.cardId || '')));
}

function chooseYasuganaBlindnessTargetForMode(playerId, sourceUnit, targets = [], modeId = '') {
  const list = (targets || []).filter(unit => unit && unit.status !== 'restoring' && Number(unit.hp ?? 0) > 0);
  if (!list.length) return null;
  const mode = String(modeId || getRealtimeCombatModeProfileForUnit(playerId, sourceUnit)?.activeId || 'offensive');
  const enemyId = getEnemyPlayerId(playerId);
  const entryFor = unit => ({ playerId: enemyId, unit, card: CARD_LIBRARY?.[unit.cardId] || null });

  if (mode === 'assassination') return null;

  if (mode === 'hunt') {
    return list.slice().sort((a, b) => {
      const sa = getRealtimeHuntScore(playerId, sourceUnit, entryFor(a));
      const sb = getRealtimeHuntScore(playerId, sourceUnit, entryFor(b));
      if (sa !== sb) return sa - sb;
      return Number(a.hp ?? 999) - Number(b.hp ?? 999);
    })[0] || null;
  }

  if (mode === 'defensive') {
    const caster = state.players?.[playerId]?.caster;
    return list.slice().sort((a, b) => {
      const aThreat = isRealtimeEnemyActivelyThreateningPlayer(playerId, a) ? 1 : 0;
      const bThreat = isRealtimeEnemyActivelyThreateningPlayer(playerId, b) ? 1 : 0;
      if (aThreat !== bThreat) return bThreat - aThreat;
      const ta = getRealtimeDefensiveThreatScore(playerId, sourceUnit, entryFor(a));
      const tb = getRealtimeDefensiveThreatScore(playerId, sourceUnit, entryFor(b));
      if (ta !== tb) return tb - ta;
      const da = caster ? ringDistance(a.row, a.col, caster.row, caster.col) : 999;
      const db = caster ? ringDistance(b.row, b.col, caster.row, caster.col) : 999;
      return da - db;
    })[0] || null;
  }

  // Ofensivo: Ceguera cae sobre la Invocación de mayor poder/impacto.
  return list.slice().sort((a, b) => {
    const pa = Math.max(0, Number(getRealtimeCombatPowerForCard(a.cardId) || 0));
    const pb = Math.max(0, Number(getRealtimeCombatPowerForCard(b.cardId) || 0));
    if (pa !== pb) return pb - pa;
    return getRealtimeLiveThreatScore(playerId, sourceUnit, entryFor(b))
      - getRealtimeLiveThreatScore(playerId, sourceUnit, entryFor(a));
  })[0] || null;
}

function chooseYasuganaVigiliaTargetForAi(playerId, sourceUnit, targets = []) {
  // Estrategia canónica actual: reservar los 2 Oscuridad exclusivamente para
  // Naito Sutoka cuando Sutoka esté configurado en Defensivo.
  return (targets || []).filter(unit => {
    if (!isYasuganaSutokaUnit(unit) || unitHasAbility(unit, 'vigilia')) return false;
    const mode = getRealtimeCombatModeProfileForUnit(playerId, unit)?.activeId || '';
    return mode === 'defensive';
  }).sort((a, b) => {
    const smokeA = Number(a.smokeBombsLeft || 0);
    const smokeB = Number(b.smokeBombsLeft || 0);
    if (smokeA !== smokeB) return smokeB - smokeA;
    return ringDistance(sourceUnit.row, sourceUnit.col, a.row, a.col)
      - ringDistance(sourceUnit.row, sourceUnit.col, b.row, b.col);
  })[0] || null;
}


function getKaguyaStrategicTargetForMode(playerId, sourceUnit, modeId = '') {
  if (!isKaguyaUnit(sourceUnit)) return null;
  const mode = String(modeId || getRealtimeCombatModeProfileForUnit(playerId, sourceUnit)?.activeId || 'offensive');
  if (mode === 'assassination') return getRealtimeEnemyCasterTarget(playerId);
  if (mode === 'siege') return chooseRealtimeEnemyStructureTarget(playerId, sourceUnit);
  if (mode === 'hunt') return buildRealtimeTargetFromUnitEntry(chooseRealtimeWeakestEnemyInvocation(playerId, sourceUnit));
  return buildRealtimeTargetFromUnitEntry(chooseRealtimeMostPowerfulEnemyInvocation(playerId, sourceUnit));
}

function isTargetWithinKaguyaNormalRange(playerId, sourceUnit, target) {
  if (!sourceUnit || !target) return false;
  const card = CARD_LIBRARY?.[sourceUnit.cardId];
  if (!card) return false;
  const profile = getEffectiveAttackProfile(card, sourceUnit, playerId) || getAttackProfile(card) || {};
  const pos = getTargetBoardPosition(target);
  if (!pos) return false;
  const range = Math.max(1, Number(profile.range || 1));
  const dist = ringDistance(sourceUnit.row, sourceUnit.col, pos.row, pos.col);
  return dist >= 1 && dist <= range;
}

function chooseKaguyaChargedShotTargetForMode(playerId, sourceUnit, targets = [], modeId = '') {
  if (!isKaguyaUnit(sourceUnit)) return null;
  const strategic = getKaguyaStrategicTargetForMode(playerId, sourceUnit, modeId);
  if (!strategic || isTargetWithinKaguyaNormalRange(playerId, sourceUnit, strategic)) return null;
  return (targets || []).find(candidate => realtimeTargetsMatch(candidate, strategic)) || null;
}

function chooseRealtimeAbilityTarget(playerId, sourceUnit, targets = []) {
  const list = (targets || []).filter(Boolean);
  if (!list.length) return null;
  const profile = getRealtimeCombatModeProfileForUnit(playerId, sourceUnit);
  const modeId = profile?.activeId || 'offensive';
  const caster = list.find(target => target?.type === 'caster');

  if (modeId === 'assassination' && caster) return caster;

  const siegeTargets = list.filter(target =>
    target?.type === 'guardian'
    || target?.type === 'structure'
    || target?.type === 'riskZone'
  );
  if (modeId === 'siege' && siegeTargets.length) {
    return siegeTargets.slice().sort((a, b) => {
      const pa = getTargetBoardPosition(a);
      const pb = getTargetBoardPosition(b);
      const da = pa ? ringDistance(sourceUnit.row, sourceUnit.col, pa.row, pa.col) : Infinity;
      const db = pb ? ringDistance(sourceUnit.row, sourceUnit.col, pb.row, pb.col) : Infinity;
      return da - db;
    })[0];
  }

  const invocationTargets = list.filter(target => {
    const unit = getRealtimeTargetUnitFromAny(target);
    return Boolean(unit && unit.status !== 'restoring' && Number(unit.hp ?? 0) > 0);
  });
  if (!invocationTargets.length) return caster || list[0];

  const toEntry = target => {
    const unit = getRealtimeTargetUnitFromAny(target);
    return unit ? { playerId: getEnemyPlayerId(playerId), unit, card: CARD_LIBRARY?.[unit.cardId] } : null;
  };

  if (modeId === 'hunt') {
    return invocationTargets.slice().sort((a, b) => {
      return getRealtimeHuntScore(playerId, sourceUnit, toEntry(a))
        - getRealtimeHuntScore(playerId, sourceUnit, toEntry(b));
    })[0];
  }

  if (modeId === 'offensive' && isOdaNoKageUnit(sourceUnit)) {
    return invocationTargets.slice().sort((a, b) => {
      const ua = getRealtimeTargetUnitFromAny(a);
      const ub = getRealtimeTargetUnitFromAny(b);
      return ringDistance(sourceUnit.row, sourceUnit.col, ua.row, ua.col)
        - ringDistance(sourceUnit.row, sourceUnit.col, ub.row, ub.col);
    })[0];
  }

  if (modeId === 'defensive') {
    const committed = invocationTargets
      .map(target => ({ target, entry: toEntry(target) }))
      .filter(item => item.entry && isRealtimeEnemyActivelyThreateningPlayer(playerId, item.entry.unit))
      .sort((a, b) => getRealtimeDefensiveThreatScore(playerId, sourceUnit, b.entry)
        - getRealtimeDefensiveThreatScore(playerId, sourceUnit, a.entry));
    return committed[0]?.target || null;
  }

  if (modeId === 'assassination') {
    const nearby = invocationTargets.slice().sort((a, b) => {
      const ua = getRealtimeTargetUnitFromAny(a);
      const ub = getRealtimeTargetUnitFromAny(b);
      return ringDistance(sourceUnit.row, sourceUnit.col, ua.row, ua.col)
        - ringDistance(sourceUnit.row, sourceUnit.col, ub.row, ub.col);
    });
    const first = nearby[0];
    const unit = getRealtimeTargetUnitFromAny(first);
    return unit && ringDistance(sourceUnit.row, sourceUnit.col, unit.row, unit.col) <= 2 ? first : null;
  }

  return invocationTargets.slice().sort((a, b) => {
    return getRealtimeLiveThreatScore(playerId, sourceUnit, toEntry(b))
      - getRealtimeLiveThreatScore(playerId, sourceUnit, toEntry(a));
  })[0];
}



function chooseMinokageShippuTargetForMode(playerId, sourceUnit, targets = [], modeId = '') {
  const mode = String(modeId || getRealtimeCombatModeProfileForUnit(playerId, sourceUnit)?.activeId || 'offensive');
  const list = (targets || []).filter(Boolean);
  if (!list.length) return null;

  if (mode === 'assassination') {
    return list.find(target => target.type === 'caster') || null;
  }

  if (mode === 'siege') {
    return list
      .filter(target => target.type === 'guardian' || target.type === 'structure')
      .sort((a, b) => {
        const pa = getTargetBoardPosition(a);
        const pb = getTargetBoardPosition(b);
        const da = pa ? ringDistance(sourceUnit.row, sourceUnit.col, pa.row, pa.col) : Infinity;
        const db = pb ? ringDistance(sourceUnit.row, sourceUnit.col, pb.row, pb.col) : Infinity;
        return da - db;
      })[0] || null;
  }

  const invocations = list.filter(target => target.type === 'invocation')
    .map(target => ({ target, unit: getUnitById(target.playerId, target.unitId) }))
    .filter(entry => entry.unit && entry.unit.status !== 'restoring' && Number(entry.unit.hp ?? 0) > 0);
  if (!invocations.length) return null;

  if (mode === 'hunt') {
    return invocations.sort((a, b) => {
      const ea = { playerId: a.target.playerId, unit: a.unit, card: CARD_LIBRARY?.[a.unit.cardId] };
      const eb = { playerId: b.target.playerId, unit: b.unit, card: CARD_LIBRARY?.[b.unit.cardId] };
      return getRealtimeHuntScore(playerId, sourceUnit, ea) - getRealtimeHuntScore(playerId, sourceUnit, eb);
    })[0]?.target || null;
  }

  if (mode === 'offensive') {
    return invocations.sort((a, b) => {
      const powerA = Math.max(0, Number(getRealtimeCombatPowerForCard(a.unit.cardId) || 0));
      const powerB = Math.max(0, Number(getRealtimeCombatPowerForCard(b.unit.cardId) || 0));
      if (powerA !== powerB) return powerB - powerA;
      const threatA = getRealtimeLiveThreatScore(playerId, sourceUnit, { playerId: a.target.playerId, unit: a.unit, card: CARD_LIBRARY?.[a.unit.cardId] });
      const threatB = getRealtimeLiveThreatScore(playerId, sourceUnit, { playerId: b.target.playerId, unit: b.unit, card: CARD_LIBRARY?.[b.unit.cardId] });
      return threatB - threatA;
    })[0]?.target || null;
  }

  return chooseRealtimeAbilityTarget(playerId, sourceUnit, list);
}

function chooseKurayamiPowerTargetForMode(playerId, sourceUnit, targets = [], modeId = '') {
  const mode = String(modeId || getRealtimeCombatModeProfileForUnit(playerId, sourceUnit)?.activeId || 'offensive');
  const list = (targets || []).filter(target => target && target.status !== 'restoring' && Number(target.hp ?? 0) > 0);
  if (!list.length) return null;

  // Asesinato no gasta Shizukesa no Shi-in de forma automática sobre Invocaciones:
  // su plan es abrir una ruta segura hacia el Kaster rival.
  if (mode === 'assassination') return null;

  const enemyId = getEnemyPlayerId(playerId);
  const entryFor = unit => ({ playerId: enemyId, unit, card: CARD_LIBRARY?.[unit.cardId] || null });

  if (mode === 'hunt') {
    // Cacería usa la misma semántica global del Modo: vulnerabilidad real.
    return list.slice().sort((a, b) => {
      const sa = getRealtimeHuntScore(playerId, sourceUnit, entryFor(a));
      const sb = getRealtimeHuntScore(playerId, sourceUnit, entryFor(b));
      if (sa !== sb) return sa - sb;
      return Number(a.hp ?? 999) - Number(b.hp ?? 999);
    })[0] || null;
  }

  if (mode === 'offensive') {
    // Ofensivo marca la pieza de mayor poder, no la más cercana. El alcance 5
    // ya fue filtrado por getKurayamiPowerTargets().
    return list.slice().sort((a, b) => {
      const pba = Math.max(0, Number(getRealtimeCombatPowerForCard(a.cardId) || 0));
      const pbb = Math.max(0, Number(getRealtimeCombatPowerForCard(b.cardId) || 0));
      if (pba !== pbb) return pbb - pba;
      const ca = CARD_LIBRARY?.[a.cardId] || {};
      const cb = CARD_LIBRARY?.[b.cardId] || {};
      const aa = getEffectiveAttackProfile?.(ca, a, enemyId) || getAttackProfile?.(ca) || {};
      const ab = getEffectiveAttackProfile?.(cb, b, enemyId) || getAttackProfile?.(cb) || {};
      const powerA = Number(aa.damage || 0) * 20 + Number(aa.range || 1) * 7 + Number(a.hp ?? ca?.stats?.life ?? 0) * 4;
      const powerB = Number(ab.damage || 0) * 20 + Number(ab.range || 1) * 7 + Number(b.hp ?? cb?.stats?.life ?? 0) * 4;
      return powerB - powerA;
    })[0] || null;
  }

  return chooseRealtimeAbilityTarget(playerId, sourceUnit, list);
}

function getKurayamiAssassinationCellSafety(playerId, row, col) {
  const enemyId = getEnemyPlayerId(playerId);
  const enemies = (state.players?.[enemyId]?.units || []).filter(unit => unit && unit.status !== 'restoring' && Number(unit.hp ?? 0) > 0);
  if (!enemies.length) return { minDistance: 99, attackCoverage: 0, nearby: 0 };
  let minDistance = 99;
  let attackCoverage = 0;
  let nearby = 0;
  for (const enemy of enemies) {
    const d = ringDistance(row, col, enemy.row, enemy.col);
    minDistance = Math.min(minDistance, d);
    if (d <= 2) nearby += 1;
    const card = CARD_LIBRARY?.[enemy.cardId];
    const attack = card ? (getEffectiveAttackProfile?.(card, enemy, enemyId) || getAttackProfile?.(card) || {}) : {};
    if (d <= Math.max(1, Number(attack.range || 1))) attackCoverage += 1;
  }
  return { minDistance, attackCoverage, nearby };
}

function chooseRealtimeKurayamiAssassinationStep(playerId, unit, destination) {
  if (!unit || !destination) return null;
  unit.movesLeft = 1;
  const options = getInvocationMovementOptionsForUnit(playerId, unit);
  if (!options.length) return null;
  const currentDistance = ringDistance(unit.row, unit.col, destination.row, destination.col);
  return options.slice().sort((a, b) => {
    const da = ringDistance(a.row, a.col, destination.row, destination.col);
    const db = ringDistance(b.row, b.col, destination.row, destination.col);
    const sa = getKurayamiAssassinationCellSafety(playerId, a.row, a.col);
    const sb = getKurayamiAssassinationCellSafety(playerId, b.row, b.col);
    const scoreA = (currentDistance - da) * 120 + sa.minDistance * 24 - sa.attackCoverage * 170 - sa.nearby * 34;
    const scoreB = (currentDistance - db) * 120 + sb.minDistance * 24 - sb.attackCoverage * 170 - sb.nearby * 34;
    if (scoreA !== scoreB) return scoreB - scoreA;
    if (da !== db) return da - db;
    return Math.abs(Number(a.col) - Number(destination.col)) - Math.abs(Number(b.col) - Number(destination.col));
  })[0] || null;
}

function chooseRealtimeKurokagiWeaponCandidate(playerId, unit, candidates = [], modeId = '') {
  const mode = String(modeId || getRealtimeCombatModeProfileForUnit(playerId, unit)?.activeId || 'offensive');
  return (candidates || [])
    .map(candidate => {
      const profile = candidate?.capturedProfile || {};
      const damage = Math.max(0, Number(profile.damage || 0));
      const range = Math.max(1, Number(profile.range || 1));
      const precision = Math.max(0, Number(profile.precision || profile.pda || 0));
      let score = damage * 44 + range * 14 + precision * 5;
      if (mode === 'assassination') score += range * 24 + precision * 8;
      else if (mode === 'hunt') score += precision * 12 + damage * 18;
      else if (mode === 'defensive') score += range * 22 + precision * 10;
      else if (mode === 'siege') score += damage * 32 + range * 8;
      else score += damage * 24;
      return { candidate, score };
    })
    .sort((a, b) => b.score - a.score)[0]?.candidate || null;
}

function getRealtimeAbilityModeWeight(modeId, actionId) {
  const table = {
    assassination: { maerynDomination: 92, seyranDistorsion: 30, minokageShippuUgachi: 120, kaguyaChargedShot: 82, odaNoKageShadow: 86, kurayamiDeathSeal: 72, yasuganaGenyutsu: 48, farolEnlazado: 62, sutokaSmokeBomb: 70, takedaOldFriend: 42, kishimotoLimits: 38, gioshoninSupply: 24, kurokagiWeaponShift: 44 },
    offensive: { maerynDomination: 118, seyranDistorsion: 88, kurayamiDeathSeal: 100, minokageShippuUgachi: 118, kaguyaChargedShot: 92, yasuganaGenyutsu: 82, takedaOldFriend: 72, kurokagiWeaponShift: 66, kishimotoLimits: 60, odaNoKageShadow: 58, farolEnlazado: 44, sutokaSmokeBomb: 46, gioshoninSupply: 32 },
    hunt: { maerynDomination: 104, seyranDistorsion: 52, minokageShippuUgachi: 118, kaguyaChargedShot: 95, kurayamiDeathSeal: 90, yasuganaGenyutsu: 80, kurokagiWeaponShift: 62, takedaOldFriend: 58, farolEnlazado: 48, sutokaSmokeBomb: 48, kishimotoLimits: 40, gioshoninSupply: 30, odaNoKageShadow: 35 },
    defensive: { maerynDomination: 84, seyranDistorsion: 96, sutokaSmokeBomb: 100, gioshoninSupply: 94, yasuganaGenyutsu: 90, farolEnlazado: 82, odaNoKageShadow: 78, kishimotoLimits: 62, kurokagiWeaponShift: 55, kurayamiDeathSeal: 36, kaguyaChargedShot: 34, minokageShippuUgachi: 26, takedaOldFriend: 50 },
    siege: { maerynDomination: 54, seyranDistorsion: 72, minokageShippuUgachi: 125, kaguyaChargedShot: 68, kurayamiDeathSeal: 38, yasuganaGenyutsu: 30, sutokaSmokeBomb: 52, farolEnlazado: 60, takedaOldFriend: 58, kishimotoLimits: 54, kurokagiWeaponShift: 48, gioshoninSupply: 36, odaNoKageShadow: 34 },
  };
  return Number(table[modeId]?.[actionId] ?? 25);
}



// RT-08.17 S3 · Support Intent: coordinación reutilizable entre aliados.
const REALTIME_SUPPORT_INTENT_DB = Object.freeze({
  yasuganaVigilia: { id: 'yasuganaVigilia', tags: ['support', 'enable_setup', 'reposition_ally', 'mobility'] },
  gioshoninSupply: { id: 'gioshoninSupply', tags: ['support', 'resupply', 'restore_capability'] },
  farolEnlazado: { id: 'farolEnlazado', tags: ['support', 'reposition', 'enable_setup'] },
  sutokaSmokeBomb: { id: 'sutokaSmokeBomb', tags: ['protect', 'field_setup', 'concealment'] },
});

function getRealtimeUnitThreatPressure(playerId, targetUnit) {
  if (!targetUnit) return 0;
  let pressure = 0;
  for (const entry of getRealtimeEnemyInvocationCandidates(playerId)) {
    const enemy = entry.unit;
    const descriptor = getRealtimeUnitAttackTargetDescriptor(enemy);
    if (descriptor?.type === 'invocation'
        && Number(descriptor.playerId) === Number(playerId)
        && String(descriptor.unitId) === String(targetUnit.id)) {
      pressure += 3;
      continue;
    }
    const attack = getEffectiveAttackProfile?.(entry.card, enemy, entry.playerId)
      || getAttackProfile?.(entry.card)
      || {};
    const range = Math.max(1, Number(attack.range ?? 1));
    const distance = ringDistance(enemy.row, enemy.col, targetUnit.row, targetUnit.col);
    if (distance <= range) pressure += 1.5;
    else if (distance <= range + 2) pressure += 0.5;
  }
  return pressure;
}

function unitCanCreateConcealmentField(playerId, unit) {
  if (!unit || unit.status === 'restoring') return false;
  if (unit.cardId === 'ninjaNaitoSutoka' || unit.cardId === 'naitoSutoka') {
    return Number(unit.smokeBombsLeft || 0) > 0;
  }
  const card = CARD_LIBRARY?.[unit.cardId];
  const values = [
    ...(card?.classification?.functionalCategories || []),
    ...(card?.tags || []),
  ].map(value => String(value || '').toLowerCase());
  return values.some(value => value.includes('conceal'));
}

function getRealtimeAllySetupValue(playerId, targetUnit) {
  if (!targetUnit || targetUnit.status === 'restoring') return 0;
  let score = 0;
  if (unitCanCreateConcealmentField(playerId, targetUnit)) {
    score += 62;
    const mode = getRealtimeCombatModeProfileForUnit(playerId, targetUnit)?.activeId || 'offensive';
    if (mode === 'defensive') score += 46;
    if (mode === 'assassination') score += 30;
  }
  if (getRealtimeCombatModeProfileForUnit(playerId, targetUnit)?.activeId === 'defensive') score += 18;
  return score;
}

function getRealtimeVigiliaMobilityGainScore(playerId, targetUnit) {
  if (!targetUnit || unitHasAbility(targetUnit, 'vigilia')) return -Infinity;
  const card = CARD_LIBRARY?.[targetUnit.cardId];
  const movement = String(
    getEffectiveMovementTypeForUnit?.(playerId, targetUnit)
    || card?.movementType
    || 'basic'
  );
  let score = movement === 'complete' ? 8 : 52;
  if (isRealtimeRowOnOwnSide(playerId, targetUnit.row)) score += 22;
  score += getRealtimeAllySetupValue(playerId, targetUnit);
  return score;
}

function scoreRealtimeSupportTarget(playerId, sourceUnit, targetUnit, actionId, modeId = '') {
  if (!sourceUnit || !targetUnit || targetUnit.status === 'restoring' || Number(targetUnit.hp ?? 0) <= 0) return -Infinity;
  const mode = String(modeId || getRealtimeCombatModeProfileForUnit(playerId, sourceUnit)?.activeId || 'defensive');
  const targetCard = CARD_LIBRARY?.[targetUnit.cardId];
  const targetPb = getRealtimeCombatPowerForCard(targetUnit.cardId);
  const maxHp = Math.max(1, Number(targetUnit.maxHp ?? targetUnit.baseHp ?? targetCard?.stats?.life ?? targetUnit.hp ?? 1));
  const hp = Math.max(0, Number(targetUnit.hp ?? maxHp));
  const missingHpRatio = Math.max(0, Math.min(1, (maxHp - hp) / maxHp));
  const pressure = getRealtimeUnitThreatPressure(playerId, targetUnit);
  const distance = ringDistance(sourceUnit.row, sourceUnit.col, targetUnit.row, targetUnit.col);
  const targetMode = getRealtimeCombatModeProfileForUnit(playerId, targetUnit)?.activeId || 'offensive';

  let score = 24 - distance * 3;
  if (mode === 'defensive') {
    score += pressure * 42 + missingHpRatio * 48;
    if (targetMode === 'defensive') score += 18;
  } else if (mode === 'offensive') {
    score += targetPb * 0.12;
    if (targetMode === 'offensive') score += 24;
  } else if (mode === 'assassination' && targetMode === 'assassination') score += 46;
  else if (mode === 'hunt' && targetMode === 'hunt') score += 38;
  else if (mode === 'siege' && targetMode === 'siege') score += 38;

  if (actionId === 'yasuganaVigilia') {
    const mobility = getRealtimeVigiliaMobilityGainScore(playerId, targetUnit);
    if (!Number.isFinite(mobility)) return -Infinity;
    score += mobility;
    if ((targetUnit.cardId === 'ninjaNaitoSutoka' || targetUnit.cardId === 'naitoSutoka')
        && Number(targetUnit.smokeBombsLeft || 0) > 0) {
      score += mode === 'defensive' ? 135 : 70;
      if (pressure > 0) score += 36;
    }
  }

  if (actionId === 'gioshoninSupply') {
    const options = getGioshoninSupplyOptionsForTarget(targetUnit);
    if (!options.length) return -Infinity;
    score += options.length * 24;
    if (options.some(option => option.type === 'baseWeapon')) score += mode === 'offensive' ? 92 : 64;
    const restoresSmoke = options.some(option =>
      option.type === 'consumable'
      && /smoke|humo|bomb/i.test(`${option.id || ''} ${option.label || ''} ${option.runtimeField || ''}`)
    );
    if (restoresSmoke && (targetUnit.cardId === 'ninjaNaitoSutoka' || targetUnit.cardId === 'naitoSutoka')) {
      score += mode === 'defensive' ? 126 : 62;
    }
  }
  return score;
}

function chooseRealtimeBestSupportTarget(playerId, sourceUnit, targets = [], actionId, modeId = '') {
  const ranked = (targets || [])
    .filter(Boolean)
    .map(targetUnit => ({
      targetUnit,
      score: scoreRealtimeSupportTarget(playerId, sourceUnit, targetUnit, actionId, modeId),
    }))
    .filter(entry => Number.isFinite(entry.score))
    .sort((a, b) => b.score - a.score);

  const best = ranked[0] || null;
  if (best && sourceUnit) {
    sourceUnit.realtimeSupportPlan = {
      actionId,
      targetUnitId: best.targetUnit.id,
      targetCardId: best.targetUnit.cardId,
      score: Number(best.score || 0),
      modeId: String(modeId || getRealtimeCombatModeProfileForUnit(playerId, sourceUnit)?.activeId || ''),
      tags: REALTIME_SUPPORT_INTENT_DB[actionId]?.tags || [],
    };
  }
  return best?.targetUnit || null;
}

function chooseRealtimeBestGioshoninSupplyOption(playerId, sourceUnit, targetUnit, modeId = '') {
  const options = getGioshoninSupplyOptionsForTarget(targetUnit);
  if (!options.length) return null;
  const mode = String(modeId || getRealtimeCombatModeProfileForUnit(playerId, sourceUnit)?.activeId || 'defensive');

  return options
    .map(option => {
      let score = Math.max(1, Number(option.missing || 1)) * 14;
      if (option.type === 'baseWeapon') score += mode === 'offensive' ? 110 : 72;
      const text = `${option.id || ''} ${option.label || ''} ${option.runtimeField || ''}`;
      if (/smoke|humo|bomb/i.test(text)
          && (targetUnit.cardId === 'ninjaNaitoSutoka' || targetUnit.cardId === 'naitoSutoka')) {
        score += mode === 'defensive' ? 140 : 68;
      }
      return { option, score };
    })
    .sort((a, b) => b.score - a.score)[0]?.option || null;
}

function getRealtimeDefensiveSetupPositionScore(playerId, unit, row, col) {
  if (!unit || !isRealtimeRowOnOwnSide(playerId, row)) return 0;
  if (!(unit.cardId === 'ninjaNaitoSutoka' || unit.cardId === 'naitoSutoka')) return 0;
  if (Number(unit.smokeBombsLeft || 0) <= 0 || !unitHasAbility(unit, 'vigilia')) return 0;
  const simulated = { ...unit, row: Number(row), col: Number(col) };
  const placement = evaluateRealtimeSutokaSmokePlacement(playerId, simulated, { modeId: 'defensive' });
  return placement ? Math.max(0, Number(placement.score || 0)) : 0;
}


// v9.25 · Farolera estratégica -------------------------------------------------
// Farol Enlazado necesita una fase real de preparación. En RT la Farolera no
// planta el círculo en el punto donde fue kasteada: primero se coloca en una
// franja útil de su propio campo y, tras fijar la entrada, avanza hasta la
// frontera central antes de lanzar la lámpara.
function getRealtimeFaroleraStrategicRows(playerId) {
  return Number(playerId) === 1
    ? { setupRow: 12, frontierRow: 9 }
    : { setupRow: 5, frontierRow: 8 };
}

function getRealtimeFaroleraEnemyNexusPoints(playerId) {
  const enemyId = getEnemyPlayerId(playerId);
  const seen = new Set();
  const result = [];
  for (const enemy of state.players?.[enemyId]?.units || []) {
    if (!enemy) continue;
    const row = Number(enemy.restoreRow);
    const col = Number(enemy.restoreCol);
    if (!Number.isFinite(row) || !Number.isFinite(col) || !isInside(row, col)) continue;
    const key = `${row}:${col}`;
    if (seen.has(key)) continue;
    seen.add(key);
    result.push({ row, col });
  }
  return result;
}

function getRealtimeFaroleraCellAccessibility(playerId, unit, row, col) {
  let freeNeighbors = 0;
  for (const cell of getCellsInRadius(Number(row), Number(col), 1, true)) {
    if (ringDistance(Number(row), Number(col), cell.row, cell.col) !== 1) continue;
    if (!isInside(cell.row, cell.col)) continue;
    const occupiedBySelf = Number(unit?.row) === Number(cell.row) && Number(unit?.col) === Number(cell.col);
    if (!occupiedBySelf && isOccupied(cell.row, cell.col)) continue;
    if (isCastPlacementBlockedForPlayer(cell.row, cell.col, playerId)) continue;
    freeNeighbors += 1;
  }
  return freeNeighbors;
}

function getRealtimeFaroleraAlliedHechiceroAccessScore(playerId, unit, row, col) {
  const allies = (state.players?.[playerId]?.units || [])
    .filter(ally => ally && String(ally.id) !== String(unit?.id) && ally.status !== 'restoring' && Number(ally.hp ?? 0) > 0)
    .filter(ally => cardIsHechicero(CARD_LIBRARY?.[ally.cardId]));
  if (!allies.length) return 0;
  const distances = allies.map(ally => ringDistance(ally.row, ally.col, row, col));
  const closest = Math.min(...distances);
  const nearby = distances.filter(distance => distance <= 4).length;
  return Math.max(0, 28 - closest * 4) + nearby * 8;
}

function isRealtimeFaroleraStrategicCellUsable(playerId, unit, row, col) {
  if (!isInside(row, col) || !isRealtimeRowOnOwnSide(playerId, row)) return false;
  if (Number(unit?.row) === Number(row) && Number(unit?.col) === Number(col)) return true;
  if (isOccupied(row, col)) return false;
  // Para la estación de preparación evitamos casillas reservadas (Nexos,
  // estructuras, zonas de casteo bloqueadas). El movimiento normal puede
  // atravesar un Nexo; simplemente no lo usamos como punto táctico de reposo.
  return !isCastPlacementBlockedForPlayer(row, col, playerId);
}

function chooseRealtimeFaroleraSetupDestination(playerId, unit, modeId = '') {
  if (!unit) return null;
  const mode = String(modeId || getRealtimeCombatModeProfileForUnit(playerId, unit)?.activeId || 'defensive');
  const { setupRow } = getRealtimeFaroleraStrategicRows(playerId);
  const threats = getRealtimeDefensiveThreatEntries(playerId);
  const candidates = [];
  for (let row = setupRow - 2; row <= setupRow + 2; row += 1) {
    for (let col = 1; col <= 7; col += 1) {
      if (!isRealtimeFaroleraStrategicCellUsable(playerId, unit, row, col)) continue;
      const centerDistance = Math.abs(col - 4);
      const rowDistance = Math.abs(row - setupRow);
      const safety = getRealtimeDefensiveSafetyMarginAt(row, col, threats);
      const accessibility = getRealtimeFaroleraCellAccessibility(playerId, unit, row, col);
      let score = accessibility * 8 - rowDistance * 55;
      if (mode === 'defensive') {
        // v9.49 · Defensivo sigue premiando seguridad, pero ya no se fuga a un
        // flanco por sistema. Mantiene la infraestructura cerca del eje central
        // para que el círculo sea útil a más Hechiceros aliados.
        score += safety * 26 - centerDistance * 22;
      } else {
        // Ofensivo concentra todavía más el setup en el eje central para abrir
        // líneas de avance útiles a ambos lados del tablero.
        score += safety * 4 - centerDistance * 34;
      }
      candidates.push({ row, col, score, safety, accessibility });
    }
  }
  return candidates.sort((a, b) => b.score - a.score)[0] || null;
}

function chooseRealtimeFaroleraThrowStagingDestination(playerId, unit, modeId = '') {
  if (!unit) return null;
  const mode = String(modeId || getRealtimeCombatModeProfileForUnit(playerId, unit)?.activeId || 'defensive');
  const { frontierRow } = getRealtimeFaroleraStrategicRows(playerId);
  const threats = getRealtimeDefensiveThreatEntries(playerId);
  const candidates = [];
  const stagingRows = Number(playerId) === 1 ? [frontierRow, frontierRow + 1] : [frontierRow - 1, frontierRow];
  for (const row of stagingRows) {
    for (let col = 1; col <= 7; col += 1) {
      if (!isRealtimeFaroleraStrategicCellUsable(playerId, unit, row, col)) continue;
      const safety = getRealtimeDefensiveSafetyMarginAt(row, col, threats);
      const centerDistance = Math.abs(col - 4);
      const frontierDistance = Math.abs(Number(row) - Number(frontierRow));
      let score = -frontierDistance * 70;
      if (mode === 'defensive') {
        // La fase de lanzamiento defensiva busca una vía segura cerca del
        // centro; solo se apartará si la amenaza real hace mejor otra casilla.
        score += safety * 35 - centerDistance * 24;
      } else {
        score += safety * 5 - centerDistance * 34;
      }
      candidates.push({ row, col, score, safety });
    }
  }
  return candidates.sort((a, b) => b.score - a.score)[0] || null;
}

function getRealtimeFaroleraPinnedStrategicDestination(playerId, unit, stage, modeId = '') {
  if (!unit) return null;
  const resolvedStage = String(stage || getFarolEnlazadoStage(playerId, unit.id));
  const resolvedMode = String(modeId || getRealtimeCombatModeProfileForUnit(playerId, unit)?.activeId || 'defensive');
  const current = unit.realtimeFaroleraStrategicPlan;
  const currentValid = current
    && String(current.stage || '') === resolvedStage
    && String(current.modeId || '') === resolvedMode
    && Number.isFinite(Number(current.row))
    && Number.isFinite(Number(current.col))
    && isRealtimeFaroleraStrategicCellUsable(playerId, unit, Number(current.row), Number(current.col));
  if (currentValid) return { row: Number(current.row), col: Number(current.col), score: Number(current.score || 0) };

  const chosen = resolvedStage === 'idle'
    ? chooseRealtimeFaroleraSetupDestination(playerId, unit, resolvedMode)
    : (resolvedStage === 'circle'
      ? { row: Number(unit.row), col: Number(unit.col), score: 999 }
      : (resolvedStage === 'complete' ? chooseRealtimeFaroleraThrowStagingDestination(playerId, unit, resolvedMode) : null));
  if (!chosen) {
    unit.realtimeFaroleraStrategicPlan = null;
    return null;
  }
  unit.realtimeFaroleraStrategicPlan = {
    stage: resolvedStage,
    modeId: resolvedMode,
    row: Number(chosen.row),
    col: Number(chosen.col),
    score: Number(chosen.score || 0),
  };
  return { ...chosen, row: Number(chosen.row), col: Number(chosen.col) };
}

function isRealtimeFaroleraVisualMotionSettled(playerId, unit) {
  if (!unit || !isRealtimePlayStyle() || !state?.realtime?.active) return true;
  const key = getRealtimeSmoothMotionKey('invocation', playerId, unit.id);
  const track = realtimeSmoothMotionRuntime.tracks.get(key);
  if (!track) return true;
  return performance.now() >= Number(track.endsAt || 0) - 34;
}

function isRealtimeFaroleraReadyForCircle(playerId, unit, modeId = '') {
  const destination = getRealtimeFaroleraPinnedStrategicDestination(playerId, unit, 'idle', modeId);
  if (!destination) return false;
  const placementCells = getFarolCirclePlacementCells(playerId, unit);
  if (!placementCells.length || !chooseRealtimeFarolCell(playerId, unit, placementCells)) return false;
  return ringDistance(unit.row, unit.col, destination.row, destination.col) === 0
    && isRealtimeFaroleraVisualMotionSettled(playerId, unit);
}

function isRealtimeFaroleraReadyForThrow(playerId, unit, modeId = '') {
  if (!unit || getFarolEnlazadoStage(playerId, unit.id) !== 'circle') return false;
  // v9.51 · El primer farol NO espera a que la Farolera alcance la frontera.
  // Una vez existe el círculo, lo lanza desde donde esté para no exponerse sin
  // haber completado ninguna salida útil.
  const placementCells = getFarolLanternDestinationCells(playerId, unit, { reposition: false, stage: 'circle' });
  if (!placementCells.length || !chooseRealtimeFarolCell(playerId, unit, placementCells)) return false;
  return isRealtimeFaroleraVisualMotionSettled(playerId, unit);
}

function isRealtimeFaroleraReadyForStrategicRecast(playerId, unit, modeId = '') {
  if (!unit || getFarolEnlazadoStage(playerId, unit.id) !== 'complete') return false;
  const portal = getFarolPortalForSource(playerId, unit.id);
  if (!portal || Number(portal.aiStrategicRecasts || 0) >= 1) return false;
  const destination = getRealtimeFaroleraPinnedStrategicDestination(playerId, unit, 'complete', modeId);
  if (!destination) return false;
  const cells = getFarolLanternDestinationCells(playerId, unit, { reposition: true, stage: 'complete' });
  if (!cells.length || !chooseRealtimeFarolCell(playerId, unit, cells)) return false;
  return ringDistance(unit.row, unit.col, destination.row, destination.col) === 0
    && isRealtimeFaroleraVisualMotionSettled(playerId, unit);
}

function getRealtimeFaroleraStrategicIntent(playerId, unit, modeId, profile) {
  if (!unit || !isFaroleraUmbralUnit(unit)) return null;
  const stage = getFarolEnlazadoStage(playerId, unit.id);
  if (stage === 'idle') {
    const destination = getRealtimeFaroleraPinnedStrategicDestination(playerId, unit, 'idle', modeId);
    if (destination) {
      const ready = isRealtimeFaroleraReadyForCircle(playerId, unit, modeId);
      return {
        modeId,
        profile,
        target: null,
        destination: ready
          ? { row: Number(unit.row), col: Number(unit.col), type: 'faroleraHold' }
          : { row: destination.row, col: destination.col, type: 'faroleraSetup' },
        avoidCombat: true,
        affordanceDestination: true,
        faroleraStrategy: ready ? 'hold-circle' : 'setup-circle',
        faroleraHold: ready,
      };
    }
  }
  if (stage === 'circle') {
    // v9.51 · después de plantar el círculo no camina hacia el borde desarmada:
    // se queda y completa inmediatamente la primera salida del portal.
    const ready = isRealtimeFaroleraReadyForThrow(playerId, unit, modeId);
    return {
      modeId,
      profile,
      target: null,
      destination: { row: Number(unit.row), col: Number(unit.col), type: 'faroleraHold' },
      avoidCombat: true,
      affordanceDestination: true,
      faroleraStrategy: ready ? 'hold-lantern' : 'wait-lantern',
      faroleraHold: true,
    };
  }
  if (stage === 'complete') {
    const portal = getFarolPortalForSource(playerId, unit.id);
    if (portal && Number(portal.aiStrategicRecasts || 0) < 1) {
      const destination = getRealtimeFaroleraPinnedStrategicDestination(playerId, unit, 'complete', modeId);
      if (destination) {
        const ready = isRealtimeFaroleraReadyForStrategicRecast(playerId, unit, modeId);
        return {
          modeId,
          profile,
          target: null,
          destination: ready
            ? { row: Number(unit.row), col: Number(unit.col), type: 'faroleraHold' }
            : { row: destination.row, col: destination.col, type: 'faroleraRecastStaging' },
          avoidCombat: true,
          affordanceDestination: true,
          faroleraStrategy: ready ? 'hold-recast' : 'stage-recast',
          faroleraHold: ready,
        };
      }
    }
  }
  return null;
}

function scoreRealtimeFaroleraCircleCell(playerId, unit, cell, modeId = '') {
  if (!unit || !cell) return -Infinity;
  const mode = String(modeId || getRealtimeCombatModeProfileForUnit(playerId, unit)?.activeId || 'defensive');
  const threats = getRealtimeDefensiveThreatEntries(playerId);
  const forward = getFarolForwardProgress(playerId, unit.row, cell.row);
  const retreat = -forward;
  const safety = getRealtimeDefensiveSafetyMarginAt(cell.row, cell.col, threats);
  const access = getRealtimeFaroleraCellAccessibility(playerId, unit, cell.row, cell.col);
  const allyAccess = getRealtimeFaroleraAlliedHechiceroAccessScore(playerId, unit, cell.row, cell.col);
  const centerDistance = Math.abs(Number(cell.col) - 4);
  const edgePenalty = [0, 8].includes(Number(cell.col)) ? 120 : ([1, 7].includes(Number(cell.col)) ? 35 : 0);
  let score = access * 18 + allyAccess - centerDistance * 8 - edgePenalty;
  if (mode === 'defensive') {
    // Entrada protegida, pero centrada: el retroceso solo desempata dentro de
    // opciones seguras; el eje central pesa más que un flanqueo gratuito.
    score += safety * 26 + retreat * 45 - centerDistance * 20;
    if (forward > 0) score -= forward * 45;
  } else {
    // Ofensivo fija la entrada delante de sí misma y cerca del eje central.
    score += forward * 95 + safety * 4 - Math.max(0, retreat) * 80 - centerDistance * 26;
  }
  return score;
}

function scoreRealtimeFaroleraLanternCell(playerId, unit, cell, modeId = '') {
  if (!unit || !cell) return -Infinity;
  const enemyId = getEnemyPlayerId(playerId);
  const enemyCaster = state.players?.[enemyId]?.caster;
  const nexusPoints = getRealtimeFaroleraEnemyNexusPoints(playerId);
  const casterDistance = enemyCaster && Number(enemyCaster.life ?? 0) > 0
    ? ringDistance(cell.row, cell.col, enemyCaster.row, enemyCaster.col)
    : 8;
  const nexusDistance = nexusPoints.length
    ? Math.min(...nexusPoints.map(point => ringDistance(cell.row, cell.col, point.row, point.col)))
    : 5;
  const forward = getFarolForwardProgress(playerId, unit.row, cell.row);
  const edgePenalty = [0, 8].includes(Number(cell.col)) ? 24 : 0;
  const threats = getRealtimeDefensiveThreatEntries(playerId);
  const safety = getRealtimeDefensiveSafetyMarginAt(cell.row, cell.col, threats);
  const centerDistance = Math.abs(Number(cell.col) - 4);
  let score = forward * 34 - casterDistance * 52 + nexusDistance * 38 - edgePenalty - centerDistance * 16;
  if (String(modeId) === 'defensive') score += safety * 5 - centerDistance * 8;
  return score;
}

function getRealtimeAbilityContextScore(playerId, unit, actionId, modeId) {
  if (actionId === 'minokageShippuUgachi') {
    const target = chooseMinokageShippuTargetForMode(playerId, unit, getMinokagePowerTargets(playerId, unit), modeId);
    if (!target) return -Infinity;
    if (String(modeId) === 'siege') return 180;
    if (String(modeId) === 'assassination') return 170;
    if (String(modeId) === 'offensive') return 160;
    if (String(modeId) === 'hunt') return 160;
    return 120;
  }
  if (actionId === 'kaguyaChargedShot') {
    const target = chooseKaguyaChargedShotTargetForMode(playerId, unit, getKaguyaChargedShotTargets(playerId, unit), modeId);
    if (!target) return -Infinity;
    const pos = getTargetBoardPosition(target);
    const distance = pos ? ringDistance(unit.row, unit.col, pos.row, pos.col) : 999;
    const normalRange = Math.max(1, Number((getEffectiveAttackProfile(CARD_LIBRARY?.[unit.cardId], unit, playerId) || {}).range || 1));
    // Una casilla fuera del alcance normal es la ventana ideal de anticipación.
    const anticipationBonus = distance === normalRange + 1 ? 70 : 0;
    return 120 + anticipationBonus;
  }
  if (actionId === 'kurayamiDeathSeal') {
    if (String(modeId) === 'assassination') return -Infinity;
    const target = chooseKurayamiPowerTargetForMode(playerId, unit, getKurayamiPowerTargets(playerId, unit), modeId);
    return target ? 120 : -Infinity;
  }
  if (actionId === 'sutokaSmokeBomb') {
    const placement = evaluateRealtimeSutokaSmokePlacement(playerId, unit, { modeId });
    return placement
      ? Math.max(0, Math.min(220, Number(placement.score || 0)))
      : -Infinity;
  }

  if (actionId === 'seyranDistorsion') {
    const plan = chooseRealtimeSeyranDistortionPlan(playerId, unit, modeId);
    return plan ? Number(plan.score || 0) : -Infinity;
  }

  if (actionId === 'maerynDomination') {
    const plan = chooseRealtimeMaerynDominationTarget(playerId, unit);
    return plan ? Math.max(40, Math.min(240, Number(plan.score || 0))) : -Infinity;
  }

  if (actionId === 'odaNoKageShadow') {
    // v9.61 · Esta sinergia se comprueba en cada ciclo de decisión de IA.
    // Nobunaga solo necesita estar activo en Arena; Oda no Kage no tiene que
    // estar cerca. Si la casilla posterior está ocupada, el candidato desaparece
    // y se vuelve a evaluar automáticamente en el siguiente ciclo.
    const nobunaga = getActiveNobunagaUnitForPlayer(playerId);
    if (!nobunaga || !canActivateOdaNoKageShadow(playerId, unit)) return -Infinity;
    return 900;
  }

  if (actionId === 'yasuganaGenyutsu') {
    const availability = getYasuganaPowerAvailability(playerId, unit);
    if (modeId === 'assassination') return -Infinity;
    const blindTarget = availability.canBlind
      ? chooseYasuganaBlindnessTargetForMode(playerId, unit, availability.blindnessTargets, modeId)
      : null;
    if (modeId === 'defensive') {
      const urgentBlind = blindTarget && isRealtimeEnemyActivelyThreateningPlayer(playerId, blindTarget);
      if (urgentBlind) return 112;
      const sutoka = availability.canTeach
        ? chooseYasuganaVigiliaTargetForAi(playerId, unit, availability.vigiliaTargets)
        : null;
      if (sutoka) return 96;
      return blindTarget ? 72 : -Infinity;
    }
    if (modeId === 'offensive' || modeId === 'hunt') return blindTarget ? 88 : -Infinity;
    return -Infinity;
  }

  if (actionId === 'farolEnlazado') {
    const stage = getFarolEnlazadoStage(playerId, unit.id);
    if (stage === 'throwing') return -Infinity;
    if (stage === 'complete') {
      const rescue = modeId === 'defensive' ? getRealtimeFarolRescuePlan(playerId, unit) : null;
      if (rescue) return Math.max(85, Math.min(260, Number(rescue.score || 0)));
      return isRealtimeFaroleraReadyForStrategicRecast(playerId, unit, modeId) ? 430 : -Infinity;
    }
    // v9.51: Etapa 1 mantiene una instalación estratégica; Etapa 2 se lanza
    // inmediatamente tras fijar el círculo. La frontera queda reservada para
    // el relanzamiento posterior de la lámpara, no para completar el portal.
    if (stage === 'idle') {
      return isRealtimeFaroleraReadyForCircle(playerId, unit, modeId) ? 520 : -Infinity;
    }
    if (stage === 'circle') {
      return isRealtimeFaroleraReadyForThrow(playerId, unit, modeId) ? 560 : -Infinity;
    }
    return -Infinity;
  }

  if (actionId === 'gioshoninSupply') {
    const targets = getAffordableGioshoninSupplyTargets(playerId, unit);
    const best = chooseRealtimeBestSupportTarget(playerId, unit, targets, 'gioshoninSupply', modeId);
    return best
      ? Math.max(24, Math.min(190, scoreRealtimeSupportTarget(playerId, unit, best, 'gioshoninSupply', modeId)))
      : -Infinity;
  }

  return 0;
}

function getRealtimeAutomatedAbilityCandidates(second) {
  if (!isRealtimeAbilityContext() || realtimeStage5Runtime.abilityBusy || state.pendingPowerAction || state.randomCostPayment) return [];
  const candidates = [];
  const playerOrder = Number(second || 0) % 2 === 0 ? [2, 1] : [1, 2];
  for (const playerId of playerOrder) {
    for (const unit of state.players?.[playerId]?.units || []) {
      if (!unit || unit.status === 'restoring' || Number(unit.hp ?? 0) <= 0 || isRealtimeEntityLocked(realtimeUnitEntityKey(playerId, unit.id))) continue;
      const retryKey = `${playerId}:${unit.id}`;
      if (Number(realtimeStage5Runtime.unitAbilityNextSecond.get(retryKey) || 0) > Number(second || 0)) continue;
      const profile = getRealtimeCombatModeProfileForUnit(playerId, unit);
      const modeId = profile?.activeId || 'offensive';
      const automationMode = getInvocationPowerAutomationMode(playerId, unit);
      const manualArmed = automationMode === 'manual' && Boolean(unit.realtimePowerArmed);
      if (automationMode === 'manual' && !manualArmed) continue;
      const actions = getVoluntaryPowerActionDescriptorsNow(playerId, unit, { shortLabel: true })
        .filter(action => ['farolEnlazado', 'seyranDistorsion', 'maerynDomination', 'sutokaSmokeBomb', 'odaNoKageShadow', 'minokageShippuUgachi', 'kaguyaChargedShot', 'yasuganaGenyutsu', 'kurayamiDeathSeal', 'kurokagiWeaponShift', 'gioshoninSupply', 'kishimotoLimits', 'takedaOldFriend'].includes(action.id));
      for (const action of actions) {
        const contextScore = getRealtimeAbilityContextScore(playerId, unit, action.id, modeId);
        if (!Number.isFinite(contextScore)) continue;
        candidates.push({
          playerId,
          unit,
          action,
          modeId,
          automationMode,
          manualArmed,
          contextScore,
          score: getRealtimeAbilityModeWeight(modeId, action.id)
            + contextScore
            + (manualArmed ? 1000 : 0),
        });
      }
    }
  }
  return candidates.sort((a, b) => b.score - a.score);
}

function getRealtimeFarolCorneredAllyEntries(playerId, farolera, portal) {
  if (!farolera || !portal || portal.originRow == null || portal.originCol == null) return [];
  const enemyEntries = getRealtimeEnemyInvocationCandidates(playerId);
  return (state.players?.[playerId]?.units || [])
    .filter(ally => ally && String(ally.id) !== String(farolera.id) && ally.status !== 'restoring' && Number(ally.hp ?? 0) > 0)
    .filter(ally => cardIsHechicero(CARD_LIBRARY?.[ally.cardId]))
    .map(ally => {
      const card = CARD_LIBRARY?.[ally.cardId];
      const movement = Math.max(1, Number(card?.stats?.mov ?? ally.mov ?? 1));
      const circleDistance = ringDistance(ally.row, ally.col, Number(portal.originRow), Number(portal.originCol));
      const reachWindow = Math.max(2, Math.min(3, movement + 1));
      if (circleDistance > reachWindow) return null;

      let directAttackers = 0;
      let threateningEnemies = 0;
      let pressure = 0;
      for (const entry of enemyEntries) {
        const enemy = entry.unit;
        if (!enemy) continue;
        const descriptor = getRealtimeUnitAttackTargetDescriptor(enemy);
        const directlyTargets = descriptor?.type === 'invocation'
          && Number(descriptor.playerId) === Number(playerId)
          && String(descriptor.unitId) === String(ally.id);
        const attack = getEffectiveAttackProfile?.(entry.card, enemy, entry.playerId)
          || getAttackProfile?.(entry.card)
          || {};
        const range = Math.max(1, Number(attack.range ?? 1));
        const distance = ringDistance(enemy.row, enemy.col, ally.row, ally.col);
        if (directlyTargets) directAttackers += 1;
        if (distance <= range + 1) threateningEnemies += 1;
        if (directlyTargets) pressure += 2.5;
        else if (distance <= range) pressure += 1.5;
        else if (distance <= range + 1) pressure += .65;
      }

      // "Acorralada" exige presión real de más de una amenaza, o al menos un
      // atacante directo acompañado por presión adicional. No rescatamos por
      // una sola pieza lejana ni por peligro hipotético.
      const cornered = threateningEnemies >= 2 || (directAttackers >= 1 && pressure >= 3);
      if (!cornered) return null;
      const maxHp = Math.max(1, Number(ally.maxHp ?? ally.baseHp ?? card?.stats?.life ?? ally.hp ?? 1));
      const hpRatio = Math.max(0, Math.min(1, Number(ally.hp ?? maxHp) / maxHp));
      const score = directAttackers * 90
        + threateningEnemies * 48
        + pressure * 28
        + (1 - hpRatio) * 55
        - circleDistance * 12;
      return { ally, circleDistance, directAttackers, threateningEnemies, pressure, score };
    })
    .filter(Boolean)
    .sort((a, b) => b.score - a.score);
}

function getRealtimeFarolRescuePlan(playerId, unit) {
  // v9.52 · Se elimina la reubicación de rescate hacia retaguardia. El usuario
  // definió que el Farol no debe lanzarse hacia atrás bajo ninguna circunstancia.
  // La infraestructura defensiva conserva el portal existente y la Farolera se
  // protege atacando durante su desplazamiento, en vez de invertir la salida.
  return null;
  /*
  if (!unit || getRealtimeCombatModeProfileForUnit(playerId, unit)?.activeId !== 'defensive') return null;
  const portal = getFarolPortalForSource(playerId, unit.id);
  if (!portal || portal.stage !== 'complete' || portal.destinationRow == null || portal.destinationCol == null) return null;
  const targetEntry = getRealtimeFarolCorneredAllyEntries(playerId, unit, portal)[0] || null;
  if (!targetEntry) return null;

  const threats = getRealtimeDefensiveThreatEntries(playerId);
  const caster = state.players?.[playerId]?.caster;
  const currentSafety = getRealtimeDefensiveSafetyMarginAt(Number(portal.destinationRow), Number(portal.destinationCol), threats);
  const currentRetreat = getFarolRetreatProgress(playerId, unit.row, Number(portal.destinationRow));
  const currentOwnSide = isRealtimeRowOnOwnSide(playerId, Number(portal.destinationRow));

  const candidates = getFarolLanternDestinationCells(playerId, unit, { reposition: true, stage: 'complete' })
    .map(cell => {
      const retreat = getFarolRetreatProgress(playerId, unit.row, cell.row);
      if (retreat <= 0) return null;
      const safety = getRealtimeDefensiveSafetyMarginAt(cell.row, cell.col, threats);
      const ownSide = isRealtimeRowOnOwnSide(playerId, cell.row);
      const casterDistance = caster ? ringDistance(cell.row, cell.col, caster.row, caster.col) : 0;
      const score = safety * 38
        + retreat * 24
        + (ownSide ? 85 : 0)
        - casterDistance * 3;
      return { ...cell, safety, retreat, ownSide, score };
    })
    .filter(Boolean)
    .sort((a, b) => b.score - a.score);
  const cell = candidates[0] || null;
  if (!cell) return null;

  // Si la lámpara ya está realmente atrás y su margen de seguridad es igual o
  // mejor que la nueva opción, no la relanzamos cada pocos segundos.
  if (currentRetreat > 0 && currentSafety >= cell.safety && (currentOwnSide || !cell.ownSide)) return null;
  return {
    targetUnit: targetEntry.ally,
    targetEntry,
    cell,
    score: Math.max(80, targetEntry.score + cell.score),
  };
  */
}

function chooseRealtimeFarolCell(playerId, unit, cells) {
  if (!cells?.length || !unit) return null;
  const stage = getFarolEnlazadoStage(playerId, unit.id);
  const modeId = getRealtimeCombatModeProfileForUnit(playerId, unit)?.activeId || 'defensive';

  if (stage === 'complete') {
    const rescue = getRealtimeFarolRescuePlan(playerId, unit);
    if (rescue?.cell && cells.some(cell => cell.row === rescue.cell.row && cell.col === rescue.cell.col)) return rescue.cell;
  }

  if (stage === 'idle') {
    // El círculo se decide como infraestructura, no como "casilla libre más
    // cercana". Ofensivo lo quiere delante y céntrico; Defensivo, algo más
    // protegido/retrasado. Ambos premian que tenga accesos libres y que los
    // Hechiceros aliados puedan alcanzarlo.
    const preferred = cells.filter(cell => {
      const forward = getFarolForwardProgress(playerId, unit.row, cell.row);
      return modeId === 'defensive' ? forward <= 0 : forward > 0;
    });
    const pool = preferred.length ? preferred : cells;
    return pool.slice()
      .map(cell => ({ ...cell, tacticalScore: scoreRealtimeFaroleraCircleCell(playerId, unit, cell, modeId) }))
      .sort((a, b) => b.tacticalScore - a.tacticalScore)[0] || null;
  }

  if (stage === 'circle') {
    // La primera lámpara aprovecha que la Farolera ya llegó a la frontera
    // central. Se acerca al Kaster rival, pero evita colocar la salida encima
    // de los Nexos enemigos para que el Hechicero que emerge no sea castigado
    // inmediatamente por el respawn.
    return cells.slice()
      .map(cell => ({ ...cell, tacticalScore: scoreRealtimeFaroleraLanternCell(playerId, unit, cell, modeId) }))
      .sort((a, b) => b.tacticalScore - a.tacticalScore)[0] || null;
  }

  // Reubicaciones defensivas completadas conservan la lógica específica de
  // rescate; cualquier otro caso usa una elección segura de respaldo.
  const threats = getRealtimeDefensiveThreatEntries(playerId);
  return cells.slice()
    .map(cell => ({
      ...cell,
      tacticalScore: getRealtimeDefensiveSafetyMarginAt(cell.row, cell.col, threats) * 20,
    }))
    .sort((a, b) => b.tacticalScore - a.tacticalScore)[0] || null;
}

async function executeRealtimeAutomatedAbility(candidate, second) {
  if (!candidate?.unit || !candidate?.action || !isRealtimeAbilityContext(candidate.playerId)) return false;
  const { playerId, unit, action, modeId } = candidate;
  const retryKey = `${playerId}:${unit.id}`;
  realtimeStage5Runtime.unitAbilityNextSecond.set(retryKey, Number(second || 0) + REALTIME_ABILITY_RETRY_SECONDS);
  realtimeStage5Runtime.abilityBusy = true;
  realtimeStage5Runtime.autoAbilityDepth += 1;
  realtimeStage5Runtime.currentAbilityLabel = action.title || action.label || action.id;
  setRealtimeTempoPause(true, realtimeStage5Runtime.currentAbilityLabel, 'auto-ability');
  let activated = false;
  try {
    if (action.id === 'maerynDomination') {
      const plan = chooseRealtimeMaerynDominationTarget(playerId, unit);
      if (plan?.target && beginMaerynDominationTargeting(playerId, unit.id)) {
        activated = Boolean(resolveMaerynDomination(
          playerId,
          unit.id,
          Number(plan.target.owner),
          plan.target.id,
        ));
      }
    } else if (action.id === 'seyranDistorsion') {
      const plan = chooseRealtimeSeyranDistortionPlan(playerId, unit, modeId);
      if (plan?.target && beginSeyranDistortionTargeting(playerId, unit.id)) {
        try {
          recordRokMatchDiagnostic('seyran-distortion-plan', 'Seyran elige plan táctico de Distorsión Espacial.', {
            playerId: Number(playerId),
            unitId: String(unit.id),
            modeId: String(modeId || ''),
            targetOwnerId: Number(plan.target.owner),
            targetUnitId: String(plan.target.id),
            relation: plan.relation,
            operation: plan.mode,
            destination: plan.destination,
            score: Number(plan.score || 0),
            reasons: Array.isArray(plan.reasons) ? plan.reasons : [],
          });
        } catch (_) {}
        activated = Boolean(resolveSeyranDistortion(
          playerId,
          unit.id,
          Number(plan.target.owner),
          plan.target.id,
          plan.mode,
        ));
        if (!activated && state.pendingPowerAction?.kind === 'seyranDistorsionTarget') {
          cancelSeyranDistortionTargeting('Distorsión Espacial automática cancelada: el plan dejó de ser válido.');
        }
      }
    } else if (action.id === 'minokageShippuUgachi') {
      const target = chooseMinokageShippuTargetForMode(playerId, unit, getMinokagePowerTargets(playerId, unit), modeId);
      if (target && beginMinokagePowerTargeting(playerId, unit.id)) activated = Boolean(await resolveMinokagePowerTarget(playerId, unit.id, target));
    } else if (action.id === 'kaguyaChargedShot') {
      const target = chooseKaguyaChargedShotTargetForMode(playerId, unit, getKaguyaChargedShotTargets(playerId, unit), modeId);
      if (target && activateKaguyaChargedShotPower(playerId, unit.id)) {
        activated = Boolean(await resolveKaguyaChargedShotTarget(playerId, unit.id, target));
      }
    } else if (action.id === 'kurayamiDeathSeal') {
      const targetUnit = chooseKurayamiPowerTargetForMode(playerId, unit, getKurayamiPowerTargets(playerId, unit), modeId);
      if (targetUnit && beginKurayamiPowerTargeting(playerId, unit.id)) activated = Boolean(resolveKurayamiPowerTarget(playerId, unit.id, getOpponentId(playerId), targetUnit.id));
    } else if (action.id === 'yasuganaGenyutsu') {
      const availability = getYasuganaPowerAvailability(playerId, unit);
      const blindTarget = availability.canBlind
        ? chooseYasuganaBlindnessTargetForMode(playerId, unit, availability.blindnessTargets, modeId)
        : null;
      const sutokaTarget = availability.canTeach
        ? chooseYasuganaVigiliaTargetForAi(playerId, unit, availability.vigiliaTargets)
        : null;
      let kind = '';
      let targetUnit = null;
      if (modeId === 'defensive') {
        if (blindTarget && isRealtimeEnemyActivelyThreateningPlayer(playerId, blindTarget)) {
          kind = 'yasuganaBlindness'; targetUnit = blindTarget;
        } else if (sutokaTarget) {
          kind = 'yasuganaVigilia'; targetUnit = sutokaTarget;
        } else if (blindTarget) {
          kind = 'yasuganaBlindness'; targetUnit = blindTarget;
        }
      } else if ((modeId === 'offensive' || modeId === 'hunt') && blindTarget) {
        kind = 'yasuganaBlindness'; targetUnit = blindTarget;
      }
      if (kind && targetUnit && beginYasuganaPowerTargeting(playerId, unit.id, kind)) {
        activated = Boolean(resolveYasuganaPowerTarget(
          playerId,
          unit.id,
          kind === 'yasuganaBlindness' ? getOpponentId(playerId) : playerId,
          targetUnit.id,
          kind,
        ));
      }
    } else if (action.id === 'sutokaSmokeBomb') {
      const placement = evaluateRealtimeSutokaSmokePlacement(playerId, unit, { modeId });
      const cell = placement?.cell || null;
      if (cell && beginSmokeBombTargeting(playerId, unit.id) !== false) {
        unit.realtimeLastSmokePlan = {
          row: cell.row,
          col: cell.col,
          modeId,
          score: Number(placement.score || 0),
          coveredAllies: placement.coveredAllies || [],
          coveredThreatened: placement.coveredThreatened || [],
          protectedAllies: placement.protectedAllies || [],
          routeProgress: Number(placement.routeProgress || 0),
        };
        activated = Boolean(await resolveSmokeBombAt(cell.row, cell.col));
      }
    } else if (action.id === 'odaNoKageShadow') {
      activated = Boolean(await activateOdaNoKageShadow(playerId, unit.id, { instant: true, silent: true }));
    } else if (action.id === 'farolEnlazado') {
      const stage = getFarolEnlazadoStage(playerId, unit.id);
      const rescuePlan = stage === 'complete' ? getRealtimeFarolRescuePlan(playerId, unit) : null;
      const strategicRecast = stage === 'complete' && !rescuePlan && isRealtimeFaroleraReadyForStrategicRecast(playerId, unit, modeId);
      const cells = stage === 'idle'
        ? getFarolCirclePlacementCells(playerId, unit)
        : (stage === 'circle'
          ? getFarolLanternDestinationCells(playerId, unit, { reposition: false, stage })
          : ((rescuePlan || strategicRecast) ? getFarolLanternDestinationCells(playerId, unit, { reposition: true, stage: 'complete' }) : []));
      const cell = rescuePlan?.cell || chooseRealtimeFarolCell(playerId, unit, cells);
      // v9.49 · Elegimos la casilla antes de abrir targeting. Así una geometría
      // que cambió entre el score y la ejecución no deja pendingPowerAction
      // bloqueando para siempre el resto de la IA.
      if (cell && beginFarolEnlazadoTargeting(playerId, unit.id)) {
        if (rescuePlan?.targetUnit && state.pendingPowerAction?.kind === 'farolEnlazadoLamp') {
          state.pendingPowerAction.rescueTargetUnitId = rescuePlan.targetUnit.id;
        }
        if (strategicRecast && state.pendingPowerAction?.kind === 'farolEnlazadoLamp') {
          state.pendingPowerAction.aiStrategicRecast = true;
        }
        activated = stage === 'idle'
          ? Boolean(resolveFarolEnlazadoCircleTarget(playerId, unit.id, cell.row, cell.col))
          : Boolean(await resolveFarolEnlazadoLamp(playerId, unit.id, cell.row, cell.col));
        if (!activated && ['farolEnlazadoCircle', 'farolEnlazadoLamp'].includes(String(state.pendingPowerAction?.kind || ''))) {
          cancelFarolEnlazadoTargeting('');
        }
      }
    } else if (action.id === 'kishimotoLimits') {
      const selection = buildRealtimeFlexibleCostSelection(playerId, KISHIMOTO_LIMIT_COST);
      if (selection) activated = Boolean(resolveKishimotoLimitsPayment({ mode: 'kishimotoLimits', playerId, unitId: unit.id, cardId: unit.cardId }, selection));
    } else if (action.id === 'takedaOldFriend') {
      activated = Boolean(await executeAiTakedaOldFriend(playerId, unit.id));
    } else if (action.id === 'gioshoninSupply') {
      const targets = getAffordableGioshoninSupplyTargets(playerId, unit);
      const targetUnit = chooseRealtimeBestSupportTarget(
        playerId, unit, targets, 'gioshoninSupply', modeId
      );
      const option = targetUnit
        ? chooseRealtimeBestGioshoninSupplyOption(playerId, unit, targetUnit, modeId)
        : null;
      if (targetUnit && option) {
        const needed = option.type === 'baseWeapon' ? 2 : 1;
        const selection = buildRealtimeFlexibleCostSelection(playerId, needed);
        if (selection) {
          state.pendingPowerAction = { kind: 'gioshoninSupply', playerId, unitId: unit.id, targetUnitId: targetUnit.id };
          activated = Boolean(resolveGioshoninRandomCostPayment({
            mode: 'gioshoninSupply', playerId, cardId: unit.cardId, sourceUnitId: unit.id,
            targetUnitId: targetUnit.id, actionType: option.type, consumableId: option.id || null,
            runtimeField: option.runtimeField || null, quantity: 1, needed,
          }, selection));
        }
      }
    } else if (action.id === 'kurokagiWeaponShift') {
      if (unitHasKurokagiBukiPickupReady(unit)) {
        const candidates = getKurokagiBukiPickupCandidates(unit);
        const selected = chooseRealtimeKurokagiWeaponCandidate(playerId, unit, candidates, modeId);
        if (selected) {
          activated = Boolean(await captureKurokagiDroppedWeapon({ playerId, unit, card: CARD_LIBRARY[unit.cardId] }, selected));
          if (activated) {
            unit.kurokagiBukiPickupCandidates = [];
            unit.kurokagiBukiPickupReady = false;
            unit.kurokagiBukiResolutionPending = false;
            unit.movesLeft = 0;
            if (unit.status !== 'restoring') restoreInvocation(playerId, unit, 'Buki Utsushi');
          }
        }
      } else {
        const captured = getKurokagiCapturedWeaponProfile(unit);
        if (captured) {
          const primary = getEffectiveAttackProfile(CARD_LIBRARY[unit.cardId], { ...unit, kurokagiWeaponMode: 'primary' }, playerId) || {};
          const preferCaptured = modeId !== 'defensive' && (Number(captured.damage || 0) > Number(primary.damage || 0) || Number(captured.range || 0) > Number(primary.range || 0));
          activated = Boolean(applyKurokagiWeaponChoice(playerId, unit.id, preferCaptured ? 'captured' : 'primary'));
        }
      }
    }
    if (activated) {
      const abilitySystem = ensureRealtimeStage5State().abilitySystem;
      abilitySystem.activations = Math.max(0, Number(abilitySystem.activations || 0)) + 1;
      abilitySystem.lastAbility = realtimeStage5Runtime.currentAbilityLabel;
      if (getInvocationPowerAutomationMode(playerId, unit) === 'manual') unit.realtimePowerArmed = false;
      // RT-08.4 · La propia animación/FX comunica la activación automática;
      // no añadimos un aviso textual extra por cada decisión de IA.
    }
  } catch (error) {
    reportDebugError(`realtime-ability:${action.id}`, error);
    if (state.pendingPowerAction && Number(state.pendingPowerAction.playerId) === Number(playerId) && String(state.pendingPowerAction.unitId || '') === String(unit.id || '')) state.pendingPowerAction = null;
  } finally {
    // RT-08.12 · Si una resolución automática salió por objetivo inválido,
    // excepción o cancelación, su selección temporal no puede transformarse en
    // una interacción manual invisible.
    cleanupRealtimeAutomatedAbilityResidue(playerId, unit.id);
    realtimeStage5Runtime.autoAbilityDepth = Math.max(0, realtimeStage5Runtime.autoAbilityDepth - 1);
    realtimeStage5Runtime.abilityBusy = false;
    realtimeStage5Runtime.currentAbilityLabel = '';
    if (state?.realtime?.tempoPause?.source === 'auto-ability') {
      setRealtimeTempoPause(false, '', 'auto-ability');
    }
    try { renderAll('realtime-ability-settled'); } catch (_) {}
  }
  return activated;
}

function scheduleRealtimeAutomatedAbility(second) {
  if (!isRealtimeAbilityContext() || realtimeStage5Runtime.abilityBusy || isRealtimeTempoPaused()) return false;
  const interval = Math.max(1, Math.round(getRealtimeTimingValue('aiDecisionSeconds')));
  if (Number(second || 0) <= 0 || Number(second) % interval !== 0) return false;
  if (Number(second || 0) <= Number(realtimeStage5Runtime.lastAbilityDecisionSecond || 0)) return false;
  realtimeStage5Runtime.lastAbilityDecisionSecond = Number(second || 0);
  const abilitySystem = ensureRealtimeStage5State().abilitySystem;
  abilitySystem.lastDecisionSecond = Number(second || 0);
  const candidate = getRealtimeAutomatedAbilityCandidates(second)[0];
  if (!candidate) return false;
  void executeRealtimeAutomatedAbility(candidate, second);
  return true;
}

function processRealtimeLegacyTurnBoundary(second) {
  const bucket = 1 + Math.floor(Math.max(0, Number(second || 1) - 1) / REALTIME_LEGACY_TURN_SECONDS);
  if (bucket <= Number(realtimeStage5Runtime.lastLegacyTurnBucket || 0)) return false;
  realtimeStage5Runtime.lastLegacyTurnBucket = bucket;
  state.turnSerial = Math.max(1, bucket);
  const temporal = ensureRealtimeStage5State().temporalSystem;
  temporal.legacyTurnSerial = state.turnSerial;
  for (const playerId of [1, 2]) {
    try { resolveCamuflajeAtTurnEnd(playerId); } catch (_) {}
    try { beginCamuflajeTurnTracking(playerId); } catch (_) {}
    try { clearTurnActionCommitted(playerId); } catch (_) {}
  }
  return true;
}

function processRealtimeTemporalSecond(second) {
  if (!isRealtimeAbilityContext() || realtimeStage5Runtime.temporalBusy) return false;
  if (Number(second || 0) <= Number(realtimeStage5Runtime.lastProcessedSecond || 0)) return false;
  realtimeStage5Runtime.lastProcessedSecond = Number(second || 0);
  const temporal = ensureRealtimeStage5State().temporalSystem;
  temporal.lastProcessedSecond = Number(second || 0);

  // Una resolución lógica nueva por ciclo evita heredar el límite de ataque
  // de una fase anterior en los combates sostenidos del modo Tiempo real.
  state.resolutionSerial = Math.max(1, Number(second || 1));
  state.resolutionActionTaken = false;
  if (Number(second) % REALTIME_TEMPORAL_STEP_SECONDS === 0) {
    advancePhaseTransitionCounters(`realtime-second-${second}`);
    advanceBurnFactorsOnePhaseStep();
    try { applyCasterEnemySideDamage(); } catch (_) {}
    try { syncSaqueadorNovatoSigiloState(); } catch (_) {}
    try { refreshGuardianAuraState({ announceNew: true }); } catch (_) {}
  }
  processRealtimeLegacyTurnBoundary(second);
  processRealtimeTakedaAttackGrowth(second);

  const hasImmediate = Array.isArray(state.pendingImmediateMinokageResolutions) && state.pendingImmediateMinokageResolutions.length > 0;
  const hasTimed = Array.isArray(state.pendingTimedAbilityResolutions) && state.pendingTimedAbilityResolutions.length > 0;
  if ((hasImmediate || hasTimed) && !realtimeStage5Runtime.temporalBusy) {
    realtimeStage5Runtime.temporalBusy = true;
    setRealtimeTempoPause(true, 'Resolución de habilidad', 'timed-ability');
    void (async () => {
      try {
        if (hasImmediate) await resolvePendingImmediateMinokageResolutions();
        if (hasTimed) await resolvePendingTimedAbilityResolutions();
      } catch (error) {
        reportDebugError('realtime-timed-ability-resolution', error);
      } finally {
        realtimeStage5Runtime.temporalBusy = false;
        setRealtimeTempoPause(false, '', 'timed-ability');
        renderAll('realtime-timed-ability-settled');
      }
    })();
  }
  return true;
}


function processRealtimeActionClock(activeMs = null) {
  if (!canRunRealtimeSimulation() || isRealtimeTempoPaused() || isGlobalGameplayPaused()) return false;
  const nowMs = Math.max(0, Number(activeMs ?? getRealtimeActiveElapsedMs()));
  const nowSecond = Math.floor(nowMs / 1000);
  const system = ensureRealtimeMovementSystemState();
  if (!system.initialized) initializeRealtimeMovementSystem();

  let changed = false;
  scheduleRealtimeSustainedCombats(nowMs);

  for (const playerId of [1, 2]) {
    const units = [...(state.players?.[playerId]?.units || [])];
    for (const unit of units) {
      if (!unit || unit.status === 'restoring' || Number(unit.hp ?? 0) <= 0) continue;
      const key = realtimeUnitEntityKey(playerId, unit.id);
      if (isRealtimeEntityLocked(key) || isUnitEngaged(unit)) continue;

      // Una unidad recién llegada al tablero recibe primero su cadencia. Esto
      // evita aparecer y disparar/moverse en el mismo instante del kasteo.
      if (!Number.isFinite(Number(unit.realtimeNextMoveAtMs))) {
        unit.realtimeNextMoveAtMs = nowMs + getRealtimeMoveIntervalSecondsForUnit(unit) * 1000;
      }
      if (!Number.isFinite(Number(unit.realtimeNextDecisionAtMs))) {
        unit.realtimeNextDecisionAtMs = nowMs + getRealtimeTimingValue('aiDecisionSeconds') * 1000;
      }

      if (unit.realtimeAttackTelegraph) {
        if (resolveRealtimeAttackPreparation(playerId, unit, nowMs)) changed = true;
        // Mientras prepara el ataque no camina.
        continue;
      }

      const decisionDue = nowMs >= Number(unit.realtimeNextDecisionAtMs || 0);
      let combatIntent = null;
      let attackDecision = null;

      if (decisionDue) {
        unit.realtimeNextDecisionAtMs = nowMs + getRealtimeTimingValue('aiDecisionSeconds') * 1000;
        combatIntent = getRealtimeCombatIntent(playerId, unit);
        attackDecision = getRealtimeAutomaticAttackDecision(playerId, unit, combatIntent);
        if (attackDecision.target && isRealtimeAttackReady(unit, nowMs)) {
          if (startRealtimeAttackPreparation(playerId, unit, attackDecision.target, nowMs)) changed = true;
          continue;
        }
        if (attackDecision.wait) {
          unit.movesLeft = 0;
          continue;
        }
      }

      if (nowMs < Number(unit.realtimeNextMoveAtMs || 0)) continue;

      combatIntent = combatIntent || getRealtimeCombatIntent(playerId, unit);

      // Durante recuperación solo se mantiene quieta si existe un objetivo que
      // su Modo realmente prioriza. Un enemigo irrelevante al costado ya no
      // congela a Ofensivo/Asesinato mientras avanzan hacia el Kaster.
      const holdDecision = getRealtimeAutomaticAttackDecision(playerId, unit, combatIntent);
      if (holdDecision?.wait || holdDecision?.target) {
        unit.realtimeNextMoveAtMs = nowMs + Math.min(1000, getRealtimeMoveIntervalSecondsForUnit(unit) * 1000);
        continue;
      }

      unit.movesLeft = 1;
      const moved = moveRealtimeInvocationOneStep(playerId, unit, nowSecond, combatIntent);
      unit.realtimeNextMoveAtMs = nowMs + getRealtimeMoveIntervalSecondsForUnit(unit) * 1000;
      if (moved) changed = true;
    }
  }

  // La IA de Poderes comparte el reloj de decisión, pero no el Tempo maestro.
  scheduleRealtimeAutomatedAbility(nowSecond);
  if (changed) renderAll('realtime-action-clock');
  return changed;
}

function processRealtimeStage3Second(second) {
  if (!canRunRealtimeSimulation()) return false;
  const system = ensureRealtimeMovementSystemState();
  if (!system.initialized) initializeRealtimeMovementSystem();
  if (Number(second || 0) <= Number(system.lastProcessedSecond || 0)) return false;
  system.lastProcessedSecond = Number(second || 0);
  realtimeStage3Runtime.lastProcessedSecond = Number(second || 0);

  // RT-05: todos los temporizadores heredados de fase avanzan primero. Si una
  // habilidad queda lista y entra en resolución asíncrona, el tempo se pausa.
  processRealtimeTemporalSecond(second);
  if (isRealtimeTempoPaused()) {
    renderRealtimeStage1Status();
    return true;
  }

  // Los dos contadores de entrada/salida de arena avanzan por ciclos de Tempo.
  if (Number(second) % REALTIME_CAST_COUNTER_STEP_SECONDS === 0) tickCastQueues();
  if (Number(second) % REALTIME_RESTORE_COUNTER_STEP_SECONDS === 0) tickRestorationCounters();

  // Movimiento, adquisición de objetivo y ataques ya no pertenecen al tick de
  // Tempo. RT-08.11 los procesa con sus propios relojes activos.
  scheduleRealtimeAiInvocationCast(second);
  renderRealtimeStage1Status();
  return true;
}


// v9.46 · Buffer de acorde WASD robusto. El primer eje NO se consume de
// inmediato: se reserva una ventana breve para que una segunda tecla ortogonal
// forme un único paso diagonal. La última pulsación real se conserva incluso si
// la primera tecla ya fue soltada, y los key-repeat no pueden adelantarse al
// temporizador pendiente y disparar accidentalmente el movimiento cardinal.
const REALTIME_CASTER_CHORD_WINDOW_MS = 240;
const realtimeCasterKeyChordRuntime = {
  pressed: new Set(),
  pendingTimer: 0,
  pendingKey: '',
  pendingStartedAt: 0,
  lastDownAt: new Map(),
};

function getRealtimeCasterChordKey(now = performance.now(), options = {}) {
  const includeRecent = options.includeRecent !== false;
  const keys = realtimeCasterKeyChordRuntime.pressed;
  const lastDown = key => Number(realtimeCasterKeyChordRuntime.lastDownAt.get(key) || -Infinity);
  const recent = key => includeRecent && (now - lastDown(key)) <= REALTIME_CASTER_CHORD_WINDOW_MS;
  const chooseAxis = (a, b) => {
    const aPressed = keys.has(a);
    const bPressed = keys.has(b);
    if (aPressed && bPressed) return lastDown(a) >= lastDown(b) ? a : b;
    if (aPressed) return a;
    if (bPressed) return b;
    const aRecent = recent(a);
    const bRecent = recent(b);
    if (aRecent && bRecent) return lastDown(a) >= lastDown(b) ? a : b;
    return aRecent ? a : (bRecent ? b : '');
  };
  const vertical = chooseAxis('w', 's');
  const horizontal = chooseAxis('a', 'd');
  return vertical && horizontal ? `${vertical}${horizontal}` : (vertical || horizontal || '');
}

function clearRealtimeCasterPendingChord() {
  if (realtimeCasterKeyChordRuntime.pendingTimer) clearTimeout(realtimeCasterKeyChordRuntime.pendingTimer);
  realtimeCasterKeyChordRuntime.pendingTimer = 0;
  realtimeCasterKeyChordRuntime.pendingKey = '';
  realtimeCasterKeyChordRuntime.pendingStartedAt = 0;
}

function clearRealtimeCasterChordHistory() {
  realtimeCasterKeyChordRuntime.lastDownAt.clear();
}

function resetRealtimeCasterMovementKeys() {
  clearRealtimeCasterPendingChord();
  realtimeCasterKeyChordRuntime.pressed.clear();
  clearRealtimeCasterChordHistory();
}

function releaseRealtimeCasterMovementKey(rawKey) {
  const key = String(rawKey || '').toLowerCase();
  if (!['w', 'a', 's', 'd'].includes(key)) return false;
  realtimeCasterKeyChordRuntime.pressed.delete(key);
  // No borrar lastDownAt aquí: una pulsación muy rápida W→keyup→D todavía
  // debe poder reconocerse como W+D si ambas ocurrieron dentro de la ventana.
  return true;
}

function performRealtimeCasterMoveKey(key) {
  const playerId = Number(LOCAL_PLAYER_ID || 1);
  const now = performance.now();
  if ((now - Number(realtimeStage3Runtime.lastCasterMoveAt || 0)) < REALTIME_CASTER_KEY_REPEAT_GUARD_MS) return true;
  if (isOnlineMatchActive() && !isRealtimeOnlineAuthority()) {
    realtimeStage3Runtime.lastCasterMoveAt = now;
    void window.ROK_ONLINE_PVP?.sendRealtimeCommand?.('caster-move', { key });
    return true;
  }
  const moved = applyRealtimeCasterMoveForPlayer(playerId, key, { markDirty: true });
  if (moved) {
    realtimeStage3Runtime.lastCasterMoveAt = now;
    try { markBattleActivity(`realtime-caster-${key}`); } catch (_) {}
    renderAll('realtime-caster-wasd');
  }
  return true;
}

function shouldAllowRealtimeCasterKeyDuringBusyFlow(event) {
  if (!isRealtimePlayStyle() || !state?.realtime?.active || state.gameOver) return false;
  if (event?.type !== 'keydown') return false;
  const key = String(event.key || '').toLowerCase();
  if (!['w', 'a', 's', 'd'].includes(key)) return false;
  const active = document.activeElement;
  if (active && (active.matches?.('input, textarea, select') || active.isContentEditable)) return false;
  return true;
}

function tryRealtimeMoveLocalCasterByKey(rawKey, event = null) {
  if (!isRealtimePlayStyle() || !state?.realtime?.active || state.gameOver) return false;
  if (isRealtimeTempoPaused()) return true;
  const key = String(rawKey || '').toLowerCase();
  if (!['w', 'a', 's', 'd'].includes(key)) return false;
  const active = document.activeElement;
  if (active && (active.matches?.('input, textarea, select') || active.isContentEditable)) return false;

  const chordNow = performance.now();
  const isRepeat = event?.repeat === true;
  realtimeCasterKeyChordRuntime.pressed.add(key);

  // Solo una pulsación física nueva alimenta la ventana de acorde. Si un
  // key-repeat actualizara este timestamp, una tecla mantenida se comportaría
  // como si acabara de pulsarse una y otra vez y produciría diagonales fantasma.
  if (!isRepeat) realtimeCasterKeyChordRuntime.lastDownAt.set(key, chordNow);

  if (isRepeat) {
    // Mientras el primer eje está esperando una posible segunda tecla, ningún
    // repeat puede consumirlo antes de tiempo. Una vez resuelto el acorde, los
    // repeats vuelven a mover usando únicamente las teclas que siguen pulsadas.
    if (realtimeCasterKeyChordRuntime.pendingTimer || realtimeCasterKeyChordRuntime.pendingKey) return true;
    const heldChord = getRealtimeCasterChordKey(chordNow, { includeRecent: false });
    return performRealtimeCasterMoveKey(heldChord || key);
  }

  const chord = getRealtimeCasterChordKey(chordNow, { includeRecent: true });
  if (chord.length === 2) {
    clearRealtimeCasterPendingChord();
    clearRealtimeCasterChordHistory();
    return performRealtimeCasterMoveKey(chord);
  }

  // Primera tecla cardinal: queda diferida. Si antes de 240 ms aparece el eje
  // ortogonal, el bloque anterior cancela este timer y ejecuta una sola diagonal.
  clearRealtimeCasterPendingChord();
  realtimeCasterKeyChordRuntime.pendingKey = chord || key;
  realtimeCasterKeyChordRuntime.pendingStartedAt = chordNow;
  realtimeCasterKeyChordRuntime.pendingTimer = setTimeout(() => {
    const pending = realtimeCasterKeyChordRuntime.pendingKey;
    realtimeCasterKeyChordRuntime.pendingTimer = 0;
    realtimeCasterKeyChordRuntime.pendingKey = '';
    realtimeCasterKeyChordRuntime.pendingStartedAt = 0;
    clearRealtimeCasterChordHistory();
    if (pending) performRealtimeCasterMoveKey(pending);
  }, REALTIME_CASTER_CHORD_WINDOW_MS);
  return true;
}

function normalizeMatchPlayStyle(value) {
  return String(value || '').toLowerCase() === MATCH_PLAY_STYLES.realtime
    ? MATCH_PLAY_STYLES.realtime
    : MATCH_PLAY_STYLES.manual;
}

function isRealtimePlayStyle() {
  return normalizeMatchPlayStyle(state?.playStyle) === MATCH_PLAY_STYLES.realtime;
}

// RT-06 · En PvP Tiempo real el Host/J1 es la autoridad única de simulación.
// El invitado conserva UI/input local, pero sus órdenes viajan como comandos y
// nunca ejecuta movimiento, timers, daño ni IA por su cuenta.
function isRealtimeOnlineAuthority() {
  if (!isOnlineMatchActive()) return true;
  try { return Boolean(window.ROK_ONLINE_PVP?.isRealtimeAuthority?.()); }
  catch (_) { return Number(LOCAL_PLAYER_ID || 0) === 1; }
}

function canRunRealtimeSimulation() {
  return Boolean(isRealtimePlayStyle() && state?.realtime?.active && !state.gameOver && isRealtimeOnlineAuthority());
}

function isRealtimeOnlineReplica() {
  return Boolean(isOnlineMatchActive() && isRealtimePlayStyle() && state?.realtime?.active && !isRealtimeOnlineAuthority());
}

function normalizeRealtimeTempoSeconds(value) {
  const parsed = Math.round(Number(value || 0));
  return REALTIME_TEMPO_LEVELS.includes(parsed) ? parsed : REALTIME_DEFAULT_TEMPO_SECONDS;
}

function ensureRealtimeTempoState() {
  if (!state.realtime || typeof state.realtime !== 'object') {
    state.realtime = { active: false, startedAt: 0, elapsedSeconds: 0, tickSerial: 0, phaseEquivalentSeconds: REALTIME_DEFAULT_TEMPO_SECONDS };
  }
  const tempoSeconds = normalizeRealtimeTempoSeconds(
    state.realtime.tempoSeconds ?? state.realtime.tempoLevel ?? REALTIME_DEFAULT_TEMPO_SECONDS,
  );
  state.realtime.tempoSeconds = tempoSeconds;
  state.realtime.tempoLevel = tempoSeconds;
  state.realtime.phaseEquivalentSeconds = tempoSeconds;
  return tempoSeconds;
}

function getRealtimeTempoSeconds() {
  return ensureRealtimeTempoState();
}

function scheduleNextRealtimeTempoTick(fromNow = Date.now()) {
  const tempoSeconds = getRealtimeTempoSeconds();
  realtimeStage1Runtime.nextTempoTickAtMs = Math.max(0, Number(fromNow || Date.now())) + tempoSeconds * 1000;
  return realtimeStage1Runtime.nextTempoTickAtMs;
}

function setRealtimeTempoSeconds(value, options = {}) {
  if (!isRealtimePlayStyle() || !state?.realtime?.active) return false;
  const next = normalizeRealtimeTempoSeconds(value);
  if (Number(value) !== next) return false;
  const previous = getRealtimeTempoSeconds();
  state.realtime.tempoSeconds = next;
  state.realtime.tempoLevel = next;
  state.realtime.phaseEquivalentSeconds = next;
  if (state.realtime.temporalSystem) state.realtime.temporalSystem.phaseSeconds = next;
  if (state.realtime.movementSystem) state.realtime.movementSystem.tempoSeconds = next;
  scheduleNextRealtimeTempoTick();
  if (previous !== next) {
    log(`RT · Velocidad de Tempo cambiada a nivel ${next}: 1 ciclo cada ${next} segundo${next === 1 ? '' : 's'}.`);
    if (isOnlineMatchActive() && isRealtimeOnlineAuthority() && options.markDirty !== false) {
      try { markOnlineStateDirty(`rt-tempo-${next}s`); } catch (_) {}
    }
  }
  renderRealtimeStage1Status();
  return true;
}

function getRealtimeElapsedSeconds() {
  return Math.max(0, Math.floor(getRealtimeActiveElapsedMs() / 1000));
}

function formatRealtimeClock(totalSeconds = 0) {
  const safe = Math.max(0, Math.floor(Number(totalSeconds || 0)));
  const minutes = Math.floor(safe / 60);
  const seconds = safe % 60;
  return `${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}`;
}

function updateRealtimeResourceCountdownLabels() {
  if (!isRealtimePlayStyle() || !state?.realtime?.resourceSystem?.initialized || !els.resourceBar) return;
  els.resourceBar.querySelectorAll('.rt-resource-column[data-element-id]').forEach(line => {
    const elementId = line.dataset.elementId;
    const track = getRealtimeResourceTrack(LOCAL_PLAYER_ID, elementId);
    const footer = line.querySelector('.rt-resource-column-foot');
    if (!track || !footer) return;
    const available = countPlayerResourcesByElement(LOCAL_PLAYER_ID, elementId);
    const capacity = Math.max(0, Number(track.capacity || 0));
    const refillIn = getRealtimeResourceCountdown(LOCAL_PLAYER_ID, elementId, 'refill');
    const growthIn = getRealtimeResourceCountdown(LOCAL_PLAYER_ID, elementId, 'growth');
    const growthMaxed = capacity >= Number(track.maxCapacity || REALTIME_RESOURCE_MAX_CAPACITY);
    const spans = footer.querySelectorAll('span');
    if (spans[0]) spans[0].textContent = available < capacity ? `REC ${refillIn ?? 0}s` : 'REC ✓';
    if (spans[1]) spans[1].textContent = growthMaxed ? `MAX ${capacity}` : `+1 ${growthIn ?? 0}s`;
  });
}

function renderRealtimeStage1Status() {
  const active = isRealtimePlayStyle() && Boolean(state?.realtime?.active);
  if (active && realtimeStage5Runtime.autoAbilityDepth === 0) syncRealtimeManualAbilityPauseState();
  document.body.classList.toggle('rok-realtime-playstyle', active);
  if (els.realtimePhaseRail) els.realtimePhaseRail.setAttribute('aria-hidden', active ? 'false' : 'true');
  if (els.realtimeClock) els.realtimeClock.textContent = formatRealtimeClock(state?.realtime?.elapsedSeconds || 0);
  const tempoSeconds = active ? getRealtimeTempoSeconds() : REALTIME_DEFAULT_TEMPO_SECONDS;
  if (els.realtimeTickSerial) els.realtimeTickSerial.textContent = `Ciclo ${Math.max(0, Number(state?.realtime?.tickSerial || 0))} · cada ${tempoSeconds}s`;
  if (els.realtimeTempoControls) {
    const canEditTempo = active && (!isOnlineMatchActive() || isRealtimeOnlineAuthority());
    els.realtimeTempoControls.querySelectorAll('[data-realtime-tempo]').forEach(button => {
      const value = normalizeRealtimeTempoSeconds(button.dataset.realtimeTempo);
      button.classList.toggle('is-active', value === tempoSeconds);
      button.setAttribute('aria-pressed', value === tempoSeconds ? 'true' : 'false');
      button.disabled = !canEditTempo;
    });
    els.realtimeTempoControls.classList.toggle('is-readonly', active && !canEditTempo);
  }
  const pause = state?.realtime?.tempoPause || {};
  if (els.realtimeTempoStatus) {
    els.realtimeTempoStatus.textContent = pause.active ? `TEMPO PAUSADO · ${pause.reason || 'HABILIDAD'}` : 'TEMPO ACTIVO';
    els.realtimeTempoStatus.classList.toggle('is-paused', Boolean(pause.active));
  }
  if (els.realtimeAbilityStatus) {
    const count = Math.max(0, Number(state?.realtime?.abilitySystem?.activations || 0));
    els.realtimeAbilityStatus.textContent = realtimeStage5Runtime.abilityBusy
      ? `IA · ${realtimeStage5Runtime.currentAbilityLabel || 'resolviendo'}`
      : `IA HABILIDADES · ${count} activación${count === 1 ? '' : 'es'}`;
  }
  updateRealtimeResourceCountdownLabels();
  renderRealtimeCombatModePanel();
  renderRealtimeThoughtTimeUi();
}

function processRealtimeSecondTick(generation) {
  if (generation !== realtimeStage1Runtime.generation || !isRealtimePlayStyle() || !state?.realtime?.active || state?.gameOver) return false;

  // RT-08.5 · La reserva de pensamiento usa tiempo real y debe seguir bajando
  // precisamente mientras el Tempo está detenido.
  processRealtimeThoughtTimePoll();

  // RT-08.12 · Repara primero cualquier Promise/selección huérfana. Si se hace
  // después de syncRealtimeManualAbilityPauseState(), el propio watchdog puede
  // quedar detrás de la pausa que intenta corregir.
  processRealtimeStallRecovery();
  syncRealtimeManualAbilityPauseState();

  // v8.86 · una decisión táctica/quick-cast es una pausa DURA:
  // no movimiento, ataques, recursos, elemento puro, kasteos progresivos ni
  // nuevos ciclos mientras exista cualquier token global de gameplay.
  if (isGlobalGameplayPaused()) {
    renderRealtimeStage1Status();
    return true;
  }

  const elapsed = getRealtimeElapsedSeconds();
  const previousElapsed = Math.max(0, Number(state.realtime.elapsedSeconds || 0));
  state.realtime.elapsedSeconds = elapsed;

  if (isRealtimeTempoPaused()) {
    if (elapsed !== realtimeStage1Runtime.lastRenderedElapsedSecond) {
      realtimeStage1Runtime.lastRenderedElapsedSecond = elapsed;
      renderRealtimeStage1Status();
    }
    return true;
  }

  // RT-08.7 · Los recursos usan el reloj de segundos activos, no el ciclo de
  // Tempo. Por eso pueden recargarse a los 3 s aunque el combate esté en Tempo
  // 2 o Tempo 3.
  const resourceAdvanced = canRunRealtimeSimulation()
    ? processRealtimeResourceSecond(elapsed)
    : false;
  const actionAdvanced = canRunRealtimeSimulation()
    ? processRealtimeActionClock(getRealtimeActiveElapsedMs())
    : false;
  const pureAdvanced = canRunRealtimeSimulation()
    ? processRealtimePureElementClock(getRealtimeActiveElapsedMs() / 1000)
    : false;
  const progressiveAdvanced = canRunRealtimeSimulation()
    ? processRealtimeProgressiveCastingClock(getRealtimeActiveElapsedMs())
    : false;

  const now = Date.now();
  const tempoSeconds = getRealtimeTempoSeconds();
  if (!Number(realtimeStage1Runtime.nextTempoTickAtMs || 0)) scheduleNextRealtimeTempoTick(now);

  let advanced = false;
  if (now >= Number(realtimeStage1Runtime.nextTempoTickAtMs || 0)) {
    // Un único ciclo por vencimiento. No hacemos ráfagas de catch-up cuando el
    // navegador vuelve de segundo plano: eso volvería a producir el problema
    // de acciones imposibles de leer que RT-08.1 está corrigiendo.
    const tick = Math.max(0, Number(state.realtime.tickSerial || 0)) + 1;
    state.realtime.tickSerial = tick;
    processRealtimeStage3Second(tick);
    advanced = true;
    if (!isRealtimeTempoPaused()) scheduleNextRealtimeTempoTick(now);
  }

  if (isOnlineMatchActive() && isRealtimeOnlineAuthority() && (advanced || resourceAdvanced || actionAdvanced || pureAdvanced || progressiveAdvanced || elapsed !== previousElapsed)) {
    try {
      markOnlineStateDirty(
        resourceAdvanced
          ? `realtime-resource:${elapsed}s`
          : `realtime-tick:${state.realtime.tickSerial}:tempo-${tempoSeconds}s`,
      );
    } catch (_) {}
  }
  if (advanced || resourceAdvanced || actionAdvanced || pureAdvanced || progressiveAdvanced || elapsed !== realtimeStage1Runtime.lastRenderedElapsedSecond) {
    realtimeStage1Runtime.lastRenderedElapsedSecond = elapsed;
    renderRealtimeStage1Status();
  }
  return true;
}

function stopRealtimeStage1Runtime(reason = 'stop', options = {}) {
  realtimeStage1Runtime.generation += 1;
  if (realtimeStage1Runtime.timer) {
    clearInterval(realtimeStage1Runtime.timer);
    realtimeStage1Runtime.timer = null;
  }
  realtimeStage1Runtime.nextTempoTickAtMs = 0;
  realtimeStage1Runtime.lastRenderedElapsedSecond = -1;
  realtimeStage1Runtime.lastThoughtBroadcastSecond = -1;
  realtimeStage1Runtime.lastThoughtActivePlayerId = 0;
  realtimeStage1Runtime.thoughtCommandPending = false;
  if (state?.realtime) {
    if (state.realtime.active) state.realtime.elapsedSeconds = getRealtimeElapsedSeconds();
    state.realtime.active = false;
    if (options.resetClock === true) {
      state.realtime.startedAt = 0;
      state.realtime.elapsedSeconds = 0;
      state.realtime.tickSerial = 0;
    }
  }
  realtimeStage3Runtime.entityLocks.clear();
  realtimeStage3Runtime.pairLocks.clear();
  realtimeStage3Runtime.aiCastBusy = false;
  realtimeStage3Runtime.lastCasterMoveAt = 0;
  realtimeStage3Runtime.lastProcessedSecond = 0;
  realtimeStage3Runtime.combatPowerCache.clear();
  resetRealtimeStage5Runtime();
  if (state?.realtime?.combatModeSystem) {
    state.realtime.combatModeSystem.selectedUnitId = '';
    state.realtime.combatModeSystem.selectedSpawnId = '';
  }
  document.body.classList.remove('rok-realtime-playstyle');
  renderRealtimeStage1Status();
  return reason;
}

function startRealtimeStage1Runtime(options = {}) {
  stopRealtimeStage1Runtime('restart-realtime-runtime', { resetClock: false });
  state.playStyle = MATCH_PLAY_STYLES.realtime;
  if (!state.realtime || typeof state.realtime !== 'object') {
    state.realtime = { active: false, startedAt: 0, elapsedSeconds: 0, tickSerial: 0, phaseEquivalentSeconds: 1 };
  }
  state.realtime.active = true;
  clearManualTurnPresentationResidueForRealtime('start-realtime-runtime');
  state.realtime.startedAt = Date.now();
  state.realtime.elapsedSeconds = 0;
  state.realtime.tickSerial = 0;
  state.realtime.tempoSeconds = REALTIME_DEFAULT_TEMPO_SECONDS;
  state.realtime.tempoLevel = REALTIME_DEFAULT_TEMPO_SECONDS;
  state.realtime.phaseEquivalentSeconds = REALTIME_DEFAULT_TEMPO_SECONDS;
  state.realtime.globalPauseClock = { active: false, startedAt: 0, accumulatedMs: 0 };
  state.realtime.timingTuning = { ...loadRealtimeTimingTuning() };
  initializeRealtimeResourceSystem();
  initializeRealtimeMovementSystem();
  initializeRealtimeCombatModeSystem();
  resetRealtimeStage5Runtime();
  resetRealtimeThoughtTimeState();
  state.realtime.pureElementSystem = {
    initialized: true,
    nextPulseAt: getRealtimeTimingValue('pureElementPulseSeconds'),
    pulses: 0,
  };
  // Se conserva una fase interna neutra para compatibilidad con renderizadores,
  // pero no ejecuta enterPhase/nextPhase ni entrega turnos. RT-03 usa el reloj
  // para recursos, kasteo/restauración mínimos y desplazamiento/combate base.
  const castingIndex = PHASES.findIndex(phase => phase.id === 'casting');
  state.phaseIndex = castingIndex >= 0 ? castingIndex : 0;
  state.activePlayer = isOnlineMatchActive() ? 1 : (Number(options.localPlayerId || LOCAL_PLAYER_ID || 1) || 1);
  state.openingElementsDealt = true;
  state.actionExecutionLock = false;
  state.actionExecutionLockReason = '';
  state.aiThinking = false;
  state.enemyResolutionRunning = false;
  state.opponentActionResolving = false;
  resetBattleInactivityRuntime('realtime-stage1-start');
  const generation = ++realtimeStage1Runtime.generation;
  scheduleNextRealtimeTempoTick();
  realtimeStage1Runtime.timer = setInterval(() => processRealtimeSecondTick(generation), REALTIME_STAGE1_POLL_MS);
  renderAll();
  renderRealtimeStage1Status();
  log(`Modo Tiempo real experimental iniciado · RT-08.11 · Tempo nivel ${getRealtimeTempoSeconds()} (${getRealtimeTempoSeconds()}s por ciclo) · ${isOnlineMatchActive() ? (isRealtimeOnlineAuthority() ? 'autoridad PvP Host' : 'réplica PvP') : 'offline'} · IA, recursos, movimiento, WASD y Modos de combate activos.`);
  return true;
}

function resumeRealtimeOnlineRuntimeFromSnapshot() {
  if (!isOnlineMatchActive() || !isRealtimePlayStyle() || !state?.realtime?.active || state.gameOver) return false;
  // Réplicas no crean reloj propio: muestran exclusivamente el snapshot del Host.
  if (!isRealtimeOnlineAuthority()) {
    if (realtimeStage1Runtime.timer) {
      clearInterval(realtimeStage1Runtime.timer);
      realtimeStage1Runtime.timer = null;
      realtimeStage1Runtime.generation += 1;
    }
    renderRealtimeStage1Status();
    return true;
  }
  // Reconexion del Host: reanuda el ticker sin reinicializar recursos/unidades.
  if (realtimeStage1Runtime.timer) return true;
  // Nunca recuperar de golpe el tiempo que el navegador estuvo desconectado.
  // Se rebasa el origen al último elapsedSeconds confirmado del snapshot.
  const now = Date.now();
  const reportedElapsedMs = Math.max(0, Number(state.realtime.elapsedSeconds || 0) * 1000);
  const pause = state.realtime.tempoPause || {};
  const tempoPauseMs = Math.max(0, Number(pause.accumulatedMs || 0))
    + (pause.active ? Math.max(0, now - Number(pause.startedAt || now)) : 0);
  const globalPause = ensureRealtimeGlobalPauseClock() || {};
  if (globalPause.active) {
    globalPause.accumulatedMs = Math.max(0, Number(globalPause.accumulatedMs || 0))
      + Math.max(0, now - Number(globalPause.startedAt || now));
    globalPause.active = false;
    globalPause.startedAt = 0;
  }
  state.realtime.startedAt = now
    - reportedElapsedMs
    - tempoPauseMs
    - Math.max(0, Number(globalPause.accumulatedMs || 0));
  syncRealtimeGlobalPauseClock(now);
  const generation = ++realtimeStage1Runtime.generation;
  ensureRealtimeTempoState();
  realtimeStage1Runtime.lastProcessedSecond = Number(state.realtime.tickSerial || 0);
  realtimeStage3Runtime.lastProcessedSecond = Number(state.realtime.tickSerial || 0);
  realtimeStage5Runtime.lastProcessedSecond = Number(state.realtime.temporalSystem?.lastProcessedSecond || state.realtime.tickSerial || 0);
  scheduleNextRealtimeTempoTick();
  realtimeStage1Runtime.timer = setInterval(() => processRealtimeSecondTick(generation), REALTIME_STAGE1_POLL_MS);
  renderRealtimeStage1Status();
  return true;
}

function applyRealtimeCasterMoveForPlayer(playerId, rawKey, options = {}) {
  if (!isRealtimePlayStyle() || !state?.realtime?.active || state.gameOver) return false;
  const resolvedPlayerId = Number(playerId || 0);
  if (![1, 2].includes(resolvedPlayerId)) return false;
  const key = String(rawKey || '').toLowerCase();
  const delta = { w: [-1, 0], s: [1, 0], a: [0, -1], d: [0, 1], wa: [-1, -1], aw: [-1, -1], wd: [-1, 1], dw: [-1, 1], sa: [1, -1], as: [1, -1], sd: [1, 1], ds: [1, 1] }[key];
  if (!delta || isRealtimeTempoPaused()) return false;
  const caster = state.players?.[resolvedPlayerId]?.caster;
  if (!caster) return false;
  const nowMs = Date.now();
  const lastMoveAt = Math.max(0, Number(caster.realtimeLastKeyboardMoveAt || 0));
  if (lastMoveAt > 0 && (nowMs - lastMoveAt) < REALTIME_CASTER_MOVE_COOLDOWN_MS) return false;
  const row = Number(caster.row) + delta[0];
  const col = Number(caster.col) + delta[1];
  if (!isInside(row, col) || isMovementPlacementBlockedForPlayer(row, col, resolvedPlayerId)) return false;
  const hiddenAtDestination = getHiddenOpponentUnitAtForPlayer(row, col, resolvedPlayerId);
  if (hiddenAtDestination && !displaceHiddenOpponentIfNeeded(row, col, resolvedPlayerId)) return false;
  const previousRow = Number(caster.row);
  const previousCol = Number(caster.col);
  queueRealtimeSmoothMotion('caster', resolvedPlayerId, 'caster', previousRow, previousCol, row, col, REALTIME_CASTER_MOVE_COOLDOWN_MS);
  caster.row = row;
  caster.col = col;
  caster.movesLeft = 0;
  caster.realtimeLastKeyboardMoveAt = nowMs;
  // El destino visual se ilumina en cuanto el paso normal queda aceptado.
  // Poderes, saltos y teletransportes no pasan por esta función y por tanto
  // no reciben ni suavizado de locomoción ni esta iluminación.
  renderRealtimeCasterDestinationCue();
  const system = ensureRealtimeMovementSystemState();
  system.casterKeyboardMoves = Math.max(0, Number(system.casterKeyboardMoves || 0)) + 1;
  refreshGuardianAuraState({ announceNew: true });
  if (options.markDirty !== false && isOnlineMatchActive() && isRealtimeOnlineAuthority()) markOnlineStateDirty(`rt-caster-move:p${resolvedPlayerId}`);
  return true;
}

function applyRealtimeCombatModeForPlayer(playerId, unitId, modeId, options = {}) {
  if (!isRealtimePlayStyle() || !state?.realtime?.active) return false;
  const resolvedPlayerId = Number(playerId || 0);
  const unit = getUnitById?.(resolvedPlayerId, unitId);
  if (!unit) return false;
  const allowed = getRealtimeCombatModeAllowedIds(resolvedPlayerId, unit);
  const normalizedModeId = normalizeRealtimeCombatModeId(modeId);
  if (!allowed.includes(normalizedModeId) || !REALTIME_COMBAT_MODE_DB[normalizedModeId]) return false;
  unit.realtimeCombatMode = normalizedModeId;
  if (options.selectLocal && resolvedPlayerId === Number(LOCAL_PLAYER_ID)) {
    const system = ensureRealtimeCombatModeSystemState();
    system.selectedPlayerId = resolvedPlayerId;
    system.selectedUnitId = String(unit.id || '');
    system.selectedSpawnId = String(unit.spawnId || '');
    system.changes = Math.max(0, Number(system.changes || 0)) + 1;
  }
  if (options.markDirty !== false && isOnlineMatchActive() && isRealtimeOnlineAuthority()) markOnlineStateDirty(`rt-combat-mode:p${resolvedPlayerId}`);
  return true;
}

function queueRealtimeOnlineCastForPlayer(playerId, payload = {}) {
  if (!canRunRealtimeSimulation() || !isOnlineMatchActive() || isRealtimeThoughtPauseActive()) return false;
  const resolvedPlayerId = Number(playerId || 0);
  const player = state.players?.[resolvedPlayerId];
  const tab = Math.max(0, Number(payload.tab || 0));
  const slotIndex = Math.max(0, Number(payload.slotIndex || 0));
  const cardId = String(payload.cardId || '');
  const card = CARD_LIBRARY?.[cardId];
  if (!player || !card || player.handTabs?.[tab]?.[slotIndex] !== cardId) return false;
  const placement = payload.placement || {};
  const row = Number(placement.row);
  const col = Number(placement.col);
  if (!canUseCastReferenceCell(card, row, col, resolvedPlayerId)) return false;
  if (!isCasterInOwnSide(resolvedPlayerId)) return false;
  const limitStatus = canQueueInvocationForPlayer(resolvedPlayerId, card);
  if (!limitStatus.ok) return false;
  let randomSelection = payload.randomSelection && typeof payload.randomSelection === 'object' ? payload.randomSelection : null;
  if (getRandomCostNeeded(card) > 0 && !randomSelection) randomSelection = buildAutomaticRandomCostSelection(resolvedPlayerId, card);
  if (!payCardCostForPlayer(resolvedPlayerId, card, randomSelection)) return false;

  const elementId = getEffectiveCardElementId(card, resolvedPlayerId);
  const spawnId = `spawn_rt06_${Date.now()}_${Math.random().toString(16).slice(2)}`;
  const persistentCardState = card.type === 'invocation'
    ? takeSpellbookCardPersistentState(resolvedPlayerId, tab, slotIndex, card.id)
    : null;
  const pending = payload.pending && typeof payload.pending === 'object' ? payload.pending : {};
  const castItem = {
    cardId: card.id,
    persistentCardState,
    elementId,
    remaining: getEffectiveCastPhasesForCard(card, resolvedPlayerId),
    row, col,
    justAdded: true,
    introStarted: false,
    introDone: false,
    introEndsAt: 0,
    spawnId,
    originTab: tab,
    originSlot: slotIndex,
    targetUnitId: pending.targetUnitId || placement.targetUnitId || null,
    targetRow: pending.targetRow ?? row,
    targetCol: pending.targetCol ?? col,
    bandStartCol: pending.bandStartCol ?? placement.bandStartCol ?? null,
    umbralPortalA: pending.umbralPortalA || placement.umbralPortalA || null,
    umbralPortalB: pending.umbralPortalB || placement.umbralPortalB || null,
  };
  player.handTabs[tab][slotIndex] = null;
  clearSpellbookUseCooldown(resolvedPlayerId, tab, slotIndex);
  if (card.type === 'invocation') {
    player.spawnMarkers = player.spawnMarkers || [];
    player.spawnMarkers.push({ id: spawnId, cardId: card.id, elementId, row, col, owner: resolvedPlayerId, originTab: tab, originSlot: slotIndex, immediateCast: castItem.remaining <= 0 });
  }
  if (castItem.remaining <= 0) {
    launchCastTravel(resolvedPlayerId, castItem);
  } else {
    player.castQueue = player.castQueue || [];
    player.castQueue.push(castItem);
    if (player.caster) player.caster.state = 'casting';
  }
  markOnlineStateDirty(`rt-cast:p${resolvedPlayerId}:${card.id}`);
  return true;
}

async function applyRealtimeOnlineCommand(command = {}) {
  if (!canRunRealtimeSimulation() || !isOnlineMatchActive() || !isRealtimeOnlineAuthority()) return false;
  const playerId = Number(command.player || command.playerId || 0);
  if (![1, 2].includes(playerId)) return false;
  const type = String(command.type || '');
  const payload = command.payload || {};
  if (type === 'caster-move') return applyRealtimeCasterMoveForPlayer(playerId, payload.key, { markDirty: true });
  if (type === 'combat-mode') return applyRealtimeCombatModeForPlayer(playerId, payload.unitId, payload.modeId, { markDirty: true, selectLocal: false });
  if (type === 'power-automation') return setInvocationPowerAutomationMode(playerId, payload.unitId, payload.mode, { fromOnlineCommand: true });
  if (type === 'power-arm') return setInvocationRealtimePowerArmed(playerId, payload.unitId, payload.armed === true, { fromOnlineCommand: true });
  if (type === 'cast-card') return queueRealtimeOnlineCastForPlayer(playerId, payload);
  if (type === 'progressive-recast') {
    const progressiveCardId = String(payload.cardId || '');
    if (progressiveCardId === KOUUTEN_CARD_ID) {
      const center = getKouutenClampedCenter(Number(payload.row), Number(payload.col));
      return queueKouutenRecast(playerId, center, Number(payload.cost || getKouutenNextRecastCost(playerId)));
    }
    if (progressiveCardId === KIARA_REGRESA_CARD_ID) {
      return await beginRealtimeKiaraRegresaRecast(playerId, Number(payload.tab), Number(payload.slot), { fromOnlineCommand: true });
    }
    return false;
  }
  if (type === 'thought-pause') {
    const action = String(payload.action || '').toLowerCase();
    if (action === 'start') return startRealtimeThoughtPauseForPlayer(playerId, { commit: false });
    if (action === 'stop') return endRealtimeThoughtPauseForPlayer(playerId, 'remote', { commit: false });
    return false;
  }
  if (type === 'spell-action-pause') {
    const action = String(payload.action || '').toLowerCase();
    if (action === 'start') {
      const existingPause = state?.realtime?.spellActionPause || {};
      const existingOwner = existingPause.active ? Number(existingPause.playerId || 0) : 0;
      if (existingOwner && existingOwner !== playerId) return false;
      const tab = Number(payload.tab ?? -1);
      const slot = Number(payload.slot ?? -1);
      const cardId = String(payload.cardId || '');
      const player = state.players?.[playerId];
      if (!cardId || tab < 0 || slot < 0 || player?.handTabs?.[tab]?.[slot] !== cardId) return false;
      // v8.86 · no rechazar la carta porque otra resolución posea Tempo.
      // El hard-pause global se apila y toma Tempo cuando el owner anterior
      // termina.
      const ok = setRealtimeSpellActionPauseLocal(true, {
        playerId,
        cardId,
        tab,
        slot,
        // La UI/targeting pertenece al navegador remoto. El Host conserva
        // únicamente la pausa autoritativa y su lease; no inventa un pending local.
        mirrorRuntime: false,
      });
      if (ok) markOnlineStateDirty(`rt-spell-action-start:p${playerId}`);
      return ok;
    }
    if (action === 'stop') {
      const owner = Number(state?.realtime?.spellActionPause?.playerId || 0);
      if (owner && owner !== playerId) return false;
      const ok = setRealtimeSpellActionPauseLocal(false, { reason: 'remote-finished', mirrorRuntime: false });
      if (ok) markOnlineStateDirty(`rt-spell-action-stop:p${playerId}`);
      return ok;
    }
    return false;
  }
  return false;
}

function getRealtimeCardCompatibilityAudit() {
  return Object.entries(CARD_LIBRARY || {})
    .filter(([, card]) => card?.type === 'invocation')
    .map(([cardId, card]) => {
      const qualities = [...new Set((Array.isArray(card.qualities) ? card.qualities : []).filter(Boolean).map(String))];
      const movementType = String(card.movementType || 'basic');
      const abilityIds = (Array.isArray(card.abilities) ? card.abilities : [])
        .map(entry => typeof entry === 'string' ? entry : entry?.id)
        .filter(Boolean)
        .map(String);
      const derived = new Set();
      qualities.forEach(qualityId => (REALTIME_COMBAT_MODE_QUALITY_RULES[qualityId] || []).forEach(modeId => derived.add(modeId)));
      (REALTIME_COMBAT_MODE_MOVEMENT_RULES[movementType] || []).forEach(modeId => derived.add(modeId));
      if (abilityIds.includes('vigilia') || abilityIds.includes('stalk')) derived.add('defensive');
      if (!derived.size) derived.add('offensive');
      const cardRule = REALTIME_COMBAT_MODE_CARD_RULES[cardId] || null;
      let allowedModes = REALTIME_COMBAT_MODE_ORDER.filter(modeId => derived.has(modeId));
      if (cardRule?.noCombatModes === true) {
        allowedModes = [];
      } else if (Array.isArray(cardRule?.allowed)) {
        allowedModes = REALTIME_COMBAT_MODE_ORDER.filter(modeId => cardRule.allowed.includes(modeId));
      }
      const defaultMode = cardRule?.default && allowedModes.includes(cardRule.default)
        ? cardRule.default
        : (allowedModes.includes('defensive') && (abilityIds.includes('vigilia') || movementType === 'retreat')
          ? 'defensive'
          : allowedModes[0] || '');
      return {
        cardId,
        name: card.name || cardId,
        qualities,
        movementType,
        abilities: abilityIds,
        allowedModes,
        defaultMode,
        curated: Boolean(cardRule),
        note: cardRule?.note || '',
        compatibilityNotes: [...(REALTIME_CARD_COMPATIBILITY_NOTES[cardId] || [])],
      };
    });
}

window.ROK_REALTIME = {
  isActive: () => isRealtimePlayStyle() && Boolean(state?.realtime?.active),
  getState: () => ({
    playStyle: normalizeMatchPlayStyle(state?.playStyle),
    active: Boolean(state?.realtime?.active),
    startedAt: Number(state?.realtime?.startedAt || 0),
    elapsedSeconds: Number(state?.realtime?.elapsedSeconds || 0),
    tickSerial: Number(state?.realtime?.tickSerial || 0),
    phaseEquivalentSeconds: Number(state?.realtime?.phaseEquivalentSeconds || REALTIME_DEFAULT_TEMPO_SECONDS),
    tempoSeconds: normalizeRealtimeTempoSeconds(state?.realtime?.tempoSeconds || REALTIME_DEFAULT_TEMPO_SECONDS),
    resourceSystem: cloneMatchData(state?.realtime?.resourceSystem || null),
    movementSystem: cloneMatchData(state?.realtime?.movementSystem || null),
    combatModeSystem: cloneMatchData(state?.realtime?.combatModeSystem || null),
    temporalSystem: cloneMatchData(state?.realtime?.temporalSystem || null),
    abilitySystem: cloneMatchData(state?.realtime?.abilitySystem || null),
    tempoPause: cloneMatchData(state?.realtime?.tempoPause || null),
    thoughtTime: cloneMatchData(state?.realtime?.thoughtTime || null),
  }),
  getMovementState: () => cloneMatchData(state?.realtime?.movementSystem || null),
  getTempoSeconds: () => getRealtimeTempoSeconds(),
  setTempoSeconds: seconds => setRealtimeTempoSeconds(seconds),
  getBalanceProfile: () => ({
    id: REALTIME_BALANCE_PROFILE_ID,
    tempoSeconds: getRealtimeTempoSeconds(),
    tempoLevels: [...REALTIME_TEMPO_LEVELS],
    movementStepSeconds: REALTIME_INVOCATION_STEP_SECONDS * getRealtimeTempoSeconds(),
    attackIntervalSeconds: REALTIME_ATTACK_INTERVAL_SECONDS * getRealtimeTempoSeconds(),
    attackIntervalTicks: REALTIME_ATTACK_INTERVAL_SECONDS,
    resourceTotalCapacity: REALTIME_RESOURCE_TOTAL_CAPACITY,
    resourceDistributionMode: 'automatic-round-robin',
    resourceInitialCapacity: REALTIME_RESOURCE_INITIAL_CAPACITY,
    resourceTimingMode: 'active-seconds-progressive',
    resourceIndependentOfTempo: true,
    resourceRefillSeconds: REALTIME_RESOURCE_REFILL_SECONDS,
    resourceGrowthStartSeconds: REALTIME_RESOURCE_GROWTH_START_SECONDS,
    resourceGrowthEndSeconds: REALTIME_RESOURCE_GROWTH_END_SECONDS,
    resourceGrowthCurveExponent: REALTIME_RESOURCE_GROWTH_CURVE_EXPONENT,
    resourceMaxCapacity: getRealtimeResourceMaxCapacityForDomainCount(getRealtimePlayerDomainIds(LOCAL_PLAYER_ID).length || 1),
    phaseEquivalentSeconds: getRealtimeTempoSeconds(),
    legacyTurnSeconds: REALTIME_LEGACY_TURN_SECONDS * getRealtimeTempoSeconds(),
  }),
  getCompatibilityAudit: () => getRealtimeCardCompatibilityAudit(),
  getCombatModes: (playerId = LOCAL_PLAYER_ID) => (state.players?.[playerId]?.units || []).map(unit => {
    const profile = getRealtimeCombatModeProfileForUnit(playerId, unit);
    return {
      unitId: unit.id,
      cardId: unit.cardId,
      name: CARD_LIBRARY?.[unit.cardId]?.name || unit.cardId,
      activeMode: profile?.activeId || '',
      allowedModes: [...(profile?.allowedIds || [])],
      movementType: getEffectiveMovementTypeForUnit(playerId, unit),
      qualities: getRealtimeCombatModeQualityIds(unit),
    };
  }),
  selectCombatModeUnit: unitId => selectRealtimeCombatModeUnit(LOCAL_PLAYER_ID, unitId, 'debug'),
  setCombatMode: (unitId, modeId) => setRealtimeCombatModeForUnit(LOCAL_PLAYER_ID, unitId, modeId),
  pauseTempo: (reason = 'Debug') => setRealtimeTempoPause(true, reason, 'debug'),
  resumeTempo: () => setRealtimeTempoPause(false, '', 'debug'),
  toggleThoughtTime: () => toggleRealtimeThoughtPauseForLocalPlayer(),
  getThoughtTime: (playerId = LOCAL_PLAYER_ID) => ({
    activePlayerId: getRealtimeThoughtPausePlayerId(),
    remainingMs: getRealtimeThoughtTimeRemainingMs(playerId, { live: true }),
    maxMs: REALTIME_THOUGHT_TIME_MAX_MS,
  }),
  isOnlineAuthority: () => isRealtimeOnlineAuthority(),
  resumeOnlineRuntime: () => resumeRealtimeOnlineRuntimeFromSnapshot(),
  applyOnlineCommand: command => applyRealtimeOnlineCommand(command),
  getResources: (playerId = LOCAL_PLAYER_ID) => {
    const rtPlayer = getRealtimeResourcePlayerState(playerId, false);
    if (!rtPlayer) return null;
    return {
      primaryElementId: rtPlayer.primaryElementId,
      elementIds: [...(rtPlayer.elementIds || [])],
      tracks: Object.fromEntries((rtPlayer.elementIds || []).map(elementId => {
        const track = rtPlayer.tracks?.[elementId] || {};
        return [elementId, {
          capacity: Number(track.capacity || 0),
          maxCapacity: Number(track.maxCapacity || 0),
          available: countPlayerResourcesByElement(playerId, elementId),
          nextRefillIn: getRealtimeResourceCountdown(playerId, elementId, 'refill'),
          nextGrowthIn: getRealtimeResourceCountdown(playerId, elementId, 'growth'),
        }];
      })),
    };
  },
  start: () => startRealtimeStage1Runtime({ localPlayerId: LOCAL_PLAYER_ID }),
  stop: () => stopRealtimeStage1Runtime('debug-stop'),
};

