      els.cardMetaInfoBody.innerHTML = `<p><strong>Resumen:</strong> ${quality.summary}</p>${buildSemanticTagChainHtml(['Cualidad', quality.label, ...qualityFocusTags])}<p>${quality.description}</p>${grantsHtml}${abilityGrantsHtml}`;
