function getKouutenProgressiveStore() {
  if (!state.kouutenProgressiveByPlayer || typeof state.kouutenProgressiveByPlayer !== 'object') {
    state.kouutenProgressiveByPlayer = {};
  }
  return state.kouutenProgressiveByPlayer;
}

function getKouutenProgressiveState(playerId, create = false) {
  const store = getKouutenProgressiveStore();
  const key = String(Number(playerId));
  if (!store[key] && create) {
    store[key] = {
      active: false,
      cardId: KOUUTEN_CARD_ID,
      castCount: 0,
      armed: false,
      awaitingResolution: false,
      lastPromptPhaseKey: '',
      lastArmedPhaseKey: '',
      originTab: null,
      originSlot: null,
      cooldownUntilMs: 0,
      windowUntilMs: 0,
    };
  }
  return store[key] || null;
}

function activateKouutenProgressiveState(playerId) {
  const runtime = getKouutenProgressiveState(playerId, true);
  runtime.active = true;
  runtime.cardId = KOUUTEN_CARD_ID;
  runtime.castCount = Math.max(1, Number(runtime.castCount || 0));
  runtime.armed = false;
  runtime.awaitingResolution = false;
  runtime.lastPromptPhaseKey = getQuickReactionPhaseKey(playerId);
  if (isRealtimePlayStyle()) {
    const nowMs = getRealtimeActiveElapsedMs();
    runtime.cooldownUntilMs = nowMs + getRealtimeTimingValue('progressiveCooldownSeconds') * 1000;
    runtime.windowUntilMs = 0;
  }
  return runtime;
}

function deactivateKouutenProgressiveState(playerId, reason = 'cadena finalizada') {
  const runtime = getKouutenProgressiveState(playerId, false);
  if (!runtime) return false;
  const wasActive = Boolean(runtime.active || runtime.armed || runtime.awaitingResolution);
  runtime.active = false;
  runtime.armed = false;
  runtime.awaitingResolution = false;
  runtime.lastPromptPhaseKey = '';
  runtime.lastArmedPhaseKey = '';
  runtime.cooldownUntilMs = 0;
  runtime.windowUntilMs = 0;

  if (isRealtimePlayStyle()) {
    const player = state.players?.[playerId];
    const tab = Number(runtime.originTab);
    const slot = Number(runtime.originSlot);
    if (player && Number.isInteger(tab) && Number.isInteger(slot)
        && player.handTabs?.[tab]?.[slot] === KOUUTEN_CARD_ID) {
      player.handTabs[tab][slot] = null;
    }
  }

  if (reason && wasActive) log(`Kouuten: ${reason}. El Kasteo progresivo termina.`);
  return wasActive;
}

function getKouutenNextRecastCost(playerId) {
  const runtime = getKouutenProgressiveState(playerId, false);
  return Math.max(2, Number(runtime?.castCount || 1) + 1);
}

function countPlayerFireResources(playerId) {
  return (state.players?.[playerId]?.resources || []).filter(resource => resource?.id === 'fuego').length;
}

function canPayKouutenRecastCost(playerId, amount = getKouutenNextRecastCost(playerId)) {
  return countPlayerFireResources(playerId) >= Math.max(1, Number(amount) || 0);
}

function payKouutenRecastCost(playerId, amount) {
  const player = state.players?.[playerId];
  const required = Math.max(1, Number(amount) || 0);
  if (!player || !canPayKouutenRecastCost(playerId, required)) return false;
  let remaining = required;
  for (let index = player.resources.length - 1; index >= 0 && remaining > 0; index -= 1) {
    if (player.resources[index]?.id !== 'fuego') continue;
    player.resources.splice(index, 1);
    remaining -= 1;
  }
  return remaining === 0;
}

function getKouutenClampedCenter(row = 8, col = 4) {
  return {
    row: Math.max(2, Math.min(15, Math.floor(Number(row) || 0))),
    col: Math.max(2, Math.min(6, Math.floor(Number(col) || 0))),
  };
}

function getKouutenCenterCells(row = 8, col = 4) {
  const center = getKouutenClampedCenter(row, col);
  const cells = [];
  for (let r = center.row - 1; r <= center.row + 1; r += 1) {
    for (let c = center.col - 1; c <= center.col + 1; c += 1) cells.push({ row: r, col: c });
  }
  return cells;
}

function getKouutenSideGroups(row = 8, col = 4) {
  const center = getKouutenClampedCenter(row, col);
  return {
    top: Array.from({ length: 3 }, (_, i) => ({ row: center.row - 2, col: center.col - 1 + i })),
    bottom: Array.from({ length: 3 }, (_, i) => ({ row: center.row + 2, col: center.col - 1 + i })),
    left: Array.from({ length: 3 }, (_, i) => ({ row: center.row - 1 + i, col: center.col - 2 })),
    right: Array.from({ length: 3 }, (_, i) => ({ row: center.row - 1 + i, col: center.col + 2 })),
  };
}

function clearKouutenPreview() {
  document.querySelectorAll('.cell.kouuten-center-preview, .cell.kouuten-side-preview').forEach(cell => cell.classList.remove('kouuten-center-preview', 'kouuten-side-preview'));
}

function previewKouutenAreaAt(row, col) {
  clearKouutenPreview();
  const centerCells = getKouutenCenterCells(row, col);
  const groups = getKouutenSideGroups(row, col);
  const centerKey = new Set(centerCells.map(cell => `${cell.row}:${cell.col}`));
  const sideKey = new Set(Object.values(groups).flat().map(cell => `${cell.row}:${cell.col}`));
  document.querySelectorAll('.cell[data-row][data-col]').forEach(cell => {
    const key = `${Number(cell.dataset.row)}:${Number(cell.dataset.col)}`;
    if (centerKey.has(key)) cell.classList.add('kouuten-center-preview');
    else if (sideKey.has(key)) cell.classList.add('kouuten-side-preview');
  });
}

function closeKouutenRecastModal() {
  const overlay = document.getElementById('kouutenRecastOverlay');
  if (!overlay) return;
  overlay.classList.remove('visible');
  overlay.setAttribute('aria-hidden', 'true');
}

function finishKouutenRecastReaction(outcome = 'cancelled') {
  const runtime = getKouutenProgressiveState(LOCAL_PLAYER_ID, false);
  if (runtime) {
    runtime.armed = false;
    if (outcome !== 'activated') deactivateKouutenProgressiveState(LOCAL_PLAYER_ID, 'rekasteo cancelado');
  }
  closeKouutenRecastModal();
  clearKouutenPreview();
  hideQuickReactionWindowForPlayer(LOCAL_PLAYER_ID);
  state.quickReactionWindow.locked = false;
  state.quickReactionWindow.active = false;
  state.quickReactionWindow.executing = false;
  finishQuickReactionPhaseIntro(outcome);
  syncLocalQuickReactionGameplayPause();
  if (isRealtimePlayStyle()) {
    try { void requestRealtimeSpellActionPause(false, { reason: `kouuten-recast-${outcome}` }); } catch (_) {}
  }
  renderAll();
}

function cancelKouutenRecastDecision() {
  if (getKouutenProgressiveState(LOCAL_PLAYER_ID, false)?.armed || state.pendingPowerAction?.kind === 'kouutenRecastLocation') {
    state.pendingPowerAction = state.pendingPowerAction?.kind === 'kouutenRecastLocation' ? null : state.pendingPowerAction;
    finishKouutenRecastReaction('cancelled');
    return;
  }
  closeKouutenRecastModal();
}

function ensureKouutenRecastModal() {
  let overlay = document.getElementById('kouutenRecastOverlay');
  if (overlay) return overlay;
  overlay = document.createElement('div');
  overlay.id = 'kouutenRecastOverlay';
  overlay.className = 'kouuten-recast-overlay';
  overlay.setAttribute('aria-hidden', 'true');
  overlay.innerHTML = `
    <div class="kouuten-recast-modal" role="dialog" aria-modal="true" aria-labelledby="kouutenRecastTitle">
      <div class="kouuten-recast-card"></div>
      <div class="kouuten-recast-copy">
        <h3 id="kouutenRecastTitle">Kouuten · Rekasteo</h3>
        <p id="kouutenRecastText"></p>
        <div class="kouuten-recast-cost" id="kouutenRecastCost"></div>
      </div>
      <div class="kouuten-recast-actions">
        <button type="button" class="kouuten-recast-confirm">Rekastear</button>
        <button type="button" class="kouuten-recast-cancel">Cancelar</button>
      </div>
    </div>`;
  appendRokUiNode(overlay);
  overlay.addEventListener('pointerdown', event => {
    if (event.target === overlay) cancelKouutenRecastDecision();
  });
  overlay.querySelector('.kouuten-recast-cancel')?.addEventListener('click', cancelKouutenRecastDecision);
  overlay.querySelector('.kouuten-recast-confirm')?.addEventListener('click', () => {
    const playerId = Number(overlay.dataset.playerId || LOCAL_PLAYER_ID);
    const runtime = getKouutenProgressiveState(playerId, false);
    if (!runtime?.active || !runtime.armed) {
      closeKouutenRecastModal();
      return;
    }
    const cost = getKouutenNextRecastCost(playerId);
    if (!canPayKouutenRecastCost(playerId, cost)) {
      log(`No tienes ${cost} elementos de Fuego para rekastear Kouuten. Pulsa Cancelar para terminar la cadena.`);
      return;
    }
    closeKouutenRecastModal();
    beginKouutenRecastLocationTargeting(playerId, cost);
  });
  return overlay;
}

function openKouutenRecastModal(playerId = LOCAL_PLAYER_ID) {
  const runtime = getKouutenProgressiveState(playerId, false);
  if (!runtime?.active || !runtime.armed) return false;
  const cost = getKouutenNextRecastCost(playerId);
  const overlay = ensureKouutenRecastModal();
  overlay.dataset.playerId = String(playerId);
  const cardHost = overlay.querySelector('.kouuten-recast-card');
  if (cardHost) {
    cardHost.innerHTML = '';
    cardHost.appendChild(createSpellCompositeMini(CARD_LIBRARY[KOUUTEN_CARD_ID], 'kouuten-recast-card-mini'));
  }
  const text = overlay.querySelector('#kouutenRecastText');
  if (text) text.textContent = `¿Quieres rekastear Kouuten pagando ${cost} elementos de Fuego?`;
  const costHost = overlay.querySelector('#kouutenRecastCost');
  if (costHost) costHost.innerHTML = `<img src="${getElementCostIcon('fuego')}" alt="Fuego"><strong>${cost}</strong><span>Fuego</span>`;
  const confirmButton = overlay.querySelector('.kouuten-recast-confirm');
  const canPay = canPayKouutenRecastCost(playerId, cost);
  if (confirmButton) {
    confirmButton.disabled = !canPay;
    confirmButton.title = canPay ? `Rekastear pagando ${cost} Fuego` : `No tienes ${cost} elementos de Fuego`;
  }
  if (text && !canPay) text.textContent += ' No tienes suficiente Fuego; pulsa Cancelar para terminar la cadena.';
  overlay.classList.add('visible');
  overlay.setAttribute('aria-hidden', 'false');
  (canPay ? confirmButton : overlay.querySelector('.kouuten-recast-cancel'))?.focus();
  return true;
}


function getRealtimeKouutenProgressiveSlotState(playerId, tab, slot) {
  if (!isRealtimePlayStyle()) return null;
  const runtime = getKouutenProgressiveState(playerId, false);
  if (!runtime) return null;
  if (Number(runtime.originTab) !== Number(tab) || Number(runtime.originSlot) !== Number(slot)) return null;
  const nowMs = getRealtimeActiveElapsedMs();
  if (runtime.awaitingResolution) return { kind: 'casting', runtime, remainingMs: getRealtimeProgressiveCastQueueRemainingMs(playerId, KOUUTEN_CARD_ID, tab, slot), ready: false };
  if (!runtime.active) return null;
  if (Number(runtime.cooldownUntilMs || 0) > nowMs) {
    return { kind: 'cooldown', runtime, remainingMs: Number(runtime.cooldownUntilMs) - nowMs, ready: false };
  }
  if (runtime.armed && Number(runtime.windowUntilMs || 0) > nowMs) {
    const cost = getKouutenNextRecastCost(playerId);
    return {
      kind: 'ready',
      runtime,
      remainingMs: Number(runtime.windowUntilMs) - nowMs,
      ready: canPayKouutenRecastCost(playerId, cost),
      cost,
    };
  }
  return { kind: 'waiting', runtime, remainingMs: 0, ready: false };
}

function beginRealtimeKouutenRecastFromSpellbook(playerId, tab, slot) {
  const status = getRealtimeKouutenProgressiveSlotState(playerId, tab, slot);
  if (!status || status.kind !== 'ready') return false;
  if (!status.ready) {
    log(`Kouuten necesita ${status.cost} Fuego para continuar el Kasteo progresivo.`);
    return false;
  }
  return beginKouutenRecastLocationTargeting(playerId, status.cost);
}


function getRealtimeProgressiveRecastDecision() {
  const current = state.realtimeProgressiveRecastDecisionCurrent;
  return current && !current.resolved ? current : null;
}

function clearRealtimeProgressiveRecastDecisionTimer(current = getRealtimeProgressiveRecastDecision()) {
  if (!current?.decisionTimer) return;
  clearTimeout(current.decisionTimer);
  current.decisionTimer = 0;
}

async function declineRealtimeProgressiveRecastDecision(reason = 'pass') {
  const current = getRealtimeProgressiveRecastDecision();
  if (!current) return false;
  clearRealtimeProgressiveRecastDecisionTimer(current);
  current.resolved = true;
  current.result = reason === 'timeout' ? 'timeout' : 'passed';
  state.realtimeProgressiveRecastDecisionCurrent = null;

  if (current.cardId === KOUUTEN_CARD_ID) {
    deactivateKouutenProgressiveState(current.playerId, reason === 'timeout' ? 'ventana de rekasteo vencida' : 'oportunidad de rekasteo omitida');
  } else if (current.cardId === KIARA_REGRESA_CARD_ID) {
    expireKiaraRegresaProgressiveWindow(current.playerId, reason === 'timeout' ? 'ventana de rekasteo vencida' : 'oportunidad de rekasteo omitida');
  }

  try { await requestRealtimeSpellActionPause(false, { reason: `progressive-recast-${reason}` }); } catch (_) {
    releaseRealtimeSpellActionHardPause(`progressive-recast-${reason}`);
  }
  realtimeQuickCastRailRuntime.lastSignature = '';
  syncRealtimeQuickCastRail(true);
  renderAll(`progressive-recast-${reason}`);
  return true;
}

async function openRealtimeProgressiveRecastDecision(playerId, cardId, tab, slot) {
  if (!isRealtimePlayStyle() || !state?.realtime?.active || state.gameOver) return false;
  if (Number(playerId) !== Number(LOCAL_PLAYER_ID)) return false;
  if (state.kiaraNoReactionCurrent && !state.kiaraNoReactionCurrent.resolved) return false;
  const existing = getRealtimeProgressiveRecastDecision();
  if (existing) {
    return String(existing.cardId) === String(cardId)
      && Number(existing.tab) === Number(tab)
      && Number(existing.slot) === Number(slot);
  }

  let cost = 0;
  if (cardId === KOUUTEN_CARD_ID) cost = getKouutenNextRecastCost(playerId);
  else if (cardId === KIARA_REGRESA_CARD_ID) cost = getKiaraRegresaNextProgressiveCost(playerId);
  else return false;

  const durationMs = Math.max(1000, Number(getRealtimeTimingValue?.('progressiveWindowSeconds') || 5) * 1000);
  const current = {
    token: `${cardId}:${tab}:${slot}:${Date.now()}`,
    playerId: Number(playerId),
    cardId: String(cardId),
    tab: Number(tab),
    slot: Number(slot),
    cost: Number(cost || 0),
    decisionWindowMs: durationMs,
    decisionStartedAt: Date.now(),
    decisionExpiresAt: Date.now() + durationMs,
    decisionTimer: 0,
    resolved: false,
    result: '',
  };
  state.realtimeProgressiveRecastDecisionCurrent = current;

  // Congelación inmediata: la decisión se comporta igual que una reacción rápida.
  acquireRealtimeSpellActionHardPause({ playerId, cardId, tab, slot });
  try {
    const started = await requestRealtimeSpellActionPause(true, { playerId, cardId, tab, slot });
    if (started === false) {
      state.realtimeProgressiveRecastDecisionCurrent = null;
      releaseRealtimeSpellActionHardPause('progressive-recast-pause-rejected');
      return false;
    }
  } catch (_) {}

  const live = getRealtimeProgressiveRecastDecision();
  if (!live || live.token !== current.token) return false;
  live.decisionTimer = setTimeout(() => {
    const pending = getRealtimeProgressiveRecastDecision();
    if (!pending || pending.token !== current.token) return;
    void declineRealtimeProgressiveRecastDecision('timeout');
  }, durationMs);

  realtimeQuickCastRailRuntime.lastSignature = '';
  syncRealtimeQuickCastRail(true);
  try { syncLocalQuickReactionGameplayPause(); } catch (_) {}
  return true;
}

async function acceptRealtimeProgressiveRecastDecision(candidate = null) {
  const current = getRealtimeProgressiveRecastDecision();
  if (!current) return false;
  if (candidate?.cardId && String(candidate.cardId) !== String(current.cardId)) return false;

  if (current.cardId === KOUUTEN_CARD_ID) {
    const status = getRealtimeKouutenProgressiveSlotState(current.playerId, current.tab, current.slot);
    if (!status?.ready) {
      log(`Kouuten necesita ${status?.cost || current.cost} Fuego para continuar el Kasteo progresivo.`);
      return false;
    }
    clearRealtimeProgressiveRecastDecisionTimer(current);
    current.resolved = true;
    state.realtimeProgressiveRecastDecisionCurrent = null;
    const started = beginKouutenRecastLocationTargeting(current.playerId, status.cost);
    if (!started) {
      await requestRealtimeSpellActionPause(false, { reason: 'kouuten-recast-start-failed' });
      return false;
    }
    realtimeQuickCastRailRuntime.lastSignature = '';
    syncRealtimeQuickCastRail(true);
    return true;
  }

  if (current.cardId === KIARA_REGRESA_CARD_ID) {
    const status = getRealtimeKiaraRegresaProgressiveSlotState(current.playerId, current.tab, current.slot);
    if (!status?.ready) {
      log(`Regresa necesita ${status?.cost || current.cost} Agua para continuar el Kasteo progresivo.`);
      return false;
    }
    clearRealtimeProgressiveRecastDecisionTimer(current);
    current.resolved = true;
    state.realtimeProgressiveRecastDecisionCurrent = null;
    const started = await beginRealtimeKiaraRegresaRecast(current.playerId, current.tab, current.slot);
    try { await requestRealtimeSpellActionPause(false, { reason: started ? 'regresa-recast-accepted' : 'regresa-recast-failed' }); } catch (_) {}
    realtimeQuickCastRailRuntime.lastSignature = '';
    syncRealtimeQuickCastRail(true);
    return Boolean(started);
  }
  return false;
}

function createRealtimeProgressiveRecastDecisionCandidate() {
  const current = getRealtimeProgressiveRecastDecision();
  if (!current) return null;
  const card = CARD_LIBRARY?.[current.cardId];
  if (!card) return null;
  const isKouuten = current.cardId === KOUUTEN_CARD_ID;
  return {
    type: 'progressiveRecastDecision',
    selectionType: 'spell',
    playerId: current.playerId,
    cardId: current.cardId,
    spellbookTab: current.tab,
    spellbookSlot: current.slot,
    label: card.shortName || card.name || 'Recasteo',
    progressiveRecastDecision: true,
    actions: [{
      id: isKouuten ? 'kouutenRecastPrompt' : 'kiaraRegresaRecastPrompt',
      label: 'Recastear',
      title: `Recastear ${card.shortName || card.name || 'carta'}`,
      directExecute: true,
      execute: () => acceptRealtimeProgressiveRecastDecision(),
    }],
    actionLabels: ['Recastear'],
    targets: [],
  };
}

function processRealtimeProgressiveCastingClock(activeMs = null) {
  if (!isRealtimePlayStyle() || !state?.realtime?.active) return false;
  const nowMs = Math.max(0, Number(activeMs ?? getRealtimeActiveElapsedMs()));
  let changed = false;

  for (const playerId of [1, 2]) {
    const noRuntime = getKiaraNoProgressiveRuntime(playerId, false);
    if (noRuntime && Number(noRuntime.expiresAtActiveMs || 0) > 0 && nowMs >= Number(noRuntime.expiresAtActiveMs)) {
      if (expireKiaraNoProgressiveWindow(playerId, '5 segundos sin continuar la cadena')) changed = true;
    }

    const regresaRuntime = getKiaraRegresaProgressiveRuntime(playerId, false);
    if (regresaRuntime?.active && !regresaRuntime.awaitingResolution) {
      if (!regresaRuntime.armed && Number(regresaRuntime.cooldownUntilActiveMs || 0) > 0
          && nowMs >= Number(regresaRuntime.cooldownUntilActiveMs)) {
        regresaRuntime.cooldownUntilActiveMs = 0;
        regresaRuntime.armed = true;
        changed = true;
        if (Number(playerId) === Number(LOCAL_PLAYER_ID)) {
          void openRealtimeProgressiveRecastDecision(playerId, KIARA_REGRESA_CARD_ID, regresaRuntime.originTab, regresaRuntime.originSlot);
        } else {
          regresaRuntime.windowUntilActiveMs = nowMs + getRealtimeTimingValue('progressiveWindowSeconds') * 1000;
        }
      } else if (regresaRuntime.armed && Number(playerId) === Number(LOCAL_PLAYER_ID)
          && !getRealtimeProgressiveRecastDecision()) {
        void openRealtimeProgressiveRecastDecision(playerId, KIARA_REGRESA_CARD_ID, regresaRuntime.originTab, regresaRuntime.originSlot);
      }
      if (Number(playerId) !== Number(LOCAL_PLAYER_ID)
          && regresaRuntime.armed
          && Number(regresaRuntime.windowUntilActiveMs || 0) > 0
          && nowMs >= Number(regresaRuntime.windowUntilActiveMs)) {
        if (expireKiaraRegresaProgressiveWindow(playerId, 'ventana de rekasteo vencida')) changed = true;
      }
    }

    const runtime = getKouutenProgressiveState(playerId, false);
    if (!runtime?.active || runtime.awaitingResolution) continue;

    if (!runtime.armed && Number(runtime.cooldownUntilMs || 0) > 0 && nowMs >= Number(runtime.cooldownUntilMs)) {
      runtime.cooldownUntilMs = 0;
      runtime.armed = true;
      changed = true;
      if (Number(playerId) === Number(LOCAL_PLAYER_ID)) {
        runtime.windowUntilMs = 0;
        void openRealtimeProgressiveRecastDecision(playerId, KOUUTEN_CARD_ID, runtime.originTab, runtime.originSlot);
      } else {
        runtime.windowUntilMs = nowMs + getRealtimeTimingValue('progressiveWindowSeconds') * 1000;
      }
    } else if (runtime.armed && Number(playerId) === Number(LOCAL_PLAYER_ID)
        && !getRealtimeProgressiveRecastDecision()) {
      void openRealtimeProgressiveRecastDecision(playerId, KOUUTEN_CARD_ID, runtime.originTab, runtime.originSlot);
    }

    if (Number(playerId) !== Number(LOCAL_PLAYER_ID)
        && runtime.armed && Number(runtime.windowUntilMs || 0) > 0 && nowMs >= Number(runtime.windowUntilMs)) {
      deactivateKouutenProgressiveState(playerId, 'ventana de rekasteo vencida');
      changed = true;
    }
  }

  if (changed) {
    renderCards();
    renderPersistentUnitCommandStack();
  }
  return changed;
}


function cancelKouutenLocationTargeting(message = 'Selección de Kouuten cancelada.') {
  const kind = state.pendingPowerAction?.kind;
  if (!['kouutenLocation', 'kouutenRecastLocation'].includes(kind)) return false;
  state.pendingPowerAction = null;
  clearKouutenPreview();
  log(message);
  if (kind === 'kouutenRecastLocation') finishKouutenRecastReaction('cancelled');
  else renderAll();
  return true;
}

function beginKouutenLocationTargeting(playerId, cardId, originTab, originSlot) {
  const player = state.players?.[playerId];
  const card = CARD_LIBRARY[cardId || KOUUTEN_CARD_ID];
  const tab = Math.max(0, Number(originTab) || 0);
  const slot = Math.max(0, Number(originSlot) || 0);
  if (!player || !card || player.handTabs?.[tab]?.[slot] !== card.id) return false;
  state.selectedMover = null;
  state.selectedTarget = null;
  state.pendingCard = null;
  state.pendingPlacement = null;
  state.pendingPowerAction = { kind: 'kouutenLocation', stage: 'precast', playerId, cardId: card.id, originTab: tab, originSlot: slot };
  log('Kouuten: selecciona un área en arena. El centro se ajustará para cubrir un patrón de 5×5 con un núcleo efectivo de 3×3.');
  renderAll();
  return true;
}

function beginKouutenRecastLocationTargeting(playerId, cost) {
  const runtime = getKouutenProgressiveState(playerId, false);
  if (!runtime?.active || !runtime.armed) return false;
  state.selectedMover = null;
  state.selectedTarget = null;
  state.pendingCard = null;
  state.pendingPlacement = null;
  state.pendingPowerAction = {
    kind: 'kouutenRecastLocation',
    stage: 'precast',
    playerId,
    cardId: KOUUTEN_CARD_ID,
    cost: Math.max(2, Number(cost) || getKouutenNextRecastCost(playerId)),
    reactionResolve: outcome => finishKouutenRecastReaction(outcome || 'cancelled'),
  };
  log(`Kouuten: selecciona el área del rekasteo. El costo será de ${state.pendingPowerAction.cost} Fuego.`);
  renderAll();
  return true;
}

function queueKouutenRecast(playerId, center, cost) {
  const player = state.players?.[playerId];
  const card = CARD_LIBRARY[KOUUTEN_CARD_ID];
  const runtime = getKouutenProgressiveState(playerId, false);
  if (!player || !card || !runtime?.active || !runtime.armed) return false;
  if (!payKouutenRecastCost(playerId, cost)) {
    log(`No tienes ${cost} elementos de Fuego para rekastear Kouuten.`);
    finishKouutenRecastReaction('unavailable');
    return false;
  }
  const spawnId = `kouuten_recast_${Date.now()}_${Math.random().toString(16).slice(2)}`;
  player.castQueue.push({
    cardId: card.id,
    elementId: 'fuego',
    remaining: getEffectiveCastPhasesForCard(card, playerId),
    row: center.row,
    col: center.col,
    targetRow: center.row,
    targetCol: center.col,
    justAdded: true,
    introStarted: false,
    introDone: false,
    introEndsAt: 0,
    spawnId,
    originTab: null,
    originSlot: null,
    fromKouutenRecast: true,
    kouutenRecastCost: cost,
  });
  player.caster.state = 'casting';
  runtime.castCount = Math.max(1, Number(runtime.castCount || 1)) + 1;
  runtime.armed = false;
  runtime.awaitingResolution = true;
  runtime.cooldownUntilMs = 0;
  runtime.windowUntilMs = 0;
  closeKouutenRecastModal();
  log(`Kouuten se rekastea pagando ${cost} Fuego. El próximo rekasteo costará ${getKouutenNextRecastCost(playerId)} Fuego.`);
  if (isRealtimePlayStyle()) {
    renderAll('realtime-kouuten-progressive-recast');
    try { void requestRealtimeSpellActionPause(false, { reason: 'kouuten-recast-queued' }); } catch (_) {}
  } else {
    finishKouutenRecastReaction('activated');
  }
  return true;
}

function resolveKouutenLocation(playerId, row, col) {
  const pending = state.pendingPowerAction;
  if (!pending || !['kouutenLocation', 'kouutenRecastLocation'].includes(pending.kind) || Number(pending.playerId) !== Number(playerId)) return false;
  if (!isInside(row, col)) return false;
  const center = getKouutenClampedCenter(row, col);
  if (pending.kind === 'kouutenRecastLocation') {
    const cost = Math.max(2, Number(pending.cost) || getKouutenNextRecastCost(playerId));
    state.pendingPowerAction = null;
    clearKouutenPreview();
    if (isOnlineMatchActive() && isRealtimePlayStyle() && !isRealtimeOnlineAuthority()) {
      void window.ROK_ONLINE_PVP?.sendRealtimeCommand?.('progressive-recast', {
        cardId: KOUUTEN_CARD_ID,
        row: center.row,
        col: center.col,
        cost,
      });
      renderAll('realtime-progressive-recast-command');
      return true;
    }
    return queueKouutenRecast(playerId, center, cost);
  }
  const player = state.players?.[playerId];
  const card = CARD_LIBRARY[pending.cardId || KOUUTEN_CARD_ID];
  const tab = Math.max(0, Number(pending.originTab) || 0);
  const slot = Math.max(0, Number(pending.originSlot) || 0);
  if (!player || !card || player.handTabs?.[tab]?.[slot] !== card.id) {
    state.pendingPowerAction = null;
    clearKouutenPreview();
    log('Kouuten ya no está disponible en ese espacio del Spellbook.');
    renderAll();
    return false;
  }
  state.pendingPowerAction = null;
  clearKouutenPreview();
  state.selectedCardSlot = slot;
  state.pendingCard = { cardId: card.id, slotIndex: slot, tab, targetRow: center.row, targetCol: center.col };
  state.pendingPlacement = { row: center.row, col: center.col, key: 'arena' };
  log(`Kouuten se centrará en ${coordLabel(center.row, center.col)}. Se paga el costo y comienza el kasteo.`);
  confirmCast();
  return true;
}

function getKouutenImpactPlan(centerRow, centerCol) {
  const centerCells = getKouutenCenterCells(centerRow, centerCol).map(cell => ({ ...cell, kind: 'center' }));
  const groups = getKouutenSideGroups(centerRow, centerCol);
  const sideHits = Object.entries(groups).map(([side, cells]) => ({ ...cells[Math.floor(Math.random() * cells.length)], kind: 'side', side }));
  return { centerCells, sideHits, allHits: [...centerCells, ...sideHits], groups };
}

function getKouutenImpactTargets(plan) {
  const hitMap = new Map(plan.allHits.map(cell => [`${cell.row}:${cell.col}`, cell]));
  const targets = [];
  for (const targetPlayerId of [1, 2]) {
    for (const unit of state.players?.[targetPlayerId]?.units || []) {
      if (!unit || unit.status === 'restoring') continue;
      const cell = hitMap.get(`${Number(unit.row)}:${Number(unit.col)}`);
      if (cell) targets.push({ type: 'invocation', playerId: targetPlayerId, unitId: unit.id, row: Number(unit.row), col: Number(unit.col), hitKind: cell.kind });
    }
    for (const guardian of state.players?.[targetPlayerId]?.guardians || []) {
      if (!guardian || guardian.active === false || guardian.destroying || Number(guardian.resistance ?? 0) <= 0) continue;
      const cell = hitMap.get(`${Number(guardian.row)}:${Number(guardian.col)}`);
      if (cell) targets.push({ type: 'guardian', playerId: targetPlayerId, guardianId: guardian.id, row: Number(guardian.row), col: Number(guardian.col), hitKind: cell.kind });
    }
  }
  return targets;
}


function resolveKouutenImpactCell(playerId, cell, card = CARD_LIBRARY[KOUUTEN_CARD_ID]) {
  if (!cell || !isInside(cell.row, cell.col)) return;
  const damage = cell.kind === 'center' ? KOUUTEN_CENTER_DAMAGE : KOUUTEN_SIDE_DAMAGE;
  const reason = cell.kind === 'center' ? 'Kouuten · área efectiva' : 'Kouuten · impacto lateral';
  const source = {
    card,
    sourceCardId: card?.id || KOUUTEN_CARD_ID,
    sourcePlayerId: playerId,
    playerId,
    isSpell: true,
    renderAfterDefeatRemoval: true,
  };

  for (const targetPlayerId of [1, 2]) {
    const targetPlayer = state.players?.[targetPlayerId];
    if (!targetPlayer) continue;

    const caster = targetPlayer.caster;
    if (caster && Number(caster.life ?? 0) > 0 && Number(caster.row) === Number(cell.row) && Number(caster.col) === Number(cell.col)) {
      applyDamageToCaster(targetPlayerId, damage, reason, {
        sourcePlayerId: playerId,
        sourceCardId: card?.id || KOUUTEN_CARD_ID,
      });
    }

    for (const guardian of [...(targetPlayer.guardians || [])]) {
      if (!guardian || guardian.active === false || guardian.destroying || Number(guardian.resistance ?? 0) <= 0) continue;
      if (Number(guardian.row) !== Number(cell.row) || Number(guardian.col) !== Number(cell.col)) continue;
      applyDamageToTarget(source, {
        type: 'guardian',
        playerId: targetPlayerId,
        guardianId: guardian.id,
        row: Number(guardian.row),
        col: Number(guardian.col),
      }, damage);
    }

    const unitsAtImpact = [...(targetPlayer.units || [])].filter(unit => unit
      && unit.status !== 'restoring'
      && Number(unit.row) === Number(cell.row)
      && Number(unit.col) === Number(cell.col));
    for (const unit of unitsAtImpact) {
      const liveUnit = getUnitById(targetPlayerId, unit.id);
      if (!liveUnit || liveUnit.status === 'restoring') continue;
      damageInvocationUnit(targetPlayerId, liveUnit, damage, reason, source);
      const survivingUnit = getUnitById(targetPlayerId, unit.id);
      if (
        cell.kind === 'center'
        && survivingUnit
        && survivingUnit.status !== 'restoring'
        && Number(survivingUnit.hp ?? 0) > 0
      ) {
        applyKouutenBurnToUnit(targetPlayerId, survivingUnit, KOUUTEN_BURN_LEVEL, card?.id || KOUUTEN_CARD_ID);
      }
    }
  }
}

function applyKouutenBurnToUnit(playerId, unit, level = KOUUTEN_BURN_LEVEL, sourceCardId = KOUUTEN_CARD_ID) {
  if (!unit) return false;
  const durationPhases = getBurnDurationPhasesByLevel(level);
  addActiveFactorToUnit(unit, {
    id: 'burn',
    level,
    source: 'spell',
    sourceType: 'card',
    sourceId: sourceCardId,
    sourceCardId,
    sourceName: 'Kouuten',
    pda: 6,
    guaranteed: true,
    durationPhases,
    durationRemaining: durationPhases,
    tickInterval: PROGRESSIVE_FACTOR_TICK_INTERVAL_PHASES,
    tickRemaining: PROGRESSIVE_FACTOR_TICK_INTERVAL_PHASES,
    damageTicksDone: 0,
    maxDamageTicks: BURN_MAX_DAMAGE_TICKS_PER_APPLICATION,
  });
  pulseProgressiveFactorApplication(playerId, unit.id, 'burn');
  renderUnits();
  renderPersistentUnitCommandStack();
  renderSelectedUnitCommandPanel();
  renderCombatHud();
  const card = CARD_LIBRARY[unit.cardId];
  log(`${card?.name || 'Invocación'} recibe Quemadura ${level} garantizada por Kouuten durante ${durationPhases} fases.`);
  return true;
}

function clearOrphanedKouutenFx() {
  document.querySelectorAll('.kouuten-fx-layer').forEach(node => node.remove());
}

function createKouutenFx() {
  const host = els.board || els.boardContent;
  if (!host) return null;
  clearOrphanedKouutenFx();
  const fx = document.createElement('div');
  fx.className = 'kouuten-fx-layer';
  fx.dataset.hostKind = host === els.board ? 'board' : 'board-content';
  host.appendChild(fx);
  return fx;
}

function getKouutenFxCellCenter(fx, row, col) {
  const host = fx?.parentElement || els.boardContent;
  const hostRect = host.getBoundingClientRect();
  const gridEl = row >= 9 ? els.allyGrid : els.enemyGrid;
  const gridRect = gridEl.getBoundingClientRect();
  const localRow = row >= 9 ? row - 9 : row;
  return {
    x: ((gridRect.left - hostRect.left) + ((col + 0.5) / 9) * gridRect.width) / hostRect.width * 100,
    y: ((gridRect.top - hostRect.top) + ((localRow + 0.5) / 9) * gridRect.height) / hostRect.height * 100,
  };
}

function spawnKouutenTrailParticle(fx, x, y, ember = false, direction = -1) {
  if (!fx) return;
  const p = document.createElement('span');
  p.className = `kouuten-trail-particle${ember ? ' ember' : ''}`;
  p.style.left = `${x}%`;
  p.style.top = `${y}%`;
  p.style.setProperty('--particle-drift-x', `${(Math.random() * 2.2 - 1.1).toFixed(2)}%`);
  p.style.setProperty('--particle-drift-y', `${((0.9 + Math.random() * 1.7) * (direction < 0 ? 1 : -1)).toFixed(2)}%`);
  p.style.setProperty('--particle-life', `${(0.62 + Math.random() * 0.82).toFixed(2)}s`);
  p.style.setProperty('--particle-size', `${(ember ? 2.8 : 3.8) + Math.random() * 3.2}px`);
  fx.appendChild(p);
  window.setTimeout(() => p.remove(), 1700);
}

function spawnKouutenImpactFx(fx, row, col, direction) {
  if (!fx) return;
  const point = getKouutenFxCellCenter(fx, row, col);
  const burst = document.createElement('span');
  burst.className = 'kouuten-impact-burst';
  burst.style.left = `${point.x}%`;
  burst.style.top = `${point.y}%`;
  fx.appendChild(burst);
  for (let i = 0; i < 7; i += 1) {
    spawnKouutenTrailParticle(fx, point.x + (Math.random() * 0.8 - 0.4), point.y + (Math.random() * 0.5 - 0.25), i % 2 === 0, direction);
  }
  window.setTimeout(() => burst.remove(), 900);
}

function playKouutenStrikeAtCell(fx, row, col, delayMs = 0, playerId = LOCAL_PLAYER_ID, onImpact = null) {
  return new Promise(resolve => {
    window.setTimeout(() => {
      if (!fx || !fx.isConnected) return resolve();
      const target = getKouutenFxCellCenter(fx, row, col);
      const direction = Number(playerId) === 1 ? -1 : 1;
      const arrow = document.createElement('img');
      arrow.className = 'kouuten-arrow';
      arrow.src = 'assets/weapons/projectile-arrow.png';
      arrow.alt = '';
      arrow.draggable = false;
      fx.appendChild(arrow);
      const startX = target.x + (Math.random() * 4.2 - 2.1);
      const startY = direction < 0 ? (108 + Math.random() * 8) : (-8 - Math.random() * 8);
      const duration = 760 + Math.random() * 320;
      const rotation = direction < 0 ? 0 : 180;
      let prevX = startX;
      let prevY = startY;
      const start = performance.now();
      const frame = now => {
        const elapsed = now - start;
        const t = Math.max(0, Math.min(1, elapsed / duration));
        const ease = t * t * t;
        const x = startX + ((target.x - startX) * ease);
        const y = startY + ((target.y - startY) * ease);
        const scale = 1.5 - (0.5 * ease);
        const opacity = Math.min(1, t / 0.12);
        arrow.style.left = `${x}%`;
        arrow.style.top = `${y}%`;
        arrow.style.opacity = `${opacity}`;
        arrow.style.transform = `translate(-50%, -50%) rotate(${rotation}deg) scale(${scale})`;
        if (elapsed > 70 && Math.random() < 0.74) {
          const midX = (x + prevX) / 2;
          const midY = (y + prevY) / 2;
          spawnKouutenTrailParticle(fx, midX, midY, Math.random() < 0.45, direction);
        }
        prevX = x;
        prevY = y;
        if (t < 1) {
          requestAnimationFrame(frame);
          return;
        }
        arrow.style.left = `${target.x}%`;
        arrow.style.top = `${target.y}%`;
        arrow.style.opacity = '1';
        arrow.style.transform = `translate(-50%, -50%) rotate(${rotation}deg) scale(1)`;
        arrow.classList.add('kouuten-arrow-embedded');
        spawnKouutenImpactFx(fx, row, col, direction);
        try {
          if (typeof onImpact === 'function') onImpact();
        } catch (error) {
          console.error('Kouuten · error al resolver impacto:', error);
        } finally {
          window.setTimeout(() => {
            if (!arrow.isConnected) return;
            arrow.classList.add('kouuten-arrow-fadeout');
            window.setTimeout(() => arrow.remove(), 260);
          }, 1500);
          resolve();
        }
      };
      requestAnimationFrame(frame);
    }, delayMs);
  });
}

async function resolveKouutenCast(playerId, item, card = CARD_LIBRARY[KOUUTEN_CARD_ID]) {
  const center = getKouutenClampedCenter(item?.targetRow ?? item?.row ?? 8, item?.targetCol ?? item?.col ?? 4);
  const plan = getKouutenImpactPlan(center.row, center.col);
  const orderedHits = [...plan.centerCells, ...plan.sideHits]
    .sort((a, b) => (a.row - b.row) || (a.col - b.col))
    .map((cell, index) => ({ ...cell, delayMs: Math.floor(Math.random() * 460) + index * 44 }));
  emitOnlineVisualEvent('kouuten', {
    playerId: Number(playerId),
    center,
    hits: orderedHits.map(cell => ({ row: Number(cell.row), col: Number(cell.col), kind: cell.kind || 'center', side: cell.side || null, delayMs: Number(cell.delayMs || 0) })),
  });
  const fx = createKouutenFx();
  const resolvedCells = new Set();
  log(`Kouuten bombardea ${coordLabel(center.row, center.col)} con una lluvia irregular de flechas incendiarias.`);
  const cleanupTimer = fx ? window.setTimeout(() => fx.remove(), 7000) : null;
  try {
    await Promise.all(orderedHits.map(cell => playKouutenStrikeAtCell(
      fx,
      cell.row,
      cell.col,
      cell.delayMs,
      playerId,
      () => {
        const key = `${cell.row}:${cell.col}`;
        if (resolvedCells.has(key)) return;
        resolvedCells.add(key);
        resolveKouutenImpactCell(playerId, cell, card);
      }
    )));
    activateKouutenProgressiveState(playerId);
    renderAll();
    return { type: 'spell', card, spellId: card?.id || KOUUTEN_CARD_ID };
  } finally {
    if (cleanupTimer) window.clearTimeout(cleanupTimer);
    if (fx) window.setTimeout(() => fx.remove(), 1900);
  }
}


async function playRemoteKouutenFx(payload = {}) {
  const hits = Array.isArray(payload.hits) ? payload.hits : [];
  if (!hits.length) return false;
  const fx = createKouutenFx();
  const cleanupTimer = fx ? window.setTimeout(() => fx.remove(), 7000) : null;
  try {
    await Promise.all(hits.map(cell => playKouutenStrikeAtCell(
      fx,
      Number(cell.row),
      Number(cell.col),
      Number(cell.delayMs || 0),
      Number(payload.playerId || 1),
      null
    )));
    return true;
  } finally {
    if (cleanupTimer) window.clearTimeout(cleanupTimer);
    if (fx) window.setTimeout(() => fx.remove(), 1900);
  }
}

function createKouutenRecastQuickReactionCandidate(playerId = LOCAL_PLAYER_ID) {
  const runtime = getKouutenProgressiveState(playerId, false);
  if (!runtime?.active || runtime.armed || runtime.awaitingResolution) return null;
  const cost = getKouutenNextRecastCost(playerId);
  return {
    type: 'kouutenRecast',
    selectionType: 'spell',
    playerId,
    cardId: KOUUTEN_CARD_ID,
    label: 'Kouuten',
    actions: [{ id: 'kouutenRecastPrompt', label: 'Activar rekasteo', title: `Kouuten · rekasteo por ${cost} Fuego` }],
    actionLabels: ['Activar rekasteo'],
    targets: [],
    kouutenRecastCost: cost,
  };
}

function armKouutenRecast(playerId = LOCAL_PLAYER_ID) {
  const runtime = getKouutenProgressiveState(playerId, false);
  if (!runtime?.active || runtime.awaitingResolution) return false;
  const cost = getKouutenNextRecastCost(playerId);
  if (!canPayKouutenRecastCost(playerId, cost)) {
    deactivateKouutenProgressiveState(playerId, `no hay ${cost} Fuego disponible para el siguiente rekasteo`);
    renderAll();
    return false;
  }
  runtime.armed = true;
  runtime.lastArmedPhaseKey = getQuickReactionPhaseKey(playerId);
  log(canPayKouutenRecastCost(playerId, cost)
    ? `Kouuten puede rekastearse por ${cost} Fuego. Pulsa su miniatura persistente para continuar.`
    : `Kouuten consulta el rekasteo por ${cost} Fuego, pero no tienes recursos suficientes. Pulsa su miniatura y cancela para terminar la cadena.`);
  renderAll();
  return true;
}

async function runLocalKouutenRecastOpportunityBeforePhase() {
  if (isRealtimePlayStyle()) return 'none';
  const runtime = getKouutenProgressiveState(LOCAL_PLAYER_ID, false);
  if (!runtime?.active) return 'none';
  const nextCost = getKouutenNextRecastCost(LOCAL_PLAYER_ID);
  if (!canPayKouutenRecastCost(LOCAL_PLAYER_ID, nextCost)) {
    closeKouutenRecastModal();
    deactivateKouutenProgressiveState(LOCAL_PLAYER_ID, `no hay ${nextCost} Fuego disponible para el siguiente rekasteo`);
    renderAll();
    return 'unavailable';
  }
  if (!canOfferQuickReactionWindowNow(LOCAL_PLAYER_ID)) return 'none';
  const phaseKey = getQuickReactionPhaseKey(LOCAL_PLAYER_ID);
  if (runtime.lastPromptPhaseKey === phaseKey) return 'already-offered';
  runtime.lastPromptPhaseKey = phaseKey;
  runtime.armed = false;
  closeKouutenRecastModal();
  const candidate = createKouutenRecastQuickReactionCandidate(LOCAL_PLAYER_ID);
  if (!candidate) {
    renderAll();
    return 'none';
  }
  return await runLocalQuickReactionOpportunityBeforePhase({
    windowMs: QUICK_REACTION_WINDOW_MS,
    candidatesOverride: [candidate],
    collectContext: { phaseTransition: true, kouutenRecast: true },
  });
}

async function ensureLocalKouutenRecastWindowForCurrentPhase() {
  return await runLocalKouutenRecastOpportunityBeforePhase();
}

function chooseBestKouutenCenter(playerId) {
  let best = { row: 8, col: 4, score: -Infinity, enemyHits: 0 };
  const enemyId = getEnemyPlayerId(playerId);
  for (let row = 2; row <= 15; row += 1) {
    for (let col = 2; col <= 6; col += 1) {
      const centerCells = new Set(getKouutenCenterCells(row, col).map(cell => `${cell.row}:${cell.col}`));
      const sideCells = new Set(Object.values(getKouutenSideGroups(row, col)).flat().map(cell => `${cell.row}:${cell.col}`));
      const enemyCenterHits = (state.players?.[enemyId]?.units || []).filter(unit => unit && unit.status !== 'restoring' && centerCells.has(`${unit.row}:${unit.col}`)).length;
      const enemySideHits = (state.players?.[enemyId]?.units || []).filter(unit => unit && unit.status !== 'restoring' && sideCells.has(`${unit.row}:${unit.col}`)).length;
      const allyCenterHits = (state.players?.[playerId]?.units || []).filter(unit => unit && unit.status !== 'restoring' && centerCells.has(`${unit.row}:${unit.col}`)).length;
      const allySideHits = (state.players?.[playerId]?.units || []).filter(unit => unit && unit.status !== 'restoring' && sideCells.has(`${unit.row}:${unit.col}`)).length;
      const score = (enemyCenterHits * 5) + enemySideHits - (allyCenterHits * 4) - allySideHits;
      if (score > best.score || (score === best.score && enemyCenterHits > best.enemyHits)) {
        best = { row, col, score, enemyHits: enemyCenterHits };
      }
    }
  }
  return best;
}



function getGurenGanClampedCenter(row = 8, col = 4) {
  return {
    row: Math.max(3, Math.min(14, Math.floor(Number(row) || 0))),
    col: Math.max(3, Math.min(5, Math.floor(Number(col) || 0))),
  };
}

function getGurenGanEffectiveCells(row = 8, col = 4) {
  const center = getGurenGanClampedCenter(row, col);
  const cells = [];
  for (let dr = -2; dr <= 2; dr += 1) {
    for (let dc = -2; dc <= 2; dc += 1) {
      if (Math.abs(dr) + Math.abs(dc) > 2) continue;
      cells.push({
        row: center.row + dr,
        col: center.col + dc,
        kind: dr === 0 && dc === 0 ? 'center' : 'effective',
      });
    }
  }
  return cells;
}

function getGurenGanOuterGroups(row = 8, col = 4) {
  const center = getGurenGanClampedCenter(row, col);
  return {
    upperRight: [
      { row: center.row - 3, col: center.col },
      { row: center.row - 2, col: center.col + 1 },
      { row: center.row - 1, col: center.col + 2 },
    ],
    lowerRight: [
      { row: center.row, col: center.col + 3 },
      { row: center.row + 1, col: center.col + 2 },
      { row: center.row + 2, col: center.col + 1 },
    ],
    lowerLeft: [
      { row: center.row + 3, col: center.col },
      { row: center.row + 2, col: center.col - 1 },
      { row: center.row + 1, col: center.col - 2 },
    ],
    upperLeft: [
      { row: center.row, col: center.col - 3 },
      { row: center.row - 1, col: center.col - 2 },
      { row: center.row - 2, col: center.col - 1 },
    ],
  };
}

function getGurenGanOuterCells(row = 8, col = 4) {
  return Object.values(getGurenGanOuterGroups(row, col)).flat();
}

function pickRandomGurenGanSplashCells(groupCells, count = GUREN_GAN_SPLASH_HITS_PER_GROUP) {
  const pool = [...(groupCells || [])];
  for (let i = pool.length - 1; i > 0; i -= 1) {
    const j = Math.floor(Math.random() * (i + 1));
    [pool[i], pool[j]] = [pool[j], pool[i]];
  }
  return pool.slice(0, Math.max(0, Math.min(pool.length, Number(count) || 0)));
}

function getGurenGanImpactPlan(centerRow, centerCol) {
  const center = getGurenGanClampedCenter(centerRow, centerCol);
  const effectiveCells = getGurenGanEffectiveCells(center.row, center.col);
  const groups = getGurenGanOuterGroups(center.row, center.col);
  const splashHits = Object.entries(groups).flatMap(([group, cells]) =>
    pickRandomGurenGanSplashCells(cells).map(cell => ({ ...cell, kind: 'splash', group }))
  );
  return {
    center,
    effectiveCells,
    groups,
    outerCells: Object.values(groups).flat().map(cell => ({ ...cell, kind: 'outer' })),
    splashHits,
    allDamageCells: [...effectiveCells, ...splashHits],
  };
}

function clearGurenGanPreview() {
  document.querySelectorAll('.cell.guren-gan-center-preview, .cell.guren-gan-effective-preview, .cell.guren-gan-outer-preview').forEach(cell => {
    cell.classList.remove('guren-gan-center-preview', 'guren-gan-effective-preview', 'guren-gan-outer-preview');
  });
}

function previewGurenGanAreaAt(row, col) {
  clearGurenGanPreview();
  const center = getGurenGanClampedCenter(row, col);
  const effective = new Map(getGurenGanEffectiveCells(center.row, center.col).map(cell => [`${cell.row}:${cell.col}`, cell.kind]));
  const outer = new Set(getGurenGanOuterCells(center.row, center.col).map(cell => `${cell.row}:${cell.col}`));
  document.querySelectorAll('.cell[data-row][data-col]').forEach(cell => {
    const key = `${Number(cell.dataset.row)}:${Number(cell.dataset.col)}`;
    const kind = effective.get(key);
    if (kind === 'center') cell.classList.add('guren-gan-center-preview');
    else if (kind === 'effective') cell.classList.add('guren-gan-effective-preview');
    else if (outer.has(key)) cell.classList.add('guren-gan-outer-preview');
  });
}

function cancelGurenGanLocationTargeting(message = 'Selección de Guren Gan cancelada.') {
  if (state.pendingPowerAction?.kind !== 'gurenGanLocation') return false;
  state.pendingPowerAction = null;
  clearGurenGanPreview();
  log(message);
  renderAll();
  return true;
}

function beginGurenGanLocationTargeting(playerId, cardId, originTab, originSlot) {
  const player = state.players?.[playerId];
  const card = CARD_LIBRARY[cardId || GUREN_GAN_CARD_ID];
  const tab = Math.max(0, Number(originTab) || 0);
  const slot = Math.max(0, Number(originSlot) || 0);
  if (!player || !card || player.handTabs?.[tab]?.[slot] !== card.id) return false;
  state.selectedMover = null;
  state.selectedTarget = null;
  state.pendingCard = null;
  state.pendingPlacement = null;
  state.pendingPowerAction = {
    kind: 'gurenGanLocation',
    stage: 'precast',
    playerId,
    cardId: card.id,
    originTab: tab,
    originSlot: slot,
  };
  log('Guren Gan: selecciona el centro del impacto. El patrón completo tiene radio 3; el costo se pagará al confirmar.');
  renderAll();
  return true;
}

function resolveGurenGanLocation(playerId, row, col) {
  const pending = state.pendingPowerAction;
  if (!pending || pending.kind !== 'gurenGanLocation' || Number(pending.playerId) !== Number(playerId)) return false;
  const center = getGurenGanClampedCenter(row, col);
  const player = state.players?.[playerId];
  const card = CARD_LIBRARY[pending.cardId || GUREN_GAN_CARD_ID];
  const tab = Math.max(0, Number(pending.originTab) || 0);
  const slot = Math.max(0, Number(pending.originSlot) || 0);
  if (!player || !card || player.handTabs?.[tab]?.[slot] !== card.id) {
    state.pendingPowerAction = null;
    clearGurenGanPreview();
    log('Guren Gan ya no está disponible en ese espacio del Spellbook.');
    renderAll();
    return false;
  }
  state.pendingPowerAction = null;
  clearGurenGanPreview();
  state.selectedCardSlot = slot;
  state.pendingCard = { cardId: card.id, slotIndex: slot, tab, targetRow: center.row, targetCol: center.col };
  state.pendingPlacement = { row: center.row, col: center.col, key: 'arena' };
  log(`Guren Gan impactará con centro en ${coordLabel(center.row, center.col)}. Se paga el costo y comienza el kasteo.`);
  confirmCast();
  return true;
}

function applyGurenGanBurnToEntity(playerId, entity, level = GUREN_GAN_BURN_LEVEL, sourceCardId = GUREN_GAN_CARD_ID, entityType = 'invocation') {
  if (!entity) return false;
  const durationPhases = getBurnDurationPhasesByLevel(level);
  addActiveFactorToUnit(entity, {
    id: 'burn',
    level,
    source: 'spell',
    sourceType: 'card',
    sourceId: sourceCardId,
    sourceCardId,
    sourceName: 'Guren Gan',
    pda: 6,
    guaranteed: true,
    damageNature: 'elemental',
    durationPhases,
    durationRemaining: durationPhases,
    tickInterval: PROGRESSIVE_FACTOR_TICK_INTERVAL_PHASES,
    tickRemaining: PROGRESSIVE_FACTOR_TICK_INTERVAL_PHASES,
    damageTicksDone: 0,
    maxDamageTicks: BURN_MAX_DAMAGE_TICKS_PER_APPLICATION,
  });
  if (entityType === 'invocation') pulseProgressiveFactorApplication(playerId, entity.id, 'burn');
  const label = entityType === 'guardian' ? 'La estructura' : (CARD_LIBRARY[entity.cardId]?.name || 'Invocación');
  log(`${label} recibe Quemadura ${level} garantizada por Guren Gan durante ${durationPhases} fases.`);
  return true;
}

function resolveGurenGanImpactCell(playerId, cell, card = CARD_LIBRARY[GUREN_GAN_CARD_ID]) {
  if (!cell || !isInside(cell.row, cell.col)) return;
  const rawDamage = cell.kind === 'splash' ? GUREN_GAN_SPLASH_DAMAGE : GUREN_GAN_EFFECTIVE_DAMAGE;
  const reason = cell.kind === 'splash' ? 'Guren Gan · salpicadura' : 'Guren Gan · área efectiva';
  const source = {
    card,
    sourceCardId: card?.id || GUREN_GAN_CARD_ID,
    sourcePlayerId: playerId,
    playerId,
    isSpell: true,
    renderAfterDefeatRemoval: true,
  };

  for (const targetPlayerId of [1, 2]) {
    const targetPlayer = state.players?.[targetPlayerId];
    if (!targetPlayer) continue;

    const caster = targetPlayer.caster;
    if (caster && Number(caster.life ?? 0) > 0 && Number(caster.row) === Number(cell.row) && Number(caster.col) === Number(cell.col)) {
      applyDamageToCaster(targetPlayerId, rawDamage, reason, {
        sourcePlayerId: playerId,
        sourceCardId: card?.id || GUREN_GAN_CARD_ID,
      });
    }

    const structureDamage = Math.max(1, Math.floor(rawDamage * GUREN_GAN_STRUCTURE_DAMAGE_MULTIPLIER));
    for (const guardian of [...(targetPlayer.guardians || [])]) {
      if (!guardian || guardian.active === false || guardian.destroying || Number(guardian.resistance ?? 0) <= 0) continue;
      if (Number(guardian.row) !== Number(cell.row) || Number(guardian.col) !== Number(cell.col)) continue;
      applyDamageToTarget(source, {
        type: 'guardian',
        playerId: targetPlayerId,
        guardianId: guardian.id,
        row: Number(guardian.row),
        col: Number(guardian.col),
      }, structureDamage);
      const survivingGuardian = state.players?.[targetPlayerId]?.guardians?.find(item => String(item.id) === String(guardian.id));
      if (survivingGuardian && survivingGuardian.active !== false && !survivingGuardian.destroying && Number(survivingGuardian.resistance ?? 0) > 0) {
        applyGurenGanBurnToEntity(targetPlayerId, survivingGuardian, GUREN_GAN_BURN_LEVEL, card?.id || GUREN_GAN_CARD_ID, 'guardian');
      }
    }

    const unitsAtImpact = [...(targetPlayer.units || [])].filter(unit => unit
      && unit.status !== 'restoring'
      && Number(unit.row) === Number(cell.row)
      && Number(unit.col) === Number(cell.col));
    for (const unit of unitsAtImpact) {
      const liveUnit = getUnitById(targetPlayerId, unit.id);
      if (!liveUnit || liveUnit.status === 'restoring') continue;
      damageInvocationUnit(targetPlayerId, liveUnit, rawDamage, reason, source);
      const survivingUnit = getUnitById(targetPlayerId, unit.id);
      if (survivingUnit && survivingUnit.status !== 'restoring' && Number(survivingUnit.hp ?? 0) > 0) {
        applyGurenGanBurnToEntity(targetPlayerId, survivingUnit, GUREN_GAN_BURN_LEVEL, card?.id || GUREN_GAN_CARD_ID, 'invocation');
      }
    }
  }
  renderUnits();
  renderPersistentUnitCommandStack();
  renderSelectedUnitCommandPanel();
  renderCombatHud();
}

function clearOrphanedGurenGanFx() {
  document.querySelectorAll('.guren-gan-fx-layer').forEach(node => node.remove());
}

function createGurenGanFx() {
  const host = els.board || els.boardContent;
  if (!host) return null;
  clearOrphanedGurenGanFx();
  const fx = document.createElement('div');
  fx.className = 'guren-gan-fx-layer';
  host.appendChild(fx);
  return fx;
}

function getGurenGanFxCellGeometry(fx, row, col) {
  const host = fx?.parentElement || els.boardContent;
  const hostRect = host.getBoundingClientRect();
  const gridEl = row >= 9 ? els.allyGrid : els.enemyGrid;
  const gridRect = gridEl.getBoundingClientRect();
  const localRow = row >= 9 ? row - 9 : row;
  return {
    x: ((gridRect.left - hostRect.left) + ((col + 0.5) / 9) * gridRect.width) / hostRect.width * 100,
    y: ((gridRect.top - hostRect.top) + ((localRow + 0.5) / 9) * gridRect.height) / hostRect.height * 100,
    width: (gridRect.width / 9) / hostRect.width * 100,
    height: (gridRect.height / 9) / hostRect.height * 100,
  };
}

function spawnGurenGanParticle(fx, x, y, options = {}) {
  if (!fx) return null;
  const particle = document.createElement('span');
  particle.className = `guren-gan-particle${options.smoke ? ' guren-gan-particle-smoke' : ''}`;
  particle.style.left = `${x}%`;
  particle.style.top = `${y}%`;
  particle.style.setProperty('--guren-particle-x', `${(Math.random() * 4.2 - 2.1).toFixed(2)}%`);
  particle.style.setProperty('--guren-particle-y', `${(Math.random() * 3.4 - 1.7).toFixed(2)}%`);
  particle.style.setProperty('--guren-particle-size', `${(options.smoke ? 8 : 4) + Math.random() * (options.smoke ? 10 : 7)}px`);
  particle.style.setProperty('--guren-particle-life', `${(options.smoke ? 0.85 : 0.48) + Math.random() * 0.72}s`);
  fx.appendChild(particle);
  window.setTimeout(() => particle.remove(), 1800);
  return particle;
}

function createGurenGanCellGlow(fx, cell, className, removeAfterMs) {
  const geometry = getGurenGanFxCellGeometry(fx, cell.row, cell.col);
  const glow = document.createElement('span');
  glow.className = `guren-gan-cell-glow ${className}`;
  glow.style.left = `${geometry.x}%`;
  glow.style.top = `${geometry.y}%`;
  glow.style.width = `${geometry.width}%`;
  glow.style.height = `${geometry.height}%`;
  glow.style.setProperty('--guren-flicker-delay', `${(-Math.random() * 0.9).toFixed(2)}s`);
  glow.style.setProperty('--guren-flicker-duration', `${(0.18 + Math.random() * 0.34).toFixed(2)}s`);
  fx.appendChild(glow);
  window.setTimeout(() => {
    glow.classList.add('guren-gan-cell-glow-fade');
    window.setTimeout(() => glow.remove(), 300);
  }, removeAfterMs);
  return glow;
}

function showGurenGanImpactIllumination(fx, plan) {
  if (!fx || !plan) return;
  plan.outerCells.forEach(cell => createGurenGanCellGlow(fx, cell, 'guren-gan-glow-outer', 1380 + Math.random() * 120));
  plan.effectiveCells.forEach(cell => {
    const isCenter = cell.kind === 'center';
    createGurenGanCellGlow(fx, cell, isCenter ? 'guren-gan-glow-center' : 'guren-gan-glow-effective', isCenter ? 2050 : 1720 + Math.random() * 120);
  });
}

function spawnGurenGanImpactBurst(fx, row, col, className = '') {
  if (!fx) return;
  const point = getGurenGanFxCellGeometry(fx, row, col);
  const burst = document.createElement('span');
  burst.className = `guren-gan-impact-burst ${className}`.trim();
  burst.style.left = `${point.x}%`;
  burst.style.top = `${point.y}%`;
  burst.style.width = `${point.width * (className.includes('splash') ? 1.1 : 2.1)}%`;
  burst.style.height = `${point.height * (className.includes('splash') ? 1.1 : 2.1)}%`;
  fx.appendChild(burst);
  for (let i = 0; i < (className.includes('splash') ? 8 : 18); i += 1) {
    spawnGurenGanParticle(fx, point.x + (Math.random() * 1.2 - 0.6), point.y + (Math.random() * 0.9 - 0.45), { smoke: i % 4 === 0 });
  }
  window.setTimeout(() => burst.remove(), className.includes('splash') ? 900 : 1300);
}

function spawnGurenGanShockwave(fx, center) {
  if (!fx) return;
  const point = getGurenGanFxCellGeometry(fx, center.row, center.col);
  const wave = document.createElement('span');
  wave.className = 'guren-gan-shockwave';
  wave.style.left = `${point.x}%`;
  wave.style.top = `${point.y}%`;
  wave.style.width = `${point.width * 5.15}%`;
  wave.style.height = `${point.height * 5.15}%`;
  fx.appendChild(wave);
  window.setTimeout(() => wave.remove(), 1050);
}

function playGurenGanSplash(fx, center, targetCell, delayMs, playerId, onImpact) {
  return new Promise(resolve => {
    window.setTimeout(() => {
      if (!fx?.isConnected) return resolve();
      const start = getGurenGanFxCellGeometry(fx, center.row, center.col);
      const target = getGurenGanFxCellGeometry(fx, targetCell.row, targetCell.col);
      const splash = document.createElement('span');
      splash.className = 'guren-gan-splash-projectile';
      splash.style.left = `${start.x}%`;
      splash.style.top = `${start.y}%`;
      fx.appendChild(splash);
      const launchedAt = performance.now();
      const duration = 390 + Math.random() * 210;
      const frame = now => {
        const t = Math.max(0, Math.min(1, (now - launchedAt) / duration));
        const eased = 1 - Math.pow(1 - t, 2.4);
        const x = start.x + (target.x - start.x) * eased;
        const baseY = start.y + (target.y - start.y) * eased;
        const arc = Math.sin(Math.PI * t) * (2.1 + Math.random() * 0.08);
        const direction = Number(playerId) === 1 ? -1 : 1;
        const y = baseY - arc * direction;
        splash.style.left = `${x}%`;
        splash.style.top = `${y}%`;
        splash.style.transform = `translate(-50%, -50%) scale(${1.15 - 0.35 * t})`;
        if (Math.random() < 0.58) spawnGurenGanParticle(fx, x, y, { smoke: Math.random() < 0.22 });
        if (t < 1) return requestAnimationFrame(frame);
        splash.remove();
        spawnGurenGanImpactBurst(fx, targetCell.row, targetCell.col, 'guren-gan-impact-splash');
        try { if (typeof onImpact === 'function') onImpact(); } finally { resolve(); }
      };
      requestAnimationFrame(frame);
    }, delayMs);
  });
}

function playGurenGanCannonball(fx, center, playerId, onImpact) {
  return new Promise(resolve => {
    if (!fx) {
      if (typeof onImpact === 'function') onImpact();
      return resolve();
    }
    const target = getGurenGanFxCellGeometry(fx, center.row, center.col);
    const direction = Number(playerId) === 1 ? -1 : 1;
    const ball = document.createElement('span');
    ball.className = 'guren-gan-cannonball';
    ball.style.width = `${target.width * 0.5}%`;
    ball.style.height = `${target.height * 0.5}%`;
    const core = document.createElement('span');
    core.className = 'guren-gan-cannonball-core';
    ball.appendChild(core);
    fx.appendChild(ball);
    const startX = 7 + Math.random() * 86;
    const startY = direction < 0 ? 108 + Math.random() * 8 : -8 - Math.random() * 8;
    const duration = 920 + Math.random() * 260;
    const startedAt = performance.now();
    let prevX = startX;
    let prevY = startY;
    const frame = now => {
      const t = Math.max(0, Math.min(1, (now - startedAt) / duration));
      const eased = t * t * (3 - 2 * t);
      const x = startX + (target.x - startX) * eased;
      const y = startY + (target.y - startY) * eased;
      const scale = 2 - eased;
      ball.style.left = `${x}%`;
      ball.style.top = `${y}%`;
      ball.style.opacity = `${Math.min(1, t / 0.08)}`;
      ball.style.transform = `translate(-50%, -50%) scale(${scale})`;
      if (t > 0.04 && Math.random() < 0.92) {
        const trailX = (x + prevX) / 2;
        const trailY = (y + prevY) / 2;
        spawnGurenGanParticle(fx, trailX, trailY, { smoke: Math.random() < 0.48 });
      }
      prevX = x;
      prevY = y;
      if (t < 1) return requestAnimationFrame(frame);
      ball.style.left = `${target.x}%`;
      ball.style.top = `${target.y}%`;
      ball.style.transform = 'translate(-50%, -50%) scale(1)';
      spawnGurenGanImpactBurst(fx, center.row, center.col, 'guren-gan-impact-main');
      try { if (typeof onImpact === 'function') onImpact(); } finally {
        ball.classList.add('guren-gan-cannonball-impact');
        window.setTimeout(() => ball.remove(), 320);
        resolve();
      }
    };
    requestAnimationFrame(frame);
  });
}

async function resolveGurenGanCast(playerId, item, card = CARD_LIBRARY[GUREN_GAN_CARD_ID]) {
  const center = getGurenGanClampedCenter(item?.targetRow ?? item?.row ?? 8, item?.targetCol ?? item?.col ?? 4);
  const plan = getGurenGanImpactPlan(center.row, center.col);
  const splashSchedule = plan.splashHits.map((cell, index) => ({ ...cell, delayMs: 110 + index * 42 + Math.floor(Math.random() * 180) }));
  emitOnlineVisualEvent('guren-gan', {
    playerId: Number(playerId),
    center: { row: Number(center.row), col: Number(center.col) },
    splashHits: splashSchedule.map(cell => ({ row: Number(cell.row), col: Number(cell.col), kind: cell.kind || 'splash', group: cell.group || null, delayMs: Number(cell.delayMs || 0) })),
  });
  const fx = createGurenGanFx();
  log(`Guren Gan dispara una bola de cañón incendiaria hacia ${coordLabel(center.row, center.col)}.`);
  await playGurenGanCannonball(fx, center, playerId, () => {
    showGurenGanImpactIllumination(fx, plan);
    spawnGurenGanShockwave(fx, center);
    plan.effectiveCells.forEach(cell => resolveGurenGanImpactCell(playerId, cell, card));
  });
  await Promise.all(splashSchedule.map(cell => playGurenGanSplash(
    fx,
    center,
    cell,
    cell.delayMs,
    playerId,
    () => resolveGurenGanImpactCell(playerId, cell, card)
  )));
  renderAll();
  if (fx) window.setTimeout(() => fx.remove(), 2400);
  return { type: 'spell', card, spellId: card?.id || GUREN_GAN_CARD_ID };
}


async function playRemoteGurenGanFx(payload = {}) {
  const center = getGurenGanClampedCenter(payload.center?.row ?? 8, payload.center?.col ?? 4);
  const splashHits = Array.isArray(payload.splashHits) ? payload.splashHits : [];
  const plan = {
    center,
    effectiveCells: getGurenGanEffectiveCells(center.row, center.col),
    outerCells: getGurenGanOuterCells(center.row, center.col).map(cell => ({ ...cell, kind: 'outer' })),
    splashHits,
  };
  const fx = createGurenGanFx();
  await playGurenGanCannonball(fx, center, Number(payload.playerId || 1), () => {
    showGurenGanImpactIllumination(fx, plan);
    spawnGurenGanShockwave(fx, center);
  });
  await Promise.all(splashHits.map(cell => playGurenGanSplash(
    fx,
    center,
    cell,
    Number(cell.delayMs || 0),
    Number(payload.playerId || 1),
    null
  )));
  if (fx) window.setTimeout(() => fx.remove(), 2400);
  return true;
}

function chooseBestGurenGanCenter(playerId) {
  let best = { row: 8, col: 4, score: -Infinity, enemyHits: 0 };
  const enemyId = getEnemyPlayerId(playerId);
  const scoreEntities = (ownerId, effectiveSet, outerSet) => {
    const player = state.players?.[ownerId];
    if (!player) return { effective: 0, outer: 0 };
    const keys = [];
    for (const unit of player.units || []) {
      if (unit && unit.status !== 'restoring') keys.push(`${unit.row}:${unit.col}`);
    }
    for (const guardian of player.guardians || []) {
      if (guardian && guardian.active !== false && !guardian.destroying && Number(guardian.resistance ?? 0) > 0) keys.push(`${guardian.row}:${guardian.col}`);
    }
    if (player.caster && Number(player.caster.life ?? 0) > 0) keys.push(`${player.caster.row}:${player.caster.col}`);
    return {
      effective: keys.filter(key => effectiveSet.has(key)).length,
      outer: keys.filter(key => outerSet.has(key)).length,
    };
  };
  for (let row = 3; row <= 14; row += 1) {
    for (let col = 3; col <= 5; col += 1) {
      const effectiveSet = new Set(getGurenGanEffectiveCells(row, col).map(cell => `${cell.row}:${cell.col}`));
      const outerSet = new Set(getGurenGanOuterCells(row, col).map(cell => `${cell.row}:${cell.col}`));
      const enemy = scoreEntities(enemyId, effectiveSet, outerSet);
      const ally = scoreEntities(playerId, effectiveSet, outerSet);
      const score = enemy.effective * 9 + enemy.outer * 3 - ally.effective * 10 - ally.outer * 3;
      const enemyHits = enemy.effective + enemy.outer * (2 / 3);
      if (score > best.score || (score === best.score && enemyHits > best.enemyHits)) best = { row, col, score, enemyHits };
    }
  }
  return best;
}

function getCargaRealDirection(playerId) {
  return Number(playerId) === 1 ? -1 : 1;
}

function getCargaRealBandStartCol(selectedCol = 0) {
  return Math.max(0, Math.min(9 - CARGA_REAL_WIDTH_COLUMNS, Math.floor(Number(selectedCol) || 0) - 1));
}

function getCargaRealBandColumns(startCol = 0) {
  const normalized = Math.max(0, Math.min(9 - CARGA_REAL_WIDTH_COLUMNS, Math.floor(Number(startCol) || 0)));
  return Array.from({ length: CARGA_REAL_WIDTH_COLUMNS }, (_, index) => normalized + index);
}

function clearCargaRealBandPreview() {
  document.querySelectorAll('.cell.carga-real-band-preview').forEach(cell => cell.classList.remove('carga-real-band-preview'));
}

function previewCargaRealBandAtColumn(col) {
  clearCargaRealBandPreview();
  const columns = new Set(getCargaRealBandColumns(getCargaRealBandStartCol(col)));
  document.querySelectorAll('.cell[data-col]').forEach(cell => {
    if (columns.has(Number(cell.dataset.col))) cell.classList.add('carga-real-band-preview');
  });
}

function cancelCargaRealLocationTargeting(message = 'Selección de Carga Real cancelada.') {
  if (state.pendingPowerAction?.kind !== 'cargaRealLocation') return false;
  state.pendingPowerAction = null;
  clearCargaRealBandPreview();
  log(message);
  renderAll();
  return true;
}

function beginCargaRealLocationTargeting(playerId, cardId, originTab, originSlot) {
  const player = state.players?.[playerId];
  const card = CARD_LIBRARY[cardId || CARGA_REAL_CARD_ID];
  const tab = Math.max(0, Number(originTab) || 0);
  const slot = Math.max(0, Number(originSlot) || 0);
  if (!player || !card || player.handTabs?.[tab]?.[slot] !== card.id) return false;
  state.selectedMover = null;
  state.selectedTarget = null;
  state.pendingCard = null;
  state.pendingPlacement = null;
  state.pendingPowerAction = {
    kind: 'cargaRealLocation',
    stage: 'precast',
    playerId,
    cardId: card.id,
    originTab: tab,
    originSlot: slot,
  };
  log('Carga Real: selecciona una ubicación en arena. La columna elegida definirá una franja de 4 columnas. El costo se pagará al confirmar.');
  renderAll();
  return true;
}

function resolveCargaRealLocation(playerId, row, col) {
  const pending = state.pendingPowerAction;
  if (!pending || pending.kind !== 'cargaRealLocation' || Number(pending.playerId) !== Number(playerId)) return false;
  if (!isInside(row, col)) return false;
  const player = state.players?.[playerId];
  const card = CARD_LIBRARY[pending.cardId || CARGA_REAL_CARD_ID];
  const tab = Math.max(0, Number(pending.originTab) || 0);
  const slot = Math.max(0, Number(pending.originSlot) || 0);
  if (!player || !card || player.handTabs?.[tab]?.[slot] !== card.id) {
    state.pendingPowerAction = null;
    clearCargaRealBandPreview();
    log('Carga Real ya no está disponible en ese espacio del Spellbook.');
    renderAll();
    return false;
  }
  const bandStartCol = getCargaRealBandStartCol(col);
  state.pendingPowerAction = null;
  clearCargaRealBandPreview();
  state.selectedCardSlot = slot;
  state.pendingCard = {
    cardId: card.id,
    slotIndex: slot,
    tab,
    targetRow: row,
    targetCol: col,
    bandStartCol,
  };
  state.pendingPlacement = { row, col, key: 'arena', bandStartCol };
  log(`Carga Real cubrirá las columnas ${bandStartCol + 1} a ${bandStartCol + CARGA_REAL_WIDTH_COLUMNS}. Se paga el costo y comienza el kasteo.`);
  confirmCast();
  return true;
}

function getCargaRealTargets(bandStartCol) {
  const columns = new Set(getCargaRealBandColumns(bandStartCol));
  const targets = [];
  for (const targetPlayerId of [1, 2]) {
    for (const unit of state.players?.[targetPlayerId]?.units || []) {
      if (!unit || unit.status === 'restoring' || !columns.has(Number(unit.col))) continue;
      targets.push({ type: 'invocation', playerId: targetPlayerId, unitId: unit.id, row: Number(unit.row), col: Number(unit.col) });
    }
    const caster = state.players?.[targetPlayerId]?.caster;
    if (caster && Number(caster.life ?? 0) > 0 && columns.has(Number(caster.col))) {
      targets.push({ type: 'caster', playerId: targetPlayerId, row: Number(caster.row), col: Number(caster.col) });
    }
  }
  return targets;
}


function createCargaRealHorseLayout() {
  const pattern = [...CARGA_REAL_RANK_PATTERNS[Math.floor(Math.random() * CARGA_REAL_RANK_PATTERNS.length)]];
  if (Math.random() < 0.5) pattern.reverse();
  const layouts = [];
  let depthCursor = 0.04 + Math.random() * 0.22;
  pattern.forEach((count, rankIndex) => {
    if (rankIndex > 0) depthCursor += 0.52 + Math.random() * 0.92;
    const slotWidth = CARGA_REAL_WIDTH_COLUMNS / count;
    const rankShift = (Math.random() * 0.34) - 0.17;
    for (let index = 0; index < count; index += 1) {
      const horizontalJitter = (Math.random() * 0.38) - 0.19;
      const xWithinBand = Math.max(0.08, Math.min(CARGA_REAL_WIDTH_COLUMNS - 0.08,
        ((index + 0.5) * slotWidth) - 0.5 + rankShift + horizontalJitter));
      const individualDepth = depthCursor + ((Math.random() * 0.7) - 0.35);
      const appearAt = Math.max(0, Math.min(0.24, individualDepth / 23 + Math.random() * 0.025));
      layouts.push({
        key: `rank-${rankIndex}-horse-${index}`,
        rankIndex,
        xWithinBand,
        depthRows: Math.max(0, individualDepth),
        appearAt,
        travelSpan: 0.77 + Math.random() * 0.17,
        speed: 0.84 + Math.random() * 0.34,
        scale: 0.72 + Math.random() * 0.19,
        hue: -8 + Math.random() * 24,
        swayPhase: Math.random() * Math.PI * 2,
        swayAmount: 0.025 + Math.random() * 0.07,
        seed: Math.floor(Math.random() * 10000),
      });
    }
  });
  return layouts.slice(0, CARGA_REAL_TOTAL_HORSES);
}

function getCargaRealBoardPoint(rowFloat, colFloat) {
  const boardRect = els.boardContent.getBoundingClientRect();
  const useAlly = rowFloat >= 9;
  const gridEl = useAlly ? els.allyGrid : els.enemyGrid;
  const gridRect = gridEl.getBoundingClientRect();
  const localRow = useAlly ? rowFloat - 9 : rowFloat;
  return {
    x: ((gridRect.left - boardRect.left) + ((colFloat + 0.5) / 9) * gridRect.width) / boardRect.width * 100,
    y: ((gridRect.top - boardRect.top) + ((localRow + 0.5) / 9) * gridRect.height) / boardRect.height * 100,
  };
}

function spawnCargaRealParticle(fx, x, y, variant = 'dust', direction = 1, sizeFactor = 1) {
  if (!fx?.particleLayer) return;
  const particle = document.createElement('span');
  particle.className = `carga-real-particle carga-real-particle-${variant}`;
  const lateralSpread = variant === 'ember' ? 2.2 : 3.6;
  const forwardSpread = variant === 'ember' ? 2.3 : 3.9;
  const driftX = (Math.random() * lateralSpread * 2 - lateralSpread) * sizeFactor;
  const driftY = (0.45 + Math.random() * forwardSpread) * sizeFactor * (direction < 0 ? -1 : 1);
  const duration = CARGA_REAL_PARTICLE_MIN_LIFETIME_MS
    + Math.random() * (CARGA_REAL_PARTICLE_MAX_LIFETIME_MS - CARGA_REAL_PARTICLE_MIN_LIFETIME_MS);
  const opacity = variant === 'ember' ? 0.62 + Math.random() * 0.38 : 0.34 + Math.random() * 0.52;
  const widthRatio = variant === 'ember' ? 0.75 + Math.random() * 0.6 : 0.9 + Math.random() * 1.4;
  const heightRatio = variant === 'ember' ? 0.75 + Math.random() * 0.6 : 0.65 + Math.random() * 1.6;
  particle.style.left = `${x}%`;
  particle.style.top = `${y}%`;
  particle.style.setProperty('--drift-x', `${driftX}%`);
  particle.style.setProperty('--drift-y', `${driftY}%`);
  particle.style.setProperty('--particle-scale', String((0.58 + Math.random() * 1.45) * sizeFactor));
  particle.style.setProperty('--particle-width-ratio', String(widthRatio));
  particle.style.setProperty('--particle-height-ratio', String(heightRatio));
  particle.style.setProperty('--particle-opacity', String(opacity));
  particle.style.setProperty('--particle-rotation', `${-75 + Math.random() * 150}deg`);
  particle.style.setProperty('--particle-delay', `${Math.random() * 90}ms`);
  particle.style.setProperty('--particle-duration', `${Math.round(duration)}ms`);
  particle.style.setProperty('--particle-blur', `${variant === 'ember' ? Math.random() * 0.45 : 0.7 + Math.random() * 1.9}px`);
  fx.particleLayer.appendChild(particle);
  particle.addEventListener('animationend', () => particle.remove(), { once: true });
}

function spawnCargaRealBurstAtRow(fx, row, bandStartCol, direction) {
  const columns = getCargaRealBandColumns(bandStartCol);
  const dustCount = 7 + Math.floor(Math.random() * 9);
  const emberCount = 2 + Math.floor(Math.random() * 7);
  for (let index = 0; index < dustCount; index += 1) {
    const col = columns[Math.floor(Math.random() * columns.length)] + (Math.random() * 0.76 - 0.38);
    const point = getCargaRealBoardPoint(row + (Math.random() * 0.5 - 0.25), col);
    spawnCargaRealParticle(fx, point.x, point.y, 'dust', direction, 0.72 + Math.random() * 0.82);
  }
  for (let index = 0; index < emberCount; index += 1) {
    const col = columns[Math.floor(Math.random() * columns.length)] + (Math.random() * 0.62 - 0.31);
    const point = getCargaRealBoardPoint(row + (Math.random() * 0.42 - 0.21), col);
    spawnCargaRealParticle(fx, point.x, point.y, 'ember', direction, 0.56 + Math.random() * 0.72);
  }
}

function createCargaRealFx(playerId, bandStartCol) {
  if (!els.boardContent) return null;
  const fx = document.createElement('div');
  fx.className = `carga-real-charge-fx carga-real-direction-${Number(playerId) === 1 ? 'up' : 'down'}`;
  fx.innerHTML = '<div class="carga-real-particle-layer"></div><div class="carga-real-horse-layer"></div>';
  fx.direction = Number(playerId) === 1 ? -1 : 1;
  fx.startRow = Number(playerId) === 1 ? 17 : 0;
  fx.bandStartCol = bandStartCol;
  fx.startTime = performance.now();
  fx.horseLayer = fx.querySelector('.carga-real-horse-layer');
  fx.particleLayer = fx.querySelector('.carga-real-particle-layer');
  fx.horses = createCargaRealHorseLayout().map((layout, index) => {
    const horseEl = document.createElement('span');
    horseEl.className = 'carga-real-horse';
    horseEl.style.setProperty('--horse-index', String(index));
    horseEl.style.setProperty('--horse-hue', `${layout.hue}deg`);
    const body = document.createElement('span');
    body.className = 'carga-real-horse-body';
    const img = document.createElement('img');
    img.className = 'carga-real-horse-img';
    img.alt = '';
    img.draggable = false;
    img.src = CARGA_REAL_HORSE_FRAMES[index % CARGA_REAL_HORSE_FRAMES.length];
    body.appendChild(img);
    horseEl.appendChild(body);
    fx.horseLayer.appendChild(horseEl);
    return { ...layout, el: horseEl, body, img };
  });
  els.boardContent.appendChild(fx);
  return fx;
}

function updateCargaRealFx(fx, progress = 0, nowMs = performance.now()) {
  if (!fx) return [];
  const visible = [];
  fx.horses.forEach(horse => {
    const travel = Math.max(0, Math.min(1.05, (progress - horse.appearAt) / Math.max(0.42, horse.travelSpan)));
    if (travel <= 0 || travel >= 1.04) {
      horse.el.style.opacity = '0';
      return;
    }
    const travelledRows = (travel * 18.8) - 1.05 - horse.depthRows;
    const rowFloat = fx.startRow + fx.direction * travelledRows;
    if (rowFloat < -1.2 || rowFloat > 18.2) {
      horse.el.style.opacity = '0';
      return;
    }
    const liveRow = Math.max(0, Math.min(17, rowFloat));
    const sway = Math.sin((nowMs / 175) * horse.speed + horse.swayPhase) * horse.swayAmount;
    const colFloat = fx.bandStartCol + horse.xWithinBand + sway;
    const point = getCargaRealBoardPoint(liveRow, colFloat);
    const cellSize = getBoardCellSizePercent(Math.max(0, Math.min(17, Math.round(liveRow))));
    const width = cellSize.width * horse.scale * 1.5;
    const height = cellSize.height * horse.scale * 1.52 * 1.5;
    const enter = Math.max(0, Math.min(1, travel / 0.16));
    const exit = Math.max(0, Math.min(1, (1 - travel) / 0.12));
    const opacity = Math.min(enter, exit) * (0.74 + (((horse.seed % 5) + 1) * 0.038));
    const frameIndex = Math.floor((nowMs / (84 / horse.speed)) + horse.seed) % CARGA_REAL_HORSE_FRAMES.length;
    if (horse.img) horse.img.src = CARGA_REAL_HORSE_FRAMES[frameIndex];
    horse.el.style.left = `${point.x}%`;
    horse.el.style.top = `${point.y}%`;
    horse.el.style.width = `${width}%`;
    horse.el.style.height = `${height}%`;
    horse.el.style.opacity = `${opacity}`;
    horse.el.style.setProperty('--horse-scale', String(0.96 + Math.sin((nowMs / 210) + horse.seed) * 0.03));
    horse.el.style.setProperty('--horse-glow', String(0.72 + Math.sin((nowMs / 200) + horse.seed * 0.6) * 0.18));
    visible.push({ x: point.x, y: point.y, row: liveRow, opacity, horse });
  });
  if (visible.length && (!fx.nextTrailAt || nowMs >= fx.nextTrailAt)) {
    const burstCount = 1 + Math.floor(Math.random() * 3);
    for (let index = 0; index < burstCount; index += 1) {
      const sample = visible[Math.floor(Math.random() * visible.length)];
      if (!sample) continue;
      spawnCargaRealParticle(
        fx,
        sample.x + (Math.random() * 1.35 - 0.675),
        sample.y + (Math.random() * 0.72 - 0.36),
        'dust',
        fx.direction,
        0.62 + Math.random() * 0.78
      );
      if (Math.random() < 0.58) {
        spawnCargaRealParticle(
          fx,
          sample.x + (Math.random() * 0.9 - 0.45),
          sample.y + (Math.random() * 0.5 - 0.25),
          'ember',
          fx.direction,
          0.48 + Math.random() * 0.58
        );
      }
    }
    fx.nextTrailAt = nowMs + 26 + Math.random() * 82;
  }
  return visible;
}

function nextAnimationFramePromise() {
  return new Promise(resolve => requestAnimationFrame(resolve));
}

function preserveCargaRealParticleLayer(fx) {
  const layer = fx?.particleLayer;
  if (!layer || !els.boardContent) return;
  layer.classList.add('carga-real-particle-layer-lingering');
  els.boardContent.appendChild(layer);
  fx.particleLayer = null;
  window.setTimeout(() => layer.remove(), CARGA_REAL_PARTICLE_LAYER_CLEANUP_MS);
}

function getCargaRealCellBlockerKind(row, col) {
  if (!isInside(row, col)) return 'edge';
  for (const playerId of [1, 2]) {
    const guardians = state.players?.[playerId]?.guardians || [];
    if (guardians.some(guardian => guardian && guardian.active !== false && !guardian.destroying && Number(guardian.row) === Number(row) && Number(guardian.col) === Number(col))) {
      return 'structure';
    }
  }
  for (const playerId of [1, 2]) {
    const player = state.players?.[playerId];
    const caster = player?.caster;
    if (caster && Number(caster.life ?? 0) > 0 && Number(caster.row) === Number(row) && Number(caster.col) === Number(col)) return 'piece';
    if ((player?.units || []).some(unit => unit && unit.status !== 'restoring' && Number(unit.row) === Number(row) && Number(unit.col) === Number(col))) return 'piece';
  }
  if (hasSpawnMarkerAtForPlayer(row, col, null)) return 'spawn';
  return null;
}

function getCargaRealPushDestination(row, col, direction) {
  const first = { row: Number(row) + direction, col: Number(col) };
  if (!isInside(first.row, first.col)) return null;
  const firstBlocker = getCargaRealCellBlockerKind(first.row, first.col);
  const second = { row: Number(row) + (direction * CARGA_REAL_PUSH_CELLS), col: Number(col) };

  if (!firstBlocker) {
    if (isInside(second.row, second.col) && !getCargaRealCellBlockerKind(second.row, second.col)) return second;
    return first;
  }

  // La carga puede atravesar una invocación o un Kaster, pero nunca una
  // estructura, un nexo/respawn reservado ni el límite de la arena.
  if (firstBlocker === 'piece' && isInside(second.row, second.col) && !getCargaRealCellBlockerKind(second.row, second.col)) {
    return second;
  }
  return null;
}

function pushCargaRealTargetOnImpact(snapshot, direction) {
  if (!snapshot) return 0;
  const target = snapshot.type === 'caster'
    ? state.players?.[snapshot.playerId]?.caster
    : getUnitById(snapshot.playerId, snapshot.unitId);
  if (!target || (snapshot.type !== 'caster' && target.status === 'restoring')) return 0;
  if (snapshot.type === 'caster' && Number(target.life ?? 0) <= 0) return 0;
  const startRow = Number(target.row);
  const destination = getCargaRealPushDestination(startRow, Number(target.col), direction);
  if (!destination) return 0;

  if (snapshot.type === 'invocation') {
    clearUnitEngagement(snapshot.playerId, target.id);
    target.movesLeft = 0;
  }
  target.row = destination.row;
  target.col = destination.col;
  const moved = Math.abs(destination.row - startRow);
  if (moved > 0) showFloatingTextAt(destination.row, destination.col, `EMPUJAR ${moved}`, 'floating-combat debuff');
  return moved;
}

async function resolveCargaRealCast(playerId, item, card = CARD_LIBRARY[CARGA_REAL_CARD_ID]) {
  const bandStartCol = Math.max(0, Math.min(9 - CARGA_REAL_WIDTH_COLUMNS, Number(item?.bandStartCol ?? getCargaRealBandStartCol(item?.col ?? 4))));
  const direction = getCargaRealDirection(playerId);
  emitOnlineVisualEvent('carga-real', { playerId: Number(playerId), bandStartCol: Number(bandStartCol) });
  const rows = direction < 0
    ? Array.from({ length: 18 }, (_, index) => 17 - index)
    : Array.from({ length: 18 }, (_, index) => index);
  const targets = getCargaRealTargets(bandStartCol);
  const targetsByRow = new Map();
  targets.forEach(target => {
    if (!targetsByRow.has(target.row)) targetsByRow.set(target.row, []);
    targetsByRow.get(target.row).push(target);
  });

  const previousLock = state.actionExecutionLock;
  const previousReason = state.actionExecutionLockReason;
  state.actionExecutionLock = true;
  state.actionExecutionLockReason = 'carga-real';
  clearCombatMenus();
  const fx = createCargaRealFx(playerId, bandStartCol);
  try {
    log(`Carga Real atraviesa las columnas ${bandStartCol + 1} a ${bandStartCol + CARGA_REAL_WIDTH_COLUMNS} con una carga de caballería irregular.`);
    const startTime = performance.now();
    let nextRowIndex = 0;
    while (true) {
      const now = performance.now();
      const progress = Math.max(0, Math.min(1, (now - startTime) / CARGA_REAL_TRAVEL_DURATION_MS));
      updateCargaRealFx(fx, progress, now);
      while (nextRowIndex < rows.length && progress >= ((nextRowIndex + CARGA_REAL_ROW_HIT_LEAD) / rows.length)) {
        const row = rows[nextRowIndex];
        spawnCargaRealBurstAtRow(fx, row, bandStartCol, direction);
        const rowTargets = targetsByRow.get(row) || [];
        let movedOnRow = false;
        for (const snapshot of rowTargets) {
          if (snapshot.type === 'caster') {
            const caster = state.players?.[snapshot.playerId]?.caster;
            if (!caster || Number(caster.life ?? 0) <= 0) continue;
            showFloatingTextAt(caster.row, caster.col, 'CARGA REAL', 'floating-combat critical');
            applyDamageToCaster(snapshot.playerId, CARGA_REAL_DAMAGE, 'Carga Real · daño directo', {
              sourcePlayerId: playerId,
              sourceCardId: card?.id || CARGA_REAL_CARD_ID,
            });
            const liveCaster = state.players?.[snapshot.playerId]?.caster;
            if (liveCaster && Number(liveCaster.life ?? 0) > 0) {
              movedOnRow = pushCargaRealTargetOnImpact(snapshot, direction) > 0 || movedOnRow;
            }
            continue;
          }

          const unit = getUnitById(snapshot.playerId, snapshot.unitId);
          if (!unit || unit.status === 'restoring') continue;
          showFloatingTextAt(unit.row, unit.col, 'CARGA REAL', 'floating-combat critical');
          damageInvocationUnit(snapshot.playerId, unit, CARGA_REAL_DAMAGE, 'Carga Real · daño directo', {
            card,
            sourceCardId: card?.id || CARGA_REAL_CARD_ID,
            sourcePlayerId: playerId,
            damageNature: 'direct',
            effectNature: 'physical',
            ignoreArmor: true,
          });
          const liveUnit = getUnitById(snapshot.playerId, snapshot.unitId);
          if (liveUnit && liveUnit.status !== 'restoring') {
            applyStunToUnit(snapshot.playerId, liveUnit, CARGA_REAL_STUN_PHASES, {
              sourceType: 'spell',
              sourceCardId: card?.id || CARGA_REAL_CARD_ID,
              sourcePlayerId: playerId,
            });
            movedOnRow = pushCargaRealTargetOnImpact(snapshot, direction) > 0 || movedOnRow;
          }
        }
        if (rowTargets.length) {
          if (movedOnRow) refreshGuardianAuraState({ announceNew: true });
          renderAll();
        }
        nextRowIndex += 1;
      }
      if (progress >= 1) break;
      await nextAnimationFramePromise();
    }
    updateCargaRealFx(fx, 1, performance.now());
    await sleep(130);
    preserveCargaRealParticleLayer(fx);
  } finally {
    if (fx?.particleLayer) preserveCargaRealParticleLayer(fx);
    fx?.remove();
    state.actionExecutionLock = previousLock;
    state.actionExecutionLockReason = previousReason;
    renderAll();
  }
  return { type: 'spell', card, spellId: card?.id || CARGA_REAL_CARD_ID };
}


async function playRemoteCargaRealFx(payload = {}) {
  const playerId = Number(payload.playerId || 1);
  const bandStartCol = Math.max(0, Math.min(9 - CARGA_REAL_WIDTH_COLUMNS, Number(payload.bandStartCol || 0)));
  const direction = getCargaRealDirection(playerId);
  const rows = direction < 0
    ? Array.from({ length: 18 }, (_, index) => 17 - index)
    : Array.from({ length: 18 }, (_, index) => index);
  const fx = createCargaRealFx(playerId, bandStartCol);
  if (!fx) return false;
  try {
    const startTime = performance.now();
    let nextRowIndex = 0;
    while (true) {
      const now = performance.now();
      const progress = Math.max(0, Math.min(1, (now - startTime) / CARGA_REAL_TRAVEL_DURATION_MS));
      updateCargaRealFx(fx, progress, now);
      while (nextRowIndex < rows.length && progress >= ((nextRowIndex + CARGA_REAL_ROW_HIT_LEAD) / rows.length)) {
        spawnCargaRealBurstAtRow(fx, rows[nextRowIndex], bandStartCol, direction);
        nextRowIndex += 1;
      }
      if (progress >= 1) break;
      await nextAnimationFramePromise();
    }
    updateCargaRealFx(fx, 1, performance.now());
    await sleep(130);
    preserveCargaRealParticleLayer(fx);
    return true;
  } finally {
    if (fx?.particleLayer) preserveCargaRealParticleLayer(fx);
    fx?.remove();
  }
}

const SPELLBOOK_COOLDOWN_ICON_ASSET = 'assets/icons/factor-enfriamiento-spellbook.svg';

function getInvocationBaseSpellbookCooldown(card) {
  if (!card || getCardTypeId(card) !== 'invocation') return 0;
  const cost = Math.max(0, Math.floor(Number(getCardTotalCost(card)) || 0));
  // Estasis base inversa al costo: 0→5, 1→4, 2→3, 3→2, 4→1, 5+→0.
  // Esto hace que las invocaciones muy baratas sean más dinámicas al entrar,
  // pero paguen esa ventaja permaneciendo más tiempo en Estasis al regresar.
  return Math.max(0, 5 - Math.min(cost, 5));
}

function getAbilitySpellbookCooldownContribution(entry) {
  const normalized = normalizeLearnedAbilityEntry(entry);
  if (!normalized) return 0;
  // La contribución es por ID de habilidad, no por cantidad de cartas que
  // alguna vez intentaron enseñar esa habilidad a la misma copia.
  const canonical = getAbilityProfile(normalized.id)?.spellbookCooldown;
  return Math.max(0, Number(canonical ?? normalized.spellbookCooldown ?? 0));
}

function getLearnedAbilitiesSpellbookCooldownTotal(entries = []) {
  const seen = new Set();
  return (Array.isArray(entries) ? entries : []).reduce((sum, entry) => {
    const normalized = normalizeLearnedAbilityEntry(entry);
    if (!normalized || seen.has(normalized.id)) return sum;
    seen.add(normalized.id);
    return sum + getAbilitySpellbookCooldownContribution(normalized);
  }, 0);
}

function getUnitSpellbookCooldownBreakdown(unit, card = CARD_LIBRARY[unit?.cardId]) {
  migrateLegacyAbilityCardEntries(unit);
  const base = getInvocationBaseSpellbookCooldown(card);
  const learned = getLearnedAbilitiesSpellbookCooldownTotal(getUnitLearnedAbilityEntries(unit));
  return { base, learned, total: base + learned };
}

function ensureSpellbookCardStateMap(playerId) {
  const player = state.players?.[playerId];
  if (!player) return null;
  player.spellbookCardStates = player.spellbookCardStates && typeof player.spellbookCardStates === 'object' ? player.spellbookCardStates : {};
  return player.spellbookCardStates;
}

function ensureSpellbookCardInstanceMap(playerId) {
  const player = state.players?.[playerId];
  if (!player) return null;
  player.spellbookCardInstances = player.spellbookCardInstances && typeof player.spellbookCardInstances === 'object'
    ? player.spellbookCardInstances
    : {};
  return player.spellbookCardInstances;
}

function createSpellbookCardInstanceId(playerId, cardId = '') {
  return `sbcopy_p${Number(playerId) || 0}_${String(cardId || 'card')}_${Date.now()}_${Math.random().toString(16).slice(2)}`;
}

function getSpellbookSlotKey(tab, slot) {
  return `${Math.max(0, Number(tab) || 0)}:${Math.max(0, Number(slot) || 0)}`;
}

function getSpellbookCardInstanceId(playerId, tab, slot, cardId = '', options = {}) {
  const map = ensureSpellbookCardInstanceMap(playerId);
  const player = state.players?.[playerId];
  if (!map || !player) return '';
  const slotKey = getSpellbookSlotKey(tab, slot);
  const liveCardId = cardId || player.handTabs?.[Number(tab)]?.[Number(slot)] || '';
  const current = map[slotKey];
  if (current && typeof current === 'object') {
    if (!liveCardId || !current.cardId || String(current.cardId) === String(liveCardId)) return String(current.instanceId || '');
  } else if (typeof current === 'string' && current) {
    return current;
  }
  if (options.create === false || !liveCardId) return '';
  const instanceId = createSpellbookCardInstanceId(playerId, liveCardId);
  map[slotKey] = { instanceId, cardId: liveCardId };
  return instanceId;
}

function setSpellbookCardInstanceId(playerId, tab, slot, cardId, instanceId = '') {
  const map = ensureSpellbookCardInstanceMap(playerId);
  if (!map) return '';
  const slotKey = getSpellbookSlotKey(tab, slot);
  const resolved = String(instanceId || createSpellbookCardInstanceId(playerId, cardId));
  map[slotKey] = { instanceId: resolved, cardId: cardId || '' };
  return resolved;
}

function takeSpellbookCardInstanceId(playerId, tab, slot, cardId = '') {
  const map = ensureSpellbookCardInstanceMap(playerId);
  if (!map) return '';
  const slotKey = getSpellbookSlotKey(tab, slot);
  const instanceId = getSpellbookCardInstanceId(playerId, tab, slot, cardId, { create: true });
  delete map[slotKey];
  return instanceId;
}

function getSpellbookCardStateKey(instanceId = '') {
  return instanceId ? `copy:${instanceId}` : '';
}

function getSpellbookCardPersistentState(playerId, tab, slot, cardId = '') {
  const map = ensureSpellbookCardStateMap(playerId);
  if (!map) return null;
  const instanceId = getSpellbookCardInstanceId(playerId, tab, slot, cardId, { create: true });
  const copyKey = getSpellbookCardStateKey(instanceId);
  let entry = copyKey ? map[copyKey] : null;
  const legacyKey = getSpellbookSlotKey(tab, slot);
  if (!entry && map[legacyKey]) {
    entry = map[legacyKey];
    if (copyKey) {
      map[copyKey] = { ...entry, instanceId };
      delete map[legacyKey];
    }
  }
  if (!entry || (cardId && entry.cardId && String(entry.cardId) !== String(cardId))) return null;
  return {
    ...entry,
    instanceId: entry.instanceId || instanceId,
    learnedAbilities: normalizeLearnedAbilityEntries(entry.learnedAbilities),
    realtimeCombatMode: String(entry.realtimeCombatMode || ''),
    powerAutomationMode: ['auto', 'manual'].includes(String(entry.powerAutomationMode || ''))
      ? String(entry.powerAutomationMode)
      : '',
  };
}

function takeSpellbookCardPersistentState(playerId, tab, slot, cardId = '') {
  const map = ensureSpellbookCardStateMap(playerId);
  if (!map) return null;
  const instanceId = getSpellbookCardInstanceId(playerId, tab, slot, cardId, { create: true });
  const entry = getSpellbookCardPersistentState(playerId, tab, slot, cardId);
  const copyKey = getSpellbookCardStateKey(instanceId);
  if (copyKey) delete map[copyKey];
  delete map[getSpellbookSlotKey(tab, slot)];
  takeSpellbookCardInstanceId(playerId, tab, slot, cardId);
  return {
    ...(entry || {}),
    cardId: entry?.cardId || cardId || '',
    instanceId,
    learnedAbilities: normalizeLearnedAbilityEntries(entry?.learnedAbilities),
    realtimeCombatMode: String(entry?.realtimeCombatMode || ''),
    powerAutomationMode: ['auto', 'manual'].includes(String(entry?.powerAutomationMode || ''))
      ? String(entry.powerAutomationMode)
      : '',
  };
}

function setSpellbookCardPersistentState(playerId, tab, slot, cardId, persistentState = null) {
  const map = ensureSpellbookCardStateMap(playerId);
  if (!map) return;
  const instanceId = setSpellbookCardInstanceId(playerId, tab, slot, cardId, persistentState?.instanceId || '');
  const copyKey = getSpellbookCardStateKey(instanceId);
  const learnedAbilities = normalizeLearnedAbilityEntries(persistentState?.learnedAbilities);
  const realtimeCombatMode = String(persistentState?.realtimeCombatMode || '');
  const powerAutomationMode = ['auto', 'manual'].includes(String(persistentState?.powerAutomationMode || ''))
    ? String(persistentState.powerAutomationMode)
    : '';
  delete map[getSpellbookSlotKey(tab, slot)];
  if (!learnedAbilities.length && !realtimeCombatMode && !powerAutomationMode) {
    if (copyKey) delete map[copyKey];
    return;
  }
  map[copyKey] = { cardId, instanceId, learnedAbilities, realtimeCombatMode, powerAutomationMode };
}

function buildInvocationPersistentStateFromUnit(unit) {
  return {
    cardId: unit?.cardId || '',
    instanceId: unit?.spellbookInstanceId || '',
    learnedAbilities: getUnitLearnedAbilityEntries(unit),
    realtimeCombatMode: String(unit?.realtimeCombatMode || ''),
    powerAutomationMode: ['auto', 'manual'].includes(String(unit?.powerAutomationMode || ''))
      ? String(unit.powerAutomationMode)
      : '',
  };
}

function getSpellbookCooldownKey(tab, slot, playerId = null, cardId = '') {
  if (playerId != null) {
    const instanceId = getSpellbookCardInstanceId(playerId, tab, slot, cardId, { create: true });
    if (instanceId) return `copy:${instanceId}`;
  }
  return getSpellbookSlotKey(tab, slot);
}

function getSpellbookUseCooldown(playerId, tab, slot) {
  const player = state.players?.[playerId];
  const map = player?.spellbookUseCooldowns || {};
  const cardId = player?.handTabs?.[Number(tab)]?.[Number(slot)] || '';
  const key = getSpellbookCooldownKey(tab, slot, playerId, cardId);
  let entry = map[key];
  const legacyKey = getSpellbookSlotKey(tab, slot);
  if (!entry && key !== legacyKey && map[legacyKey]) {
    entry = map[legacyKey];
    map[key] = entry;
    delete map[legacyKey];
  }
  return Math.max(0, Number(entry?.remaining ?? entry ?? 0));
}

function setSpellbookUseCooldown(playerId, tab, slot, cardId, phases = DESPLIEGUE_ANTICIPADO_USE_COOLDOWN_PER_LINK, meta = {}) {
  const player = state.players?.[playerId];
  if (!player) return;
  player.spellbookUseCooldowns = player.spellbookUseCooldowns && typeof player.spellbookUseCooldowns === 'object'
    ? player.spellbookUseCooldowns
    : {};
  const remaining = Math.max(0, Math.floor(Number(phases) || 0));
  const instanceId = setSpellbookCardInstanceId(playerId, tab, slot, cardId, meta.instanceId || '');
  const key = `copy:${instanceId}`;
  delete player.spellbookUseCooldowns[getSpellbookSlotKey(tab, slot)];
  if (!remaining) delete player.spellbookUseCooldowns[key];
  else player.spellbookUseCooldowns[key] = {
    cardId,
    instanceId,
    remaining,
    sourceSpellId: meta.sourceSpellId || '',
    sourceType: meta.sourceType || 'spellbookCooldown',
    breakdown: meta.breakdown || null,
  };
}

function clearSpellbookUseCooldown(playerId, tab, slot) {
  const player = state.players?.[playerId];
  const map = player?.spellbookUseCooldowns;
  if (!map || typeof map !== 'object') return;
  const cardId = player?.handTabs?.[Number(tab)]?.[Number(slot)] || '';
  const instanceId = getSpellbookCardInstanceId(playerId, tab, slot, cardId, { create: false });
  if (instanceId) delete map[`copy:${instanceId}`];
  delete map[getSpellbookSlotKey(tab, slot)];
}

function advanceSpellbookUseCooldownsOnePhaseStep() {
  for (const playerId of [1, 2]) {
    const player = state.players?.[playerId];
    const map = player?.spellbookUseCooldowns;
    if (!map || typeof map !== 'object') continue;
    Object.keys(map).forEach(key => {
      const entry = map[key];
      const remaining = Math.max(0, Number(entry?.remaining ?? entry ?? 0) - 1);
      if (remaining <= 0) delete map[key];
      else if (entry && typeof entry === 'object') entry.remaining = remaining;
      else map[key] = { remaining, cardId: '', sourceSpellId: '', sourceType: 'spellbookCooldown' };
    });
  }
}

function getActiveDespliegueAnticipadoLinks(playerId = null) {
  const links = Array.isArray(state.activeSpellLinks) ? state.activeSpellLinks : [];
  return links.filter(link => {
    if (!link || link.type !== DESPLIEGUE_ANTICIPADO_POWER_ID) return false;
    if (playerId != null && Number(link.playerId) !== Number(playerId)) return false;
    const target = getUnitById(Number(link.playerId), link.targetUnitId);
    return Boolean(target && target.status !== 'restoring' && unitHasCardQuality(target, 'caudillo'));
  });
}

function isDespliegueAnticipadoActiveForPlayer(playerId) {
  return getActiveDespliegueAnticipadoLinks(playerId).length > 0;
}

function getDespliegueAnticipadoActiveStacks(playerId) {
  return Math.min(DESPLIEGUE_ANTICIPADO_MAX_ACTIVE_LINKS, getActiveDespliegueAnticipadoLinks(playerId).length);
}

function getDespliegueAnticipadoCostReduction(card, playerId = null) {
  const ownerId = Number(playerId || state.activePlayer || LOCAL_PLAYER_ID);
  if (!card || getCardTypeId(card) !== 'invocation') return 0;
  if (!unitHasCardQuality(card, 'warrior')) return 0;
  return getDespliegueAnticipadoActiveStacks(ownerId) * DESPLIEGUE_ANTICIPADO_COST_REDUCTION_PER_LINK;
}

function getDespliegueAnticipadoReturnCooldown(playerId, card) {
  if (!card || getCardTypeId(card) !== 'invocation' || !unitHasCardQuality(card, 'warrior')) return 0;
  return getDespliegueAnticipadoActiveStacks(playerId) * DESPLIEGUE_ANTICIPADO_USE_COOLDOWN_PER_LINK;
}

function reduceCostObjectByAmount(rawCost, reduction) {
  const result = {};
  Object.entries(rawCost || {}).forEach(([id, amount]) => {
    const value = Math.max(0, Number(amount) || 0);
    if (value) result[id] = value;
  });
  let remaining = Math.max(0, Number(reduction) || 0);
  const order = ['random', ...Object.keys(result).filter(id => id !== 'random').sort((a, b) => Number(result[b]) - Number(result[a]))];
  order.forEach(id => {
    if (!remaining || !result[id]) return;
    const removed = Math.min(remaining, result[id]);
    result[id] -= removed;
    remaining -= removed;
    if (result[id] <= 0) delete result[id];
  });
  return result;
}

function getTacticaGuerraTargetElementId(playerId, unit) {
  const targetCard = CARD_LIBRARY[unit?.cardId] || null;
  return targetCard ? getEffectiveCardElementId(targetCard, playerId) : '';
}

function getTacticaGuerraResourceCounts(playerId) {
  return (state.players?.[playerId]?.resources || []).reduce((counts, resource) => {
    if (resource?.id) counts[resource.id] = (counts[resource.id] || 0) + 1;
    return counts;
  }, {});
}

function getTacticaGuerraSelectionCostMap(playerId, unitIds = []) {
  const cost = {};
  (Array.isArray(unitIds) ? unitIds : []).forEach(unitId => {
    const unit = getUnitById(playerId, unitId);
    const elementId = getTacticaGuerraTargetElementId(playerId, unit);
    if (elementId) cost[elementId] = (cost[elementId] || 0) + 1;
  });
  return cost;
}

function canPayTacticaGuerraCostMap(playerId, costMap = {}) {
  return canPayCost(state.players?.[playerId]?.resources || [], costMap, 'agua');
}

function canPayTacticaGuerraTargetCost(playerId, unit) {
  const elementId = getTacticaGuerraTargetElementId(playerId, unit);
  if (!elementId) return false;
  return Number(getTacticaGuerraResourceCounts(playerId)[elementId] || 0) > 0;
}

function isTacticaGuerraQuickMode() {
  return currentPhase().id !== 'casting';
}

function getEligibleTacticaGuerraTargets(playerId, options = {}) {
  const quickOnly = options.quickOnly === true;
  const requirePayable = options.requirePayable !== false;
  return (state.players?.[playerId]?.units || []).filter(unit => {
    if (!unit || unit.status === 'restoring' || unit.restoreAnimating || Number(unit.hp ?? 0) <= 0) return false;
    if (quickOnly && !isUnitInOwnSide(playerId, unit)) return false;
    if (requirePayable && !canPayTacticaGuerraTargetCost(playerId, unit)) return false;
    return true;
  });
}

function getTacticaGuerraCastAvailability(playerId) {
  const quickOnly = isTacticaGuerraQuickMode();
  const activeTargets = getEligibleTacticaGuerraTargets(playerId, { quickOnly, requirePayable: false });
  const payableTargets = getEligibleTacticaGuerraTargets(playerId, { quickOnly, requirePayable: true });
  if (!activeTargets.length) {
    return {
      available: false,
      message: quickOnly
        ? 'Defensa rápida requiere al menos una invocación aliada activa en tu lado de la arena.'
        : 'Táctica de guerra requiere al menos una invocación aliada activa en la arena.',
      targets: [],
      quickOnly,
    };
  }
  if (!payableTargets.length) {
    return {
      available: false,
      message: 'No tienes un elemento compatible con el dominio de ninguna invocación aliada activa.',
      targets: [],
      quickOnly,
    };
  }
  return { available: true, message: '', targets: payableTargets, allTargets: activeTargets, quickOnly };
}

let tacticaGuerraCursorTrackingBound = false;

function closeTacticaGuerraSelectionModal() {
  document.getElementById('tacticaGuerraSelectionOverlay')?.remove();
}

function removeTacticaGuerraNexusCursor() {
  document.getElementById('tacticaGuerraNexusCursor')?.remove();
}

function handleTacticaGuerraCursorMove(event) {
  const cursor = document.getElementById('tacticaGuerraNexusCursor');
  if (!cursor) return;
  cursor.style.left = `${event.clientX}px`;
  cursor.style.top = `${event.clientY}px`;
}

function ensureTacticaGuerraCursorTracking() {
  if (tacticaGuerraCursorTrackingBound) return;
  tacticaGuerraCursorTrackingBound = true;
  document.addEventListener('pointermove', handleTacticaGuerraCursorMove, { passive: true });
}

function cancelTacticaGuerraTargeting(message = 'Táctica de guerra fue cancelada.') {
  const pending = state.pendingPowerAction;
  if (!['tacticaGuerraSelection', 'tacticaGuerraDestination'].includes(pending?.kind)) return false;
  state.pendingPowerAction = null;
  closeTacticaGuerraSelectionModal();
  removeTacticaGuerraNexusCursor();
  log(message);
  renderAll();
  return true;
}

function beginTacticaGuerraTargeting(playerId, cardId, originTab, originSlot) {
  const availability = getTacticaGuerraCastAvailability(playerId);
  if (!availability.available) {
    log(availability.message);
    renderAll();
    return false;
  }
  state.selectedMover = null;
  state.selectedTarget = null;
  state.pendingPlacement = null;
  state.pendingCard = null;
  state.pendingPowerAction = {
    kind: 'tacticaGuerraSelection',
    stage: 'selection',
    playerId,
    cardId: cardId || TACTICA_GUERRA_CARD_ID,
    originTab: Math.max(0, Number(originTab) || 0),
    originSlot: Math.max(0, Number(originSlot) || 0),
    quickDefense: availability.quickOnly === true,
    selectedUnitIds: [],
    destinations: [],
  };
  log(`Táctica de guerra: selecciona una o varias invocaciones.${availability.quickOnly ? ' Defensa rápida está activa.' : ''}`);
  renderAll();
  renderTacticaGuerraSelectionModal();
  return true;
}

function toggleTacticaGuerraSelectedUnit(unitId) {
  const pending = state.pendingPowerAction;
  if (!pending || pending.kind !== 'tacticaGuerraSelection') return false;
  const playerId = Number(pending.playerId);
  const selected = Array.isArray(pending.selectedUnitIds) ? [...pending.selectedUnitIds] : [];
  const key = String(unitId);
  const existingIndex = selected.findIndex(id => String(id) === key);
  if (existingIndex >= 0) {
    selected.splice(existingIndex, 1);
    pending.selectedUnitIds = selected;
    renderTacticaGuerraSelectionModal();
    return true;
  }
  const valid = getEligibleTacticaGuerraTargets(playerId, { quickOnly: pending.quickDefense === true, requirePayable: false })
    .some(unit => String(unit.id) === key);
  if (!valid) return false;
  const prospective = [...selected, unitId];
  const costMap = getTacticaGuerraSelectionCostMap(playerId, prospective);
  if (!canPayTacticaGuerraCostMap(playerId, costMap)) {
    const unit = getUnitById(playerId, unitId);
    const elementId = getTacticaGuerraTargetElementId(playerId, unit);
    const label = getElementById(elementId)?.label || elementId || 'ese dominio';
    log(`No tienes otro elemento de ${label} para incluir esa invocación.`);
    return false;
  }
  pending.selectedUnitIds = prospective;
  renderTacticaGuerraSelectionModal();
  return true;
}

function renderTacticaGuerraSelectionModal() {
  const pending = state.pendingPowerAction;
  if (!pending || pending.kind !== 'tacticaGuerraSelection') {
    closeTacticaGuerraSelectionModal();
    return;
  }
  closeTacticaGuerraSelectionModal();
  const playerId = Number(pending.playerId);
  const selected = Array.isArray(pending.selectedUnitIds) ? pending.selectedUnitIds : [];
  const candidates = getEligibleTacticaGuerraTargets(playerId, { quickOnly: pending.quickDefense === true, requirePayable: false });
  const costMap = getTacticaGuerraSelectionCostMap(playerId, selected);
  const resourceCounts = getTacticaGuerraResourceCounts(playerId);
  const card = CARD_LIBRARY[pending.cardId || TACTICA_GUERRA_CARD_ID];
  const water = getElementById('agua');

  const overlay = document.createElement('section');
  overlay.id = 'tacticaGuerraSelectionOverlay';
  overlay.className = 'tactica-guerra-selection-overlay open';
  overlay.style.setProperty('--tactica-water-color', water?.color || '#49d6dd');
  overlay.style.setProperty('--tactica-water-accent', '#65efcf');
  overlay.setAttribute('aria-modal', 'true');
  overlay.setAttribute('role', 'dialog');
  overlay.innerHTML = `<div class="tactica-guerra-selection-shell">
    <button type="button" class="tactica-guerra-selection-close" aria-label="Cerrar">×</button>
    <header>
      <img src="${card?.spellIcon || card?.thumbnailImage || 'assets/spell-tactica-de-guerra.png'}" alt="">
      <div><strong>Táctica de guerra</strong><span>Selecciona las invocaciones</span></div>
    </header>
    <p class="tactica-guerra-selection-help">Cada invocación añade 1 elemento de su propio dominio. El orden de selección será el orden de colocación de sus nuevos nexos. ${pending.quickDefense ? '<strong>Defensa rápida:</strong> resolución instantánea; solo invocaciones en tu lado de la arena.' : '<strong>Kasteo normal:</strong> 2 fases antes de la resolución.'}</p>
    <div class="tactica-guerra-selection-list"></div>
    <div class="tactica-guerra-cost-panel">
      <span class="tactica-guerra-cost-title">Costo acumulado</span>
      <div class="tactica-guerra-cost-strip"></div>
    </div>
    <footer>
      <span class="tactica-guerra-selection-count">${selected.length} seleccionada${selected.length === 1 ? '' : 's'}</span>
      <button type="button" class="tactica-guerra-selection-cancel">Cancelar</button>
      <button type="button" class="tactica-guerra-selection-confirm" ${selected.length && canPayTacticaGuerraCostMap(playerId, costMap) ? '' : 'disabled'}>Kastear</button>
    </footer>
  </div>`;
  appendRokUiNode(overlay);

  const list = overlay.querySelector('.tactica-guerra-selection-list');
  candidates.forEach(unit => {
    const unitCard = CARD_LIBRARY[unit.cardId] || null;
    const elementId = getTacticaGuerraTargetElementId(playerId, unit);
    const element = getElementById(elementId);
    const selectedIndex = selected.findIndex(id => String(id) === String(unit.id));
    const alreadySelected = selectedIndex >= 0;
    const selectedCountForElement = Number(costMap[elementId] || 0);
    const availableCount = Number(resourceCounts[elementId] || 0);
    const canAdd = alreadySelected || selectedCountForElement < availableCount;
    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'tactica-guerra-selection-unit';
    button.classList.toggle('selected', alreadySelected);
    button.classList.toggle('unpayable', !canAdd);
    button.disabled = !canAdd;
    button.style.setProperty('--tactica-target-color', element?.color || '#ffffff');
    button.innerHTML = `
      <span class="tactica-guerra-selection-order">${alreadySelected ? selectedIndex + 1 : ''}</span>
      <img class="tactica-guerra-selection-token" src="${unitCard?.tokenImage || unitCard?.artImage || 'assets/invocation-token.png'}" alt="">
      <span class="tactica-guerra-selection-copy"><strong>${unitCard?.name || 'Invocación'}</strong><small>${coordLabel(unit.row, unit.col)} · Vida ${Number(unit.hp ?? unitCard?.stats?.life ?? 0)}/${Number(unit.maxHp ?? unitCard?.stats?.life ?? 0)}</small></span>
      <span class="tactica-guerra-selection-element"><img src="${getElementCostIcon(elementId)}" alt="${element?.label || elementId}"><b>${element?.label || elementId}</b><small>${availableCount - selectedCountForElement} libre${availableCount - selectedCountForElement === 1 ? '' : 's'}</small></span>`;
    button.addEventListener('click', event => {
      event.preventDefault();
      event.stopPropagation();
      toggleTacticaGuerraSelectedUnit(unit.id);
    });
    list?.appendChild(button);
  });

  const costStrip = overlay.querySelector('.tactica-guerra-cost-strip');
  if (!selected.length) {
    costStrip.innerHTML = '<span class="tactica-guerra-cost-empty">Selecciona al menos una invocación</span>';
  } else {
    selected.forEach((unitId, index) => {
      const unit = getUnitById(playerId, unitId);
      const elementId = getTacticaGuerraTargetElementId(playerId, unit);
      const element = getElementById(elementId);
      const chip = document.createElement('span');
      chip.className = 'tactica-guerra-cost-chip';
      chip.style.setProperty('--tactica-cost-color', element?.color || '#ffffff');
      chip.innerHTML = `<small>${index + 1}</small><img src="${getElementCostIcon(elementId)}" alt="${element?.label || elementId}"><b>${element?.label || elementId}</b>`;
      costStrip.appendChild(chip);
    });
  }

  overlay.addEventListener('pointerdown', event => event.stopPropagation());
  overlay.querySelector('.tactica-guerra-selection-close')?.addEventListener('click', () => cancelTacticaGuerraTargeting());
  overlay.querySelector('.tactica-guerra-selection-cancel')?.addEventListener('click', () => cancelTacticaGuerraTargeting());
  overlay.querySelector('.tactica-guerra-selection-confirm')?.addEventListener('click', confirmTacticaGuerraTargetSelection);
}

function confirmTacticaGuerraTargetSelection() {
  const pending = state.pendingPowerAction;
  if (!pending || pending.kind !== 'tacticaGuerraSelection') return false;
  const playerId = Number(pending.playerId);
  const selected = Array.isArray(pending.selectedUnitIds) ? pending.selectedUnitIds.filter(Boolean) : [];
  if (!selected.length) {
    log('Selecciona al menos una invocación para Táctica de guerra.');
    return false;
  }
  const validIds = new Set(getEligibleTacticaGuerraTargets(playerId, { quickOnly: pending.quickDefense === true, requirePayable: false }).map(unit => String(unit.id)));
  if (selected.some(unitId => !validIds.has(String(unitId)))) {
    log('Una de las invocaciones seleccionadas dejó de ser válida.');
    renderTacticaGuerraSelectionModal();
    return false;
  }
  const costMap = getTacticaGuerraSelectionCostMap(playerId, selected);
  if (!canPayTacticaGuerraCostMap(playerId, costMap)) {
    log('Ya no tienes los elementos necesarios para cubrir el costo acumulado.');
    renderTacticaGuerraSelectionModal();
    return false;
  }
  closeTacticaGuerraSelectionModal();
  state.pendingPowerAction = {
    ...pending,
    kind: 'tacticaGuerraDestination',
    stage: 'destination',
    selectedUnitIds: selected,
    currentIndex: 0,
    destinations: [],
    costMap,
  };
  ensureTacticaGuerraCursorTracking();
  renderAll();
  renderTacticaGuerraNexusCursor();
  const firstUnit = getUnitById(playerId, selected[0]);
  log(`Táctica de guerra: coloca el nexo 1 de ${selected.length} para ${CARD_LIBRARY[firstUnit?.cardId]?.name || 'la invocación'}.`);
  return true;
}

function isTacticaGuerraDestinationRowAllowed(playerId, row) {
  return Number(playerId) === 1 ? Number(row) >= 9 : Number(row) <= 8;
}

function getTacticaGuerraCurrentUnit(pending = state.pendingPowerAction) {
  if (!pending || pending.kind !== 'tacticaGuerraDestination') return null;
  return getUnitById(Number(pending.playerId), pending.selectedUnitIds?.[Number(pending.currentIndex || 0)]);
}

function getTacticaGuerraDestinationCells(playerId, unit, pending = state.pendingPowerAction) {
  if (!unit) return [];
  const reserved = Array.isArray(pending?.destinations) ? pending.destinations : [];
  const cells = [];
  for (let row = 0; row < 18; row += 1) {
    if (!isTacticaGuerraDestinationRowAllowed(playerId, row)) continue;
    for (let col = 0; col < 9; col += 1) {
      if (row === unit.row && col === unit.col) continue;
      if (reserved.some(entry => Number(entry.row) === row && Number(entry.col) === col)) continue;
      if (isOccupiedForPlayer(row, col, null)) continue;
      const markerOccupied = (state.players[1]?.spawnMarkers || []).some(marker => marker.row === row && marker.col === col && marker.id !== unit.spawnId)
        || (state.players[2]?.spawnMarkers || []).some(marker => marker.row === row && marker.col === col && marker.id !== unit.spawnId);
      if (markerOccupied) continue;
      cells.push({ row, col });
    }
  }
  return cells;
}

function renderTacticaGuerraNexusCursor() {
  const pending = state.pendingPowerAction;
  const isTactica = pending?.kind === 'tacticaGuerraDestination';
  const isEmboscada = pending?.kind === 'emboscadaDestination';
  if (!isTactica && !isEmboscada) {
    removeTacticaGuerraNexusCursor();
    return;
  }
  removeTacticaGuerraNexusCursor();
  const unit = isEmboscada ? getEmboscadaCurrentUnit(pending) : getTacticaGuerraCurrentUnit(pending);
  const card = CARD_LIBRARY[unit?.cardId] || null;
  if (!unit || !card) return;
  const elementId = isEmboscada ? 'agua' : getTacticaGuerraTargetElementId(Number(pending.playerId), unit);
  const element = getElementById(elementId);
  const cursor = document.createElement('div');
  cursor.id = 'tacticaGuerraNexusCursor';
  cursor.className = `tactica-guerra-nexus-cursor${isEmboscada ? ' emboscada-nexus-cursor' : ''}`;
  cursor.style.setProperty('--tactica-nexus-color', element?.color || '#49d6dd');
  cursor.innerHTML = `<div class="tactica-guerra-nexus-cursor-ring"></div><span class="tactica-guerra-nexus-cursor-count">${Number(pending.currentIndex || 0) + 1}/${pending.selectedUnitIds.length}</span>`;
  const mini = createCardElement(card, { elementIdOverride: getEffectiveCardElementId(card, Number(pending.playerId)) });
  mini.classList.add('mini', 'tactica-guerra-nexus-cursor-card');
  cursor.insertBefore(mini, cursor.firstChild);
  document.body.appendChild(cursor);
}

async function playTacticaGuerraResolutionFx(title = 'TÁCTICA DE GUERRA', subtitle = 'REPOSICIONAMIENTO DE NEXOS', options = {}) {
  if (!options.suppressOnlineFx) emitOnlineVisualEvent('tactica-resolution', { title: String(title || ''), subtitle: String(subtitle || '') });
  const boardRect = els.boardContent?.getBoundingClientRect?.();
  if (!boardRect) return;
  const fx = document.createElement('div');
  fx.className = 'tactica-guerra-resolution-fx';
  fx.style.left = `${boardRect.left}px`;
  fx.style.top = `${boardRect.top}px`;
  fx.style.width = `${boardRect.width}px`;
  fx.style.height = `${boardRect.height}px`;
  const safeTitle = String(title || '').replace(/[<>]/g, '');
  const safeSubtitle = String(subtitle || '').replace(/[<>]/g, '');
  fx.innerHTML = `<span class="tactica-guerra-resolution-wave wave-a"></span><span class="tactica-guerra-resolution-wave wave-b"></span><strong>${safeTitle}</strong><small>${safeSubtitle}</small>`;
  document.body.appendChild(fx);
  await new Promise(resolve => setTimeout(resolve, 760));
  setTimeout(() => fx.remove(), 700);
}

function playTacticaGuerraWaterRestoreFx(unit, delayMs = 0, options = {}) {
  if (!options.suppressOnlineFx) emitOnlineVisualEvent('tactica-water', { source: snapshotOnlineFxUnit(0, unit), delayMs: Number(delayMs || 0) });
  if (!unit) return Promise.resolve(false);
  return new Promise(resolve => {
    setTimeout(() => {
      const point = getCellViewportCenter(unit.row, unit.col);
      const fx = document.createElement('div');
      fx.className = 'tactica-guerra-water-restore-fx';
      fx.style.left = `${point.x}px`;
      fx.style.top = `${point.y}px`;
      fx.innerHTML = '<span class="tactica-water-ring ring-a"></span><span class="tactica-water-ring ring-b"></span><span class="tactica-water-ray ray-a"></span><span class="tactica-water-ray ray-b"></span><span class="tactica-water-ray ray-c"></span><i></i><i></i><i></i><i></i><i></i><i></i>';
      document.body.appendChild(fx);
      setTimeout(() => { fx.remove(); resolve(true); }, 1700);
    }, Math.max(0, Number(delayMs) || 0));
  });
}

function applyTacticaGuerraNexusDestinations(playerId, units = [], destinations = []) {
  units.forEach((unit, index) => {
    const destination = destinations[index];
    if (!unit || !destination) return;
    const marker = (state.players?.[playerId]?.spawnMarkers || []).find(item => item.id === unit.spawnId);
    if (marker) {
      marker.row = destination.row;
      marker.col = destination.col;
    } else {
      unit.restoreRow = destination.row;
      unit.restoreCol = destination.col;
    }
    clearUnitEngagement(playerId, unit.id);
  });
}

async function executeTacticaGuerraResolution(playerId, plan = {}, card = CARD_LIBRARY[TACTICA_GUERRA_CARD_ID]) {
  const selected = Array.isArray(plan.selectedUnitIds) ? plan.selectedUnitIds : [];
  const destinations = Array.isArray(plan.destinations) ? plan.destinations : [];
  const units = selected.map(unitId => getUnitById(playerId, unitId)).filter(Boolean);
  if (!units.length || destinations.length < selected.length) {
    log('Táctica de guerra se resuelve sin objetivos válidos suficientes.');
    return { type: 'spell', card, spellId: card?.id || TACTICA_GUERRA_CARD_ID };
  }

  applyTacticaGuerraNexusDestinations(playerId, units, destinations);
  renderAll();
  await playTacticaGuerraResolutionFx();

  units.forEach((unit, index) => {
    const delay = index * 180;
    playTacticaGuerraWaterRestoreFx(unit, delay);
    setTimeout(() => {
      const liveUnit = getUnitById(playerId, unit.id);
      if (!liveUnit) return;
      showFloatingTextAt(liveUnit.row, liveUnit.col, 'TÁCTICA DE GUERRA', 'floating-combat buff');
      restoreInvocation(playerId, liveUnit, 'Táctica de guerra');
    }, delay + 260);
  });

  log(`Táctica de guerra reposiciona ${units.length} nexo${units.length === 1 ? '' : 's'} y restaura las invocaciones seleccionadas.`);
  renderAll();
  return { type: 'spell', card, spellId: card?.id || TACTICA_GUERRA_CARD_ID };
}

async function resolveQueuedTacticaGuerraCast(playerId, item, card = CARD_LIBRARY[TACTICA_GUERRA_CARD_ID]) {
  return executeTacticaGuerraResolution(playerId, item?.tacticaGuerraPlan || {}, card);
}

async function resolveTacticaGuerraPlan() {
  const pending = state.pendingPowerAction;
  if (!pending || pending.kind !== 'tacticaGuerraDestination') return false;
  const playerId = Number(pending.playerId);
  const player = state.players?.[playerId];
  const card = CARD_LIBRARY[pending.cardId || TACTICA_GUERRA_CARD_ID];
  const tab = Number(pending.originTab || 0);
  const slot = Number(pending.originSlot || 0);
  const selected = Array.isArray(pending.selectedUnitIds) ? pending.selectedUnitIds : [];
  const destinations = Array.isArray(pending.destinations) ? pending.destinations : [];
  const units = selected.map(unitId => getUnitById(playerId, unitId));
  if (!player || !card || player.handTabs?.[tab]?.[slot] !== card.id || units.some(unit => !unit) || destinations.length !== units.length) {
    return cancelTacticaGuerraTargeting('Táctica de guerra se canceló porque la carta, los objetivos o los nexos dejaron de estar disponibles.');
  }
  const costMap = getTacticaGuerraSelectionCostMap(playerId, selected);
  if (!payCost(player.resources, costMap, 'agua')) {
    log('No tienes los elementos necesarios para resolver Táctica de guerra.');
    renderAll();
    return false;
  }

  player.handTabs[tab][slot] = null;
  clearSpellbookUseCooldown(playerId, tab, slot);
  markTurnActionCommitted(playerId, 'cast');
  state.infoCard = null;
  state.selectedCardSlot = null;
  state.pendingCard = null;
  state.pendingPlacement = null;
  state.pendingPowerAction = null;
  closeTacticaGuerraSelectionModal();
  removeTacticaGuerraNexusCursor();

  const plan = {
    selectedUnitIds: [...selected],
    destinations: destinations.map(entry => ({ ...entry })),
    costMap: { ...costMap },
  };
  const paidText = Object.entries(costMap).map(([elementId, amount]) => `${amount} ${getElementById(elementId)?.label || elementId}`).join(', ');

  if (pending.quickDefense === true) {
    log(`Defensa rápida: Táctica de guerra consume ${paidText} y se resuelve como instantáneo.`);
    renderAll();
    await executeTacticaGuerraResolution(playerId, plan, card);
    return true;
  }

  const caster = state.players?.[playerId]?.caster || {};
  const persistentCardState = card.type === 'invocation'
    ? takeSpellbookCardPersistentState(LOCAL_PLAYER_ID, pending.tab, pending.slotIndex, card.id)
    : null;
  const castItem = {
    cardId: card.id,
    persistentCardState,
    elementId: getEffectiveCardElementId(card, playerId),
    remaining: 2,
    row: Number(caster.row ?? 0),
    col: Number(caster.col ?? 0),
    justAdded: true,
    introStarted: false,
    introDone: false,
    introEndsAt: 0,
    spawnId: `spell_${Date.now()}_${Math.random().toString(16).slice(2)}`,
    originTab: tab,
    originSlot: slot,
    tacticaGuerraPlan: plan,
  };
  player.castQueue = Array.isArray(player.castQueue) ? player.castQueue : [];
  player.castQueue.push(castItem);
  player.caster.state = 'casting';
  const queuePosition = player.castQueue.length;
  log(queuePosition === 1
    ? `Táctica de guerra consume ${paidText} y entra a zona de kasteo. Kasteo activo: 2 fases.`
    : `Táctica de guerra consume ${paidText} y entra a cola de kasteo. Espera ${queuePosition - 1} carta${queuePosition === 2 ? '' : 's'} antes de comenzar.`);
  renderAll();
  return true;
}

async function resolveTacticaGuerraDestination(playerId, row, col) {
  const pending = state.pendingPowerAction;
  if (!pending || pending.kind !== 'tacticaGuerraDestination' || Number(pending.playerId) !== Number(playerId)) return false;
  const unit = getTacticaGuerraCurrentUnit(pending);
  if (!unit) return cancelTacticaGuerraTargeting('La siguiente invocación seleccionada dejó de estar disponible.');
  if (!getTacticaGuerraDestinationCells(playerId, unit, pending).some(cell => cell.row === row && cell.col === col)) {
    log('Esa casilla no es válida para trasladar el nexo.');
    return false;
  }
  pending.destinations = [...(pending.destinations || []), { unitId: unit.id, row, col }];
  const nextIndex = Number(pending.currentIndex || 0) + 1;
  if (nextIndex < pending.selectedUnitIds.length) {
    pending.currentIndex = nextIndex;
    renderAll();
    renderTacticaGuerraNexusCursor();
    const nextUnit = getTacticaGuerraCurrentUnit(pending);
    log(`Nexo ${nextIndex} colocado. Ahora coloca el nexo ${nextIndex + 1} de ${pending.selectedUnitIds.length} para ${CARD_LIBRARY[nextUnit?.cardId]?.name || 'la siguiente invocación'}.`);
    return true;
  }
  return resolveTacticaGuerraPlan();
}


function isEmboscadaTargetingKind(kind) {
  return ['emboscadaRivalSelection', 'emboscadaAlliedSelection', 'emboscadaDestination'].includes(String(kind || ''));
}

function getEmboscadaWaterCount(playerId) {
  return (state.players?.[playerId]?.resources || []).filter(resource => resource?.id === 'agua').length;
}

function getEmboscadaRivalCandidates(playerId) {
  const enemyId = getEnemyPlayerId(playerId);
  return (state.players?.[enemyId]?.units || []).filter(unit => unit
    && canPlayerDirectlyTargetInvocation(playerId, enemyId, unit)
    && !unit.restoreAnimating
    && isUnitInOwnSide(playerId, unit));
}

function getEmboscadaAlliedCandidates(playerId) {
  return (state.players?.[playerId]?.units || []).filter(unit => unit
    && unit.status !== 'restoring'
    && !unit.restoreAnimating
    && Number(unit.hp ?? 0) > 0
    && isUnitInOwnSide(playerId, unit));
}

function getEmboscadaCastAvailability(playerId) {
  const rivals = getEmboscadaRivalCandidates(playerId);
  const allies = getEmboscadaAlliedCandidates(playerId);
  const water = getEmboscadaWaterCount(playerId);
  const quickDefense = (isRealtimePlayStyle() && Boolean(state?.realtime?.active))
    ? true
    : (currentPhase().id !== 'casting' || Number(state.activePlayer) !== Number(playerId));
  if (!isCasterInOwnSide(playerId)) return { available: false, message: 'El Kaster no puede usar Emboscada desde la zona enemiga.', rivals: [], allies: [], water, quickDefense };
  const userStatus = canCasterUseSpell(playerId, CARD_LIBRARY[EMBOSCADA_CARD_ID]);
  if (!userStatus.ok) return { available: false, message: userStatus.message, rivals: [], allies: [], water, quickDefense };
  if (!rivals.length) return { available: false, message: 'Emboscada requiere una invocación rival dentro de tu lado de la arena.', rivals: [], allies, water, quickDefense };
  if (!allies.length) return { available: false, message: 'Emboscada requiere al menos una invocación aliada activa dentro de tu lado de la arena.', rivals, allies: [], water, quickDefense };
  if (water <= 0) return { available: false, message: 'Emboscada requiere al menos 1 elemento de Agua.', rivals, allies, water, quickDefense };
  return { available: true, message: '', rivals, allies, water, quickDefense };
}

function findReadyEmboscadaSpellbookSlot(playerId) {
  const player = state.players?.[playerId];
  if (!player || !Array.isArray(player.handTabs)) return null;
  for (let tab = 0; tab < player.handTabs.length; tab += 1) {
    for (let slot = 0; slot < (player.handTabs[tab] || []).length; slot += 1) {
      if (player.handTabs[tab][slot] !== EMBOSCADA_CARD_ID) continue;
      if (getSpellbookUseCooldown(playerId, tab, slot) > 0) continue;
      return { tab, slot };
    }
  }
  return null;
}

function createEmboscadaQuickReactionCandidate(playerId = LOCAL_PLAYER_ID) {
  const availability = getEmboscadaCastAvailability(playerId);
  if (!availability.available || !availability.quickDefense) return null;
  const slotInfo = findReadyEmboscadaSpellbookSlot(playerId);
  const card = CARD_LIBRARY[EMBOSCADA_CARD_ID];
  if (!slotInfo || !card) return null;
  return {
    type: 'spellbookReaction', selectionType: 'spellbook', playerId, unitId: null,
    cardId: card.id, originTab: slotInfo.tab, originSlot: slotInfo.slot,
    label: card.name,
    actions: [{ id: 'emboscadaDefensaRapida', label: 'Kastear', title: 'Usar Emboscada con Defensa rápida', directExecute: true, targets: [], execute: () => beginEmboscadaTargeting(playerId, card.id, slotInfo.tab, slotInfo.slot) }],
    actionLabels: ['Kastear'], targets: [],
  };
}

function prepareEmboscadaQuickReactionManualTargeting() {
  stopQuickReactionDecisionCountdown();
  hideQuickReactionInputShield({ force: true });
  hideQuickReactionWindowForPlayer(LOCAL_PLAYER_ID);
  clearQuickReactionExecutionLayer();
  clearQuickReactionCommandDock();
  if (els.quickReactionModal) {
    els.quickReactionModal.classList.remove('visible', 'quick-reaction-modal-executing');
    els.quickReactionModal.setAttribute('aria-hidden', 'true');
  }
  if (els.quickReactionModalList) els.quickReactionModalList.innerHTML = '';
  resetQuickReactionModalCardLayout();
  clearInterval(closeQuickReactionModal.timer);
  if (state.quickReactionWindow) {
    state.quickReactionWindow.locked = true;
    state.quickReactionWindow.active = true;
    state.quickReactionWindow.executing = true;
    state.quickReactionWindow.manualEmboscadaTargeting = true;
  }
  syncLocalQuickReactionGameplayPause();
}

function releaseEmboscadaQuickReactionManualTargeting(outcome = 'cancelled') {
  if (state.quickReactionWindow) delete state.quickReactionWindow.manualEmboscadaTargeting;
  hideQuickReactionInputShield({ force: true });
  return forceReleaseQuickReactionManualPowerFlow(outcome);
}

function closeEmboscadaSelectionModal() {
  document.getElementById('emboscadaSelectionOverlay')?.remove();
}

function cancelEmboscadaTargeting(message = 'Emboscada fue cancelada.') {
  const pending = state.pendingPowerAction;
  if (!isEmboscadaTargetingKind(pending?.kind)) return false;
  const fromQuickReactionWindow = pending.fromQuickReactionWindow === true;
  state.pendingPowerAction = null;
  closeEmboscadaSelectionModal();
  removeTacticaGuerraNexusCursor();
  if (fromQuickReactionWindow) releaseEmboscadaQuickReactionManualTargeting('cancelled');
  log(message);
  renderAll();
  return true;
}

function beginEmboscadaTargeting(playerId, cardId, originTab, originSlot) {
  const availability = getEmboscadaCastAvailability(playerId);
  if (!availability.available) {
    log(availability.message);
    renderAll();
    return false;
  }
  const fromQuickReactionWindow = availability.quickDefense && Boolean(
    state.quickReactionWindow?.phaseIntro
    || state.quickReactionWindow?.locked
    || state.quickReactionWindow?.active
    || state.quickReactionWindow?.executing
    || els.quickReactionWindow?.classList?.contains('visible')
    || els.quickReactionModal?.classList?.contains('visible')
    || document.getElementById('quickReactionCommandDock')?.classList?.contains('visible')
    || document.getElementById('quickReactionInputShield')?.classList?.contains('visible')
  );
  if (fromQuickReactionWindow) prepareEmboscadaQuickReactionManualTargeting();
  else if (availability.quickDefense === true) hideQuickReactionInputShield({ force: true });

  state.selectedMover = null;
  state.selectedTarget = null;
  state.pendingPlacement = null;
  state.pendingCard = null;
  state.pendingPowerAction = {
    kind: 'emboscadaRivalSelection',
    stage: 'rival-selection',
    playerId,
    cardId: cardId || EMBOSCADA_CARD_ID,
    originTab: Math.max(0, Number(originTab) || 0),
    originSlot: Math.max(0, Number(originSlot) || 0),
    quickDefense: availability.quickDefense === true,
    fromQuickReactionWindow,
    selectedRivalUnitId: '',
    selectedUnitIds: [],
    destinations: [],
    currentIndex: 0,
  };
  log(`Emboscada: selecciona primero la invocación rival invasora.${availability.quickDefense ? ' Defensa rápida está activa.' : ''}`);
  renderAll();
  renderEmboscadaRivalSelectionModal();
  return true;
}

function createEmboscadaTacticaUnitButton(playerId, unit, options = {}) {
  const card = CARD_LIBRARY[unit?.cardId] || null;
  const elementId = getEffectiveCardElementId(card, playerId);
  const element = getElementById(elementId);
  const water = getElementById('agua');
  const selected = options.selected === true;
  const unpayable = options.unpayable === true;
  const order = options.order || '';
  const role = options.role || 'ALIADA';
  const detail = options.detail || '';
  const useWaterCost = options.useWaterCost === true;
  const targetColor = useWaterCost ? (water?.color || '#49d6dd') : (element?.color || '#ffffff');
  const iconElementId = useWaterCost ? 'agua' : elementId;
  const iconElement = useWaterCost ? water : element;

  const button = document.createElement('button');
  button.type = 'button';
  button.className = 'tactica-guerra-selection-unit emboscada-selection-unit';
  button.classList.toggle('selected', selected);
  button.classList.toggle('unpayable', unpayable);
  button.disabled = unpayable;
  button.style.setProperty('--tactica-target-color', targetColor);
  button.innerHTML = `
    <span class="tactica-guerra-selection-order">${order}</span>
    <img class="tactica-guerra-selection-token" src="${card?.tokenImage || card?.artImage || card?.thumbnailImage || 'assets/invocation-token.png'}" alt="">
    <span class="tactica-guerra-selection-copy"><strong>${escapeHtml(card?.name || 'Invocación')}</strong><small>${coordLabel(unit.row, unit.col)} · Vida ${Number(unit.hp ?? card?.stats?.life ?? 0)}/${Number(unit.maxHp ?? card?.stats?.life ?? 0)}</small></span>
    <span class="tactica-guerra-selection-element"><img src="${getElementCostIcon(iconElementId)}" alt="${escapeHtml(iconElement?.label || iconElementId)}"><b>${escapeHtml(role)}</b><small>${escapeHtml(detail)}</small></span>`;
  return button;
}

function renderEmboscadaRivalSelectionModal() {
  const pending = state.pendingPowerAction;
  if (pending?.kind !== 'emboscadaRivalSelection') {
    closeEmboscadaSelectionModal();
    return;
  }
  closeEmboscadaSelectionModal();
  const playerId = Number(pending.playerId);
  const rivals = getEmboscadaRivalCandidates(playerId);
  const selectedRivalId = String(pending.selectedRivalUnitId || '');
  const card = CARD_LIBRARY[pending.cardId || EMBOSCADA_CARD_ID];
  const water = getElementById('agua');

  const overlay = document.createElement('section');
  overlay.id = 'emboscadaSelectionOverlay';
  overlay.className = 'tactica-guerra-selection-overlay emboscada-selection-overlay open';
  overlay.style.setProperty('--tactica-water-color', water?.color || '#49d6dd');
  overlay.style.setProperty('--tactica-water-accent', '#65efcf');
  overlay.setAttribute('aria-modal', 'true');
  overlay.setAttribute('role', 'dialog');
  overlay.innerHTML = `<div class="tactica-guerra-selection-shell emboscada-selection-shell">
    <button type="button" class="tactica-guerra-selection-close" aria-label="Cerrar">×</button>
    <header>
      <img src="${card?.spellIcon || card?.thumbnailImage || 'assets/spell-emboscada.webp'}" alt="">
      <div><strong>Emboscada</strong><span>Selecciona la invasora rival</span></div>
    </header>
    <p class="tactica-guerra-selection-help">Selecciona la invocación rival que ingresó a tu lado de la arena. Esa unidad será el objetivo exclusivo de todas las invocaciones vinculadas por Emboscada hasta que vuelvan a restaurarse.</p>
    <div class="tactica-guerra-selection-list"></div>
    <footer>
      <span class="tactica-guerra-selection-count">${selectedRivalId ? '1 objetivo seleccionado' : 'Selecciona un objetivo'}</span>
      <button type="button" class="tactica-guerra-selection-cancel">Cancelar</button>
      <button type="button" class="tactica-guerra-selection-confirm" ${selectedRivalId ? '' : 'disabled'}>Continuar</button>
    </footer>
  </div>`;
  appendRokUiNode(overlay);

  const list = overlay.querySelector('.tactica-guerra-selection-list');
  rivals.forEach(unit => {
    const selected = String(unit.id) === selectedRivalId;
    const button = createEmboscadaTacticaUnitButton(getEnemyPlayerId(playerId), unit, {
      selected,
      order: selected ? '1' : '',
      role: 'OBJETIVO',
      detail: 'Invasora rival',
    });
    button.addEventListener('click', event => {
      event.preventDefault();
      event.stopPropagation();
      pending.selectedRivalUnitId = unit.id;
      renderEmboscadaRivalSelectionModal();
    });
    list?.appendChild(button);
  });

  overlay.addEventListener('pointerdown', event => event.stopPropagation());
  overlay.querySelector('.tactica-guerra-selection-close')?.addEventListener('click', () => cancelEmboscadaTargeting());
  overlay.querySelector('.tactica-guerra-selection-cancel')?.addEventListener('click', () => cancelEmboscadaTargeting());
  overlay.querySelector('.tactica-guerra-selection-confirm')?.addEventListener('click', confirmEmboscadaRivalSelection);
}

function confirmEmboscadaRivalSelection() {
  const pending = state.pendingPowerAction;
  if (pending?.kind !== 'emboscadaRivalSelection') return false;
  const valid = getEmboscadaRivalCandidates(Number(pending.playerId))
    .some(unit => String(unit.id) === String(pending.selectedRivalUnitId || ''));
  if (!valid) {
    pending.selectedRivalUnitId = '';
    log('La invasora seleccionada dejó de ser válida.');
    renderEmboscadaRivalSelectionModal();
    return false;
  }
  pending.kind = 'emboscadaAlliedSelection';
  pending.stage = 'allied-selection';
  pending.selectedUnitIds = [];
  renderAll();
  renderEmboscadaAlliedSelectionModal();
  return true;
}

function toggleEmboscadaAlliedUnit(unitId) {
  const pending = state.pendingPowerAction;
  if (pending?.kind !== 'emboscadaAlliedSelection') return false;
  const playerId = Number(pending.playerId);
  const selected = [...(pending.selectedUnitIds || [])];
  const index = selected.findIndex(id => String(id) === String(unitId));
  if (index >= 0) {
    selected.splice(index, 1);
  } else {
    const valid = getEmboscadaAlliedCandidates(playerId).some(unit => String(unit.id) === String(unitId));
    if (!valid) return false;
    if (selected.length >= getEmboscadaWaterCount(playerId)) {
      log('No tienes más Agua para incluir otra invocación en Emboscada.');
      return false;
    }
    selected.push(unitId);
  }
  pending.selectedUnitIds = selected;
  renderEmboscadaAlliedSelectionModal();
  return true;
}

function renderEmboscadaAlliedSelectionModal() {
  const pending = state.pendingPowerAction;
  if (pending?.kind !== 'emboscadaAlliedSelection') {
    closeEmboscadaSelectionModal();
    return;
  }
  closeEmboscadaSelectionModal();
  const playerId = Number(pending.playerId);
  const selected = Array.isArray(pending.selectedUnitIds) ? pending.selectedUnitIds : [];
  const allies = getEmboscadaAlliedCandidates(playerId);
  const waterCount = getEmboscadaWaterCount(playerId);
  const water = getElementById('agua');
  const rival = getUnitById(getEnemyPlayerId(playerId), pending.selectedRivalUnitId);
  const rivalCard = CARD_LIBRARY[rival?.cardId] || null;
  const card = CARD_LIBRARY[pending.cardId || EMBOSCADA_CARD_ID];

  const overlay = document.createElement('section');
  overlay.id = 'emboscadaSelectionOverlay';
  overlay.className = 'tactica-guerra-selection-overlay emboscada-selection-overlay open';
  overlay.style.setProperty('--tactica-water-color', water?.color || '#49d6dd');
  overlay.style.setProperty('--tactica-water-accent', '#65efcf');
  overlay.setAttribute('aria-modal', 'true');
  overlay.setAttribute('role', 'dialog');
  overlay.innerHTML = `<div class="tactica-guerra-selection-shell emboscada-selection-shell">
    <button type="button" class="tactica-guerra-selection-close" aria-label="Cerrar">×</button>
    <header>
      <img src="${card?.spellIcon || card?.thumbnailImage || 'assets/spell-emboscada.webp'}" alt="">
      <div><strong>Emboscada</strong><span>Objetivo: ${escapeHtml(rivalCard?.name || 'Invasora rival')}</span></div>
    </header>
    <p class="tactica-guerra-selection-help">Selecciona una o varias invocaciones aliadas de tu lado. Cada selección consume <strong>1 Agua</strong>. El orden de selección será el orden de colocación de sus nuevos nexos dentro de radio ${EMBOSCADA_RADIUS} alrededor de la invasora. ${pending.quickDefense ? '<strong>Defensa rápida:</strong> se resolverá como instantáneo.' : '<strong>Kasteo normal:</strong> 2 fases.'}</p>
    <div class="tactica-guerra-selection-list"></div>
    <div class="tactica-guerra-cost-panel">
      <span class="tactica-guerra-cost-title">Costo acumulado · ${selected.length}/${waterCount} Agua</span>
      <div class="tactica-guerra-cost-strip"></div>
    </div>
    <footer>
      <span class="tactica-guerra-selection-count">${selected.length} seleccionada${selected.length === 1 ? '' : 's'}</span>
      <button type="button" class="tactica-guerra-selection-cancel">Cancelar</button>
      <button type="button" class="tactica-guerra-selection-confirm" ${selected.length && selected.length <= waterCount ? '' : 'disabled'}>Colocar nexos</button>
    </footer>
  </div>`;
  appendRokUiNode(overlay);

  const list = overlay.querySelector('.tactica-guerra-selection-list');
  allies.forEach(unit => {
    const selectedIndex = selected.findIndex(id => String(id) === String(unit.id));
    const isSelected = selectedIndex >= 0;
    const canAdd = isSelected || selected.length < waterCount;
    const button = createEmboscadaTacticaUnitButton(playerId, unit, {
      selected: isSelected,
      unpayable: !canAdd,
      order: isSelected ? selectedIndex + 1 : '',
      role: 'AGUA',
      detail: isSelected ? `Costo ${selectedIndex + 1}` : `${waterCount - selected.length} libre${waterCount - selected.length === 1 ? '' : 's'}`,
      useWaterCost: true,
    });
    button.addEventListener('click', event => {
      event.preventDefault();
      event.stopPropagation();
      toggleEmboscadaAlliedUnit(unit.id);
    });
    list?.appendChild(button);
  });

  const costStrip = overlay.querySelector('.tactica-guerra-cost-strip');
  if (!selected.length) {
    costStrip.innerHTML = '<span class="tactica-guerra-cost-empty">Selecciona al menos una invocación</span>';
  } else {
    selected.forEach((unitId, index) => {
      const unit = getUnitById(playerId, unitId);
      const unitCard = CARD_LIBRARY[unit?.cardId] || null;
      const chip = document.createElement('span');
      chip.className = 'tactica-guerra-cost-chip';
      chip.style.setProperty('--tactica-cost-color', water?.color || '#49d6dd');
      chip.title = unitCard?.name || 'Invocación';
      chip.innerHTML = `<small>${index + 1}</small><img src="${getElementCostIcon('agua')}" alt="Agua"><b>Agua</b>`;
      costStrip?.appendChild(chip);
    });
  }

  overlay.addEventListener('pointerdown', event => event.stopPropagation());
  overlay.querySelector('.tactica-guerra-selection-close')?.addEventListener('click', () => cancelEmboscadaTargeting());
  overlay.querySelector('.tactica-guerra-selection-cancel')?.addEventListener('click', () => cancelEmboscadaTargeting());
  overlay.querySelector('.tactica-guerra-selection-confirm')?.addEventListener('click', beginEmboscadaDestinationSelection);
}

function getEmboscadaCurrentUnit(pending = state.pendingPowerAction) {
  if (pending?.kind !== 'emboscadaDestination') return null;
  return getUnitById(Number(pending.playerId), pending.selectedUnitIds?.[Number(pending.currentIndex || 0)]);
}

function beginEmboscadaDestinationSelection() {
  const pending = state.pendingPowerAction;
  if (pending?.kind !== 'emboscadaAlliedSelection') return false;
  const playerId = Number(pending.playerId);
  const selected = Array.isArray(pending.selectedUnitIds) ? pending.selectedUnitIds.filter(Boolean) : [];
  const waterCount = getEmboscadaWaterCount(playerId);
  const rival = getUnitById(getEnemyPlayerId(playerId), pending.selectedRivalUnitId);
  const validAllies = new Set(getEmboscadaAlliedCandidates(playerId).map(unit => String(unit.id)));
  if (!rival || rival.status === 'restoring' || !getEmboscadaRivalCandidates(playerId).some(unit => String(unit.id) === String(rival.id))) {
    return cancelEmboscadaTargeting('Emboscada se canceló porque la invasora dejó de ser válida.');
  }
  if (!selected.length || selected.some(id => !validAllies.has(String(id)))) {
    log('Selecciona al menos una invocación aliada válida.');
    renderEmboscadaAlliedSelectionModal();
    return false;
  }
  if (selected.length > waterCount) {
    log(`Necesitas ${selected.length} Agua para incluir todas las invocaciones seleccionadas.`);
    renderEmboscadaAlliedSelectionModal();
    return false;
  }
  pending.kind = 'emboscadaDestination';
  pending.stage = 'destination';
  pending.currentIndex = 0;
  pending.destinations = [];
  closeEmboscadaSelectionModal();
  ensureTacticaGuerraCursorTracking();
  renderAll();
  renderTacticaGuerraNexusCursor();
  const firstUnit = getEmboscadaCurrentUnit(pending);
  log(`Emboscada: coloca el nexo 1 de ${selected.length} para ${CARD_LIBRARY[firstUnit?.cardId]?.name || 'la invocación'} dentro de radio ${EMBOSCADA_RADIUS} de la invasora.`);
  return true;
}

function getEmboscadaDestinationCells(playerId, pending = state.pendingPowerAction) {
  if (pending?.kind !== 'emboscadaDestination') return [];
  const rival = getUnitById(getEnemyPlayerId(playerId), pending.selectedRivalUnitId);
  if (!rival || rival.status === 'restoring') return [];
  const currentUnitId = String(pending.selectedUnitIds?.[Number(pending.currentIndex || 0)] || '');
  const currentUnit = getUnitById(playerId, currentUnitId);
  const used = new Set((pending.destinations || []).map(cell => `${cell.row},${cell.col}`));
  return getCellsInRadius(rival.row, rival.col, EMBOSCADA_RADIUS, false).filter(cell => {
    if (!isInside(cell.row, cell.col) || used.has(`${cell.row},${cell.col}`)) return false;
    const occupiedUnit = [1,2].flatMap(id => state.players?.[id]?.units || []).find(unit => unit && unit.status !== 'restoring' && Number(unit.row)===cell.row && Number(unit.col)===cell.col);
    if (occupiedUnit && String(occupiedUnit.id) !== currentUnitId) return false;
    const occupiedGuardian = [1,2].flatMap(id => state.players?.[id]?.guardians || []).some(g => g && g.active !== false && !g.destroying && Number(g.row)===cell.row && Number(g.col)===cell.col);
    if (occupiedGuardian) return false;
    const occupiedCaster = [1,2].some(id => { const c=state.players?.[id]?.caster; return c && Number(c.row)===cell.row && Number(c.col)===cell.col; });
    if (occupiedCaster) return false;
    const occupiedMarker = [1,2].flatMap(id => state.players?.[id]?.spawnMarkers || []).find(m => m && Number(m.row)===cell.row && Number(m.col)===cell.col);
    if (occupiedMarker && String(occupiedMarker.id || '') !== String(currentUnit?.spawnId || '')) return false;
    return true;
  });
}

async function resolveEmboscadaDestination(playerId, row, col) {
  const pending = state.pendingPowerAction;
  if (pending?.kind !== 'emboscadaDestination' || Number(pending.playerId) !== Number(playerId)) return false;
  const unit = getEmboscadaCurrentUnit(pending);
  if (!unit) return cancelEmboscadaTargeting('La siguiente invocación seleccionada dejó de estar disponible.');
  if (!getEmboscadaDestinationCells(playerId, pending).some(cell => cell.row === row && cell.col === col)) {
    log('Esa casilla no es válida para colocar el nexo de Emboscada.');
    return false;
  }
  pending.destinations = [...(pending.destinations || []), { unitId: unit.id, row, col }];
  const nextIndex = Number(pending.currentIndex || 0) + 1;
  if (nextIndex < pending.selectedUnitIds.length) {
    pending.currentIndex = nextIndex;
    renderAll();
    renderTacticaGuerraNexusCursor();
    const nextUnit = getEmboscadaCurrentUnit(pending);
    log(`Nexo ${nextIndex} colocado. Ahora coloca el nexo ${nextIndex + 1} de ${pending.selectedUnitIds.length} para ${CARD_LIBRARY[nextUnit?.cardId]?.name || 'la siguiente invocación'}.`);
    return true;
  }
  removeTacticaGuerraNexusCursor();
  return finalizeEmboscadaPlan();
}

function applyEmboscadaBond(playerId, unit, rival) {
  if (!unit || !rival) return;
  unit.emboscadaCompleteMobility = true;
  unit.emboscadaTargetPlayerId = Number(rival.owner || getEnemyPlayerId(playerId));
  unit.emboscadaTargetUnitId = rival.id;
  unit.emboscadaSourceCardId = EMBOSCADA_CARD_ID;
}

async function executeEmboscadaResolution(playerId, plan = {}, card = CARD_LIBRARY[EMBOSCADA_CARD_ID]) {
  const enemyId = getEnemyPlayerId(playerId);
  const rival = getUnitById(enemyId, plan.rivalUnitId);
  const selected = Array.isArray(plan.selectedUnitIds) ? plan.selectedUnitIds : [];
  const destinations = Array.isArray(plan.destinations) ? plan.destinations : [];
  const units = selected.map(id => getUnitById(playerId, id)).filter(Boolean);
  if (!rival || rival.status === 'restoring' || !isUnitInOwnSide(playerId, rival) || !units.length || destinations.length < units.length) {
    log('Emboscada se resuelve sin suficientes objetivos válidos.');
    return { type: 'spell', card, spellId: card?.id || EMBOSCADA_CARD_ID };
  }
  applyTacticaGuerraNexusDestinations(playerId, units, destinations);
  renderAll();
  await playTacticaGuerraResolutionFx('EMBOSCADA', 'CERCO TÁCTICO');
  for (let index=0; index<units.length; index+=1) {
    const unit = getUnitById(playerId, units[index].id);
    if (!unit) continue;
    const attackSpent = unitHasAttackSpentThisResolution(unit);
    playTacticaGuerraWaterRestoreFx(unit, index * 130);
    const hadRestoreTime = Object.prototype.hasOwnProperty.call(unit, 'restoreTime');
    const oldRestoreTime = unit.restoreTime;
    unit.restoreTime = 0;
    restoreInvocation(playerId, unit, 'Emboscada');
    if (hadRestoreTime) unit.restoreTime = oldRestoreTime; else delete unit.restoreTime;
    const restored = await waitForInterceptarRestore(playerId, unit.id, 4200);
    const liveRival = getUnitById(enemyId, rival.id);
    if (restored && liveRival && liveRival.status !== 'restoring') {
      applyEmboscadaBond(playerId, restored, liveRival);
      restored.movesLeft = Math.max(0, Number(CARD_LIBRARY[restored.cardId]?.stats?.mov ?? restored.mov ?? 0));
      if (attackSpent) markUnitAttackSpentThisResolution(restored);
      showFloatingTextAt(restored.row, restored.col, 'EMBOSCADA', 'floating-combat buff');
    }
  }
  log(`Emboscada reposiciona ${units.length} invocación${units.length===1?'':'es'}, les concede Movilidad completa y las fija contra ${CARD_LIBRARY[rival.cardId]?.name || 'la invasora'}.`);
  renderAll();
  return { type: 'spell', card, spellId: card?.id || EMBOSCADA_CARD_ID };
}

async function resolveQueuedEmboscadaCast(playerId, item, card = CARD_LIBRARY[EMBOSCADA_CARD_ID]) {
  return executeEmboscadaResolution(playerId, item?.emboscadaPlan || {}, card);
}

async function finalizeEmboscadaPlan() {
  const pending = state.pendingPowerAction;
  if (pending?.kind !== 'emboscadaDestination') return false;
  const playerId = Number(pending.playerId);
  const player = state.players?.[playerId];
  const card = CARD_LIBRARY[pending.cardId || EMBOSCADA_CARD_ID];
  const tab = Number(pending.originTab || 0);
  const slot = Number(pending.originSlot || 0);
  const rival = getUnitById(getEnemyPlayerId(playerId), pending.selectedRivalUnitId);
  const selected = pending.selectedUnitIds || [];
  const destinations = pending.destinations || [];
  if (!player || !card || player.handTabs?.[tab]?.[slot] !== card.id || !rival || selected.length===0 || destinations.length<selected.length) return cancelEmboscadaTargeting('Emboscada se canceló porque la carta o los objetivos dejaron de estar disponibles.');
  if (!payCost(player.resources, { agua: selected.length }, 'agua')) { log(`Necesitas ${selected.length} Agua para resolver Emboscada.`); renderAll(); return false; }
  const plan = { rivalUnitId: rival.id, selectedUnitIds: [...selected], destinations: destinations.map(cell => ({...cell})) };
  const quickDefense = pending.quickDefense === true;
  const fromQuickReactionWindow = pending.fromQuickReactionWindow === true;
  player.handTabs[tab][slot] = null;
  clearSpellbookUseCooldown(playerId, tab, slot);
  markTurnActionCommitted(playerId, 'cast');
  state.pendingPowerAction = null;
  closeEmboscadaSelectionModal();
  removeTacticaGuerraNexusCursor();
  state.infoCard = null; state.selectedCardSlot = null; state.pendingCard = null; state.pendingPlacement = null;
  if (quickDefense) {
    log(`Defensa rápida: Emboscada consume ${selected.length} Agua y se resuelve como instantáneo.`);
    renderAll();
    try { await executeEmboscadaResolution(playerId, plan, card); }
    finally { if (fromQuickReactionWindow) releaseEmboscadaQuickReactionManualTargeting('activated'); }
    return true;
  }
  const caster = state.players?.[playerId]?.caster || {};
  const item = { cardId: card.id, elementId: 'agua', remaining: Math.max(0, Number(card.castPhases || 2)), row: Number(caster.row ?? 0), col: Number(caster.col ?? 0), justAdded: true, introStarted: false, introDone: false, introEndsAt: 0, spawnId: `spell_${Date.now()}_${Math.random().toString(16).slice(2)}`, originTab: tab, originSlot: slot, emboscadaPlan: plan };
  player.castQueue = Array.isArray(player.castQueue) ? player.castQueue : [];
  player.castQueue.push(item);
  player.caster.state = 'casting';
  log(`Emboscada consume ${selected.length} Agua y entra en kasteo durante ${item.remaining} fases.`);
  renderAll();
  return true;
}

function triggerEmboscadaHuntersOnTargetDeath(targetPlayerId, targetUnitId) {
  const hunters = [];
  for (const ownerId of [1,2]) {
    for (const unit of state.players?.[ownerId]?.units || []) {
      if (unit.status === 'restoring') continue;
      if (Number(unit.emboscadaTargetPlayerId) !== Number(targetPlayerId)) continue;
      if (String(unit.emboscadaTargetUnitId || '') !== String(targetUnitId || '')) continue;
      unit.emboscadaCompleteMobility = false;
      unit.emboscadaTargetPlayerId = null;
      unit.emboscadaTargetUnitId = '';
      unit.emboscadaSourceCardId = '';
      hunters.push({ ownerId, unitId: unit.id });
    }
  }
  hunters.forEach((entry, index) => window.setTimeout(() => {
    const hunter = getUnitById(entry.ownerId, entry.unitId);
    if (!hunter || hunter.status === 'restoring') return;
    showFloatingTextAt(hunter.row, hunter.col, 'FIN DE EMBOSCADA', 'floating-combat buff');
    restoreInvocation(entry.ownerId, hunter, 'objetivo de Emboscada eliminado');
  }, 80 + index * 90));
  return hunters.length;
}

function isInterceptarArtimanaMode(playerId) {
  return Number(state.activePlayer) !== Number(playerId);
}

function getInterceptarAlliedCandidates(playerId) {
  return (state.players?.[playerId]?.units || []).filter(unit => unit
    && unit.status !== 'restoring'
    && !unit.restoreAnimating
    && Number(unit.hp ?? 0) > 0);
}

function getInterceptarDestinationCell(playerId, alliedUnit, rivalUnit) {
  if (!alliedUnit || !rivalUnit) return null;
  if (rivalUnit.status === 'restoring' || rivalUnit.restoreAnimating || Number(rivalUnit.hp ?? 0) <= 0) return null;
  if (!isUnitInOwnSide(playerId, rivalUnit)) return null;
  const row = Number(rivalUnit.row) + (Number(playerId) === 1 ? 1 : -1);
  const col = Number(rivalUnit.col);
  if (!isInside(row, col)) return null;
  const virtualCell = { row, col };
  if (!isUnitInOwnSide(playerId, virtualCell)) return null;

  const occupiedByOtherUnit = [1, 2].some(ownerId => (state.players?.[ownerId]?.units || []).some(unit => unit
    && unit.status !== 'restoring'
    && Number(unit.row) === row
    && Number(unit.col) === col
    && !(Number(ownerId) === Number(playerId) && String(unit.id) === String(alliedUnit.id))));
  if (occupiedByOtherUnit) return null;

  const occupiedByOtherMarker = [1, 2].some(ownerId => (state.players?.[ownerId]?.spawnMarkers || []).some(marker => marker
    && Number(marker.row) === row
    && Number(marker.col) === col
    && !(Number(ownerId) === Number(playerId) && String(marker.id) === String(alliedUnit.spawnId))));
  if (occupiedByOtherMarker) return null;

  const occupiedByStructure = [1, 2].some(ownerId => (state.players?.[ownerId]?.guardians || []).some(guardian => guardian
    && guardian.active !== false
    && Number(guardian.row) === row
    && Number(guardian.col) === col));
  if (occupiedByStructure) return null;
  return { row, col };
}

function getInterceptarRivalCandidates(playerId, alliedUnit = null) {
  const enemyPlayerId = getEnemyPlayerId(playerId);
  const alliedCandidates = alliedUnit ? [alliedUnit] : getInterceptarAlliedCandidates(playerId);
  return (state.players?.[enemyPlayerId]?.units || []).filter(rival => {
    if (!canPlayerDirectlyTargetInvocation(playerId, enemyPlayerId, rival) || rival.restoreAnimating) return false;
    if (!isUnitInOwnSide(playerId, rival)) return false;
    return alliedCandidates.some(ally => Boolean(getInterceptarDestinationCell(playerId, ally, rival)));
  });
}

function getInterceptarCastAvailability(playerId) {
  const realtimeQuick = isRealtimePlayStyle() && Boolean(state?.realtime?.active);
  const ownTurn = Number(state.activePlayer) === Number(playerId);
  const artimana = realtimeQuick ? true : !ownTurn;
  if (!realtimeQuick && ownTurn && currentPhase().id !== 'casting') {
    return { available: false, message: 'Interceptar solo puede usarse en tu fase de Kasteo o mediante Artimaña durante el turno rival.', artimana, allies: [], rivals: [] };
  }
  if (!isCasterInOwnSide(playerId)) {
    return { available: false, message: 'El Kaster no puede usar Interceptar desde la zona enemiga.', artimana, allies: [], rivals: [] };
  }
  const card = CARD_LIBRARY[INTERCEPTAR_CARD_ID];
  const userStatus = card ? canCasterUseSpell(playerId, card) : { ok: false, message: 'Interceptar no está disponible.' };
  if (!userStatus.ok) return { available: false, message: userStatus.message, artimana, allies: [], rivals: [] };
  const resources = state.players?.[playerId]?.resources || [];
  if (!canPayCost(resources, { agua: 2 }, 'agua')) {
    return { available: false, message: 'Interceptar requiere 2 elementos de Agua.', artimana, allies: [], rivals: [] };
  }
  const allies = getInterceptarAlliedCandidates(playerId)
    .filter(ally => getInterceptarRivalCandidates(playerId, ally).length > 0);
  if (!allies.length) {
    const anyAllies = getInterceptarAlliedCandidates(playerId);
    if (!anyAllies.length) return { available: false, message: 'Interceptar requiere una invocación aliada activa en arena.', artimana, allies: [], rivals: [] };
    return { available: false, message: 'No hay una invocación rival invasora con una casilla frontal libre para interceptarla.', artimana, allies: [], rivals: [] };
  }
  const rivals = getInterceptarRivalCandidates(playerId);
  if (!rivals.length) return { available: false, message: 'Interceptar requiere una invocación rival dentro de tu lado de la arena.', artimana, allies: [], rivals: [] };
  return { available: true, message: '', artimana, allies, rivals };
}

function prepareInterceptarArtimanaManualTargeting() {
  stopQuickReactionDecisionCountdown();
  hideQuickReactionInputShield({ force: true });
  hideQuickReactionWindowForPlayer(LOCAL_PLAYER_ID);
  clearQuickReactionExecutionLayer();
  clearQuickReactionCommandDock();
  if (els.quickReactionModal) {
    els.quickReactionModal.classList.remove('visible', 'quick-reaction-modal-executing');
    els.quickReactionModal.setAttribute('aria-hidden', 'true');
  }
  if (els.quickReactionModalList) els.quickReactionModalList.innerHTML = '';
  resetQuickReactionModalCardLayout();
  clearInterval(closeQuickReactionModal.timer);
  if (state.quickReactionWindow) {
    state.quickReactionWindow.locked = true;
    state.quickReactionWindow.active = true;
    state.quickReactionWindow.executing = true;
    state.quickReactionWindow.manualInterceptarTargeting = true;
  }
  syncLocalQuickReactionGameplayPause();
}

function releaseInterceptarArtimanaManualTargeting(outcome = 'cancelled') {
  if (state.quickReactionWindow) delete state.quickReactionWindow.manualInterceptarTargeting;
  hideQuickReactionInputShield({ force: true });
  return forceReleaseQuickReactionManualPowerFlow(outcome);
}

function closeInterceptarSelectionModal() {
  document.getElementById('interceptarSelectionOverlay')?.remove();
}

function cancelInterceptarTargeting(message = 'Interceptar fue cancelado.') {
  const pending = state.pendingPowerAction;
  if (!['interceptarAlliedSelection', 'interceptarRivalSelection'].includes(pending?.kind)) return false;
  const fromQuickReactionWindow = pending.fromQuickReactionWindow === true;
  state.pendingPowerAction = null;
  closeInterceptarSelectionModal();
  if (fromQuickReactionWindow) releaseInterceptarArtimanaManualTargeting('cancelled');
  log(message);
  renderAll();
  return true;
}

function beginInterceptarTargeting(playerId, cardId, originTab, originSlot) {
  const availability = getInterceptarCastAvailability(playerId);
  if (!availability.available) {
    log(availability.message);
    renderAll();
    return false;
  }
  state.selectedMover = null;
  state.selectedTarget = null;
  state.pendingPlacement = null;
  state.pendingCard = null;
  const fromQuickReactionWindow = availability.artimana === true && Boolean(
    state.quickReactionWindow?.phaseIntro
    || state.quickReactionWindow?.locked
    || state.quickReactionWindow?.active
    || state.quickReactionWindow?.executing
    || els.quickReactionWindow?.classList?.contains('visible')
    || els.quickReactionModal?.classList?.contains('visible')
    || document.getElementById('quickReactionCommandDock')?.classList?.contains('visible')
    || document.getElementById('quickReactionInputShield')?.classList?.contains('visible')
  );
  if (fromQuickReactionWindow) prepareInterceptarArtimanaManualTargeting();
  else if (availability.artimana === true) hideQuickReactionInputShield({ force: true });
  state.pendingPowerAction = {
    kind: 'interceptarAlliedSelection',
    playerId,
    cardId: cardId || INTERCEPTAR_CARD_ID,
    originTab: Math.max(0, Number(originTab) || 0),
    originSlot: Math.max(0, Number(originSlot) || 0),
    artimana: availability.artimana === true,
    fromQuickReactionWindow,
    selectedAlliedUnitId: null,
    selectedRivalUnitId: null,
  };
  log(`Interceptar: selecciona una invocación aliada.${availability.artimana ? ' Artimaña está activa.' : ''}`);
  renderAll();
  renderInterceptarAlliedSelectionModal();
  return true;
}

function createInterceptarCandidateButton(playerId, unit, options = {}) {
  const card = CARD_LIBRARY[unit?.cardId] || null;
  const elementId = getEffectiveCardElementId(card, playerId);
  const element = getElementById(elementId);
  const button = document.createElement('button');
  button.type = 'button';
  button.className = 'tactica-guerra-selection-unit interceptar-selection-unit';
  button.style.setProperty('--tactica-target-color', element?.color || '#49d6dd');
  button.innerHTML = `
    <span class="tactica-guerra-selection-order">${options.orderLabel || ''}</span>
    <img class="tactica-guerra-selection-token" src="${card?.tokenImage || card?.artImage || card?.thumbnailImage || 'assets/invocation-token.png'}" alt="">
    <span class="tactica-guerra-selection-copy"><strong>${card?.name || 'Invocación'}</strong><small>${coordLabel(unit.row, unit.col)} · Vida ${Number(unit.hp ?? card?.stats?.life ?? 0)}/${Number(unit.maxHp ?? card?.stats?.life ?? 0)}</small></span>
    <span class="tactica-guerra-selection-element"><img src="${getElementCostIcon(elementId)}" alt="${element?.label || elementId}"><b>${options.roleLabel || element?.label || elementId}</b><small>${options.detailLabel || ''}</small></span>`;
  return button;
}

function renderInterceptarAlliedSelectionModal() {
  const pending = state.pendingPowerAction;
  if (!pending || pending.kind !== 'interceptarAlliedSelection') {
    closeInterceptarSelectionModal();
    return;
  }
  closeInterceptarSelectionModal();
  const playerId = Number(pending.playerId);
  const card = CARD_LIBRARY[pending.cardId || INTERCEPTAR_CARD_ID];
  const candidates = getInterceptarAlliedCandidates(playerId).filter(ally => getInterceptarRivalCandidates(playerId, ally).length > 0);
  const water = getElementById('agua');
  const overlay = document.createElement('section');
  overlay.id = 'interceptarSelectionOverlay';
  overlay.className = 'tactica-guerra-selection-overlay interceptar-selection-overlay open';
  overlay.style.setProperty('--tactica-water-color', water?.color || '#49d6dd');
  overlay.style.setProperty('--tactica-water-accent', '#65efcf');
  overlay.setAttribute('aria-modal', 'true');
  overlay.setAttribute('role', 'dialog');
  overlay.innerHTML = `<div class="tactica-guerra-selection-shell interceptar-selection-shell">
    <button type="button" class="tactica-guerra-selection-close" aria-label="Cerrar">×</button>
    <header>
      <img src="${card?.spellIcon || card?.thumbnailImage || 'assets/spell-interceptar.webp'}" alt="">
      <div><strong>Interceptar</strong><span>Selecciona tu invocación</span></div>
    </header>
    <p class="tactica-guerra-selection-help">Selecciona una sola invocación aliada activa. Después elegirás la invocación rival que haya ingresado a tu lado de la arena.${pending.artimana ? ' <strong>Artimaña:</strong> se resolverá como instantáneo.' : ' <strong>Kasteo normal:</strong> 2 fases.'}</p>
    <div class="tactica-guerra-selection-list"></div>
    <footer>
      <span class="tactica-guerra-selection-count">Costo: 2 Agua</span>
      <button type="button" class="tactica-guerra-selection-cancel">Cancelar</button>
    </footer>
  </div>`;
  appendRokUiNode(overlay);
  const list = overlay.querySelector('.tactica-guerra-selection-list');
  candidates.forEach(unit => {
    const button = createInterceptarCandidateButton(playerId, unit, { roleLabel: 'ALIADA', detailLabel: 'Seleccionar' });
    button.addEventListener('click', event => {
      event.preventDefault();
      event.stopPropagation();
      selectInterceptarAlliedUnit(unit.id);
    });
    list?.appendChild(button);
  });
  overlay.addEventListener('pointerdown', event => event.stopPropagation());
  overlay.querySelector('.tactica-guerra-selection-close')?.addEventListener('click', () => cancelInterceptarTargeting());
  overlay.querySelector('.tactica-guerra-selection-cancel')?.addEventListener('click', () => cancelInterceptarTargeting());
}

function selectInterceptarAlliedUnit(unitId) {
  const pending = state.pendingPowerAction;
  if (!pending || pending.kind !== 'interceptarAlliedSelection') return false;
  const playerId = Number(pending.playerId);
  const allied = getUnitById(playerId, unitId);
  if (!allied || !getInterceptarAlliedCandidates(playerId).some(unit => String(unit.id) === String(unitId))) return false;
  const rivals = getInterceptarRivalCandidates(playerId, allied);
  if (!rivals.length) {
    log('Esa invocación ya no tiene un rival invasor válido para interceptar.');
    renderInterceptarAlliedSelectionModal();
    return false;
  }
  pending.selectedAlliedUnitId = allied.id;
  if (rivals.length === 1) return selectInterceptarRivalUnit(rivals[0].id, { automatic: true });
  pending.kind = 'interceptarRivalSelection';
  renderInterceptarRivalSelectionModal();
  return true;
}

function renderInterceptarRivalSelectionModal() {
  const pending = state.pendingPowerAction;
  if (!pending || pending.kind !== 'interceptarRivalSelection') {
    closeInterceptarSelectionModal();
    return;
  }
  closeInterceptarSelectionModal();
  const playerId = Number(pending.playerId);
  const allied = getUnitById(playerId, pending.selectedAlliedUnitId);
  const card = CARD_LIBRARY[pending.cardId || INTERCEPTAR_CARD_ID];
  const candidates = getInterceptarRivalCandidates(playerId, allied);
  const water = getElementById('agua');
  const overlay = document.createElement('section');
  overlay.id = 'interceptarSelectionOverlay';
  overlay.className = 'tactica-guerra-selection-overlay interceptar-selection-overlay open';
  overlay.style.setProperty('--tactica-water-color', water?.color || '#49d6dd');
  overlay.style.setProperty('--tactica-water-accent', '#65efcf');
  overlay.setAttribute('aria-modal', 'true');
  overlay.setAttribute('role', 'dialog');
  overlay.innerHTML = `<div class="tactica-guerra-selection-shell interceptar-selection-shell">
    <button type="button" class="tactica-guerra-selection-close" aria-label="Cerrar">×</button>
    <header>
      <img src="${card?.spellIcon || card?.thumbnailImage || 'assets/spell-interceptar.webp'}" alt="">
      <div><strong>Interceptar</strong><span>Selecciona la invocación rival</span></div>
    </header>
    <p class="tactica-guerra-selection-help">El nuevo nexo de tu invocación aparecerá automáticamente en la casilla inmediatamente inferior, frente al rival seleccionado.</p>
    <div class="tactica-guerra-selection-list"></div>
    <footer>
      <span class="tactica-guerra-selection-count">1 invocación aliada seleccionada</span>
      <button type="button" class="tactica-guerra-selection-cancel">Cancelar</button>
    </footer>
  </div>`;
  appendRokUiNode(overlay);
  const list = overlay.querySelector('.tactica-guerra-selection-list');
  candidates.forEach(unit => {
    const destination = getInterceptarDestinationCell(playerId, allied, unit);
    const button = createInterceptarCandidateButton(getEnemyPlayerId(playerId), unit, {
      roleLabel: 'RIVAL',
      detailLabel: destination ? `Nexo → ${coordLabel(destination.row, destination.col)}` : 'Sin casilla válida',
    });
    button.classList.add('interceptar-rival-candidate');
    button.addEventListener('click', event => {
      event.preventDefault();
      event.stopPropagation();
      selectInterceptarRivalUnit(unit.id);
    });
    list?.appendChild(button);
  });
  overlay.addEventListener('pointerdown', event => event.stopPropagation());
  overlay.querySelector('.tactica-guerra-selection-close')?.addEventListener('click', () => cancelInterceptarTargeting());
  overlay.querySelector('.tactica-guerra-selection-cancel')?.addEventListener('click', () => cancelInterceptarTargeting());
}

async function selectInterceptarRivalUnit(unitId, options = {}) {
  const pending = state.pendingPowerAction;
  if (!pending || !['interceptarAlliedSelection', 'interceptarRivalSelection'].includes(pending.kind)) return false;
  const playerId = Number(pending.playerId);
  const allied = getUnitById(playerId, pending.selectedAlliedUnitId);
  const rival = getUnitById(getEnemyPlayerId(playerId), unitId);
  const destination = getInterceptarDestinationCell(playerId, allied, rival);
  if (!allied || !rival || !destination) {
    log('El objetivo rival ya no puede ser interceptado porque su casilla frontal dejó de estar disponible.');
    if (pending.kind === 'interceptarRivalSelection') renderInterceptarRivalSelectionModal();
    else renderInterceptarAlliedSelectionModal();
    return false;
  }
  pending.selectedRivalUnitId = rival.id;
  pending.destination = { ...destination };
  if (options.automatic) log(`${CARD_LIBRARY[rival.cardId]?.name || 'La única invocación rival'} se selecciona automáticamente como objetivo.`);
  return finalizeInterceptarPlan();
}

function applyInterceptarNexusDestination(playerId, unit, destination) {
  if (!unit || !destination) return false;
  const marker = (state.players?.[playerId]?.spawnMarkers || []).find(item => item.id === unit.spawnId);
  if (marker) {
    marker.row = destination.row;
    marker.col = destination.col;
  } else {
    unit.restoreRow = destination.row;
    unit.restoreCol = destination.col;
  }
  clearUnitEngagement(playerId, unit.id);
  return true;
}

async function waitForInterceptarRestore(playerId, unitId, timeoutMs = 3600) {
  const started = Date.now();
  while (Date.now() - started < timeoutMs) {
    const unit = getUnitById(playerId, unitId);
    if (!unit) return null;
    if (!unit.restoreAnimating && unit.status !== 'restoring') return unit;
    await sleep(70);
  }
  return getUnitById(playerId, unitId);
}

async function executeInterceptarResolution(playerId, plan = {}, card = CARD_LIBRARY[INTERCEPTAR_CARD_ID]) {
  const allied = getUnitById(playerId, plan.alliedUnitId);
  const enemyPlayerId = getEnemyPlayerId(playerId);
  const rival = getUnitById(enemyPlayerId, plan.rivalUnitId);
  const destination = getInterceptarDestinationCell(playerId, allied, rival);
  if (!allied || !rival || !destination) {
    log('Interceptar se resuelve sin objetivo válido: el invasor o la casilla frontal dejaron de estar disponibles.');
    return { type: 'spell', card, spellId: card?.id || INTERCEPTAR_CARD_ID };
  }

  // La restauración especial de Interceptar no concede un ataque nuevo.
  // Conservamos explícitamente el consumo de ataque de ambas invocaciones
  // antes de mover el nexo y restaurar a la aliada.
  const alliedAttackWasSpent = unitHasAttackSpentThisResolution(allied);
  const rivalAttackWasSpent = unitHasAttackSpentThisResolution(rival);

  applyInterceptarNexusDestination(playerId, allied, destination);
  renderAll();
  await playTacticaGuerraResolutionFx('INTERCEPTAR', 'INTERCEPCIÓN INMEDIATA');
  playTacticaGuerraWaterRestoreFx(allied, 0);
  showFloatingTextAt(allied.row, allied.col, 'INTERCEPTAR', 'floating-combat buff');

  const hadRestoreTime = Object.prototype.hasOwnProperty.call(allied, 'restoreTime');
  const previousRestoreTime = allied.restoreTime;
  allied.restoreTime = 0;
  restoreInvocation(playerId, allied, 'Interceptar');
  if (hadRestoreTime) allied.restoreTime = previousRestoreTime;
  else delete allied.restoreTime;

  const restored = await waitForInterceptarRestore(playerId, allied.id);
  const liveRival = getUnitById(enemyPlayerId, rival.id);
  if (restored && alliedAttackWasSpent) markUnitAttackSpentThisResolution(restored);
  if (liveRival && rivalAttackWasSpent) markUnitAttackSpentThisResolution(liveRival);
  if (restored && liveRival && restored.status !== 'restoring' && liveRival.status !== 'restoring') {
    showFloatingTextAt(restored.row, restored.col, 'INTERCEPCIÓN', 'floating-combat buff');
    await enterInvocationCombat(
      { type: 'invocation', playerId, unit: restored, card: CARD_LIBRARY[restored.cardId] },
      { type: 'invocation', playerId: enemyPlayerId, unitId: liveRival.id, unit: liveRival, row: liveRival.row, col: liveRival.col },
      {
        respectAttackSpent: true,
        markAttacksSpent: true,
        resolutionReason: 'Interceptar',
      }
    );
  } else {
    log('Interceptar reposicionó el nexo, pero el combate inmediato no pudo iniciarse porque uno de los objetivos dejó la arena.');
  }
  renderAll();
  return { type: 'spell', card, spellId: card?.id || INTERCEPTAR_CARD_ID };
}

async function resolveQueuedInterceptarCast(playerId, item, card = CARD_LIBRARY[INTERCEPTAR_CARD_ID]) {
  return executeInterceptarResolution(playerId, item?.interceptarPlan || {}, card);
}

async function finalizeInterceptarPlan() {
  const pending = state.pendingPowerAction;
  if (!pending || !['interceptarAlliedSelection', 'interceptarRivalSelection'].includes(pending.kind)) return false;
  const playerId = Number(pending.playerId);
  const player = state.players?.[playerId];
  const card = CARD_LIBRARY[pending.cardId || INTERCEPTAR_CARD_ID];
  const tab = Number(pending.originTab || 0);
  const slot = Number(pending.originSlot || 0);
  const allied = getUnitById(playerId, pending.selectedAlliedUnitId);
  const rival = getUnitById(getEnemyPlayerId(playerId), pending.selectedRivalUnitId);
  const destination = getInterceptarDestinationCell(playerId, allied, rival);
  if (!player || !card || player.handTabs?.[tab]?.[slot] !== card.id || !allied || !rival || !destination) {
    return cancelInterceptarTargeting('Interceptar se canceló porque la carta o los objetivos dejaron de estar disponibles.');
  }
  if (!payCost(player.resources, { agua: 2 }, 'agua')) {
    log('No tienes 2 elementos de Agua para usar Interceptar.');
    renderAll();
    return false;
  }

  const artimana = pending.artimana === true;
  const fromQuickReactionWindow = pending.fromQuickReactionWindow === true;
  const plan = { alliedUnitId: allied.id, rivalUnitId: rival.id, destination: { ...destination } };
  player.handTabs[tab][slot] = null;
  clearSpellbookUseCooldown(playerId, tab, slot);
  if (Number(state.activePlayer) === playerId) markTurnActionCommitted(playerId, 'cast');
  state.infoCard = null;
  state.selectedCardSlot = null;
  state.pendingCard = null;
  state.pendingPlacement = null;
  state.pendingPowerAction = null;
  closeInterceptarSelectionModal();

  if (artimana) {
    log('Artimaña: Interceptar consume 2 Agua y se resuelve como instantáneo durante el turno rival.');
    renderAll();
    try {
      await executeInterceptarResolution(playerId, plan, card);
    } finally {
      if (fromQuickReactionWindow) releaseInterceptarArtimanaManualTargeting('activated');
    }
    return true;
  }

  const caster = state.players?.[playerId]?.caster || {};
  const castItem = {
    cardId: card.id,
    elementId: 'agua',
    remaining: Math.max(0, Number(card.castPhases || 2)),
    row: Number(caster.row ?? 0),
    col: Number(caster.col ?? 0),
    justAdded: true,
    introStarted: false,
    introDone: false,
    introEndsAt: 0,
    spawnId: `spell_${Date.now()}_${Math.random().toString(16).slice(2)}`,
    originTab: tab,
    originSlot: slot,
    interceptarPlan: plan,
  };
  player.castQueue = Array.isArray(player.castQueue) ? player.castQueue : [];
  player.castQueue.push(castItem);
  player.caster.state = 'casting';
  const queuePosition = player.castQueue.length;
  log(queuePosition === 1
    ? 'Interceptar consume 2 Agua y entra a zona de kasteo. Kasteo activo: 2 fases.'
    : `Interceptar consume 2 Agua y entra a cola de kasteo. Espera ${queuePosition - 1} carta${queuePosition === 2 ? '' : 's'} antes de comenzar.`);
  renderAll();
  return true;
}

function getEligibleDespliegueAnticipadoTargets(playerId) {
  return (state.players?.[playerId]?.units || []).filter(unit => unit
    && unit.status !== 'restoring'
    && unitHasCardQuality(unit, 'caudillo'));
}

function getQueuedDespliegueAnticipadoCount(playerId) {
  return (state.players?.[playerId]?.castQueue || []).filter(item => item?.cardId === DESPLIEGUE_ANTICIPADO_CARD_ID).length;
}

function getDespliegueAnticipadoCommittedCount(playerId, options = {}) {
  const active = getActiveDespliegueAnticipadoLinks(playerId).length;
  const queued = getQueuedDespliegueAnticipadoCount(playerId);
  const includePending = options.includePending !== false;
  const pending = includePending
    && state.pendingPowerAction?.kind === 'despliegueAnticipadoTarget'
    && Number(state.pendingPowerAction.playerId) === Number(playerId)
      ? 1
      : 0;
  return active + queued + pending;
}

function getDespliegueAnticipadoCastAvailability(playerId) {
  const targets = getEligibleDespliegueAnticipadoTargets(playerId);
  const committed = getDespliegueAnticipadoCommittedCount(playerId);
  if (!targets.length) {
    return {
      available: false,
      reason: 'noCaudillo',
      message: 'Despliegue anticipado requiere al menos una invocación Caudillo aliada activa en arena.',
      targets,
      committed,
    };
  }
  if (committed >= DESPLIEGUE_ANTICIPADO_MAX_ACTIVE_LINKS) {
    return {
      available: false,
      reason: 'maxInstances',
      message: 'Ya hay dos instancias de Despliegue anticipado activas o en kasteo.',
      targets,
      committed,
    };
  }
  return { available: true, reason: '', message: '', targets, committed };
}

function restoreSpellCardToSpellbook(playerId, cardId, originTab = 0, originSlot = 0) {
  const player = state.players?.[playerId];
  if (!player || !cardId) return null;
  const tabs = Array.isArray(player.handTabs) ? player.handTabs : (player.handTabs = [[], [], []]);
  while (tabs.length < 3) tabs.push([]);
  const preferredTab = Math.max(0, Number(originTab) || 0);
  const preferredSlot = Math.max(0, Number(originSlot) || 0);
  if (!Array.isArray(tabs[preferredTab])) tabs[preferredTab] = Array(12).fill(null);
  while (tabs[preferredTab].length < 12) tabs[preferredTab].push(null);
  let tab = preferredTab;
  let slot = preferredSlot;
  if (tabs[tab][slot]) {
    let found = null;
    for (let t = 0; t < tabs.length && !found; t++) {
      while (tabs[t].length < 12) tabs[t].push(null);
      const free = tabs[t].findIndex(value => !value);
      if (free >= 0) found = { tab: t, slot: free };
    }
    if (found) ({ tab, slot } = found);
  }
  tabs[tab][slot] = cardId;
  if (Number(playerId) === Number(LOCAL_PLAYER_ID)) renderCards();
  return { tab, slot };
}

function getAbilityCardEquippedEntries(unit) {
  const learned = getUnitLearnedAbilityEntries(unit);
  const temporary = Array.isArray(unit?.temporaryAbilities)
    ? unit.temporaryAbilities.filter(entry => typeof entry === 'object' && entry?.sourceType === 'abilityCard' && entry?.sourceCardId)
    : [];
  return [...learned, ...temporary];
}

function getUnitAbilitySlotStatus(unit) {
  const card = CARD_LIBRARY[unit?.cardId];
  const capacity = Math.max(0, Math.floor(Number(card?.abilitySlots) || 0));
  const nativeCount = Array.isArray(card?.abilities) ? card.abilities.filter(Boolean).length : 0;
  const learnedCount = getAbilityCardEquippedEntries(unit).length;
  const used = Math.max(0, nativeCount + learnedCount);
  return { capacity, used, free: Math.max(0, capacity - used) };
}

function isEligibleShirahadoriAbilityUser(playerId, unit) {
  if (!unitMeetsShirahadoriUserRequirements(playerId, unit)) return false;
  if (unitHasAbility(unit, SHIRAHADORI_ABILITY_ID)) return false;
  return getUnitAbilitySlotStatus(unit).free > 0;
}

function getEligibleShirahadoriAbilityUsers(playerId) {
  return (state.players?.[playerId]?.units || []).filter(unit => isEligibleShirahadoriAbilityUser(playerId, unit));
}

function getShirahadoriAbilityCastAvailability(playerId) {
  const targets = getEligibleShirahadoriAbilityUsers(playerId);
  if (!targets.length) {
    return {
      available: false,
      targets,
      message: 'Shirahadori requiere una invocación aliada activa que cumpla Invocación → Guerrero o Asesino → Espada compatible → Cuerpo a cuerpo, sin Shirahadori y con un espacio de habilidad disponible. El arma base nunca cuenta.',
    };
  }
  return { available: true, targets, message: '' };
}

function cancelShirahadoriAbilityTargeting(message = 'Selección de Shirahadori cancelada.') {
  if (state.pendingPowerAction?.kind !== 'shirahadoriAbilityTarget') return false;
  state.pendingPowerAction = null;
  log(message);
  renderAll();
  return true;
}

function beginShirahadoriAbilityTargeting(playerId, cardId, originTab, originSlot) {
  const availability = getShirahadoriAbilityCastAvailability(playerId);
  if (!availability.available) {
    log(availability.message);
    renderAll();
    return false;
  }
  state.selectedMover = null;
  state.selectedTarget = null;
  state.pendingPlacement = null;
  state.pendingCard = null;
  state.pendingPowerAction = {
    kind: 'shirahadoriAbilityTarget',
    stage: 'equip',
    playerId: Number(playerId),
    cardId: cardId || SHIRAHADORI_ABILITY_CARD_ID,
    originTab: Math.max(0, Number(originTab) || 0),
    originSlot: Math.max(0, Number(originSlot) || 0),
  };
  log('Shirahadori: selecciona una invocación que cumpla Guerrero/Asesino → Espada compatible → Cuerpo a cuerpo. El arma base nunca habilita la técnica.');
  renderAll();
  return true;
}

function resolveShirahadoriAbilityTarget(playerId, unitId) {
  const pending = state.pendingPowerAction;
  if (!pending || pending.kind !== 'shirahadoriAbilityTarget' || Number(pending.playerId) !== Number(playerId)) return false;
  const target = getUnitById(playerId, unitId);
  if (!isEligibleShirahadoriAbilityUser(playerId, target)) {
    log('Shirahadori solo puede aprenderla una invocación válida con espacio de habilidad que cumpla Guerrero/Asesino → Espada compatible → Cuerpo a cuerpo. El arma base queda excluida.');
    renderAll();
    return false;
  }
  const player = state.players?.[playerId];
  const tab = Math.max(0, Number(pending.originTab) || 0);
  const slot = Math.max(0, Number(pending.originSlot) || 0);
  const cardId = pending.cardId || SHIRAHADORI_ABILITY_CARD_ID;
  if (!player || player.handTabs?.[tab]?.[slot] !== cardId) {
    state.pendingPowerAction = null;
    log('Shirahadori ya no está disponible en ese espacio del Spellbook.');
    renderAll();
    return false;
  }

  player.handTabs[tab][slot] = null;
  clearSpellbookUseCooldown(playerId, tab, slot);
  target.learnedAbilities = normalizeLearnedAbilityEntries([
    ...getUnitLearnedAbilityEntries(target),
    {
      id: SHIRAHADORI_ABILITY_ID,
      sourceType: 'learnedAbility',
      sourceCardId: cardId,
      sourceName: 'Shirahadori',
      spellbookCooldown: 3,
      learnedAt: Date.now(),
    },
  ]);
  state.pendingPowerAction = null;
  const targetName = CARD_LIBRARY[target.cardId]?.name || 'la invocación';
  showFloatingTextAt(target.row, target.col, 'SHIRAHADORI', 'floating-combat buff');
  log(`${targetName} aprende Shirahadori permanentemente. La carta se consume y añade +3 a su Estasis de Spellbook.`);
  renderAll();
  return true;
}

function endDespliegueAnticipadoLink(link, reason = 'el Caudillo dejó la arena') {
  if (!link) return false;
  state.activeSpellLinks = (state.activeSpellLinks || []).filter(item => String(item.id) !== String(link.id));
  log(`Despliegue anticipado termina porque ${reason}. El hechizo ya fue consumido y no regresa al Spellbook.`);
  return true;
}

function endDespliegueAnticipadoLinksForTarget(playerId, unitId, reason = 'el Caudillo dejó la arena') {
  const links = (state.activeSpellLinks || []).filter(link => link?.type === DESPLIEGUE_ANTICIPADO_POWER_ID
    && Number(link.playerId) === Number(playerId)
    && String(link.targetUnitId) === String(unitId));
  links.forEach(link => endDespliegueAnticipadoLink(link, reason));
  return links.length;
}

function cleanupInvalidDespliegueAnticipadoLinks() {
  const links = [...(state.activeSpellLinks || [])];
  links.forEach(link => {
    if (link?.type !== DESPLIEGUE_ANTICIPADO_POWER_ID) return;
    const target = getUnitById(Number(link.playerId), link.targetUnitId);
    if (!target || target.status === 'restoring' || !unitHasCardQuality(target, 'caudillo')) {
      endDespliegueAnticipadoLink(link, 'el objetivo ya no está activo en arena');
    }
  });
}

function cancelDespliegueAnticipadoTargeting(message = 'Selección de Despliegue anticipado cancelada.') {
  const pending = state.pendingPowerAction;
  if (pending?.kind !== 'despliegueAnticipadoTarget') return false;
  state.pendingPowerAction = null;
  log(message);
  renderAll();
  return true;
}

function beginDespliegueAnticipadoTargeting(playerId, cardId, originTab, originSlot) {
  const availability = getDespliegueAnticipadoCastAvailability(playerId);
  if (!availability.available) {
    log(availability.message);
    renderAll();
    return false;
  }
  // La selección del Caudillo es un paso previo al pago y al kasteo.
  // Se limpian selecciones de combate para que ninguna capa anterior tape
  // el foil, el punto amarillo o intercepte el clic del objetivo.
  state.selectedMover = null;
  state.selectedTarget = null;
  state.pendingPlacement = null;
  state.pendingCard = null;
  state.pendingPowerAction = {
    kind: 'despliegueAnticipadoTarget',
    stage: 'precast',
    playerId,
    cardId: cardId || DESPLIEGUE_ANTICIPADO_CARD_ID,
    originTab: Math.max(0, Number(originTab) || 0),
    originSlot: Math.max(0, Number(originSlot) || 0),
  };
  log('Despliegue anticipado: selecciona una invocación Caudillo aliada resaltada. El costo se pagará después de confirmar el objetivo.');
  renderAll();
  return true;
}

function resolveDespliegueAnticipadoTarget(playerId, unitId) {
  const pending = state.pendingPowerAction;
  if (!pending || pending.kind !== 'despliegueAnticipadoTarget' || Number(pending.playerId) !== Number(playerId)) return false;
  const target = getUnitById(playerId, unitId);
  const committedWithoutPending = getDespliegueAnticipadoCommittedCount(playerId, { includePending: false });
  if (!target || target.status === 'restoring' || !unitHasCardQuality(target, 'caudillo')) {
    log('Despliegue anticipado requiere una invocación Caudillo aliada activa.');
    renderAll();
    return false;
  }
  if (committedWithoutPending >= DESPLIEGUE_ANTICIPADO_MAX_ACTIVE_LINKS) {
    log('Ya existen dos instancias activas o en kasteo de Despliegue anticipado.');
    state.pendingPowerAction = null;
    renderAll();
    return false;
  }

  const player = state.players?.[playerId];
  const card = CARD_LIBRARY[pending.cardId || DESPLIEGUE_ANTICIPADO_CARD_ID];
  const tab = Math.max(0, Number(pending.originTab) || 0);
  const slot = Math.max(0, Number(pending.originSlot) || 0);
  if (!player || !card || player.handTabs?.[tab]?.[slot] !== card.id) {
    state.pendingPowerAction = null;
    log('Despliegue anticipado ya no está disponible en ese espacio del Spellbook.');
    renderAll();
    return false;
  }

  state.pendingPowerAction = null;
  state.selectedCardSlot = slot;
  state.pendingCard = { cardId: card.id, slotIndex: slot, tab, targetUnitId: target.id };
  const caster = player.caster;
  const row = Math.max(0, Math.min(15, Number(caster?.row ?? 0) + (Number(playerId) === 1 ? -1 : 1)));
  const col = Number(caster?.col ?? 0);
  if (!isInside(row, col)) {
    clearPendingCast();
    log(`No hay una casilla de referencia válida para preparar ${card.name}.`);
    renderAll();
    return false;
  }
  state.pendingPlacement = { row, col, key: 'auto', targetUnitId: target.id };
  log(`${CARD_LIBRARY[target.cardId]?.name || 'El Caudillo'} fue elegido. Ahora se paga el costo y comienza el kasteo de ${card.name}.`);
  confirmCast();
  return true;
}

function resolveDespliegueAnticipadoCast(playerId, item, card) {
  const target = getUnitById(playerId, item?.targetUnitId);
  if (!target || target.status === 'restoring' || !unitHasCardQuality(target, 'caudillo')) {
    log('Despliegue anticipado no puede vincularse: el Caudillo seleccionado dejó de estar activo durante el kasteo. El hechizo se consume sin crear vínculo.');
    renderAll();
    return false;
  }
  const activeLinks = getActiveDespliegueAnticipadoLinks(playerId);
  if (activeLinks.length >= DESPLIEGUE_ANTICIPADO_MAX_ACTIVE_LINKS) {
    log('Despliegue anticipado no puede vincularse: ya existen dos instancias activas. El hechizo se consume sin crear vínculo.');
    renderAll();
    return false;
  }
  const link = {
    id: `despliegue_${Date.now()}_${Math.random().toString(16).slice(2)}`,
    type: DESPLIEGUE_ANTICIPADO_POWER_ID,
    cardId: card?.id || DESPLIEGUE_ANTICIPADO_CARD_ID,
    playerId,
    targetUnitId: target.id,
    originTab: item?.originTab ?? 0,
    originSlot: item?.originSlot ?? 0,
    createdAt: Date.now(),
  };
  state.activeSpellLinks = Array.isArray(state.activeSpellLinks) ? state.activeSpellLinks : [];
  state.activeSpellLinks.push(link);
  const stacks = getDespliegueAnticipadoActiveStacks(playerId);
  showFloatingTextAt(target.row, target.col, 'DESPLIEGUE ANTICIPADO', 'floating-combat buff');
  log(`${CARD_LIBRARY[target.cardId]?.name || 'El Caudillo'} queda marcado por Despliegue anticipado. Acumulaciones activas: ${stacks}.`);
  renderAll();
  return true;
}

function shouldApplyDespliegueUseCooldown(playerId, card) {
  return getDespliegueAnticipadoReturnCooldown(playerId, card) > 0;
}

function isEligibleGloriaLatenteTargetUnit(playerId, unit) {
  if (!unit || Number(unit.owner ?? playerId) !== Number(playerId)) return false;
  if (unit.status === 'restoring') return false;
  return ['warrior', 'caudillo', 'knight', 'hero'].some(qualityId => unitHasCardQuality(unit, qualityId));
}

function getEligibleGloriaLatenteTargets(playerId) {
  return (state.players?.[playerId]?.units || []).filter(unit => isEligibleGloriaLatenteTargetUnit(playerId, unit));
}

function getSelectableGloriaLatenteTargets(playerId) {
  const targets = getEligibleGloriaLatenteTargets(playerId);
  const pending = state.pendingPowerAction;
  if (pending?.kind !== 'gloriaLatenteTarget' || pending.quickReaction !== true || !pending.requiredTargetUnitId) return targets;
  return targets.filter(unit => String(unit.id) === String(pending.requiredTargetUnitId));
}

function getGloriaLatenteCastAvailability(playerId) {
  const targets = getEligibleGloriaLatenteTargets(playerId);
  if (!targets.length) {
    return {
      available: false,
      reason: 'noTarget',
      message: 'Gloria latente requiere una invocación aliada activa con cualidad Guerrero, Caudillo, Caballero o Héroe.',
      targets,
    };
  }
  return { available: true, reason: '', message: '', targets };
}

function getActiveGloriaLatenteLinks(playerId = null) {
  const links = Array.isArray(state.activeSpellLinks) ? state.activeSpellLinks : [];
  return links.filter(link => {
    if (!link || link.type !== GLORIA_LATENTE_POWER_ID) return false;
    if (playerId != null && Number(link.playerId) !== Number(playerId)) return false;
    const target = getUnitById(Number(link.playerId), link.targetUnitId);
    return Boolean(target);
  });
}

function getGloriaLatenteStacksForUnit(playerId, unitOrId) {
  const unitId = typeof unitOrId === 'string' ? unitOrId : unitOrId?.id;
  if (!unitId) return 0;
  return getActiveGloriaLatenteLinks(playerId).filter(link => String(link.targetUnitId) === String(unitId)).length;
}

function getGloriaLatenteMaxHpBonusForUnit(playerId, unitOrId) {
  return getGloriaLatenteStacksForUnit(playerId, unitOrId) * GLORIA_LATENTE_HP_BONUS_PER_LINK;
}

function applyGloriaLatenteLinkBonusToUnit(playerId, unit, options = {}) {
  if (!unit) return 0;
  const card = CARD_LIBRARY[unit.cardId];
  const baseMaxHp = Math.max(1, Number(unit.baseHp ?? card?.stats?.life ?? unit.maxHp ?? unit.hp ?? 1));
  const previousGloriaBonus = Math.max(0, Number(unit.gloriaLatenteMaxHpBonus || 0));
  const currentEffectiveMax = Math.max(baseMaxHp, Number(unit.maxHp ?? baseMaxHp));
  const otherMaxHpBonus = Math.max(0, currentEffectiveMax - baseMaxHp - previousGloriaBonus);
  const hpBefore = Math.max(0, Number(unit.hp ?? currentEffectiveMax));

  unit.gloriaLatenteStacks = Math.max(0, Number(unit.gloriaLatenteStacks || 0)) + 1;
  unit.gloriaLatenteMaxHpBonus = previousGloriaBonus + GLORIA_LATENTE_HP_BONUS_PER_LINK;
  unit.maxHp = baseMaxHp + otherMaxHpBonus + unit.gloriaLatenteMaxHpBonus;

  // El +2 amplía únicamente el límite. La vida actual no aumenta salvo que
  // otra parte explícita del efecto ordene una curación independiente.
  const healNow = Boolean(options.healNow);
  unit.hp = healNow
    ? Math.min(unit.maxHp, hpBefore + GLORIA_LATENTE_RESTORE_HEAL_PER_LINK)
    : Math.min(hpBefore, unit.maxHp);
  return unit.gloriaLatenteStacks;
}

function removeGloriaLatenteLinkBonusFromUnit(unit) {
  if (!unit) return 0;
  const stacks = Math.max(0, Number(unit.gloriaLatenteStacks || 0));
  if (!stacks) return 0;
  const card = CARD_LIBRARY[unit.cardId];
  const baseMaxHp = Math.max(1, Number(unit.baseHp ?? card?.stats?.life ?? unit.maxHp ?? unit.hp ?? 1));
  const previousGloriaBonus = Math.max(0, Number(unit.gloriaLatenteMaxHpBonus || 0));
  const currentEffectiveMax = Math.max(baseMaxHp, Number(unit.maxHp ?? baseMaxHp));
  const otherMaxHpBonus = Math.max(0, currentEffectiveMax - baseMaxHp - previousGloriaBonus);

  unit.gloriaLatenteStacks = Math.max(0, stacks - 1);
  unit.gloriaLatenteMaxHpBonus = Math.max(0, previousGloriaBonus - GLORIA_LATENTE_HP_BONUS_PER_LINK);
  unit.maxHp = Math.max(1, baseMaxHp + otherMaxHpBonus + unit.gloriaLatenteMaxHpBonus);
  unit.hp = Math.min(Math.max(0, Number(unit.hp ?? unit.maxHp)), unit.maxHp);
  return unit.gloriaLatenteStacks;
}

function endGloriaLatenteLink(link, reason = 'el objetivo dejó la arena') {
  if (!link || link.type !== GLORIA_LATENTE_POWER_ID) return false;
  state.activeSpellLinks = Array.isArray(state.activeSpellLinks) ? state.activeSpellLinks.filter(entry => entry !== link) : [];
  const target = getUnitById(Number(link.playerId), link.targetUnitId);
  if (target) removeGloriaLatenteLinkBonusFromUnit(target);
  log(`Gloria latente termina porque ${reason}. El hechizo ya fue consumido y no regresa al Spellbook.`);
  return true;
}

function endGloriaLatenteLinksForTarget(playerId, unitId, reason = 'la invocación dejó la arena') {
  const links = (state.activeSpellLinks || []).filter(link => link?.type === GLORIA_LATENTE_POWER_ID
    && Number(link.playerId) === Number(playerId)
    && String(link.targetUnitId) === String(unitId));
  links.forEach(link => endGloriaLatenteLink(link, reason));
  return links.length;
}

function cleanupInvalidGloriaLatenteLinks() {
  const links = [...(state.activeSpellLinks || [])];
  links.forEach(link => {
    if (link?.type !== GLORIA_LATENTE_POWER_ID) return;
    const target = getUnitById(Number(link.playerId), link.targetUnitId);
    if (!target) endGloriaLatenteLink(link, 'el objetivo ya no está activo en arena');
  });
}

function cancelGloriaLatenteTargeting(message = 'Selección de Gloria latente cancelada.') {
  const pending = state.pendingPowerAction;
  if (pending?.kind !== 'gloriaLatenteTarget') return false;
  const quickReaction = pending.quickReaction === true;
  state.pendingPowerAction = null;
  log(message);
  if (quickReaction) {
    resolveGloriaLatenteQuickReactionDecision(false, 'cancelled');
    return true;
  }
  renderAll();
  return true;
}

function beginGloriaLatenteTargeting(playerId, cardId, originTab, originSlot, options = {}) {
  const availability = getGloriaLatenteCastAvailability(playerId);
  if (!availability.available) {
    log(availability.message);
    renderAll();
    return false;
  }
  state.selectedMover = null;
  state.selectedTarget = null;
  state.pendingPlacement = null;
  state.pendingCard = null;
  const quickReaction = options.quickReaction === true;
  const requiredTargetUnitId = options.requiredTargetUnitId || null;
  if (quickReaction) {
    const requiredTarget = getUnitById(playerId, requiredTargetUnitId);
    if (!requiredTarget || !isEligibleGloriaLatenteTargetUnit(playerId, requiredTarget)) {
      resolveGloriaLatenteQuickReactionDecision(false, 'target-invalid');
      return false;
    }
  }
  state.pendingPowerAction = {
    kind: 'gloriaLatenteTarget',
    stage: 'precast',
    playerId,
    cardId: cardId || GLORIA_LATENTE_CARD_ID,
    originTab: Math.max(0, Number(originTab) || 0),
    originSlot: Math.max(0, Number(originSlot) || 0),
    quickReaction,
    reactionEventId: options.reactionEventId || '',
    requiredTargetUnitId,
  };
  if (quickReaction && state.gloriaLatenteQuickCastMode) {
    state.gloriaLatenteQuickCastMode.stage = 'target';
    clearQuickReactionSpellbookFocus();
  }
  log(quickReaction
    ? `Gloria latente: confirma a ${CARD_LIBRARY[getUnitById(playerId, requiredTargetUnitId)?.cardId]?.name || 'la invocación amenazada'} como objetivo del Kasteo rápido.`
    : 'Gloria latente: selecciona una invocación aliada Guerrero, Caudillo, Caballero o Héroe. El costo se pagará después de confirmar el objetivo.');
  renderAll();
  return true;
}

function resolveGloriaLatenteTarget(playerId, unitId) {
  const pending = state.pendingPowerAction;
  if (!pending || pending.kind !== 'gloriaLatenteTarget' || Number(pending.playerId) !== Number(playerId)) return false;
  const target = getUnitById(playerId, unitId);
  const selectableTargets = getSelectableGloriaLatenteTargets(playerId);
  if (!target || !selectableTargets.some(candidate => String(candidate.id) === String(unitId))) {
    log(pending.quickReaction
      ? 'Kasteo rápido de Gloria latente debe confirmarse sobre la invocación amenazada por el daño letal.'
      : 'Gloria latente requiere una invocación aliada activa con cualidad Guerrero, Caudillo, Caballero o Héroe.');
    renderAll();
    return false;
  }
  const player = state.players?.[playerId];
  const card = CARD_LIBRARY[pending.cardId || GLORIA_LATENTE_CARD_ID];
  const tab = Math.max(0, Number(pending.originTab) || 0);
  const slot = Math.max(0, Number(pending.originSlot) || 0);
  if (!player || !card || player.handTabs?.[tab]?.[slot] !== card.id) {
    state.pendingPowerAction = null;
    log('Gloria latente ya no está disponible en ese espacio del Spellbook.');
    if (pending.quickReaction) resolveGloriaLatenteQuickReactionDecision(false, 'card-missing');
    else renderAll();
    return false;
  }
  if (pending.quickReaction) {
    state.pendingPowerAction = null;
    const event = state.gloriaLatenteReactionCurrent;
    if (!event || String(event.id) !== String(pending.reactionEventId || event.id)) {
      resolveGloriaLatenteQuickReactionDecision(false, 'reaction-expired');
      return false;
    }
    const activated = performGloriaLatenteQuickRescue(playerId, target, event.source, { tab, slot, card });
    state.gloriaLatenteReactionCurrent = null;
    clearGloriaLatenteQuickReactionUi(activated ? 'activated' : 'failed');
    if (!activated && target.status !== 'restoring') {
      damageInvocationUnit(event.playerId, target, event.originalAmount, event.reason, { ...(event.source || {}), skipGloriaLatenteQuickReaction: true });
    }
    renderAll();
    setTimeout(showNextGloriaLatenteQuickReaction, 40);
    return activated;
  }
  state.pendingPowerAction = null;
  state.selectedCardSlot = slot;
  state.pendingCard = { cardId: card.id, slotIndex: slot, tab, targetUnitId: target.id };
  const caster = player.caster;
  const row = Math.max(0, Math.min(15, Number(caster?.row ?? 0) + (Number(playerId) === 1 ? -1 : 1)));
  const col = Number(caster?.col ?? 0);
  if (!isInside(row, col)) {
    clearPendingCast();
    log(`No hay una casilla de referencia válida para preparar ${card.name}.`);
    renderAll();
    return false;
  }
  state.pendingPlacement = { row, col, key: 'auto', targetUnitId: target.id };
  log(`${CARD_LIBRARY[target.cardId]?.name || 'La invocación'} fue elegida. Ahora se paga el costo y comienza el kasteo de ${card.name}.`);
  confirmCast();
  return true;
}

function resolveGloriaLatenteCast(playerId, item, card) {
  const target = getUnitById(playerId, item?.targetUnitId);
  if (!isEligibleGloriaLatenteTargetUnit(playerId, target)) {
    log('Gloria latente no puede vincularse: el objetivo seleccionado dejó de ser válido durante el kasteo. El hechizo se consume sin crear vínculo.');
    renderAll();
    return false;
  }
  const link = {
    id: `gloria_${Date.now()}_${Math.random().toString(16).slice(2)}`,
    type: GLORIA_LATENTE_POWER_ID,
    cardId: card?.id || GLORIA_LATENTE_CARD_ID,
    playerId,
    targetUnitId: target.id,
    originTab: item?.originTab ?? 0,
    originSlot: item?.originSlot ?? 0,
    createdAt: Date.now(),
  };
  state.activeSpellLinks = Array.isArray(state.activeSpellLinks) ? state.activeSpellLinks : [];
  state.activeSpellLinks.push(link);
  applyGloriaLatenteLinkBonusToUnit(playerId, target, { healNow: false });
  showFloatingTextAt(target.row, target.col, 'GLORIA LATENTE', 'floating-combat buff');
  log(`${CARD_LIBRARY[target.cardId]?.name || 'La invocación'} queda vinculada a Gloria latente: +2 de vida máxima y restauración 0 mientras el vínculo siga activo.`);
  renderAll();
  return true;
}

const GLORIA_LATENTE_QUICK_REACTION_LOCK_REASON = 'gloria-latente-quick-reaction';

function findFirstReadyGloriaLatenteSlot(playerId, targetUnit = null) {
  const player = state.players?.[playerId];
  const card = CARD_LIBRARY[GLORIA_LATENTE_CARD_ID];
  if (!player || !card) return null;
  if (targetUnit && !isEligibleGloriaLatenteTargetUnit(playerId, targetUnit)) return null;
  const casterStatus = canCasterUseSpell(playerId, card);
  if (!casterStatus.ok) return null;
  const paymentStatus = getCostPaymentStatus(playerId, card);
  if (!paymentStatus.ok) return null;
  for (let tabIndex = 0; tabIndex < (player.handTabs || []).length; tabIndex++) {
    const tab = player.handTabs[tabIndex] || [];
    for (let slotIndex = 0; slotIndex < tab.length; slotIndex++) {
      if (tab[slotIndex] !== GLORIA_LATENTE_CARD_ID) continue;
      if (getSpellbookUseCooldown(playerId, tabIndex, slotIndex) > 0) continue;
      return { tab: tabIndex, slot: slotIndex, card };
    }
  }
  return null;
}

function performGloriaLatenteQuickRescue(playerId, unit, source = null, preferredSlotInfo = null) {
  const slotInfo = preferredSlotInfo || findFirstReadyGloriaLatenteSlot(playerId, unit);
  if (!slotInfo || !unit || !isEligibleGloriaLatenteTargetUnit(playerId, unit)) return false;
  const card = slotInfo.card || CARD_LIBRARY[GLORIA_LATENTE_CARD_ID];
  const player = state.players?.[playerId];
  if (!player || !card || player.handTabs?.[slotInfo.tab]?.[slotInfo.slot] !== GLORIA_LATENTE_CARD_ID) return false;
  if (!canCasterUseSpell(playerId, card).ok) return false;
  if (!payCardCostForPlayer(playerId, card, null)) return false;

  // Todos los hechizos son consumibles: la copia sale definitivamente del
  // Spellbook en cuanto el jugador confirma la activación rápida.
  player.handTabs[slotInfo.tab][slotInfo.slot] = null;
  clearSpellbookUseCooldown(playerId, slotInfo.tab, slotInfo.slot);
  state.activeSpellLinks = Array.isArray(state.activeSpellLinks) ? state.activeSpellLinks : [];
  state.activeSpellLinks.push({
    id: `gloria_${Date.now()}_${Math.random().toString(16).slice(2)}`,
    type: GLORIA_LATENTE_POWER_ID,
    cardId: card.id,
    playerId,
    targetUnitId: unit.id,
    originTab: slotInfo.tab,
    originSlot: slotInfo.slot,
    createdAt: Date.now(),
    quickCast: true,
    consumed: true,
  });

  // Primero se aplica el vínculo y su +2 de vida máxima. No cura al entrar.
  applyGloriaLatenteLinkBonusToUnit(playerId, unit, { healNow: false });
  showFloatingTextAt(unit.row, unit.col, 'GLORIA LATENTE', 'floating-combat buff');
  showFloatingTextAt(unit.row, unit.col, '+2 VIDA MÁX', 'floating-combat buff');
  renderAll();

  // El daño letal queda cancelado porque esta función devuelve éxito. Después
  // se ejecuta la restauración real para que Gloria latente aplique allí su
  // restauración 0 y su +1 de vida por cada vínculo activo.
  clearUnitEngagement(playerId, unit.id);
  const restored = restoreInvocation(playerId, unit, 'Gloria latente por Kasteo rápido');
  if (restored === false) {
    log(`Gloria latente se vinculó a ${CARD_LIBRARY[unit.cardId]?.name || 'la invocación'}, pero la restauración quedó bloqueada por otra resolución pendiente.`);
  } else {
    log(`Gloria latente se activa por Kasteo rápido y salva a ${CARD_LIBRARY[unit.cardId]?.name || 'la invocación'} antes del daño letal. La copia se consume, el daño se cancela y la invocación se restaura con el efecto normal del hechizo.`);
  }
  renderAll();
  return true;
}

function getGloriaLatenteReactionQueue() {
  state.gloriaLatenteReactionQueue = Array.isArray(state.gloriaLatenteReactionQueue) ? state.gloriaLatenteReactionQueue : [];
  return state.gloriaLatenteReactionQueue;
}

function createGloriaLatenteQuickReactionCandidate(event) {
  const unit = getUnitById(event.playerId, event.unitId);
  const targetName = CARD_LIBRARY[unit?.cardId]?.name || 'la invocación aliada';
  const action = {
    id: 'gloriaLatenteQuickCast',
    label: 'Activar',
    title: `Activar Gloria latente para salvar a ${targetName}`,
    directExecute: false,
    execute: () => beginGloriaLatenteQuickCastSpellbookFlow(),
    cancel: () => resolveGloriaLatenteQuickReactionDecision(false, 'declined'),
  };
  return {
    type: 'casterAbility',
    selectionType: 'caster',
    playerId: event.playerId,
    unitId: null,
    cardId: GLORIA_LATENTE_CARD_ID,
    spellbookTab: event.slotInfo?.tab,
    spellbookSlot: event.slotInfo?.slot,
    label: `Gloria latente · ${targetName}`,
    actions: [action],
    actionLabels: [action.label],
    targets: [],
  };
}

function clearGloriaLatenteQuickReactionUi(result = 'resolved') {
  if (state.pendingPowerAction?.kind === 'gloriaLatenteTarget' && state.pendingPowerAction.quickReaction === true) {
    state.pendingPowerAction = null;
  }
  state.gloriaLatenteQuickCastMode = null;
  const intro = state.quickReactionWindow?.phaseIntro;
  if (intro?.windowTimer) clearTimeout(intro.windowTimer);
  const store = getQuickReactionWindowStore();
  clearTimeout(store.hideTimersByPlayer?.[LOCAL_PLAYER_ID]);
  if (store.hideTimersByPlayer) store.hideTimersByPlayer[LOCAL_PLAYER_ID] = null;
  stopQuickReactionDecisionCountdown();
  hideQuickReactionModalVisualOnly();
  hideQuickReactionWindowForPlayer(LOCAL_PLAYER_ID);
  clearQuickReactionCommandDock();
  if (state.quickReactionWindow) {
    state.quickReactionWindow.collectContext = null;
    state.quickReactionWindow.phaseIntro = null;
    state.quickReactionWindow.candidates = [];
    state.quickReactionWindow.locked = false;
    state.quickReactionWindow.active = false;
    state.quickReactionWindow.executing = false;
  }
  if (state.actionExecutionLockReason === GLORIA_LATENTE_QUICK_REACTION_LOCK_REASON) {
    setActionExecutionLock(false, GLORIA_LATENTE_QUICK_REACTION_LOCK_REASON);
  }
  syncLocalQuickReactionGameplayPause();
  return result;
}

function showNextGloriaLatenteQuickReaction() {
  if (state.gloriaLatenteReactionCurrent) return true;
  const queue = getGloriaLatenteReactionQueue();
  while (queue.length) {
    const event = queue.shift();
    const unit = getUnitById(event.playerId, event.unitId);
    if (!unit || unit.status === 'restoring') continue;
    const currentHp = Math.max(0, Number(unit.hp ?? 0));
    if (event.damageAmount < currentHp) continue;
    const slotInfo = findFirstReadyGloriaLatenteSlot(event.playerId, unit);
    if (!slotInfo) {
      damageInvocationUnit(event.playerId, unit, event.originalAmount, event.reason, { ...(event.source || {}), skipGloriaLatenteQuickReaction: true });
      continue;
    }

    event.slotInfo = slotInfo;
    state.gloriaLatenteReactionCurrent = event;
    state.gloriaLatenteQuickCastMode = {
      active: true,
      stage: 'prompt',
      eventId: event.id,
      playerId: Number(event.playerId),
      cardId: GLORIA_LATENTE_CARD_ID,
      tab: Number(slotInfo.tab),
      slot: Number(slotInfo.slot),
      requiredTargetUnitId: event.unitId,
      openedAt: Date.now(),
    };
    setActionExecutionLock(true, GLORIA_LATENTE_QUICK_REACTION_LOCK_REASON);
    syncLocalQuickReactionGameplayPause();
    const candidate = createGloriaLatenteQuickReactionCandidate(event);
    const windowMs = QUICK_REACTION_WINDOW_MS;
    event.windowExpiresAt = Date.now() + windowMs;
    state.quickReactionWindow.collectContext = { gloriaLatenteReaction: true };
    state.quickReactionWindow.candidates = [candidate];
    state.quickReactionWindow.playerId = LOCAL_PLAYER_ID;
    state.quickReactionWindow.locked = false;
    state.quickReactionWindow.active = true;
    state.quickReactionWindow.executing = false;
    state.quickReactionWindow.phaseIntro = {
      playerId: LOCAL_PLAYER_ID,
      phaseKey: getQuickReactionPhaseKey(LOCAL_PLAYER_ID),
      done: false,
      modalOpen: false,
      contextual: true,
      synthetic: true,
      candidates: [candidate],
      windowTimer: null,
    };
    cacheQuickReactionCandidatesForPlayer(LOCAL_PLAYER_ID, [candidate]);
    showQuickReactionWindowForCandidates([candidate], LOCAL_PLAYER_ID, { force: true, duration: windowMs });
    const intro = state.quickReactionWindow.phaseIntro;
    intro.windowTimer = setTimeout(() => {
      if (state.gloriaLatenteReactionCurrent?.id !== event.id) return;
      resolveGloriaLatenteQuickReactionDecision(false, 'timeout');
    }, windowMs + 40);
    log(`Ventana de acción: puedes activar Gloria latente para salvar a ${CARD_LIBRARY[unit.cardId]?.name || 'la invocación'} del daño letal.`);
    return true;
  }
  clearGloriaLatenteQuickReactionUi('queue-empty');
  return false;
}

function resolveGloriaLatenteQuickReactionDecision(activate, reason = 'declined') {
  const event = state.gloriaLatenteReactionCurrent;
  if (!event) return false;
  state.gloriaLatenteReactionCurrent = null;
  clearGloriaLatenteQuickReactionUi(reason);

  const unit = getUnitById(event.playerId, event.unitId);
  let activated = false;
  if (activate && unit && unit.status !== 'restoring') {
    const liveSlot = findFirstReadyGloriaLatenteSlot(event.playerId, unit);
    activated = performGloriaLatenteQuickRescue(event.playerId, unit, event.source, liveSlot);
  }
  if (!activated && unit && unit.status !== 'restoring') {
    if (activate) log('Gloria latente ya no pudo activarse; el daño pendiente continúa normalmente.');
    else if (reason === 'timeout') log('La ventana de Gloria latente terminó sin activarse. El daño pendiente continúa.');
    else log('Gloria latente no fue activada. El daño pendiente continúa.');
    damageInvocationUnit(event.playerId, unit, event.originalAmount, event.reason, { ...(event.source || {}), skipGloriaLatenteQuickReaction: true });
  }
  renderAll();
  setTimeout(showNextGloriaLatenteQuickReaction, 40);
  return activated;
}

function maybeUseGloriaLatenteQuickRescueBeforeDamage(playerId, unit, damageAmount, source = null, context = {}) {
  if (Number(playerId) !== Number(LOCAL_PLAYER_ID)) return false;
  if (!unit || unit.status === 'restoring') return false;
  if (!isEligibleGloriaLatenteTargetUnit(playerId, unit)) return false;
  const hp = Math.max(0, Number(unit.hp ?? 0));
  const lethalDamage = Math.max(0, Number(damageAmount) || 0);
  if (lethalDamage < hp) return false;
  if (!findFirstReadyGloriaLatenteSlot(playerId, unit)) return false;

  const queue = getGloriaLatenteReactionQueue();
  const duplicatePending = state.gloriaLatenteReactionCurrent?.unitId === unit.id
    || queue.some(entry => String(entry.unitId) === String(unit.id));
  if (duplicatePending) return true;

  queue.push({
    id: `gloria_reaction_${Date.now()}_${Math.random().toString(16).slice(2)}`,
    playerId: Number(playerId),
    unitId: unit.id,
    damageAmount: lethalDamage,
    originalAmount: Math.max(0, Number(context.amount ?? damageAmount) || 0),
    reason: context.reason || 'daño',
    source: source ? { ...source } : null,
    queuedAt: Date.now(),
  });
  showNextGloriaLatenteQuickReaction();
  return true;
}

function getCasterCardForPlayer(playerId) {
  const casterCardId = state.players[playerId]?.caster?.cardId;
  return CARD_LIBRARY[casterCardId] || null;
}

function canCasterUseSpell(playerId, card) {
  if (casterHasSilence(playerId, 3)) {
    const entry = getCasterSilenceEntry(playerId);
    return { ok: false, message: `El Kaster está bajo Silencio ${entry?.level || 3} y no puede kastear durante ${entry?.durationRemaining || 0} fase(s).` };
  }
  const rules = getSpellRules(card);
  const userRule = rules.user || {};
  if (userRule.mode !== 'restricted' || userRule.allowAnyCaster === true) return { ok: true };
  const casterCard = getCasterCardForPlayer(playerId);
  if (!casterCard) return { ok: false, message: 'No se encontró el Kaster usuario del hechizo.' };
  const requiredElements = Array.isArray(userRule.elements) ? userRule.elements : [];
  const requiredQualities = Array.isArray(userRule.casterQualities) ? userRule.casterQualities : [];
  const casterElement = getCardElementId(casterCard);
  const casterQualities = Array.isArray(casterCard.qualities) ? casterCard.qualities : [];
  const hasElement = requiredElements.length && requiredElements.includes(casterElement);
  const hasQuality = requiredQualities.length && casterQualities.some(q => requiredQualities.includes(q));
  const mode = userRule.requirementMode || 'all';
  const ok = mode === 'any'
    ? Boolean(hasElement || hasQuality || (!requiredElements.length && !requiredQualities.length))
    : ((!requiredElements.length || hasElement) && (!requiredQualities.length || hasQuality));
  if (ok) return { ok: true };
  const names = [
    ...requiredElements.map(elementId => (DOMAIN_ART_DB[elementId] || DOMAIN_ART_DB.oscuridad).elementLabel),
    ...requiredQualities.map(q => getQualityProfile(q)?.label || q),
  ];
  return { ok: false, message: `${card.name} requiere usuario ${names.join(' o ')}.` };
}


function getSpellRuleStandardLabel(kind, rule) {
  if (rule?.mode === 'standard') return 'Estándar';
  return rule?.label || (kind === 'user' ? 'Usuario' : 'Objetivo');
}

function renderSpellRuleRestrictionIcons(kind, rule) {
  if (!rule || rule.mode === 'standard') {
    return `<span class="card-info-value-chip card-info-spell-channel-value" title="${rule?.description || 'Sin restricción especial'}">Estándar</span>`;
  }
  if (rule.mode === 'arenaLocation') {
    const text = rule.displayText || rule.label || 'Selecciona una ubicación en arena';
    return `<span class="card-info-value-chip card-info-spell-channel-value card-info-spell-location-value" title="${rule.description || text}">${text}</span>`;
  }
  if (String(rule.mode || '').toLowerCase() === 'selfuser') {
    const text = rule.displayText || rule.label || 'Usuario de esta habilidad';
    return `<span class="card-info-value-chip card-info-spell-channel-value card-info-spell-self-user-value" title="${rule.description || text}">${text}</span>`;
  }

  const domainChips = [];
  const typeChips = [];
  const qualityChips = [];
  const weaponChips = [];
  const combatModeChips = [];
  const mandatory = rule.mandatory || {};
  const mandatoryElements = Array.isArray(mandatory.elements) ? mandatory.elements : [];
  const mandatoryCardTypes = Array.isArray(mandatory.cardTypes) ? mandatory.cardTypes : [];

  const makeDomainChip = (elementId, isMandatory = false) => {
    const domain = DOMAIN_ART_DB[elementId] || DOMAIN_ART_DB.oscuridad;
    return `<button type="button" class="card-info-spell-restriction-chip card-info-spell-domain-restriction ${isMandatory ? 'mandatory' : 'optional'}" data-info-kind="domain" data-info-id="${elementId}" title="${isMandatory ? 'Requisito obligatorio' : 'Dominio'}: ${domain.elementLabel}">
      <span class="card-info-spell-domain-stack">
        <span class="card-info-spell-domain-bg"></span>
        <img class="card-info-spell-domain-element" src="${domain.elementArt}" alt="${domain.elementLabel}">
        <img class="card-info-spell-domain-attribute" src="${domain.attributeArt}" alt="${domain.attributeLabel}">
      </span>
    </button>`;
  };

  const makeTypeChip = (typeId, isMandatory = false) => {
    const type = CARD_TYPE_DB[typeId] || CARD_TYPE_DB.invocation;
    return `<button type="button" class="card-info-spell-restriction-chip card-info-icon-chip ${isMandatory ? 'mandatory' : 'optional'}" data-info-kind="cardType" data-info-id="${type.id}" title="${isMandatory ? 'Requisito obligatorio' : 'Tipo'}: ${type.label}"><img src="${type.icon}" alt="${type.label}"></button>`;
  };

  mandatoryElements.forEach(elementId => domainChips.push(makeDomainChip(elementId, true)));
  mandatoryCardTypes.forEach(typeId => typeChips.push(makeTypeChip(typeId, true)));

  if (Array.isArray(rule.elements)) {
    rule.elements.filter(elementId => !mandatoryElements.includes(elementId)).forEach(elementId => domainChips.push(makeDomainChip(elementId, false)));
  }
  if (Array.isArray(rule.cardTypes)) {
    rule.cardTypes.filter(typeId => !mandatoryCardTypes.includes(typeId)).forEach(typeId => typeChips.push(makeTypeChip(typeId, false)));
  }
  if (Array.isArray(rule.casterQualities)) {
    rule.casterQualities.forEach(qualityId => {
      const quality = getQualityProfile(qualityId);
      if (quality) qualityChips.push(`<button type="button" class="card-info-spell-restriction-chip card-info-icon-chip optional" data-info-kind="quality" data-info-id="${quality.id}" title="Cualidad usuaria: ${quality.label}"><img src="${quality.icon}" alt="${quality.label}"></button>`);
    });
  }
  if (Array.isArray(rule.qualities)) {
    rule.qualities.forEach(qualityId => {
      const quality = getQualityProfile(qualityId);
      const roleLabel = kind === 'user' ? 'Cualidad usuaria' : 'Cualidad objetivo';
      if (quality) qualityChips.push(`<button type="button" class="card-info-spell-restriction-chip card-info-icon-chip optional" data-info-kind="quality" data-info-id="${quality.id}" title="${roleLabel}: ${quality.label}"><img src="${quality.icon}" alt="${quality.label}"></button>`);
    });
  }
  if (Array.isArray(rule.weapons)) {
    rule.weapons.forEach(weaponId => {
      const weapon = getWeaponInfoProfile(weaponId);
      if (weapon) weaponChips.push(`<button type="button" class="card-info-spell-restriction-chip card-info-icon-chip mandatory" data-info-kind="weapon" data-info-id="${weapon.id}" title="Arma requerida: ${weapon.label}"><img src="${weapon.icon}" alt="${weapon.label}"></button>`);
    });
  }
  if (Array.isArray(rule.combatModes)) {
    rule.combatModes.forEach(modeId => {
      const mode = COMBAT_MODE_DB[modeId];
      if (mode) combatModeChips.push(`<button type="button" class="card-info-spell-restriction-chip card-info-icon-chip mandatory" data-info-kind="combatMode" data-info-id="${mode.id}" title="Modo de combate requerido: ${mode.label}"><img src="${mode.icon}" alt="${mode.label}"></button>`);
    });
  }

  if (rule.displayHierarchy === true && typeChips.length) {
    const secondary = [...domainChips, ...qualityChips];
    const hierarchyGroups = [typeChips, secondary, weaponChips, combatModeChips].filter(group => group.length);
    return `<span class="card-info-spell-channel-value card-info-spell-channel-icons card-info-spell-channel-hierarchy" title="${rule.description || getSpellRuleStandardLabel(kind, rule)}">
      ${hierarchyGroups.map((group, index) => `${index ? '<span class="card-info-spell-restriction-chain-arrow" aria-hidden="true">→</span>' : ''}<span class="card-info-spell-restriction-group ${index === 0 ? 'card-info-spell-restriction-group-base' : 'card-info-spell-restriction-group-qualities'}">${group.join('')}</span>`).join('')}
    </span>`;
  }

  const chips = [...domainChips, ...typeChips, ...qualityChips, ...weaponChips, ...combatModeChips];
  return `<span class="card-info-spell-channel-value card-info-spell-channel-icons" title="${rule.description || getSpellRuleStandardLabel(kind, rule)}">${chips.join('') || getSpellRuleStandardLabel(kind, rule)}</span>`;
}

function renderSpellRuleChip(kind, rule, card = null) {
  const label = getSpellRuleStandardLabel(kind, rule);
  const description = rule?.description || label;
  const iconText = kind === 'user' ? 'U' : 'O';
  const isAbility = getCardTypeId(card) === 'ability';
  const title = kind === 'user'
    ? (isAbility ? 'Usuarios de la habilidad' : 'Usuarios del hechizo')
    : (isAbility ? 'Objetivo de la habilidad' : 'Objetivos del hechizo');
  return `
    <div class="card-info-spell-channel card-info-spell-channel-${kind}">
      <button type="button" class="card-info-spell-channel-letter card-info-spell-rule-${kind}" data-info-kind="spellRule" data-info-id="${kind}" title="${title}: ${description}">${iconText}</button>
      <span class="card-info-spell-channel-arrow" aria-hidden="true">→</span>
      ${renderSpellRuleRestrictionIcons(kind, rule)}
    </div>`;
}

function renderSpellUserChip(card) {
  const rules = getSpellRules(card);
  return renderSpellRuleChip('user', rules.user, card);
}

function renderSpellTargetChip(card) {
  const rules = getSpellRules(card);
  return renderSpellRuleChip('target', rules.target, card);
}

function renderSpellTraitChips(card) {
  const traits = Array.isArray(getSpellRules(card).castRequirements?.traits) ? getSpellRules(card).castRequirements.traits : [];
  if (!traits.length) return '';
  return traits.map(trait => `<span class="card-info-value-chip card-info-spell-trait-chip" title="Rasgo de kasteo: ${trait}"><span>${trait}</span></span>`).join('');
}

function renderSpellInfoRows(card) {
  if (els.cardInfoDamage) {
    els.cardInfoDamage.innerHTML = `<div class="card-info-chip-stack card-info-chip-stack-spell-users">${renderSpellUserChip(card)}</div>`;
    bindInlineInfoButtons(els.cardInfoDamage, card);
  }
  if (els.cardInfoAttackType) els.cardInfoAttackType.innerHTML = '';
  if (els.cardInfoRange) els.cardInfoRange.innerHTML = '';
  if (els.cardInfoFactors) els.cardInfoFactors.innerHTML = '';

  if (els.cardInfoLife) {
    els.cardInfoLife.innerHTML = `<div class="card-info-chip-stack card-info-chip-stack-spell-targets">${renderSpellTargetChip(card)}</div>`;
    bindInlineInfoButtons(els.cardInfoLife, card);
  }
  if (els.cardInfoDefense) els.cardInfoDefense.innerHTML = '';

  if (els.cardInfoCost) {
    const costChip = renderCardCostChip(card);
    els.cardInfoCost.innerHTML = costChip ? `<div class="card-info-chip-stack">${costChip}</div>` : '';
    if (costChip) bindInlineInfoButtons(els.cardInfoCost, card);
  }
  if (els.cardInfoCastTime) {
    els.cardInfoCastTime.innerHTML = `<div class="card-info-chip-stack card-info-chip-stack-spell-cast">${renderCastTimeChip(card)}</div>`;
    bindInlineInfoButtons(els.cardInfoCastTime, card);
  }
  if (els.cardInfoRestoreTime) els.cardInfoRestoreTime.innerHTML = '';
  if (els.cardInfoSpellbookCooldown) {
    const cooldownChip = renderSpellbookCooldownChip(card);
    els.cardInfoSpellbookCooldown.innerHTML = cooldownChip ? `<div class="card-info-chip-stack">${cooldownChip}</div>` : '';
    if (cooldownChip) bindInlineInfoButtons(els.cardInfoSpellbookCooldown, card);
  }
  if (els.cardInfoUtilityFactors) {
    const spellFactors = getCardAllFactors(card);
    const spellFactorChips = spellFactors.map(factorEntry => renderFactorChip(factorEntry, card)).join('');
    const grantedMovementChips = (Array.isArray(card?.grantedMovementTypes) ? card.grantedMovementTypes : []).map(typeId => {
      const movement = getMovementProfile(typeId);
      return `<button type="button" class="card-info-icon-chip card-info-movement-chip card-info-granted-movement-chip" data-info-kind="movementType" data-info-id="${movement.id}" title="Movilidad concedida por el hechizo: ${movement.label}"><img src="${movement.icon}" alt="${movement.label}"></button>`;
    }).join('');
    const spellUtilityChips = `${spellFactorChips}${grantedMovementChips}`;
    els.cardInfoUtilityFactors.innerHTML = spellUtilityChips
      ? `<div class="card-info-chip-stack card-info-chip-stack-factors card-info-chip-stack-spell-factors">${spellUtilityChips}</div>`
      : '';
    if (spellUtilityChips) bindInlineInfoButtons(els.cardInfoUtilityFactors, card);
  }
  if (els.cardInfoMoveType) els.cardInfoMoveType.innerHTML = '';
  if (els.cardInfoMove) els.cardInfoMove.innerHTML = '';
  if (els.cardInfoBiotype) els.cardInfoBiotype.innerHTML = '';
}

function enforceDamageApplicationVisibility(card, root = els.cardInfoOverlay) {
  if (!root) return;
  const visible = hasExplicitDamageApplication(card);
  root.classList.toggle('has-damage-application', visible);
  root.classList.toggle('no-damage-application', !visible);
  if (!visible) {
    root.querySelectorAll('[data-info-kind="damageApplication"]').forEach(node => node.remove());
  }
}


const CARD_RARITY_ICON_ASSETS = {
  // Conserva exactamente el orden visual previo de los sprites (1→9).
  ordinary: 'assets/rarities/rarity-ordinary.png',
  uncommon: 'assets/rarities/rarity-uncommon.png',
  infrequent: 'assets/rarities/rarity-extraordinary.png',
  unusual: 'assets/rarities/rarity-singular.png',
  extraordinary: 'assets/rarities/rarity-infrequent.png',
  strange: 'assets/rarities/rarity-unusual.png',
  singular: 'assets/rarities/rarity-strange.png',
  legendary: 'assets/rarities/rarity-mythic.png',
  mythic: 'assets/rarities/rarity-legendary.png',
};

const CARD_RARITY_LABELS = {
  ordinary: 'Ordinaria',
  uncommon: 'Poco ordinaria',
  infrequent: 'Infrecuente',
  unusual: 'Inhabitual',
  extraordinary: 'Extraordinaria',
  strange: 'Extraña',
  singular: 'Singular',
  legendary: 'Legendaria',
  mythic: 'Mítica',
};

const CARD_RARITY_META = Object.freeze({
  ordinary: Object.freeze({ rank: 1, group: 'Bajas (Básicas)', description: 'La carta base, común y corriente. Forma el esqueleto de cualquier mazo.' }),
  uncommon: Object.freeze({ rank: 2, group: 'Bajas (Básicas)', description: 'Un paso inmediato arriba de la común. Sigue siendo muy vista en los sobres.' }),
  infrequent: Object.freeze({ rank: 3, group: 'Bajas (Básicas)', description: 'Ya no sale en todos lados, pero los jugadores conseguirán muchas de ellas.' }),
  unusual: Object.freeze({ rank: 4, group: 'Medias (Especiales)', description: 'Algo que no ocurre habitualmente. Ideal para abrir el nivel de diseño medio.' }),
  extraordinary: Object.freeze({ rank: 5, group: 'Medias (Especiales)', description: 'Va más allá de lo ordinario. Cartas con mecánicas más complejas.' }),
  strange: Object.freeze({ rank: 6, group: 'Medias (Especiales)', description: 'Algo raro de ver. Cartas difíciles de comprender o encontrar en la naturaleza.' }),
  singular: Object.freeze({ rank: 7, group: 'Altas (Supremas)', description: 'Única en su tipo. El puente perfecto y antesala hacia lo legendario.' }),
  legendary: Object.freeze({ rank: 8, group: 'Altas (Supremas)', description: 'Personajes con historia, reliquias o deidades. Muy baja tasa de aparición.' }),
  mythic: Object.freeze({ rank: 9, group: 'Altas (Supremas)', description: 'La cúspide del juego. Fuerzas divinas o prohibidas. La joya de la corona.' }),
});

const CARD_RARITY_ORDER = Object.freeze(['ordinary','uncommon','infrequent','unusual','extraordinary','strange','singular','legendary','mythic']);

function normalizeCardRarityId(rarity = '') {
  const value = String(rarity || '').trim().toLowerCase();
  const aliases = {
    common: 'ordinary',
    ordinary: 'ordinary',
    ordinaria: 'ordinary',
    uncommon: 'uncommon',
    pocoordinaria: 'uncommon',
    'poco ordinaria': 'uncommon',
    extraordinary: 'extraordinary',
    extraordinary: 'extraordinary',
    'extra ordinaria': 'extraordinary',
    extraordinaria: 'extraordinary',
    singular: 'singular',
    infrequent: 'infrequent',
    infrecuente: 'infrequent',
    unusual: 'unusual',
    inhabitual: 'unusual',
    strange: 'strange',
    extrana: 'strange',
    extraña: 'strange',
    mythic: 'mythic',
    mitica: 'mythic',
    mítica: 'mythic',
    legendary: 'legendary',
    legendaria: 'legendary',
  };
  return aliases[value] || 'ordinary';
}

function getCardVisualRarity(card) {
  // Una carta normal tiene una sola verdad: PB calculado → rareza → ícono/bono.
  // forceRarityId queda reservado para muestras de booster/debug o un override explícito de desarrollo.
  const allowForcedRarity = card?.boosterDebugSample === true || card?.allowForcedRarity === true || card?.rarityOverrideMode === 'debug';
  const forcedId = allowForcedRarity && card?.forceRarityId ? normalizeCardRarityId(card.forceRarityId) : '';
  let scoreRarity = null;
  if (!forcedId) {
    try {
      scoreRarity = typeof calculateCardBattleScore === 'function' ? calculateCardBattleScore(card) : null;
    } catch (error) {
      scoreRarity = null;
    }
  }
  const id = forcedId || scoreRarity?.rarityId || normalizeCardRarityId(card?.rarity);
  const meta = CARD_RARITY_META[id] || CARD_RARITY_META.ordinary;
  return {
    id,
    label: forcedId ? (CARD_RARITY_LABELS[id] || 'Ordinaria') : (scoreRarity?.rarityLabel || CARD_RARITY_LABELS[id] || 'Ordinaria'),
    asset: CARD_RARITY_ICON_ASSETS[id] || CARD_RARITY_ICON_ASSETS.ordinary,
    rank: meta.rank,
    group: meta.group,
    description: meta.description,
  };
}

function renderCardInfoDomainBadge(card) {
  if (!els.cardInfoPreview || !card) return;
  const main = els.cardInfoPreview.closest('.card-info-main');

  // Limpia cualquier dominio anterior, tanto del preview antiguo como del host flotante.
  els.cardInfoPreview.querySelectorAll(':scope > .card-domain-zone').forEach(node => node.remove());
  main?.querySelectorAll(':scope > .card-info-domain-floating').forEach(node => node.remove());

  const domain = createCardDomainElement(card);
  if (!domain) return;

  // En partida el dominio mantiene exactamente la posición histórica visual,
  // pero deja de pertenecer al contenedor de la miniatura para que éste no lo recorte.
  if (document.body.classList.contains('rok-battle-mode') && main) {
    domain.classList.add('card-info-domain-floating');
    main.appendChild(domain);
    return;
  }

  // Biblioteca/otros contextos conservan la estructura previa.
  els.cardInfoPreview.appendChild(domain);
}

function renderCardInfoRarityBadge(card) {
  if (!els.cardInfoPreview || !card) return;
  const rarity = getCardVisualRarity(card);
  const badge = document.createElement('button');
  badge.type = 'button';
  badge.className = `card-info-rarity-badge rarity-${rarity.id}`;
  badge.dataset.infoKind = 'battleScoreRarity';
  badge.dataset.infoId = rarity.id;
  badge.title = `Rareza: ${rarity.label} · nivel ${rarity.rank} de 9`;
  badge.setAttribute('aria-label', `Consultar rareza ${rarity.label}`);
  badge.innerHTML = `<img src="${rarity.asset}" alt="Rareza ${rarity.label}">`;
  badge.addEventListener('click', (event) => {
    event.preventDefault();
    event.stopPropagation();
    event.stopImmediatePropagation?.();
    openCardMetaInfo('battleScoreRarity', rarity.id, card);
  });
  els.cardInfoPreview.appendChild(badge);
  els.cardInfoRarityBadge = badge;
}

function getCardBattlePointsValue(card) {
  if (!card) return null;
  try {
    const result = typeof calculateCardBattleScore === 'function' ? calculateCardBattleScore(card) : null;
    const value = Number(result?.battlePoints);
    return Number.isFinite(value) ? Math.max(5, Math.round(value)) : null;
  } catch (error) {
    return null;
  }
}

function renderCardInfoBattlePointsChip(card) {
  if (!els.cardInfoType || !card || card.type === 'kaster') return;
  const points = getCardBattlePointsValue(card);
  if (!Number.isFinite(points)) return;
  const chip = document.createElement('span');
  chip.className = 'card-info-pb-chip';
  chip.title = `Puntos de Batalla: ${points}`;
  chip.innerHTML = `<span>PB</span><strong>${points}</strong>`;
  els.cardInfoType.appendChild(chip);
}

function getVisibleLibraryBuilderCardIdsFromDom() {
  if (!els.libraryBuilderLibraryGrid) return [];
  return Array.from(els.libraryBuilderLibraryGrid.querySelectorAll('.library-builder-card-tile[data-origin="library"][data-card-id]'))
    .map(tile => tile.dataset.cardId)
    .filter(cardId => cardId && CARD_LIBRARY[cardId]);
}

function ensureCardInfoLibraryNav() {
  if (!els.cardInfoOverlay) return null;
  let nav = els.cardInfoOverlay.querySelector('.card-info-library-nav');
  if (nav) return nav;
  nav = document.createElement('div');
  nav.className = 'card-info-library-nav';
  nav.innerHTML = `
    <button type="button" class="card-info-library-nav-btn card-info-library-prev" data-dir="prev" aria-label="Carta anterior">‹</button>
    <button type="button" class="card-info-library-nav-btn card-info-library-next" data-dir="next" aria-label="Carta siguiente">›</button>
  `;
  nav.addEventListener('click', event => {
    const button = event.target.closest('.card-info-library-nav-btn');
    if (!button || button.disabled) return;
    event.preventDefault();
    event.stopPropagation();
    const ids = getVisibleLibraryBuilderCardIdsFromDom();
    const currentId = state?.infoCard?.cardId;
    const currentIndex = ids.indexOf(currentId);
    if (currentIndex < 0) return;
    const nextIndex = button.dataset.dir === 'prev' ? currentIndex - 1 : currentIndex + 1;
    if (nextIndex < 0 || nextIndex >= ids.length) return;
    const nextId = ids[nextIndex];
    const currentSource = state?.infoCard?.source === 'cardCreator' ? 'cardCreator' : 'libraryBuilder';
    libraryBuilderState.selectedLibraryCardId = nextId;
    libraryBuilderState.selectedSpellbookIndex = null;
    openCardInfo(nextId, null, null, { source: currentSource, origin: 'library' });
  });
  els.cardInfoOverlay.appendChild(nav);
  return nav;
}

function updateCardInfoLibraryNav(cardId, meta = {}) {
  const nav = ensureCardInfoLibraryNav();
  if (!nav) return;
  const allowed = Boolean((meta?.source === 'libraryBuilder' || meta?.source === 'cardCreator') && meta?.origin === 'library');
  nav.hidden = !allowed;
  nav.setAttribute('aria-hidden', allowed ? 'false' : 'true');
  if (!allowed) return;
  const ids = getVisibleLibraryBuilderCardIdsFromDom();
  const index = ids.indexOf(cardId);
  const prevBtn = nav.querySelector('[data-dir="prev"]');
  const nextBtn = nav.querySelector('[data-dir="next"]');
  const atStart = index <= 0;
  const atEnd = index < 0 || index >= ids.length - 1;
  if (prevBtn) {
    prevBtn.disabled = atStart;
    prevBtn.title = atStart ? 'Primera carta' : 'Carta anterior';
  }
  if (nextBtn) {
    nextBtn.disabled = atEnd;
    nextBtn.title = atEnd ? 'Última carta' : 'Carta siguiente';
  }
}

function hideCardInfoLibraryNav() {
  const nav = els.cardInfoOverlay?.querySelector('.card-info-library-nav');
  if (!nav) return;
  nav.hidden = true;
  nav.setAttribute('aria-hidden', 'true');
}

function resolveCardInfoTheme(card, meta = {}) {
  const elementId = getCardElementId(card);
  return {
    elementId,
    color: getElementColorById(elementId, '#5400FF'),
    playerId: null,
    source: 'card',
  };
}

function applyCardInfoTheme(card, meta = {}) {
  if (!els.cardInfoOverlay || !card) return;
  const theme = resolveCardInfoTheme(card, meta);
  const factorTheme = getCardFactorThemeColors(card);
  els.cardInfoOverlay.style.setProperty('--p1', theme.color);
  els.cardInfoOverlay.style.setProperty('--p1-soft', `color-mix(in srgb, ${theme.color} 28%, transparent)`);
  els.cardInfoOverlay.style.setProperty('--caster-info-color', theme.color);
  els.cardInfoOverlay.style.setProperty('--card-info-theme-color', theme.color);
  els.cardInfoOverlay.style.setProperty('--card-factor-theme-color', factorTheme.secondary);
  els.cardInfoOverlay.style.setProperty('--card-factor-accent-color', factorTheme.primary);
  els.cardInfoOverlay.style.setProperty('--card-factor-foreground-color', getReadableForegroundForTheme(factorTheme.primary, factorTheme.secondary));
  els.cardInfoOverlay.dataset.elementId = theme.elementId || '';
  els.cardInfoOverlay.dataset.themeSource = theme.source;
}

function applyCardMetaInfoTheme(card = null) {
  if (!els.cardMetaInfoOverlay) return;
  const sourceCard = card || CARD_LIBRARY[state.infoCard?.cardId] || null;
  const mainColor = els.cardInfoOverlay?.style.getPropertyValue('--card-info-theme-color')?.trim();
  const mainElementId = els.cardInfoOverlay?.dataset?.elementId || '';
  const fallbackTheme = sourceCard ? resolveCardInfoTheme(sourceCard, state.infoCard || {}) : null;
  const color = mainColor || fallbackTheme?.color || '#5400FF';
  const factorTheme = getCardFactorThemeColors(sourceCard);
  els.cardMetaInfoOverlay.classList.add('card-element-meta-theme');
  els.cardMetaInfoOverlay.style.setProperty('--meta-theme-color', color);
  els.cardMetaInfoOverlay.style.setProperty('--meta-factor-theme-color', factorTheme.secondary);
  els.cardMetaInfoOverlay.style.setProperty('--meta-factor-accent-color', factorTheme.primary);
  els.cardMetaInfoOverlay.style.setProperty('--meta-factor-foreground-color', getReadableForegroundForTheme(factorTheme.primary, factorTheme.secondary));
  if (mainElementId || fallbackTheme?.elementId) els.cardMetaInfoOverlay.dataset.elementTheme = mainElementId || fallbackTheme.elementId;
}

function renderCardInfoOriginBadge(card) {
  if (!els.cardInfoPreview) return;
  els.cardInfoPreview.querySelectorAll('.card-info-origin-badge').forEach(node => node.remove());
  if (getRokCardOriginId(card) !== ROK_ORIGIN_JAPAN_ID) return;
  const badge = document.createElement('span');
  badge.className = 'card-info-origin-badge card-info-origin-badge-japan';
  badge.title = 'Origen: Japón';
  badge.setAttribute('aria-label', 'Origen Japón');
  badge.innerHTML = `<img src="${ROK_ORIGIN_JAPAN_ICON}" alt="Origen Japón">`;
  els.cardInfoPreview.appendChild(badge);
}

function openCardInfo(cardId, slotIndex, tab, meta = {}) {
  els.cardInfoOverlay?.classList.remove('guardian-info-open');
  const baseCard = CARD_LIBRARY[cardId];
  if (!baseCard || !els.cardInfoOverlay) return;
  let card;
  if (meta?.source === 'castQueue') {
    const queuePlayerId = Number(meta?.playerId ?? LOCAL_PLAYER_ID);
    const queuedItem = findQueuedItemBySpawn(queuePlayerId, meta?.spawnId || '');
    card = buildCastQueuePersistentCardInfoViewModel(baseCard, queuePlayerId, queuedItem);
  } else {
    card = buildCardInfoViewModel(baseCard, meta);
    if (card === baseCard && tab != null && slotIndex != null && Number.isInteger(Number(tab)) && Number.isInteger(Number(slotIndex)) && Number(tab) >= 0 && Number(slotIndex) >= 0) {
      card = buildSpellbookPersistentCardInfoViewModel(card, LOCAL_PLAYER_ID, Number(tab), Number(slotIndex));
    }
  }
  if (getCardTypeId(card) === 'kaster' && (meta?.source === 'libraryBuilder' || meta?.source === 'cardCreator')) {
    card = buildCasterProgressedInfoCard(card);
  }
  const isSpell = isSpellCard(card);
  const isAbility = getCardTypeId(card) === 'ability';
  const isSpellLikeSupportCard = isSpell || isAbility;

  resetCardInfoSpellbookQuantity();
  state.infoCard = { cardId, slotIndex, tab, ...meta };
  applyCardInfoTheme(card, meta);
  els.cardInfoPreview.innerHTML = '';
  els.cardInfoPreview.appendChild(createCardElement(card));
  renderCardInfoDomainBadge(card);
  renderCardInfoOriginBadge(card);
  renderCardInfoRarityBadge(card);
  bindCardInfoName(card);
  setCardInfoType(getCardTypeId(card));
  renderCasterLevelProgress(card);
  renderCardInfoBattlePointsChip(card);
  updateCardInfoLibraryNav(card.id, meta);
  renderCardInfoMeta(card);
  renderCardInfoSummaryTags(card);
  renderCardInfoTraits(card);
  renderCardInfoCasterCompatibility(card);
  renderCardAbilityPowerPanel(card);
  els.cardInfoOverlay.classList.toggle('spell-card-info', isSpellLikeSupportCard);
  if (isSpellLikeSupportCard) {
    renderSpellInfoRows(card);
    renderCardInfoCooldownTray(card, { show: false });
    enforceDamageApplicationVisibility(card);
    els.cardInfoOverlay.classList.add('open');
    els.cardInfoOverlay.setAttribute('aria-hidden', 'false');
    scheduleCardInfoStatRowScrollCueSync();
    updateCardInfoAction();
    updateBattleScoreDebugToggleButton(card, meta);
    log(`${card.name}: vista de ${isAbility ? 'habilidad' : 'hechizo'} abierta.`);
    return;
  }
  const profile = getAttackProfile(card);
  const weapon = getWeaponProfile(card);
  if (els.cardInfoDamage) {
    els.cardInfoDamage.innerHTML = `<div class="card-info-chip-stack card-info-chip-stack-damage">${renderWeaponDamageChip(card)}</div>`;
    bindInlineInfoButtons(els.cardInfoDamage, card);
  }
  if (els.cardInfoLife) {
    const defenseFactors = getCardDefenseFactors(card);
    const defenseFactorChips = defenseFactors.map(factorEntry => renderDefenseFactorChip(factorEntry, card)).join('');
    els.cardInfoLife.innerHTML = `<div class="card-info-chip-stack card-info-chip-stack-life-defense">${renderLifeBaseChip(card)}${defenseFactorChips}</div>`;
    bindInlineInfoButtons(els.cardInfoLife, card);
  }
  if (els.cardInfoDefense) els.cardInfoDefense.innerHTML = Number(card.stats?.def ?? 0) > 0 ? `<div class="card-info-chip-stack"><button type="button" class="card-info-value-chip" data-info-kind="defenseStat" data-info-id="defense" title="Defensa: ${card.stats.def}"><span class="card-info-value-chip-key">DEF</span><span>${card.stats.def}</span></button></div>` : '';
  if (els.cardInfoAttackType) {
    els.cardInfoAttackType.innerHTML = `<div class="card-info-chip-stack">${renderCombatModeChip(card)}${renderDamageApplicationChip(card)}</div>`;
    bindInlineInfoButtons(els.cardInfoAttackType, card);
  }
  if (els.cardInfoRange) {
    els.cardInfoRange.innerHTML = `<div class="card-info-chip-stack card-info-chip-stack-range">${renderAttackRangeChip(card)}${renderAttackPrecisionChip(card)}${renderAttackSpeedChip(card)}</div>`;
    bindInlineInfoButtons(els.cardInfoRange, card);
  }
  if (els.cardInfoFactors) {
    const attackFactors = getCardAttackFactors(card);
    const runtimeFactors = Array.isArray(card?.__runtime?.activeFactors) ? card.__runtime.activeFactors : [];
    const mergedFactors = mergeFactorEntriesForDisplay([...attackFactors, ...runtimeFactors]);
    const factorChips = mergedFactors.map(factorEntry => renderFactorChip(factorEntry, card)).join('');
    els.cardInfoFactors.innerHTML = factorChips ? `<div class="card-info-chip-stack card-info-chip-stack-factors">${factorChips}</div>` : '';
    bindInlineInfoButtons(els.cardInfoFactors, card);
  }
  if (els.cardInfoMoveType) {
    els.cardInfoMoveType.innerHTML = `<div class="card-info-chip-stack">${renderMovementTypeChip(card)}</div>`;
    bindInlineInfoButtons(els.cardInfoMoveType, card);
  }
  if (els.cardInfoMove) {
    els.cardInfoMove.innerHTML = `<div class="card-info-chip-stack">${renderSpeedChip(card)}</div>`;
    bindInlineInfoButtons(els.cardInfoMove, card);
  }
  if (els.cardInfoBiotype) {
    els.cardInfoBiotype.innerHTML = `<div class="card-info-chip-stack">${renderBiotypeChip(card)}</div>`;
    bindInlineInfoButtons(els.cardInfoBiotype, card);
  }
  if (els.cardInfoCost) {
    const costChip = renderCardCostChip(card);
    els.cardInfoCost.innerHTML = costChip ? `<div class="card-info-chip-stack">${costChip}</div>` : '';
    if (costChip) bindInlineInfoButtons(els.cardInfoCost, card);
  }
  if (els.cardInfoCastTime) {
    els.cardInfoCastTime.innerHTML = `<div class="card-info-chip-stack">${renderCastTimeChip(card)}</div>`;
    bindInlineInfoButtons(els.cardInfoCastTime, card);
  }
  if (els.cardInfoRestoreTime) {
    const restoreTimeChip = renderRestoreTimeChip(card);
    els.cardInfoRestoreTime.innerHTML = restoreTimeChip ? `<div class="card-info-chip-stack">${restoreTimeChip}</div>` : '';
    bindInlineInfoButtons(els.cardInfoRestoreTime, card);
  }
  if (els.cardInfoSpellbookCooldown) {
    const cooldownChip = renderSpellbookCooldownChip(card);
    els.cardInfoSpellbookCooldown.innerHTML = cooldownChip ? `<div class="card-info-chip-stack">${cooldownChip}</div>` : '';
    if (cooldownChip) bindInlineInfoButtons(els.cardInfoSpellbookCooldown, card);
  }
  if (els.cardInfoUtilityFactors) {
    const utilityFactorChips = getCardUtilityFactors(card).map(factorEntry => renderFactorChip(factorEntry, card)).join('');
    els.cardInfoUtilityFactors.innerHTML = utilityFactorChips ? `<div class="card-info-chip-stack card-info-chip-stack-factors">${utilityFactorChips}</div>` : '';
    if (utilityFactorChips) bindInlineInfoButtons(els.cardInfoUtilityFactors, card);
  }
  if (getCardTypeId(card) === 'kaster' && (meta?.source === 'libraryBuilder' || meta?.source === 'cardCreator')) renderLibraryCasterSystemRows(card);
  renderCardInfoCooldownTray(card, { show: true });
  enforceDamageApplicationVisibility(card);
  els.cardInfoOverlay.classList.add('open');
  els.cardInfoOverlay.setAttribute('aria-hidden', 'false');
  scheduleCardInfoStatRowScrollCueSync();
  updateCardInfoAction();
  updateBattleScoreDebugToggleButton(card, meta);
  log(`${card.name}: vista de carta abierta.`);
}

