function unitHasBurnFactor(unit) {
  return unitHasActiveFactor(unit, 'burn');
}

function createCombatSideNode(side, opponentSide = null) {
  const card = CARD_LIBRARY[side.unit.cardId];
  const damage = getEffectiveUnitDamageValue(side.unit, card, side.playerId);
  const life = side.unit.hp ?? card?.stats?.life ?? 0;

  const row = document.createElement('div');
  row.className = `combat-side player-${side.playerId}`;
  row.dataset.playerId = String(side.playerId);
  row.dataset.unitId = String(side.unit.id);
  row.dataset.cardId = side.unit.cardId || '';
  const elementId = getUnitElementId(side.playerId, side.unit);
  const element = getElementById(elementId);
  row.dataset.elementId = elementId;
  row.style.setProperty('--combat-element-color', element?.color || '#5400FF');
  if ((side.unit.damageFlashUntil || 0) > Date.now()) row.classList.add('damage-flash');

  const mini = document.createElement('div');
  mini.className = 'combat-mini-card';
  mini.title = card?.name || 'Invocación';
  const linkedSpellLinks = getUnitLinkedSpellLinks(side.playerId, side.unit.id);
  const cardVisual = createSelectedUnitCommandCardVisual({ card, linkedSpellLinks });
  cardVisual.classList.add('combat-linked-card-composite');
  if (linkedSpellLinks.length) {
    mini.classList.add('linked-spell-popover-trigger');
    mini.dataset.linkedSpellCount = String(linkedSpellLinks.length);
    mini.addEventListener('click', event => {
      stopTargetMenuEvent(event);
      toggleLinkedSpellPopover(row, linkedSpellLinks, {
        onOpenInfo(link, spellCard) {
          openCardInfo(spellCard.id, null, null, { source: 'activeSpell', playerId: side.playerId, targetUnitId: side.unit.id });
        },
      });
    });
  }
  mini.appendChild(cardVisual);

  const evasionPenalty = getCombatHudEvasionPenaltyForAttacker(side, opponentSide);
  if (evasionPenalty) mini.appendChild(createCombatMiniModifierChip(evasionPenalty));
  if (unitHasBurnFactor(side.unit)) {
    const burnButton = document.createElement('button');
    burnButton.type = 'button';
    burnButton.className = 'combat-mini-status-button combat-mini-status-burn';
    burnButton.title = 'Quemadura';
    burnButton.appendChild(createCombatBurnStatusIcon());
    burnButton.addEventListener('click', event => {
      stopTargetMenuEvent(event);
      const cardModel = buildCardInfoViewModel(card, { source: 'arena', playerId: side.playerId, unitId: side.unit.id });
      const factorEntry = getActiveFactorEntry(side.unit, 'burn');
      openCardMetaInfo('factor', 'burn', cardModel, { factorLevel: Number(factorEntry?.level) || 1, factorSource: getFactorEntrySourceId(factorEntry) });
    });
    mini.appendChild(burnButton);
  }

  const damageBadge = document.createElement('span');
  damageBadge.className = 'combat-card-corner combat-card-damage';
  damageBadge.textContent = damage;

  const lifeBadge = document.createElement('span');
  lifeBadge.className = `combat-card-corner combat-card-life ${lifeToneClass(side.unit)}`;
  lifeBadge.textContent = life;

  mini.appendChild(damageBadge);
  mini.appendChild(lifeBadge);
  row.appendChild(mini);
  return row;
}

function getTargetAccessLabel(target) {
  if (!target) return 'Objetivo';
  if (target.type === 'caster') return getCasterDisplayName(state.players[target.playerId]?.caster, `Kaster J${target.playerId}`);
  if (target.type === 'guardian') return 'Guardián';
  if (target.type === 'invocation') {
    const unit = getUnitById(target.playerId, target.unitId);
    const card = CARD_LIBRARY[unit?.cardId];
    return card?.shortName || card?.name || 'Invocación';
  }
  return 'Objetivo';
}

function createTargetAccessMini(target) {
  const mini = document.createElement('div');
  mini.className = `target-access-mini target-access-${target.type}`;
  if (target.type === 'invocation') {
    const unit = getUnitById(target.playerId, target.unitId);
    const card = CARD_LIBRARY[unit?.cardId];
    mini.innerHTML = card ? `<img src="${card.tokenImage || card.artImage}" alt="${card.name}">` : '<span>?</span>';
    return mini;
  }
  if (target.type === 'guardian') {
    mini.innerHTML = `<img src="${getGuardianAssetForPlayer(target.playerId)}" alt="Guardián">`;
    return mini;
  }
  const caster = state.players[target.playerId]?.caster;
  mini.innerHTML = `<img src="${getCasterTokenImage(caster)}" alt="${getTargetAccessLabel(target)}">`;
  return mini;
}

function bindTargetChoiceRowHover(row, target) {
  if (!row || !target) return;
  row.classList.add('target-access-row-hoverable');
  row.addEventListener('pointerenter', () => showTargetChoiceHoverFoil(target));
  row.addEventListener('pointerleave', clearYasuganaTargetHoverFoil);
  row.addEventListener('focusin', () => showTargetChoiceHoverFoil(target));
  row.addEventListener('focusout', event => {
    if (!row.contains(event.relatedTarget)) clearYasuganaTargetHoverFoil();
  });
}

function renderTargetAccessPanel() {
  if (!els.targetAccessPanel) return;
  els.targetAccessPanel.innerHTML = '';

  const pendingPower = ['yasuganaBlindness', 'yasuganaVigilia', 'kurayamiMark', 'kaguyaChargedShot'].includes(state.pendingPowerAction?.kind)
    ? state.pendingPowerAction
    : null;
  if (pendingPower?.kind === 'yasuganaVigilia') {
    els.targetAccessPanel.classList.remove('visible');
    els.targetAccessPanel.setAttribute('aria-hidden', 'true');
    return;
  }
  if (pendingPower?.kind === 'kaguyaChargedShot') {
    const sourceUnit = getUnitById(pendingPower.playerId, pendingPower.unitId);
    const invalidSource = !sourceUnit
      || Number(pendingPower.playerId) !== Number(LOCAL_PLAYER_ID)
      || sourceUnit.status === 'restoring'
      || !sourceUnit.kaguyaChargedShotPrimed;
    if (invalidSource) {
      els.targetAccessPanel.classList.remove('visible');
      els.targetAccessPanel.setAttribute('aria-hidden', 'true');
      return;
    }
    const targets = getKaguyaChargedShotTargets(pendingPower.playerId, sourceUnit);
    if (!targets.length) {
      els.targetAccessPanel.classList.remove('visible');
      els.targetAccessPanel.setAttribute('aria-hidden', 'true');
      return;
    }
    els.targetAccessPanel.classList.add('visible');
    els.targetAccessPanel.setAttribute('aria-hidden', 'false');
    targets.forEach(target => {
      const row = document.createElement('div');
      row.className = 'target-access-row';
      bindTargetChoiceRowHover(row, target);

      const miniBtn = document.createElement('button');
      miniBtn.type = 'button';
      miniBtn.className = 'target-access-mini-btn';
      miniBtn.title = `${getTargetAccessLabel(target)} · ${coordLabel(target.row, target.col)}`;
      miniBtn.appendChild(createTargetAccessMini(target));
      miniBtn.addEventListener('click', event => {
        stopTargetMenuEvent(event);
        openInfoForTarget(target);
      });
      row.appendChild(miniBtn);

      const btn = document.createElement('button');
      btn.type = 'button';
      btn.className = 'target-access-btn';
      btn.textContent = 'Elegir';
      btn.title = `Iniciar Disparo energizado contra ${getTargetAccessLabel(target)} en ${coordLabel(target.row, target.col)}`;
      btn.addEventListener('click', event => {
        stopTargetMenuEvent(event);
        void resolveKaguyaChargedShotTarget(pendingPower.playerId, pendingPower.unitId, target);
      });
      row.appendChild(btn);

      const cellBubble = document.createElement('span');
      cellBubble.className = 'target-access-cell-bubble';
      cellBubble.textContent = coordLabel(target.row, target.col);
      cellBubble.title = `Casilla ${coordLabel(target.row, target.col)}`;
      row.appendChild(cellBubble);
      els.targetAccessPanel.appendChild(row);
    });
    return;
  }
  if (pendingPower) {
    const sourceUnit = getUnitById(pendingPower.playerId, pendingPower.unitId);
    const isKurayamiSelection = pendingPower.kind === 'kurayamiMark';
    const invalidSource = !sourceUnit
      || Number(pendingPower.playerId) !== Number(LOCAL_PLAYER_ID)
      || (!isKurayamiSelection && (Number(state.activePlayer) !== Number(LOCAL_PLAYER_ID) || currentPhase().id !== 'resolution'));
    if (invalidSource) {
      els.targetAccessPanel.classList.remove('visible');
      els.targetAccessPanel.setAttribute('aria-hidden', 'true');
      return;
    }
    const targets = isKurayamiSelection
      ? getKurayamiPowerTargets(pendingPower.playerId, sourceUnit)
      : (pendingPower.kind === 'yasuganaBlindness'
        ? getYasuganaBlindnessTargets(pendingPower.playerId, sourceUnit)
        : getYasuganaVigiliaTargets(pendingPower.playerId, sourceUnit));
    if (!targets.length) {
      els.targetAccessPanel.classList.remove('visible');
      els.targetAccessPanel.setAttribute('aria-hidden', 'true');
      return;
    }
    els.targetAccessPanel.classList.add('visible');
    els.targetAccessPanel.setAttribute('aria-hidden', 'false');
    targets.forEach(unit => {
      const target = { type: 'invocation', playerId: unit.owner, unitId: unit.id, row: unit.row, col: unit.col };
      const row = document.createElement('div');
      row.className = 'target-access-row';
      bindTargetChoiceRowHover(row, target);

      const miniBtn = document.createElement('button');
      miniBtn.type = 'button';
      miniBtn.className = 'target-access-mini-btn';
      miniBtn.title = `${getTargetAccessLabel(target)} · ${coordLabel(target.row, target.col)}`;
      miniBtn.appendChild(createTargetAccessMini(target));
      miniBtn.addEventListener('click', event => {
        stopTargetMenuEvent(event);
        openInfoForTarget(target);
      });
      row.appendChild(miniBtn);

      const btn = document.createElement('button');
      btn.type = 'button';
      btn.className = 'target-access-btn';
      btn.textContent = 'Elegir';
      btn.title = isKurayamiSelection
        ? `Marcar con Shizukesa no Shi-in en ${coordLabel(target.row, target.col)}`
        : `${pendingPower.kind === 'yasuganaBlindness' ? 'Aplicar Ceguera' : 'Enseñar Vigilia'} en ${coordLabel(target.row, target.col)}`;
      btn.addEventListener('click', event => {
        stopTargetMenuEvent(event);
        if (isKurayamiSelection) {
          resolveKurayamiPowerTarget(pendingPower.playerId, pendingPower.unitId, target.playerId, target.unitId);
        } else {
          resolveYasuganaPowerTarget(pendingPower.playerId, pendingPower.unitId, target.playerId, target.unitId, pendingPower.kind);
        }
      });
      row.appendChild(btn);

      const cellBubble = document.createElement('span');
      cellBubble.className = 'target-access-cell-bubble';
      cellBubble.textContent = coordLabel(target.row, target.col);
      cellBubble.title = `Casilla ${coordLabel(target.row, target.col)}`;
      row.appendChild(cellBubble);

      els.targetAccessPanel.appendChild(row);
    });
    return;
  }

  const source = getSourceUnitFromSelection();
  if (!source || source.playerId !== LOCAL_PLAYER_ID || state.activePlayer !== LOCAL_PLAYER_ID || currentPhase().id !== 'resolution') {
    els.targetAccessPanel.classList.remove('visible');
    els.targetAccessPanel.setAttribute('aria-hidden', 'true');
    return;
  }
  const targets = getTargetsInRangeForSource(source)
    .filter(target => Number(target.playerId) !== Number(source.playerId) || isAlliedAttackReceiverTarget(source, target));
  if (!targets.length) {
    els.targetAccessPanel.classList.remove('visible');
    return;
  }
  els.targetAccessPanel.classList.add('visible');
  els.targetAccessPanel.setAttribute('aria-hidden', 'false');
  targets.forEach(target => {
    const row = document.createElement('div');
    row.className = 'target-access-row';
    bindTargetChoiceRowHover(row, target);

    const miniBtn = document.createElement('button');
    miniBtn.type = 'button';
    miniBtn.className = 'target-access-mini-btn';
    miniBtn.title = `${getTargetAccessLabel(target)} · ${coordLabel(target.row, target.col)}`;
    miniBtn.appendChild(createTargetAccessMini(target));
    miniBtn.addEventListener('click', event => {
      stopTargetMenuEvent(event);
      openInfoForTarget(target);
    });
    row.appendChild(miniBtn);

    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'target-access-btn';
    btn.textContent = 'Elegir';
    btn.title = `Elegir objetivo en ${coordLabel(target.row, target.col)}`;
    btn.addEventListener('click', event => {
      stopTargetMenuEvent(event);
      try { window.ROK_DEBUG_RIBBON?.markAction?.(`targetAccess:${getTargetAccessLabel(target)}:${coordLabel(target.row, target.col)}`, event); } catch (_) {}
      if (state.activePlayer !== LOCAL_PLAYER_ID || currentPhase().id !== 'resolution') {
        clearCombatMenus();
        clearYasuganaTargetHoverFoil();
        els.targetAccessPanel.classList.remove('visible');
        els.targetAccessPanel.setAttribute('aria-hidden', 'true');
        log('Ese acceso de objetivo quedó viejo: solo puedes confirmar ataques en Resolución.');
        openInfoForTarget(target);
        return;
      }
      showTargetMenu(target);
    });
    row.appendChild(btn);

    const cellBubble = document.createElement('span');
    cellBubble.className = 'target-access-cell-bubble';
    cellBubble.textContent = coordLabel(target.row, target.col);
    cellBubble.title = `Casilla ${coordLabel(target.row, target.col)}`;
    row.appendChild(cellBubble);

    els.targetAccessPanel.appendChild(row);
  });
}

function loadHudModePreference() {
  try {
    const saved = localStorage.getItem('rokLite:hudMode');
    state.hudMode = saved === 'overlay' ? 'overlay' : 'anchored';
  } catch (error) {
    state.hudMode = 'anchored';
  }
}

function saveHudModePreference() {
  try {
    localStorage.setItem('rokLite:hudMode', state.hudMode || 'anchored');
  } catch (error) {}
}

function ensureHudOverlayLayer() {
  if (els.hudOverlayLayer) return els.hudOverlayLayer;
  const layer = document.createElement('div');
  layer.id = 'hudOverlayLayer';
  layer.className = 'hud-overlay-layer';
  getRokUiStage().appendChild(layer);
  els.hudOverlayLayer = layer;
  return layer;
}

function moveElementBefore(element, parent, beforeNode = null) {
  if (!element || !parent) return;
  if (beforeNode && beforeNode.parentElement === parent) {
    if (element.parentElement !== parent || element.nextSibling !== beforeNode) parent.insertBefore(element, beforeNode);
    return;
  }
  if (element.parentElement !== parent) parent.appendChild(element);
}

function syncHudOverlayLayerToBoard() {
  const layer = ensureHudOverlayLayer();
  const active = state.hudMode === 'overlay' && isBattleHudScreenActive();
  layer.classList.toggle('active', !!active);
  if (!active || !els.board) return;
  const viewportRect = els.board.getBoundingClientRect();
  const rect = window.ROK_LAYOUT_SCALE?.rectToLogical
    ? window.ROK_LAYOUT_SCALE.rectToLogical(viewportRect)
    : viewportRect;
  layer.style.left = `${Math.round(rect.left)}px`;
  layer.style.top = `${Math.round(rect.top)}px`;
  layer.style.width = `${Math.round(rect.width)}px`;
  layer.style.height = `${Math.round(rect.height)}px`;
}

function applyHudModeLayout() {
  const mode = state.hudMode === 'overlay' ? 'overlay' : 'anchored';
  const overlayLayer = ensureHudOverlayLayer();
  const useOverlay = mode === 'overlay' && isBattleHudScreenActive();
  syncHudOverlayLayerToBoard();
  // HUD-08.20c · Rival y aliado pertenecen a la MISMA banda. La lógica
  // histórica movía el HUD rival directamente a .game-shell y rompía el
  // wrapper .caster-hud-pair, lo que terminaba apilando/separando ambos HUD.
  // Si existe la banda nueva, ambos Kasters permanecen dentro de ella.
  const casterHudPair = els.gameShell?.querySelector?.('.caster-hud-pair') || null;
  if (casterHudPair) {
    const localCasterPanel = els.casterWidePanel || casterHudPair.querySelector('.caster-wide-panel');
    if (els.opponentCasterHud?.parentElement !== casterHudPair) {
      moveElementBefore(els.opponentCasterHud, casterHudPair, localCasterPanel?.parentElement === casterHudPair ? localCasterPanel : null);
    }
    if (localCasterPanel && localCasterPanel.parentElement !== casterHudPair) casterHudPair.appendChild(localCasterPanel);
  } else if (els.gameShell && els.opponentCasterHud?.parentElement !== els.gameShell) {
    // Fallback para HTML histórico sin .caster-hud-pair.
    const localCasterPanel = els.gameShell.querySelector('.caster-wide-panel');
    moveElementBefore(els.opponentCasterHud, els.gameShell, localCasterPanel);
  }
  if (useOverlay) {
    moveElementBefore(els.opponentThinkingNotice, overlayLayer);
    moveElementBefore(els.selectedUnitCommandPanel, overlayLayer);
    moveElementBefore(els.persistentUnitCommandStack, overlayLayer);
    moveElementBefore(els.arenaEffectTrackers, overlayLayer);
    moveElementBefore(els.targetAccessPanel, overlayLayer);
    moveElementBefore(els.combatHud, overlayLayer);
    moveElementBefore(els.quickReactionWindow, overlayLayer);
    moveElementBefore(els.rivalQuickReactionWindow, overlayLayer);
  } else if (els.boardContent) {
    moveElementBefore(els.opponentThinkingNotice, els.boardContent, els.enemyGrid);
    moveElementBefore(els.selectedUnitCommandPanel, els.boardContent);
    moveElementBefore(els.persistentUnitCommandStack, els.boardContent);
    moveElementBefore(els.arenaEffectTrackers, els.boardContent);
    moveElementBefore(els.targetAccessPanel, els.boardContent);
    moveElementBefore(els.combatHud, els.boardContent);
    moveElementBefore(els.quickReactionWindow, els.boardContent);
    moveElementBefore(els.rivalQuickReactionWindow, els.boardContent);
  }
  refreshHudFloatingMenus();
  updateHudOverlayZoomState();
  refreshVisibleQuickReactionWindowAnchors();
}

function updateHudOverlayZoomState() {
  const mode = state.hudMode === 'overlay' ? 'overlay' : 'anchored';
  const nearMaxZoom = Number(boardView?.zoom || 1) >= 2.15;
  document.body.classList.toggle('hud-overlay-soft', mode === 'overlay' && nearMaxZoom && isBattleHudScreenActive());
  syncHudOverlayLayerToBoard();
}

function getHudFloatingMenuParent() {
  return state.hudMode === 'overlay' && isBattleHudScreenActive() ? ensureHudOverlayLayer() : els.boardContent;
}

function mountArenaEffectTrackersForHudMode() {
  if (!els.arenaEffectTrackers) return;
  // RT-08.13 S4 · Los persistentes globales dejan de ocupar superficie del
  // tablero y pasan al carril de Invocaciones. Fuera de combate se conserva
  // el montaje anterior como fallback.
  const panelHost = isBattleHudScreenActive() ? els.invocationControlEffectsHost : null;
  const fallback = state.hudMode === 'overlay' && isBattleHudScreenActive() ? ensureHudOverlayLayer() : els.boardContent;
  const parent = panelHost || fallback;
  if (parent && els.arenaEffectTrackers.parentElement !== parent) parent.appendChild(els.arenaEffectTrackers);
}

function placeHudFloatingMenu(menu, row, col) {
  if (!menu) return;
  const mode = state.hudMode === 'overlay' && isBattleHudScreenActive() ? 'overlay' : 'anchored';
  const pos = cellCenter(row, col);
  menu.dataset.hudRow = String(row);
  menu.dataset.hudCol = String(col);
  menu.classList.add('hud-floating-menu');
  menu.classList.toggle('hud-floating-menu-overlay', mode === 'overlay');
  menu.classList.toggle('hud-floating-menu-anchored', mode !== 'overlay');
  menu.style.left = `${pos.x}%`;
  menu.style.top = `${pos.y}%`;
}

function appendHudFloatingMenu(menu, row, col) {
  const parent = getHudFloatingMenuParent();
  if (!menu || !parent) return;
  syncHudOverlayLayerToBoard();
  placeHudFloatingMenu(menu, row, col);
  parent.appendChild(menu);
}

function refreshHudFloatingMenus() {
  syncHudOverlayLayerToBoard();
  document.querySelectorAll('.hud-floating-menu').forEach(menu => {
    const row = Number(menu.dataset.hudRow);
    const col = Number(menu.dataset.hudCol);
    if (!Number.isFinite(row) || !Number.isFinite(col)) return;
    const parent = getHudFloatingMenuParent();
    if (parent && menu.parentElement !== parent) parent.appendChild(menu);
    placeHudFloatingMenu(menu, row, col);
  });
}


function updateHudModeUi() {
  const mode = state.hudMode === 'overlay' ? 'overlay' : 'anchored';
  document.body.classList.toggle('hud-mode-overlay', mode === 'overlay');
  document.body.classList.toggle('hud-mode-anchored', mode === 'anchored');
  applyHudModeLayout();
  if (els.hudModeAnchoredBtn) {
    const active = mode === 'anchored';
    els.hudModeAnchoredBtn.classList.toggle('active', active);
    els.hudModeAnchoredBtn.setAttribute('aria-pressed', active ? 'true' : 'false');
  }
  if (els.hudModeOverlayBtn) {
    const active = mode === 'overlay';
    els.hudModeOverlayBtn.classList.toggle('active', active);
    els.hudModeOverlayBtn.setAttribute('aria-pressed', active ? 'true' : 'false');
  }
}

function setHudMode(mode) {
  state.hudMode = mode === 'overlay' ? 'overlay' : 'anchored';
  saveHudModePreference();
  updateHudModeUi();
  log(`HUD ${state.hudMode === 'overlay' ? 'overlay' : 'anclado'} seleccionado.`);
}

const GAME_MENU_GAMEPLAY_PAUSE_TOKEN = 'game-menu-offline';
let gameMenuPausedAnimations = [];
let gameMenuSuppressedQuickReactionShield = false;

function isGameMenuOfflinePauseAllowed() {
  return Boolean(document.body.classList.contains('rok-battle-mode') && !isOnlineMatchActive());
}

function pauseBattleVisualAnimationsForGameMenu() {
  gameMenuPausedAnimations = [];
  const stage = document.getElementById('rokAppStage');
  if (!stage?.getAnimations) return;
  try {
    gameMenuPausedAnimations = stage.getAnimations({ subtree: true }).filter(animation => {
      try {
        const target = animation.effect?.target;
        if (target?.closest?.('#gameMenuOverlay')) return false;
        if (animation.playState === 'running' || animation.playState === 'pending') {
          animation.pause();
          return true;
        }
      } catch (_) {}
      return false;
    });
  } catch (_) { gameMenuPausedAnimations = []; }
}

function resumeBattleVisualAnimationsFromGameMenu() {
  const animations = gameMenuPausedAnimations;
  gameMenuPausedAnimations = [];
  animations.forEach(animation => {
    try { if (animation.playState === 'paused') animation.play(); } catch (_) {}
  });
}

function acquireGameMenuOfflinePause() {
  if (!isGameMenuOfflinePauseAllowed()) return false;
  acquireGlobalGameplayPause(GAME_MENU_GAMEPLAY_PAUSE_TOKEN);
  document.body.classList.add('rok-game-menu-paused');
  try { hideBattleInactivityPrompt('game-menu-pause'); } catch (_) {}
  try { markBattleActivity('game-menu-pause', { keepPrompt: true }); } catch (_) {}
  pauseBattleVisualAnimationsForGameMenu();
  return true;
}

function releaseGameMenuOfflinePause() {
  releaseGlobalGameplayPause(GAME_MENU_GAMEPLAY_PAUSE_TOKEN);
  document.body.classList.remove('rok-game-menu-paused');
  resumeBattleVisualAnimationsFromGameMenu();
  try { markBattleActivity('game-menu-resume'); } catch (_) {}
}

function openGameMenu() {
  if (!els.gameMenuOverlay || els.gameMenuOverlay.classList.contains('open')) return;
  const quickShield = document.getElementById('quickReactionInputShield');
  gameMenuSuppressedQuickReactionShield = Boolean(quickShield?.classList?.contains('visible'));
  if (gameMenuSuppressedQuickReactionShield) {
    try { hideQuickReactionInputShield({ force: true }); } catch (_) {}
  }
  acquireGameMenuOfflinePause();
  els.gameMenuOverlay.classList.add('open');
  els.gameMenuOverlay.setAttribute('aria-hidden', 'false');
  if (els.gameMenuBtn) els.gameMenuBtn.setAttribute('aria-expanded', 'true');
  if (els.gameSettingsPanel) els.gameSettingsPanel.setAttribute('aria-hidden', 'true');
  updateHudModeUi();
}

function closeGameMenu() {
  if (!els.gameMenuOverlay) return;
  els.gameMenuOverlay.classList.remove('open');
  els.gameMenuOverlay.setAttribute('aria-hidden', 'true');
  if (els.gameMenuBtn) els.gameMenuBtn.setAttribute('aria-expanded', 'false');
  releaseGameMenuOfflinePause();
  if (gameMenuSuppressedQuickReactionShield) {
    gameMenuSuppressedQuickReactionShield = false;
    try {
      const quick = state.quickReactionWindow || {};
      const stillNeedsShield = Boolean(quick.active || quick.locked || quick.actionSelectionActive || els.quickReactionModal?.classList?.contains('visible'));
      if (stillNeedsShield) showQuickReactionInputShield();
    } catch (_) {}
  }
}

function priorityGameMenuPointerDown(event) {
  // La iniciativa RPS es modal. El botón de menú que permanece debajo no debe
  // capturar el gesto solo porque sus coordenadas coincidan con el pointer.
  if (isRpsInitiativeInteractiveEvent(event)) return;
  if (!document.body.classList.contains('rok-battle-mode') || !els.gameMenuBtn || event.button > 0) return;
  const rect = els.gameMenuBtn.getBoundingClientRect();
  const x = Number(event.clientX);
  const y = Number(event.clientY);
  if (!Number.isFinite(x) || !Number.isFinite(y)) return;
  if (x < rect.left || x > rect.right || y < rect.top || y > rect.bottom) return;
  event.preventDefault();
  event.stopPropagation();
  event.stopImmediatePropagation();
  openGameMenu();
}

function toggleGameSettingsPanel() {
  if (!els.gameSettingsPanel) return;
  const hidden = els.gameSettingsPanel.getAttribute('aria-hidden') !== 'false';
  els.gameSettingsPanel.setAttribute('aria-hidden', hidden ? 'false' : 'true');
  els.gameSettingsPanel.classList.toggle('open', hidden);
}

function returnToMainMenuFromGameMenu() {
  // Salir desde una batalla siempre destruye la sesión actual. No se permite
  // dejar timers, FX, listeners o resoluciones vivas detrás del menú principal.
  const inBattle = document.body.classList.contains('rok-battle-mode') || mainMenuBattleStarted || isOnlineMatchActive();
  if (inBattle) {
    releaseGameMenuOfflinePause();
    exitMatchToMainMenu();
    return;
  }
  closeGameMenu();
  showMainMenu();
}

function loadSemiAutoMovementPreference() {
  try {
    state.semiAutoMovement = localStorage.getItem('rokLite:semiAutoMovement') === '1';
  } catch (error) {
    state.semiAutoMovement = false;
  }
}

function saveSemiAutoMovementPreference() {
  try {
    localStorage.setItem('rokLite:semiAutoMovement', state.semiAutoMovement ? '1' : '0');
  } catch (error) {
    // localStorage puede estar bloqueado; el estado de sesión sigue funcionando.
  }
}

function updateSemiAutoMovementToggle() {
  const btn = els.semiAutoMoveToggle;
  if (!btn) return;
  const active = Boolean(state.semiAutoMovement);
  btn.classList.toggle('active', active);
  btn.setAttribute('aria-pressed', active ? 'true' : 'false');
  btn.textContent = active ? 'Movimiento asistido ON' : 'Movimiento asistido';
  btn.title = active ? 'Movimiento asistido activado' : 'Activar movimiento asistido';
}

function toggleSemiAutoMovement() {
  state.semiAutoMovement = !state.semiAutoMovement;
  saveSemiAutoMovementPreference();
  updateSemiAutoMovementToggle();
  log(`Movimiento asistido ${state.semiAutoMovement ? 'activado' : 'desactivado'}.`);
  renderMoveOptions();
}

function renderDespliegueAnticipadoTargetingGuide() {
  if (!els.boardContent) return;
  const selector = '.despliegue-anticipado-targeting-guide';
  const pending = state.pendingPowerAction;
  const isDespliegue = pending?.kind === 'despliegueAnticipadoTarget' && Number(pending.playerId) === Number(LOCAL_PLAYER_ID);
  const isGloria = pending?.kind === 'gloriaLatenteTarget' && Number(pending.playerId) === Number(LOCAL_PLAYER_ID);
  const isShirahadoriAbility = pending?.kind === 'shirahadoriAbilityTarget' && Number(pending.playerId) === Number(LOCAL_PLAYER_ID);
  const isTacticaDestination = pending?.kind === 'tacticaGuerraDestination' && Number(pending.playerId) === Number(LOCAL_PLAYER_ID);
  const activeTargetFoil = Boolean(isDespliegue || isGloria || isShirahadoriAbility);
  const active = Boolean(activeTargetFoil || isTacticaDestination);

  els.boardContent.classList.toggle('despliegue-targeting-active', activeTargetFoil);
  els.boardContent.querySelectorAll(selector).forEach(node => node.remove());
  if (!active) return;

  if (isDespliegue && !getEligibleDespliegueAnticipadoTargets(Number(pending.playerId)).length) {
    cancelDespliegueAnticipadoTargeting('Despliegue anticipado se canceló porque ya no hay un Caudillo aliado activo.');
    return;
  }
  if (isGloria && !getSelectableGloriaLatenteTargets(Number(pending.playerId)).length) {
    cancelGloriaLatenteTargeting('Gloria latente se canceló porque ya no hay un objetivo aliado válido activo.');
    return;
  }
  if (isShirahadoriAbility && !getEligibleShirahadoriAbilityUsers(Number(pending.playerId)).length) {
    cancelShirahadoriAbilityTargeting('Shirahadori se canceló porque ya no hay un Guerrero o Asesino con Espada compatible de Cuerpo a cuerpo y espacio de habilidad.');
    return;
  }
  if (isTacticaDestination && !getTacticaGuerraCurrentUnit(pending)) {
    cancelTacticaGuerraTargeting('Táctica de guerra se canceló porque la siguiente invocación dejó de estar disponible.');
    return;
  }

  const guide = document.createElement('div');
  guide.className = 'despliegue-anticipado-targeting-guide';
  guide.setAttribute('role', 'status');
  guide.setAttribute('aria-live', 'polite');
  guide.textContent = isDespliegue
    ? 'Selecciona un Caudillo en arena'
    : isGloria
      ? 'Selecciona una invocación Guerrero, Caudillo, Caballero o Héroe'
      : isShirahadoriAbility
        ? 'Selecciona una invocación Guerrero o Asesino'
        : `Coloca el nexo ${Number(pending.currentIndex || 0) + 1} de ${pending.selectedUnitIds.length}`;
  els.boardContent.appendChild(guide);
}

function renderUmbralFugazTargetingGuide() {
  if (!els.boardContent) return;
  const selector = '.umbral-fugaz-targeting-guide';
  els.boardContent.querySelectorAll(selector).forEach(node => node.remove());

  const pending = state.pendingPowerAction;
  const active = ['umbralFugazPortalA', 'umbralFugazPortalB'].includes(String(pending?.kind || ''))
    && Number(pending?.playerId) === Number(LOCAL_PLAYER_ID);
  // v9.58 · El indicador principal de Umbral Fugaz vuelve a la propia Arena.
  // No se renderiza ya la guía superior; solo se activan overlays/casillas.
  els.boardContent.classList.toggle('umbral-fugaz-targeting-active', active);
}

// Etapa 5 · Motor de render batched.
//
// Antes cada mutación llamaba renderAll() de forma síncrona. En una sola
// acción podían acumularse decenas de reconstrucciones completas del DOM,
// y cada una volvía a marcar el snapshot online como dirty. El motor nuevo
// colapsa todas las solicitudes del mismo frame en una sola pasada, mantiene
// una ruta de flush inmediato para transiciones autoritativas y separa el
// aviso de estado online del trabajo visual.
let ROK_RENDER_FRAME_HANDLE = null;
let ROK_RENDER_FALLBACK_TIMER = null;
let ROK_RENDER_RUNNING = false;
let ROK_RENDER_AGAIN = false;
let ROK_RENDER_ONLINE_DIRTY_QUEUED = false;
let ROK_RENDER_DIRTY_TOKEN = 0;
let ROK_RENDER_SUPPRESS_ONLINE_DIRTY_DEPTH = 0;
let ROK_RENDER_GEOMETRY_CACHE = null;
let ROK_ARENA_CELL_CACHE = [];
const ROK_RENDER_PENDING_REASONS = new Set();
const ROK_RENDER_STATS = {
  requested: 0,
  flushed: 0,
  coalesced: 0,
  immediateFlushes: 0,
  lastDurationMs: 0,
  maxDurationMs: 0,
  totalDurationMs: 0,
  lastReasons: [],
};

function queueOnlineDirtyFromRender(reason = 'render-state-change') {
  if (ROK_RENDER_SUPPRESS_ONLINE_DIRTY_DEPTH > 0 || ROK_RENDER_ONLINE_DIRTY_QUEUED) return;
  ROK_RENDER_ONLINE_DIRTY_QUEUED = true;
  const token = ++ROK_RENDER_DIRTY_TOKEN;
  const flushDirty = () => {
    // Un reset de partida invalida microtasks pertenecientes al match anterior.
    if (token !== ROK_RENDER_DIRTY_TOKEN) return;
    ROK_RENDER_ONLINE_DIRTY_QUEUED = false;
    markOnlineStateDirty(reason || 'render-batch');
  };
  if (typeof queueMicrotask === 'function') queueMicrotask(flushDirty);
  else Promise.resolve().then(flushDirty);
}

function captureRenderGeometry() {
  if (!els?.boardContent) return null;
  try {
    const boardRect = els.boardContent.getBoundingClientRect();
    const enemyRect = els.enemyGrid?.getBoundingClientRect?.() || null;
    const allyRect = els.allyGrid?.getBoundingClientRect?.() || null;
    const rootStyle = getComputedStyle(document.documentElement);
    const readCachedRootNumber = (name, fallback) => {
      const parsed = Number.parseFloat(rootStyle.getPropertyValue(name).trim());
      return Number.isFinite(parsed) ? parsed : fallback;
    };
    return {
      boardRect,
      enemyRect,
      allyRect,
      boardWidth: Number(els.boardContent.offsetWidth || 0),
      boardHeight: Number(els.boardContent.offsetHeight || 0),
      enemyCellSize: {
        width: readCachedRootNumber('--enemy-grid-width', 53.7) / 9,
        height: readCachedRootNumber('--enemy-grid-height', 34.5) / 9,
      },
      allyCellSize: {
        width: readCachedRootNumber('--ally-grid-width', 53.7) / 9,
        height: readCachedRootNumber('--ally-grid-height', 39.5) / 9,
      },
    };
  } catch (_) {
    return null;
  }
}

function performRenderAll(reasons = []) {
  if (ROK_RENDER_RUNNING) {
    ROK_RENDER_AGAIN = true;
    return false;
  }
  ROK_RENDER_RUNNING = true;
  const startedAt = (typeof performance !== 'undefined' && performance.now) ? performance.now() : Date.now();
  ROK_RENDER_GEOMETRY_CACHE = captureRenderGeometry();
  try {
    ensureRuntimeStateCollections();
    cleanupInvalidGloriaLatenteLinks();
    safeRenderStep('refreshGuardianAuraState', refreshGuardianAuraState);
    safeRenderStep('refreshSmokeZoneEffects', refreshSmokeZoneEffects);
    safeRenderStep('refreshFarolPortalTeleports', refreshFarolPortalTeleports);
    safeRenderStep('refreshUmbralFugazPortalTeleports', refreshUmbralFugazPortalTeleports);
    safeRenderStep('refreshLongNightEffects', refreshLongNightEffects);
    safeRenderStep('syncSaqueadorNovatoSigiloState', syncSaqueadorNovatoSigiloState);
    safeRenderStep('applyFountainColors', applyFountainColors);
    safeRenderStep('renderPhaseUI', renderPhaseUI);
    safeRenderStep('renderCards', renderCards);
    safeRenderStep('renderResources', renderResources);
    safeRenderStep('renderCastQueue', renderCastQueue);
    safeRenderStep('renderEnemyMiniHud', renderEnemyMiniHud);
    safeRenderStep('renderGridHighlights', renderGridHighlights);
    safeRenderStep('renderSpawnMarkers', renderSpawnMarkers);
    safeRenderStep('renderMoveOptions', renderMoveOptions);
    safeRenderStep('renderTacticaGuerraNexusCursor', renderTacticaGuerraNexusCursor);
    safeRenderStep('renderGuardianAuras', renderGuardianAuras);
    safeRenderStep('renderMinokageAuras', renderMinokageAuras);
    safeRenderStep('renderNaelProvocationAuras', renderNaelProvocationAuras);
    safeRenderStep('renderMaerynDominationAuras', renderMaerynDominationAuras);
    safeRenderStep('renderSmokeZones', renderSmokeZones);
    safeRenderStep('renderCelestialLamps', renderCelestialLamps);
    safeRenderStep('renderLongNightLayer', renderLongNightLayer);
    safeRenderStep('renderArenaEffectTrackers', renderArenaEffectTrackers);
    safeRenderStep('renderDroppedWeaponsLayer', renderDroppedWeaponsLayer);
    safeRenderStep('renderFarolPortals', renderFarolPortals);
    safeRenderStep('renderUmbralFugazPortals', renderUmbralFugazPortals);
    safeRenderStep('renderUnits', renderUnits);
    safeRenderStep('renderMaerynDominationControlFx', renderMaerynDominationControlFx);
    safeRenderStep('renderNaelProvocationControlFx', renderNaelProvocationControlFx);
    safeRenderStep('renderSilenceControlFx', renderSilenceControlFx);
    safeRenderStep('renderUmbralFugazTargetingGuide', renderUmbralFugazTargetingGuide);
    safeRenderStep('renderDespliegueAnticipadoTargetingGuide', renderDespliegueAnticipadoTargetingGuide);
    safeRenderStep('renderParalysisLinksLayer', renderParalysisLinksLayer);
    safeRenderStep('renderGuardianChannelFx', renderGuardianChannelFx);
    safeRenderStep('renderMinokageChannelFxLayer', renderMinokageChannelFxLayer);
    // renderUnits() ya mantiene esta capa; no repetir el mismo trabajo aquí.
    safeRenderStep('renderSelectedUnitCommandPanel', renderSelectedUnitCommandPanel);
    safeRenderStep('renderCombatHud', renderCombatHud);
    safeRenderStep('renderTargetAccessPanel', renderTargetAccessPanel);
    safeRenderStep('renderCasterStats', renderCasterStats);
    safeRenderStep('renderCasterWidePanel', renderCasterWidePanel);
    safeRenderStep('renderOpponentCasterHud', renderOpponentCasterHud);
    safeRenderStep('renderVisualDevShowcase', renderVisualDevShowcase);
    safeRenderStep('updateCardInfoAction', updateCardInfoAction);
    safeRenderStep('refreshQuickReactionWindowVisibility', refreshQuickReactionWindowVisibility);
    safeRenderStep('renderQuickReactionCancelHint', renderQuickReactionCancelHint);
    safeRenderStep('refreshGioshoninSupplyPrompt', refreshGioshoninSupplyPrompt);
    scheduleEligibleGoemonLegendaryInfiltrationCheck();
    return true;
  } finally {
    ROK_RENDER_GEOMETRY_CACHE = null;
    ROK_RENDER_RUNNING = false;
    const endedAt = (typeof performance !== 'undefined' && performance.now) ? performance.now() : Date.now();
    const duration = Math.max(0, endedAt - startedAt);
    ROK_RENDER_STATS.flushed += 1;
    ROK_RENDER_STATS.lastDurationMs = duration;
    ROK_RENDER_STATS.totalDurationMs += duration;
    ROK_RENDER_STATS.maxDurationMs = Math.max(ROK_RENDER_STATS.maxDurationMs, duration);
    ROK_RENDER_STATS.lastReasons = Array.isArray(reasons) ? reasons.slice(-12) : [];
    if (ROK_RENDER_AGAIN) {
      ROK_RENDER_AGAIN = false;
      requestRenderAll('render-reentrant');
    }
    scheduleAutomaticNoActionPhaseCheck('render-settled');
  }
}

function cancelScheduledRenderFrame() {
  if (ROK_RENDER_FRAME_HANDLE != null && typeof window.cancelAnimationFrame === 'function') {
    try { window.cancelAnimationFrame(ROK_RENDER_FRAME_HANDLE); } catch (_) {}
  }
  ROK_RENDER_FRAME_HANDLE = null;
  if (ROK_RENDER_FALLBACK_TIMER != null) {
    try { window.clearTimeout(ROK_RENDER_FALLBACK_TIMER); } catch (_) {}
  }
  ROK_RENDER_FALLBACK_TIMER = null;
}

function resetRenderEngineForMatch() {
  cancelScheduledRenderFrame();
  clearTimeout(noActionPhaseRuntime?.timer);
  if (typeof noActionPhaseRuntime === 'object' && noActionPhaseRuntime) {
    noActionPhaseRuntime.timer = null;
    noActionPhaseRuntime.advancing = false;
    noActionPhaseRuntime.lastReason = '';
    noActionPhaseRuntime.lastPhaseKey = '';
    noActionPhaseRuntime.autoAdvanceCount = 0;
  }
  ROK_RENDER_PENDING_REASONS.clear();
  ROK_RENDER_AGAIN = false;
  ROK_RENDER_ONLINE_DIRTY_QUEUED = false;
  ROK_RENDER_DIRTY_TOKEN += 1;
  ROK_RENDER_GEOMETRY_CACHE = null;
  ROK_ARENA_CELL_CACHE = [];
  try { resetMaerynDominationFxRuntime(); } catch (_) {}
  try { resetNaelProvocationFxRuntime(); } catch (_) {}
  try { resetSilenceFxRuntime(); } catch (_) {}
  try { resetSeyranDistortionFxRuntime(); } catch (_) {}
}

function flushScheduledRender() {
  cancelScheduledRenderFrame();
  const reasons = Array.from(ROK_RENDER_PENDING_REASONS);
  ROK_RENDER_PENDING_REASONS.clear();
  // Una única señal dirty por pasada visual real. Ya no se generan señales
  // redundantes por cada renderAll() que terminó colapsado en este frame.
  queueOnlineDirtyFromRender('render-frame');
  return performRenderAll(reasons);
}

function scheduleRenderFrame() {
  if (ROK_RENDER_FRAME_HANDLE != null || ROK_RENDER_FALLBACK_TIMER != null) return;
  const flush = () => flushScheduledRender();
  if (typeof document !== 'undefined' && document.hidden) {
    ROK_RENDER_FALLBACK_TIMER = window.setTimeout(flush, 16);
    return;
  }
  if (typeof window.requestAnimationFrame === 'function') {
    ROK_RENDER_FRAME_HANDLE = window.requestAnimationFrame(flush);
  } else {
    ROK_RENDER_FALLBACK_TIMER = window.setTimeout(flush, 16);
  }
}

function requestRenderAll(reason = 'state-change') {
  ROK_RENDER_STATS.requested += 1;
  ROK_RENDER_PENDING_REASONS.add(String(reason || 'state-change'));
  if (ROK_RENDER_RUNNING) {
    ROK_RENDER_AGAIN = true;
    ROK_RENDER_STATS.coalesced += 1;
    return false;
  }
  if (ROK_RENDER_FRAME_HANDLE != null || ROK_RENDER_FALLBACK_TIMER != null) {
    ROK_RENDER_STATS.coalesced += 1;
    return false;
  }
  scheduleRenderFrame();
  return true;
}

function flushRenderAllNow(reason = 'forced-render', options = {}) {
  const suppressOnlineDirty = options.markOnlineDirty === false;
  ROK_RENDER_STATS.immediateFlushes += 1;
  ROK_RENDER_PENDING_REASONS.add(String(reason || 'forced-render'));
  if (suppressOnlineDirty) ROK_RENDER_SUPPRESS_ONLINE_DIRTY_DEPTH += 1;
  try {
    return flushScheduledRender();
  } finally {
    if (suppressOnlineDirty) ROK_RENDER_SUPPRESS_ONLINE_DIRTY_DEPTH = Math.max(0, ROK_RENDER_SUPPRESS_ONLINE_DIRTY_DEPTH - 1);
  }
}

// Compatibilidad con todo el código existente: renderAll ya no reconstruye
// el DOM inmediatamente; solicita una sola pasada para el siguiente frame.
function renderAll(reason = 'legacy-render') {
  return requestRenderAll(reason);
}

window.ROK_RENDER_ENGINE = {
  request: requestRenderAll,
  flush: (reason = 'external-flush') => flushRenderAllNow(reason, { markOnlineDirty: false }),
  getStats: () => ({
    ...ROK_RENDER_STATS,
    averageDurationMs: ROK_RENDER_STATS.flushed > 0
      ? ROK_RENDER_STATS.totalDurationMs / ROK_RENDER_STATS.flushed
      : 0,
    pendingReasons: Array.from(ROK_RENDER_PENDING_REASONS),
  }),
  resetForMatch: resetRenderEngineForMatch,
  resetStats: () => {
    Object.assign(ROK_RENDER_STATS, {
      requested: 0,
      flushed: 0,
      coalesced: 0,
      immediateFlushes: 0,
      lastDurationMs: 0,
      maxDurationMs: 0,
      totalDurationMs: 0,
      lastReasons: [],
    });
  },
};

function updateOpponentThinkingNotice() {
  const notice = els.opponentThinkingNotice;
  if (!notice) return;

  // ROK v83 · regreso a comportamiento normal:
  // El aviso solo aparece cuando la IA rival está ejecutando su turno.
  const aiOpponentThinking = Boolean(
    state.aiEnabled
    && state.aiThinking
    && (state.activePlayer !== LOCAL_PLAYER_ID || state.opponentActionResolving)
  );
  const onlineOpponentThinking = Boolean(
    isOnlineMatchActive()
    && state.opponentActionResolving
    && state.opponentActionLockReason === 'remote-priority-action'
  );
  const show = Boolean(isBattleHudScreenActive() && (aiOpponentThinking || onlineOpponentThinking));

  notice.classList.toggle('visible', show);
  notice.classList.remove('thinking-calibration-pinned');
  notice.setAttribute('aria-hidden', show ? 'false' : 'true');
  if (els.opponentThinkingText) els.opponentThinkingText.textContent = 'El rival está pensando…';
}


const manualTurnHudRuntime = {
  lastTransitionKey: '',
  foilTimer: 0,
};

function getManualTurnTransitionKey() {
  return [
    Number(state.turnSerial || 0),
    Number(state.phaseTransitionSerial || 0),
    Number(state.activePlayer || 0),
    Number(state.phaseIndex || 0),
    String(currentPhase()?.id || 'unknown'),
  ].join(':');
}

function clearManualTurnHudFoilTimer() {
  if (manualTurnHudRuntime.foilTimer) {
    window.clearTimeout(manualTurnHudRuntime.foilTimer);
    manualTurnHudRuntime.foilTimer = 0;
  }
}

function triggerManualTurnHudFoil(hud) {
  if (!hud) return false;
  clearManualTurnHudFoilTimer();
  for (const node of [els.casterWidePanel, els.opponentCasterHud]) {
    node?.classList?.remove('caster-turn-transition-foil');
  }
  // Reinicia keyframes de forma determinista sin introducir un segundo render.
  void hud.offsetWidth;
  hud.classList.add('caster-turn-transition-foil');
  manualTurnHudRuntime.foilTimer = window.setTimeout(() => {
    hud.classList.remove('caster-turn-transition-foil');
    manualTurnHudRuntime.foilTimer = 0;
  }, 980);
  return true;
}

function renderManualTurnHudState() {
  const manualActive = Boolean(isBattleHudScreenActive() && !isRealtimePlayStyle());
  const localHud = els.casterWidePanel;
  const rivalHud = els.opponentCasterHud;
  const localIndicator = els.localCasterTurnIndicator;
  const rivalIndicator = els.opponentCasterTurnIndicator;

  if (!manualActive) {
    localHud?.classList?.remove('is-active-turn', 'caster-turn-transition-foil');
    rivalHud?.classList?.remove('is-active-turn', 'caster-turn-transition-foil');
    localIndicator?.setAttribute('aria-hidden', 'true');
    rivalIndicator?.setAttribute('aria-hidden', 'true');
    manualTurnHudRuntime.lastTransitionKey = '';
    clearManualTurnHudFoilTimer();
    return false;
  }

  const localTurn = Number(state.activePlayer) === Number(LOCAL_PLAYER_ID);
  const activeHud = localTurn ? localHud : rivalHud;
  const localColor = getPlayerElementColor(LOCAL_PLAYER_ID);
  const rivalId = getOpponentId(LOCAL_PLAYER_ID);
  const rivalColor = getPlayerElementColor(rivalId);

  if (localHud) {
    localHud.style.setProperty('--caster-turn-color', localColor);
    localHud.classList.toggle('is-active-turn', localTurn);
  }
  if (rivalHud) {
    rivalHud.style.setProperty('--caster-turn-color', rivalColor);
    rivalHud.classList.toggle('is-active-turn', !localTurn);
  }

  if (localIndicator) {
    localIndicator.setAttribute('aria-hidden', localTurn ? 'false' : 'true');
    localIndicator.querySelector('b').textContent = 'TU TURNO';
  }
  if (rivalIndicator) {
    rivalIndicator.setAttribute('aria-hidden', localTurn ? 'true' : 'false');
    rivalIndicator.querySelector('b').textContent = 'TURNO DEL RIVAL';
  }

  const transitionKey = getManualTurnTransitionKey();
  if (transitionKey !== manualTurnHudRuntime.lastTransitionKey) {
    manualTurnHudRuntime.lastTransitionKey = transitionKey;
    triggerManualTurnHudFoil(activeHud);
  }
  return true;
}

function renderPhaseUI() {
  const realtime = isRealtimePlayStyle() && Boolean(state?.realtime?.active);
  document.body.classList.toggle('rok-realtime-playstyle', realtime);
  if (realtime) clearManualTurnPresentationResidueForRealtime('render-phase-ui');
  const waitingPlayer = state.activePlayer === 1 ? 2 : 1;
  document.querySelectorAll('.phase-box').forEach((box) => {
    const phaseId = box.dataset.phaseId;
    box.className = 'phase-box';
    if (phaseId === currentPhase().id) box.classList.add('active', state.activePlayer === 1 ? 'p1' : 'p2');
    if (phaseId === 'wait') box.classList.add('active', waitingPlayer === 1 ? 'p1' : 'p2', 'waiting');
    const undoBtn = box.querySelector('.phase-undo-btn');
    if (undoBtn) {
      const showUndo = Boolean(
        state.activePlayer === LOCAL_PLAYER_ID
        && state.phaseUndo
        && currentPhase().id === 'resolution'
        && !state.resolutionActionTaken
        && state.phaseUndo.playerId === state.activePlayer
      );
      undoBtn.classList.toggle('visible', showUndo);
      undoBtn.disabled = !showUndo;
    }
  });
  if (els.turnBanner) {
    els.turnBanner.textContent = realtime ? '' : `J${state.activePlayer} · ${currentPhase().label} / J${waitingPlayer} espera`;
    els.turnBanner.setAttribute('aria-hidden', realtime ? 'true' : 'false');
  }
  els.boardContent.classList.toggle('player-p1', state.activePlayer === 1);
  els.boardContent.classList.toggle('player-p2', state.activePlayer === 2);
  renderManualTurnHudState();
  if (els.p1Life) els.p1Life.textContent = state.players[1].life;
  if (els.p1ElementCount) els.p1ElementCount.textContent = state.players[1].resources.length;
  document.querySelectorAll('#tabStack > .deck-tab').forEach(btn => {
    const tabIndex = Number(btn.dataset.tab);
    btn.classList.toggle('active', tabIndex === state.activeTab);
  });
  syncQuickReactionPageFocus(getActiveQuickReactionPageTab());
  if (els.nextPhaseBtn) {
    const extractionLocked = currentPhase().id === 'extraction';
    els.nextPhaseBtn.disabled = realtime || extractionLocked || isGlobalGameplayPaused() || isOffTurnCasterRepositionBlockingInput() || state.extractionAnimating || state.aiThinking || state.opponentActionResolving || state.actionExecutionLock || Boolean(getKurokagiBukiStageBlocker(state.activePlayer)) || (state.aiEnabled && state.activePlayer !== LOCAL_PLAYER_ID) || (isOnlineMatchActive() && Number(state.activePlayer) !== Number(LOCAL_PLAYER_ID));
  }
  renderSpellbookPageAvailabilityHints();
  updateOpponentThinkingNotice();
  renderRealtimeStage1Status();
}

function ensureSpellbookPageAvailabilityLayers(btn) {
  let label = btn.querySelector(':scope > .deck-tab-label');
  if (!label) {
    label = document.createElement('span');
    label.className = 'deck-tab-label';
    const textNodes = Array.from(btn.childNodes)
      .filter(node => node.nodeType === Node.TEXT_NODE && node.textContent.trim());
    label.textContent = textNodes.map(node => node.textContent).join('').trim()
      || `Página ${Number(btn.dataset.tab || 0) + 1}`;
    textNodes.forEach(node => node.remove());
    btn.appendChild(label);
  }

  let foil = btn.querySelector(':scope > .spellbook-page-foil');
  if (!foil) {
    foil = document.createElement('span');
    foil.className = 'spellbook-page-foil';
    foil.setAttribute('aria-hidden', 'true');
    btn.insertBefore(foil, label);
  }

  let indicator = btn.querySelector(':scope > .spellbook-page-ready-indicator');
  if (!indicator) {
    indicator = document.createElement('span');
    indicator.className = 'spellbook-page-ready-indicator';
    indicator.setAttribute('aria-hidden', 'true');
    btn.insertBefore(indicator, label);
  }

  return { foil, indicator };
}

function clearSpellbookPageAvailabilityLayers(btn) {
  btn.querySelectorAll(
    ':scope > .spellbook-page-foil, :scope > .spellbook-page-ready-indicator'
  ).forEach(node => node.remove());
}



// =========================================================
// RT-08.17 S5 · Telemetría táctica versionable.
// Este registro NO cambia automáticamente pesos/reglas durante la partida.
// Su propósito es comparar recomendación vs. decisión real del jugador y
// convertir esos patrones en conocimiento explícito en builds posteriores.
// =========================================================
const ROK_TACTICAL_TELEMETRY_FORMAT = 'ROK_TACTICAL_TELEMETRY_V1';
const ROK_TACTICAL_KNOWLEDGE_VERSION = '2026-08-20.s5';
const ROK_TACTICAL_TELEMETRY_STORAGE_KEY = 'rok_tactical_telemetry_current_v1';
const ROK_TACTICAL_TELEMETRY_PREVIOUS_KEY = 'rok_tactical_telemetry_previous_v1';
const ROK_TACTICAL_TELEMETRY_MAX_EVENTS = 2600;

const rokTacticalTelemetryRuntime = {
  session: null,
  previousRecovered: null,
  lastRecommendationKey: '',
  lastSuggestionKey: '',
  lastSupportPlanKeys: new Map(),
};

function getRokTacticalTelemetryStorage() {
  try { return window.localStorage || null; }
  catch (_) { return null; }
}

function saveRokTacticalTelemetry(key, value) {
  const storage = getRokTacticalTelemetryStorage();
  if (!storage) return false;
  try {
    storage.setItem(key, JSON.stringify(value));
    return true;
  } catch (_) {
    return false;
  }
}

function loadRokTacticalTelemetry(key) {
  const storage = getRokTacticalTelemetryStorage();
  if (!storage) return null;
  try {
    const raw = storage.getItem(key);
    return raw ? JSON.parse(raw) : null;
  } catch (_) {
    return null;
  }
}

function beginRokTacticalTelemetrySession(reason = 'battle-detected') {
  const old = loadRokTacticalTelemetry(ROK_TACTICAL_TELEMETRY_STORAGE_KEY);
  if (old?.active && !old?.endedAt) {
    saveRokTacticalTelemetry(ROK_TACTICAL_TELEMETRY_PREVIOUS_KEY, old);
    rokTacticalTelemetryRuntime.previousRecovered = old;
  }

  const now = Date.now();
  rokTacticalTelemetryRuntime.session = {
    format: ROK_TACTICAL_TELEMETRY_FORMAT,
    knowledgeVersion: ROK_TACTICAL_KNOWLEDGE_VERSION,
    build: GAME_VERSION,
    balanceProfile: REALTIME_BALANCE_PROFILE_ID,
    sessionId: `roktel_${now}_${Math.random().toString(16).slice(2)}`,
    matchSerial: Number(state?.matchSerial || 0),
    startedAt: now,
    endedAt: 0,
    active: true,
    startReason: String(reason || ''),
    events: [],
  };
  rokTacticalTelemetryRuntime.lastRecommendationKey = '';
  rokTacticalTelemetryRuntime.lastSuggestionKey = '';
  rokTacticalTelemetryRuntime.lastSupportPlanKeys.clear();
  saveRokTacticalTelemetry(ROK_TACTICAL_TELEMETRY_STORAGE_KEY, rokTacticalTelemetryRuntime.session);
  recordRokTacticalTelemetry('session-start', {
    reason,
    playStyle: state?.playStyle,
    realtime: Boolean(state?.realtime?.active),
  });
  return rokTacticalTelemetryRuntime.session;
}

function ensureRokTacticalTelemetrySession() {
  if (!isBattleHudScreenActive?.()) return rokTacticalTelemetryRuntime.session;
  const serial = Number(state?.matchSerial || 0);
  const session = rokTacticalTelemetryRuntime.session;
  if (state?.gameOver && session) return session;
  if (!session || !session.active || Number(session.matchSerial) !== serial) {
    return beginRokTacticalTelemetrySession('match-serial');
  }
  return session;
}

function getRokTacticalTelemetryContext(extra = null) {
  return {
    at: Date.now(),
    matchSerial: Number(state?.matchSerial || 0),
    playStyle: String(state?.playStyle || ''),
    realtimeElapsedSeconds: Number(state?.realtime?.elapsedSeconds || 0),
    turnSerial: Number(state?.turnSerial || 0),
    phaseId: String(currentPhase?.()?.id || ''),
    activePlayer: Number(state?.activePlayer || 0),
    localPlayerId: Number(LOCAL_PLAYER_ID || 0),
    gameOver: Boolean(state?.gameOver),
    actionExecutionLock: Boolean(state?.actionExecutionLock),
    actionExecutionLockReason: String(state?.actionExecutionLockReason || ''),
    runtimeEpoch: captureBattleRuntimeEpoch(),
    pendingKind: String(state?.pendingPowerAction?.kind || ''),
    pendingCardId: String(
      state?.pendingPowerAction?.cardId
      || state?.pendingCard?.cardId
      || tacticalSpellbookRuntime?.spellAction?.cardId
      || ''
    ),
    spellActionPaused: Boolean(tacticalSpellbookRuntime?.spellAction?.active),
    extra: extra == null ? null : safeDiagnosticClone(extra, extra),
  };
}

function recordRokTacticalTelemetry(type, detail = null) {
  const session = ensureRokTacticalTelemetrySession() || rokTacticalTelemetryRuntime.session;
  if (!session || session.active === false) return null;
  const event = {
    seq: session.events.length + 1,
    t: Date.now(),
    iso: new Date().toISOString(),
    type: String(type || 'event'),
    context: getRokTacticalTelemetryContext(detail),
  };
  session.events.push(event);
  if (session.events.length > ROK_TACTICAL_TELEMETRY_MAX_EVENTS) {
    session.events.splice(0, session.events.length - ROK_TACTICAL_TELEMETRY_MAX_EVENTS);
  }
  saveRokTacticalTelemetry(ROK_TACTICAL_TELEMETRY_STORAGE_KEY, session);
  return event;
}

function finishRokTacticalTelemetrySession(reason = 'match-ended') {
  const session = rokTacticalTelemetryRuntime.session;
  if (!session) return false;
  recordRokTacticalTelemetry('session-end', { reason });
  session.active = false;
  session.endedAt = Date.now();
  session.endReason = String(reason || '');
  saveRokTacticalTelemetry(ROK_TACTICAL_TELEMETRY_STORAGE_KEY, session);
  return true;
}

function formatRokTacticalTelemetryJsonl(record = null) {
  const session = record
    || rokTacticalTelemetryRuntime.session
    || loadRokTacticalTelemetry(ROK_TACTICAL_TELEMETRY_STORAGE_KEY)
    || loadRokTacticalTelemetry(ROK_TACTICAL_TELEMETRY_PREVIOUS_KEY);
  if (!session) return '';

  const header = {
    type: 'header',
    format: session.format || ROK_TACTICAL_TELEMETRY_FORMAT,
    knowledgeVersion: session.knowledgeVersion || ROK_TACTICAL_KNOWLEDGE_VERSION,
    build: session.build || GAME_VERSION,
    balanceProfile: session.balanceProfile || REALTIME_BALANCE_PROFILE_ID,
    sessionId: session.sessionId || '',
    matchSerial: Number(session.matchSerial || 0),
    startedAt: Number(session.startedAt || 0),
    endedAt: Number(session.endedAt || 0),
    endReason: String(session.endReason || ''),
  };
  return [
    JSON.stringify(header),
    ...(session.events || []).map(event => JSON.stringify(event)),
  ].join('\n');
}

async function exportRokTacticalTelemetry(options = {}) {
  let record = null;
  if (options.preferPrevious === true) {
    record = rokTacticalTelemetryRuntime.previousRecovered
      || loadRokTacticalTelemetry(ROK_TACTICAL_TELEMETRY_PREVIOUS_KEY);
  }
  if (!record) {
    record = rokTacticalTelemetryRuntime.session
      || loadRokTacticalTelemetry(ROK_TACTICAL_TELEMETRY_STORAGE_KEY)
      || loadRokTacticalTelemetry(ROK_TACTICAL_TELEMETRY_PREVIOUS_KEY);
  }
  if (!record) return false;

  const text = formatRokTacticalTelemetryJsonl(record);
  if (!text) return false;

  const fileName = `ROK_telemetria_${String(record.build || GAME_VERSION).replace(/[^\w.-]+/g, '_')}_match${Number(record.matchSerial || 0)}_${Date.now()}.jsonl`;
  return await saveRokExportArtifact({
    text,
    suggestedName: fileName,
    mimeType: 'application/x-ndjson;charset=utf-8',
    extension: '.jsonl',
    description: 'Telemetría táctica R.O.K Lite',
  });
}

function captureRokTacticalManualChoice(event) {
  if (!tacticalSpellbookRuntime?.spellAction?.active) return;
  const target = event?.target?.closest?.(
    '.move-option, .target-access-btn, .tactica-guerra-selection-unit, .interceptar-selection-unit, .cell, .unit'
  );
  if (!target || target.closest('#tacticalSuggestedPlayDock')) return;

  const suggestion = tacticalSuggestedPlayRuntime.current;
  recordRokTacticalTelemetry('player-manual-choice', {
    cardId: tacticalSpellbookRuntime.spellAction.cardId,
    pendingKind: state?.pendingPowerAction?.kind || '',
    title: target.getAttribute('title') || '',
    text: String(target.textContent || '').trim().slice(0, 180),
    className: String(target.className || ''),
    dataset: { ...target.dataset },
    suggestedAtMoment: suggestion ? {
      kind: suggestion.kind,
      label: suggestion.label,
      target: suggestion.target || null,
      row: suggestion.row ?? null,
      col: suggestion.col ?? null,
      targetUnitId: suggestion.targetUnitId ?? null,
    } : null,
  });
}

function scanRokTacticalSupportPlans() {
  if (!isBattleHudScreenActive?.()) return;
  for (const playerId of [1, 2]) {
    for (const unit of state.players?.[playerId]?.units || []) {
      const plan = unit?.realtimeSupportPlan;
      if (!plan) continue;
      const key = JSON.stringify(plan);
      const unitKey = `${playerId}:${unit.id}`;
      if (rokTacticalTelemetryRuntime.lastSupportPlanKeys.get(unitKey) === key) continue;
      rokTacticalTelemetryRuntime.lastSupportPlanKeys.set(unitKey, key);
      recordRokTacticalTelemetry('support-plan', {
        playerId,
        unitId: unit.id,
        cardId: unit.cardId,
        plan,
      });
    }
  }
}

function initRokTacticalTelemetry() {
  const previous = loadRokTacticalTelemetry(ROK_TACTICAL_TELEMETRY_STORAGE_KEY);
  if (previous?.active && !previous?.endedAt) {
    saveRokTacticalTelemetry(ROK_TACTICAL_TELEMETRY_PREVIOUS_KEY, previous);
    rokTacticalTelemetryRuntime.previousRecovered = previous;
  }

  document.addEventListener('click', captureRokTacticalManualChoice, true);
  document.addEventListener('keydown', event => {
    if (!(event.ctrlKey && event.shiftKey && String(event.key || '').toLowerCase() === 't')) return;
    event.preventDefault();
    event.stopPropagation();
    exportRokTacticalTelemetry({
      preferPrevious: !isBattleHudScreenActive?.() && Boolean(rokTacticalTelemetryRuntime.previousRecovered),
    });
  }, true);

  setInterval(scanRokTacticalSupportPlans, 1100);
}

window.ROK_TACTICAL_TELEMETRY = {
  record: recordRokTacticalTelemetry,
  exportJsonl: exportRokTacticalTelemetry,
  finish: finishRokTacticalTelemetrySession,
  getCurrent: () => safeDiagnosticClone(rokTacticalTelemetryRuntime.session, null),
  getPrevious: () => safeDiagnosticClone(
    rokTacticalTelemetryRuntime.previousRecovered
      || loadRokTacticalTelemetry(ROK_TACTICAL_TELEMETRY_PREVIOUS_KEY),
    null
  ),
};

// =========================================================
// RT-08.17 S4 · Spellbook táctico asistido.
// El Kaster no juega por el usuario: detecta oportunidades, enfoca la página
// y congela Tiempo real cuando una carta exige una decisión espacial.
// =========================================================
const REALTIME_SPELL_ACTION_PAUSE_SOURCE = 'spell-action';
const REALTIME_SPELL_ACTION_GAMEPLAY_PAUSE_TOKEN = 'realtime-spell-action';
const REALTIME_SPELL_ACTION_PAUSE_LEASE_MS = 60000;
const TACTICAL_SPELLBOOK_RECOMMENDATION_MIN_SCORE = 82;
const TACTICAL_SPELLBOOK_AUTOSWITCH_MIN_SCORE = 108;
const TACTICAL_SPELLBOOK_USER_TAB_GRACE_MS = 2600;

const tacticalSpellbookRuntime = {
  recommendations: [],
  lastComputedAt: 0,
  lastStateKey: '',
  lastAutoFocusKey: '',
  lastAutoFocusAt: 0,
  lastUserTabAt: 0,
  spellAction: {
    active: false,
    cardId: '',
    tab: -1,
    slot: -1,
    startedAt: 0,
    onlineStopSent: false,
  },
};


const tacticalSuggestedPlayRuntime = {
  current: null,
  lastSignature: '',
  lastRenderedSignature: '',
  timer: 0,
  executing: false,
};

function getTacticalSuggestedPlayStateSignature() {
  const pending = state?.pendingPowerAction || {};
  return [
    Number(state?.matchSerial || 0),
    String(tacticalSpellbookRuntime?.spellAction?.cardId || ''),
    String(pending.kind || ''),
    String(pending.unitId || ''),
    String(pending.selectedRivalUnitId || ''),
    JSON.stringify(pending.selectedUnitIds || []),
    Number(pending.currentIndex || 0),
    JSON.stringify(pending.destinations || []),
    Number(state?.realtime?.elapsedSeconds || 0),
  ].join('::');
}

function scoreTacticalDestinationForUnit(playerId, unit, cell) {
  if (!unit || !cell) return -Infinity;
  const modeId = getRealtimeCombatModeProfileForUnit(playerId, unit)?.activeId || 'offensive';

  if (modeId === 'defensive') {
    const safety = getRealtimeDefensiveSafetyMarginAt(
      cell.row,
      cell.col,
      getRealtimeDefensiveThreatEntries(playerId),
    );
    return safety * 100
      + getRealtimeDefensiveSetupPositionScore(playerId, unit, cell.row, cell.col) * 0.8
      + (isRealtimeRowOnOwnSide(playerId, cell.row) ? 24 : -18);
  }

  const intent = getRealtimeCombatIntent(playerId, unit);
  const target = getRealtimeTacticalTargetPosition(intent);
  if (!target) return 0;
  const current = ringDistance(unit.row, unit.col, target.row, target.col);
  const next = ringDistance(cell.row, cell.col, target.row, target.col);
  const progress = current - next;
  if (modeId === 'assassination') return progress * 46;
  if (modeId === 'hunt') return progress * 38;
  if (modeId === 'siege') return progress * 34;
  return progress * 32;
}

function chooseTacticalSuggestedGloriaTarget(playerId) {
  const availability = getGloriaLatenteCastAvailability(playerId);
  if (!availability.available) return null;
  return availability.targets
    .map(unit => {
      const card = CARD_LIBRARY?.[unit.cardId];
      const maxHp = Math.max(1, Number(unit.maxHp ?? unit.baseHp ?? card?.stats?.life ?? unit.hp ?? 1));
      const hp = Math.max(0, Number(unit.hp ?? maxHp));
      const missingRatio = Math.max(0, Math.min(1, (maxHp - hp) / maxHp));
      const pressure = getRealtimeUnitThreatPressure(playerId, unit);
      const pb = getRealtimeCombatPowerForCard(unit.cardId);
      return { unit, score: missingRatio * 110 + pressure * 46 + pb * 0.1 };
    })
    .sort((a, b) => b.score - a.score)[0] || null;
}

function chooseTacticalSuggestedInterceptAlly(playerId) {
  const allies = getInterceptarAlliedCandidates(playerId)
    .filter(ally => getInterceptarRivalCandidates(playerId, ally).length > 0);
  return allies
    .map(ally => {
      const rivals = getInterceptarRivalCandidates(playerId, ally);
      const threat = rivals.reduce((best, rival) => {
        const entry = {
          playerId: getEnemyPlayerId(playerId),
          unit: rival,
          card: CARD_LIBRARY?.[rival.cardId],
        };
        return Math.max(best, getRealtimeLiveThreatScore(playerId, ally, entry));
      }, 0);
      return {
        ally,
        score: threat + getRealtimeCombatPowerForCard(ally.cardId) * 0.05,
      };
    })
    .sort((a, b) => b.score - a.score)[0] || null;
}

function chooseTacticalSuggestedEmboscadaRival(playerId) {
  return getEmboscadaRivalCandidates(playerId)
    .map(unit => ({
      unit,
      score: getRealtimeLiveThreatScore(playerId, null, {
        playerId: getEnemyPlayerId(playerId),
        unit,
        card: CARD_LIBRARY?.[unit.cardId],
      }),
    }))
    .sort((a, b) => b.score - a.score)[0] || null;
}

function chooseTacticalSuggestedEmboscadaAlly(playerId, rival) {
  return getEmboscadaAlliedCandidates(playerId)
    .map(unit => ({
      unit,
      score:
        getRealtimeCombatPowerForCard(unit.cardId) * 0.12
        + getRealtimeOffensiveFeasibilityScore(playerId, unit, {
          playerId: getEnemyPlayerId(playerId),
          unit: rival,
          card: CARD_LIBRARY?.[rival?.cardId],
        })
        - ringDistance(unit.row, unit.col, rival?.row ?? unit.row, rival?.col ?? unit.col) * 3,
    }))
    .sort((a, b) => b.score - a.score)[0] || null;
}


function chooseTacticalSuggestedDespliegueTarget(playerId) {
  return getEligibleDespliegueAnticipadoTargets(playerId)
    .map(unit => ({
      unit,
      score:
        getRealtimeUnitThreatPressure(playerId, unit) * 34
        + getRealtimeAllySetupValue(playerId, unit)
        + getRealtimeCombatPowerForCard(unit.cardId) * 0.12,
    }))
    .sort((a, b) => b.score - a.score)[0] || null;
}

function chooseTacticalSuggestedShirahadoriTarget(playerId) {
  return getEligibleShirahadoriAbilityUsers(playerId)
    .map(unit => {
      const modeId = getRealtimeCombatModeProfileForUnit(playerId, unit)?.activeId || 'offensive';
      let score = getRealtimeCombatPowerForCard(unit.cardId) * 0.12;
      score += getRealtimeUnitThreatPressure(playerId, unit) * 22;
      if (modeId === 'defensive') score += 36;
      if (modeId === 'offensive') score += 28;
      if (modeId === 'assassination') score += 18;
      return { unit, score };
    })
    .sort((a, b) => b.score - a.score)[0] || null;
}

function computeTacticalSuggestedPlay(force = false) {
  if (!isRealtimePlayStyle?.()
      || !state?.realtime?.active
      || !tacticalSpellbookRuntime?.spellAction?.active
      || state.gameOver) {
    tacticalSuggestedPlayRuntime.current = null;
    return null;
  }

  const signature = getTacticalSuggestedPlayStateSignature();
  if (!force
      && signature === tacticalSuggestedPlayRuntime.lastSignature
      && tacticalSuggestedPlayRuntime.current) {
    return tacticalSuggestedPlayRuntime.current;
  }
  tacticalSuggestedPlayRuntime.lastSignature = signature;

  const pending = state.pendingPowerAction || {};
  const playerId = Number(pending.playerId || LOCAL_PLAYER_ID);
  const kind = String(pending.kind || '');
  const cardId = String(
    pending.cardId
    || tacticalSpellbookRuntime.spellAction.cardId
    || state?.pendingCard?.cardId
    || ''
  );
  let suggestion = null;

  if (kind === 'cargaRealLocation') {
    const plan = chooseBestCargaRealBand(playerId);
    suggestion = {
      kind,
      cardId,
      label: `Franja ${plan.bandStartCol + 1}-${plan.bandStartCol + CARGA_REAL_WIDTH_COLUMNS}`,
      reason: `${plan.enemyHits} rival(es) · ${plan.allyHits} aliado(s) · score ${Math.round(plan.score)}`,
      row: playerId === 1 ? 13 : 4,
      col: Math.min(8, plan.bandStartCol + 1),
      score: plan.score,
      target: plan,
    };
  } else if (['kouutenLocation', 'kouutenRecastLocation'].includes(kind)) {
    const plan = chooseBestKouutenCenter(playerId);
    suggestion = {
      kind,
      cardId,
      label: `Centro ${coordLabel(plan.row, plan.col)}`,
      reason: `${plan.enemyHits} impacto(s) centrales · score ${Math.round(plan.score)}`,
      row: plan.row,
      col: plan.col,
      score: plan.score,
      target: plan,
    };
  } else if (kind === 'gurenGanLocation') {
    const plan = chooseBestGurenGanCenter(playerId);
    suggestion = {
      kind,
      cardId,
      label: `Centro ${coordLabel(plan.row, plan.col)}`,
      reason: `impacto ponderado ${Number(plan.enemyHits || 0).toFixed(1)} · score ${Math.round(plan.score)}`,
      row: plan.row,
      col: plan.col,
      score: plan.score,
      target: plan,
    };
  } else if (kind === 'smokeBomb') {
    const unit = getUnitById(playerId, pending.unitId);
    const modeId = unit ? getRealtimeCombatModeProfileForUnit(playerId, unit)?.activeId : 'defensive';
    const plan = unit ? evaluateRealtimeSutokaSmokePlacement(playerId, unit, { modeId }) : null;
    if (plan?.cell) {
      suggestion = {
        kind,
        cardId: unit?.cardId || cardId,
        label: `Humo en ${coordLabel(plan.cell.row, plan.cell.col)}`,
        reason: `${modeId} · cubre ${plan.coveredAllies?.length || 0} aliado(s) · score ${Math.round(plan.score)}`,
        row: plan.cell.row,
        col: plan.cell.col,
        score: plan.score,
        target: plan,
      };
    }
  } else if (['farolEnlazadoCircle', 'farolEnlazadoLamp'].includes(kind)) {
    const unit = getUnitById(playerId, pending.unitId);
    const cells = kind === 'farolEnlazadoCircle'
      ? getFarolCirclePlacementCells(playerId, unit)
      : getFarolLanternDestinationCells(playerId, unit);
    const cell = unit ? chooseRealtimeFarolCell(playerId, unit, cells) : null;
    if (cell) {
      suggestion = {
        kind,
        cardId: unit?.cardId || cardId,
        label: `${kind === 'farolEnlazadoCircle' ? 'Círculo' : 'Lámpara'} ${coordLabel(cell.row, cell.col)}`,
        reason: `posición con mayor valor según ${getRealtimeCombatModeProfileForUnit(playerId, unit)?.active?.label || 'Modo'}`,
        row: cell.row,
        col: cell.col,
        score: Number(cell.tacticalScore || 0),
      };
    }
  } else if (['yasuganaBlindness', 'yasuganaVigilia'].includes(kind)) {
    const unit = getUnitById(playerId, pending.unitId);
    if (unit) {
      const targets = kind === 'yasuganaBlindness'
        ? getYasuganaBlindnessTargets(playerId, unit)
        : getYasuganaVigiliaTargets(playerId, unit);
      const modeId = getRealtimeCombatModeProfileForUnit(playerId, unit)?.activeId || 'offensive';
      const targetUnit = kind === 'yasuganaBlindness'
        ? chooseYasuganaBlindnessTargetForMode(playerId, unit, targets, modeId)
        : (chooseYasuganaVigiliaTargetForAi(playerId, unit, targets)
          || chooseRealtimeBestSupportTarget(playerId, unit, targets, 'yasuganaVigilia', modeId));
      if (targetUnit) {
        suggestion = {
          kind,
          cardId: unit.cardId,
          label: `${kind === 'yasuganaBlindness' ? 'Cegar' : 'Vigilia'} → ${CARD_LIBRARY?.[targetUnit.cardId]?.name || 'Invocación'}`,
          reason: `${modeId} · objetivo de mayor valor contextual`,
          targetUnitId: targetUnit.id,
          targetPlayerId: kind === 'yasuganaBlindness' ? getOpponentId(playerId) : playerId,
          score: kind === 'yasuganaBlindness'
            ? getRealtimeLiveThreatScore(playerId, unit, {
                playerId: getOpponentId(playerId),
                unit: targetUnit,
                card: CARD_LIBRARY?.[targetUnit.cardId],
              })
            : scoreRealtimeSupportTarget(playerId, unit, targetUnit, 'yasuganaVigilia', modeId),
        };
      }
    }
  } else if (kind === 'despliegueAnticipadoTarget') {
    const best = chooseTacticalSuggestedDespliegueTarget(playerId);
    if (best?.unit) {
      suggestion = {
        kind,
        cardId: DESPLIEGUE_ANTICIPADO_CARD_ID,
        label: `Desplegar → ${CARD_LIBRARY?.[best.unit.cardId]?.name || 'Caudillo'}`,
        reason: `Caudillo con mayor presión/setup · score ${Math.round(best.score)}`,
        targetUnitId: best.unit.id,
        targetPlayerId: playerId,
        score: best.score,
      };
    }
  } else if (kind === 'shirahadoriAbilityTarget') {
    const best = chooseTacticalSuggestedShirahadoriTarget(playerId);
    if (best?.unit) {
      suggestion = {
        kind,
        cardId: SHIRAHADORI_ABILITY_CARD_ID,
        label: `Enseñar Shirahadori → ${CARD_LIBRARY?.[best.unit.cardId]?.name || 'Invocación'}`,
        reason: `mejor usuario legal por impacto/amenaza/Modo · score ${Math.round(best.score)}`,
        targetUnitId: best.unit.id,
        targetPlayerId: playerId,
        score: best.score,
      };
    }
  } else if (kind === 'gloriaLatenteTarget') {
    const best = chooseTacticalSuggestedGloriaTarget(playerId);
    if (best?.unit) {
      suggestion = {
        kind,
        cardId: GLORIA_LATENTE_CARD_ID,
        label: `Vincular → ${CARD_LIBRARY?.[best.unit.cardId]?.name || 'Invocación'}`,
        reason: `riesgo/valor de rescate · score ${Math.round(best.score)}`,
        targetUnitId: best.unit.id,
        targetPlayerId: playerId,
        score: best.score,
      };
    }
  } else if (kind === 'interceptarAlliedSelection') {
    const best = chooseTacticalSuggestedInterceptAlly(playerId);
    if (best?.ally) {
      suggestion = {
        kind,
        cardId: INTERCEPTAR_CARD_ID,
        label: `Interceptor → ${CARD_LIBRARY?.[best.ally.cardId]?.name || 'Invocación'}`,
        reason: `mejor pareja disponible contra la invasión · score ${Math.round(best.score)}`,
        targetUnitId: best.ally.id,
        targetPlayerId: playerId,
        score: best.score,
      };
    }
  } else if (kind === 'interceptarRivalSelection') {
    const allied = getUnitById(playerId, pending.selectedAlliedUnitId);
    const best = getInterceptarRivalCandidates(playerId, allied)
      .map(unit => ({
        unit,
        score: getRealtimeLiveThreatScore(playerId, allied, {
          playerId: getEnemyPlayerId(playerId),
          unit,
          card: CARD_LIBRARY?.[unit.cardId],
        }),
      }))
      .sort((a, b) => b.score - a.score)[0] || null;
    if (best?.unit) {
      suggestion = {
        kind,
        cardId: INTERCEPTAR_CARD_ID,
        label: `Interceptar → ${CARD_LIBRARY?.[best.unit.cardId]?.name || 'Rival'}`,
        reason: `invasora de mayor amenaza · score ${Math.round(best.score)}`,
        targetUnitId: best.unit.id,
        targetPlayerId: getEnemyPlayerId(playerId),
        score: best.score,
      };
    }
  } else if (kind === 'tacticaGuerraSelection') {
    const selected = new Set((pending.selectedUnitIds || []).map(String));
    const candidates = getEligibleTacticaGuerraTargets(playerId, {
      quickOnly: pending.quickDefense === true,
      requirePayable: false,
    }).filter(unit => !selected.has(String(unit.id)));
    const best = candidates
      .map(unit => ({
        unit,
        score:
          getRealtimeUnitThreatPressure(playerId, unit) * 46
          + getRealtimeAllySetupValue(playerId, unit)
          + getRealtimeCombatPowerForCard(unit.cardId) * 0.08,
      }))
      .sort((a, b) => b.score - a.score)[0] || null;
    if (best?.unit && !(pending.selectedUnitIds || []).length) {
      suggestion = {
        kind,
        cardId: TACTICA_GUERRA_CARD_ID,
        action: 'toggle-tactica',
        label: `Reposicionar → ${CARD_LIBRARY?.[best.unit.cardId]?.name || 'Invocación'}`,
        reason: `presión + setup + valor de unidad · score ${Math.round(best.score)}`,
        targetUnitId: best.unit.id,
        targetPlayerId: playerId,
        score: best.score,
      };
    } else if ((pending.selectedUnitIds || []).length) {
      suggestion = {
        kind,
        cardId: TACTICA_GUERRA_CARD_ID,
        action: 'confirm-tactica',
        label: `Continuar con ${(pending.selectedUnitIds || []).length} Invocación(es)`,
        reason: 'la selección actual ya forma una jugada táctica completa',
        score: 80,
      };
    }
  } else if (kind === 'tacticaGuerraDestination') {
    const unit = getTacticaGuerraCurrentUnit(pending);
    const cells = getTacticaGuerraDestinationCells(playerId, unit, pending);
    const best = cells
      .map(cell => ({ cell, score: scoreTacticalDestinationForUnit(playerId, unit, cell) }))
      .sort((a, b) => b.score - a.score)[0] || null;
    if (best?.cell) {
      suggestion = {
        kind,
        cardId: TACTICA_GUERRA_CARD_ID,
        label: `${CARD_LIBRARY?.[unit?.cardId]?.name || 'Invocación'} → ${coordLabel(best.cell.row, best.cell.col)}`,
        reason: `mejor posición según ${getRealtimeCombatModeProfileForUnit(playerId, unit)?.active?.label || 'Modo'} · score ${Math.round(best.score)}`,
        row: best.cell.row,
        col: best.cell.col,
        targetUnitId: unit?.id || null,
        score: best.score,
      };
    }
  } else if (kind === 'emboscadaRivalSelection') {
    const best = chooseTacticalSuggestedEmboscadaRival(playerId);
    if (best?.unit) {
      suggestion = {
        kind,
        cardId: EMBOSCADA_CARD_ID,
        action: 'select-emboscada-rival',
        label: `Objetivo → ${CARD_LIBRARY?.[best.unit.cardId]?.name || 'Invasora'}`,
        reason: `invasora de mayor impacto · score ${Math.round(best.score)}`,
        targetUnitId: best.unit.id,
        targetPlayerId: getEnemyPlayerId(playerId),
        score: best.score,
      };
    }
  } else if (kind === 'emboscadaAlliedSelection') {
    const rival = getUnitById(getEnemyPlayerId(playerId), pending.selectedRivalUnitId);
    if ((pending.selectedUnitIds || []).length) {
      suggestion = {
        kind,
        cardId: EMBOSCADA_CARD_ID,
        action: 'confirm-emboscada-allies',
        label: `Colocar ${(pending.selectedUnitIds || []).length} nexo(s)`,
        reason: 'ya existe una fuerza de emboscada válida',
        score: 80,
      };
    } else {
      const best = rival ? chooseTacticalSuggestedEmboscadaAlly(playerId, rival) : null;
      if (best?.unit) {
        suggestion = {
          kind,
          cardId: EMBOSCADA_CARD_ID,
          action: 'toggle-emboscada-ally',
          label: `Emboscador → ${CARD_LIBRARY?.[best.unit.cardId]?.name || 'Invocación'}`,
          reason: `presión viable contra ${CARD_LIBRARY?.[rival?.cardId]?.name || 'la invasora'} · score ${Math.round(best.score)}`,
          targetUnitId: best.unit.id,
          targetPlayerId: playerId,
          score: best.score,
        };
      }
    }
  } else if (kind === 'emboscadaDestination') {
    const unit = getEmboscadaCurrentUnit(pending);
    const rival = getUnitById(getEnemyPlayerId(playerId), pending.selectedRivalUnitId);
    const cells = getEmboscadaDestinationCells(playerId, pending);
    const best = cells
      .map(cell => {
        const modeScore = scoreTacticalDestinationForUnit(playerId, unit, cell);
        const rivalDistance = rival ? ringDistance(cell.row, cell.col, rival.row, rival.col) : 0;
        return { cell, score: modeScore - rivalDistance * 2 };
      })
      .sort((a, b) => b.score - a.score)[0] || null;
    if (best?.cell) {
      suggestion = {
        kind,
        cardId: EMBOSCADA_CARD_ID,
        label: `${CARD_LIBRARY?.[unit?.cardId]?.name || 'Invocación'} → ${coordLabel(best.cell.row, best.cell.col)}`,
        reason: `mejor nexo alrededor de la invasora · score ${Math.round(best.score)}`,
        row: best.cell.row,
        col: best.cell.col,
        targetUnitId: unit?.id || null,
        score: best.score,
      };
    }
  }

  tacticalSuggestedPlayRuntime.current = suggestion;
  if (suggestion) {
    const key = JSON.stringify({
      kind: suggestion.kind,
      cardId: suggestion.cardId,
      action: suggestion.action || '',
      row: suggestion.row ?? null,
      col: suggestion.col ?? null,
      targetUnitId: suggestion.targetUnitId ?? null,
      label: suggestion.label,
    });
    if (key !== rokTacticalTelemetryRuntime.lastSuggestionKey) {
      rokTacticalTelemetryRuntime.lastSuggestionKey = key;
      recordRokTacticalTelemetry('suggested-play', {
        suggestion: safeDiagnosticClone(suggestion, null),
      });
    }
  }
  return suggestion;
}

async function executeTacticalSuggestedPlay(suggestion = tacticalSuggestedPlayRuntime.current) {
  if (!suggestion || tacticalSuggestedPlayRuntime.executing) return false;
  tacticalSuggestedPlayRuntime.executing = true;
  recordRokTacticalTelemetry('suggested-play-accepted', {
    suggestion: safeDiagnosticClone(suggestion, null),
  });

  try {
    const pending = state.pendingPowerAction || {};
    const playerId = Number(pending.playerId || LOCAL_PLAYER_ID);
    const kind = String(suggestion.kind || pending.kind || '');

    if (kind === 'cargaRealLocation') return Boolean(resolveCargaRealLocation(playerId, suggestion.row, suggestion.col));
    if (['kouutenLocation', 'kouutenRecastLocation'].includes(kind)) return Boolean(resolveKouutenLocation(playerId, suggestion.row, suggestion.col));
    if (kind === 'gurenGanLocation') return Boolean(resolveGurenGanLocation(playerId, suggestion.row, suggestion.col));
    if (kind === 'smokeBomb') return Boolean(await resolveSmokeBombAt(suggestion.row, suggestion.col));
    if (kind === 'farolEnlazadoCircle') return Boolean(resolveFarolEnlazadoCircleTarget(playerId, pending.unitId, suggestion.row, suggestion.col));
    if (kind === 'farolEnlazadoLamp') return Boolean(resolveFarolEnlazadoLamp(playerId, pending.unitId, suggestion.row, suggestion.col));

    if (['yasuganaBlindness', 'yasuganaVigilia'].includes(kind)) {
      return Boolean(resolveYasuganaPowerTarget(
        playerId,
        pending.unitId,
        suggestion.targetPlayerId,
        suggestion.targetUnitId,
        kind,
      ));
    }

    if (kind === 'despliegueAnticipadoTarget') {
      return Boolean(resolveDespliegueAnticipadoTarget(playerId, suggestion.targetUnitId));
    }
    if (kind === 'shirahadoriAbilityTarget') {
      return Boolean(resolveShirahadoriAbilityTarget(playerId, suggestion.targetUnitId));
    }
    if (kind === 'gloriaLatenteTarget') {
      return Boolean(resolveGloriaLatenteTarget(playerId, suggestion.targetUnitId));
    }

    if (kind === 'interceptarAlliedSelection') {
      return Boolean(selectInterceptarAlliedUnit(suggestion.targetUnitId));
    }
    if (kind === 'interceptarRivalSelection') {
      return Boolean(await selectInterceptarRivalUnit(suggestion.targetUnitId));
    }

    if (kind === 'tacticaGuerraSelection') {
      if (suggestion.action === 'confirm-tactica') return Boolean(confirmTacticaGuerraTargetSelection());
      return Boolean(toggleTacticaGuerraSelectedUnit(suggestion.targetUnitId));
    }
    if (kind === 'tacticaGuerraDestination') {
      return Boolean(resolveTacticaGuerraDestination(playerId, suggestion.row, suggestion.col));
    }

    if (kind === 'emboscadaRivalSelection') {
      pending.selectedRivalUnitId = suggestion.targetUnitId;
      renderEmboscadaRivalSelectionModal();
      return Boolean(confirmEmboscadaRivalSelection());
    }
    if (kind === 'emboscadaAlliedSelection') {
      if (suggestion.action === 'confirm-emboscada-allies') return Boolean(beginEmboscadaDestinationSelection());
      return Boolean(toggleEmboscadaAlliedUnit(suggestion.targetUnitId));
    }
    if (kind === 'emboscadaDestination') {
      return Boolean(await resolveEmboscadaDestination(playerId, suggestion.row, suggestion.col));
    }

    return false;
  } catch (error) {
    reportDebugError('execute-tactical-suggested-play', error);
    recordRokTacticalTelemetry('suggested-play-error', {
      message: error?.message || String(error || ''),
      stack: error?.stack || '',
      suggestion: safeDiagnosticClone(suggestion, null),
    });
    return false;
  } finally {
    tacticalSuggestedPlayRuntime.executing = false;
    setTimeout(() => syncTacticalSuggestedPlayDock(true), 40);
  }
}

function removeTacticalSuggestedPlayDock() {
  document.getElementById('tacticalSuggestedPlayDock')?.remove();
  document.querySelectorAll('.rok-tactical-suggested-target').forEach(node =>
    node.classList.remove('rok-tactical-suggested-target'));
}

function highlightTacticalSuggestedPlayTarget(suggestion) {
  document.querySelectorAll('.rok-tactical-suggested-target').forEach(node =>
    node.classList.remove('rok-tactical-suggested-target'));
  if (!suggestion) return;

  if (suggestion.row != null && suggestion.col != null) {
    const target = Array.from(document.querySelectorAll('#moveOptionsLayer .move-option'))
      .find(node => {
        const title = String(node.title || '');
        return title.includes(coordLabel(suggestion.row, suggestion.col));
      });
    target?.classList.add('rok-tactical-suggested-target');
  }

  if (suggestion.targetUnitId != null) {
    document.querySelectorAll('.unit').forEach(node => {
      const unitId = node.dataset?.unitId || node.dataset?.id || '';
      if (String(unitId) === String(suggestion.targetUnitId)) {
        node.classList.add('rok-tactical-suggested-target');
      }
    });
  }
}

function renderTacticalSuggestedPlayDock(suggestion) {
  removeTacticalSuggestedPlayDock();
  if (!suggestion || !tacticalSpellbookRuntime?.spellAction?.active) return;

  const dock = document.createElement('aside');
  dock.id = 'tacticalSuggestedPlayDock';
  dock.className = 'tactical-suggested-play-dock';
  dock.setAttribute('aria-label', 'Jugada sugerida por el Kaster');
  dock.innerHTML = `
    <div class="tactical-suggested-play-copy">
      <span>JUGADA SUGERIDA</span>
      <strong>${escapeHtml(suggestion.label || 'Opción táctica')}</strong>
      <small>${escapeHtml(suggestion.reason || '')}</small>
    </div>
    <button type="button" class="tactical-suggested-play-accept">USAR SUGERENCIA</button>`;
  dock.querySelector('.tactical-suggested-play-accept')?.addEventListener('click', event => {
    event.preventDefault();
    event.stopPropagation();
    void executeTacticalSuggestedPlay(suggestion);
  });

  appendRokUiNode(dock);
  highlightTacticalSuggestedPlayTarget(suggestion);
}

function syncTacticalSuggestedPlayDock(force = false) {
  if (!isRealtimePlayStyle?.()
      || !state?.realtime?.active
      || !tacticalSpellbookRuntime?.spellAction?.active
      || state.gameOver) {
    tacticalSuggestedPlayRuntime.current = null;
    removeTacticalSuggestedPlayDock();
    return false;
  }

  const suggestion = computeTacticalSuggestedPlay(force);
  const signature = suggestion
    ? JSON.stringify([
        suggestion.kind,
        suggestion.label,
        suggestion.row ?? null,
        suggestion.col ?? null,
        suggestion.targetUnitId ?? null,
      ])
    : '';

  if (!force && signature === tacticalSuggestedPlayRuntime.lastRenderedSignature) {
    highlightTacticalSuggestedPlayTarget(suggestion);
    return Boolean(suggestion);
  }
  tacticalSuggestedPlayRuntime.lastRenderedSignature = signature;
  renderTacticalSuggestedPlayDock(suggestion);
  return Boolean(suggestion);
}

function initTacticalSuggestedPlayRuntime() {
  clearInterval(tacticalSuggestedPlayRuntime.timer);
  tacticalSuggestedPlayRuntime.timer = setInterval(() => {
    try { syncTacticalSuggestedPlayDock(); }
    catch (error) { reportDebugError('suggested-play-sync', error); }
  }, 280);
}

function markTacticalSpellbookUserTabInteraction() {
  tacticalSpellbookRuntime.lastUserTabAt = Date.now();
}

function getTacticalSpellbookCardText(card) {
  return [
    card?.name,
    card?.summary,
    card?.description,
    card?.power,
    card?.spellRules?.description,
    card?.spellRules?.effect?.description,
    ...(card?.tags || []),
    ...(card?.classification?.functionalCategories || []),
  ].filter(Boolean).join(' ').toLowerCase();
}

function getTacticalSpellbookDecisionProfile(card) {
  if (!card) return { tactical: false, spatial: false, tags: [] };
  const id = String(card.id || '');
  const typeId = getCardTypeId(card);
  const text = getTacticalSpellbookCardText(card);
  const knownSpatial = new Set([
    CARGA_REAL_CARD_ID,
    KOUUTEN_CARD_ID,
    GUREN_GAN_CARD_ID,
    DESPLIEGUE_ANTICIPADO_CARD_ID,
    GLORIA_LATENTE_CARD_ID,
    TACTICA_GUERRA_CARD_ID,
    INTERCEPTAR_CARD_ID,
    EMBOSCADA_CARD_ID,
    SHIRAHADORI_ABILITY_CARD_ID,
  ]);
  const spatialByText = /(reposicion|reubic|traslad|mover|movim|casilla|zona|área|area|objetivo|selecciona|destino|dirección|direccion|alrededor|frontal)/i.test(text);
  const supportByText = /(curar|cura|proteger|protege|rescate|retirar|retirada|salvar|oculto|humo|vigilia|restaur)/i.test(text);
  const controlByText = /(aturd|atadur|ceguera|paral|empuj|intercept|embosc|control)/i.test(text);
  const tactical = knownSpatial.has(id) || (typeId === 'spell' && (spatialByText || supportByText || controlByText));
  return {
    tactical,
    spatial: knownSpatial.has(id) || spatialByText,
    tags: [
      spatialByText ? 'spatial' : '',
      supportByText ? 'support' : '',
      controlByText ? 'control' : '',
    ].filter(Boolean),
  };
}

function getTacticalSpellbookThreatenedAllies(playerId) {
  try { return getRealtimeThreatenedAlliedUnits(playerId); }
  catch (_) { return []; }
}

function scoreTacticalSpellbookCard(playerId, tabIndex, slotIndex, card) {
  const availability = getBattleSpellbookCastingAvailability(playerId, card, tabIndex, slotIndex);
  if (!availability.available) return null;

  const profile = getTacticalSpellbookDecisionProfile(card);
  const typeId = getCardTypeId(card);
  const threatenedAllies = getTacticalSpellbookThreatenedAllies(playerId);
  const enemyUnits = getRealtimeEnemyInvocationCandidates(playerId);
  const activeAllies = (state.players?.[playerId]?.units || [])
    .filter(unit => unit && unit.status !== 'restoring' && Number(unit.hp ?? 0) > 0);

  let score = typeId === 'spell' ? 42 : typeId === 'ability' ? 34 : 12;
  const reasons = [];

  if (profile.tactical) {
    score += 26;
    reasons.push('carta táctica');
  }
  if (profile.spatial) {
    score += 18;
    reasons.push('decisión espacial');
  }

  if (card.id === INTERCEPTAR_CARD_ID) {
    score += 92;
    reasons.push('invasor interceptable');
  } else if (card.id === EMBOSCADA_CARD_ID) {
    score += 88;
    reasons.push('ventana de Emboscada');
  } else if (card.id === TACTICA_GUERRA_CARD_ID) {
    score += 72 + threatenedAllies.length * 14;
    reasons.push('reposicionamiento disponible');
  } else if (card.id === GLORIA_LATENTE_CARD_ID) {
    const low = activeAllies.filter(unit => {
      const maxHp = Math.max(1, Number(unit.maxHp ?? unit.baseHp ?? CARD_LIBRARY?.[unit.cardId]?.stats?.life ?? unit.hp ?? 1));
      return Number(unit.hp ?? maxHp) / maxHp <= 0.45;
    }).length;
    score += 58 + low * 38;
    reasons.push(low ? `${low} aliado(s) en riesgo` : 'restauración táctica');
  } else if (card.id === DESPLIEGUE_ANTICIPADO_CARD_ID) {
    score += 48;
    reasons.push('Caudillo compatible');
  } else if (card.id === CARGA_REAL_CARD_ID) {
    const plan = chooseBestCargaRealBand(playerId);
    const hits = Number(plan?.targets?.length ?? plan?.enemyHits ?? 0);
    score += hits * 34;
    if (hits) reasons.push(`${hits} objetivo(s) en línea`);
  } else if (card.id === KOUUTEN_CARD_ID) {
    const plan = chooseBestKouutenCenter(playerId);
    const hits = Number(plan?.enemyHits ?? 0);
    score += hits * 31;
    if (hits) reasons.push(`${hits} impacto(s) previstos`);
  } else if (card.id === GUREN_GAN_CARD_ID) {
    const plan = chooseBestGurenGanCenter(playerId);
    const hits = Number(plan?.enemyHits ?? 0);
    score += hits * 30;
    if (hits) reasons.push(`${hits} impacto(s) previstos`);
  }

  if (profile.tags.includes('support') && threatenedAllies.length) {
    score += Math.min(90, threatenedAllies.length * 36);
    reasons.push(`${threatenedAllies.length} aliado(s) amenazados`);
  }
  if (profile.tags.includes('control') && enemyUnits.length) {
    const strongest = enemyUnits
      .slice()
      .sort((a, b) => getRealtimeLiveThreatScore(playerId, null, b) - getRealtimeLiveThreatScore(playerId, null, a))[0];
    if (strongest) {
      score += 28;
      reasons.push('amenaza rival controlable');
    }
  }

  // Evita llenar la interfaz de recomendaciones de invocaciones normales.
  if (typeId === 'invocation' && !profile.tactical) score -= 50;

  return {
    cardId: card.id,
    cardName: card.name || card.id,
    tab: Number(tabIndex),
    slot: Number(slotIndex),
    score,
    reasons,
    profile,
  };
}

function getTacticalSpellbookStateKey() {
  const own = state.players?.[LOCAL_PLAYER_ID];
  const hand = (own?.handTabs || []).map(tab => (tab || []).join(',')).join('|');
  return [
    Number(state?.matchSerial || 0),
    Number(state?.realtime?.elapsedSeconds || 0),
    Number(state?.turnSerial || 0),
    Number(state?.phaseTransitionSerial || 0),
    Number(state?.activePlayer || 0),
    String(currentPhase?.()?.id || ''),
    hand,
    Number(own?.resources?.length || 0),
    Number(own?.units?.length || 0),
    Number(state.players?.[getEnemyPlayerId(LOCAL_PLAYER_ID)]?.units?.length || 0),
  ].join('::');
}

function computeTacticalSpellbookRecommendations(force = false) {
  if (!isBattleHudScreenActive?.() || !isRealtimePlayStyle?.() || !state?.realtime?.active || state.gameOver) {
    tacticalSpellbookRuntime.recommendations = [];
    return [];
  }
  if (isRealtimeThoughtPauseActive?.()) {
    tacticalSpellbookRuntime.recommendations = [];
    return [];
  }

  const key = getTacticalSpellbookStateKey();
  const now = Date.now();
  if (!force
      && key === tacticalSpellbookRuntime.lastStateKey
      && now - tacticalSpellbookRuntime.lastComputedAt < 450) {
    return tacticalSpellbookRuntime.recommendations;
  }
  tacticalSpellbookRuntime.lastStateKey = key;
  tacticalSpellbookRuntime.lastComputedAt = now;

  const player = state.players?.[LOCAL_PLAYER_ID];
  const candidates = [];
  (player?.handTabs || []).forEach((tab, tabIndex) => {
    (tab || []).forEach((cardId, slotIndex) => {
      const card = CARD_LIBRARY?.[cardId];
      if (!card) return;
      const candidate = scoreTacticalSpellbookCard(LOCAL_PLAYER_ID, tabIndex, slotIndex, card);
      if (candidate && candidate.score >= TACTICAL_SPELLBOOK_RECOMMENDATION_MIN_SCORE) candidates.push(candidate);
    });
  });

  candidates.sort((a, b) => b.score - a.score);
  tacticalSpellbookRuntime.recommendations = candidates.slice(0, 2).map((entry, index) => ({
    ...entry,
    rank: index + 1,
  }));

  const primary = tacticalSpellbookRuntime.recommendations[0] || null;
  const recommendationKey = primary
    ? `${primary.cardId}:${primary.tab}:${primary.slot}:${Math.round(primary.score)}`
    : 'none';
  if (recommendationKey !== rokTacticalTelemetryRuntime.lastRecommendationKey) {
    rokTacticalTelemetryRuntime.lastRecommendationKey = recommendationKey;
    recordRokTacticalTelemetry('spellbook-recommendation', {
      primary: primary ? safeDiagnosticClone(primary, null) : null,
      alternative: tacticalSpellbookRuntime.recommendations[1]
        ? safeDiagnosticClone(tacticalSpellbookRuntime.recommendations[1], null)
        : null,
    });
  }
  return tacticalSpellbookRuntime.recommendations;
}

function getTacticalSpellbookRecommendation(tabIndex, slotIndex) {
  return computeTacticalSpellbookRecommendations()
    .find(entry => Number(entry.tab) === Number(tabIndex) && Number(entry.slot) === Number(slotIndex)) || null;
}

function canAutoFocusTacticalSpellbookRecommendation() {
  if (!isRealtimePlayStyle?.() || !state?.realtime?.active || state.gameOver) return false;
  if (Date.now() - tacticalSpellbookRuntime.lastUserTabAt < TACTICAL_SPELLBOOK_USER_TAB_GRACE_MS) return false;
  if (state.pendingCard || state.pendingPlacement || state.pendingPowerAction || state.randomCostPayment) return false;
  if (state.actionExecutionLock || state.opponentActionResolving || state.castTravelResolving) return false;
  if (spellbookCardDragState?.active) return false;
  if (isRealtimeThoughtPauseActive?.()) return false;
  if (tacticalSpellbookRuntime.spellAction.active) return false;
  if (els.cardInfoOverlay?.classList?.contains('open')) return false;
  return true;
}

function maybeAutoFocusTacticalSpellbookRecommendation() {
  // RT-08.18 · El Kaster NO vuelve a cambiar la página que el usuario está
  // leyendo/preparando. Las oportunidades temporales viven en el rail lateral.
  return false;
}

function hasRealtimeSpellActionInteraction() {
  if (!isRealtimePlayStyle?.() || !state?.realtime?.active) return false;
  if (state.pendingCard || state.pendingPlacement || state.pendingPowerAction || state.randomCostPayment) return true;
  if (state.kiaraNoReactionCurrent && !state.kiaraNoReactionCurrent.resolved) return true;
  if (getRealtimeProgressiveRecastDecision?.()) return true;
  if (state.hattoriAbilitySelectionActive || state.hattoriReactionPromptActive || state.tokugawaAbilitySelectionActive) return true;
  if (state.quickReactionWindow?.actionSelectionActive) return true;
  if (document.querySelector('.move-option, .target-access-btn, #randomCostOverlay.open, #gioshoninSupplyModal.visible')) return true;
  return false;
}


function acquireRealtimeSpellActionHardPause(meta = {}) {
  if (!isRealtimePlayStyle?.() || !state?.realtime?.active) return false;

  acquireGlobalGameplayPause(REALTIME_SPELL_ACTION_GAMEPLAY_PAUSE_TOKEN);

  // tempoPause solo puede tener un owner a la vez. Si otra resolución ya lo
  // posee, NO la pisamos; el token global mantiene la simulación congelada y
  // syncRealtimeSpellActionPauseState() toma Tempo en cuanto el owner anterior
  // termina.
  if (!state.realtime.tempoPause?.active) {
    setRealtimeTempoPause(true, 'DECISIÓN DE CARTA', REALTIME_SPELL_ACTION_PAUSE_SOURCE);
  }

  document.body?.classList?.add('rok-realtime-spell-action-paused');
  try {
    recordRokMatchDiagnostic('spell-action-hard-pause', 'ACQUIRE', {
      cardId: String(meta.cardId || tacticalSpellbookRuntime?.spellAction?.cardId || ''),
      playerId: Number(meta.playerId || LOCAL_PLAYER_ID),
      tempoPauseSource: String(state?.realtime?.tempoPause?.source || ''),
      globalTokens: Object.keys(getGlobalGameplayPauseStore()?.tokens || {}),
    }, { persistNow: true });
  } catch (_) {}
  return true;
}

function releaseRealtimeSpellActionHardPause(reason = 'completed') {
  releaseGlobalGameplayPause(REALTIME_SPELL_ACTION_GAMEPLAY_PAUSE_TOKEN);

  if (state?.realtime?.tempoPause?.active
      && state.realtime.tempoPause.source === REALTIME_SPELL_ACTION_PAUSE_SOURCE) {
    setRealtimeTempoPause(false, '', REALTIME_SPELL_ACTION_PAUSE_SOURCE);
  }

  document.body?.classList?.remove('rok-realtime-spell-action-paused');
  try {
    recordRokMatchDiagnostic('spell-action-hard-pause', 'RELEASE', {
      reason,
      tempoPauseSource: String(state?.realtime?.tempoPause?.source || ''),
      globalTokens: Object.keys(getGlobalGameplayPauseStore()?.tokens || {}),
    });
  } catch (_) {}
  return true;
}

function setRealtimeSpellActionPauseLocal(active, meta = {}) {
  if (!isRealtimePlayStyle?.() || !state?.realtime?.active) return false;
  const runtime = tacticalSpellbookRuntime.spellAction;
  const mirrorRuntime = meta.mirrorRuntime !== false;
  const previousPause = state.realtime.spellActionPause || {};

  if (active) {
    const startedAt = Date.now();
    if (mirrorRuntime) {
      runtime.active = true;
      runtime.cardId = String(meta.cardId || runtime.cardId || '');
      runtime.tab = Number(meta.tab ?? runtime.tab ?? -1);
      runtime.slot = Number(meta.slot ?? runtime.slot ?? -1);
      runtime.startedAt = startedAt;
      runtime.onlineStopSent = false;
    }
    if (!state.realtime.spellActionPause || typeof state.realtime.spellActionPause !== 'object') {
      state.realtime.spellActionPause = {};
    }
    state.realtime.spellActionPause = {
      active: true,
      playerId: Number(meta.playerId || LOCAL_PLAYER_ID),
      cardId: String(meta.cardId || runtime.cardId || ''),
      tab: Number(meta.tab ?? runtime.tab ?? -1),
      slot: Number(meta.slot ?? runtime.slot ?? -1),
      startedAt,
      expiresAt: startedAt + REALTIME_SPELL_ACTION_PAUSE_LEASE_MS,
    };
    acquireRealtimeSpellActionHardPause({ ...meta, cardId: state.realtime.spellActionPause.cardId });
    try {
      recordRokMatchDiagnostic('spell-action-pause', 'START', {
        playerId: Number(meta.playerId || LOCAL_PLAYER_ID),
        cardId: state.realtime.spellActionPause.cardId,
        tab: state.realtime.spellActionPause.tab,
        slot: state.realtime.spellActionPause.slot,
      }, { persistNow: true });
    } catch (_) {}
    return true;
  }

  if (mirrorRuntime) {
    runtime.active = false;
    runtime.cardId = '';
    runtime.tab = -1;
    runtime.slot = -1;
    runtime.startedAt = 0;
    runtime.onlineStopSent = false;
  }
  if (state.realtime.spellActionPause && typeof state.realtime.spellActionPause === 'object') {
    state.realtime.spellActionPause.active = false;
  }
  releaseRealtimeSpellActionHardPause(meta.reason || 'completed');
  try { recordRokMatchDiagnostic('spell-action-pause', 'STOP', { reason: meta.reason || 'completed' }); } catch (_) {}
  try {
    recordRokTacticalTelemetry('spell-action-finished', {
      reason: meta.reason || 'completed',
      cardId: String(runtime.cardId || previousPause.cardId || ''),
    });
  } catch (_) {}
  tacticalSuggestedPlayRuntime.current = null;
  removeTacticalSuggestedPlayDock();
  return true;
}

async function requestRealtimeSpellActionPause(active, meta = {}) {
  if (!isRealtimePlayStyle?.() || !state?.realtime?.active) return false;
  const playerId = Number(meta.playerId || LOCAL_PLAYER_ID);

  if (!isOnlineMatchActive?.() || isRealtimeOnlineAuthority?.()) {
    return setRealtimeSpellActionPauseLocal(active, { ...meta, playerId });
  }

  // El Invitado solicita al Host la pausa autoritativa. El comando se envía
  // antes de abrir la selección para que el snapshot deje de avanzar.
  try {
    const ok = await window.ROK_ONLINE_PVP?.sendRealtimeCommand?.(
      'spell-action-pause',
      {
        action: active ? 'start' : 'stop',
        cardId: String(meta.cardId || tacticalSpellbookRuntime.spellAction.cardId || ''),
        tab: Number(meta.tab ?? tacticalSpellbookRuntime.spellAction.tab ?? -1),
        slot: Number(meta.slot ?? tacticalSpellbookRuntime.spellAction.slot ?? -1),
      }
    );
    if (active && ok !== false) {
      // El Host ya aceptó. Reflejamos la misma pausa en el cliente invitado
      // inmediatamente; no esperamos al siguiente snapshot para frenar la UI.
      setRealtimeSpellActionPauseLocal(true, {
        ...meta,
        playerId,
        cardId: String(meta.cardId || ''),
        tab: Number(meta.tab ?? -1),
        slot: Number(meta.slot ?? -1),
      });
      tacticalSpellbookRuntime.spellAction.onlineStopSent = false;
    } else if (!active && ok !== false) {
      setRealtimeSpellActionPauseLocal(false, { reason: meta.reason || 'remote-finished' });
      tacticalSpellbookRuntime.spellAction.onlineStopSent = true;
    } else if (active && ok === false) {
      releaseRealtimeSpellActionHardPause('online-start-rejected');
    }
    return ok !== false;
  } catch (error) {
    reportDebugError('spell-action-pause-command', error);
    return false;
  }
}

function syncRealtimeSpellActionPauseState() {
  if (!isRealtimePlayStyle?.() || !state?.realtime?.active) return false;

  const runtime = tacticalSpellbookRuntime.spellAction;
  const remotePause = state?.realtime?.spellActionPause || {};
  const localOwnsRemote = Boolean(
    remotePause.active
    && Number(remotePause.playerId || 0) === Number(LOCAL_PLAYER_ID)
  );
  const remoteOwnsPause = Boolean(
    remotePause.active
    && Number(remotePause.playerId || 0)
    && Number(remotePause.playerId || 0) !== Number(LOCAL_PLAYER_ID)
  );

  // La selección remota no posee pendingCard/pendingPowerAction en este DOM.
  // El Host debe mantener la pausa por el lease remoto, no buscar una interfaz
  // local inexistente y liberarla a los ~250 ms.
  if (remoteOwnsPause) {
    if (runtime.active) {
      runtime.active = false;
      runtime.cardId = '';
      runtime.tab = -1;
      runtime.slot = -1;
      runtime.startedAt = 0;
      runtime.onlineStopSent = false;
    }
    const expiresAt = Math.max(0, Number(remotePause.expiresAt || 0));
    if (isRealtimeOnlineAuthority?.() && expiresAt && Date.now() >= expiresAt) {
      setRealtimeSpellActionPauseLocal(false, { reason: 'remote-lease-timeout', mirrorRuntime: false });
      try { markOnlineStateDirty('rt-spell-action-remote-timeout'); } catch (_) {}
      return false;
    }
    acquireGlobalGameplayPause(REALTIME_SPELL_ACTION_GAMEPLAY_PAUSE_TOKEN);
    document.body?.classList?.add('rok-realtime-spell-action-paused');
    if (!state?.realtime?.tempoPause?.active) {
      setRealtimeTempoPause(true, 'RIVAL DECIDIENDO CARTA', REALTIME_SPELL_ACTION_PAUSE_SOURCE);
    }
    return true;
  }

  if (!runtime.active && localOwnsRemote) {
    runtime.active = true;
    runtime.cardId = String(remotePause.cardId || '');
    runtime.tab = Number(remotePause.tab ?? -1);
    runtime.slot = Number(remotePause.slot ?? -1);
    runtime.startedAt = Number(remotePause.startedAt || Date.now());
    runtime.onlineStopSent = false;
  }

  if (!runtime.active) {
    releaseGlobalGameplayPause(REALTIME_SPELL_ACTION_GAMEPLAY_PAUSE_TOKEN);
    document.body?.classList?.remove('rok-realtime-spell-action-paused');
    return false;
  }

  // v9.36 · Autocuración del deadlock observado en v9.35: si el owner de la
  // pausa era ¡No! pero su reacción de 4 s ya terminó, no puede conservar el
  // token realtime-spell-action ni un tempoPause huérfano.
  if (String(runtime.cardId || '') === String(KIARA_NO_CARD_ID)
      && !(state.kiaraNoReactionCurrent && !state.kiaraNoReactionCurrent.resolved)) {
    setRealtimeSpellActionPauseLocal(false, { reason: 'kiara-no-stale-owner' });
    try { syncLocalQuickReactionGameplayPause(); } catch (_) {}
    return false;
  }

  acquireGlobalGameplayPause(REALTIME_SPELL_ACTION_GAMEPLAY_PAUSE_TOKEN);
  document.body?.classList?.add('rok-realtime-spell-action-paused');
  if (!state?.realtime?.tempoPause?.active) {
    setRealtimeTempoPause(true, 'DECISIÓN DE CARTA', REALTIME_SPELL_ACTION_PAUSE_SOURCE);
  }

  if (hasRealtimeSpellActionInteraction()) return true;

  // Se da un pequeño margen al startKastFromInfo para instalar su targeting.
  if (Date.now() - Number(runtime.startedAt || 0) < 220) return true;

  if (isOnlineMatchActive?.() && !isRealtimeOnlineAuthority?.()) {
    if (!runtime.onlineStopSent) {
      runtime.onlineStopSent = true;
      void requestRealtimeSpellActionPause(false, { reason: 'interaction-finished' });
    }
    return true;
  }

  setRealtimeSpellActionPauseLocal(false, { reason: 'interaction-finished' });
  if (isOnlineMatchActive?.() && isRealtimeOnlineAuthority?.()) {
    try { markOnlineStateDirty('rt-spell-action-stop'); } catch (_) {}
  }
  return true;
}

async function beginRealtimeTacticalSpellCast(cardId, tabIndex, slotIndex) {
  const card = CARD_LIBRARY?.[cardId];
  if (!card) return false;
  const profile = getTacticalSpellbookDecisionProfile(card);
  if (!profile.tactical) return beginSpellbookDragCast(cardId, tabIndex, slotIndex);

  beginLocalOpponentActionView({
    cardId,
    title: card.name || card.id,
    step: 'Activando el hechizo directamente desde el Spellbook.',
  });

  const started = await requestRealtimeSpellActionPause(true, {
    playerId: LOCAL_PLAYER_ID,
    cardId,
    tab: Number(tabIndex),
    slot: Number(slotIndex),
  });
  if (!started) {
    log('No se pudo congelar el combate para esta decisión táctica.');
    return false;
  }

  try {
    const recommendation = getTacticalSpellbookRecommendation(tabIndex, slotIndex);
    recordRokMatchDiagnostic('spellbook-card-start', `Inicia ${card.name || card.id}.`, {
      cardId,
      tab: Number(tabIndex),
      slot: Number(slotIndex),
      tactical: true,
      recommendation: recommendation
        ? { score: recommendation.score, reasons: recommendation.reasons }
        : null,
    });
    recordRokTacticalTelemetry('spellbook-card-start', {
      cardId,
      cardName: card.name || card.id,
      tab: Number(tabIndex),
      slot: Number(slotIndex),
      recommendation: recommendation
        ? { score: recommendation.score, reasons: recommendation.reasons }
        : null,
    });
  } catch (_) {}

  const result = beginSpellbookDragCast(cardId, tabIndex, slotIndex);
  setTimeout(syncRealtimeSpellActionPauseState, 40);
  setTimeout(syncRealtimeSpellActionPauseState, 260);
  return result;
}

function renderTacticalSpellbookTabHints() {
  // Las recomendaciones rápidas dejaron de vivir en las pestañas del Spellbook.
  // Mantener la página estable evita entorpecer una carta que el usuario ya
  // estaba preparando.
  document.querySelectorAll('#tabStack > .deck-tab').forEach(btn => {
    btn.classList.remove('spellbook-page-tactical-recommended', 'spellbook-page-tactical-primary');
    delete btn.dataset.tacticalRecommendation;
  });
  maybeAutoFocusTacticalSpellbookRecommendation();
}


// =========================================================
// RT-08.18 · Rail persistente de CASTEO RÁPIDO.
// No cambia el Spellbook, no enfoca pestañas y no usa la vieja ventana de
// acción. Solo contiene CARTAS con una oportunidad rápida real.
// =========================================================
const realtimeQuickCastRailRuntime = {
  timer: 0,
  lastSignature: '',
  executingKey: '',
};

function isRealtimeQuickCastSpellbookCandidate(candidate) {
  if (!candidate?.cardId || !Array.isArray(candidate.actions) || !candidate.actions.length) return false;
  const card = CARD_LIBRARY?.[candidate.cardId];
  if (!card) return false;
  const typeId = getCardTypeId(card);
  if (!['spell', 'ability'].includes(typeId)) return false;
  if (candidate.type === 'casterAbility' && !resolveQuickReactionSpellbookSlot(candidate)) return false;
  return Boolean(
    resolveQuickReactionSpellbookSlot(candidate)
    || candidate.type === 'spellbookReaction'
    || candidate.type === 'kouutenRecast'
    || candidate.selectionType === 'spellbook'
    || candidate.selectionType === 'spell'
  );
}

function getRealtimeQuickCastCandidateKey(candidate) {
  const actionId = String(candidate?.actions?.[0]?.id || '');
  const slot = resolveQuickReactionSpellbookSlot(candidate);
  return [
    String(candidate?.cardId || ''),
    actionId,
    slot ? `${slot.tab}:${slot.slot}` : '',
  ].join(':');
}

function getRealtimeQuickCastCandidatePriority(candidate) {
  const actionId = String(candidate?.actions?.[0]?.id || '');
  const slot = resolveQuickReactionSpellbookSlot(candidate);
  let score = 0;

  if (slot) {
    const recommendation = getTacticalSpellbookRecommendation(slot.tab, slot.slot);
    if (recommendation) score += Number(recommendation.score || 0);
  }

  if (actionId === 'kiaraNoNegateCast') score += 1320;
  else if (actionId === 'gloriaLatenteQuickCast') score += 1200;
  else if (actionId === 'interceptarArtimana') score += 960;
  else if (actionId === 'emboscadaDefensaRapida') score += 900;
  else if (actionId === 'kouutenRecastPrompt' || actionId === 'kiaraRegresaRecastPrompt') score += 1280;
  else score += 500;

  return score;
}

function collectRealtimeQuickCastCandidates() {
  if (!isBattleHudScreenActive?.()
      || !isRealtimePlayStyle?.()
      || !state?.realtime?.active
      || state.gameOver) return [];

  const candidates = [];

  // Una decisión de recasteo ya abierta es exclusiva: igual que ¡No!, el rail
  // muestra solo ESA carta y PASAR hasta que el jugador decida.
  try {
    const activeRecastDecision = createRealtimeProgressiveRecastDecisionCandidate();
    if (isRealtimeQuickCastSpellbookCandidate(activeRecastDecision)) return [activeRecastDecision];
  } catch (error) {
    reportDebugError('quick-cast-rail-progressive-exclusive', error);
  }

  // Independiente de la vieja Ventana de acción.
  try {
    const kiaraNo = createKiaraNoQuickReactionCandidate(LOCAL_PLAYER_ID);
    if (isRealtimeQuickCastSpellbookCandidate(kiaraNo)) candidates.push(kiaraNo);
  } catch (error) {
    reportDebugError('quick-cast-rail-kiara-no', error);
  }

  try {
    const interceptar = createInterceptarArtimanaQuickReactionCandidate(LOCAL_PLAYER_ID);
    if (isRealtimeQuickCastSpellbookCandidate(interceptar)) candidates.push(interceptar);
  } catch (error) {
    reportDebugError('quick-cast-rail-interceptar', error);
  }

  try {
    const emboscada = createEmboscadaQuickReactionCandidate(LOCAL_PLAYER_ID);
    if (isRealtimeQuickCastSpellbookCandidate(emboscada)) candidates.push(emboscada);
  } catch (error) {
    reportDebugError('quick-cast-rail-emboscada', error);
  }

  try {
    if (state.gloriaLatenteReactionCurrent) {
      const gloria = createGloriaLatenteQuickReactionCandidate(state.gloriaLatenteReactionCurrent);
      if (isRealtimeQuickCastSpellbookCandidate(gloria)) candidates.push(gloria);
    }
  } catch (error) {
    reportDebugError('quick-cast-rail-gloria', error);
  }


  const deduped = new Map();
  candidates.forEach(candidate => {
    if (!isRealtimeQuickCastSpellbookCandidate(candidate)) return;
    const key = getRealtimeQuickCastCandidateKey(candidate);
    const current = deduped.get(key);
    if (!current || getRealtimeQuickCastCandidatePriority(candidate) > getRealtimeQuickCastCandidatePriority(current)) {
      deduped.set(key, candidate);
    }
  });

  return [...deduped.values()]
    .sort((a, b) => getRealtimeQuickCastCandidatePriority(b) - getRealtimeQuickCastCandidatePriority(a))
    .slice(0, 4);
}

function ensureRealtimeQuickCastRail() {
  let rail = document.getElementById('realtimeQuickCastRail');
  const host = document.body;
  if (!host) return null;

  if (rail && rail.parentElement !== host) {
    rail.remove();
    rail = null;
  }
  if (rail) return rail;

  rail = document.createElement('aside');
  rail.id = 'realtimeQuickCastRail';
  rail.className = 'realtime-quick-cast-rail rok-quick-cast-external';
  rail.dataset.host = 'document-body';
  rail.setAttribute('aria-label', 'Casteo rápido');
  rail.setAttribute('aria-hidden', 'true');
  host.appendChild(rail);
  return rail;
}

function positionRealtimeQuickCastRail() {
  const rail = document.getElementById('realtimeQuickCastRail');
  const board = document.getElementById('board');
  if (!rail || !board || !rail.classList.contains('visible')) return false;

  const rect = board.getBoundingClientRect();
  if (!(rect.width > 0) || !(rect.height > 0)) return false;

  // El rail vive fuera del DOM de Arena, pero visualmente ocupa el mismo
  // margen derecho libre: grid termina ~77.7%, lámpara derecha ~91%.
  const width = Math.max(82, Math.min(116, rect.width * 0.16));
  const left = rect.left + (rect.width * 0.905);
  const top = rect.top + (rect.height * 0.205);
  const maxHeight = Math.max(180, rect.height * 0.61);

  rail.style.setProperty('left', `${Math.round(left)}px`, 'important');
  rail.style.setProperty('top', `${Math.round(top)}px`, 'important');
  rail.style.setProperty('width', `${Math.round(width)}px`, 'important');
  rail.style.setProperty('max-height', `${Math.round(maxHeight)}px`, 'important');
  rail.style.setProperty('right', 'auto', 'important');
  rail.style.setProperty('bottom', 'auto', 'important');
  return true;
}

async function executeRealtimeQuickCastCandidate(candidate) {
  if (!candidate || realtimeQuickCastRailRuntime.executingKey) return false;
  const key = getRealtimeQuickCastCandidateKey(candidate);
  realtimeQuickCastRailRuntime.executingKey = key;
  const action = candidate.actions?.[0] || null;
  const card = CARD_LIBRARY?.[candidate.cardId];
  const slot = resolveQuickReactionSpellbookSlot(candidate);

  try {
    if (String(candidate.cardId || '') !== String(KIARA_NO_CARD_ID || '')) {
      beginLocalOpponentActionView({
        cardId: candidate.cardId,
        title: action?.title || action?.label || card?.name || 'Casteo rápido',
        step: 'La acción rápida fue activada; el rival prepara su selección.',
      });
    }
    if (candidate.progressiveRecastDecision === true
        || action?.id === 'kiaraRegresaRecastPrompt'
        || (action?.id === 'kouutenRecastPrompt' && getRealtimeProgressiveRecastDecision())) {
      return Boolean(await acceptRealtimeProgressiveRecastDecision(candidate));
    }

    // Congelar primero. Así ningún movimiento/ataque que caiga en el mismo
    // frame puede seguir avanzando mientras se abre el selector de la carta.
    acquireRealtimeSpellActionHardPause({
      playerId: LOCAL_PLAYER_ID,
      cardId: candidate.cardId,
      tab: slot?.tab ?? -1,
      slot: slot?.slot ?? -1,
    });

    recordRokTacticalTelemetry('quick-cast-rail-activated', {
      cardId: candidate.cardId,
      actionId: action?.id || '',
      priority: getRealtimeQuickCastCandidatePriority(candidate),
      slot,
    });

    // Gloria ya mantiene el daño en espera mediante su lock dedicado. Añadir
    // otra pausa aquí duplicaría propietarios.
    if (action?.id === 'gloriaLatenteQuickCast') {
      const result = action.execute?.();
      return result instanceof Promise ? Boolean(await result) : result !== false;
    }

    if (action?.id === 'kouutenRecastPrompt') {
      if (!slot) return false;
      const pauseStarted = await requestRealtimeSpellActionPause(true, {
        playerId: LOCAL_PLAYER_ID,
        cardId: candidate.cardId,
        tab: slot.tab,
        slot: slot.slot,
      });
      if (!pauseStarted) {
        releaseRealtimeSpellActionHardPause('quick-cast-pause-rejected');
        return false;
      }
      const started = beginRealtimeKouutenRecastFromSpellbook(
        LOCAL_PLAYER_ID,
        slot.tab,
        slot.slot
      );
      if (!started) await requestRealtimeSpellActionPause(false, { reason: 'quick-cast-failed' });
      return Boolean(started);
    }

    if (!action?.execute) return false;

    // Interceptar/Emboscada y futuras cartas rápidas con targeting congelan
    // la simulación solo DESPUÉS de que el jugador toque su miniatura.
    let pauseStarted = true;
    if (slot) {
      pauseStarted = await requestRealtimeSpellActionPause(true, {
        playerId: LOCAL_PLAYER_ID,
        cardId: candidate.cardId,
        tab: slot.tab,
        slot: slot.slot,
      });
    }
    if (!pauseStarted) {
      releaseRealtimeSpellActionHardPause('quick-cast-pause-rejected');
      return false;
    }

    const result = action.execute();
    const resolved = result instanceof Promise ? await result : result;
    if (resolved === false && slot) {
      await requestRealtimeSpellActionPause(false, { reason: 'quick-cast-failed' });
    }
    return resolved !== false;
  } catch (error) {
    reportDebugError(`quick-cast:${card?.name || candidate.cardId}`, error);
    try { await requestRealtimeSpellActionPause(false, { reason: 'quick-cast-error' }); } catch (_) {}
    return false;
  } finally {
    realtimeQuickCastRailRuntime.executingKey = '';
    setTimeout(() => {
      try { syncRealtimeSpellActionPauseState(); } catch (_) {}
      syncRealtimeQuickCastRail(true);
    }, 40);
    setTimeout(() => {
      try { syncRealtimeSpellActionPauseState(); } catch (_) {}
    }, 260);
  }
}


function getRealtimeKiaraNoDecisionCandidate(candidates = []) {
  return (Array.isArray(candidates) ? candidates : []).find(candidate =>
    String(candidate?.actions?.[0]?.id || '') === 'kiaraNoNegateCast'
  ) || null;
}

function updateRealtimeKiaraNoDecisionTimerVisual() {
  const current = (state?.kiaraNoReactionCurrent && !state.kiaraNoReactionCurrent.resolved)
    ? state.kiaraNoReactionCurrent
    : getRealtimeProgressiveRecastDecision();
  const root = document.getElementById('realtimeQuickCastRail');
  if (!root) return false;
  const fill = root.querySelector('.realtime-quick-cast-decision-timer-fill');
  const label = root.querySelector('.realtime-quick-cast-decision-timer-label');
  if (!fill && !label) return false;
  const total = Math.max(1, Number(current?.decisionWindowMs || KIARA_NO_REACTION_WINDOW_MS));
  const expiresAt = Number(current?.decisionExpiresAt || 0);
  const remaining = expiresAt > 0 ? Math.max(0, expiresAt - Date.now()) : total;
  const pct = Math.max(0, Math.min(100, (remaining / total) * 100));
  if (fill) fill.style.width = `${pct}%`;
  if (label) label.textContent = `${(remaining / 1000).toFixed(1)} s`;
  return true;
}

function renderRealtimeQuickCastRail(candidates = collectRealtimeQuickCastCandidates()) {
  const rail = ensureRealtimeQuickCastRail();
  if (!rail) return false;
  const list = Array.isArray(candidates) ? candidates : [];

  rail.innerHTML = '';
  rail.classList.toggle('visible', list.length > 0);
  rail.setAttribute('aria-hidden', list.length ? 'false' : 'true');
  if (!list.length) return false;
  positionRealtimeQuickCastRail();

  const noDecision = getRealtimeKiaraNoDecisionCandidate(list);
  const recastDecision = list.find(candidate => candidate?.progressiveRecastDecision === true) || null;
  const compactDecision = noDecision || recastDecision;
  // v9.51 · durante ¡No! no mostramos encabezados ni instrucciones redundantes:
  // nombre del kasteo, reloj, carta clicable y PASAR.
  if (!compactDecision) {
    const title = document.createElement('div');
    title.className = 'realtime-quick-cast-rail-title';
    title.textContent = 'CASTEO RÁPIDO';
    rail.appendChild(title);
  }

  rail.classList.toggle('realtime-quick-cast-rail--decision', Boolean(compactDecision));
  rail.classList.toggle('realtime-quick-cast-rail--recast-decision', Boolean(recastDecision));
  if (compactDecision) {
    const targetCard = noDecision ? CARD_LIBRARY?.[noDecision.reactionTargetCardId] : null;
    const decision = document.createElement('div');
    decision.className = 'realtime-quick-cast-decision';
    const heading = recastDecision ? 'RECASTEAR' : (targetCard?.name || 'Carta desconocida');
    decision.innerHTML = `<strong>${heading}</strong><div class="realtime-quick-cast-decision-timer" aria-hidden="true"><i class="realtime-quick-cast-decision-timer-fill"></i></div><em class="realtime-quick-cast-decision-timer-label">${recastDecision ? '5.0' : '4.0'} s</em>`;
    rail.appendChild(decision);
  }

  list.forEach((candidate, index) => {
    const card = CARD_LIBRARY?.[candidate.cardId];
    if (!card) return;

    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'realtime-quick-cast-card realtime-quick-cast-card-mini';
    button.dataset.cardId = String(candidate.cardId || '');
    button.dataset.quickCastRank = String(index + 1);
    button.title = `${index === 0 ? 'Recomendación principal' : `Opción ${index + 1}`} · ${card.name || candidate.cardId} · ${candidate.actions?.[0]?.title || candidate.actions?.[0]?.label || 'Kastear'}`;

    const rank = document.createElement('span');
    rank.className = 'realtime-quick-cast-rank';
    rank.textContent = index === 0 ? '1' : String(index + 1);

    const miniHost = document.createElement('span');
    miniHost.className = 'realtime-quick-cast-miniature';
    try {
      const visual = createCardElement(card);
      visual.classList.add('realtime-quick-cast-card-visual');
      miniHost.appendChild(visual);
    } catch (_) {
      const image = getQuickReactionIndicatorImage(card);
      if (image) miniHost.innerHTML = `<img src="${image}" alt="">`;
      else miniHost.textContent = card.shortName || card.name || 'Carta';
    }

    const actionChip = document.createElement('span');
    actionChip.className = 'realtime-quick-cast-action-chip';
    actionChip.textContent = String(candidate.actions?.[0]?.label || 'KASTEAR').toUpperCase();

    const nameChip = document.createElement('span');
    nameChip.className = 'realtime-quick-cast-name-chip';
    nameChip.textContent = card.shortName || card.name || 'Carta';

    button.append(miniHost, rank, actionChip, nameChip);
    let quickCastActivationStarted = false;
    const activateQuickCast = event => {
      if (quickCastActivationStarted) return;
      if (event?.type === 'pointerdown' && event.pointerType === 'mouse' && Number(event.button) !== 0) return;
      quickCastActivationStarted = true;
      event?.preventDefault?.();
      event?.stopPropagation?.();
      event?.stopImmediatePropagation?.();
      button.classList.add('is-activating');
      void executeRealtimeQuickCastCandidate(candidate);
    };
    button.addEventListener('pointerdown', activateQuickCast, { capture: true });
    button.addEventListener('click', activateQuickCast, { capture: true });
    rail.appendChild(button);
  });

  if (compactDecision) {
    const pass = document.createElement('button');
    pass.type = 'button';
    pass.className = 'realtime-quick-cast-pass';
    pass.textContent = 'PASAR';
    let quickPassStarted = false;
    const activateQuickPass = event => {
      if (quickPassStarted) return;
      if (event?.type === 'pointerdown' && event.pointerType === 'mouse' && Number(event.button) !== 0) return;
      quickPassStarted = true;
      event?.preventDefault?.();
      event?.stopPropagation?.();
      event?.stopImmediatePropagation?.();
      if (recastDecision) void declineRealtimeProgressiveRecastDecision('pass');
      else void declineKiaraNoReaction('pass');
    };
    pass.addEventListener('pointerdown', activateQuickPass, { capture: true });
    pass.addEventListener('click', activateQuickPass, { capture: true });
    rail.appendChild(pass);
    updateRealtimeKiaraNoDecisionTimerVisual();
  }

  return true;
}

function syncRealtimeQuickCastRail(force = false, suppliedCandidates = null) {
  if (!isRealtimePlayStyle?.() || !state?.realtime?.active || state.gameOver) {
    document.getElementById('realtimeQuickCastRail')?.remove();
    realtimeQuickCastRailRuntime.lastSignature = '';
    return false;
  }

  const candidates = Array.isArray(suppliedCandidates)
    ? suppliedCandidates.filter(isRealtimeQuickCastSpellbookCandidate)
    : collectRealtimeQuickCastCandidates();

  const ordered = candidates
    .slice()
    .sort((a, b) => getRealtimeQuickCastCandidatePriority(b) - getRealtimeQuickCastCandidatePriority(a))
    .slice(0, 4);

  const signature = ordered
    .map(candidate => `${getRealtimeQuickCastCandidateKey(candidate)}:${Math.round(getRealtimeQuickCastCandidatePriority(candidate))}`)
    .join('|');

  if (!force && signature === realtimeQuickCastRailRuntime.lastSignature) {
    if (ordered.length) {
      positionRealtimeQuickCastRail();
      updateRealtimeKiaraNoDecisionTimerVisual();
    }
    return Boolean(ordered.length);
  }
  const previousSignature = realtimeQuickCastRailRuntime.lastSignature;
  realtimeQuickCastRailRuntime.lastSignature = signature;
  renderRealtimeQuickCastRail(ordered);
  try { syncLocalQuickReactionGameplayPause(); } catch (_) {}
  try {
    recordRokMatchDiagnostic('quick-cast-rail-update', ordered.length ? 'Oportunidades rápidas visibles.' : 'Rail rápido vacío.', {
      previousSignature,
      signature,
      candidates: ordered.map(candidate => ({
        cardId: candidate.cardId,
        actionId: candidate.actions?.[0]?.id || '',
        priority: getRealtimeQuickCastCandidatePriority(candidate),
      })),
      host: document.getElementById('realtimeQuickCastRail')?.parentElement === document.body ? 'document.body' : 'unexpected',
      boardRect: (() => {
        const rect = document.getElementById('board')?.getBoundingClientRect?.();
        return rect ? { left: rect.left, top: rect.top, width: rect.width, height: rect.height } : null;
      })(),
    });
  } catch (_) {}
  return Boolean(ordered.length);
}

function initRealtimeQuickCastRail() {
  clearInterval(realtimeQuickCastRailRuntime.timer);
  realtimeQuickCastRailRuntime.timer = setInterval(() => {
    try { syncRealtimeQuickCastRail(); }
    catch (error) { reportDebugError('quick-cast-rail-sync', error); }
  }, 320);
  window.addEventListener('resize', positionRealtimeQuickCastRail, { passive: true });
  window.addEventListener('orientationchange', positionRealtimeQuickCastRail, { passive: true });
}

function renderSpellbookPageAvailabilityHints() {
  const quickReactionTab = getActiveQuickReactionPageTab();
  const onCastingPhase = isRealtimePlayStyle() || (currentPhase().id === 'casting'
    && Number(state.activePlayer) === Number(LOCAL_PLAYER_ID));

  // La reacción rápida no sustituye estos indicadores. Si está abierta, los
  // botones siguen mostrando normalmente qué páginas contienen cartas usables.
  const tacticaReadyOutsideCasting = (isRealtimePlayStyle() || Number(state.activePlayer) === Number(LOCAL_PLAYER_ID)) && getTacticaGuerraCastAvailability(LOCAL_PLAYER_ID).available;
  const interceptarReady = getInterceptarCastAvailability(LOCAL_PLAYER_ID).available;
  const emboscadaReady = getEmboscadaCastAvailability(LOCAL_PLAYER_ID).available;
  const availabilityHintsEnabled = onCastingPhase || quickReactionTab != null || tacticaReadyOutsideCasting || interceptarReady || emboscadaReady;
  const pageState = new Map();
  const tabs = state.players?.[LOCAL_PLAYER_ID]?.handTabs || [];

  tabs.forEach((tab, tabIndex) => {
    let hasReady = false;
    (tab || []).forEach((cardId, slotIndex) => {
      if (!cardId || hasReady) return;
      if (getSpellbookUseCooldown(LOCAL_PLAYER_ID, tabIndex, slotIndex) > 0) return;

      if (
        cardId === DESPLIEGUE_ANTICIPADO_CARD_ID
        && getDespliegueAnticipadoCastAvailability(LOCAL_PLAYER_ID).available
      ) {
        hasReady = true;
      }

      if (
        cardId === GLORIA_LATENTE_CARD_ID
        && getGloriaLatenteCastAvailability(LOCAL_PLAYER_ID).available
      ) {
        hasReady = true;
      }

      if (
        cardId === TACTICA_GUERRA_CARD_ID
        && getTacticaGuerraCastAvailability(LOCAL_PLAYER_ID).available
      ) {
        hasReady = true;
      }

      if (
        cardId === INTERCEPTAR_CARD_ID
        && getInterceptarCastAvailability(LOCAL_PLAYER_ID).available
      ) {
        hasReady = true;
      }

      if (cardId === EMBOSCADA_CARD_ID && getEmboscadaCastAvailability(LOCAL_PLAYER_ID).available) hasReady = true;
    });
    pageState.set(tabIndex, hasReady);
  });

  document.querySelectorAll('#tabStack > .deck-tab').forEach(btn => {
    const tabIndex = Number(btn.dataset.tab);
    const ready = availabilityHintsEnabled && Boolean(pageState.get(tabIndex));
    const isCurrentPage = tabIndex === Number(state.activeTab);

    btn.classList.toggle('spellbook-page-ready', ready && !isCurrentPage);
    btn.classList.toggle('spellbook-page-active-ready', ready && isCurrentPage);

    if (!ready) {
      clearSpellbookPageAvailabilityLayers(btn);
      return;
    }

    const { foil, indicator } = ensureSpellbookPageAvailabilityLayers(btn);
    foil.title = 'Hay una carta utilizable en esta página';
    indicator.title = 'Hay una carta utilizable en esta página';
  });
  renderTacticalSpellbookTabHints();
}

const spellbookCardDragState = {
  active: false,
  cardId: null,
  tab: null,
  slot: null,
  sourceNode: null,
};

function clearSpellbookCardDragVisuals() {
  document.body.classList.remove('rok-spellbook-card-dragging');
  els.boardContent?.classList.remove('spellbook-card-drop-ready');
  document.querySelectorAll('.card-slot.spellbook-drag-source').forEach(node => node.classList.remove('spellbook-drag-source'));
  spellbookCardDragState.active = false;
  spellbookCardDragState.cardId = null;
  spellbookCardDragState.tab = null;
  spellbookCardDragState.slot = null;
  spellbookCardDragState.sourceNode = null;
}

function beginSpellbookDragCast(cardId, tabIndex, slotIndex) {
  const tab = Number(tabIndex);
  const slot = Number(slotIndex);
  if (isRealtimeThoughtPauseActive()) {
    const inspectCardId = localPlayer()?.handTabs?.[tab]?.[slot];
    if (inspectCardId) openCardInfo(inspectCardId, slot, tab, { thoughtInspection: true });
    return false;
  }
  const liveCardId = localPlayer()?.handTabs?.[tab]?.[slot];
  if (!cardId || liveCardId !== cardId) {
    log('Esa copia ya no está disponible en el Spellbook.');
    renderAll();
    return false;
  }
  // v9.57 · En Tiempo Real una animación/resolución autónoma no debe comerse
  // el clic del Spellbook. La compuerta dura se conserva en Manual y cuando el
  // Tempo RT está explícitamente pausado por una decisión/reacción que requiere
  // exclusividad. Con el reloj corriendo, el intento de kasteo se acepta.
  const realtimeRunningInput = Boolean(isRealtimePlayStyle() && state?.realtime?.active && !isRealtimeTempoPaused());
  if ((state.actionExecutionLock || state.opponentActionResolving) && !realtimeRunningInput) {
    log('Espera a que termine la acción en curso antes de kastear otra carta.');
    return false;
  }
  if (state.pendingPowerAction) {
    log('Termina o cancela la selección actual antes de arrastrar otra carta.');
    return false;
  }

  // El arrastre sustituye a seleccionar la carta y pulsar Kastear/Equipar en su modal.
  // Reutilizamos el mismo botón oculto para respetar exactamente sus validaciones actuales.
  state.activeTab = tab;
  state.selectedCardSlot = slot;
  state.pendingCard = null;
  state.pendingPlacement = null;
  state.infoCard = { cardId, slotIndex: slot, tab };
  updateCardInfoAction();

  if (!els.cardInfoKastBtn || els.cardInfoKastBtn.disabled) {
    const reason = els.cardInfoKastBtn?.title || `No puedes usar ${CARD_LIBRARY[cardId]?.name || 'esa carta'} ahora.`;
    log(reason);
    renderAll();
    return false;
  }

  startKastFromInfo();
  return true;
}

function setupSpellbookCardDrag(cardNode, cardId, tabIndex, slotIndex) {
  if (!cardNode || !cardId) return;
  const card = CARD_LIBRARY[cardId];
  const costAvailable = Boolean(card && canPayCardCostForPlayer(LOCAL_PLAYER_ID, card));
  cardNode.draggable = costAvailable;
  cardNode.classList.add('spellbook-draggable-card');
  cardNode.querySelectorAll('img').forEach(img => { img.draggable = false; });

  cardNode.addEventListener('dragstart', event => {
    if (isRealtimeThoughtPauseActive()) {
      event.preventDefault();
      openCardInfo(cardId, Number(slotIndex), Number(tabIndex), { thoughtInspection: true });
      return;
    }
    const liveCostCard = CARD_LIBRARY[cardId];
    if (!liveCostCard || !canPayCardCostForPlayer(LOCAL_PLAYER_ID, liveCostCard)) {
      event.preventDefault();
      return;
    }
    if (cardId === SHIRAHADORI_ABILITY_CARD_ID) {
      const availability = getShirahadoriAbilityCastAvailability(LOCAL_PLAYER_ID);
      if (!availability.available) {
        event.preventDefault();
        log(availability.message);
        return;
      }
    }
    const useCooldown = getSpellbookUseCooldown(LOCAL_PLAYER_ID, tabIndex, slotIndex);
    if (useCooldown > 0) {
      event.preventDefault();
      log(`${CARD_LIBRARY[cardId]?.name || 'Esta carta'} está en Estasis de Spellbook durante ${useCooldown} fase${useCooldown === 1 ? '' : 's'} más.`);
      return;
    }
    if (!event.dataTransfer) return;
    spellbookCardDragState.active = true;
    spellbookCardDragState.cardId = cardId;
    spellbookCardDragState.tab = Number(tabIndex);
    spellbookCardDragState.slot = Number(slotIndex);
    spellbookCardDragState.sourceNode = cardNode;
    cardNode.closest('.card-slot')?.classList.add('spellbook-drag-source');
    document.body.classList.add('rok-spellbook-card-dragging');
    event.dataTransfer.effectAllowed = 'copy';
    const payload = JSON.stringify({ cardId, tab: Number(tabIndex), slot: Number(slotIndex) });
    try { event.dataTransfer.setData('application/x-rok-spellbook-card', payload); } catch (_) {}
    try { event.dataTransfer.setData('text/plain', payload); } catch (_) {}
  });

  cardNode.addEventListener('dragend', () => {
    cardNode.dataset.spellbookDragEndedAt = String(Date.now());
    clearSpellbookCardDragVisuals();
  });
}

function handleSpellbookCardDragOverArena(event) {
  if (!spellbookCardDragState.active) return;
  event.preventDefault();
  if (event.dataTransfer) event.dataTransfer.dropEffect = 'copy';
  els.boardContent?.classList.add('spellbook-card-drop-ready');
}

function handleSpellbookCardDropOnArena(event) {
  if (!spellbookCardDragState.active) return;
  event.preventDefault();
  event.stopPropagation();

  let payload = null;
  const raw = event.dataTransfer?.getData('application/x-rok-spellbook-card')
    || event.dataTransfer?.getData('text/plain')
    || '';
  if (raw) {
    try { payload = JSON.parse(raw); } catch (_) {}
  }
  const cardId = payload?.cardId || spellbookCardDragState.cardId;
  const tab = Number(payload?.tab ?? spellbookCardDragState.tab);
  const slot = Number(payload?.slot ?? spellbookCardDragState.slot);
  const sourceNode = spellbookCardDragState.sourceNode;
  clearSpellbookCardDragVisuals();
  if (sourceNode) sourceNode.dataset.spellbookDragEndedAt = String(Date.now());
  beginSpellbookDragCast(cardId, tab, slot);
}

function renderCards() {
  const tab = localPlayer().handTabs[state.activeTab] || [];
  const reactionFocus = state.quickReactionSpellbookFocus;
  const focusOnThisPage = Boolean(reactionFocus && Number(reactionFocus.tab) === Number(state.activeTab));
  const fragment = document.createDocumentFragment();
  els.cardGrid.classList.toggle('quick-reaction-spellbook-focus-active', focusOnThisPage);
  for (let i = 0; i < 12; i++) {
    const slot = document.createElement('div');
    slot.className = 'card-slot';
    if (i === state.selectedCardSlot) slot.classList.add('selected');
    const key = document.createElement('span');
    key.className = 'key-label';
    key.textContent = CARD_KEYS[i];
    slot.appendChild(key);
    const cardId = tab[i];
    if (cardId) {
      const isReactionFocus = focusOnThisPage && Number(reactionFocus.slot) === i && String(reactionFocus.cardId || '') === String(cardId);
      slot.classList.toggle('quick-reaction-spellbook-focus', isReactionFocus);
      slot.classList.toggle('quick-reaction-spellbook-muted', focusOnThisPage && !isReactionFocus);
      const card = CARD_LIBRARY[cardId];
      const cardNode = createCardElement(card);
      cardNode.dataset.cardId = cardId;
      const tacticalRecommendation = getTacticalSpellbookRecommendation(state.activeTab, i);
      slot.classList.remove('spellbook-tactical-recommended', 'spellbook-tactical-primary');
      cardNode.classList.remove('spellbook-tactical-recommended-card');
      if (tacticalRecommendation) slot.dataset.tacticalScore = String(Math.round(tacticalRecommendation.score));
      else delete slot.dataset.tacticalScore;
      const progressiveStatus = card?.id === KOUUTEN_CARD_ID
        ? getRealtimeKouutenProgressiveSlotState(LOCAL_PLAYER_ID, state.activeTab, i)
        : card?.id === KIARA_NO_CARD_ID
          ? getRealtimeKiaraNoProgressiveSlotState(LOCAL_PLAYER_ID, state.activeTab, i)
          : card?.id === KIARA_REGRESA_CARD_ID
            ? getRealtimeKiaraRegresaProgressiveSlotState(LOCAL_PLAYER_ID, state.activeTab, i)
            : null;
      const progressiveLocked = Boolean(progressiveStatus && progressiveStatus.kind !== 'ready');
      const progressivePayable = Boolean(progressiveStatus?.kind === 'ready' && progressiveStatus.ready);
      const costAvailable = progressiveStatus
        ? progressivePayable
        : Boolean(card && canPayCardCostForPlayer(LOCAL_PLAYER_ID, card));
      const costUnavailable = !costAvailable;
      slot.classList.toggle('spellbook-cost-unavailable', costUnavailable);
      cardNode.classList.toggle('spellbook-cost-unavailable-card', costUnavailable);
      cardNode.setAttribute('aria-disabled', costUnavailable ? 'true' : 'false');
      if (costUnavailable) cardNode.dataset.spellbookCostUnavailable = 'true';
      if (card?.id === SHIRAHADORI_ABILITY_CARD_ID) {
        const shirahadoriAvailability = getShirahadoriAbilityCastAvailability(LOCAL_PLAYER_ID);
        const disabledWithoutUser = !shirahadoriAvailability.available;
        const shirahadoriCooldown = getSpellbookUseCooldown(LOCAL_PLAYER_ID, state.activeTab, i);
        const readyToUse = costAvailable
          && !disabledWithoutUser
          && (isRealtimePlayStyle() || Number(state.activePlayer) === Number(LOCAL_PLAYER_ID))
          && (isRealtimePlayStyle() || currentPhase().id === 'casting')
          && shirahadoriCooldown <= 0;

        slot.classList.toggle('shirahadori-no-valid-user', disabledWithoutUser);
        slot.classList.toggle('shirahadori-spell-ready', readyToUse);
        cardNode.classList.toggle('shirahadori-no-valid-user-card', disabledWithoutUser);
        cardNode.classList.toggle('shirahadori-spell-ready-card', readyToUse);
        cardNode.setAttribute('aria-disabled', disabledWithoutUser ? 'true' : 'false');

        if (disabledWithoutUser) {
          cardNode.dataset.shirahadoriDisabled = 'true';
          slot.title = shirahadoriAvailability.message;
        } else {
          delete cardNode.dataset.shirahadoriDisabled;
          if (readyToUse) {
            slot.title = 'Shirahadori listo para usar.';
            const readyDot = document.createElement('span');
            readyDot.className = 'spellbook-action-ready-indicator shirahadori-action-ready-indicator';
            readyDot.title = 'Shirahadori listo para usar';
            slot.appendChild(readyDot);
          }
        }
      }
      if (costAvailable && !progressiveStatus) setupSpellbookCardDrag(cardNode, cardId, state.activeTab, i);
      if (isHideyoshiWarColleaguesInstantReady(card)) cardNode.classList.add('war-colleagues-ready');
      if ([DESPLIEGUE_ANTICIPADO_CARD_ID, GLORIA_LATENTE_CARD_ID, TACTICA_GUERRA_CARD_ID, INTERCEPTAR_CARD_ID, EMBOSCADA_CARD_ID].includes(card.id)) {
        const availability = card.id === DESPLIEGUE_ANTICIPADO_CARD_ID
          ? getDespliegueAnticipadoCastAvailability(LOCAL_PLAYER_ID)
          : card.id === GLORIA_LATENTE_CARD_ID
            ? getGloriaLatenteCastAvailability(LOCAL_PLAYER_ID)
            : card.id === TACTICA_GUERRA_CARD_ID
              ? getTacticaGuerraCastAvailability(LOCAL_PLAYER_ID)
              : card.id === INTERCEPTAR_CARD_ID
                ? getInterceptarCastAvailability(LOCAL_PLAYER_ID)
                : getEmboscadaCastAvailability(LOCAL_PLAYER_ID);
        const readyTitle = card.id === DESPLIEGUE_ANTICIPADO_CARD_ID
          ? 'Despliegue anticipado listo: hay un Caudillo válido en arena.'
          : card.id === GLORIA_LATENTE_CARD_ID
            ? 'Gloria latente lista: hay una invocación válida en arena.'
            : card.id === TACTICA_GUERRA_CARD_ID
              ? 'Táctica de guerra lista: hay una invocación aliada activa con costo pagable.'
              : card.id === INTERCEPTAR_CARD_ID
                ? 'Interceptar listo: hay una invocación aliada y un invasor rival con casilla frontal libre.'
                : 'Emboscada lista: hay una invasora rival, invocaciones aliadas y Agua disponible.';
        const spellReady = Boolean(availability.available && costAvailable);
        slot.classList.toggle('despliegue-spell-unavailable', !spellReady);
        slot.classList.toggle('despliegue-spell-ready', spellReady);
        cardNode.classList.toggle('despliegue-spell-unavailable-card', !spellReady);
        cardNode.classList.toggle('despliegue-spell-ready-card', spellReady);
        slot.title = costUnavailable ? '' : (availability.available ? readyTitle : availability.message);
        if (spellReady) {
          const readyDot = document.createElement('span');
          readyDot.className = 'spellbook-action-ready-indicator';
          readyDot.title = 'Requisitos de arena cumplidos';
          slot.appendChild(readyDot);
        }
      }
      if (costUnavailable) cardNode.setAttribute('aria-disabled', 'true');

      if (progressiveStatus) {
        slot.classList.add('realtime-progressive-cast-slot');
        slot.classList.toggle('is-ready', progressiveStatus.kind === 'ready' && progressiveStatus.ready);
        const overlay = document.createElement('div');
        overlay.className = `realtime-progressive-cast-overlay is-${progressiveStatus.kind}`;
        if (progressiveStatus.kind === 'casting') {
          overlay.innerHTML = `<span class="realtime-progressive-timer-only">${(progressiveStatus.remainingMs / 1000).toFixed(1)}s</span>`;
        } else if (progressiveStatus.kind === 'cooldown') {
          overlay.innerHTML = `<span class="realtime-progressive-timer-only">${(progressiveStatus.remainingMs / 1000).toFixed(1)}s</span>`;
        } else if (progressiveStatus.kind === 'ready' && card?.id === KIARA_NO_CARD_ID) {
          overlay.innerHTML = `<span class="realtime-progressive-timer-only">${(progressiveStatus.remainingMs / 1000).toFixed(1)}s</span>`;
        } else if (progressiveStatus.kind === 'ready') {
          overlay.innerHTML = `<span class="realtime-progressive-timer-only">●</span>`;
        } else {
          overlay.innerHTML = `<span class="realtime-progressive-timer-only">…</span>`;
        }
        slot.appendChild(overlay);
      }
      cardNode.addEventListener('click', (event) => {
        event.preventDefault();
        event.stopPropagation();
        if (progressiveStatus) return;
        if (costUnavailable) return;
        const dragEndedAt = Number(cardNode.dataset.spellbookDragEndedAt || 0);
        if (dragEndedAt && Date.now() - dragEndedAt < 250) return;
        selectCardSlot(i);
      });
      slot.appendChild(cardNode);

      // v9.65 · El Spellbook solo muestra temporizadores. La decisión de recasteo
      // se abre automáticamente en el rail rápido al terminar el cooldown.

      // v9.02 · Etapa 3: INFO independiente en Tiempo Real.
      // Debe poder leerse incluso si la carta no tiene recursos, está en cooldown
      // o tiene un flujo progresivo activo. Nunca inicia selección/kasteo.
      if (isRealtimePlayStyle()) {
        const infoBtn = document.createElement('button');
        infoBtn.type = 'button';
        infoBtn.className = 'realtime-spellbook-info-btn';
        infoBtn.textContent = 'INFO';
        infoBtn.title = `Ver información de ${card?.name || 'la carta'}`;
        infoBtn.setAttribute('aria-label', `Información de ${card?.name || 'la carta'}`);
        const stopInfoPointer = event => {
          event.preventDefault();
          event.stopPropagation();
        };
        ['pointerdown', 'mousedown', 'touchstart', 'dragstart'].forEach(type => {
          infoBtn.addEventListener(type, stopInfoPointer, { passive: false });
        });
        infoBtn.addEventListener('click', event => {
          event.preventDefault();
          event.stopPropagation();
          openCardInfo(cardId, i, state.activeTab, { source: 'spellbookInfo' });
        });
        slot.appendChild(infoBtn);
      }
      const useCooldown = getSpellbookUseCooldown(LOCAL_PLAYER_ID, state.activeTab, i);
      if (useCooldown > 0) {
        slot.classList.add('spellbook-use-cooldown');
        const cooldownOverlay = document.createElement('div');
        cooldownOverlay.className = 'spellbook-use-cooldown-overlay';
        const cooldownEntry = localPlayer()?.spellbookUseCooldowns?.[getSpellbookCooldownKey(state.activeTab, i)] || null;
        const breakdown = cooldownEntry?.breakdown || null;
        const detail = breakdown
          ? ` · Base ${Math.max(0, Number(breakdown.base || 0))} + habilidades ${Math.max(0, Number(breakdown.learned || 0))}${Math.max(0, Number(breakdown.despliegue || 0)) > 0 ? ` + otros ${Math.max(0, Number(breakdown.despliegue || 0))}` : ''}`
          : '';
        cooldownOverlay.title = `Estasis de Spellbook: ${useCooldown} fase${useCooldown === 1 ? '' : 's'} restante${useCooldown === 1 ? '' : 's'}${detail}`;
        cooldownOverlay.innerHTML = `<span class="spellbook-use-cooldown-card"><img src="${SPELLBOOK_COOLDOWN_ICON_ASSET}" alt="Estasis de Spellbook"></span><strong>${useCooldown}</strong>`;
        slot.appendChild(cooldownOverlay);
      }
      if (getCardTypeId(card) === 'invocation' || getCardTypeId(card) === 'spell') {
        const costLayer = document.createElement('div');
        costLayer.className = 'game-spellbook-cost-layer';
        costLayer.innerHTML = buildGameSpellbookInvocationCostRibbon(card);
        slot.appendChild(costLayer);
      }
      slot.addEventListener('click', (event) => {
        event.preventDefault();
        if (progressiveStatus) return;
        if (costUnavailable) return;
        selectCardSlot(i);
      });
    } else {
      slot.classList.add('empty');
    }
    fragment.appendChild(slot);
  }
  els.cardGrid.replaceChildren(fragment);
}


function createCardDomainElement(card) {
  const domain = getDomainArtProfile(card);
  const node = document.createElement('button');
  node.type = 'button';
  node.className = 'card-domain-zone card-domain-zone-clickable';
  node.dataset.infoKind = 'domain';
  node.dataset.infoId = getCardElementId(card);
  node.title = `Dominio: ${domain.elementLabel} · Atributo: ${domain.attributeLabel}`;
  node.innerHTML = `
    <div class="card-domain-layer card-domain-bg" aria-hidden="true"></div>
    <img class="card-domain-layer card-domain-element" src="${domain.elementArt}" alt="Elemento ${domain.elementLabel}">
    <img class="card-domain-layer card-domain-attribute" src="${domain.attributeArt}" alt="Atributo ${domain.attributeLabel}">
  `;
  node.addEventListener('click', event => {
    event.stopPropagation();
    openCardMetaInfo('domain', getCardElementId(card), card);
  });
  return node;
}

function createCardElement(card, options = {}) {
  const wrap = document.createElement('div');
  wrap.className = 'card';
  const elementId = options.elementIdOverride || options.elementId || getCardElementId(card);
  const element = getElementById(elementId);
  const skinImage = getElementSkinForCard(card, elementId);
  const bgImage = getElementBackgroundForCard(card, elementId);
  const artImage = card?.artImage || 'assets/kagero-art.png';
  const cardTypeId = getCardTypeId(card);
  const usesArtLayer = card?.composition !== 'backgroundSkin' && card?.usesArtLayer !== false && cardTypeId !== 'spell';
  wrap.dataset.elementId = elementId;
  wrap.dataset.cardType = cardTypeId;
  wrap.classList.toggle('card-catalyst', isCatalystCard(card));
  wrap.classList.toggle('card-no-art-layer', !usesArtLayer);
  wrap.style.setProperty('--card-element-color', element?.color || '#5400FF');
  wrap.innerHTML = `
    <img class="card-layer card-bg" src="${bgImage}" alt="fondo" onerror="this.onerror=null;this.src='assets/card-bg-darkness.jpg';">
    ${usesArtLayer ? `<img class="card-layer card-art" src="${artImage}" alt="arte" onerror="this.onerror=null;this.src='assets/invocation-art.png';">` : ''}
    <img class="card-layer card-skin" src="${skinImage}" alt="skin ${element?.label || ''}" onerror="this.onerror=null;this.src='assets/card-skin-darkness.png';">
  `;
  return wrap;
}

function getSpellMiniImage(card) {
  return card?.thumbnailImage
    || card?.spellIcon
    || card?.bgImage
    || card?.artImage
    || card?.tokenImage
    || 'assets/card-types/card-type-spell.svg';
}

function createSpellArtMini(card, className = 'cast-spell-art-mini') {
  const img = document.createElement('img');
  img.className = className;
  img.src = getSpellMiniImage(card);
  img.alt = card?.name || 'Hechizo';
  img.onerror = () => {
    img.onerror = null;
    img.src = 'assets/card-types/card-type-spell.svg';
  };
  return img;
}

function createSpellCompositeMini(card, className = 'cast-spell-composite-mini') {
  const wrap = document.createElement('div');
  wrap.className = className;
  wrap.setAttribute('aria-label', card?.name || 'Hechizo');

  const bg = document.createElement('img');
  bg.className = 'spell-mini-bg';
  bg.src = card?.bgImage || card?.thumbnailImage || getSpellMiniImage(card);
  bg.alt = card?.name || 'Hechizo';
  bg.onerror = () => {
    bg.onerror = null;
    bg.src = getSpellMiniImage(card);
  };
  wrap.appendChild(bg);

  if (card?.skinImage) {
    const skin = document.createElement('img');
    skin.className = 'spell-mini-skin';
    skin.src = card.skinImage;
    skin.alt = '';
    skin.setAttribute('aria-hidden', 'true');
    wrap.appendChild(skin);
  }

  return wrap;
}

function createCastQueueVisual(card, options = {}) {
  const isSpell = getCardTypeId(card) === 'spell';
  if (isSpell) {
    return createSpellCompositeMini(card, 'cast-spell-composite-mini');
  }
  const img = document.createElement('img');
  img.className = 'cast-token-image';
  img.src = card?.tokenImage || card?.artImage || 'assets/invocation-token.png';
  img.alt = card?.name || 'Carta en kasteo';
  return img;
}

function createCastTravelVisual(card, options = {}) {
  const isSpell = getCardTypeId(card) === 'spell';
  if (isSpell) {
    return createSpellCompositeMini(card, 'cast-travel-spell-composite-mini');
  }
  const img = document.createElement('img');
  img.src = card?.tokenImage || card?.artImage || 'assets/invocation-token.png';
  img.alt = card?.name || 'Carta en viaje';
  return img;
}

function createArenaEffectTrackerVisual(zone) {
  if (zone?.type === 'kageNoMichi') {
    const card = CARD_LIBRARY[zone.sourceCardId || 'spellKageNoMichi'];
    if (card) {
      const mini = createSpellArtMini(card, 'arena-effect-spell-art-mini');
      mini.setAttribute('aria-label', card.name || 'Kage no Michi');
      return mini;
    }
  }
  const token = document.createElement('div');
  token.className = 'arena-effect-icon-token';
  token.innerHTML = `<img src="${SMOKE_BOMB_ICON_ASSET}" alt="Bomba de humo">`;
  return token;
}

function openArenaEffectTrackerInfo(zone) {
  if (zone?.type === 'kageNoMichi' && CARD_LIBRARY[zone.sourceCardId || 'spellKageNoMichi']) {
    openCardMetaInfo('power', 'kageNoMichi', CARD_LIBRARY[zone.sourceCardId || 'spellKageNoMichi']);
    return;
  }
  openCardMetaInfo('weapon', 'smokeBomb');
}

function applyArenaTrackerMetaTheme(playerId) {
  if (!els.cardMetaInfoOverlay) return;
  els.cardMetaInfoOverlay.dataset.trackerInfoOpen = '1';
  els.cardMetaInfoOverlay.classList.add('guardian-meta-theme');
  els.cardMetaInfoOverlay.style.setProperty('--meta-theme-color', getPlayerElementColor(playerId));
}

function openSmokeBombStockInfo(playerId, unit) {
  const current = Math.max(0, Number(unit?.smokeBombsLeft ?? 0));
  const maximum = Math.max(current, Number(unit?.smokeBombsMax ?? 3));
  openCardMetaInfo('weapon', 'smokeBomb', CARD_LIBRARY[unit?.cardId] || null, { skipHistory: true });
  applyArenaTrackerMetaTheme(playerId);
  if (els.cardMetaInfoIcon) els.cardMetaInfoIcon.innerHTML = `<img src="${SMOKE_BOMB_ICON_ASSET}" alt="Bomba de humo">`;
  if (els.cardMetaInfoTitle) els.cardMetaInfoTitle.textContent = 'Bombas de humo restantes';
  if (els.cardMetaInfoCategory) els.cardMetaInfoCategory.textContent = `Consumible recargable · ${current} de ${maximum}`;
  if (els.cardMetaInfoBody) els.cardMetaInfoBody.innerHTML = `<p><strong>Resumen:</strong> Este contador muestra cuántas Bombas de humo conserva Naito Sutoka mientras permanece en la arena.</p>${buildTagListHtml(['consumible', 'bomba de humo', 'cargas restantes', 'Naito Sutoka'])}<p><strong>Cantidad actual:</strong> ${current} de ${maximum}.</p><p>La burbuja utiliza el color del dominio del Kaster propietario para distinguirla de los contadores temporales de efectos activos.</p>`;
}

function openSmokeZoneDurationInfo(zone) {
  const remaining = Math.max(0, Number(zone?.phasesRemaining ?? 0));
  const ownerPlayerId = Number(zone?.playerId || LOCAL_PLAYER_ID);
  const sourceUnit = getSmokeSourceUnit(zone);
  const sourceName = zone?.sourceName || (sourceUnit ? CARD_LIBRARY[sourceUnit.cardId]?.name : '') || 'Naito Sutoka';
  openCardMetaInfo('weapon', 'smokeBomb', sourceUnit ? CARD_LIBRARY[sourceUnit.cardId] : null, { skipHistory: true });
  applyArenaTrackerMetaTheme(ownerPlayerId);
  if (els.cardMetaInfoIcon) els.cardMetaInfoIcon.innerHTML = `<img src="${SMOKE_BOMB_ICON_ASSET}" alt="Cortina de humo">`;
  if (els.cardMetaInfoTitle) els.cardMetaInfoTitle.textContent = 'Fases restantes de la cortina de humo';
  if (els.cardMetaInfoCategory) els.cardMetaInfoCategory.textContent = `Efecto temporal · ${remaining} fase${remaining === 1 ? '' : 's'} restante${remaining === 1 ? '' : 's'}`;
  if (els.cardMetaInfoBody) els.cardMetaInfoBody.innerHTML = `<p><strong>Resumen:</strong> Este contador indica cuánto tiempo continuará activa la cortina lanzada por ${sourceName}.</p>${buildTagListHtml(['duración', 'cortina de humo', 'fases restantes', 'efecto temporal'])}<p><strong>Duración actual:</strong> ${remaining} fase${remaining === 1 ? '' : 's'}.</p><p>Al llegar a 0, la zona desaparece y deja de conceder Oculto. La burbuja amarilla identifica que este número es duración y no inventario.</p>`;
}

function bindArenaEffectTrackerInfo(item, zone) {
  if (!item) return;
  item.dataset.infoKind = zone?.type === 'kageNoMichi' ? 'power' : 'weapon';
  item.dataset.infoId = zone?.type === 'kageNoMichi' ? 'kageNoMichi' : 'smokeBomb';
  item.addEventListener('pointerdown', (event) => {
    event.stopPropagation();
  });
  item.addEventListener('click', (event) => {
    event.preventDefault();
    event.stopPropagation();
    event.stopImmediatePropagation?.();
    if (zone?.type === 'kageNoMichi') openArenaEffectTrackerInfo(zone);
    else openSmokeZoneDurationInfo(zone);
  });
}

function renderArenaEffectTrackers() {
  if (!els.arenaEffectTrackers) return;
  mountArenaEffectTrackersForHudMode();
  const fragment = document.createDocumentFragment();

  // Contadores permanentes de consumibles recargables: permanecen mientras
  // la entidad dueña siga en la arena. Su burbuja usa el color de su dominio.
  for (const playerId of [LOCAL_PLAYER_ID, getOpponentId(LOCAL_PLAYER_ID)]) {
    const units = state.players?.[playerId]?.units || [];
    units.forEach(unit => {
      if (!unit || unit.status === 'restoring' || unit.cardId !== 'ninjaNaitoSutoka' || !Number.isFinite(Number(unit.smokeBombsLeft))) return;
      if (Number(playerId) === Number(LOCAL_PLAYER_ID)) return;
      const item = document.createElement('button');
      item.type = 'button';
      item.className = `arena-effect-tracker arena-effect-consumable-stock player-${playerId}`;
      item.style.setProperty('--arena-tracker-domain-color', getPlayerElementColor(playerId));
      item.title = `Bombas de humo restantes: ${Math.max(0, Number(unit.smokeBombsLeft))}`;
      const token = document.createElement('div');
      token.className = 'arena-effect-icon-token';
      token.innerHTML = `<img src="${SMOKE_BOMB_ICON_ASSET}" alt="Bomba de humo">`;
      item.appendChild(token);
      const count = document.createElement('span');
      count.className = 'arena-effect-tracker-count arena-effect-consumable-count';
      count.textContent = String(Math.max(0, Number(unit.smokeBombsLeft)));
      item.appendChild(count);
      item.addEventListener('pointerdown', event => event.stopPropagation());
      item.addEventListener('click', event => {
        event.preventDefault();
        event.stopPropagation();
        openSmokeBombStockInfo(playerId, unit);
      });
      fragment.appendChild(item);
    });
  }

  getActiveDespliegueAnticipadoLinks().forEach(link => {
    const card = CARD_LIBRARY[link.cardId || DESPLIEGUE_ANTICIPADO_CARD_ID];
    const target = getUnitById(Number(link.playerId), link.targetUnitId);
    if (!card || !target) return;
    const item = document.createElement('button');
    item.type = 'button';
    item.className = `arena-effect-tracker arena-effect-linked-spell arena-effect-despliegue player-${link.playerId}`;
    item.title = `${card.name} · vinculado a ${CARD_LIBRARY[target.cardId]?.name || 'Caudillo'}`;
    item.appendChild(createSpellCompositeMini(card, 'arena-effect-spell-card-mini'));
    item.addEventListener('pointerdown', event => event.stopPropagation());
    item.addEventListener('click', event => {
      event.preventDefault();
      event.stopPropagation();
      openCardInfo(card.id, null, null, { source: 'activeSpell', playerId: link.playerId, targetUnitId: link.targetUnitId });
    });
    fragment.appendChild(item);
  });

  getActiveTentorouGroups().forEach(group => {
    const card = CARD_LIBRARY[group.cardId || TENTOROU_CARD_ID] || CARD_LIBRARY[TENTOROU_CARD_ID];
    if (!card) return;
    const item = document.createElement('button');
    item.type = 'button';
    item.className = `arena-effect-tracker arena-effect-linked-spell arena-effect-tentorou player-${group.playerId}`;
    item.title = `${card.name} · ${group.remainingPhases} fase${Number(group.remainingPhases) === 1 ? '' : 's'} restante${Number(group.remainingPhases) === 1 ? '' : 's'}`;
    item.appendChild(createSpellCompositeMini(card, 'arena-effect-spell-card-mini'));
    const count = document.createElement('span');
    count.className = 'arena-effect-tracker-count arena-effect-duration-count';
    count.textContent = String(Math.max(0, Number(group.remainingPhases || 0)));
    item.appendChild(count);
    item.addEventListener('pointerdown', event => event.stopPropagation());
    item.addEventListener('click', event => {
      event.preventDefault();
      event.stopPropagation();
      openCardInfo(card.id, null, null, { source: 'activeSpell', playerId: group.playerId, effectId: group.id });
    });
    fragment.appendChild(item);
  });

  getActiveLongNightGroups().forEach(group => {
    const card = CARD_LIBRARY[group.cardId || LONG_NIGHT_CARD_ID] || CARD_LIBRARY[LONG_NIGHT_CARD_ID];
    if (!card) return;
    const item = document.createElement('button');
    item.type = 'button';
    item.className = `arena-effect-tracker arena-effect-linked-spell arena-effect-long-night player-${group.playerId}`;
    item.title = `${card.name} · ${group.remainingPhases} fase${Number(group.remainingPhases) === 1 ? '' : 's'} restante${Number(group.remainingPhases) === 1 ? '' : 's'}`;
    item.appendChild(createSpellCompositeMini(card, 'arena-effect-spell-card-mini'));
    const count = document.createElement('span');
    count.className = 'arena-effect-tracker-count arena-effect-duration-count';
    count.textContent = String(Math.max(0, Number(group.remainingPhases || 0)));
    item.appendChild(count);
    item.addEventListener('pointerdown', event => event.stopPropagation());
    item.addEventListener('click', event => {
      event.preventDefault();
      event.stopPropagation();
      openCardInfo(card.id, null, null, { source: 'activeSpell', playerId: group.playerId, effectId: group.id });
    });
    fragment.appendChild(item);
  });

  const zones = (Array.isArray(state.smokeZones) ? state.smokeZones : []).slice().sort((a, b) => {
    const at = Number(a.createdAt || 0);
    const bt = Number(b.createdAt || 0);
    return at - bt;
  });
  zones.forEach(zone => {
    const item = document.createElement('button');
    item.type = 'button';
    item.className = `arena-effect-tracker arena-effect-duration arena-effect-${zone.type || 'smoke'}`;
    item.title = `${zone.sourceName || (zone.type === 'kageNoMichi' ? 'Kage no Michi' : 'Bomba de humo')} · ${zone.phasesRemaining} fases restantes`;
    item.appendChild(createArenaEffectTrackerVisual(zone));
    const count = document.createElement('span');
    count.className = 'arena-effect-tracker-count arena-effect-duration-count';
    count.textContent = String(zone.phasesRemaining ?? 0);
    item.appendChild(count);
    bindArenaEffectTrackerInfo(item, zone);
    fragment.appendChild(item);
  });
  els.arenaEffectTrackers.replaceChildren(fragment);
  syncInvocationPanelEffectCount();
}

function createRealtimeResourceLine(playerId, elementId, options = {}) {
  const compact = options.compact === true;
  const track = getRealtimeResourceTrack(playerId, elementId);
  if (!track) return null;
  const element = getElementById(elementId) || ELEMENTS.find(entry => entry.id === elementId) || { id: elementId, label: elementId, color: '#ffffff' };
  const available = countPlayerResourcesByElement(playerId, elementId);
  const maxCapacity = Math.max(1, Number(track.maxCapacity || getRealtimeResourceMaxCapacityForDomainCount(getRealtimeResourcePlayerState(playerId, false)?.elementIds?.length || 1)));
  const capacity = Math.max(0, Math.min(maxCapacity, Number(track.capacity || 0)));
  const isPrimary = getRealtimeResourcePlayerState(playerId, false)?.primaryElementId === elementId;
  const refillIn = getRealtimeResourceCountdown(playerId, elementId, 'refill');
  const growthIn = getRealtimeResourceCountdown(playerId, elementId, 'growth');
  const growthMaxed = capacity >= maxCapacity;

  if (compact) {
    // HUD rival: UNA FILA REAL por dominio. Nunca se mezclan colores en la misma fila.
    const row = document.createElement('div');
    row.className = `rt-resource-rival-line${isPrimary ? ' is-primary' : ''}`;
    row.dataset.elementId = elementId;
    row.style.setProperty('--rt-resource-color', element.color || getDominionPrimaryColor(elementId));

    const identity = document.createElement('span');
    identity.className = 'rt-resource-rival-identity';
    identity.innerHTML = `<img src="${getElementCostIcon(elementId)}" alt="${element.label || elementId}" title="${element.label || elementId}"><strong>${available}/${capacity}</strong>`;
    row.appendChild(identity);

    const slots = document.createElement('div');
    slots.className = 'rt-resource-rival-slots';
    slots.setAttribute('aria-label', `${element.label || elementId}: ${available} disponibles de ${capacity}; máximo ${maxCapacity}`);
    for (let index = 0; index < capacity; index += 1) {
      const charged = index < available;
      const slot = document.createElement('span');
      slot.className = `rt-resource-rival-drop${charged ? ' is-charged' : ' is-spent'}`;
      slot.title = charged ? `${element.label || elementId} disponible` : `${element.label || elementId} consumido · recargando`;
      slot.innerHTML = `<img src="${getElementCostIcon(elementId)}" alt="">`;
      slots.appendChild(slot);
    }
    row.appendChild(slots);
    return row;
  }

  // HUD local: restaurado a la lógica vertical anterior. Solo aparecen tantos
  // espacios como capacidad se haya desbloqueado hasta ese momento.
  const line = document.createElement('div');
  line.className = `rt-resource-column${isPrimary ? ' is-primary' : ''}`;
  line.dataset.elementId = elementId;
  line.style.setProperty('--rt-resource-color', element.color || getDominionPrimaryColor(elementId));

  const head = document.createElement('div');
  head.className = 'rt-resource-column-head';
  head.innerHTML = `<span class="rt-resource-column-identity"><img src="${getElementCostIcon(elementId)}" alt="${element.label || elementId}" title="${element.label || elementId}"><b>${element.label || elementId}</b>${isPrimary ? '<i>PRINCIPAL</i>' : ''}</span><strong>${available}/${capacity}</strong>`;
  line.appendChild(head);

  const slots = document.createElement('div');
  slots.className = 'rt-resource-column-slots';
  slots.setAttribute('aria-label', `${element.label || elementId}: ${available} disponibles de ${capacity}; máximo ${maxCapacity}`);
  for (let index = 0; index < capacity; index += 1) {
    const charged = index < available;
    const slot = document.createElement('span');
    slot.className = `rt-resource-drop${charged ? ' is-charged' : ' is-spent'}`;
    slot.title = charged ? `${element.label || elementId} disponible` : `${element.label || elementId} consumido · recargando`;
    slot.innerHTML = `<img src="${getElementCostIcon(elementId)}" alt="">`;
    slots.appendChild(slot);
  }
  line.appendChild(slots);

  const footer = document.createElement('div');
  footer.className = 'rt-resource-column-foot';
  const refillLabel = available < capacity ? `REC ${refillIn ?? 0}s` : 'REC ✓';
  const growthLabel = growthMaxed ? `MAX ${maxCapacity}` : `+1 ${growthIn ?? 0}s`;
  footer.innerHTML = `<span>${refillLabel}</span><span>${growthLabel}</span>`;
  line.appendChild(footer);
  return line;
}

function renderRealtimeResourcesForPlayer(playerId, container, options = {}) {
  if (!container) return false;
  const rtPlayer = getRealtimeResourcePlayerState(playerId, false);
  if (!rtPlayer) return false;
  const ids = [...(rtPlayer.elementIds || [])];
  container.dataset.rtResourceColumns = String(Math.max(1, ids.length));
  container.dataset.rtResourceLayout = options.compact === true ? 'rival-horizontal-lines' : 'vertical-columns';
  const fragment = document.createDocumentFragment();
  ids.forEach(elementId => {
    const line = createRealtimeResourceLine(playerId, elementId, options);
    if (line) fragment.appendChild(line);
  });
  container.replaceChildren(fragment);
  return true;
}

function renderResources() {
  if (isRealtimePlayStyle() && state?.realtime?.resourceSystem?.initialized) {
    renderRealtimeResourcesForPlayer(LOCAL_PLAYER_ID, els.resourceBar);
    return;
  }
  const resources = sortResourcesForPlayer(localPlayer().resources, LOCAL_PLAYER_ID).filter(resource => !isOpeningElementResourceHidden(resource));
  const fragment = document.createDocumentFragment();
  resources.forEach(res => {
    const token = document.createElement('div');
    token.className = 'orb resource-token';
    token.style.setProperty('--orb-color', res.color);
    token.dataset.type = res.label;
    token.dataset.elementId = res.id;
    token.title = res.label || res.id || 'Elemento';
    token.innerHTML = `<img src="${res.icon || getElementCostIcon(res.id)}" alt="${res.label || res.id || 'Elemento'}">`;
    fragment.appendChild(token);
  });
  els.resourceBar.replaceChildren(fragment);
}



function updateEnemyMiniCastOverflowIndicator() {
  const queue = els.enemyMiniCastQueue;
  const more = els.enemyMiniCastMore;
  if (!queue || !more) return;
  const hasOverflow = queue.scrollWidth > queue.clientWidth + 2;
  const canScrollRight = hasOverflow && queue.scrollLeft < (queue.scrollWidth - queue.clientWidth - 2);
  more.classList.toggle('visible', canScrollRight);
  more.setAttribute('aria-hidden', canScrollRight ? 'false' : 'true');
}

function bindEnemyMiniCastScrollControls() {
  const queue = els.enemyMiniCastQueue;
  const more = els.enemyMiniCastMore;
  if (!queue || queue.dataset.scrollBound === '1') return;
  queue.dataset.scrollBound = '1';
  queue.addEventListener('wheel', event => {
    if (queue.scrollWidth <= queue.clientWidth + 2) return;
    const delta = Math.abs(event.deltaX) > Math.abs(event.deltaY) ? event.deltaX : event.deltaY;
    if (!delta) return;
    event.preventDefault();
    queue.scrollLeft += delta;
    window.requestAnimationFrame(updateEnemyMiniCastOverflowIndicator);
  }, { passive: false });
  queue.addEventListener('scroll', updateEnemyMiniCastOverflowIndicator, { passive: true });
  if (more && more.dataset.scrollBound !== '1') {
    more.dataset.scrollBound = '1';
    more.addEventListener('click', event => {
      event.preventDefault();
      queue.scrollBy({ left: Math.max(42, queue.clientWidth * 0.75), behavior: 'smooth' });
      window.setTimeout(updateEnemyMiniCastOverflowIndicator, 220);
    });
  }
}

const opponentCastQueueModalRuntime = {
  previousFocus: null,
};

function getPublicOpponentInvocationCasts() {
  const enemyId = getEnemyPlayerId(LOCAL_PLAYER_ID);
  const queue = state.players?.[enemyId]?.castQueue || [];
  return queue
    .map((item, queueIndex) => ({ item, queueIndex, card: CARD_LIBRARY[item?.cardId] || null, enemyId }))
    .filter(entry => entry.card && getCardTypeId(entry.card) === 'invocation');
}

function renderOpponentCastQueueModal() {
  const overlay = els.opponentCastQueueOverlay;
  const list = els.opponentCastQueueList;
  if (!overlay || !list) return 0;

  const entries = getPublicOpponentInvocationCasts();
  const timeUnit = isRealtimePlayStyle() ? 's' : 'fases';
  const fragment = document.createDocumentFragment();

  entries.forEach(({ item, queueIndex, card, enemyId }, visibleIndex) => {
    const active = queueIndex === 0;
    const article = document.createElement('article');
    article.className = `opponent-cast-queue-entry ${active ? 'is-active' : 'is-waiting'}`;
    article.dataset.spawnId = item.spawnId || '';
    article.dataset.queuePosition = String(queueIndex + 1);

    const visual = document.createElement('div');
    visual.className = 'opponent-cast-queue-card';
    const cardNode = createCardElement(card, {
      elementIdOverride: item.elementId || getEffectiveCardElementId(card, enemyId),
    });
    cardNode.classList.add('opponent-cast-queue-card-visual');
    visual.appendChild(cardNode);
    article.appendChild(visual);

    const copy = document.createElement('div');
    copy.className = 'opponent-cast-queue-copy';
    const remaining = Math.max(0, Number(item.remaining || 0));
    const status = active ? `KASTEO ACTIVO · ${remaining} ${timeUnit}` : `EN COLA · POSICIÓN ${queueIndex + 1}`;
    const elementId = item.elementId || getEffectiveCardElementId(card, enemyId) || getCardElementId(card) || '';
    copy.innerHTML = `
      <span class="opponent-cast-queue-order">${active ? 'AHORA' : `SIGUE ${Math.max(1, visibleIndex)}`}</span>
      <strong>${card.name || 'Invocación rival'}</strong>
      <div class="opponent-cast-queue-status"><img src="${getElementCostIcon(elementId)}" alt=""><span>${status}</span></div>
    `;
    article.appendChild(copy);
    fragment.appendChild(article);
  });

  list.replaceChildren(fragment);
  list.dataset.count = String(entries.length);
  return entries.length;
}

function openOpponentCastQueueModal(event = null) {
  event?.preventDefault?.();
  event?.stopPropagation?.();
  const overlay = els.opponentCastQueueOverlay;
  if (!overlay) return false;
  const count = renderOpponentCastQueueModal();
  if (!count) return false;

  opponentCastQueueModalRuntime.previousFocus = document.activeElement;
  overlay.classList.add('visible');
  overlay.setAttribute('aria-hidden', 'false');
  els.enemyMiniCastQueue?.setAttribute('aria-expanded', 'true');
  els.enemyMiniCastMore?.setAttribute('aria-expanded', 'true');
  window.requestAnimationFrame(() => {
    window.ROK_LAYOUT_SCALE?.fitVisibleModals?.();
    els.opponentCastQueueCloseBtn?.focus?.({ preventScroll: true });
  });
  return true;
}

function closeOpponentCastQueueModal(options = {}) {
  const overlay = els.opponentCastQueueOverlay;
  if (!overlay?.classList.contains('visible')) return false;
  overlay.classList.remove('visible');
  overlay.setAttribute('aria-hidden', 'true');
  els.enemyMiniCastQueue?.setAttribute('aria-expanded', 'false');
  els.enemyMiniCastMore?.setAttribute('aria-expanded', 'false');
  if (options.restoreFocus !== false && opponentCastQueueModalRuntime.previousFocus?.isConnected) {
    opponentCastQueueModalRuntime.previousFocus.focus?.({ preventScroll: true });
  }
  opponentCastQueueModalRuntime.previousFocus = null;
  return true;
}

function updateEnemyMiniCastOverflowIndicator() {
  const queue = els.enemyMiniCastQueue;
  const more = els.enemyMiniCastMore;
  if (!queue || !more) return;
  const hasOverflow = queue.scrollWidth > queue.clientWidth + 2;
  const invocationCount = getPublicOpponentInvocationCasts().length;
  const canInspect = invocationCount > 0;
  queue.classList.toggle('is-inspectable', canInspect);
  queue.classList.toggle('has-overflow', hasOverflow);
  queue.tabIndex = canInspect ? 0 : -1;
  queue.setAttribute('aria-disabled', canInspect ? 'false' : 'true');
  queue.setAttribute('aria-label', canInspect
    ? `Ampliar ${invocationCount} ${invocationCount === 1 ? 'invocación rival en kasteo' : 'invocaciones rivales en kasteo'}`
    : 'No hay invocaciones rivales en kasteo');
  more.disabled = !canInspect;
  more.classList.toggle('visible', canInspect);
  more.classList.toggle('has-overflow', hasOverflow);
  more.setAttribute('aria-hidden', canInspect ? 'false' : 'true');
}

function bindEnemyMiniCastScrollControls() {
  const queue = els.enemyMiniCastQueue;
  const more = els.enemyMiniCastMore;
  if (!queue || queue.dataset.scrollBound === '1') return;
  queue.dataset.scrollBound = '1';
  queue.addEventListener('wheel', event => {
    if (queue.scrollWidth <= queue.clientWidth + 2) return;
    const delta = Math.abs(event.deltaX) > Math.abs(event.deltaY) ? event.deltaX : event.deltaY;
    if (!delta) return;
    event.preventDefault();
    queue.scrollLeft += delta;
    window.requestAnimationFrame(updateEnemyMiniCastOverflowIndicator);
  }, { passive: false });
  queue.addEventListener('scroll', updateEnemyMiniCastOverflowIndicator, { passive: true });
  queue.addEventListener('click', event => {
    if (queue.getAttribute('aria-disabled') === 'true') return;
    openOpponentCastQueueModal(event);
  });
  queue.addEventListener('keydown', event => {
    if (!['Enter', ' '].includes(event.key) || queue.getAttribute('aria-disabled') === 'true') return;
    openOpponentCastQueueModal(event);
  });
  if (more && more.dataset.scrollBound !== '1') {
    more.dataset.scrollBound = '1';
    more.addEventListener('click', event => {
      openOpponentCastQueueModal(event);
    });
  }
  els.opponentCastQueueCloseBtn?.addEventListener('click', event => {
    event.preventDefault();
    event.stopPropagation();
    closeOpponentCastQueueModal();
  });
  els.opponentCastQueueOverlay?.addEventListener('click', event => {
    if (event.target === els.opponentCastQueueOverlay) closeOpponentCastQueueModal();
  });
  document.addEventListener('keydown', event => {
    if (event.key !== 'Escape' || !els.opponentCastQueueOverlay?.classList.contains('visible')) return;
    event.preventDefault();
    event.stopImmediatePropagation();
    closeOpponentCastQueueModal();
  });
}

function appendEnemyMiniResourceToken(container, resource, count = 1) {
  const token = document.createElement('div');
  token.className = `enemy-mini-orb enemy-mini-resource-token${count > 1 ? ' enemy-mini-resource-group' : ''}`;
  token.dataset.elementId = resource.id || '';
  token.style.setProperty('--orb-color', resource.color);
  token.title = count > 1
    ? `${resource.label || resource.id || 'Elemento rival'} × ${count}`
    : (resource.label || resource.id || 'Elemento rival');
  token.innerHTML = `<img src="${resource.icon || getElementCostIcon(resource.id)}" alt="${resource.label || resource.id || 'Elemento rival'}">${count > 1 ? `<b>×${count}</b>` : ''}`;
  container.appendChild(token);
}

function getEnemyMiniResourceLayoutSignature(ordered, width) {
  const counts = new Map();
  ordered.forEach(resource => {
    const id = String(resource?.id || 'unknown');
    counts.set(id, (counts.get(id) || 0) + 1);
  });
  const composition = Array.from(counts.entries())
    .sort((a, b) => a[0].localeCompare(b[0]))
    .map(([id, count]) => `${id}:${count}`)
    .join('|');
  return `${Math.max(0, Math.round(Number(width || 0)))}::${composition}`;
}

function enemyMiniResourcesNeedGrouping(container, ordered) {
  if (!container || !ordered.length) return false;

  const visibleWidth = Math.max(0, Math.round(container.getBoundingClientRect().width || container.clientWidth || 0));
  const signature = getEnemyMiniResourceLayoutSignature(ordered, visibleWidth);
  if (container.dataset.layoutSignature === signature && container.dataset.layoutGrouped != null) {
    return container.dataset.layoutGrouped === '1';
  }

  // v552 · Nunca se vuelve a pintar el HUD visible primero como elementos sueltos
  // para medirlo. Esa secuencia era la causa del parpadeo: cada renderAll()
  // mostraba un frame sin agrupación y el requestAnimationFrame siguiente lo
  // reconstruía agrupado. La medición se hace ahora con una copia invisible.
  let grouped = container.dataset.layoutGrouped === '1';
  if (visibleWidth > 1 && container.parentElement) {
    const probe = container.cloneNode(false);
    probe.removeAttribute('id');
    probe.removeAttribute('aria-label');
    probe.classList.add('enemy-mini-resources-layout-probe');
    probe.style.setProperty('position', 'absolute', 'important');
    probe.style.setProperty('left', '-100000px', 'important');
    probe.style.setProperty('top', '0', 'important');
    probe.style.setProperty('width', `${visibleWidth}px`, 'important');
    probe.style.setProperty('max-width', `${visibleWidth}px`, 'important');
    probe.style.setProperty('min-width', `${visibleWidth}px`, 'important');
    probe.style.setProperty('visibility', 'hidden', 'important');
    probe.style.setProperty('opacity', '0', 'important');
    probe.style.setProperty('pointer-events', 'none', 'important');
    probe.style.setProperty('contain', 'layout style paint', 'important');

    const probeFragment = document.createDocumentFragment();
    ordered.forEach(resource => appendEnemyMiniResourceToken(probeFragment, resource, 1));
    probe.appendChild(probeFragment);
    container.parentElement.appendChild(probe);
    grouped = probe.scrollWidth > probe.clientWidth + 2;
    probe.remove();
  } else if (container.dataset.layoutGrouped == null) {
    // Si el HUD todavía está oculto/no tiene geometría, usa una decisión estable
    // para reservas grandes y vuelve a medir cuando ya tenga ancho real.
    grouped = ordered.length > 10;
  }

  container.dataset.layoutSignature = signature;
  container.dataset.layoutGrouped = grouped ? '1' : '0';
  return grouped;
}

function renderEnemyMiniResources(enemy, enemyId) {
  const container = els.enemyMiniResources;
  if (!container) return;
  if (isRealtimePlayStyle() && state?.realtime?.resourceSystem?.initialized) {
    renderRealtimeResourcesForPlayer(enemyId, container, { compact: true });
    return;
  }
  const fragment = document.createDocumentFragment();
  const ordered = sortResourcesForPlayer(enemy.resources || [], enemyId).filter(resource => !isOpeningElementResourceHidden(resource));
  const grouped = enemyMiniResourcesNeedGrouping(container, ordered);

  if (!grouped) {
    ordered.forEach(resource => appendEnemyMiniResourceToken(fragment, resource, 1));
    container.replaceChildren(fragment);
    return;
  }

  const groups = new Map();
  ordered.forEach(resource => {
    const id = resource.id || 'unknown';
    const current = groups.get(id) || { resource, count: 0 };
    current.count += 1;
    groups.set(id, current);
  });
  groups.forEach(({ resource, count }) => appendEnemyMiniResourceToken(fragment, resource, count));
  container.replaceChildren(fragment);
}

function renderEnemyMiniHud() {
  if (!els.enemyMiniHud || !els.enemyMiniResources || !els.enemyMiniCastQueue) return;
  const enemyId = getEnemyPlayerId(LOCAL_PLAYER_ID);
  const enemy = state.players[enemyId];
  if (!enemy) return;

  renderEnemyMiniResources(enemy, enemyId);

  const castFragment = document.createDocumentFragment();
  (enemy.castQueue || []).forEach((item, index) => {
    const card = CARD_LIBRARY[item.cardId];
    if (!card) return;
    const isActiveCast = index === 0;
    const div = document.createElement('div');
    div.className = `enemy-mini-cast-item ${isActiveCast ? 'cast-active' : 'cast-waiting'}`;
    div.dataset.spawnId = item.spawnId || '';
    div.dataset.elementId = item.elementId || getEffectiveCardElementId(card, enemyId) || getCardElementId(card) || '';
    div.title = isActiveCast
      ? `${card.name}: kasteo activo · ${item.remaining} ${isRealtimePlayStyle() ? 'segundos' : 'fases'}`
      : `${card.name}: en cola · espera a que termine el kasteo activo`;
    div.appendChild(createCastQueueVisual(card, { elementIdOverride: item.elementId || getEffectiveCardElementId(card, enemyId) }));
    const status = document.createElement('div');
    status.className = 'enemy-mini-cast-status';
    status.innerHTML = `<span class="cast-icon-badge enemy-mini-hourglass cooldown-time-badge">${CAST_ENTRY_ICON_INLINE_SVG}<span class="cast-corner-number enemy-mini-corner-number">${isActiveCast ? item.remaining : 'Q'}</span></span>`;
    div.appendChild(status);
    castFragment.appendChild(div);
  });
  els.enemyMiniCastQueue.replaceChildren(castFragment);

  window.requestAnimationFrame(updateEnemyMiniCastOverflowIndicator);
  const realtimeHasTracks = isRealtimePlayStyle() && Boolean(getRealtimeResourcePlayerState(enemyId, false)?.elementIds?.length);
  els.enemyMiniHud.classList.toggle('empty', !realtimeHasTracks && !(enemy.resources?.length) && !(enemy.castQueue?.length));
}



function finalizeCastIntro(playerId, spawnId) {
  const item = findQueuedItemBySpawn(playerId, spawnId);
  if (!item || item.introDone) return;
  item.justAdded = false;
  item.introDone = true;
  item.introStarted = false;
  item.introEndsAt = 0;
  renderAll();
}

function scheduleCastIntroFinish(playerId, spawnId, duration = 940) {
  const item = findQueuedItemBySpawn(playerId, spawnId);
  if (!item || item.introTimerSet) return;
  item.introTimerSet = true;
  item.introEndsAt = Date.now() + duration;
  window.setTimeout(() => {
    const queued = findQueuedItemBySpawn(playerId, spawnId);
    if (queued) queued.introTimerSet = false;
    finalizeCastIntro(playerId, spawnId);
  }, duration);
}

function renderCastQueue() {
  const queue = localPlayer().castQueue;
  const fragment = document.createDocumentFragment();
  queue.forEach((item, index) => {
    const card = CARD_LIBRARY[item.cardId];
    const isActiveCast = index === 0;
    const div = document.createElement('div');
    div.className = `cast-item ${isActiveCast ? 'cast-active' : 'cast-waiting'}`;
    div.dataset.spawnId = item.spawnId || '';
    div.dataset.playerId = String(LOCAL_PLAYER_ID);
    div.title = isActiveCast
      ? `${card.name}: kasteo activo · ${item.remaining} ${isRealtimePlayStyle() ? 'segundos' : 'fases'}`
      : `${card.name}: en cola · espera a que termine el kasteo activo`;
    div.appendChild(createCastQueueVisual(card, { elementIdOverride: item.elementId || getEffectiveCardElementId(card, LOCAL_PLAYER_ID) }));
    const status = document.createElement('div');
    status.className = 'cast-status';
    status.innerHTML = `<span class="cast-icon-badge big cooldown-time-badge">${CAST_ENTRY_ICON_INLINE_SVG}<span class="cast-corner-number">${isActiveCast ? item.remaining : 'Q'}</span></span>`;
    div.appendChild(status);

    // v506 · La ficha de kasteo siempre puede inspeccionarse, incluso durante
    // la animación inicial. El modal usa el persistentCardState de esta copia,
    // así se puede comprobar Shirahadori y cualquier habilidad aprendida antes
    // de que la invocación termine de entrar a la arena.
    div.classList.add('cast-item-info-clickable');
    div.tabIndex = 0;
    div.setAttribute('role', 'button');
    div.setAttribute('aria-label', `Ver información de ${card?.name || 'carta'} en zona de kasteo`);
    const openQueuedInfo = event => {
      event?.preventDefault?.();
      event?.stopPropagation?.();
      openCardInfo(card.id, null, null, {
        source: 'castQueue',
        playerId: LOCAL_PLAYER_ID,
        spawnId: item.spawnId || '',
      });
    };
    div.addEventListener('click', openQueuedInfo);
    div.addEventListener('keydown', event => {
      if (event.key !== 'Enter' && event.key !== ' ') return;
      openQueuedInfo(event);
    });

    const introExpired = Boolean(item.introEndsAt && Date.now() >= item.introEndsAt);
    if (introExpired) {
      item.justAdded = false;
      item.introDone = true;
      item.introStarted = false;
      item.introEndsAt = 0;
    }

    if (item.justAdded && !item.introDone && !item.introStarted) {
      item.introStarted = true;
      div.classList.add('entering', 'intro-locked');
      scheduleCastIntroFinish(LOCAL_PLAYER_ID, item.spawnId, 940);
      div.addEventListener('animationend', (event) => {
        if (event.animationName !== 'kastDropLanding') return;
        finalizeCastIntro(LOCAL_PLAYER_ID, item.spawnId);
      }, { once: true });
    } else if (!item.introDone) {
      // Si otro render ocurre mientras la animación aún está viva, NO se reinicia.
      // La ficha queda bloqueada hasta que el timer original finalice la intro.
      div.classList.add('intro-locked');
    } else {
      item.justAdded = false;
      item.introDone = true;
      item.introStarted = false;
      attachLinkHoverHandlers(div, item.spawnId, state.activePlayer, 'queue');
    }

    fragment.appendChild(div);
  });
  els.castQueue.replaceChildren(fragment);
}

function getArenaCellCache() {
  if (ROK_ARENA_CELL_CACHE.length
    && ROK_ARENA_CELL_CACHE.every(entry => entry?.node?.isConnected)) {
    return ROK_ARENA_CELL_CACHE;
  }
  ROK_ARENA_CELL_CACHE = Array.from(document.querySelectorAll('.cell')).map(node => ({
    node,
    row: Number(node.dataset.row),
    col: Number(node.dataset.col),
  }));
  return ROK_ARENA_CELL_CACHE;
}

function renderGridHighlights() {
  const castingActive = Boolean(state.pendingCard);
  els.enemyGrid.classList.toggle('casting-active', castingActive);
  els.allyGrid.classList.toggle('casting-active', castingActive);
  getArenaCellCache().forEach(({ node: cell, row, col }) => {
    cell.classList.remove('caster-zone', 'selected-place', 'occupied');
    const pendingCard = state.pendingCard ? CARD_LIBRARY[state.pendingCard.cardId] : null;
    const blockedForCast = isCastPlacementBlockedForPlayer(row, col, state.pendingCard ? LOCAL_PLAYER_ID : null);
    if (blockedForCast && !isNonCollidingSpellCast(pendingCard)) cell.classList.add('occupied');
    if (state.pendingCard) {
      const caster = currentPlayer().caster;
      const isAround = Math.abs(row - caster.row) <= 1 && Math.abs(col - caster.col) <= 1 && !(row === caster.row && col === caster.col);
      if (isAround && canUseCastReferenceCell(pendingCard, row, col, LOCAL_PLAYER_ID)) cell.classList.add('caster-zone');
    }
    if (state.pendingPlacement && state.pendingPlacement.row === row && state.pendingPlacement.col === col) {
      cell.classList.add('selected-place');
    }
  });
}

function renderSpawnMarkers() {
  if (!els.spawnMarkersLayer) return;
  const fragment = document.createDocumentFragment();
  for (const playerId of [1, 2]) {
    const player = state.players[playerId];
    (player.spawnMarkers || []).forEach(marker => {
      const card = CARD_LIBRARY[marker.cardId];
      if (!card || card.type !== 'invocation') return;
      const pos = cellCenter(marker.row, marker.col);
      const holder = document.createElement('div');
      holder.className = 'spawn-marker';
      holder.dataset.spawnId = marker.id;
      holder.dataset.playerId = String(playerId);
      holder.style.left = `${pos.x}%`;
      holder.style.top = `${pos.y}%`;
      holder.style.zIndex = String(100 + marker.row);
      const element = getElementById(marker.elementId || getEffectiveCardElementId(card, playerId));
      holder.dataset.elementId = element?.id || '';
      holder.style.setProperty('--marker-glow', element?.color || '#ffffff');
      holder.title = `${card.name} · Punto de respawn en ${coordLabel(marker.row, marker.col)}`;
      if (isRealtimePlayStyle()) {
        holder.classList.add('realtime-pass-through-nexus');
        holder.removeAttribute('tabindex');
        holder.removeAttribute('role');
        holder.removeAttribute('aria-label');
        holder.setAttribute('aria-hidden', 'true');
      }
      const mini = createCardElement(card, { elementIdOverride: element?.id });
      mini.classList.add('mini');
      holder.appendChild(mini);
      const queued = findQueuedItemBySpawn(playerId, marker.id);
      if (queued) {
        holder.classList.add('waiting');
        if (!isCastIntroReady(playerId, marker.id)) holder.classList.add('intro-locked');
        const status = document.createElement('div');
        status.className = 'spawn-status';
        status.innerHTML = `<span class="cast-icon-badge big cooldown-time-badge">${CAST_ENTRY_ICON_INLINE_SVG}<span class="cast-corner-number">${queued.remaining}</span></span>`;
        holder.appendChild(status);
      }
      attachLinkHoverHandlers(holder, marker.id, playerId, 'marker');
      fragment.appendChild(holder);
    });
  }
  els.spawnMarkersLayer.replaceChildren(fragment);
}

function renderMoveOptions() {
  if (!els.moveOptionsLayer) return;
  const fragment = document.createDocumentFragment();
  try {


  if (['umbralFugazPortalA','umbralFugazPortalB'].includes(String(state.pendingPowerAction?.kind || ''))) {
    const pending = state.pendingPowerAction;
    const excluded = pending.kind === 'umbralFugazPortalB' ? pending.portalA : null;
    getUmbralFugazPlacementCells(Number(pending.playerId), excluded).forEach(opt => {
      const pos = cellCenter(opt.row, opt.col);
      const size = getBoardCellSizePercent(opt.row);
      const div = document.createElement('button');
      div.type = 'button';
      div.className = `move-option move-option-power umbral-fugaz-target ${pending.kind === 'umbralFugazPortalA' ? 'portal-a' : 'portal-b'}`;
      div.dataset.umbralRow = String(opt.row);
      div.dataset.umbralCol = String(opt.col);
      div.style.left = `${pos.x}%`; div.style.top = `${pos.y}%`; div.style.width = `${size.width}%`; div.style.height = `${size.height}%`;
      div.title = `Umbral Fugaz · ${pending.kind === 'umbralFugazPortalA' ? 'Portal A' : 'Portal B'} en ${coordLabel(opt.row,opt.col)}`;
      div.innerHTML = `<span class="umbral-fugaz-target-glyph">${pending.kind === 'umbralFugazPortalA' ? 'A' : 'B'}</span>`;
      div.addEventListener('click', event => { event.preventDefault(); event.stopPropagation(); resolveUmbralFugazPortalTarget(opt.row, opt.col); });
      fragment.appendChild(div);
    });
    if (pending.portalA) {
      const pos = cellCenter(Number(pending.portalA.row), Number(pending.portalA.col));
      const size = getBoardCellSizePercent(Number(pending.portalA.row));
      const marker = document.createElement('span');
      marker.className = 'umbral-fugaz-selected-marker';
      marker.style.left = `${pos.x}%`; marker.style.top = `${pos.y}%`; marker.style.width = `${size.width}%`; marker.style.height = `${size.height}%`;
      marker.textContent = 'A'; fragment.appendChild(marker);
    }
    els.moveOptionsLayer.replaceChildren(fragment);
    return;
  }

  if (state.pendingPowerAction?.kind === 'emboscadaDestination') {
    const pending = state.pendingPowerAction;
    const index = Number(pending.currentIndex || 0);
    const unitId = pending.selectedUnitIds?.[index];
    const unit = getUnitById(Number(pending.playerId), unitId);
    if (!unit) { cancelEmboscadaTargeting('Una invocación seleccionada dejó de estar disponible.'); return; }
    getEmboscadaDestinationCells(Number(pending.playerId), pending).forEach(opt => {
      const pos = cellCenter(opt.row, opt.col);
      const size = getBoardCellSizePercent(opt.row);
      const div = document.createElement('button');
      div.type = 'button';
      div.className = 'move-option move-option-tactica-guerra move-option-emboscada';
      div.style.left = `${pos.x}%`; div.style.top = `${pos.y}%`; div.style.width = `${size.width}%`; div.style.height = `${size.height}%`;
      div.title = `Emboscada · nexo ${index + 1}/${pending.selectedUnitIds.length} en ${coordLabel(opt.row,opt.col)}`;
      div.innerHTML = '<span class="tactica-guerra-target-glyph">✦</span>';
      div.addEventListener('click', async event => { event.stopPropagation(); await resolveEmboscadaDestination(Number(pending.playerId), opt.row, opt.col); });
      fragment.appendChild(div);
    });
    return;
  }

  if (state.pendingPowerAction?.kind === 'tacticaGuerraDestination') {
    const pending = state.pendingPowerAction;
    const unit = getTacticaGuerraCurrentUnit(pending);
    if (!unit) {
      cancelTacticaGuerraTargeting('La invocación seleccionada dejó de estar disponible.');
      return;
    }
    getTacticaGuerraDestinationCells(Number(pending.playerId), unit, pending).forEach(opt => {
      const pos = cellCenter(opt.row, opt.col);
      const size = getBoardCellSizePercent(opt.row);
      const div = document.createElement('button');
      div.type = 'button';
      div.className = 'move-option move-option-tactica-guerra';
      div.style.left = `${pos.x}%`;
      div.style.top = `${pos.y}%`;
      div.style.width = `${size.width}%`;
      div.style.height = `${size.height}%`;
      div.title = `Táctica de guerra · colocar nexo ${Number(pending.currentIndex || 0) + 1}/${pending.selectedUnitIds.length} en ${coordLabel(opt.row, opt.col)}`;
      div.innerHTML = '<span class="tactica-guerra-target-glyph">✦</span>';
      div.addEventListener('click', async event => {
        event.preventDefault();
        event.stopPropagation();
        await resolveTacticaGuerraDestination(Number(pending.playerId), opt.row, opt.col);
      });
      fragment.appendChild(div);
    });
    return;
  }

  if (state.pendingTokugawaReposition) {
    const pending = state.pendingTokugawaReposition;
    const unit = getUnitById(pending.playerId, pending.unitId);
    const options = getTokugawaRepositionCells(pending.playerId, unit);
    options.forEach(opt => {
      const pos = cellCenter(opt.row, opt.col);
      const size = getBoardCellSizePercent(opt.row);
      const div = document.createElement('button');
      div.type = 'button';
      div.className = 'move-option move-option-tokugawa';
      div.style.left = `${pos.x}%`;
      div.style.top = `${pos.y}%`;
      div.style.width = `${size.width}%`;
      div.style.height = `${size.height}%`;
      div.title = `Trasladar nexo a ${coordLabel(opt.row, opt.col)}`;
      div.innerHTML = '<span class="tokugawa-target-glyph">✦</span>';
      div.addEventListener('click', async event => {
        event.stopPropagation();
        await executeTokugawaReposition(opt.row, opt.col);
      });
      fragment.appendChild(div);
    });
    return;
  }

  if (state.pendingPowerAction?.kind === 'cargaRealLocation') {
    for (let row = 0; row < 18; row += 1) {
      for (let col = 0; col < 9; col += 1) {
        const pos = cellCenter(row, col);
        const size = getBoardCellSizePercent(row);
        const button = document.createElement('button');
        button.type = 'button';
        button.className = 'move-option carga-real-location-cell';
        button.style.left = `${pos.x}%`;
        button.style.top = `${pos.y}%`;
        button.style.width = `${size.width}%`;
        button.style.height = `${size.height}%`;
        button.title = `Carga Real · franja desde la columna ${getCargaRealBandStartCol(col) + 1}`;
        button.addEventListener('mouseenter', () => previewCargaRealBandAtColumn(col));
        button.addEventListener('mouseleave', clearCargaRealBandPreview);
        button.addEventListener('focus', () => previewCargaRealBandAtColumn(col));
        button.addEventListener('blur', clearCargaRealBandPreview);
        button.addEventListener('click', event => {
          event.preventDefault();
          event.stopPropagation();
          resolveCargaRealLocation(LOCAL_PLAYER_ID, row, col);
        });
        fragment.appendChild(button);
      }
    }
    return;
  }

  if (['kouutenLocation', 'kouutenRecastLocation'].includes(state.pendingPowerAction?.kind)) {
    for (let row = 0; row < 18; row += 1) {
      for (let col = 0; col < 9; col += 1) {
        const pos = cellCenter(row, col);
        const size = getBoardCellSizePercent(row);
        const button = document.createElement('button');
        button.type = 'button';
        button.className = 'move-option kouuten-location-cell';
        button.style.left = `${pos.x}%`;
        button.style.top = `${pos.y}%`;
        button.style.width = `${size.width}%`;
        button.style.height = `${size.height}%`;
        button.title = 'Kouuten · seleccionar área';
        button.addEventListener('mouseenter', () => previewKouutenAreaAt(row, col));
        button.addEventListener('mouseleave', clearKouutenPreview);
        button.addEventListener('focus', () => previewKouutenAreaAt(row, col));
        button.addEventListener('blur', clearKouutenPreview);
        button.addEventListener('click', event => {
          event.preventDefault();
          event.stopPropagation();
          resolveKouutenLocation(LOCAL_PLAYER_ID, row, col);
        });
        fragment.appendChild(button);
      }
    }
    return;
  }


  if (state.pendingPowerAction?.kind === 'gurenGanLocation') {
    for (let row = 0; row < 18; row += 1) {
      for (let col = 0; col < 9; col += 1) {
        const pos = cellCenter(row, col);
        const size = getBoardCellSizePercent(row);
        const button = document.createElement('button');
        button.type = 'button';
        button.className = 'move-option guren-gan-location-cell';
        button.style.left = `${pos.x}%`;
        button.style.top = `${pos.y}%`;
        button.style.width = `${size.width}%`;
        button.style.height = `${size.height}%`;
        button.title = 'Guren Gan · seleccionar centro del impacto';
        button.addEventListener('mouseenter', () => previewGurenGanAreaAt(row, col));
        button.addEventListener('mouseleave', clearGurenGanPreview);
        button.addEventListener('focus', () => previewGurenGanAreaAt(row, col));
        button.addEventListener('blur', clearGurenGanPreview);
        button.addEventListener('click', event => {
          event.preventDefault();
          event.stopPropagation();
          resolveGurenGanLocation(LOCAL_PLAYER_ID, row, col);
        });
        fragment.appendChild(button);
      }
    }
    return;
  }

  if (state.pendingPowerAction?.kind === 'farolEnlazadoCircle') {
    const pending = state.pendingPowerAction;
    const sourceUnit = getUnitById(Number(pending.playerId), pending.unitId);
    if (!sourceUnit || !unitCanActivateFarolEnlazado(Number(pending.playerId), sourceUnit)) {
      cancelFarolEnlazadoTargeting('Farol Enlazado se canceló porque la Farolera dejó de estar disponible.');
      return;
    }
    getFarolCirclePlacementCells(Number(pending.playerId), sourceUnit).forEach(opt => {
      const pos = cellCenter(opt.row, opt.col);
      const size = getBoardCellSizePercent(opt.row);
      const div = document.createElement('button');
      div.type = 'button';
      div.className = 'move-option move-option-power farol-circle-target';
      div.style.left = `${pos.x}%`;
      div.style.top = `${pos.y}%`;
      div.style.width = `${size.width}%`;
      div.style.height = `${size.height}%`;
      div.title = `Farol Enlazado · fijar círculo en ${coordLabel(opt.row, opt.col)}`;
      div.innerHTML = '<span class="farol-lantern-target-glyph">◎</span>';
      div.addEventListener('click', event => {
        event.preventDefault();
        event.stopPropagation();
        resolveFarolEnlazadoCircleTarget(Number(pending.playerId), pending.unitId, opt.row, opt.col);
      });
      fragment.appendChild(div);
    });
    return;
  }

  if (state.pendingPowerAction?.kind === 'farolEnlazadoLamp') {
    const pending = state.pendingPowerAction;
    const sourceUnit = getUnitById(Number(pending.playerId), pending.unitId);
    if (!sourceUnit || !unitCanActivateFarolEnlazado(Number(pending.playerId), sourceUnit)) {
      cancelFarolEnlazadoTargeting('Farol Enlazado se canceló porque la Farolera dejó de estar disponible.');
      return;
    }
    getFarolLanternDestinationCells(Number(pending.playerId), sourceUnit).forEach(opt => {
      const pos = cellCenter(opt.row, opt.col);
      const size = getBoardCellSizePercent(opt.row);
      const div = document.createElement('button');
      div.type = 'button';
      div.className = 'move-option move-option-power farol-lantern-target';
      div.style.left = `${pos.x}%`;
      div.style.top = `${pos.y}%`;
      div.style.width = `${size.width}%`;
      div.style.height = `${size.height}%`;
      div.title = `Farol Enlazado · lanzar lámpara en ${coordLabel(opt.row, opt.col)}`;
      div.innerHTML = '<span class="farol-lantern-target-glyph">✦</span>';
      div.addEventListener('click', event => {
        event.preventDefault();
        event.stopPropagation();
        resolveFarolEnlazadoLamp(Number(pending.playerId), pending.unitId, opt.row, opt.col);
      });
      fragment.appendChild(div);
    });
    return;
  }

  if (['despliegueAnticipadoTarget', 'shirahadoriAbilityTarget'].includes(state.pendingPowerAction?.kind)) {
    // Estas selecciones se realizan directamente sobre las fichas válidas con foil y punto luminoso.
    // No se dibujan cuadros ni glifos encima de las casillas.
    return;
  }

  if (state.pendingPowerAction?.kind === 'minokageShippuUgachi') {
    const pending = state.pendingPowerAction;
    const sourceUnit = getUnitById(pending.playerId, pending.unitId);
    if (!sourceUnit || !unitCanActivateMinokageShippu(pending.playerId, sourceUnit)) {
      cancelMinokagePowerTargeting('Shippū Ugachi ya no está disponible.');
      return;
    }
    getMinokagePowerTargets(pending.playerId, sourceUnit).forEach(target => {
      const pos = cellCenter(target.row, target.col);
      const size = getBoardCellSizePercent(target.row);
      const div = document.createElement('button');
      div.type = 'button';
      div.className = 'move-option move-option-power minokage-power-target';
      div.style.left = `${pos.x}%`;
      div.style.top = `${pos.y}%`;
      div.style.width = `${size.width}%`;
      div.style.height = `${size.height}%`;
      div.title = `Shippū Ugachi contra ${getQuickReactionTargetLabel(target)}`;
      div.innerHTML = '<span class="minokage-power-target-glyph">✦</span>';
      div.addEventListener('click', event => {
        event.preventDefault();
        event.stopPropagation();
        void resolveMinokagePowerTarget(pending.playerId, pending.unitId, target);
      });
      fragment.appendChild(div);
    });
    return;
  }

  if (state.pendingPowerAction?.kind === 'maerynDominationTarget') {
    const pending = state.pendingPowerAction;
    const sourceUnit = getUnitById(pending.playerId, pending.unitId);
    if (!sourceUnit || sourceUnit.status === 'restoring' || !unitCanActivateMaerynDomination(pending.playerId, sourceUnit)) {
      cancelMaerynDominationTargeting('Dominación Mental ya no está disponible.');
      return;
    }
    getMaerynDominationTargets(pending.playerId, sourceUnit).forEach(targetUnit => {
      const pos = cellCenter(targetUnit.row, targetUnit.col);
      const size = getBoardCellSizePercent(targetUnit.row);
      const div = document.createElement('button');
      div.type = 'button';
      div.className = 'move-option move-option-power maeryn-domination-target';
      div.style.left = `${pos.x}%`;
      div.style.top = `${pos.y}%`;
      div.style.width = `${size.width}%`;
      div.style.height = `${size.height}%`;
      div.title = `Dominación Mental sobre ${CARD_LIBRARY[targetUnit.cardId]?.name || 'Invocación'}`;
      div.innerHTML = '<span class="maeryn-domination-target-glyph">◉</span>';
      div.addEventListener('click', event => {
        event.preventDefault();
        event.stopPropagation();
        resolveMaerynDomination(pending.playerId, pending.unitId, targetUnit.owner, targetUnit.id);
      });
      fragment.appendChild(div);
    });
    return;
  }

  if (state.pendingPowerAction?.kind === 'seyranDistorsionTarget') {
    const pending = state.pendingPowerAction;
    const sourceUnit = getUnitById(pending.playerId, pending.unitId);
    if (!sourceUnit || sourceUnit.status === 'restoring' || !unitCanActivateSeyranDistortion(pending.playerId, sourceUnit)) {
      cancelSeyranDistortionTargeting('Distorsión Espacial ya no está disponible.');
      return;
    }
    getSeyranDistortionTargets(pending.playerId, sourceUnit).forEach(targetUnit => {
      const pos = cellCenter(targetUnit.row, targetUnit.col);
      const size = getBoardCellSizePercent(targetUnit.row);
      const div = document.createElement('button');
      div.type = 'button';
      const targetRelation = Number(targetUnit.owner) === Number(pending.playerId) ? 'ally' : 'enemy';
      div.className = `move-option move-option-power seyran-distortion-target seyran-distortion-target-${targetRelation}`;
      div.dataset.relation = targetRelation;
      div.style.left = `${pos.x}%`;
      div.style.top = `${pos.y}%`;
      div.style.width = `${size.width}%`;
      div.style.height = `${size.height}%`;
      div.title = `Distorsión Espacial · ${targetRelation === 'ally' ? 'ALIADA' : 'RIVAL'} · ${CARD_LIBRARY[targetUnit.cardId]?.name || 'Invocación'}`;
      div.innerHTML = `<span class="seyran-distortion-target-glyph">${targetRelation === 'ally' ? 'A' : 'R'}</span>`;
      div.addEventListener('click', event => {
        event.preventDefault();
        event.stopPropagation();
        openSeyranDistortionChoice(pending.playerId, pending.unitId, targetUnit.owner, targetUnit.id);
      });
      fragment.appendChild(div);
    });
    return;
  }

  if (state.pendingPowerAction?.kind === 'kaguyaChargedShot') {
    const pending = state.pendingPowerAction;
    const sourceUnit = getUnitById(pending.playerId, pending.unitId);
    if (!sourceUnit || sourceUnit.status === 'restoring' || !sourceUnit.kaguyaChargedShotPrimed) {
      cancelKaguyaChargedShotTargeting('Disparo energizado ya no está disponible.');
      return;
    }
    getKaguyaChargedShotTargets(pending.playerId, sourceUnit).forEach(target => {
      const pos = cellCenter(target.row, target.col);
      const size = getBoardCellSizePercent(target.row);
      const div = document.createElement('button');
      div.type = 'button';
      div.className = 'move-option move-option-power kaguya-power-target';
      div.style.left = `${pos.x}%`;
      div.style.top = `${pos.y}%`;
      div.style.width = `${size.width}%`;
      div.style.height = `${size.height}%`;
      div.title = `Disparo energizado contra ${getQuickReactionTargetLabel(target)}`;
      div.innerHTML = '<span class="yasugana-power-target-glyph">➤</span>';
      div.addEventListener('click', event => {
        event.preventDefault();
        event.stopPropagation();
        void resolveKaguyaChargedShotTarget(pending.playerId, pending.unitId, target);
      });
      fragment.appendChild(div);
    });
    return;
  }

  if (state.pendingPowerAction?.kind === 'kurayamiMark') {
    const pending = state.pendingPowerAction;
    const sourceUnit = getUnitById(pending.playerId, pending.unitId);
    if (!sourceUnit || sourceUnit.status === 'restoring') {
      state.pendingPowerAction = null;
      clearCombatMenus();
      return;
    }
    getKurayamiPowerTargets(pending.playerId, sourceUnit).forEach(targetUnit => {
      const pos = cellCenter(targetUnit.row, targetUnit.col);
      const size = getBoardCellSizePercent(targetUnit.row);
      const div = document.createElement('button');
      div.type = 'button';
      div.className = 'move-option move-option-power kurayami-power-target';
      div.style.left = `${pos.x}%`;
      div.style.top = `${pos.y}%`;
      div.style.width = `${size.width}%`;
      div.style.height = `${size.height}%`;
      div.title = `Marcar a ${CARD_LIBRARY[targetUnit.cardId]?.name || 'la invocación'}`;
      div.innerHTML = '<span class="yasugana-power-target-glyph">◆</span>';
      div.addEventListener('click', event => {
        event.stopPropagation();
        resolveKurayamiPowerTarget(pending.playerId, pending.unitId, targetUnit.owner, targetUnit.id);
      });
      fragment.appendChild(div);
    });
    return;
  }

  if ((state.pendingPowerAction?.kind === 'yasuganaBlindness' || state.pendingPowerAction?.kind === 'yasuganaVigilia') && state.pendingPowerAction?.selectionMode === 'board') {
    const pending = state.pendingPowerAction;
    const sourceUnit = getUnitById(pending.playerId, pending.unitId);
    if (!sourceUnit || sourceUnit.status === 'restoring') {
      state.pendingPowerAction = null;
      clearCombatMenus();
      return;
    }
    const targets = pending.kind === 'yasuganaBlindness'
      ? getYasuganaBlindnessTargets(pending.playerId, sourceUnit)
      : getYasuganaVigiliaTargets(pending.playerId, sourceUnit);
    targets.forEach(targetUnit => {
      const pos = cellCenter(targetUnit.row, targetUnit.col);
      const size = getBoardCellSizePercent(targetUnit.row);
      const div = document.createElement('button');
      div.type = 'button';
      div.className = 'move-option move-option-power yasugana-power-target';
      div.style.left = `${pos.x}%`;
      div.style.top = `${pos.y}%`;
      div.style.width = `${size.width}%`;
      div.style.height = `${size.height}%`;
      div.title = pending.kind === 'yasuganaBlindness' ? 'Aplicar Ceguera' : 'Enseñar Vigilia';
      div.innerHTML = `<span class="yasugana-power-target-glyph">${pending.kind === 'yasuganaBlindness' ? '◉' : '✦'}</span>`;
      div.addEventListener('click', event => {
        event.stopPropagation();
        resolveYasuganaPowerTarget(pending.playerId, pending.unitId, targetUnit.owner, targetUnit.id, pending.kind);
      });
      fragment.appendChild(div);
    });
    return;
  }

  if (state.pendingPowerAction?.kind === 'gioshoninSupply') {
    const pending = state.pendingPowerAction;
    const sourceUnit = getUnitById(pending.playerId, pending.unitId);
    if (!sourceUnit || sourceUnit.status === 'restoring' || !unitCanActivateGioshoninSupply(pending.playerId, sourceUnit)) {
      state.pendingPowerAction = null;
      hideGioshoninSupplyModal();
      clearCombatMenus();
      return;
    }

    const auraCells = [];
    for (let row = 0; row < 18; row++) {
      for (let col = 0; col < 9; col++) {
        if (!isInside(row, col)) continue;
        if (ringDistance(sourceUnit.row, sourceUnit.col, row, col) <= 2) auraCells.push({ row, col });
      }
    }
    auraCells.forEach(cell => {
      const pos = cellCenter(cell.row, cell.col);
      const size = getBoardCellSizePercent(cell.row);
      const aura = document.createElement('div');
      aura.className = 'move-option gioshonin-supply-aura-cell';
      aura.style.left = `${pos.x}%`;
      aura.style.top = `${pos.y}%`;
      aura.style.width = `${size.width}%`;
      aura.style.height = `${size.height}%`;
      aura.setAttribute('aria-hidden', 'true');
      fragment.appendChild(aura);
    });

    return;
  }

  if (state.pendingPowerAction?.kind === 'smokeBomb') {
    const unit = getUnitById(state.pendingPowerAction.playerId, state.pendingPowerAction.unitId);
    const power = getPowerDefinitionForUnit(state.pendingPowerAction.playerId, unit);
    const options = unit && power ? getCellsInRadius(unit.row, unit.col, Number(power.throwRange ?? 3), true) : [];
    options.forEach(opt => {
      const pos = cellCenter(opt.row, opt.col);
      const size = getBoardCellSizePercent(opt.row);
      const div = document.createElement('button');
      div.type = 'button';
      div.className = 'move-option move-option-power';
      div.style.left = `${pos.x}%`;
      div.style.top = `${pos.y}%`;
      div.style.width = `${size.width}%`;
      div.style.height = `${size.height}%`;
      div.title = `Lanzar bomba de humo en ${coordLabel(opt.row, opt.col)}`;
      div.dataset.smokeBombTarget = 'true';
      div.addEventListener('click', (event) => {
        event.stopPropagation();
        resolveSmokeBombAt(opt.row, opt.col);
      });
      fragment.appendChild(div);
    });
    return;
  }

  const semiOptions = getSemiAutoReachableMoveOptions();
  if (semiOptions.length) {
    semiOptions.forEach(opt => {
      const pos = cellCenter(opt.row, opt.col);
      const size = getBoardCellSizePercent(opt.row);
      const div = document.createElement('button');
      div.type = 'button';
      div.className = `move-option move-option-semiauto${opt.dist === 1 ? ' move-option-semiauto-step' : ''}`;
      div.style.left = `${pos.x}%`;
      div.style.top = `${pos.y}%`;
      div.style.width = `${size.width}%`;
      div.style.height = `${size.height}%`;
      div.title = `Casilla alcanzable: ${coordLabel(opt.row, opt.col)} · ${opt.dist} paso${opt.dist === 1 ? '' : 's'}`;
      div.innerHTML = `<span class="move-option-semiauto-dot">${opt.dist}</span>`;
      div.addEventListener('click', async (event) => {
        event.stopPropagation();
        await executeSemiAutoMovementTo(opt.row, opt.col);
      });
      fragment.appendChild(div);
    });
    return;
  }

  const options = getSelectedMoverOptions();
  options.forEach(opt => {
    const pos = cellCenter(opt.row, opt.col);
    const arrow = MOVE_ARROW_BY_DELTA[`${opt.dr},${opt.dc}`];
    const size = getBoardCellSizePercent(opt.row);
    const div = document.createElement('button');
    div.type = 'button';
    div.className = 'move-option';
    div.style.left = `${pos.x}%`;
    div.style.top = `${pos.y}%`;
    div.style.width = `${size.width}%`;
    div.style.height = `${size.height}%`;
    div.title = `Mover a ${coordLabel(opt.row, opt.col)}`;
    div.innerHTML = `<img src="${arrow}" alt="Mover a ${coordLabel(opt.row, opt.col)}">`;
    div.addEventListener('click', (event) => {
      event.stopPropagation();
      tryMoveSelectedTo(opt.row, opt.col);
    });
    fragment.appendChild(div);
  });
  } finally {
    els.moveOptionsLayer.replaceChildren(fragment);
  }
}


function renderSmokeZones() {
  if (!els.smokeZonesLayer) return;

  const zones = Array.isArray(state.smokeZones) ? state.smokeZones : [];
  const existing = new Map();
  Array.from(els.smokeZonesLayer.children).forEach(node => {
    if (node?.dataset?.smokeKey) existing.set(node.dataset.smokeKey, node);
  });
  const markerLayer = els.smokeBombMarkersLayer || els.smokeZonesLayer;
  const existingMarkers = new Map();
  Array.from(markerLayer.children).forEach(node => {
    if (node?.dataset?.smokeMarkerKey) existingMarkers.set(node.dataset.smokeMarkerKey, node);
  });
  const liveKeys = new Set();
  const liveMarkerKeys = new Set();

  const ensureSmokeNode = (key, className, init = null) => {
    let node = existing.get(key);
    if (!node) {
      node = document.createElement('div');
      node.className = className;
      node.dataset.smokeKey = key;
      if (init) init(node);
      els.smokeZonesLayer.appendChild(node);
    }
    liveKeys.add(key);
    return node;
  };

  const ensureSmokeMarkerNode = (key, className, init = null) => {
    let node = existingMarkers.get(key);
    if (!node) {
      node = document.createElement('div');
      node.className = className;
      node.dataset.smokeMarkerKey = key;
      if (init) init(node);
      markerLayer.appendChild(node);
    }
    liveMarkerKeys.add(key);
    return node;
  };

  for (const zone of zones) {
    const radius = zone.radius ?? 3;
    if (!Array.isArray(zone.hazeCells) || !zone.hazeCells.length) {
      zone.hazeCells = zone.type === 'kageNoMichi'
        ? buildKageNoMichiPathCells(zone.playerId)
        : buildSmokeZoneHazeCells(zone.row, zone.col, radius);
    }

    for (const cell of zone.hazeCells) {
      if (isCellProtectedByGuardianAura(cell.row, cell.col, zone.playerId) || isCellRevealedByEnemyCelestialLamp(cell.row, cell.col, zone.playerId)) continue;
      const pos = cellCenter(cell.row, cell.col);
      const size = getBoardCellSizePercent(cell.row);
      const key = `${zone.id}_haze_${cell.row}_${cell.col}`;
      const haze = ensureSmokeNode(key, zone.type === 'kageNoMichi' ? 'smoke-cell-overlay kage-path-cell-overlay' : 'smoke-cell-overlay', node => {
        node.style.setProperty('--smoke-cell-pulse-speed', `${cell.pulseSpeed || '1.80'}s`);
        node.style.setProperty('--smoke-cell-pulse-delay', `-${cell.pulseDelay || '0'}s`);
      });
      haze.style.left = `${pos.x}%`;
      haze.style.top = `${pos.y}%`;
      haze.style.width = `${size.width}%`;
      haze.style.height = `${size.height}%`;
    }

    const particles = Array.isArray(zone.particles) ? zone.particles : (zone.type === 'kageNoMichi' ? buildKageNoMichiParticles(zone.hazeCells || []) : buildSmokeZoneParticles(zone.row, zone.col, radius));
    zone.particles = particles;
    particles.forEach((particle, index) => {
      if (isCellProtectedByGuardianAura(particle.row, particle.col, zone.playerId) || isCellRevealedByEnemyCelestialLamp(particle.row, particle.col, zone.playerId)) return;
      const pos = cellCenter(particle.row, particle.col);
      const key = `${zone.id}_cloud_${index}_${particle.row}_${particle.col}`;
      const cloud = ensureSmokeNode(key, zone.type === 'kageNoMichi' ? 'smoke-cloud-particle kage-path-cloud-particle' : 'smoke-cloud-particle', node => {
        node.style.setProperty('--smoke-cloud-offset-x', `${particle.offsetXPct}%`);
        node.style.setProperty('--smoke-cloud-offset-y', `${particle.offsetYPct}%`);
        node.style.setProperty('--smoke-cloud-scale', particle.sizeScale);
        node.style.setProperty('--smoke-cloud-opacity-scale', particle.opacityScale);
        node.style.setProperty('--smoke-cloud-pulse-speed', `${particle.pulseSpeed}s`);
        node.style.setProperty('--smoke-cloud-pulse-delay', `-${particle.pulseDelay}s`);
        node.style.zIndex = `${40 + (index % 6)}`;
      });
      cloud.style.left = `${pos.x}%`;
      cloud.style.top = `${pos.y}%`;
    });

  }

  Array.from(els.smokeZonesLayer.children).forEach(node => {
    if (node?.dataset?.smokeKey && !liveKeys.has(node.dataset.smokeKey)) safeRemove(node);
  });
  Array.from((els.smokeBombMarkersLayer || els.smokeZonesLayer).children).forEach(node => {
    if (node?.dataset?.smokeMarkerKey && !liveMarkerKeys.has(node.dataset.smokeMarkerKey)) safeRemove(node);
  });
}


function renderCelestialLamps() {
  if (!els.celestialLampLayer) return;
  const activeKeys = new Set();
  getActiveCelestialLampEntries().forEach(({ playerId, lamp }) => {
    const key = `${playerId}:${lamp.id}`;
    activeKeys.add(key);
    let node = els.celestialLampLayer.querySelector(`[data-celestial-lamp-key="${key}"]`);
    if (!node) {
      node = document.createElement('div');
      node.className = 'celestial-lamp-field celestial-lamp-entering';
      node.dataset.celestialLampKey = key;
      node.setAttribute('aria-hidden', 'true');
      node.innerHTML = `
        <span class="celestial-lamp-halo"></span>
        <span class="celestial-lamp-cell-flash"></span>
        <span class="celestial-lamp-spark-burst"></span>
        <img class="celestial-lamp-sprite" src="${TENTOROU_LAMP_SPRITE}" alt="">
        <span class="celestial-lamp-ambient-particles"></span>`;
      const particleHost = node.querySelector('.celestial-lamp-ambient-particles');
      for (let index = 0; index < 9; index += 1) {
        const particle = document.createElement('i');
        particle.style.setProperty('--tentorou-particle-x', `${(8 + Math.random() * 84).toFixed(2)}%`);
        particle.style.setProperty('--tentorou-particle-delay', `${(-Math.random() * 4.2).toFixed(2)}s`);
        particle.style.setProperty('--tentorou-particle-duration', `${(2.2 + Math.random() * 2.6).toFixed(2)}s`);
        particle.style.setProperty('--tentorou-particle-drift', `${(-12 + Math.random() * 24).toFixed(2)}px`);
        particleHost?.appendChild(particle);
      }
      els.celestialLampLayer.appendChild(node);
      window.setTimeout(() => node.classList.remove('celestial-lamp-entering'), 1800);
    }
    const pos = cellCenter(lamp.row, lamp.col);
    const cellSize = getBoardCellSizePercent(lamp.row);
    node.style.left = `${pos.x}%`;
    node.style.top = `${pos.y}%`;
    node.style.width = `${cellSize.width}%`;
    node.style.height = `${cellSize.height}%`;
    node.style.setProperty('--tentorou-owner-color', getPlayerElementColor(playerId));
    node.dataset.remainingPhases = String(Math.max(0, Number(lamp.remainingPhases || 0)));
    node.title = `Tentoro · ${lamp.remainingPhases} fase${Number(lamp.remainingPhases) === 1 ? '' : 's'} restante${Number(lamp.remainingPhases) === 1 ? '' : 's'}`;
  });
  [...els.celestialLampLayer.querySelectorAll('[data-celestial-lamp-key]')].forEach(node => {
    if (!activeKeys.has(node.dataset.celestialLampKey)) node.remove();
  });
}

function populateLongNightFireflies(shell = null, count = 5) {
  const fireflyHost = shell?.querySelector('.long-night-fireflies');
  if (!fireflyHost) return;
  fireflyHost.innerHTML = '';
  const sides = ['top', 'right', 'bottom', 'left'];
  const total = Math.max(1, Number(count) || 5);
  for (let index = 0; index < total; index += 1) {
    const dot = document.createElement('i');
    const side = sides[Math.floor(Math.random() * sides.length)];
    dot.className = `long-night-firefly long-night-firefly-${side}`;
    if (side === 'top' || side === 'bottom') {
      dot.style.setProperty('--firefly-x', `${(4 + Math.random() * 92).toFixed(2)}%`);
      dot.style.setProperty('--firefly-y', side === 'top' ? `${(2 + Math.random() * 13).toFixed(2)}%` : `${(84 + Math.random() * 11).toFixed(2)}%`);
    } else {
      dot.style.setProperty('--firefly-x', side === 'left' ? `${(2 + Math.random() * 13).toFixed(2)}%` : `${(85 + Math.random() * 11).toFixed(2)}%`);
      dot.style.setProperty('--firefly-y', `${(6 + Math.random() * 88).toFixed(2)}%`);
    }
    dot.style.setProperty('--firefly-delay', `${(-Math.random() * 7).toFixed(2)}s`);
    dot.style.setProperty('--firefly-duration', `${(5.8 + Math.random() * 3.2).toFixed(2)}s`);
    dot.style.setProperty('--firefly-drift-x', `${(-28 + Math.random() * 56).toFixed(2)}px`);
    dot.style.setProperty('--firefly-drift-y', `${(-24 + Math.random() * 48).toFixed(2)}px`);
    fireflyHost.appendChild(dot);
  }
}

function renderLongNightLayer() {
  if (!els.longNightLayer) return;
  const groups = getActiveLongNightEffects();
  if (!groups.length) {
    els.longNightLayer.innerHTML = '';
    els.longNightLayer.classList.remove('active', 'activating');
    return;
  }

  let shell = els.longNightLayer.querySelector('.long-night-shell');
  if (!shell) {
    shell = document.createElement('div');
    shell.className = 'long-night-shell';
    shell.setAttribute('aria-hidden', 'true');
    shell.innerHTML = `
      <span class="long-night-global-mask"></span>
      <span class="long-night-vignette"></span>
      <span class="long-night-activation-wave"></span>
      <span class="long-night-fireflies"></span>
      <span class="long-night-fog-banks"></span>
    `;
    els.longNightLayer.appendChild(shell);

    populateLongNightFireflies(shell, 5);

    const fogHost = shell.querySelector('.long-night-fog-banks');
    const fogSeeds = [
      { x: '10%', y: '22%', w: '24%', h: '18%' },
      { x: '86%', y: '24%', w: '28%', h: '18%' },
      { x: '18%', y: '78%', w: '32%', h: '18%' },
      { x: '82%', y: '80%', w: '34%', h: '20%' },
      { x: '51%', y: '12%', w: '38%', h: '14%' },
      { x: '6%', y: '58%', w: '26%', h: '16%' },
      { x: '93%', y: '58%', w: '26%', h: '16%' },
    ];
    fogSeeds.forEach((seed, index) => {
      const bank = document.createElement('i');
      bank.className = 'long-night-fog-bank';
      bank.style.left = seed.x;
      bank.style.top = seed.y;
      bank.style.width = seed.w;
      bank.style.height = seed.h;
      bank.style.setProperty('--long-night-fog-delay', `${(-Math.random() * 6).toFixed(2)}s`);
      bank.style.setProperty('--long-night-fog-duration', `${(8 + Math.random() * 7).toFixed(2)}s`);
      bank.style.zIndex = String(1 + (index % 2));
      fogHost?.appendChild(bank);
    });
  }

  const strongest = groups.reduce((best, item) => Number(item.remainingPhases || 0) > Number(best?.remainingPhases || 0) ? item : best, groups[0]);
  const latestActivation = groups.reduce((max, item) => Math.max(max, Number(item.activationFxUntil || 0)), 0);
  const activationStamp = String(latestActivation || 0);
  if (shell.dataset.longNightActivationStamp !== activationStamp) {
    shell.dataset.longNightActivationStamp = activationStamp;
    populateLongNightFireflies(shell, 5);
  }
  shell.title = `Larga Noche · ${groups.length} efecto${groups.length === 1 ? '' : 's'} activo${groups.length === 1 ? '' : 's'} · hasta ${Math.max(0, Number(strongest?.remainingPhases || 0))} fases restantes`;
  els.longNightLayer.classList.add('active');
  const activating = Date.now() < latestActivation;
  els.longNightLayer.classList.toggle('activating', activating);
}

function playMaerynDominationPulseFx(playerId, maerynUnit) {
  if (!els.maerynDominationAuraLayer || !maerynUnit || maerynUnit.status === 'restoring' || Number(maerynUnit.hp ?? 0) <= 0) return null;
  if (unitHasSilence(maerynUnit) || isOnlineUnitConcealedFromViewer(playerId, maerynUnit)) return null;

  const pos = getRealtimeRenderedInvocationPoint(playerId, maerynUnit);
  const cellSize = getBoardCellSizePercent(maerynUnit.row);
  const diameter = (MAERYN_DOMINATION_RANGE * 2) + 1;
  const elementId = getUnitElementId(playerId, maerynUnit) || 'agua';
  const primary = getElementColorById(elementId, getDominionPrimaryColor('agua'));
  const secondary = getElementSecondaryColorById(elementId, getDominionSecondaryColor('agua'));

  const pulse = document.createElement('div');
  pulse.className = 'maeryn-domination-pulse-fx';
  pulse.setAttribute('aria-hidden', 'true');
  pulse.style.left = `${pos.x}%`;
  pulse.style.top = `${pos.y}%`;
  pulse.style.width = `${cellSize.width * diameter}%`;
  pulse.style.height = `${cellSize.height * diameter}%`;
  pulse.style.setProperty('--maeryn-aura-primary-rgb', hexToRgbParts(primary));
  pulse.style.setProperty('--maeryn-aura-secondary-rgb', hexToRgbParts(secondary));

  const first = document.createElement('span');
  first.className = 'maeryn-domination-ripple maeryn-domination-ripple--first';
  const second = document.createElement('span');
  second.className = 'maeryn-domination-ripple maeryn-domination-ripple--second';
  pulse.append(first, second);
  els.maerynDominationAuraLayer.appendChild(pulse);
  window.setTimeout(() => safeRemove(pulse), 1500);
  return pulse;
}

function renderMaerynDominationAuras() {
  if (!els.maerynDominationAuraLayer) return;
  const activeKeys = new Set();

  for (const playerId of [1, 2]) {
    for (const unit of state.players?.[playerId]?.units || []) {
      if (!isMaerynUnit(unit) || unit.status === 'restoring' || Number(unit.hp ?? 0) <= 0 || unitHasSilence(unit)) continue;
      if (isOnlineUnitConcealedFromViewer(playerId, unit)) continue;

      const key = `${playerId}:${unit.id}`;
      activeKeys.add(key);
      let node = els.maerynDominationAuraLayer.querySelector(`[data-maeryn-domination-aura-key="${key}"]`);
      if (!node) {
        node = document.createElement('div');
        node.className = 'maeryn-domination-aura-field';
        node.dataset.maerynDominationAuraKey = key;
        node.dataset.maerynPulseSerial = '0';
        node.setAttribute('aria-hidden', 'true');
        node.innerHTML = '<span class="maeryn-domination-aura-core"></span>';
        els.maerynDominationAuraLayer.appendChild(node);
      }

      const pos = getRealtimeRenderedInvocationPoint(playerId, unit);
      const cellSize = getBoardCellSizePercent(unit.row);
      const diameter = (MAERYN_DOMINATION_RANGE * 2) + 1;
      const elementId = getUnitElementId(playerId, unit) || 'agua';
      const primary = getElementColorById(elementId, getDominionPrimaryColor('agua'));
      const secondary = getElementSecondaryColorById(elementId, getDominionSecondaryColor('agua'));

      node.style.left = `${pos.x}%`;
      node.style.top = `${pos.y}%`;
      node.style.width = `${cellSize.width * diameter}%`;
      node.style.height = `${cellSize.height * diameter}%`;
      node.style.setProperty('--maeryn-aura-primary-rgb', hexToRgbParts(primary));
      node.style.setProperty('--maeryn-aura-secondary-rgb', hexToRgbParts(secondary));
      node.classList.toggle('maeryn-domination-aura-field--cooldown', getMaerynDominationCooldownRemaining(unit) > 0);
      node.classList.toggle('maeryn-domination-aura-field--supremacy', isMaerynSupremacyActive(playerId, unit));

      const pulseSerial = Math.max(0, Number(unit.maerynDominationPulseSerial || 0));
      const lastPulseSerial = Math.max(0, Number(node.dataset.maerynPulseSerial || 0));
      if (pulseSerial > 0 && pulseSerial !== lastPulseSerial) {
        node.dataset.maerynPulseSerial = String(pulseSerial);
        if ((Date.now() - Number(unit.maerynDominationPulseAt || 0)) < 4500) {
          playMaerynDominationPulseFx(playerId, unit);
        }
      }
    }
  }

  [...els.maerynDominationAuraLayer.querySelectorAll('[data-maeryn-domination-aura-key]')].forEach(node => {
    if (!activeKeys.has(node.dataset.maerynDominationAuraKey)) node.remove();
  });
}

