function renderGuardianChannelFx() {
  if (!els.guardianChannelFxLayer || !els.boardContent) return;
  const activeKeys = new Set();
  const boardWidth = els.boardContent.offsetWidth || 1;
  const boardHeight = els.boardContent.offsetHeight || 1;
  for (const { playerId, guardian } of getActiveGuardianEntries()) {
    const channels = getGuardianChannelEntries(guardian);
    Object.entries(channels).forEach(([targetKey, entry]) => {
      const unit = getUnitById(entry.playerId, entry.unitId);
      if (!unit || unit.status === 'restoring' || !isCellInsideGuardianAura(guardian, unit.row, unit.col)) return;
      if (isOnlineUnitConcealedFromViewer(entry.playerId, unit)) return;
      const key = `${playerId}:${guardian.id}:${targetKey}`;
      activeKeys.add(key);
      let beam = els.guardianChannelFxLayer.querySelector(`[data-guardian-channel-key="${key}"]`);
      if (!beam) {
        beam = document.createElement('div');
        beam.className = 'guardian-channel-beam';
        beam.dataset.guardianChannelKey = key;
        beam.setAttribute('aria-hidden', 'true');
        beam.innerHTML = '<span class="guardian-channel-beam-core"></span><i class="guardian-channel-origin"></i><i class="guardian-channel-target"></i>';
        els.guardianChannelFxLayer.appendChild(beam);
      }
      const start = cellCenter(guardian.row, guardian.col);
      const end = getRealtimeRenderedInvocationPoint(entry.playerId, unit);
      const dx = ((end.x - start.x) / 100) * boardWidth;
      const dy = ((end.y - start.y) / 100) * boardHeight;
      const length = Math.max(1, Math.hypot(dx, dy));
      const angle = Math.atan2(dy, dx) * 180 / Math.PI;
      const color = getPlayerElementColor(playerId);
      beam.style.left = `${start.x}%`;
      beam.style.top = `${start.y}%`;
      beam.style.width = `${length}px`;
      beam.style.transform = `translateY(-50%) rotate(${angle}deg)`;
      beam.style.setProperty('--guardian-channel-color', color);
      beam.style.setProperty('--guardian-channel-rgb', hexToRgbParts(color));
      beam.dataset.remaining = String(Math.max(0, Number(entry.remaining ?? GUARDIAN_CHANNEL_PHASES)));
      beam.classList.toggle('guardian-channel-ready', Boolean(entry.readyQueued));
      beam.classList.toggle('guardian-channel-striking', guardian.strikingTargetKey === targetKey);
    });
  }
  [...els.guardianChannelFxLayer.querySelectorAll('[data-guardian-channel-key]')].forEach(node => {
    if (!activeKeys.has(node.dataset.guardianChannelKey)) node.remove();
  });
}


function syncMinokagePersistentAnimationPhase(node, startedAt) {
  if (!node) return;
  const normalizedStartedAt = Number(startedAt || Date.now());
  // Si el nodo sigue vivo, no se vuelve a tocar su reloj de animación.
  // Si el DOM tuvo que recrearlo, el retraso negativo lo coloca en la fase
  // visual correcta en vez de comenzar nuevamente desde cero.
  if (node.dataset.animationStartedAt === String(normalizedStartedAt)) return;
  const elapsed = Math.max(0, Date.now() - normalizedStartedAt);
  const timings = [
    ['.minokage-yari-orbit-main', 1800],
    ['.minokage-targeting-beam-core::after', 1180],
  ];
  timings.forEach(([selector, duration]) => {
    if (selector.includes('::')) return;
    const element = node.querySelector(selector);
    if (element) element.style.animationDelay = `${-(elapsed % duration)}ms`;
  });
  const beamCore = node.querySelector('.minokage-targeting-beam-core');
  if (beamCore) beamCore.style.setProperty('--minokage-beam-delay', `${-(elapsed % 1180)}ms`);
  node.dataset.animationStartedAt = String(normalizedStartedAt);
  window.requestAnimationFrame(() => {
    try {
      node.getAnimations({ subtree: true }).forEach(animation => {
        const timing = animation.effect?.getComputedTiming?.();
        const duration = Number(timing?.duration || 0);
        if (duration > 0 && Number.isFinite(duration)) animation.currentTime = elapsed % duration;
      });
    } catch (_) { /* la persistencia visual no debe bloquear el render */ }
  });
}

function isInvocationHiddenFromPlayer(viewerPlayerId, ownerPlayerId, unit) {
  if (!unit || viewerPlayerId == null || ownerPlayerId == null) return false;
  if (Number(viewerPlayerId) === Number(ownerPlayerId)) return false;
  return unit.status !== 'restoring' && unitHasActiveFactor(unit, 'hidden');
}

function canPlayerDirectlyTargetInvocation(viewerPlayerId, ownerPlayerId, unit) {
  if (!unit || unit.status === 'restoring' || Number(unit.hp ?? 1) <= 0) return false;
  // Dominación Mental cambia el bando efectivo de la pieza: para Maeryn y todo
  // su ejército es una aliada real durante el control, nunca un objetivo rival.
  if (isMaerynDominatedAllyForPlayer(viewerPlayerId, unit)) return false;
  return !isInvocationHiddenFromPlayer(viewerPlayerId, ownerPlayerId, unit);
}

function canPlayerDirectlyTargetTarget(viewerPlayerId, target) {
  if (!target || viewerPlayerId == null) return false;
  if (target.type !== 'invocation') return true;
  const unit = getUnitById(target.playerId, target.unitId);
  return canPlayerDirectlyTargetInvocation(viewerPlayerId, target.playerId, unit);
}

function isOnlineUnitConcealedFromViewer(ownerPlayerId, unit, viewerPlayerId = LOCAL_PLAYER_ID) {
  if (!isOnlineMatchActive()) return false;
  return isInvocationHiddenFromPlayer(viewerPlayerId, ownerPlayerId, unit);
}

function isOnlineOwnHiddenUnit(ownerPlayerId, unit, viewerPlayerId = LOCAL_PLAYER_ID) {
  if (!isOnlineMatchActive() || !unit || viewerPlayerId == null) return false;
  return Number(ownerPlayerId) === Number(viewerPlayerId) && unitHasActiveFactor(unit, 'hidden');
}

function renderMinokageChannelFxLayer() {
  if (!els.minokageChannelFxLayer || !els.boardContent) return;
  const activeKeys = new Set();
  const boardWidth = els.boardContent.offsetWidth || 1;
  const boardHeight = els.boardContent.offsetHeight || 1;
  const charges = Array.isArray(state.minokageCharges) ? state.minokageCharges : [];

  charges.forEach(charge => {
    const unit = getUnitById(charge.playerId, charge.unitId);
    if (!unit || unit.status === 'restoring' || !unit.minokageChanneling) return;
    if (isOnlineUnitConcealedFromViewer(charge.playerId, unit)) return;
    if (!isMinokageChargeTargetValid(charge)) {
      clearMinokageChargeRuntime(charge, 'el objetivo murió, fue destruido o salió de la arena', true);
      return;
    }
    const key = `${charge.playerId}:${charge.unitId}`;
    activeKeys.add(key);
    let node = els.minokageChannelFxLayer.querySelector(`[data-minokage-channel-key="${key}"]`);
    if (!node) {
      node = document.createElement('div');
      node.className = 'minokage-channel-persistent';
      node.dataset.minokageChannelKey = key;
      node.setAttribute('aria-hidden', 'true');
      node.innerHTML = `
        <span class="minokage-yari-channel-fx" aria-hidden="true">${getMinokageYariSpinMarkup('channel')}</span>
        <span class="minokage-targeting-beam">
          <span class="minokage-targeting-beam-core"></span>
          <i class="minokage-targeting-origin"></i>
          <i class="minokage-targeting-end"></i>
        </span>`;
      els.minokageChannelFxLayer.appendChild(node);
    }
    syncMinokagePersistentAnimationPhase(node, unit.minokageChannelStartedAt || charge.startedAt || Date.now());
    ensureMinokageYariTrail(node.querySelector('.minokage-yari-spin-system'));

    const start = cellCenter(unit.row, unit.col);
    const rebuiltTarget = rebuildMinokageTargetFromSnapshot(charge.target);
    const targetPos = getTargetBoardPosition(rebuiltTarget);
    const end = targetPos?.row != null && targetPos?.col != null
      ? cellCenter(targetPos.row, targetPos.col)
      : start;
    const dx = ((end.x - start.x) / 100) * boardWidth;
    const dy = ((end.y - start.y) / 100) * boardHeight;
    const length = Math.max(1, Math.hypot(dx, dy));
    const angle = Math.atan2(dy, dx) * 180 / Math.PI;
    const originFx = node.querySelector('.minokage-channel-origin-fx');
    const beam = node.querySelector('.minokage-targeting-beam');
    if (originFx) {
      originFx.style.left = `${start.x}%`;
      originFx.style.top = `${start.y}%`;
    }
    const remainingPhases = Math.max(0, Number(charge.phasesRemaining || 0));
    node.classList.toggle('minokage-channel-prelaunch', remainingPhases === 1);
    if (beam) {
      beam.style.left = `${start.x}%`;
      beam.style.top = `${start.y}%`;
      beam.style.width = `${length}px`;
      beam.style.transform = `translateY(-50%) rotate(${angle}deg)`;
      beam.dataset.remaining = String(remainingPhases);
    }
    const yariSpin = node.querySelector('.minokage-yari-channel-fx');
    if (yariSpin) {
      yariSpin.style.left = `${start.x}%`;
      yariSpin.style.top = `${start.y}%`;
    }
  });

  [...els.minokageChannelFxLayer.querySelectorAll('[data-minokage-channel-key]')].forEach(node => {
    if (!activeKeys.has(node.dataset.minokageChannelKey)) node.remove();
  });
}


/* ========================================================================== 
   R.O.K Lite · Etapa 4/4 · herramienta temporal de ajuste de tokens
   ========================================================================== */
const ROK_TOKEN_TUNING_STORAGE_KEY = 'rok_token_tuning_v2';
const ROK_TOKEN_TUNING_DEFAULT = Object.freeze({ scale: 1, x: 0, y: 0 });

// RT-08.6 · Calibración de bloques completos de combate. Se mantiene en una
// clave separada para que los ajustes de fichas existentes no cambien.
const ROK_UI_TUNING_STORAGE_KEY = 'rok_ui_tuning_v3';
const ROK_UI_TUNING_LEGACY_STORAGE_KEY = 'rok_ui_tuning_v3_legacy_disabled';
const ROK_UI_TUNING_DEFAULT = Object.freeze({ x: 0, width: 1 });
const ROK_UI_TUNING_CANONICAL_DEFAULTS = Object.freeze({
  tempo: Object.freeze({ x: -42, width: 1.49 }),
  cast: Object.freeze({ x: -52, width: 1 }),
  spellbook: Object.freeze({ x: -56, width: 1 }),
  'caster-rival': Object.freeze({ x: 0, width: 1 }),
  'caster-ally': Object.freeze({ x: 0, width: 1 }),
  elements: Object.freeze({ x: 0, width: 1 }),
  arena: Object.freeze({ x: 0, width: 1 }),
  'combat-modes': Object.freeze({ x: -46, width: 1 }),
});
const ROK_UI_TUNING_TARGETS = Object.freeze([
  { key: 'tempo', label: 'Tempo / Tiempo', selector: '.phase-rail', scope: 'Combate', trackVar: '--rok-ui-phase-track-w', note: 'Ajusta el carril; reloj, botones y textos escalan juntos con el módulo.' },
  { key: 'cast', label: 'Zona de kasteo', selector: '.cast-panel', scope: 'Combate', trackVar: '--rok-ui-cast-track-w', note: 'Ajusta el carril; cartas, contadores y textos escalan juntos.' },
  { key: 'spellbook', label: 'Spellbook', selector: '.right-panel', scope: 'Combate', trackVar: '--rok-ui-spellbook-track-w', note: 'Ajusta el contenedor; miniaturas, tabs, badges y textos escalan juntos.' },
  { key: 'caster-rival', label: 'Zona del Kaster rival', selector: '#opponentCasterHud', scope: 'Combate', layoutWidth: true, note: 'Mueve y cambia únicamente el ancho REAL del HUD rival. No modifica el HUD aliado.' },
  { key: 'caster-ally', label: 'Zona del Kaster aliado', selector: '#localCasterHud', scope: 'Combate', layoutWidth: true, note: 'Mueve y cambia únicamente el ancho REAL de tu HUD. No modifica el HUD rival.' },
  { key: 'elements', label: 'Zona de elementos', selector: '.left-panel', scope: 'Combate', trackVar: '--rok-ui-elements-track-w', note: 'Ajusta el carril; elementos, INFO, CSS y contadores escalan juntos.' },
  { key: 'arena', label: 'Arena', selector: '.board-panel', scope: 'Combate', trackVar: '--rok-ui-board-track-w', note: 'Aumenta el espacio reservado a la Arena; el tablero mantiene su proporción.' },
  { key: 'combat-modes', label: 'Panel de Invocaciones', selector: '#realtimeCombatModeDock', scope: 'Combate', trackVar: '--rok-ui-mode-track-w', note: 'Ajusta el carril; cartas, estados, botones y textos escalan juntos.' },
]);

const tokenTuningState = {
  loaded: false,
  values: Object.create(null),
  selectedKey: '',
  entriesSignature: '',
  activeTab: 'tokens',
  uiLoaded: false,
  uiValues: Object.create(null),
  selectedUiKey: 'tempo',
  ui: null,
  pausedAnimations: [],
  realtimePauseOwned: false,
};
const TOKEN_TUNING_GAMEPLAY_PAUSE_TOKEN = 'token-tuning-editor';

// RT-08.18 · Persistencia REAL de AJUSTES VISUALES.
// El navegador no puede escribir un archivo local arbitrario sin permiso.
// La primera pulsación de Guardar vincula style.css; después el FileSystemHandle
// se conserva en IndexedDB y el mismo botón vuelve a escribir ese archivo.
const ROK_DIRECT_CSS_DB_NAME = 'rok_direct_css_file_v1';
const ROK_DIRECT_CSS_DB_STORE = 'handles';
const ROK_DIRECT_CSS_HANDLE_KEY = 'style.css';
const ROK_DIRECT_VISUAL_BLOCK_START = '/* === R.O.K DIRECT VISUAL TUNING · START === */';
const ROK_DIRECT_VISUAL_BLOCK_END = '/* === R.O.K DIRECT VISUAL TUNING · END === */';
const ROK_DIRECT_CSS_CANONICAL_ON_BOOT = true;

const rokDirectCssState = {
  fileHandle: null,
  restoreAttempted: false,
  writing: false,
  lastSavedAt: 0,
};

function openRokDirectCssDb() {
  return new Promise((resolve, reject) => {
    if (!window.indexedDB) {
      reject(new Error('IndexedDB no está disponible.'));
      return;
    }
    const request = indexedDB.open(ROK_DIRECT_CSS_DB_NAME, 1);
    request.onupgradeneeded = () => {
      const db = request.result;
      if (!db.objectStoreNames.contains(ROK_DIRECT_CSS_DB_STORE)) {
        db.createObjectStore(ROK_DIRECT_CSS_DB_STORE);
      }
    };
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error || new Error('No se pudo abrir IndexedDB.'));
  });
}

async function persistRokDirectCssHandle(handle) {
  if (!handle) return false;
  try {
    const db = await openRokDirectCssDb();
    await new Promise((resolve, reject) => {
      const tx = db.transaction(ROK_DIRECT_CSS_DB_STORE, 'readwrite');
      tx.objectStore(ROK_DIRECT_CSS_DB_STORE).put(handle, ROK_DIRECT_CSS_HANDLE_KEY);
      tx.oncomplete = () => resolve();
      tx.onerror = () => reject(tx.error || new Error('No se pudo persistir el handle.'));
      tx.onabort = () => reject(tx.error || new Error('Persistencia cancelada.'));
    });
    db.close();
    return true;
  } catch (_) {
    return false;
  }
}

async function restoreRokDirectCssHandle() {
  if (rokDirectCssState.restoreAttempted) return rokDirectCssState.fileHandle;
  rokDirectCssState.restoreAttempted = true;
  try {
    const db = await openRokDirectCssDb();
    const handle = await new Promise((resolve, reject) => {
      const tx = db.transaction(ROK_DIRECT_CSS_DB_STORE, 'readonly');
      const request = tx.objectStore(ROK_DIRECT_CSS_DB_STORE).get(ROK_DIRECT_CSS_HANDLE_KEY);
      request.onsuccess = () => resolve(request.result || null);
      request.onerror = () => reject(request.error || new Error('No se pudo restaurar el handle.'));
    });
    db.close();
    if (handle) {
      rokDirectCssState.fileHandle = handle;
      try {
        if (typeof vsLayoutEditorState !== 'undefined' && !vsLayoutEditorState.cssFileHandle) {
          vsLayoutEditorState.cssFileHandle = handle;
        }
      } catch (_) {}
    }
  } catch (_) {}
  return rokDirectCssState.fileHandle;
}

async function ensureRokDirectCssWritePermission(handle) {
  if (!handle) return false;
  try {
    if (typeof handle.queryPermission !== 'function') return true;
    let permission = await handle.queryPermission({ mode: 'readwrite' });
    if (permission === 'granted') return true;
    if (typeof handle.requestPermission === 'function') {
      permission = await handle.requestPermission({ mode: 'readwrite' });
    }
    return permission === 'granted';
  } catch (_) {
    return false;
  }
}

async function pickRokDirectStyleCssHandle() {
  if (typeof window.showOpenFilePicker !== 'function') {
    throw new Error('Este navegador no permite escritura directa. Abre R.O.K en Chrome/Edge con File System Access habilitado.');
  }
  const [handle] = await window.showOpenFilePicker({
    multiple: false,
    types: [{
      description: 'style.css de R.O.K Lite',
      accept: { 'text/css': ['.css'] },
    }],
  });
  if (!handle) throw new DOMException('Selección cancelada.', 'AbortError');
  if (String(handle.name || '').toLowerCase() !== 'style.css') {
    throw new Error(`Seleccionaste "${handle.name}". Debes seleccionar el style.css del proyecto.`);
  }
  rokDirectCssState.fileHandle = handle;
  try {
    if (typeof vsLayoutEditorState !== 'undefined') vsLayoutEditorState.cssFileHandle = handle;
  } catch (_) {}
  await persistRokDirectCssHandle(handle);
  return handle;
}

async function ensureRokDirectStyleCssHandle() {
  let handle = rokDirectCssState.fileHandle;
  if (!handle) {
    try {
      if (typeof vsLayoutEditorState !== 'undefined' && vsLayoutEditorState.cssFileHandle) {
        handle = vsLayoutEditorState.cssFileHandle;
      }
    } catch (_) {}
  }
  if (!handle) {
    // restoreRokDirectCssHandle se ejecuta al cargar. Si el usuario pulsó Guardar
    // antes de que terminara, se abre el picker dentro del gesto del botón.
    handle = await pickRokDirectStyleCssHandle();
  }
  rokDirectCssState.fileHandle = handle;
  await persistRokDirectCssHandle(handle);
  return handle;
}

function getRokDirectManagedCssBlock(source = '') {
  const start = source.indexOf(ROK_DIRECT_VISUAL_BLOCK_START);
  const end = source.indexOf(ROK_DIRECT_VISUAL_BLOCK_END);
  if (start < 0 || end < start) return '';
  return source.slice(start, end + ROK_DIRECT_VISUAL_BLOCK_END.length);
}

function replaceRokDirectManagedCssBlock(source = '', block = '') {
  const cleanBlock = `${ROK_DIRECT_VISUAL_BLOCK_START}\n${String(block || '').trim()}\n${ROK_DIRECT_VISUAL_BLOCK_END}`;
  const start = source.indexOf(ROK_DIRECT_VISUAL_BLOCK_START);
  const end = source.indexOf(ROK_DIRECT_VISUAL_BLOCK_END);
  if (start >= 0 && end >= start) {
    return source.slice(0, start) + cleanBlock + source.slice(end + ROK_DIRECT_VISUAL_BLOCK_END.length);
  }
  return `${String(source || '').replace(/\s+$/, '')}\n\n${cleanBlock}\n`;
}

function parseRokDirectTokenTuningFromCss(source = '') {
  const block = getRokDirectManagedCssBlock(source);
  const out = Object.create(null);
  const pattern = /\.unit\[data-token-tune-key="([^"]+)"\]\s*\{([\s\S]*?)\}/g;
  let match;
  while ((match = pattern.exec(block))) {
    const key = String(match[1] || '').replace(/\\"/g, '"').replace(/\\\\/g, '\\');
    const body = match[2] || '';
    const scale = /--rok-token-tune-scale:\s*([-.\d]+)/.exec(body);
    const x = /--rok-token-tune-x:\s*([-.\d]+)px/.exec(body);
    const y = /--rok-token-tune-y:\s*([-.\d]+)px/.exec(body);
    out[key] = normalizeTokenTuningRecord({
      scale: scale ? Number(scale[1]) : 1,
      x: x ? Number(x[1]) : 0,
      y: y ? Number(y[1]) : 0,
    });
  }
  return out;
}

function getUiTuningCssVarPrefix(key = '') {
  return `--rok-ui-saved-${String(key || '').replace(/[^a-z0-9-]/gi, '-')}`;
}

function readUiTuningBaselineFromCss(key) {
  try {
    const computed = getComputedStyle(document.documentElement);
    const prefix = getUiTuningCssVarPrefix(key);
    let xRaw = computed.getPropertyValue(`${prefix}-x`).trim();
    let widthRaw = computed.getPropertyValue(`${prefix}-width`).trim();
    if ((!xRaw && !widthRaw) && (key === 'caster-rival' || key === 'caster-ally')) {
      const legacyPrefix = getUiTuningCssVarPrefix('caster');
      xRaw = computed.getPropertyValue(`${legacyPrefix}-x`).trim();
      widthRaw = computed.getPropertyValue(`${legacyPrefix}-width`).trim();
    }
    if (!xRaw && !widthRaw) return null;
    const fallback = ROK_UI_TUNING_CANONICAL_DEFAULTS[key] || ROK_UI_TUNING_DEFAULT;
    return normalizeUiTuningRecord({
      x: xRaw ? Number(xRaw) : fallback.x,
      width: widthRaw ? Number(widthRaw) : fallback.width,
    });
  } catch (_) {
    return null;
  }
}

function getVisualDevCssBaselineDefaults() {
  const defaults = getVisualDevDefaults();
  try {
    const computed = getComputedStyle(document.documentElement);
    Object.keys(defaults).forEach(key => {
      const value = computed.getPropertyValue(key).trim();
      if (value) defaults[key] = value;
    });
  } catch (_) {}
  return defaults;
}

function buildRokDirectVisualCssBlock(source = '') {
  loadTokenTuningSettings();
  loadUiTuningSettings();

  const previousTokens = parseRokDirectTokenTuningFromCss(source);
  const mergedTokens = { ...previousTokens };
  Object.entries(tokenTuningState.values || {}).forEach(([key, value]) => {
    mergedTokens[key] = normalizeTokenTuningRecord(value);
  });

  const lines = [
    '/* Guardado por AJUSTES VISUALES. Este bloque es la fuente canónica de las calibraciones del navegador. */',
    '',
    ':root {',
  ];

  for (const target of ROK_UI_TUNING_TARGETS) {
    const tune = getUiTuningValue(target.key);
    const prefix = getUiTuningCssVarPrefix(target.key);
    lines.push(`  ${prefix}-x: ${Number(tune.x.toFixed(1))};`);
    lines.push(`  ${prefix}-width: ${Number(tune.width.toFixed(2))};`);
  }

  const devSettings = loadVisualDevSettings();
  Object.entries(devSettings).forEach(([key, value]) => {
    lines.push(`  ${key}: ${value};`);
  });
  lines.push('}', '');

  // X queda también escrito como CSS real. El ancho se conserva como ratio
  // canónico y el runtime lo convierte a track/caja real en cada viewport.
  for (const target of ROK_UI_TUNING_TARGETS) {
    const tune = getUiTuningValue(target.key);
    const selector = `body.rok-battle-mode ${target.selector}`;
    lines.push(`/* ${target.label} · ancho ${Math.round(tune.width * 100)}% */`);
    lines.push(`${selector} {`);
    lines.push(`  --rok-ui-tune-x: ${Number(tune.x.toFixed(1))}px;`);
    lines.push('}', '');
  }

  lines.push(
    '.unit[data-token-tune-key] > .unit-token-img,',
    '.unit[data-token-tune-key] > .unit-hitbox {',
    '  scale: var(--rok-token-tune-scale, 1);',
    '  translate: var(--rok-token-tune-x, 0px) var(--rok-token-tune-y, 0px);',
    '}',
    ''
  );

  Object.keys(mergedTokens).sort().forEach(key => {
    const tune = normalizeTokenTuningRecord(mergedTokens[key]);
    if (isDefaultTokenTuning(tune)) return;
    const safeKey = String(key).replace(/\\/g, '\\\\').replace(/"/g, '\\"');
    lines.push(`.unit[data-token-tune-key="${safeKey}"] {`);
    lines.push(`  --rok-token-tune-scale: ${Number(tune.scale.toFixed(2))};`);
    lines.push(`  --rok-token-tune-x: ${Number(tune.x.toFixed(1))}px;`);
    lines.push(`  --rok-token-tune-y: ${Number(tune.y.toFixed(1))}px;`);
    lines.push('}', '');
  });

  return lines.join('\n');
}

function setRokDirectCssSaveStatus(message, isError = false) {
  const text = String(message || '');
  if (tokenTuningState.ui?.status) tokenTuningState.ui.status.textContent = text;
  if (tokenTuningState.ui?.uiStatus) tokenTuningState.ui.uiStatus.textContent = text;
  try {
    const devNote = els.patchInfoBody?.querySelector?.('[data-visual-dev-save-status]');
    if (devNote) devNote.textContent = text;
  } catch (_) {}
  if (isError) {
    try { window.ROK_DEBUG_RIBBON?.show?.('CSS', 'warn', text); } catch (_) {}
  }
}

async function saveRokVisualSettingsDirectToCss(sourceLabel = 'AJUSTES VISUALES') {
  if (rokDirectCssState.writing) return false;
  rokDirectCssState.writing = true;
  try {
    setRokDirectCssSaveStatus('Vinculando style.css…');
    const handle = await ensureRokDirectStyleCssHandle();
    const allowed = await ensureRokDirectCssWritePermission(handle);
    if (!allowed) throw new Error('El navegador no concedió permiso de escritura para style.css.');

    const file = await handle.getFile();
    const source = await file.text();
    const block = buildRokDirectVisualCssBlock(source);
    const updated = replaceRokDirectManagedCssBlock(source, block);

    const writable = await handle.createWritable();
    await writable.write(updated);
    await writable.close();

    rokDirectCssState.fileHandle = handle;
    rokDirectCssState.lastSavedAt = Date.now();
    await persistRokDirectCssHandle(handle);
    try {
      if (typeof vsLayoutEditorState !== 'undefined') vsLayoutEditorState.cssFileHandle = handle;
    } catch (_) {}

    // Ya no dependemos de estos borradores para el siguiente arranque.
    // Se mantienen en memoria durante esta pantalla para no saltar visualmente.
    try {
      localStorage.removeItem(ROK_TOKEN_TUNING_STORAGE_KEY);
      localStorage.removeItem(ROK_UI_TUNING_STORAGE_KEY);
      localStorage.removeItem(VISUAL_DEV_STORAGE_KEY);
    } catch (_) {}

    setRokDirectCssSaveStatus(`GUARDADO DIRECTO · ${handle.name} actualizado. El próximo reload leerá estas posiciones desde el CSS principal.`);
    try {
      recordRokMatchDiagnostic('visual-css-direct-save', sourceLabel, {
        file: handle.name,
        bytes: updated.length,
        at: rokDirectCssState.lastSavedAt,
      }, { persistNow: true });
    } catch (_) {}

    // Fuerza al documento actual a releer el archivo que acabamos de escribir.
    try { refreshCssOnly(); } catch (_) {}
    return true;
  } catch (error) {
    if (error?.name === 'AbortError') {
      setRokDirectCssSaveStatus('Guardado cancelado. No se modificó style.css.');
      return false;
    }
    reportGameException(error, 'AJUSTES VISUALES · guardar style.css');
    setRokDirectCssSaveStatus(`NO SE PUDO GUARDAR · ${error?.message || error}`, true);
    return false;
  } finally {
    rokDirectCssState.writing = false;
  }
}

async function initRokDirectCssPersistence() {
  await restoreRokDirectCssHandle();
  if (rokDirectCssState.fileHandle) {
    try {
      if (typeof vsLayoutEditorState !== 'undefined' && !vsLayoutEditorState.cssFileHandle) {
        vsLayoutEditorState.cssFileHandle = rokDirectCssState.fileHandle;
      }
    } catch (_) {}
  }
}



function isTokenTuningToolOpen() {
  return Boolean(tokenTuningState.ui?.panel?.classList?.contains('open'));
}


const ROK_TOKEN_TUNING_PANEL_POSITION_KEY = 'rokLite.tokenTuningPanelPosition.v1';

function clampTokenTuningPanelPosition(panel, left, top) {
  if (!panel) return { left: 8, top: 45 };
  const rect = panel.getBoundingClientRect();
  const margin = 6;
  const maxLeft = Math.max(margin, window.innerWidth - Math.max(120, rect.width) - margin);
  const maxTop = Math.max(margin, window.innerHeight - Math.max(80, rect.height) - margin);
  return {
    left: Math.max(margin, Math.min(maxLeft, Number(left) || margin)),
    top: Math.max(margin, Math.min(maxTop, Number(top) || margin)),
  };
}

function saveTokenTuningPanelPosition(panel) {
  if (!panel) return;
  const rect = panel.getBoundingClientRect();
  const pos = clampTokenTuningPanelPosition(panel, rect.left, rect.top);
  try { localStorage.setItem(ROK_TOKEN_TUNING_PANEL_POSITION_KEY, JSON.stringify(pos)); } catch (_) {}
}

function applySavedTokenTuningPanelPosition(panel) {
  if (!panel) return;
  let saved = null;
  try {
    const raw = localStorage.getItem(ROK_TOKEN_TUNING_PANEL_POSITION_KEY);
    saved = raw ? JSON.parse(raw) : null;
  } catch (_) {}
  if (!saved || !Number.isFinite(Number(saved.left)) || !Number.isFinite(Number(saved.top))) return;
  const pos = clampTokenTuningPanelPosition(panel, Number(saved.left), Number(saved.top));
  panel.style.left = `${pos.left}px`;
  panel.style.top = `${pos.top}px`;
  panel.style.right = 'auto';
  panel.style.bottom = 'auto';
}

function bindTokenTuningPanelDrag(panel) {
  if (!panel || panel.dataset.rokDraggableBound === '1') return;
  const handle = panel.querySelector('.token-tuning-header');
  if (!handle) return;
  panel.dataset.rokDraggableBound = '1';

  let drag = null;
  const endDrag = () => {
    if (!drag) return;
    drag = null;
    panel.classList.remove('is-dragging');
    document.body.classList.remove('rok-token-tuning-dragging');
    saveTokenTuningPanelPosition(panel);
  };

  handle.addEventListener('pointerdown', event => {
    if (event.button !== 0) return;
    if (event.target?.closest?.('button, input, select, textarea, a')) return;
    const rect = panel.getBoundingClientRect();
    drag = {
      pointerId: event.pointerId,
      offsetX: event.clientX - rect.left,
      offsetY: event.clientY - rect.top,
    };
    try { handle.setPointerCapture(event.pointerId); } catch (_) {}
    panel.classList.add('is-dragging');
    document.body.classList.add('rok-token-tuning-dragging');
    event.preventDefault();
    event.stopPropagation();
  });

  handle.addEventListener('pointermove', event => {
    if (!drag || event.pointerId !== drag.pointerId) return;
    const pos = clampTokenTuningPanelPosition(panel, event.clientX - drag.offsetX, event.clientY - drag.offsetY);
    panel.style.left = `${pos.left}px`;
    panel.style.top = `${pos.top}px`;
    panel.style.right = 'auto';
    panel.style.bottom = 'auto';
    event.preventDefault();
    event.stopPropagation();
  });

  handle.addEventListener('pointerup', event => {
    if (!drag || event.pointerId !== drag.pointerId) return;
    try { handle.releasePointerCapture(event.pointerId); } catch (_) {}
    endDrag();
  });
  handle.addEventListener('pointercancel', endDrag);
  window.addEventListener('resize', () => {
    if (!panel.classList.contains('open')) return;
    const rect = panel.getBoundingClientRect();
    const pos = clampTokenTuningPanelPosition(panel, rect.left, rect.top);
    panel.style.left = `${pos.left}px`;
    panel.style.top = `${pos.top}px`;
  }, { passive: true });
}

function pauseBattleVisualAnimationsForTokenTuning() {
  tokenTuningState.pausedAnimations = [];
  const stage = document.getElementById('rokAppStage');
  if (!stage?.getAnimations) return;
  try {
    tokenTuningState.pausedAnimations = stage.getAnimations({ subtree: true }).filter(animation => {
      try {
        const target = animation.effect?.target;
        if (target?.closest?.('#tokenTuningPanel, #tokenTuningToggle')) return false;
        if (animation.playState === 'running' || animation.playState === 'pending') {
          animation.pause();
          return true;
        }
      } catch (_) {}
      return false;
    });
  } catch (_) { tokenTuningState.pausedAnimations = []; }
}

function resumeBattleVisualAnimationsFromTokenTuning() {
  const animations = tokenTuningState.pausedAnimations || [];
  tokenTuningState.pausedAnimations = [];
  animations.forEach(animation => {
    try { if (animation.playState === 'paused') animation.play(); } catch (_) {}
  });
}

function acquireTokenTuningGameplayPause() {
  acquireGlobalGameplayPause(TOKEN_TUNING_GAMEPLAY_PAUSE_TOKEN);
  document.body.classList.add('rok-token-tuning-paused');

  // RT-08.8 · La pausa global por sí sola no detenía el ticker independiente de
  // Tiempo real. Si no existe otra pausa temporal, el editor adquiere también
  // la pausa del motor RT para congelar reloj, recursos, IA, ataques y estados.
  tokenTuningState.realtimePauseOwned = false;
  if (isRealtimePlayStyle() && state?.realtime?.active && !isRealtimeTempoPaused()) {
    tokenTuningState.realtimePauseOwned = Boolean(
      setRealtimeTempoPause(true, 'Ajustes visuales', 'token-tuning')
    );
  }

  try { hideBattleInactivityPrompt('token-tuning-pause'); } catch (_) {}
  try { markBattleActivity('token-tuning-pause', { keepPrompt: true }); } catch (_) {}
  pauseBattleVisualAnimationsForTokenTuning();
  try { renderPhaseUI(); } catch (_) {}
  try { renderRealtimeStage1Status(); } catch (_) {}
}

function releaseTokenTuningGameplayPause() {
  if (tokenTuningState.realtimePauseOwned
      && state?.realtime?.tempoPause?.active
      && state.realtime.tempoPause.source === 'token-tuning') {
    setRealtimeTempoPause(false, '', 'token-tuning');
  }
  tokenTuningState.realtimePauseOwned = false;

  releaseGlobalGameplayPause(TOKEN_TUNING_GAMEPLAY_PAUSE_TOKEN);
  document.body.classList.remove('rok-token-tuning-paused');
  resumeBattleVisualAnimationsFromTokenTuning();
  try { markBattleActivity('token-tuning-resume'); } catch (_) {}
  try { renderPhaseUI(); } catch (_) {}
  try { renderRealtimeStage1Status(); } catch (_) {}
}

function sanitizeTokenTuningValue(value, fallback, min, max) {
  const numeric = Number(value);
  if (!Number.isFinite(numeric)) return fallback;
  return Math.max(min, Math.min(max, numeric));
}

function normalizeTokenTuningRecord(value = null) {
  return {
    scale: Number(sanitizeTokenTuningValue(value?.scale, 1, 0.25, 6).toFixed(2)),
    x: Number(sanitizeTokenTuningValue(value?.x, 0, -160, 160).toFixed(1)),
    y: Number(sanitizeTokenTuningValue(value?.y, 0, -160, 160).toFixed(1)),
  };
}

function loadTokenTuningSettings() {
  if (tokenTuningState.loaded) return tokenTuningState.values;
  tokenTuningState.loaded = true;

  // v8.86 · style.css es la fuente canónica al arrancar.
  // Los sliders siguen usando memoria/localStorage como borrador DURANTE la
  // sesión, pero un borrador viejo nunca puede pisar el bloque guardado en CSS
  // al recargar o abrir una build nueva.
  if (ROK_DIRECT_CSS_CANONICAL_ON_BOOT) {
    try { localStorage.removeItem(ROK_TOKEN_TUNING_STORAGE_KEY); } catch (_) {}
    return tokenTuningState.values;
  }

  try {
    const raw = localStorage.getItem(ROK_TOKEN_TUNING_STORAGE_KEY);
    const parsed = raw ? JSON.parse(raw) : null;
    if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) {
      Object.entries(parsed).forEach(([key, value]) => {
        if (!key) return;
        tokenTuningState.values[key] = normalizeTokenTuningRecord(value);
      });
    }
  } catch (_) {}
  return tokenTuningState.values;
}

function persistTokenTuningSettings() {
  loadTokenTuningSettings();
  try { localStorage.setItem(ROK_TOKEN_TUNING_STORAGE_KEY, JSON.stringify(tokenTuningState.values)); } catch (_) {}
}

function getTokenTuning(key) {
  loadTokenTuningSettings();
  if (tokenTuningState.values[key]) return normalizeTokenTuningRecord(tokenTuningState.values[key]);

  // Sin borrador local, no inventar defaults inline: leer el valor que ya vive
  // en style.css si existe una instancia renderizada de esta pieza.
  try {
    const node = document.querySelector(`.unit[data-token-tune-key="${escapeTokenTuningSelectorValue(key)}"]`);
    if (node) {
      const computed = getComputedStyle(node);
      const scale = computed.getPropertyValue('--rok-token-tune-scale').trim();
      const x = computed.getPropertyValue('--rok-token-tune-x').trim();
      const y = computed.getPropertyValue('--rok-token-tune-y').trim();
      if (scale || x || y) {
        return normalizeTokenTuningRecord({
          scale: scale ? Number(scale) : 1,
          x: x ? parseFloat(x) : 0,
          y: y ? parseFloat(y) : 0,
        });
      }
    }
  } catch (_) {}
  return normalizeTokenTuningRecord(ROK_TOKEN_TUNING_DEFAULT);
}

function escapeTokenTuningSelectorValue(value = '') {
  return String(value).replace(/\\/g, '\\\\').replace(/"/g, '\\"');
}

function isDefaultTokenTuning(value) {
  const tune = normalizeTokenTuningRecord(value);
  return Math.abs(tune.scale - 1) < 0.001 && Math.abs(tune.x) < 0.001 && Math.abs(tune.y) < 0.001;
}

function getTokenTuningKeyForRenderedUnit(type, playerId, unitState = null, guardianState = null) {
  if (type === 'invocation' && unitState?.cardId) return `invocation:${unitState.cardId}`;
  if (type === 'caster') {
    const caster = state.players?.[playerId]?.caster;
    const id = caster?.cardId || caster?.casterId;
    return id ? `caster:${id}` : '';
  }
  if (type === 'guardian') return `guardian:${getPlayerDomainId(playerId) || 'default'}`;
  if (type === 'structure' && unitState?.cardId) return `structure:${unitState.cardId}`;
  return '';
}

function applyTokenTuningToNode(node, key) {
  if (!node || !key) return;
  loadTokenTuningSettings();
  node.dataset.tokenTuneKey = key;

  // Solo un BORRADOR local necesita inline style. Si no existe, dejamos las
  // propiedades sin tocar para que la regla guardada en style.css mande.
  const local = tokenTuningState.values[key];
  if (!local) {
    node.style.removeProperty('--rok-token-tune-scale');
    node.style.removeProperty('--rok-token-tune-x');
    node.style.removeProperty('--rok-token-tune-y');
    return;
  }
  const tune = normalizeTokenTuningRecord(local);
  node.style.setProperty('--rok-token-tune-scale', String(tune.scale));
  node.style.setProperty('--rok-token-tune-x', `${tune.x}px`);
  node.style.setProperty('--rok-token-tune-y', `${tune.y}px`);
}

function applyTokenTuningToRenderedNodes(key = '') {
  if (!els.unitsLayer) return;
  const nodes = key
    ? els.unitsLayer.querySelectorAll(`.unit[data-token-tune-key="${escapeTokenTuningSelectorValue(key)}"]`)
    : els.unitsLayer.querySelectorAll('.unit[data-token-tune-key]');
  nodes.forEach(node => applyTokenTuningToNode(node, node.dataset.tokenTuneKey));
  syncTokenTuningSelectionHighlight();
}

function getTokenTuningOwnerLabel(playerId) {
  return Number(playerId) === Number(LOCAL_PLAYER_ID) ? 'Tuyo' : 'Rival';
}

function collectTokenTuningEntries() {
  const entries = [];
  const seen = new Map();

  const addEntry = entry => {
    if (!entry?.key) return;
    const existing = seen.get(entry.key);
    if (existing) {
      // Si la misma pieza visual existe en ambos lados, una sola regla CSS debe
      // seguir gobernándola. La lista deja claro que está presente en ambos.
      const owners = new Set([...(existing.owners || []), ...(entry.owners || [])]);
      existing.owners = [...owners];
      existing.sublabel = `${existing.kindLabel} · ${existing.owners.join(' / ')}`;
      return;
    }
    const clone = { ...entry, owners: [...(entry.owners || [])] };
    clone.sublabel = `${clone.kindLabel} · ${clone.owners.join(' / ')}`;
    seen.set(clone.key, clone);
    entries.push(clone);
  };

  for (const playerId of [1, 2]) {
    const player = state.players?.[playerId];
    if (!player) continue;
    const ownerLabel = getTokenTuningOwnerLabel(playerId);
    const caster = player.caster;
    const casterId = caster?.cardId || caster?.casterId;
    if (casterId) {
      const card = caster?.cardId ? CARD_LIBRARY[caster.cardId] : null;
      addEntry({
        key: `caster:${casterId}`,
        kind: 'caster',
        kindLabel: 'Kaster',
        label: card?.name || caster?.name || caster?.shortName || `Kaster J${playerId}`,
        owners: [ownerLabel],
      });
    }

    for (const unit of player.units || []) {
      if (!unit?.cardId || unit.restoreAnimating || unit.status === 'restoring') continue;
      if (isOnlineUnitConcealedFromViewer(playerId, unit)) continue;
      const card = CARD_LIBRARY[unit.cardId];
      if (!card) continue;
      const typeId = getCardTypeId(card);
      const kind = typeId === 'structure' ? 'structure' : 'invocation';
      addEntry({
        key: `${kind}:${unit.cardId}`,
        kind,
        kindLabel: kind === 'structure' ? 'Estructura' : 'Invocación',
        cardId: unit.cardId,
        label: card.name || unit.cardId,
        owners: [ownerLabel],
      });
    }

    const activeGuardians = (player.guardians || []).filter(guardian => guardian?.active !== false || guardian?.destroying);
    if (activeGuardians.length) {
      const domainId = getPlayerDomainId(playerId) || 'default';
      addEntry({
        key: `guardian:${domainId}`,
        kind: 'guardian',
        kindLabel: 'Estructura / Guardián',
        label: `Guardián · ${getDomainTheme(domainId)?.label || domainId}`,
        owners: [ownerLabel],
      });
    }
  }

  return entries;
}

function clearTokenTuningSelectionVisuals() {
  if (!els.unitsLayer) return;
  // v568 · La selección del editor no modifica en absoluto la ficha real.
  // Limpiamos restos de versiones anteriores (clase/foil) y solo manejamos
  // el indicador azul independiente.
  els.unitsLayer.querySelectorAll('.unit.token-tuning-selected').forEach(node => node.classList.remove('token-tuning-selected'));
  els.unitsLayer.querySelectorAll('.token-tuning-editor-foil-img, .token-tuning-editor-indicator').forEach(node => node.remove());
}

function applyTokenTuningSelectionVisual(node) {
  if (!node) return;
  // No crear wrapper, clon/foil ni clase de selección sobre .unit. La ficha
  // debe conservar exactamente el mismo tamaño/render que tiene sin editor.
  if (!node.querySelector(':scope > .token-tuning-editor-indicator')) {
    const dot = document.createElement('span');
    dot.className = 'token-tuning-editor-indicator';
    dot.title = 'Ficha seleccionada para edición';
    dot.setAttribute('aria-hidden', 'true');
    node.appendChild(dot);
  }
}

function syncTokenTuningSelectionHighlight() {
  if (!els.unitsLayer) return;
  clearTokenTuningSelectionVisuals();
  if (!isTokenTuningToolOpen() || tokenTuningState.activeTab !== 'tokens') return;
  const selected = tokenTuningState.selectedKey;
  if (!selected) return;
  els.unitsLayer.querySelectorAll(`.unit[data-token-tune-key="${escapeTokenTuningSelectorValue(selected)}"]`).forEach(applyTokenTuningSelectionVisual);
}

function setTokenTuningValue(key, field, value) {
  if (!key || !['scale', 'x', 'y'].includes(field)) return;
  const current = getTokenTuning(key);
  const next = { ...current };
  if (field === 'scale') next.scale = sanitizeTokenTuningValue(value, current.scale, 0.25, 6);
  if (field === 'x') next.x = sanitizeTokenTuningValue(value, current.x, -160, 160);
  if (field === 'y') next.y = sanitizeTokenTuningValue(value, current.y, -160, 160);
  tokenTuningState.values[key] = normalizeTokenTuningRecord(next);
  persistTokenTuningSettings();
  applyTokenTuningToRenderedNodes(key);
  syncTokenTuningControls();
}

function resetTokenTuningValue(key) {
  if (!key) return;
  loadTokenTuningSettings();
  delete tokenTuningState.values[key];
  persistTokenTuningSettings();
  applyTokenTuningToRenderedNodes(key);
  const nodes = els.unitsLayer?.querySelectorAll?.(`.unit[data-token-tune-key="${escapeTokenTuningSelectorValue(key)}"]`) || [];
  nodes.forEach(node => {
    node.style.removeProperty('--rok-token-tune-scale');
    node.style.removeProperty('--rok-token-tune-x');
    node.style.removeProperty('--rok-token-tune-y');
  });
  syncTokenTuningControls();
}

function resetAllTokenTuningValues() {
  tokenTuningState.values = Object.create(null);
  persistTokenTuningSettings();
  els.unitsLayer?.querySelectorAll?.('.unit[data-token-tune-key]')?.forEach(node => {
    node.style.removeProperty('--rok-token-tune-scale');
    node.style.removeProperty('--rok-token-tune-x');
    node.style.removeProperty('--rok-token-tune-y');
  });
  syncTokenTuningControls();
}

function buildTokenTuningCss() {
  loadTokenTuningSettings();
  const entriesByKey = new Map(collectTokenTuningEntries().map(entry => [entry.key, entry]));
  const keys = Object.keys(tokenTuningState.values).filter(key => !isDefaultTokenTuning(tokenTuningState.values[key]));
  const lines = [
    '/* R.O.K Lite · Ajustes de tokens exportados desde la herramienta de prueba */',
    '/* Pegar estas reglas al final de style.css. */',
    '',
    '.unit[data-token-tune-key] > .unit-token-img,',
    '.unit[data-token-tune-key] > .unit-hitbox {',
    '  scale: var(--rok-token-tune-scale, 1);',
    '  translate: var(--rok-token-tune-x, 0px) var(--rok-token-tune-y, 0px);',
    '}',
    '',
  ];
  if (!keys.length) lines.push('/* No hay ajustes distintos de los valores base. */');
  keys.sort().forEach(key => {
    const tune = getTokenTuning(key);
    const entry = entriesByKey.get(key);
    if (entry) lines.push(`/* ${entry.sublabel}: ${entry.label} */`);
    lines.push(`.unit[data-token-tune-key="${String(key).replace(/\\/g, '\\\\').replace(/"/g, '\\"')}"] {`);
    lines.push(`  --rok-token-tune-scale: ${Number(tune.scale.toFixed(2))};`);
    lines.push(`  --rok-token-tune-x: ${Number(tune.x.toFixed(1))}px;`);
    lines.push(`  --rok-token-tune-y: ${Number(tune.y.toFixed(1))}px;`);
    lines.push('}', '');
  });
  return lines.join('\n');
}

function downloadTokenTuningCss() {
  const css = buildTokenTuningCss();
  const blob = new Blob([css], { type: 'text/css;charset=utf-8' });
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = url;
  link.download = `rok-token-ajustes-${new Date().toISOString().slice(0, 10)}.css`;
  document.body.appendChild(link);
  link.click();
  link.remove();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
  if (tokenTuningState.ui?.status) tokenTuningState.ui.status.textContent = 'Fragmento CSS generado por compatibilidad interna.';
}

function syncTokenTuningControls() {
  const ui = tokenTuningState.ui;
  if (!ui) return;
  const key = tokenTuningState.selectedKey;
  const enabled = Boolean(key);
  ui.controls.classList.toggle('disabled', !enabled);
  ui.controls.querySelectorAll('input, button[data-token-control]').forEach(node => { node.disabled = !enabled; });
  if (!enabled) return;
  const tune = getTokenTuning(key);
  const values = { scale: tune.scale, x: tune.x, y: tune.y };
  Object.entries(values).forEach(([field, value]) => {
    const range = ui.panel.querySelector(`[data-token-range="${field}"]`);
    const number = ui.panel.querySelector(`[data-token-number="${field}"]`);
    if (range) range.value = String(value);
    if (number) number.value = String(value);
  });
}

function refreshTokenTuningToolEntries() {
  const ui = tokenTuningState.ui;
  if (!ui) return;
  const entries = collectTokenTuningEntries();
  const signature = entries.map(entry => `${entry.key}:${entry.label}:${entry.sublabel}`).join('|');
  if (signature === tokenTuningState.entriesSignature) {
    syncTokenTuningSelectionHighlight();
    return;
  }
  tokenTuningState.entriesSignature = signature;
  ui.list.replaceChildren();
  entries.forEach(entry => {
    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'token-tuning-entry';
    button.dataset.tokenTuningKey = entry.key;
    button.innerHTML = `<strong>${escapeHtml(entry.label)}</strong><small>${escapeHtml(entry.sublabel)}</small>`;
    button.addEventListener('click', event => {
      event.preventDefault();
      event.stopPropagation();
      tokenTuningState.selectedKey = entry.key;
      ui.list.querySelectorAll('.token-tuning-entry').forEach(node => node.classList.toggle('active', node === button));
      ui.selected.textContent = entry.label;
      ui.status.textContent = 'Ajusta tamaño y posición. Cada pieza conserva su propio valor al cambiar de selección; token e hitbox se transforman juntos.';
      syncTokenTuningControls();
      syncTokenTuningSelectionHighlight();
    });
    ui.list.appendChild(button);
  });
  if (!entries.some(entry => entry.key === tokenTuningState.selectedKey)) {
    tokenTuningState.selectedKey = entries[0]?.key || '';
  }
  if (tokenTuningState.selectedKey) {
    const activeEntry = entries.find(entry => entry.key === tokenTuningState.selectedKey);
    ui.list.querySelectorAll('.token-tuning-entry').forEach(node => node.classList.toggle('active', node.dataset.tokenTuningKey === tokenTuningState.selectedKey));
    ui.selected.textContent = activeEntry?.label || 'Selecciona una pieza';
  } else {
    ui.selected.textContent = 'Sin piezas disponibles';
  }
  syncTokenTuningControls();
  syncTokenTuningSelectionHighlight();
}

function installTokenTuningTool() {
  if (tokenTuningState.ui || document.getElementById('tokenTuningToggle')) return;
  loadTokenTuningSettings();
  const toggle = document.createElement('button');
  toggle.type = 'button';
  toggle.id = 'tokenTuningToggle';
  toggle.className = 'token-tuning-toggle';
  toggle.textContent = 'AJUSTES VISUALES';
  toggle.title = 'Ajustar fichas y bloques completos de la interfaz';

  const panel = document.createElement('aside');
  panel.id = 'tokenTuningPanel';
  panel.className = 'token-tuning-panel';
  panel.setAttribute('aria-hidden', 'true');
  panel.innerHTML = `
    <header class="token-tuning-header">
      <div><strong>AJUSTES VISUALES</strong><small>Fichas + interfaz de combate</small></div>
      <button type="button" class="token-tuning-close" aria-label="Cerrar">×</button>
    </header>

    <div class="token-tuning-tabs" role="tablist" aria-label="Tipo de ajuste visual">
      <button type="button" class="active" data-tuning-tab="tokens" aria-pressed="true">FICHAS</button>
      <button type="button" data-tuning-tab="interface" aria-pressed="false">INTERFAZ</button>
      <button type="button" data-tuning-tab="timing" aria-pressed="false">TEMPOS</button>
    </div>

    <section class="token-tuning-pane" data-tuning-pane="tokens">
      <div class="token-tuning-list" data-token-tuning-list></div>
      <div class="token-tuning-controls" data-token-tuning-controls>
        <div class="token-tuning-selected"><small>PIEZA</small><strong data-token-selected>Selecciona una pieza</strong></div>
        <label><span>Tamaño</span><input type="range" min="0.25" max="6" step="0.01" data-token-range="scale"><input type="number" min="0.25" max="6" step="0.01" data-token-number="scale"></label>
        <label><span>Posición X</span><input type="range" min="-160" max="160" step="1" data-token-range="x"><input type="number" min="-160" max="160" step="1" data-token-number="x"></label>
        <label><span>Posición Y</span><input type="range" min="-160" max="160" step="1" data-token-range="y"><input type="number" min="-160" max="160" step="1" data-token-number="y"></label>
        <div class="token-tuning-actions">
          <button type="button" data-token-control="reset">Restablecer pieza</button>
          <button type="button" class="token-tuning-save" data-token-control="save">Guardar en style.css</button>
        </div>
        <button type="button" class="token-tuning-reset-all" data-token-control="reset-all">Restablecer todas las fichas</button>
        <p class="token-tuning-status" data-token-status>Selecciona una pieza. Guardar escribirá directamente en style.css; la primera vez tendrás que elegir ese archivo.</p>
      </div>
    </section>

    <section class="token-tuning-pane ui-tuning-pane" data-tuning-pane="interface" hidden>
      <div class="token-tuning-list ui-tuning-list" data-ui-tuning-list></div>
      <div class="token-tuning-controls ui-tuning-controls" data-ui-tuning-controls>
        <div class="token-tuning-selected">
          <small>BLOQUE</small>
          <strong data-ui-selected>Tempo / Tiempo</strong>
          <em data-ui-target-note>Combate · Reloj, velocidad y Tiempo de Pensamiento.</em>
        </div>
        <label><span>Posición X</span><input type="range" min="-1200" max="1200" step="1" data-ui-range="x"><input type="number" min="-1200" max="1200" step="1" data-ui-number="x"></label>
        <label><span>Ancho X real %</span><input type="range" min="35" max="250" step="1" data-ui-range="width"><input type="number" min="35" max="250" step="1" data-ui-number="width"></label>
        <div class="token-tuning-actions">
          <button type="button" data-ui-control="reset">Restablecer panel</button>
          <button type="button" class="token-tuning-save" data-ui-control="save">Guardar en style.css</button>
        </div>
        <button type="button" class="token-tuning-reset-all" data-ui-control="reset-all">Restablecer toda la interfaz</button>
        <p class="token-tuning-status" data-ui-status>Los sliders son un borrador en vivo. Pulsa Guardar en style.css para fijarlos en el CSS principal.</p>
      </div>
    </section>

    <section class="token-tuning-pane realtime-timing-tuning-pane" data-tuning-pane="timing" hidden>
      <div class="realtime-timing-tuning-scroll">
        <div class="realtime-timing-tuning-group">
          <strong>RECURSOS</strong>
          <label><span>Crecimiento mínimo</span><input type="number" min="1" max="120" step=".5" data-rt-timing="resourceGrowthMinSeconds"><b>s</b></label>
          <label><span>Crecimiento máximo</span><input type="number" min="1" max="180" step=".5" data-rt-timing="resourceGrowthMaxSeconds"><b>s</b></label>
          <label><span>Recarga consumido</span><input type="number" min="1" max="60" step=".5" data-rt-timing="resourceRefillSeconds"><b>s</b></label>
          <label><span>Elemento puro</span><input type="number" min="1" max="120" step=".5" data-rt-timing="pureElementPulseSeconds"><b>s</b></label>
        </div>

        <div class="realtime-timing-tuning-group">
          <strong>IA / ATAQUES</strong>
          <label><span>Decisión IA</span><input type="number" min=".5" max="20" step=".5" data-rt-timing="aiDecisionSeconds"><b>s</b></label>
          <label><span>Preparación ataque</span><input type="number" min="0" max="10" step=".25" data-rt-timing="attackPrepSeconds"><b>s</b></label>
          <label><span>Cuerpo a cuerpo</span><input type="number" min="1" max="30" step=".5" data-rt-timing="meleeAttackSeconds"><b>s</b></label>
          <label><span>Distancia</span><input type="number" min="1" max="40" step=".5" data-rt-timing="rangedAttackSeconds"><b>s</b></label>
          <label><span>Pesado / Artillería</span><input type="number" min="1" max="60" step=".5" data-rt-timing="heavyAttackSeconds"><b>s</b></label>
        </div>

        <div class="realtime-timing-tuning-group">
          <strong>KASTEO PROGRESIVO</strong>
          <label><span>Cooldown</span><input type="number" min="0" max="30" step=".5" data-rt-timing="progressiveCooldownSeconds"><b>s</b></label>
          <label><span>Ventana para recastear</span><input type="number" min="1" max="30" step=".5" data-rt-timing="progressiveWindowSeconds"><b>s</b></label>
        </div>

        <div class="realtime-speed-reference">
          <strong>VELOCIDAD → MOVIMIENTO</strong>
          <span>V5 · 1s</span><span>V4 · 2s</span><span>V3 · 3s</span><span>V2 · 4s</span><span>V1 · 5s</span>
        </div>

        <button type="button" class="token-tuning-reset-all" data-rt-timing-reset>Restablecer tempos recomendados</button>
        <p class="token-tuning-status" data-rt-timing-status>Los cambios se aplican al cerrar AJUSTES VISUALES. La partida permanece pausada mientras calibras.</p>
      </div>
    </section>
`;
  document.body.append(toggle, panel);
  applySavedTokenTuningPanelPosition(panel);
  bindTokenTuningPanelDrag(panel);

  const ui = tokenTuningState.ui = {
    toggle,
    panel,
    list: panel.querySelector('[data-token-tuning-list]'),
    controls: panel.querySelector('[data-token-tuning-controls]'),
    selected: panel.querySelector('[data-token-selected]'),
    status: panel.querySelector('[data-token-status]'),
    uiList: panel.querySelector('[data-ui-tuning-list]'),
    uiControls: panel.querySelector('[data-ui-tuning-controls]'),
    uiSelected: panel.querySelector('[data-ui-selected]'),
    uiTargetNote: panel.querySelector('[data-ui-target-note]'),
    uiStatus: panel.querySelector('[data-ui-status]'),
    timingStatus: panel.querySelector('[data-rt-timing-status]'),
  };

  const setOpen = open => {
    const wasOpen = panel.classList.contains('open');
    panel.classList.toggle('open', open);
    panel.setAttribute('aria-hidden', open ? 'false' : 'true');
    toggle.classList.toggle('active', open);
    if (open) {
      applySavedTokenTuningPanelPosition(panel);
      if (!wasOpen) acquireTokenTuningGameplayPause();
      applyUiTuningSettings();
      setTokenTuningEditorTab(tokenTuningState.activeTab || 'tokens');
    } else {
      clearTokenTuningSelectionVisuals();
      clearUiTuningSelectionHighlight();
      if (wasOpen) releaseTokenTuningGameplayPause();
    }
  };
  toggle.addEventListener('click', event => { event.preventDefault(); event.stopPropagation(); setOpen(!panel.classList.contains('open')); });
  panel.querySelector('.token-tuning-close')?.addEventListener('click', event => { event.preventDefault(); event.stopPropagation(); setOpen(false); });
  panel.addEventListener('pointerdown', event => event.stopPropagation());
  panel.addEventListener('click', event => event.stopPropagation());
  panel.addEventListener('wheel', event => event.stopPropagation(), { passive: true });

  ['scale', 'x', 'y'].forEach(field => {
    const range = panel.querySelector(`[data-token-range="${field}"]`);
    const number = panel.querySelector(`[data-token-number="${field}"]`);
    const update = source => {
      if (!tokenTuningState.selectedKey) return;
      setTokenTuningValue(tokenTuningState.selectedKey, field, source.value);
    };
    range?.addEventListener('input', () => update(range));
    number?.addEventListener('input', () => update(number));
  });
  panel.querySelector('[data-token-control="reset"]')?.addEventListener('click', () => resetTokenTuningValue(tokenTuningState.selectedKey));
  panel.querySelector('[data-token-control="reset-all"]')?.addEventListener('click', () => {
    if (window.confirm?.('¿Restablecer todos los ajustes temporales de tokens?') === false) return;
    resetAllTokenTuningValues();
    if (ui.status) ui.status.textContent = 'Todos los ajustes volvieron a sus valores base.';
  });
  panel.querySelector('[data-token-control="save"]')?.addEventListener('click', () => {
    void saveRokVisualSettingsDirectToCss('AJUSTES VISUALES · Fichas');
  });

  panel.querySelectorAll('[data-tuning-tab]').forEach(button => {
    button.addEventListener('click', event => {
      event.preventDefault();
      event.stopPropagation();
      setTokenTuningEditorTab(button.dataset.tuningTab);
    });
  });

  ['x', 'width'].forEach(field => {
    const range = panel.querySelector(`[data-ui-range="${field}"]`);
    const number = panel.querySelector(`[data-ui-number="${field}"]`);
    const update = source => {
      if (!tokenTuningState.selectedUiKey) return;
      const raw = Number(source.value);
      const normalized = field === 'x' ? raw : raw / 100;
      setUiTuningValue(tokenTuningState.selectedUiKey, field, normalized);
    };
    range?.addEventListener('input', () => update(range));
    number?.addEventListener('input', () => update(number));
  });

  panel.querySelector('[data-ui-control="reset"]')?.addEventListener('click', () => resetUiTuningValue(tokenTuningState.selectedUiKey));
  panel.querySelector('[data-ui-control="reset-all"]')?.addEventListener('click', () => {
    if (window.confirm?.('¿Restablecer todos los ajustes temporales de interfaz?') === false) return;
    resetAllUiTuningValues();
    if (ui.uiStatus) ui.uiStatus.textContent = 'Todos los bloques volvieron a sus valores base.';
  });
  panel.querySelector('[data-ui-control="save"]')?.addEventListener('click', () => {
    void saveRokVisualSettingsDirectToCss('AJUSTES VISUALES · Interfaz');
  });

  panel.querySelectorAll('[data-rt-timing]').forEach(input => {
    input.addEventListener('input', () => {
      const key = input.dataset.rtTiming;
      setRealtimeTimingTuningValue(key, input.value, { reschedule: true });
      if (ui.timingStatus) ui.timingStatus.textContent = 'Tempo actualizado. Cierra AJUSTES VISUALES para reanudar y probarlo.';
    });
  });
  panel.querySelector('[data-rt-timing-reset]')?.addEventListener('click', () => {
    resetRealtimeTimingTuning();
    if (ui.timingStatus) ui.timingStatus.textContent = 'Tempos restablecidos a la base de prueba.';
  });

  applyUiTuningSettings();
  refreshTokenTuningToolEntries();
  buildUiTuningEntries();
  setTokenTuningEditorTab('tokens');
}


function normalizeUiTuningRecord(value = null) {
  return {
    x: Number(sanitizeTokenTuningValue(value?.x, value?.y ?? 0, -1200, 1200).toFixed(1)),
    width: Number(sanitizeTokenTuningValue(value?.width, 1, 0.35, 2.5).toFixed(2)),
  };
}

function loadUiTuningSettings() {
  if (tokenTuningState.uiLoaded) return tokenTuningState.uiValues;
  tokenTuningState.uiLoaded = true;

  if (ROK_DIRECT_CSS_CANONICAL_ON_BOOT) {
    try {
      localStorage.removeItem(ROK_UI_TUNING_STORAGE_KEY);
      localStorage.removeItem(ROK_UI_TUNING_LEGACY_STORAGE_KEY);
    } catch (_) {}
    return tokenTuningState.uiValues;
  }

  try {
    let raw = localStorage.getItem(ROK_UI_TUNING_STORAGE_KEY);
    let legacy = false;
    if (!raw) {
      raw = localStorage.getItem(ROK_UI_TUNING_LEGACY_STORAGE_KEY);
      legacy = Boolean(raw);
    }
    const parsed = raw ? JSON.parse(raw) : null;
    if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) {
      Object.entries(parsed).forEach(([key, value]) => {
        if (!ROK_UI_TUNING_TARGETS.some(target => target.key === key)) return;
        const migrated = legacy
          ? { x: value?.x ?? value?.y ?? 0, width: value?.width ?? 1 }
          : value;
        tokenTuningState.uiValues[key] = normalizeUiTuningRecord(migrated);
      });
      if (legacy) persistUiTuningSettings();
    }
  } catch (_) {}
  return tokenTuningState.uiValues;
}

function persistUiTuningSettings() {
  loadUiTuningSettings();
  try { localStorage.setItem(ROK_UI_TUNING_STORAGE_KEY, JSON.stringify(tokenTuningState.uiValues)); } catch (_) {}
}

function getUiTuningTarget(key) {
  return ROK_UI_TUNING_TARGETS.find(target => target.key === key) || null;
}

function getUiTuningTargetNode(key) {
  const target = getUiTuningTarget(key);
  return target?.selector ? document.querySelector(target.selector) : null;
}

function getUiTuningValue(key) {
  loadUiTuningSettings();
  const cssBaseline = readUiTuningBaselineFromCss(key);
  const baseline = cssBaseline || ROK_UI_TUNING_CANONICAL_DEFAULTS[key] || ROK_UI_TUNING_DEFAULT;
  return normalizeUiTuningRecord(tokenTuningState.uiValues[key] || baseline);
}

function isDefaultUiTuning(value) {
  const tune = normalizeUiTuningRecord(value);
  return Math.abs(tune.x) < 0.001
    && Math.abs(tune.width - 1) < 0.001;
}

function getUiTuningBaseTrackWidth(target, node) {
  if (!target?.trackVar || !node) return Math.max(1, Number(node?.offsetWidth || 1));
  const body = document.body;
  const previous = body.style.getPropertyValue(target.trackVar);
  const previousPriority = body.style.getPropertyPriority(target.trackVar);
  body.style.removeProperty(target.trackVar);

  // offsetWidth is layout width before transforms and therefore gives us the
  // real default track width in logical CSS pixels.
  const width = Math.max(1, Number(node.offsetWidth || 1));

  if (previous) body.style.setProperty(target.trackVar, previous, previousPriority);
  return width;
}


function captureUiTuningIntrinsicMetrics(target, node) {
  if (!target || !node || node.dataset.rokUiIntrinsicCaptured === '1') return;
  node.dataset.rokUiIntrinsicCaptured = '1';

  const setPx = (name, value) => {
    const n = Number(value || 0);
    if (n > 0.5) node.style.setProperty(name, `${Number(n.toFixed(2))}px`);
  };

  if (target.key === 'spellbook') {
    const slot = node.querySelector('.card-slot');
    if (slot) setPx('--rok-ui-intrinsic-card-slot-w', slot.offsetWidth);
  }

  if (target.key === 'tempo') {
    const contentCandidates = [
      node.querySelector('.realtime-tempo-controls'),
      node.querySelector('.realtime-thought-button'),
      node.querySelector('.phase-box'),
      node.querySelector('.next-phase-vertical'),
    ].filter(Boolean);
    const widest = contentCandidates.reduce((max, el) => Math.max(max, Number(el.offsetWidth || 0)), 0);
    if (widest) setPx('--rok-ui-intrinsic-tempo-content-w', widest);
  }

  if (target.key === 'combat-modes') {
    const card = node.querySelector('.invocation-control-card');
    const status = node.querySelector('.invocation-control-statuses .selected-unit-command-status');
    const modeButton = node.querySelector('.invocation-panel-mode-btn');
    const actionButton = node.querySelector('.invocation-control-actions .selected-unit-command-btn');
    if (card) setPx('--rok-ui-intrinsic-invocation-card-w', card.offsetWidth);
    if (status) setPx('--rok-ui-intrinsic-invocation-status-w', status.offsetWidth);
    if (modeButton) setPx('--rok-ui-intrinsic-mode-btn-w', modeButton.offsetWidth);
    if (actionButton) setPx('--rok-ui-intrinsic-invocation-action-w', actionButton.offsetWidth);
  }

  if (target.key === 'caster-rival' || target.key === 'caster-ally') {
    const card = node.querySelector('.caster-hud-card');
    const stat = node.querySelector('.caster-hud-stat');
    if (card) setPx('--rok-ui-intrinsic-caster-card-w', card.offsetWidth);
    if (stat) setPx('--rok-ui-intrinsic-caster-stat-w', stat.offsetWidth);
  }
}

function clearUiTuningWidthForTarget(target, node) {
  if (target?.trackVar) document.body.style.removeProperty(target.trackVar);
  if (node) {
    node.style.removeProperty('width');
    node.style.removeProperty('max-width');
    node.style.removeProperty('min-width');
    node.style.removeProperty('justify-self');
  }
}

function applyUiTuningToNode(node, key) {
  if (!node || !key) return;
  const target = getUiTuningTarget(key);
  if (!target) return;
  const tune = getUiTuningValue(key);

  node.dataset.rokUiTuneKey = key;
  node.classList.add('rok-ui-tuning-calibrated');
  captureUiTuningIntrinsicMetrics(target, node);

  // Posición X sí es un transform: solo desplaza el panel y no intenta
  // redimensionar el contenido.
  node.style.setProperty('--rok-ui-tune-x', `${tune.x}px`);

  // RT-08.9 · ANCHO REAL.
  // Para carriles del HUD se modifica la pista del CSS Grid. Esto hace que
  // hijos, texto, botones, scroll y miniaturas vuelvan a distribuirse dentro
  // del nuevo espacio; no se escalan ni deforman.
  if (target.trackVar) {
    const body = document.body;
    const previous = body.style.getPropertyValue(target.trackVar);
    const previousPriority = body.style.getPropertyPriority(target.trackVar);
    body.style.removeProperty(target.trackVar);
    const baseWidth = Math.max(1, Number(node.offsetWidth || 1));
    if (previous) body.style.setProperty(target.trackVar, previous, previousPriority);

    const wantedWidth = Math.max(24, Number((baseWidth * tune.width).toFixed(2)));
    body.style.setProperty(target.trackVar, `${wantedWidth}px`);
    node.style.removeProperty('width');
    node.style.removeProperty('max-width');
    node.style.removeProperty('min-width');
    return;
  }

  // Bloques que no son una pista individual del grid (Kaster y Arena):
  // width cambia la caja de layout de verdad. No existe scaleX.
  if (target.layoutWidth) {
    const wantedPercent = `${Math.max(10, tune.width * 100)}%`;
    node.style.setProperty('width', wantedPercent, 'important');
    node.style.setProperty('max-width', 'none', 'important');
    node.style.setProperty('min-width', '0', 'important');
    node.style.setProperty('justify-self', 'center', 'important');
  }
}

function applyUiTuningSettings(key = '') {
  loadUiTuningSettings();
  const targets = key ? ROK_UI_TUNING_TARGETS.filter(target => target.key === key) : ROK_UI_TUNING_TARGETS;
  targets.forEach(target => {
    const node = getUiTuningTargetNode(target.key);
    if (node) applyUiTuningToNode(node, target.key);
  });
  syncUiTuningSelectionHighlight();
  try { window.ROK_PROPORTIONAL_MODULES?.refresh?.(); } catch (_) {}
}

function clearUiTuningStyleFromNode(node) {
  if (!node) return;
  const key = node.dataset.rokUiTuneKey || '';
  const target = getUiTuningTarget(key);
  if (target) clearUiTuningWidthForTarget(target, node);
  node.classList.remove('rok-ui-tuning-calibrated');
  node.classList.remove('rok-ui-tuning-selected');
  delete node.dataset.rokUiTuneKey;
  node.style.removeProperty('--rok-ui-tune-x');
}

function clearUiTuningSelectionHighlight() {
  ROK_UI_TUNING_TARGETS.forEach(target => {
    getUiTuningTargetNode(target.key)?.classList.remove('rok-ui-tuning-selected');
  });
}

function syncUiTuningSelectionHighlight() {
  clearUiTuningSelectionHighlight();
  if (!isTokenTuningToolOpen() || tokenTuningState.activeTab !== 'interface') return;
  const node = getUiTuningTargetNode(tokenTuningState.selectedUiKey);
  if (node) node.classList.add('rok-ui-tuning-selected');
}

function setUiTuningValue(key, field, value) {
  if (!key || !['x', 'width'].includes(field) || !getUiTuningTarget(key)) return;
  const current = getUiTuningValue(key);
  const next = { ...current };
  if (field === 'x') next.x = sanitizeTokenTuningValue(value, current.x, -1200, 1200);
  if (field === 'width') next.width = sanitizeTokenTuningValue(value, current.width, 0.35, 2.5);
  tokenTuningState.uiValues[key] = normalizeUiTuningRecord(next);
  persistUiTuningSettings();
  applyUiTuningSettings(key);
  syncUiTuningControls();
}

function resetUiTuningValue(key) {
  const target = getUiTuningTarget(key);
  if (!key || !target) return;
  loadUiTuningSettings();
  delete tokenTuningState.uiValues[key];
  persistUiTuningSettings();
  const node = getUiTuningTargetNode(key);
  clearUiTuningWidthForTarget(target, node);
  clearUiTuningStyleFromNode(node);
  if (node) applyUiTuningToNode(node, key);
  syncUiTuningControls();
  syncUiTuningSelectionHighlight();
}

function resetAllUiTuningValues() {
  tokenTuningState.uiValues = Object.create(null);
  persistUiTuningSettings();
  ROK_UI_TUNING_TARGETS.forEach(target => {
    const node = getUiTuningTargetNode(target.key);
    clearUiTuningWidthForTarget(target, node);
    clearUiTuningStyleFromNode(node);
    if (node) applyUiTuningToNode(node, target.key);
  });
  syncUiTuningControls();
  syncUiTuningSelectionHighlight();
}

function syncUiTuningControls() {
  const ui = tokenTuningState.ui;
  if (!ui?.uiControls) return;
  const key = tokenTuningState.selectedUiKey;
  const target = getUiTuningTarget(key);
  const enabled = Boolean(target && getUiTuningTargetNode(key));
  ui.uiControls.classList.toggle('disabled', !enabled);
  ui.uiControls.querySelectorAll('input, button[data-ui-control]').forEach(node => { node.disabled = !enabled; });

  if (ui.uiSelected) ui.uiSelected.textContent = target?.label || 'Selecciona un bloque';
  if (ui.uiTargetNote) {
    ui.uiTargetNote.textContent = target
      ? `${target.scope} · ${target.note}`
      : 'Selecciona un bloque de la interfaz.';
  }
  if (!target) return;

  const tune = getUiTuningValue(key);
  const values = { x: tune.x, width: tune.width };
  Object.entries(values).forEach(([field, value]) => {
    const range = ui.panel.querySelector(`[data-ui-range="${field}"]`);
    const number = ui.panel.querySelector(`[data-ui-number="${field}"]`);
    const displayValue = field === 'x' ? value : Math.round(value * 100);
    if (range) range.value = String(displayValue);
    if (number) number.value = String(displayValue);
  });
}

function buildUiTuningEntries() {
  const ui = tokenTuningState.ui;
  if (!ui?.uiList) return;
  ui.uiList.replaceChildren();
  ROK_UI_TUNING_TARGETS.forEach(target => {
    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'token-tuning-entry ui-tuning-entry';
    button.dataset.uiTuningKey = target.key;
    button.innerHTML = `<strong>${escapeHtml(target.label)}</strong><small>${escapeHtml(target.scope)}</small>`;
    button.addEventListener('click', event => {
      event.preventDefault();
      event.stopPropagation();
      tokenTuningState.selectedUiKey = target.key;
      ui.uiList.querySelectorAll('.ui-tuning-entry').forEach(node => node.classList.toggle('active', node === button));
      if (ui.uiStatus) ui.uiStatus.textContent = 'Posición X mueve el bloque horizontalmente. Ancho X cambia el ancho REAL del contenedor para que su contenido se redistribuya dentro.';
      syncUiTuningControls();
      syncUiTuningSelectionHighlight();
    });
    ui.uiList.appendChild(button);
  });
  ui.uiList.querySelectorAll('.ui-tuning-entry').forEach(node => {
    node.classList.toggle('active', node.dataset.uiTuningKey === tokenTuningState.selectedUiKey);
  });
  syncUiTuningControls();
  syncUiTuningSelectionHighlight();
}

function setTokenTuningEditorTab(tab = 'tokens') {
  const ui = tokenTuningState.ui;
  if (!ui) return;
  const next = tab === 'interface' ? 'interface' : (tab === 'timing' ? 'timing' : 'tokens');
  tokenTuningState.activeTab = next;

  ui.panel.querySelectorAll('[data-tuning-tab]').forEach(button => {
    const active = button.dataset.tuningTab === next;
    button.classList.toggle('active', active);
    button.setAttribute('aria-pressed', active ? 'true' : 'false');
  });
  ui.panel.querySelectorAll('[data-tuning-pane]').forEach(pane => {
    pane.hidden = pane.dataset.tuningPane !== next;
  });

  if (next === 'tokens') {
    clearUiTuningSelectionHighlight();
    refreshTokenTuningToolEntries();
    syncTokenTuningSelectionHighlight();
  } else if (next === 'interface') {
    clearTokenTuningSelectionVisuals();
    buildUiTuningEntries();
    applyUiTuningSettings();
    syncUiTuningSelectionHighlight();
  } else {
    clearTokenTuningSelectionVisuals();
    clearUiTuningSelectionHighlight();
    syncRealtimeTimingTuningControls();
  }
}


function syncRealtimeTimingTuningControls() {
  const panel = tokenTuningState.ui?.panel;
  if (!panel) return;
  const values = getRealtimeTimingTuning();
  const canEdit = !isOnlineMatchActive() || isRealtimeOnlineAuthority();
  panel.querySelectorAll('[data-rt-timing]').forEach(input => {
    const key = input.dataset.rtTiming;
    if (document.activeElement !== input) input.value = String(values[key] ?? '');
    input.disabled = !canEdit;
  });
  const reset = panel.querySelector('[data-rt-timing-reset]');
  if (reset) reset.disabled = !canEdit;
  if (tokenTuningState.ui?.timingStatus && !canEdit) {
    tokenTuningState.ui.timingStatus.textContent = 'En PvP Online solo el Host puede modificar los tempos autoritativos.';
  }
}

function buildUiTuningCss() {
  loadUiTuningSettings();
  const lines = [
    '/* R.O.K Lite · RT-08.6 · Ajustes de interfaz exportados */',
    '',
  ];
  const changed = ROK_UI_TUNING_TARGETS.filter(target => !isDefaultUiTuning(getUiTuningValue(target.key)));
  if (!changed.length) {
    lines.push('/* No hay ajustes de interfaz distintos de los valores base. */');
    return lines.join('\\n');
  }
  changed.forEach(target => {
    const tune = getUiTuningValue(target.key);
    lines.push(`/* ${target.label} */`);
    lines.push(`${target.selector} {`);
    lines.push(`  --rok-ui-tune-x: ${Number(tune.x.toFixed(1))}px;`);
    lines.push(`  /* Ancho de contenedor: ${Math.round(tune.width * 100)}% del track/caja base; contenido interno no se escala */`);
    lines.push('}', '');
  });
  return lines.join('\\n');
}

function downloadUiTuningCss() {
  const cssText = buildUiTuningCss();
  const blob = new Blob([cssText], { type: 'text/css;charset=utf-8' });
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = url;
  link.download = `rok-ui-ajustes-${new Date().toISOString().slice(0, 10)}.css`;
  document.body.appendChild(link);
  link.click();
  link.remove();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
  if (tokenTuningState.ui?.uiStatus) {
    tokenTuningState.ui.uiStatus.textContent = 'Fragmento CSS de interfaz generado por compatibilidad interna.';
  }
}


function getCasterPersistentInvocationCast(playerId) {
  const player = state.players?.[playerId];
  const activeItem = player?.castQueue?.[0] || null;
  if (!activeItem) return null;
  const card = CARD_LIBRARY[activeItem.cardId];
  if (!card || !['invocation', 'spell', 'structure'].includes(getCardTypeId(card))) return null;
  if (getEffectiveCastPhasesForCard(card) < 1) return null;
  if (Number(activeItem.remaining ?? 0) < 1) return null;
  return { item: activeItem, card };
}

function renderUnits() {
  if (!els.unitsLayer) return;
  // Construir fuera del DOM vivo evita invalidar layout por cada ficha. La capa
  // completa se intercambia una sola vez al final de la pasada.
  const fragment = document.createDocumentFragment();
  for (const playerId of [1, 2]) {
    const player = state.players?.[playerId];
    if (!player?.caster) continue;
    const guardians = Array.isArray(player.guardians) ? player.guardians : [];
    const units = Array.isArray(player.units) ? player.units : [];
    renderUnit(
      player.caster.row,
      player.caster.col,
      'caster',
      getCasterTokenImage(player.caster),
      getCasterDisplayName(player.caster, `Kaster J${playerId}`),
      playerId,
      null,
      getPlayerElementColor(playerId),
      null,
      null,
      { target: fragment },
    );
    guardians
      .filter(g => g.active !== false || g.destroying)
      .forEach((g, index) => renderUnit(
        g.row,
        g.col,
        'guardian',
        isUmbralFugazPortalGuardian(g) ? UMBRAL_FUGAZ_PORTAL_ASSET : getGuardianAssetForPlayer(playerId),
        isUmbralFugazPortalGuardian(g) ? `Umbral Fugaz ${g.portalEndpoint || ''}` : `Guardián ${index + 1} · RES ${g.resistance ?? 5}`,
        playerId,
        null,
        getOwnerColor(playerId),
        null,
        g.id,
        { target: fragment },
      ));
    units.forEach(unit => {
      if (unit.restoreAnimating) return;
      // PvP: Oculto es información visual privada. El propietario conserva su
      // ficha como referencia semitransparente; el rival no recibe ningún nodo
      // DOM de esa invocación, por lo que tampoco ve hitbox, stats ni badges.
      if (isOnlineUnitConcealedFromViewer(playerId, unit)) return;
      const card = CARD_LIBRARY[unit.cardId];
      if (!card) return;
      const element = getElementById(getUnitElementId(playerId, unit));
      renderUnit(
        unit.row,
        unit.col,
        'invocation',
        card.tokenImage,
        card.name,
        playerId,
        unit.spawnId,
        element?.color || '#ffffff',
        unit.id,
        null,
        { target: fragment },
      );
    });
  }
  els.unitsLayer.replaceChildren(fragment);
  try { syncRealtimeDirectionalUnitFx(); } catch (_) {}
  resumeRealtimeSmoothTransitionsInLayer();
  renderRealtimeCasterDestinationCue();
  renderKaguyaChargeFxLayer();
  refreshTokenTuningToolEntries();
  syncTokenTuningSelectionHighlight();
}


function ensureKaguyaChargeFxLayer() {
  if (els.kaguyaChargeFxLayer) return els.kaguyaChargeFxLayer;
  if (!els.boardContent) return null;
  els.kaguyaChargeFxLayer = document.createElement('div');
  els.kaguyaChargeFxLayer.id = 'kaguyaChargeFxLayer';
  els.kaguyaChargeFxLayer.className = 'kaguya-charge-fx-layer';
  els.boardContent.insertBefore(els.kaguyaChargeFxLayer, els.unitsLayer || null);
  return els.kaguyaChargeFxLayer;
}

function renderKaguyaChargeFxLayer() {
  const layer = ensureKaguyaChargeFxLayer();
  if (!layer) return;
  const activeKeys = new Set();
  for (const playerId of [1, 2]) {
    const player = state.players?.[playerId];
    const units = Array.isArray(player?.units) ? player.units : [];
    units.forEach(unit => {
      const visual = getKaguyaChargeVisualState(unit);
      if (!visual?.active || unit.status === 'restoring' || unit.restoreAnimating) return;
      if (isOnlineUnitConcealedFromViewer(playerId, unit)) return;
      const key = `p${playerId}_${unit.id}`;
      activeKeys.add(key);
      let node = layer.querySelector(`[data-kaguya-fx-key="${key}"]`);
      if (!node) {
        node = document.createElement('div');
        node.className = 'kaguya-charge-persistent-fx unit-card-samuraiKaguya';
        node.dataset.kaguyaFxKey = key;
        node.setAttribute('aria-hidden', 'true');
        node.innerHTML = '<span class="kaguya-charge-aura"></span><span class="kaguya-charge-ring kaguya-charge-ring-a"></span><span class="kaguya-charge-ring kaguya-charge-ring-b"></span><span class="kaguya-charge-sparks"></span>';
        layer.appendChild(node);
      }
      node.classList.remove('kaguya-charge-primed', 'kaguya-charge-channeling');
      applyKaguyaChargeVisualStyles(node, visual);
      const motionKey = getRealtimeSmoothMotionKey('invocation', playerId, unit.id);
      const pos = (isRealtimePlayStyle() && state?.realtime?.active)
        ? getRealtimeSmoothMotionSample(motionKey, unit.row, unit.col)
        : cellCenter(unit.row, unit.col);
      node.style.left = `${pos.x}%`;
      node.style.top = `${pos.y}%`;
      node.style.zIndex = String(185 + unit.row);
    });
  }
  [...layer.querySelectorAll('[data-kaguya-fx-key]')].forEach(node => {
    if (!activeKeys.has(node.dataset.kaguyaFxKey)) node.remove();
  });
}

function getQuickReactionVisualCandidate(playerId, type, unitId = null, guardianId = null) {
  const flow = state.quickReactionWindow || {};
  const root = Number(playerId) === Number(LOCAL_PLAYER_ID) ? els.quickReactionWindow : els.rivalQuickReactionWindow;
  const promptVisible = Boolean(root?.classList?.contains('visible'));
  const dockVisible = Number(playerId) === Number(LOCAL_PLAYER_ID)
    && Boolean(document.getElementById('quickReactionCommandDock')?.classList?.contains('visible'));
  const modalVisible = Number(playerId) === Number(LOCAL_PLAYER_ID)
    && Boolean(els.quickReactionModal?.classList?.contains('visible'));
  const introForPlayer = Boolean(flow.phaseIntro && Number(flow.phaseIntro.playerId) === Number(playerId));
  const activeForPlayer = Boolean((flow.active || flow.locked || flow.executing) && Number(flow.playerId) === Number(playerId));
  if (!promptVisible && !dockVisible && !modalVisible && !introForPlayer && !activeForPlayer) return null;
  const candidates = flow.candidatesByPlayer?.[playerId]
    || (Number(flow.playerId) === Number(playerId) ? flow.candidates : [])
    || [];
  return candidates.find(candidate => {
    const candidateIsCaster = candidate?.type === 'casterAbility' || candidate?.selectionType === 'caster';
    if (type === 'caster') return candidateIsCaster;
    if (candidateIsCaster || candidate?.selectionType === 'spell' || candidate?.type === 'kouutenRecast') return false;
    if (type === 'invocation') {
      return candidate?.unitId != null && unitId != null && String(candidate.unitId) === String(unitId);
    }
    if (type === 'guardian') {
      return candidate?.guardianId != null && guardianId != null && String(candidate.guardianId) === String(guardianId);
    }
    return false;
  }) || null;
}

function arenaSelectionTargetMatchesRenderedUnit(target, playerId, type, unitId = null, guardianId = null) {
  if (!target || playerId == null) return false;
  const targetPlayerId = Number(target.playerId ?? target.owner ?? target.ownerId);
  if (Number.isFinite(targetPlayerId) && targetPlayerId !== Number(playerId)) return false;
  const targetType = String(target.type || 'invocation').toLowerCase();
  if (type === 'caster') return targetType === 'caster';
  if (type === 'guardian') {
    return targetType === 'guardian'
      && String(target.guardianId ?? target.id ?? '') === String(guardianId ?? '');
  }
  if (type === 'invocation') {
    return targetType === 'invocation'
      && String(target.unitId ?? target.id ?? '') === String(unitId ?? '');
  }
  return false;
}

function getStandardArenaSelectionInfo(playerId, type, unitId = null, guardianId = null) {
  const pending = state.pendingPowerAction;
  if (!pending || playerId == null) return null;
  const sourcePlayerId = Number(pending.playerId);
  const renderedPlayerId = Number(playerId);
  const unit = type === 'invocation' && unitId != null ? getUnitById(renderedPlayerId, unitId) : null;
  const matchesAnyTarget = targets => (Array.isArray(targets) ? targets : []).some(target =>
    arenaSelectionTargetMatchesRenderedUnit(target, renderedPlayerId, type, unitId, guardianId));
  const matchesAnyUnit = units => type === 'invocation' && !!unit && (Array.isArray(units) ? units : []).some(candidate =>
    Number(candidate?.owner ?? sourcePlayerId) === renderedPlayerId && String(candidate?.id ?? '') === String(unitId ?? ''));

  switch (pending.kind) {
    case 'despliegueAnticipadoTarget':
      if (renderedPlayerId === sourcePlayerId && matchesAnyUnit(getEligibleDespliegueAnticipadoTargets(sourcePlayerId))) return { title: 'Objetivo seleccionable' };
      break;
    case 'gloriaLatenteTarget':
      if (renderedPlayerId === sourcePlayerId && matchesAnyUnit(getSelectableGloriaLatenteTargets(sourcePlayerId))) return { title: 'Objetivo seleccionable' };
      break;
    case 'shirahadoriAbilityTarget':
      if (renderedPlayerId === sourcePlayerId && matchesAnyUnit(getEligibleShirahadoriAbilityUsers(sourcePlayerId))) return { title: 'Puede aprender Shirahadori' };
      break;
    case 'minokageShippuUgachi': {
      const sourceUnit = getUnitById(sourcePlayerId, pending.unitId);
      if (sourceUnit && matchesAnyTarget(getMinokagePowerTargets(sourcePlayerId, sourceUnit))) return { title: 'Objetivo de Shippū Ugachi' };
      break;
    }
    case 'kaguyaChargedShot': {
      const sourceUnit = getUnitById(sourcePlayerId, pending.unitId);
      if (sourceUnit && matchesAnyTarget(getKaguyaChargedShotTargets(sourcePlayerId, sourceUnit))) return { title: 'Objetivo de Disparo energizado' };
      break;
    }
    case 'kurayamiMark': {
      const sourceUnit = getUnitById(sourcePlayerId, pending.unitId);
      if (renderedPlayerId === Number(getOpponentId(sourcePlayerId)) && matchesAnyUnit(getKurayamiPowerTargets(sourcePlayerId, sourceUnit))) return { title: 'Objetivo seleccionable' };
      break;
    }
    case 'yasuganaBlindness':
    case 'yasuganaVigilia': {
      const sourceUnit = getUnitById(sourcePlayerId, pending.unitId);
      const targets = pending.kind === 'yasuganaBlindness'
        ? getYasuganaBlindnessTargets(sourcePlayerId, sourceUnit)
        : getYasuganaVigiliaTargets(sourcePlayerId, sourceUnit);
      if (matchesAnyUnit(targets)) return { title: pending.kind === 'yasuganaBlindness' ? 'Objetivo de Ceguera' : 'Puede aprender Vigilia' };
      break;
    }
    case 'gioshoninSupply': {
      const sourceUnit = getUnitById(sourcePlayerId, pending.unitId);
      if (renderedPlayerId === sourcePlayerId && matchesAnyUnit(getAffordableGioshoninSupplyTargets(sourcePlayerId, sourceUnit))) return { title: 'Objetivo de Mercancía de guerra' };
      break;
    }
    case 'tacticaGuerraSelection':
      if (renderedPlayerId === sourcePlayerId && matchesAnyUnit(getEligibleTacticaGuerraTargets(sourcePlayerId, { quickOnly: pending.quickDefense === true, requirePayable: false }))) return { title: 'Seleccionable para Táctica de guerra' };
      break;
    case 'emboscadaRivalSelection':
      if (renderedPlayerId === Number(getEnemyPlayerId(sourcePlayerId)) && matchesAnyUnit(getEmboscadaRivalCandidates(sourcePlayerId))) return { title: 'Objetivo de Emboscada' };
      break;
    case 'emboscadaAlliedSelection':
      if (renderedPlayerId === sourcePlayerId && matchesAnyUnit(getEmboscadaAlliedCandidates(sourcePlayerId))) return { title: 'Seleccionable para Emboscada' };
      break;
    case 'interceptarAlliedSelection': {
      const targets = getInterceptarAlliedCandidates(sourcePlayerId).filter(ally => getInterceptarRivalCandidates(sourcePlayerId, ally).length > 0);
      if (renderedPlayerId === sourcePlayerId && matchesAnyUnit(targets)) return { title: 'Seleccionable para Interceptar' };
      break;
    }
    case 'interceptarRivalSelection': {
      const allied = getUnitById(sourcePlayerId, pending.selectedAlliedUnitId);
      if (renderedPlayerId === Number(getEnemyPlayerId(sourcePlayerId)) && matchesAnyUnit(getInterceptarRivalCandidates(sourcePlayerId, allied))) return { title: 'Objetivo de Interceptar' };
      break;
    }
    default:
      break;
  }
  return null;
}

function applyStandardArenaSelectionVisual(div, src, title = 'Seleccionable') {
  if (!div || !src) return false;
  div.classList.add('unit-selection-standard-ready');
  if (!div.querySelector(':scope > .unit-selection-standard-foil-img')) {
    const foil = document.createElement('img');
    foil.className = 'action-window-token-foil-img unit-selection-standard-foil-img';
    foil.src = src;
    foil.alt = '';
    foil.draggable = false;
    foil.setAttribute('aria-hidden', 'true');
    div.appendChild(foil);
  }
  const protectedLayer = div.querySelector('.unit-protected-icons-layer') || div;
  if (!protectedLayer.querySelector(':scope > .unit-selection-standard-ready-indicator')) {
    const dot = document.createElement('span');
    dot.className = 'unit-action-ready-indicator unit-selection-standard-ready-indicator';
    dot.title = title;
    protectedLayer.appendChild(dot);
  }
  return true;
}

function getRealtimeRenderedCasterPoint(playerId) {
  const caster = state?.players?.[playerId]?.caster;
  if (!caster) return null;
  const row = Number(caster.row || 0);
  const col = Number(caster.col || 0);
  if (!isRealtimePlayStyle() || !state?.realtime?.active) return cellCenter(row, col);
  const key = getRealtimeSmoothMotionKey('caster', Number(playerId), 'caster');
  return getRealtimeSmoothMotionSample(key, row, col);
}

// v9.44 · Para la flecha de pertenencia la referencia autoritativa VISUAL es
// el centro renderizado del sprite, no una de cuatro direcciones de cuadrícula.
// Así también se respetan offsets/escala del afinador de fichas.
function getDirectionalRenderedNodeCenter(node) {
  if (!node || typeof node.getBoundingClientRect !== 'function') return null;
  const token = node.querySelector?.(':scope > .unit-token-img') || node;
  const rect = token?.getBoundingClientRect?.();
  if (!rect || !Number.isFinite(rect.left) || !Number.isFinite(rect.top) || rect.width <= 0 || rect.height <= 0) return null;
  return {
    x: rect.left + (rect.width / 2),
    y: rect.top + (rect.height / 2),
    source: 'dom',
  };
}

function getDirectionalRenderedCasterCenter(playerId) {
  const casterNode = els.unitsLayer?.querySelector?.(`.unit.caster[data-player-id="${Number(playerId)}"]`) || null;
  return getDirectionalRenderedNodeCenter(casterNode);
}

function getInvocationSideMarkerAngle(row, col, controllerPlayerId, ownerPlayerId = controllerPlayerId, unitId = '', renderedUnitNode = null) {
  // Primero usamos las posiciones visuales reales en píxeles. Esto produce un
  // ángulo continuo incluso en diagonales y mientras hay offsets/escala.
  let casterPoint = getDirectionalRenderedCasterCenter(Number(controllerPlayerId));
  let unitPoint = getDirectionalRenderedNodeCenter(renderedUnitNode);

  // Fallback para el primer frame antes de insertar los nodos en el DOM o si
  // la capa aún no tiene dimensiones: usa la interpolación suave de la Arena.
  if (!casterPoint) casterPoint = getRealtimeRenderedCasterPoint(Number(controllerPlayerId));
  if (!unitPoint) {
    unitPoint = cellCenter(Number(row), Number(col));
    const unit = unitId ? (getUnitById?.(Number(ownerPlayerId), unitId) || findPlayerContainingUnit?.(unitId)?.unit) : null;
    const locatedOwner = unit ? Number(findPlayerContainingUnit?.(unitId)?.playerId || ownerPlayerId) : Number(ownerPlayerId);
    if (unit) unitPoint = getRealtimeRenderedInvocationPoint(locatedOwner, unit, row, col);
  }

  if (!casterPoint || !unitPoint) return Number(controllerPlayerId) === Number(LOCAL_PLAYER_ID) ? 90 : -90;
  const dx = Number(casterPoint.x || 0) - Number(unitPoint.x || 0);
  const dy = Number(casterPoint.y || 0) - Number(unitPoint.y || 0);
  if (Math.abs(dx) < 0.0001 && Math.abs(dy) < 0.0001) return Number(controllerPlayerId) === Number(LOCAL_PLAYER_ID) ? 90 : -90;
  return Math.atan2(dy, dx) * (180 / Math.PI);
}

function createProvocationDirectionArrowNode(extraClass = '') {
  const arrow = document.createElement('i');
  arrow.className = ['nael-provocation-direction-arrow', extraClass].filter(Boolean).join(' ');
  const tension = document.createElement('b');
  arrow.appendChild(tension);
  return arrow;
}

function appendInvocationSideMarker(div, row, col, controllerPlayerId, ownerPlayerId = controllerPlayerId, unitId = '') {
  if (!div || controllerPlayerId == null) return;
  const relation = Number(controllerPlayerId) === Number(LOCAL_PLAYER_ID) ? 'ally' : 'rival';
  const angle = getInvocationSideMarkerAngle(row, col, controllerPlayerId, ownerPlayerId, unitId, div);
  div.dataset.sideRelation = relation;
  div.dataset.sideControllerPlayerId = String(controllerPlayerId);
  div.dataset.sideOwnerPlayerId = String(ownerPlayerId);
  div.classList.add(`unit-side-${relation}`);
  const marker = document.createElement('span');
  marker.className = `unit-side-marker unit-side-marker--${relation} unit-side-marker--arrow`;
  marker.setAttribute('aria-hidden', 'true');
  // La flecha de pertenencia comparte LITERALMENTE el mismo nodo/clase base de
  // Provocación. Solo el modificador blanco cambia la paleta.
  marker.style.setProperty('--nael-provocation-direction', `${angle}deg`);
  marker.appendChild(createProvocationDirectionArrowNode('unit-side-direction-arrow--white'));
  div.prepend(marker);
}

function syncRealtimeDirectionalUnitFx() {
  if (!els.unitsLayer) return false;
  const nodes = els.unitsLayer.querySelectorAll('.unit.invocation[data-unit-id]');
  nodes.forEach(div => {
    const unitId = String(div.dataset.unitId || '');
    // Maeryn puede transferir la Invocación de un array de jugador al otro.
    // No confiamos ciegamente en el data-player-id que tenía el nodo antes del
    // cambio: localizamos la unidad en el estado actual en cada sincronización.
    const located = unitId ? findPlayerContainingUnit?.(unitId) : null;
    const ownerPlayerId = Number(located?.playerId || div.dataset.playerId || div.dataset.sideOwnerPlayerId || 0);
    const unit = located?.unit || getUnitById?.(ownerPlayerId, unitId);
    if (!unit) return;

    const controllerPlayerId = Number(getMaerynEffectiveOwnerPlayerId(unit) || ownerPlayerId || 0);
    const marker = div.querySelector(':scope > .unit-side-marker--arrow');
    if (marker && controllerPlayerId) {
      const relation = controllerPlayerId === Number(LOCAL_PLAYER_ID) ? 'ally' : 'rival';
      const angle = getInvocationSideMarkerAngle(unit.row, unit.col, controllerPlayerId, ownerPlayerId, unitId, div);
      marker.style.setProperty('--nael-provocation-direction', `${angle}deg`);
      marker.classList.toggle('unit-side-marker--ally', relation === 'ally');
      marker.classList.toggle('unit-side-marker--rival', relation === 'rival');
      div.classList.toggle('unit-side-ally', relation === 'ally');
      div.classList.toggle('unit-side-rival', relation === 'rival');
      div.dataset.sideRelation = relation;
      div.dataset.sideControllerPlayerId = String(controllerPlayerId);
      div.dataset.sideOwnerPlayerId = String(ownerPlayerId);
    }

    const provocationEntry = getActiveProvocationEntry(unit);
    const provocationSource = provocationEntry ? getProvocationSourceUnit(unit) : null;
    if (provocationEntry && provocationSource?.unit) {
      // v9.45 · Seleccionar EXCLUSIVAMENTE la flecha naranja persistente. Desde
      // v9.43 la flecha blanca de pertenencia comparte la misma clase geométrica,
      // por lo que un querySelector genérico puede apuntar al indicador equivocado.
      const arrow = div.querySelector('.nael-provocation-persistent-fx > .nael-provocation-direction-arrow');
      if (arrow) {
        let sourceNode = null;
        try {
          sourceNode = els.unitsLayer?.querySelector(
            `.unit.invocation[data-unit-id="${CSS.escape(String(provocationSource.unit.id || ''))}"]`
          ) || null;
        } catch (_) {}
        const angle = getNaelProvocationRenderedDirectionAngle(unit, provocationSource.unit, div, sourceNode);
        // Aplicarlo sobre la propia flecha evita cualquier cruce con el marcador
        // de pertenencia y permite seguir a Nael cuadro a cuadro sin renderUnits().
        arrow.style.setProperty('--nael-provocation-direction', `${angle}deg`);
        arrow.dataset.liveDirection = String(angle);
      }
    }
  });
  return true;
}

function renderUnit(row, col, type, src, label, playerId = null, spawnId = null, glowColor = '#ffffff', unitId = null, guardianId = null, renderOptions = null) {
  const div = document.createElement('div');
  div.className = `unit ${type}`;
  div.dataset.row = String(row);
  div.dataset.col = String(col);
  div.dataset.type = type;
  if (playerId !== null) div.dataset.playerId = String(playerId);
  if (spawnId) div.dataset.spawnId = spawnId;
  if (unitId) div.dataset.unitId = unitId;
  if (guardianId) div.dataset.guardianId = guardianId;
  if (type === 'caster' && playerId != null) {
    const casterState = state.players[playerId]?.caster;
    if (casterState?.casterId) {
      div.dataset.casterId = casterState.casterId;
      div.classList.add(`unit-caster-${casterState.casterId}`);
    }
    if (casterState?.cardId) div.dataset.cardId = casterState.cardId;
  }
  div.style.setProperty('--unit-glow', glowColor || '#ffffff');
  if (type === 'caster' && src) {
    div.style.setProperty('--offturn-caster-token-url', `url("${src}")`);
  }
  const unitState = unitId && playerId ? state.players[playerId].units.find(u => u.id === unitId) : null;
  const guardianState = type === 'guardian' && guardianId && playerId ? state.players[playerId]?.guardians?.find(item => String(item.id) === String(guardianId)) : null;
  if (type === 'guardian' && isUmbralFugazPortalGuardian(guardianState)) {
    div.classList.add('unit-umbral-fugaz-portal');
    div.dataset.umbralPairId = String(guardianState.umbralPairId || '');
    div.dataset.umbralEndpoint = String(guardianState.portalEndpoint || '');
  }
  const tokenTuningKey = getTokenTuningKeyForRenderedUnit(type, playerId, unitState, guardianState);
  if (tokenTuningKey) applyTokenTuningToNode(div, tokenTuningKey);
  const actionWindowCandidate = playerId != null ? getQuickReactionVisualCandidate(playerId, type, unitId, guardianId) : null;
  if (unitState?.cardId) {
    div.dataset.cardId = unitState.cardId;
    div.classList.add(`unit-card-${unitState.cardId}`);
  }
  if (type === 'invocation' && unitState && isOnlineOwnHiddenUnit(playerId, unitState)) {
    div.classList.add('unit-online-hidden-own');
  }
  if (type === 'invocation' && unitState && (unitHasCamuflajeHidden(unitState) || unitHasSaqueadorSigiloHidden(unitState))) {
    div.classList.add('unit-camuflaje-hidden');
    div.style.setProperty('--camuflaje-opacity', String(unitState.saqueadorSigiloOpacity || unitState.camuflajeOpacity || 0.5));
  }
  if (type === 'invocation' && unitState && (Number(unitState.camuflajeFxUntil || 0) > Date.now() || Number(unitState.saqueadorSigiloFxUntil || 0) > Date.now())) {
    div.classList.add('unit-camuflaje-activating');
  }
  if (type === 'invocation' && unitState && Number(unitState.yasuganaBlindnessFxUntil || 0) > Date.now()) {
    div.classList.add('unit-yasugana-blindness-activating');
  }
  if (type === 'invocation' && unitState && Number(unitState.gioshoninSupplyFxUntil || 0) > Date.now()) {
    div.classList.add('unit-gioshonin-supply-fx-active');
  }
  if (type === 'invocation' && unitState?.realtimeAttackTelegraph && isRealtimePlayStyle()) {
    div.classList.add('unit-realtime-attack-preparing');
    const prep = document.createElement('span');
    prep.className = 'unit-realtime-attack-prep-indicator';
    prep.textContent = '!';
    prep.title = 'Preparando ataque';
    div.appendChild(prep);
  }
  if (type === 'invocation' && unitState && isKurayamiUnit(unitState) && unitState.kurayamiChanneling) {
    div.classList.add('unit-kurayami-channeling');
    const channelTotal = Math.max(1, Number(unitState.kurayamiChannelTotal ?? getPowerProfile('shizukesaNoShiin')?.channelPhases ?? 3));
    const channelRemaining = Math.max(0, Number(unitState.kurayamiChannelRemaining ?? channelTotal));
    const channelStage = Math.max(0, Math.min(2, channelTotal - channelRemaining));
    const tokenOpacityByStage = [1.00, 0.80, 0.60];
    const channelTokenOpacity = tokenOpacityByStage[channelStage] ?? 0.60;
    const fxOpacityByStage = [0.25, 0.40, 0.80];
    const channelFxOpacity = fxOpacityByStage[channelStage] ?? 0.80;
    const channelStartedAt = Number(unitState.kurayamiPowerStartedAt || Date.now());
    const channelElapsed = Math.max(0, Date.now() - channelStartedAt);
    div.dataset.kurayamiChannelStage = String(channelStage + 1);
    div.style.setProperty('--kurayami-channel-remaining', String(channelRemaining));
    div.style.setProperty('--kurayami-channel-token-opacity', String(channelTokenOpacity));
    div.style.setProperty('--kurayami-channel-fx-opacity', String(channelFxOpacity));
    div.style.setProperty('--kurayami-channel-animation-delay', `-${channelElapsed}ms`);
  }
  if (type === 'invocation' && unitState && isKurayamiUnit(unitState) && unitHasActiveFactor(unitState, 'hidden')) {
    div.classList.add('unit-kurayami-hidden');
  }
  if (type === 'invocation' && unitState && isMinokageUnit(unitState) && unitState.minokageChanneling) {
    div.classList.add('unit-minokage-channeling');
    div.style.setProperty('--minokage-channel-progress', String(Math.max(0, MINOKAGE_SHIPPU_CHANNEL_PHASES - Number(unitState.minokageChannelRemaining || 0))));
  }
  if (type === 'invocation' && unitState && isMinokageUnit(unitState) && unitState.minokageEvasionAnimating) {
    div.classList.add('minokage-dash-source-hidden');
  }
  const kaguyaChargeVisual = type === 'invocation' ? getKaguyaChargeVisualState(unitState) : null;
  if (kaguyaChargeVisual?.active) applyKaguyaChargeVisualStyles(div, kaguyaChargeVisual);
  if (unitState?.status === 'restoring') {
    div.classList.add('restoring');
    div.style.setProperty('--restore-color', getUnitElementColor(playerId, unitState));
  }
  if (type === 'invocation' && unitState && Number(unitState.burnTickFlashUntil || 0) > Date.now()) {
    div.classList.add('unit-burn-tick-flash');
  }
  if (unitState?.engagedWith) div.classList.add('engaged');
  if (hasStructureAttackAnchor(unitState)) div.classList.add('structure-anchored');
  if (type === 'guardian' && guardianId) {
    if (guardianState?.destroying) {
      div.classList.add('structure-destroying');
      div.style.setProperty('--destroy-color', getOwnerColor(playerId) || '#5400FF');
    }
  }
  if (state.selectedMover && state.selectedMover.playerId === playerId) {
    if ((type === 'caster' && state.selectedMover.type === 'caster') || (type === 'invocation' && state.selectedMover.type === 'invocation' && state.selectedMover.unitId === unitId)) {
      div.classList.add('selected-mover');
    }
  }
  if (type === 'invocation' && isRealtimePlayStyle() && Number(playerId) === Number(LOCAL_PLAYER_ID)) {
    const modeSystem = ensureRealtimeCombatModeSystemState();
    if (String(modeSystem.selectedUnitId || '') === String(unitId || '')) div.classList.add('realtime-combat-mode-unit-selected');
  }
  const isLocalResolutionUnit = type === 'invocation'
    && playerId === LOCAL_PLAYER_ID
    && playerId === state.activePlayer
    && currentPhase().id === 'resolution';
  if (isLocalResolutionUnit) div.classList.add('local-resolution-unit');
  const selectedSourceForLayering = currentPhase().id === 'resolution' ? getSourceUnitFromSelection() : null;
  if (selectedSourceForLayering && !unitHasKurokagiBukiPickupReady(selectedSourceForLayering.unit) && type === 'invocation') {
    if (playerId === selectedSourceForLayering.playerId) div.classList.add('friendly-targeting-blocker');
    else div.classList.add('targetable-rival-hitbox');
  }
  div.title = `${label} · ${coordLabel(row, col)}`;
  const pos = cellCenter(row, col);
  applyRealtimeSmoothMotionToRenderedNode(div, type, playerId, type === 'invocation' ? unitId : 'caster', row, col);
  const rowDepth = 200 + (Number(row || 0) * 10);
  const typeDepth = type === 'invocation' ? 3 : type === 'guardian' ? 2 : 1;
  div.style.zIndex = String(rowDepth + typeDepth);
  div.innerHTML = `<img class="unit-token-img" src="${src}" alt="${label}"><div class="unit-protected-icons-layer" aria-hidden="true"></div><button type="button" class="unit-hitbox" aria-label="${label} en ${coordLabel(row, col)}"></button>`;
  if (type === 'invocation' && unitState) {
    const sideControllerPlayerId = Number(getMaerynEffectiveOwnerPlayerId(unitState) || playerId);
    appendInvocationSideMarker(div, row, col, sideControllerPlayerId, playerId, unitId);
  }
  if (type === 'invocation' && unitState && isMaerynDominatedUnit(unitState)) {
    const control = unitState.maerynDomination;
    const source = getMaerynDominationSource(unitState);
    const controllerPlayerId = Number(control.controllerPlayerId || playerId);
    const palette = getMaerynControlFxPalette(controllerPlayerId, source);
    const age = Math.max(0, Date.now() - Number(control.appliedAt || Date.now()));
    div.classList.add('unit-maeryn-dominated');
    div.style.setProperty('--maeryn-control-primary-rgb', palette.primaryRgb);
    div.style.setProperty('--maeryn-control-secondary-rgb', palette.secondaryRgb);
    div.style.setProperty('--maeryn-control-side-rgb', palette.sideRgb);
    div.style.setProperty('--maeryn-control-ring-delay', `-${age % 3200}ms`);
    div.style.setProperty('--maeryn-control-counter-delay', `-${age % 4300}ms`);
    div.style.setProperty('--maeryn-control-particle-delay', `-${age % 2700}ms`);
    div.style.setProperty('--maeryn-control-pulse-delay', `-${age % 3600}ms`);
    div.dataset.maerynControlledBy = String(controllerPlayerId);
    const host = div.querySelector('.unit-protected-icons-layer') || div;
    const halo = document.createElement('span');
    halo.className = 'maeryn-control-persistent-halo maeryn-control-persistent-halo--token';
    halo.setAttribute('aria-hidden', 'true');
    halo.innerHTML = `
      <i class="maeryn-control-side-glow"></i>
      <i class="maeryn-control-ring maeryn-control-ring--outer"></i>
      <i class="maeryn-control-ring maeryn-control-ring--inner"></i>
      <i class="maeryn-control-runes"></i>
      <i class="maeryn-control-mental-pulse"></i>
      <i class="maeryn-control-particle particle-a"></i>
      <i class="maeryn-control-particle particle-b"></i>
      <i class="maeryn-control-particle particle-c"></i>`;
    host.appendChild(halo);
  }
  if (type === 'invocation' && unitState) {
    const provocationEntry = getActiveProvocationEntry(unitState);
    const provocationSource = provocationEntry ? getProvocationSourceUnit(unitState) : null;
    if (provocationEntry && provocationSource?.unit) {
      const age = Math.max(0, Date.now() - Number(provocationEntry.appliedAt || Date.now()));
      const routePulseAge = Math.max(0, Date.now() - Number(unitState.naelProvocationRoutePulseAt || 0));
      const directionAngle = getNaelProvocationDirectionAngle(unitState, provocationSource.unit);
      div.classList.add('unit-nael-provoked');
      if (routePulseAge <= NAEL_PROVOCATION_ROUTE_PULSE_MS) div.classList.add('unit-nael-provocation-route-pulse');
      div.style.setProperty('--nael-provocation-direction', `${directionAngle}deg`);
      div.style.setProperty('--nael-provocation-ring-delay', `-${age % 1800}ms`);
      div.style.setProperty('--nael-provocation-tension-delay', `-${age % 2300}ms`);
      div.dataset.provokedBy = String(provocationSource.unit.id || '');
      const host = div.querySelector('.unit-protected-icons-layer') || div;
      const fx = document.createElement('span');
      fx.className = 'nael-provocation-persistent-fx';
      fx.setAttribute('aria-hidden', 'true');
      fx.innerHTML = `
        <i class="nael-provocation-foot-ring"></i>
        <i class="nael-provocation-tension tension-a"></i>
        <i class="nael-provocation-tension tension-b"></i>
        <i class="nael-provocation-tension tension-c"></i>
        <i class="nael-provocation-route-pulse"></i>`;
      // Una sola fábrica DOM para Provocación y Pertenencia: cualquier ajuste de
      // forma/proporción en la flecha base afecta a ambas de manera idéntica.
      fx.insertBefore(createProvocationDirectionArrowNode(), fx.children[1] || null);
      host.appendChild(fx);
    }
  }
  if (type === 'invocation' && unitState && unitHasStun(unitState)) {
    const protectedLayer = div.querySelector('.unit-protected-icons-layer') || div;
    const stunFxNode = createStunOrbitFxNode(unitState);
    if (stunFxNode) protectedLayer.appendChild(stunFxNode);
  }
  if (type === 'invocation' && unitState && unitHasBurn(unitState)) {
    const protectedLayer = div.querySelector('.unit-protected-icons-layer') || div;
    const burnFxNode = createBurnFxNode(unitState);
    if (burnFxNode) protectedLayer.appendChild(burnFxNode);
  }
  if (type === 'guardian' && guardianState && unitHasBurn(guardianState)) {
    const protectedLayer = div.querySelector('.unit-protected-icons-layer') || div;
    const burnFxNode = createBurnFxNode(guardianState);
    if (burnFxNode) protectedLayer.appendChild(burnFxNode);
  }
  const standardSelectionInfo = getStandardArenaSelectionInfo(playerId, type, unitId, guardianId);
  if (standardSelectionInfo) applyStandardArenaSelectionVisual(div, src, standardSelectionInfo.title);
  if (actionWindowCandidate) {
    div.classList.add('unit-action-window-ready');
    applyStandardArenaSelectionVisual(div, src, 'Acción disponible');
  }
  if (type === 'invocation' && unitState && isKurayamiUnit(unitState) && unitState.kurayamiChanneling) {
    const channelFx = document.createElement('span');
    channelFx.className = 'kurayami-channel-fx';
    channelFx.setAttribute('aria-hidden', 'true');
    channelFx.style.setProperty('--kurayami-channel-seed', String(Math.max(0, Number(unitState.kurayamiPowerStartedAt || Date.now()) % 997)));
    // Reservados para otros efectos: backdrop, aura, ring-a/ring-b/ring-c y core.
    // Sus clases, keyframes y estilos permanecen intactos en style.css.
    channelFx.innerHTML = `
      <i class="kurayami-channel-beam"></i>
      <img class="kurayami-channel-ground-sigil" src="data:image/png;base64," alt="">
      <img class="kurayami-channel-echo kurayami-channel-echo-a" src="${src}" alt="">
      <img class="kurayami-channel-echo kurayami-channel-echo-b" src="${src}" alt="">
      <i class="kurayami-channel-slash kurayami-channel-slash-a"></i>
      <i class="kurayami-channel-slash kurayami-channel-slash-b"></i>
      <i class="kurayami-channel-wisp kurayami-channel-wisp-a"></i>
      <i class="kurayami-channel-wisp kurayami-channel-wisp-b"></i>
      <i class="kurayami-channel-wisp kurayami-channel-wisp-c"></i>
      <i class="kurayami-channel-spark kurayami-channel-spark-1"></i>
      <i class="kurayami-channel-spark kurayami-channel-spark-2"></i>
      <i class="kurayami-channel-spark kurayami-channel-spark-3"></i>
      <i class="kurayami-channel-spark kurayami-channel-spark-4"></i>`;
    div.appendChild(channelFx);
  }
  if (type === 'invocation' && unitState && unitHasHattoriDirectMark(unitState)) {
    div.classList.add('hattori-direct-marked');
    const directFx = document.createElement('span');
    directFx.className = 'hattori-direct-mark-fx';
    directFx.setAttribute('aria-hidden', 'true');
    directFx.innerHTML = '<i class="hattori-direct-mark-core"></i><i class="hattori-direct-mark-ring"></i><i class="hattori-direct-mark-slash"></i>';
    div.appendChild(directFx);
  }
  if (type === 'caster' && playerId != null) {
    const activeCasterCast = getCasterPersistentInvocationCast(playerId);
    const casterState = state.players[playerId]?.caster;
    if (activeCasterCast) {
      div.classList.add('caster-is-channeling-cast');
      div.dataset.castingCardId = activeCasterCast.card.id;
      div.style.setProperty('--caster-cast-color', getElementColorById(activeCasterCast.item.elementId || getEffectiveCardElementId(activeCasterCast.card, playerId), getPlayerElementColor(playerId)));
      const castingFx = document.createElement('span');
      castingFx.className = 'caster-persistent-cast-circle';
      castingFx.setAttribute('aria-hidden', 'true');

      // Mantiene la fase visual del giro aunque renderAll reconstruya el token.
      // El reloj solo nace al comenzar el estado de kasteo y se conserva hasta
      // que el Kaster deja de tener una invocación de 1+ fases en la cola.
      const now = Date.now();
      if (!Number.isFinite(Number(casterState?.persistentCastCircleStartedAt))) {
        if (casterState) casterState.persistentCastCircleStartedAt = now;
      }
      const startedAt = Number(casterState?.persistentCastCircleStartedAt ?? now);
      const elapsed = Math.max(0, now - startedAt);
      castingFx.style.setProperty('--caster-cast-spin-delay', `-${elapsed % 4200}ms`);
      castingFx.style.setProperty('--caster-cast-glow-delay', `-${elapsed % 3600}ms`);

      const cellSize = getBoardCellSizePercent(row);
      const boardWidth = Number(ROK_RENDER_GEOMETRY_CACHE?.boardWidth ?? els.boardContent?.offsetWidth ?? 0);
      const boardHeight = Number(ROK_RENDER_GEOMETRY_CACHE?.boardHeight ?? els.boardContent?.offsetHeight ?? 0);
      if (boardWidth > 0 && boardHeight > 0) {
        // El círculo vive dentro de board-content y ya hereda su zoom. Usar
        // getBoundingClientRect() aquí aplicaba el zoom una segunda vez.
        const circleWidthPercent = Math.max(cellSize.width * 0.88725, 3.6075);
        const circleHeightPercent = Math.max(cellSize.height * 0.88725, 3.6075);
        castingFx.style.width = `${(circleWidthPercent / 100) * boardWidth}px`;
        castingFx.style.height = `${(circleHeightPercent / 100) * boardHeight}px`;
      }
      castingFx.innerHTML = '<img src="data:image/png;base64," alt="" draggable="false">';
      div.appendChild(castingFx);
    } else if (casterState && casterState.persistentCastCircleStartedAt != null) {
      delete casterState.persistentCastCircleStartedAt;
    }
  }
  if (type === 'guardian' && guardianId) {
    const g = state.players[playerId].guardians.find(item => item.id === guardianId);
    const badge = document.createElement('div');
    badge.className = 'resistance-status';
    badge.innerHTML = `<span class="cast-icon-badge big resistance-icon-badge"><span class="brick-shield" aria-hidden="true"></span><span class="cast-corner-number resistance-corner-number">${g?.resistance ?? 5}</span></span>`;
    div.appendChild(badge);
  }
  if (type === 'invocation' && unitState && unitState.status !== 'restoring') {
    const card = CARD_LIBRARY[unitState.cardId];
    const weapon = getWeaponInfoProfile(getWeaponTypeForAttackUnit(unitState));
    const effectiveDamage = getVisualEffectiveUnitDamageValue(unitState, card, playerId);
    const baseDamage = Math.max(0, Number(getEffectiveAttackProfile(card, unitState, playerId)?.damage ?? unitState.damage ?? card?.attackProfile?.damage ?? card?.stats?.damage ?? card?.stats?.atk ?? effectiveDamage ?? 0) || 0);
    const attackBonusTotal = getVisualAttackBonusSourcesForUnit(unitState, card, playerId).reduce((sum, item) => sum + Math.max(0, Number(item?.amount || 0)), 0);
    const damage = effectiveDamage;
    const damageBuffTheme = getCardBuffThemeId(card);
    const damageTitle = attackBonusTotal > 0
      ? `Daño · ${weapon.label} · total ${effectiveDamage} · base ${baseDamage} + bono ${attackBonusTotal}`
      : `Daño · ${weapon.label}`;
    const life = unitState.hp ?? card?.stats?.life ?? 0;
    const lifeClass = lifeToneClass(unitState);
    const badge = document.createElement('div');
    badge.className = 'invocation-stat-status';
    badge.innerHTML = `
      <span class="unit-stat-icon-badge unit-damage-badge${attackBonusTotal > 0 ? ` unit-damage-badge--buffed unit-buff-theme-${damageBuffTheme}` : ''}" title="${damageTitle}">
        <img class="unit-weapon-icon unit-protected-icon" src="${weapon.icon}" alt="${weapon.label}" draggable="false">
        <span class="unit-stat-corner-number">${damage}</span>
      </span>
      <span class="unit-stat-icon-badge unit-life-badge" title="Vida">
        <span class="unit-heart-icon" aria-hidden="true"></span>
        <span class="unit-stat-corner-number ${lifeClass}">${life}</span>
      </span>`;
    div.appendChild(badge);
  }
  if (type === 'invocation' && unitState && isOdaNoKageShadowBound(unitState)) {
    div.classList.add('oda-no-kage-shadow-bound');
    const shadowFx = document.createElement('span');
    shadowFx.className = 'oda-no-kage-shadow-bound-fx';
    shadowFx.setAttribute('aria-hidden', 'true');
    div.appendChild(shadowFx);
  }
  if (type === 'invocation' && unitState && unitHasActiveFactor(unitState, 'hidden')) {
    const hiddenInfo = getSmokeHiddenSourceInfo(playerId, unitState);
    const hiddenBadge = document.createElement('button');
    hiddenBadge.type = 'button';
    hiddenBadge.className = 'unit-hidden-badge';
    hiddenBadge.setAttribute('aria-label', hiddenInfo?.sourceName ? `Oculto por ${hiddenInfo.sourceName}` : 'Oculto');
    hiddenBadge.title = hiddenInfo?.sourceName ? `Oculto por ${hiddenInfo.sourceName}` : 'Oculto';
    hiddenBadge.innerHTML = `<img class="unit-protected-icon" src="${HIDDEN_FACTOR_ICON_ASSET}" alt="Oculto">`;
    hiddenBadge.addEventListener('click', event => {
      stopTargetMenuEvent(event);
      const cardModel = buildCardInfoViewModel(CARD_LIBRARY[unitState.cardId], { source: 'arena', playerId, unitId });
      openCardMetaInfo('factor', 'hidden', cardModel, {
        factorLevel: 1,
        factorSource: hiddenInfo?.zone?.type === 'kageNoMichi' ? 'kageNoMichi' : 'smokeZone',
        hiddenSourceName: hiddenInfo?.sourceName || '',
      });
    });
    (div.querySelector('.unit-protected-icons-layer') || div).appendChild(hiddenBadge);
  }
  if (type === 'invocation' && unitState && (Number(unitState.camuflajeFxUntil || 0) > Date.now() || Number(unitState.saqueadorSigiloFxUntil || 0) > Date.now())) {
    const camoFx = document.createElement('span');
    camoFx.className = 'unit-camuflaje-fx';
    camoFx.setAttribute('aria-hidden', 'true');
    camoFx.innerHTML = '<i class="unit-camuflaje-ring unit-camuflaje-ring-a"></i><i class="unit-camuflaje-ring unit-camuflaje-ring-b"></i><i class="unit-camuflaje-mist"></i>';
    div.appendChild(camoFx);
  }
  if (type === 'invocation' && unitState && unitHasActiveFactor(unitState, 'blindness') && !unitState.yasuganaBlindnessPending) {
    const crowFx = document.createElement('span');
    crowFx.className = `yasugana-blindness-crow-fx${Number(unitState.yasuganaBlindnessFxUntil || 0) > Date.now() ? ' is-activating' : ''}`;
    crowFx.setAttribute('aria-hidden', 'true');
    crowFx.innerHTML = `
      <i class="yasugana-crow-mark crow-1">⌄</i>
      <i class="yasugana-crow-mark crow-2">⌄</i>
      <i class="yasugana-crow-mark crow-3">⌄</i>
      <i class="yasugana-crow-mark crow-4">⌄</i>
      <i class="yasugana-crow-mark crow-5">⌄</i>`;
    const orbitStart = Number(unitState.yasuganaBlindnessLoopStartedAt || 0) || Date.now();
    const orbitSpecs = [
      ['.crow-1', 2200, 0],
      ['.crow-2', 2400, 240],
      ['.crow-3', 2150, 120],
      ['.crow-4', 2500, 360],
      ['.crow-5', 2250, 180],
    ];
    orbitSpecs.forEach(([selector, duration, offset]) => {
      const node = crowFx.querySelector(selector);
      if (!node) return;
      const elapsed = Math.max(0, Date.now() - orbitStart) + Number(offset || 0);
      const phase = elapsed % Number(duration || 1);
      node.style.animationDelay = `-${phase}ms`;
    });
    div.appendChild(crowFx);
  }
  if (type === 'invocation' && unitState && Number(unitState.gioshoninSupplyFxUntil || 0) > Date.now()) {
    const supplyFx = document.createElement('span');
    supplyFx.className = 'unit-gioshonin-supply-fx';
    supplyFx.setAttribute('aria-hidden', 'true');
    supplyFx.innerHTML = '<i class="unit-gioshonin-supply-ring"></i><i class="unit-gioshonin-supply-spark unit-gioshonin-supply-spark-a"></i><i class="unit-gioshonin-supply-spark unit-gioshonin-supply-spark-b"></i><i class="unit-gioshonin-supply-glow"></i>';
    div.appendChild(supplyFx);
  }
  const hasPendingNormalMoveFoil = (type === 'invocation' && unitState && unitHasMandatoryMovement(playerId, unitState))
    || (type === 'caster' && casterHasNormalMovementPending(playerId));
  if (hasPendingNormalMoveFoil) {
    div.classList.add('move-pending-foil');

    const moveFoilImg = document.createElement('img');
    moveFoilImg.className = 'move-pending-token-foil-img';
    moveFoilImg.src = src;
    moveFoilImg.alt = '';
    moveFoilImg.setAttribute('aria-hidden', 'true');
    moveFoilImg.draggable = false;
    div.appendChild(moveFoilImg);

    const moveBadge = document.createElement('div');
    moveBadge.className = 'move-ready-badge';
    moveBadge.innerHTML = `<img class="move-ready-icon unit-protected-icon" src="assets/indicators/indicador-movimientos-faltantes.svg" alt="" aria-hidden="true" />`;
    (div.querySelector('.unit-protected-icons-layer') || div).appendChild(moveBadge);
  }
  const isSelectedPowerUnit = state.selectedMover
    && state.selectedMover.type === 'invocation'
    && state.selectedMover.playerId === playerId
    && state.selectedMover.unitId === unitId
    && unitHasPowerDefinition(playerId, unitState);
  const canShowDirectPowerActions = false && isLocalResolutionUnit && isSelectedPowerUnit;
  if (canShowDirectPowerActions) {
    div.classList.add('has-power-actions');
    const canPower = unitCanVoluntarilyActivateSmokePower(playerId, unitState);
    const actionBox = document.createElement('div');
    actionBox.className = 'unit-direct-action-buttons';
    actionBox.innerHTML = `
      <button type="button" class="unit-direct-action-btn" data-unit-direct-action="info">Info</button>
      <button type="button" class="unit-direct-action-btn unit-direct-power-info-btn" data-unit-direct-action="power-info" title="Ver Bomba de humo"><img src="${SMOKE_BOMB_ICON_ASSET}" alt="Bomba de humo"></button>
      <button type="button" class="unit-direct-action-btn unit-direct-power-btn" data-unit-direct-action="power"${canPower ? '' : ' disabled title="Poder no disponible ahora"'}>Poder</button>
    `;
    actionBox.querySelector('[data-unit-direct-action="info"]')?.addEventListener('click', event => {
      stopTargetMenuEvent(event);
      clearCombatMenus();
      openCardInfo(unitState.cardId, null, null, { source: 'arena', playerId, unitId });
    });
    actionBox.querySelector('[data-unit-direct-action="power-info"]')?.addEventListener('click', event => {
      stopTargetMenuEvent(event);
      const cardModel = buildCardInfoViewModel(CARD_LIBRARY[unitState.cardId], { source: 'arena', playerId, unitId });
      openCardMetaInfo('weapon', 'smokeBomb', cardModel);
    });
    actionBox.querySelector('[data-unit-direct-action="power"]')?.addEventListener('click', event => {
      stopTargetMenuEvent(event);
      beginSmokeBombTargeting(playerId, unitId);
    });
    div.appendChild(actionBox);
  }
  if (type === 'invocation' && unitState) {
    const card = CARD_LIBRARY[unitState.cardId];
    const restoreTime = Math.max(0, Number(unitState.restoreTime ?? card?.stats?.restore ?? 0));
    const restoreRemaining = Math.max(0, Number(unitState.restoreRemaining ?? restoreTime));
    const showRestoreBadge = (unitState.status === 'restoring' && restoreTime > 0 && restoreRemaining > 0)
      || (state.devPreviewIndicators?.restore && restoreTime > 0);
    if (showRestoreBadge) {
      const badge = document.createElement('div');
      badge.className = `restore-stat-status${unitState.status === 'restoring' ? '' : ' dev-preview-badge'}`;
      badge.innerHTML = `
        <span class="unit-stat-icon-badge unit-restore-badge" title="Restauración">
          <span class="unit-restore-icon" aria-hidden="true">${RESTORE_ICON_INLINE_SVG}</span>
          <span class="unit-stat-corner-number restore-cooldown-number">${unitState.status === 'restoring' ? restoreRemaining : restoreTime}</span>
        </span>
      `;
      div.appendChild(badge);
    }
  }

  if (type === 'caster' && isOffTurnCasterRepositionActiveForPlayer(playerId)) {
    div.classList.add('has-offturn-caster-action', 'offturn-caster-foil');

    const foilImg = document.createElement('img');
    foilImg.className = 'offturn-caster-token-foil-img';
    foilImg.src = src;
    foilImg.alt = '';
    foilImg.setAttribute('aria-hidden', 'true');
    foilImg.draggable = false;
    div.appendChild(foilImg);
    if (!actionWindowCandidate) {
      const actionIndicator = document.createElement('span');
      actionIndicator.className = 'unit-action-ready-indicator';
      actionIndicator.title = 'Acción disponible';
      (div.querySelector('.unit-protected-icons-layer') || div).appendChild(actionIndicator);
    }

  }

  const hitbox = div.querySelector('.unit-hitbox');
  hitbox.addEventListener('click', (event) => {
    event.preventDefault();
    event.stopPropagation();
    event.stopImmediatePropagation?.();
    if (isTokenTuningToolOpen()) return;

    // Panel permanente: un clic sobre una Invocación aliada la ancla arriba.
    // No altera el flujo de combate/objetivos; solo cambia la presentación del panel.
    if (type === 'invocation' && unitId && Number(playerId) === Number(LOCAL_PLAYER_ID)) {
      pinInvocationControlUnit(playerId, unitId, { render: true });
    }

    const pendingDespliegue = state.pendingPowerAction;
    if (type === 'invocation' && unitId && ['despliegueAnticipadoTarget', 'gloriaLatenteTarget', 'shirahadoriAbilityTarget'].includes(pendingDespliegue?.kind)) {
      const sourcePlayerId = Number(pendingDespliegue.playerId);
      const valid = Number(playerId) === sourcePlayerId
        && (pendingDespliegue.kind === 'despliegueAnticipadoTarget'
          ? getEligibleDespliegueAnticipadoTargets(sourcePlayerId).some(candidate => String(candidate.id) === String(unitId))
          : pendingDespliegue.kind === 'gloriaLatenteTarget'
            ? getSelectableGloriaLatenteTargets(sourcePlayerId).some(candidate => String(candidate.id) === String(unitId))
            : getEligibleShirahadoriAbilityUsers(sourcePlayerId).some(candidate => String(candidate.id) === String(unitId)));
      if (valid) {
        if (pendingDespliegue.kind === 'despliegueAnticipadoTarget') resolveDespliegueAnticipadoTarget(sourcePlayerId, unitId);
        else if (pendingDespliegue.kind === 'gloriaLatenteTarget') resolveGloriaLatenteTarget(sourcePlayerId, unitId);
        else resolveShirahadoriAbilityTarget(sourcePlayerId, unitId);
        return;
      }
    }

    // Shizukesa no Shi-in también confirma la marca tocando directamente
    // la ficha rival resaltada, sin depender únicamente del aro de selección.
    const pendingKurayami = state.pendingPowerAction;
    if (type === 'invocation' && unitId && pendingKurayami?.kind === 'kurayamiMark') {
      const sourcePlayerId = Number(pendingKurayami.playerId);
      const sourceUnit = getUnitById(sourcePlayerId, pendingKurayami.unitId);
      const validTargets = getKurayamiPowerTargets(sourcePlayerId, sourceUnit);
      const isValidTarget = Number(playerId) === Number(getOpponentId(sourcePlayerId))
        && validTargets.some(candidate => String(candidate.id) === String(unitId));
      if (isValidTarget) {
        resolveKurayamiPowerTarget(sourcePlayerId, pendingKurayami.unitId, playerId, unitId);
        return;
      }
    }

    // Mercancía de guerra también usa la lectura estándar de selección sobre la ficha.
    const pendingGioshonin = state.pendingPowerAction;
    if (type === 'invocation' && unitId && pendingGioshonin?.kind === 'gioshoninSupply') {
      const sourcePlayerId = Number(pendingGioshonin.playerId);
      const sourceUnit = getUnitById(sourcePlayerId, pendingGioshonin.unitId);
      const valid = Number(playerId) === sourcePlayerId
        && getAffordableGioshoninSupplyTargets(sourcePlayerId, sourceUnit).some(candidate => String(candidate.id) === String(unitId));
      if (valid) {
        pendingGioshonin.targetUnitId = unitId;
        renderGioshoninSupplyModal();
        renderAll();
        return;
      }
    }

    // Yasugana puede confirmar Ceguera o Vigilia directamente tocando la ficha
    // resaltada, además de usar la lista lateral de ELEGIR.
    const pendingYasugana = state.pendingPowerAction;
    if (type === 'invocation' && unitId && ['yasuganaBlindness', 'yasuganaVigilia'].includes(pendingYasugana?.kind)) {
      const sourcePlayerId = Number(pendingYasugana.playerId);
      const sourceUnitId = pendingYasugana.unitId;
      const sourceUnit = getUnitById(sourcePlayerId, sourceUnitId);
      const validTargets = pendingYasugana.kind === 'yasuganaBlindness'
        ? getYasuganaBlindnessTargets(sourcePlayerId, sourceUnit)
        : getYasuganaVigiliaTargets(sourcePlayerId, sourceUnit);
      const expectedOwnerId = pendingYasugana.kind === 'yasuganaBlindness' ? getOpponentId(sourcePlayerId) : sourcePlayerId;
      const isValidTarget = Number(playerId) === Number(expectedOwnerId)
        && validTargets.some(candidate => String(candidate.id) === String(unitId));
      if (isValidTarget) {
        resolveYasuganaPowerTarget(sourcePlayerId, sourceUnitId, playerId, unitId, pendingYasugana.kind);
        return;
      }
    }

    const pendingMinokage = state.pendingPowerAction;
    if (pendingMinokage?.kind === 'minokageShippuUgachi') {
      const sourcePlayerId = Number(pendingMinokage.playerId);
      const sourceUnit = getUnitById(sourcePlayerId, pendingMinokage.unitId);
      if (sourceUnit && Number(playerId) === Number(getOpponentId(sourcePlayerId))) {
        let target = null;
        if (type === 'caster') target = buildTarget('caster', playerId);
        else if (type === 'guardian' && guardianId) target = buildTarget('guardian', playerId, { guardianId });
        else if (type === 'invocation' && unitId) target = buildTarget('invocation', playerId, { unitId });
        if (target) {
          void resolveMinokagePowerTarget(sourcePlayerId, pendingMinokage.unitId, target);
          return;
        }
      }
    }

    const pendingMaeryn = state.pendingPowerAction;
    if (type === 'invocation' && unitId && pendingMaeryn?.kind === 'maerynDominationTarget') {
      const sourcePlayerId = Number(pendingMaeryn.playerId);
      const sourceUnit = getUnitById(sourcePlayerId, pendingMaeryn.unitId);
      const targetUnit = getUnitById(Number(playerId), unitId);
      const valid = sourceUnit && targetUnit
        && getMaerynDominationTargets(sourcePlayerId, sourceUnit)
          .some(candidate => String(candidate.id) === String(unitId) && Number(candidate.owner) === Number(playerId));
      if (valid) {
        resolveMaerynDomination(sourcePlayerId, pendingMaeryn.unitId, Number(playerId), unitId);
        return;
      }
    }

    const pendingSeyran = state.pendingPowerAction;
    if (type === 'invocation' && unitId && pendingSeyran?.kind === 'seyranDistorsionTarget') {
      const sourcePlayerId = Number(pendingSeyran.playerId);
      const sourceUnit = getUnitById(sourcePlayerId, pendingSeyran.unitId);
      const targetUnit = getUnitById(Number(playerId), unitId);
      const valid = sourceUnit && targetUnit
        && getSeyranDistortionTargets(sourcePlayerId, sourceUnit)
          .some(candidate => String(candidate.id) === String(unitId) && Number(candidate.owner) === Number(playerId));
      if (valid) {
        openSeyranDistortionChoice(sourcePlayerId, pendingSeyran.unitId, Number(playerId), unitId);
        return;
      }
    }

    // Disparo energizado confirma el objetivo directamente tocando la ficha,
    // sin abrir una segunda miniatura ni el menú normal de ataque.
    const pendingKaguya = state.pendingPowerAction;
    if (pendingKaguya?.kind === 'kaguyaChargedShot') {
      const sourcePlayerId = Number(pendingKaguya.playerId);
      const sourceUnit = getUnitById(sourcePlayerId, pendingKaguya.unitId);
      if (sourceUnit && Number(playerId) === Number(getOpponentId(sourcePlayerId))) {
        let target = null;
        if (type === 'caster') target = buildTarget('caster', playerId);
        else if (type === 'guardian' && guardianId) target = buildTarget('guardian', playerId, { guardianId });
        else if (type === 'invocation' && unitId) target = buildTarget('invocation', playerId, { unitId });
        if (target) {
          void resolveKaguyaChargedShotTarget(sourcePlayerId, pendingKaguya.unitId, target);
          return;
        }
      }
      if (type === 'invocation' && Number(playerId) === sourcePlayerId && String(unitId || '') === String(pendingKaguya.unitId || '')) {
        log('Disparo energizado está preparado: selecciona un objetivo rival resaltado.');
        renderAll();
        return;
      }
    }

    // Si otro modo de poder quedó abierto y el jugador clickea una ficha,
    // se cancela para que no bloquee el flujo normal de movimiento/ataque.
    if (state.pendingPowerAction) {
      const pending = state.pendingPowerAction;
      if (pending.kind === 'kurokagiBukiPickup') {
        log('Buki Utsushi está esperando: toca una de las armas resaltadas en el suelo.');
        renderDroppedWeaponsLayer();
        return;
      }
      if (pending.kind === 'smokeBomb') completeSmokeBombFlow(pending, 'cancelled');
      else {
        state.pendingPowerAction = null;
        pending.reactionResolve?.('cancelled');
        forceReleaseQuickReactionManualPowerFlow('cancelled');
      }
    }

    if (type === 'caster' && isOffTurnCasterRepositionSelecting(playerId)) {
      log('Toca Mover para reposicionar el Kaster o usa clic derecho para continuar.');
      renderAll();
      return;
    }

    // RT-08.16 · La Invocación de Arena deja de ser una superficie de UI.
    // Incluso en Restauración, su información se consulta desde la carta
    // persistente del Panel de Invocaciones.
    if (type === 'invocation' && unitId) {
      const clickedUnit = state.players?.[playerId]?.units?.find(unit => String(unit.id) === String(unitId));
      if (clickedUnit?.status === 'restoring') return;
    }

    if (isRealtimeThoughtPauseActive()) {
      // v9.54 · Tiempo de Pensamiento congela la simulación, no la interfaz de
      // selección de combate. Si ya existe una fuente seleccionada, tocar un
      // objetivo válido debe abrir el mismo menú Info/Atacar que fuera de la pausa.
      const pausedSource = getSourceUnitFromSelection();
      if (currentPhase().id === 'resolution' && pausedSource) {
        let pausedTarget = null;
        if (type === 'caster') pausedTarget = buildTarget('caster', playerId);
        else if (type === 'guardian' && guardianId) pausedTarget = buildTarget('guardian', playerId, { guardianId });
        else if (type === 'invocation' && unitId) pausedTarget = buildTarget('invocation', playerId, { unitId });
        const isEnemyTarget = pausedTarget && Number(playerId) !== Number(pausedSource.playerId);
        const isAlliedReceiver = pausedTarget ? isAlliedAttackReceiverTarget(pausedSource, pausedTarget) : false;
        if (pausedTarget && (isEnemyTarget || isAlliedReceiver) && canSelectTarget(pausedSource, pausedTarget)) {
          showTargetMenu(pausedTarget);
          return;
        }
      }

      clearCombatMenus();
      if (type === 'invocation' && unitId) return;
      if (type === 'caster') {
        // El token físico del Kaster local es una superficie de combate. Al
        // tocarlo se selecciona y se publican de inmediato los objetivos del
        // panel izquierdo; el modal continúa reservado a su miniatura/HUD.
        if (Number(playerId) === Number(LOCAL_PLAYER_ID)
            && currentPhase().id === 'resolution'
            && isCasterAvailableForActiveAttack(playerId)) {
          selectMover('caster', playerId);
          renderTargetAccessPanel();
          renderAll('v9.54-caster-selected-thought-pause');
        }
        return;
      }
      if (type === 'guardian' && guardianId) { openGuardianInfo(playerId, guardianId); return; }
      return;
    }

    const selectedSource = getSourceUnitFromSelection();

    // Si ya hay una fuente seleccionada, un rival abre su menú normal. Edran
    // aliado también puede abrirlo porque Resonancia Convergente acepta fuego
    // aliado (incluido ahora el Kaster).
    if (currentPhase().id === 'resolution' && selectedSource) {
      let clickedTarget = null;
      if (type === 'caster') clickedTarget = buildTarget('caster', playerId);
      else if (type === 'guardian' && guardianId) clickedTarget = buildTarget('guardian', playerId, { guardianId });
      else if (type === 'invocation' && unitId) clickedTarget = buildTarget('invocation', playerId, { unitId });
      const isEnemyTarget = Number(playerId) !== Number(selectedSource.playerId);
      const isAlliedReceiver = clickedTarget ? isAlliedAttackReceiverTarget(selectedSource, clickedTarget) : false;
      if (clickedTarget && (isEnemyTarget || isAlliedReceiver)) {
        showTargetMenu(clickedTarget);
        return;
      }
    }

    // Click sobre ficha propia en Resolución: seleccionar SIEMPRE para mover/atacar.
    // Si la ficha puede usar poder, el menú aparece encima sin cancelar la selección.
    if (currentPhase().id === 'resolution' && playerId === state.activePlayer && playerId === LOCAL_PLAYER_ID) {
      if (type === 'caster') {
        selectMover('caster', playerId);
        renderTargetAccessPanel();
        renderAll('v9.54-caster-selected');
        return;
      }
      if (type === 'invocation' && unitId) {
        // Selección normal de Invocación migrada al Panel permanente.
        return;
      }
    }

    // Kishimoto puede activar Límites Superados durante Kasteo para ampliar
    // el límite antes de añadir nuevas invocaciones a la cola.
    if (currentPhase().id === 'casting'
      && playerId === state.activePlayer
      && playerId === LOCAL_PLAYER_ID
      && type === 'invocation'
      && unitId
      && isKishimotoUnit(unitState)) {
      // Límites Superados se administra desde la carta del Panel.
      return;
    }

    // Fuera de Resolución, o si no es tu turno, el click abre información.
    // Excepción RT: el token del Kaster local NUNCA abre modal; la miniatura/HUD
    // es el único acceso de información. Así el token queda reservado a atacar.
    clearCombatMenus();
    if (type === 'invocation' && unitId) {
      // Sin acción normal: Info/Poder/Modo viven en la carta persistente.
      return;
    }
    if (type === 'caster') {
      if (isRealtimePlayStyle() && Number(playerId) === Number(LOCAL_PLAYER_ID)) return;
      openKasterInfo(playerId);
      return;
    }
    if (type === 'guardian' && guardianId) { openGuardianInfo(playerId, guardianId); return; }
    log(`${label} en ${coordLabel(row, col)}.`);
  });

  hitbox.addEventListener('mouseenter', () => {
    div.classList.add('unit-hovered');
    if (type === 'guardian' && guardianId && playerId != null) {
      const guardianState = state.players[playerId]?.guardians?.find(item => item.id === guardianId);
      if (guardianState) guardianState.auraHovered = true;
      renderGuardianAuras();
    }
  });
  hitbox.addEventListener('mouseleave', () => {
    div.classList.remove('unit-hovered');
    if (type === 'guardian' && guardianId && playerId != null) {
      const guardianState = state.players[playerId]?.guardians?.find(item => item.id === guardianId);
      if (guardianState) guardianState.auraHovered = false;
      renderGuardianAuras();
    }
  });

  if (type === 'invocation' && spawnId && playerId !== null) {
    attachLinkHoverHandlers(hitbox, spawnId, playerId, 'unit');
  }
  const renderTarget = renderOptions?.target || els.unitsLayer;
  if (renderTarget && renderOptions?.append !== false) renderTarget.appendChild(div);
  return div;
}


function buildSimpleCastStatus(value = '2', className = 'cast-status') {
  const status = document.createElement('div');
  status.className = className;
  const badge = document.createElement('span');
  badge.className = className === 'enemy-mini-cast-status' ? 'cast-icon-badge enemy-mini-hourglass' : 'cast-icon-badge big cast';
  badge.textContent = '⌛';
  const corner = document.createElement('span');
  corner.className = className === 'enemy-mini-cast-status' ? 'cast-corner-number enemy-mini-corner-number' : 'cast-corner-number';
  corner.textContent = value;
  badge.appendChild(corner);
  status.appendChild(badge);
  return status;
}

function getSelectedVisualDevInvocation(invocations = []) {
  const selectedId = state.visualDevSelectedInvocationId;
  const selected = invocations.find(card => card.id === selectedId);
  return selected || invocations[0] || null;
}

function getVisualDevSampleCards() {
  const cards = Object.values(CARD_LIBRARY || {});
  const spells = cards.filter(card => getCardTypeId(card) === 'spell');
  const invocations = cards.filter(card => getCardTypeId(card) === 'invocation');
  const invokeA = getSelectedVisualDevInvocation(invocations) || cards[0];
  const invokeB = invocations.find(card => card.id !== invokeA?.id) || invokeA || cards[0];
  if (invokeA?.id && state.visualDevSelectedInvocationId !== invokeA.id) {
    state.visualDevSelectedInvocationId = invokeA.id;
  }
  return {
    spellA: spells[0] || cards[0],
    spellB: spells[1] || spells[0] || cards[0],
    invokeA,
    invokeB,
  };
}

function clearVisualDevShowcaseNodes() {
  document.querySelectorAll('.visual-dev-showcase-node').forEach(node => node.remove());
  if (els.targetAccessPanel) els.targetAccessPanel.classList.remove('visual-dev-showcase-live');
  if (els.enemyMiniHud) els.enemyMiniHud.classList.remove('visual-dev-showcase-live');
  if (els.castQueue) els.castQueue.classList.remove('visual-dev-showcase-live');
  if (els.arenaEffectTrackers) els.arenaEffectTrackers.classList.remove('visual-dev-showcase-live');
}

function renderVisualDevShowcase() {
  clearVisualDevShowcaseNodes();
  if (!document.body.classList.contains(VISUAL_DEV_SHOW_ALL_CLASS)) return;
  const { spellA, spellB, invokeA, invokeB } = getVisualDevSampleCards();

  if (els.castQueue) {
    els.castQueue.classList.add('visual-dev-showcase-live');
    const samples = [
      { card: spellA, remaining: 2, active: true },
      { card: invokeA, remaining: 'Q', active: false },
      { card: spellB, remaining: 'Q', active: false },
    ];
    samples.forEach(sample => {
      const item = document.createElement('div');
      item.className = `cast-item visual-dev-showcase-node ${sample.active ? 'cast-active' : 'cast-waiting'}`;
      item.title = 'Muestra dev';
      item.appendChild(createCastQueueVisual(sample.card, { elementIdOverride: getCardElementId(sample.card) }));
      item.appendChild(buildSimpleCastStatus(String(sample.remaining), 'cast-status'));
      els.castQueue.appendChild(item);
    });
  }

  if (els.enemyMiniResources && els.enemyMiniCastQueue && els.enemyMiniHud) {
    els.enemyMiniHud.classList.add('visual-dev-showcase-live');
    els.enemyMiniHud.classList.remove('empty');
    ['darkness', 'fire', 'water', 'light'].forEach(id => {
      const token = document.createElement('div');
      token.className = 'enemy-mini-orb enemy-mini-resource-token visual-dev-showcase-node';
      token.dataset.elementId = id;
      token.style.setProperty('--orb-color', '#7d4cff');
      token.innerHTML = `<img src="${getElementCostIcon(id)}" alt="${id}">`;
      els.enemyMiniResources.appendChild(token);
    });
    [
      { card: invokeB, active: true, remaining: '2' },
      { card: spellA, active: false, remaining: 'Q' },
    ].forEach(sample => {
      const div = document.createElement('div');
      div.className = `enemy-mini-cast-item visual-dev-showcase-node ${sample.active ? 'cast-active' : 'cast-waiting'}`;
      div.dataset.elementId = getCardElementId(sample.card) || '';
      div.appendChild(createCastQueueVisual(sample.card, { elementIdOverride: getCardElementId(sample.card) }));
      div.appendChild(buildSimpleCastStatus(sample.remaining, 'enemy-mini-cast-status'));
      els.enemyMiniCastQueue.appendChild(div);
    });
  }

  if (els.arenaEffectTrackers) {
    els.arenaEffectTrackers.classList.add('visual-dev-showcase-live');
    [
      { type: 'smoke', phasesRemaining: 3, sourceName: 'Bomba de humo' },
      { type: 'kageNoMichi', phasesRemaining: 9, sourceName: 'Kage no Michi', sourceCardId: spellA?.id || 'spellKageNoMichi' },
    ].forEach(zone => {
      const item = document.createElement('button');
      item.type = 'button';
      item.className = `arena-effect-tracker arena-effect-${zone.type} visual-dev-showcase-node`;
      item.title = `${zone.sourceName || (zone.type === 'kageNoMichi' ? 'Kage no Michi' : 'Bomba de humo')} · ${zone.phasesRemaining} fases restantes`;
      item.appendChild(createArenaEffectTrackerVisual(zone));
      const count = document.createElement('span');
      count.className = 'arena-effect-tracker-count';
      count.textContent = String(zone.phasesRemaining);
      item.appendChild(count);
      bindArenaEffectTrackerInfo(item, zone);
      els.arenaEffectTrackers.appendChild(item);
    });
  }

  if (els.targetAccessPanel) {
    els.targetAccessPanel.classList.add('visible', 'visual-dev-showcase-live');
    [
      { label: 'D4', card: invokeA },
      { label: 'E5', card: invokeB || invokeA },
    ].forEach(sample => {
      const row = document.createElement('div');
      row.className = 'target-access-row visual-dev-showcase-node';
      const miniBtn = document.createElement('button');
      miniBtn.type = 'button';
      miniBtn.className = 'target-access-mini-btn';
      const mini = document.createElement('div');
      mini.className = 'target-access-mini target-access-invocation';
      mini.innerHTML = `<img src="${sample.card?.tokenImage || sample.card?.artImage || 'assets/invocation-token.png'}" alt="${sample.card?.name || 'Invocación'}">`;
      miniBtn.appendChild(mini);
      row.appendChild(miniBtn);
      const btn = document.createElement('button');
      btn.type = 'button';
      btn.className = 'target-access-btn';
      btn.textContent = 'Elegir';
      row.appendChild(btn);
      const bubble = document.createElement('span');
      bubble.className = 'target-access-cell-bubble';
      bubble.textContent = sample.label;
      row.appendChild(bubble);
      els.targetAccessPanel.appendChild(row);
    });
  }

  if (els.boardContent) {
    const sampleUnitId = 'visual_dev_arena_invocation_sample';
    const sampleCard = invokeA || Object.values(CARD_LIBRARY || {}).find(card => getCardTypeId(card) === 'invocation');
    if (sampleCard && els.unitsLayer) {
      const player = state.players[LOCAL_PLAYER_ID];
      const previousUnits = player.units;
      const fakeUnit = {
        id: sampleUnitId,
        cardId: sampleCard.id,
        elementId: getEffectiveCardElementId(sampleCard, LOCAL_PLAYER_ID),
        row: 8,
        col: 5,
        hp: sampleCard.stats?.life ?? 1,
        baseHp: sampleCard.stats?.life ?? 1,
        maxHp: sampleCard.stats?.life ?? 1,
        atk: sampleCard.stats?.atk ?? 1,
        def: sampleCard.stats?.def ?? 0,
        damage: sampleCard.attackProfile?.damage ?? sampleCard.stats?.damage ?? 1,
        mov: sampleCard.stats?.mov ?? 1,
        restoreTime: sampleCard.stats?.restore ?? 2,
        restoreRemaining: sampleCard.stats?.restore ?? 2,
        status: 'active',
        movesLeft: 0,
        activeFactors: [{ id: 'hidden', level: 1, source: 'devPreview' }],
        hiddenSuppressedZoneIds: [],
        originTab: 0,
        originSlot: 0,
      };
      player.units = [...previousUnits, fakeUnit];
      renderUnit(fakeUnit.row, fakeUnit.col, 'invocation', sampleCard.tokenImage || sampleCard.artImage || 'assets/invocation-token.png', sampleCard.name, LOCAL_PLAYER_ID, null, '#5400FF', sampleUnitId);
      player.units = previousUnits;

      const sampleNode = els.unitsLayer.querySelector(`[data-unit-id="${sampleUnitId}"]`);
      if (sampleNode) {
        sampleNode.classList.add('visual-dev-showcase-node', 'visual-dev-arena-invocation-sample', 'local-resolution-unit');
        sampleNode.dataset.cardId = sampleCard.id;
        const protectedLayer = sampleNode.querySelector('.unit-protected-icons-layer') || sampleNode;
        if (!sampleNode.querySelector('.move-ready-badge')) {
          const moveBadge = document.createElement('div');
          moveBadge.className = 'move-ready-badge visual-dev-sample-move';
          moveBadge.innerHTML = '<img class="move-ready-icon unit-protected-icon" src="assets/indicators/indicador-movimientos-faltantes.svg" alt="" aria-hidden="true">';
          protectedLayer.appendChild(moveBadge);
        }
        if (!sampleNode.querySelector('.restore-stat-status')) {
          const restoreBadge = document.createElement('div');
          restoreBadge.className = 'restore-stat-status dev-preview-badge';
          restoreBadge.innerHTML = `
            <span class="unit-stat-icon-badge unit-restore-badge" title="Restauración">
              <span class="unit-restore-icon" aria-hidden="true">${RESTORE_ICON_INLINE_SVG}</span>
              <span class="unit-stat-corner-number restore-cooldown-number">2</span>
            </span>`;
          sampleNode.appendChild(restoreBadge);
        }
        // No se crean botones falsos aquí. Los menús reales se añaden en un paso separado.
      }
    }

    const casterDefenseMenu = document.createElement('div');
    casterDefenseMenu.className = 'caster-defense-menu visual-dev-showcase-node visual-dev-caster-defense-menu';
    casterDefenseMenu.innerHTML = `
      <button type="button" data-action="defend">Defender</button>
      <button type="button" data-action="counter">Contraatacar</button>
    `;
    els.boardContent.appendChild(casterDefenseMenu);

    const versus = document.createElement('div');
    versus.className = 'visual-dev-vs-showcase visual-dev-showcase-node';
    versus.innerHTML = `
      <div class="vs-card left"><img src="${invokeA?.tokenImage || invokeA?.artImage || 'assets/invocation-token.png'}" alt=""><span>${invokeA?.name || 'Aliado'}</span></div>
      <div class="vs-badge">VS</div>
      <div class="vs-card right"><img src="${invokeB?.tokenImage || invokeB?.artImage || 'assets/invocation-token.png'}" alt=""><span>${invokeB?.name || 'Enemigo'}</span></div>`;
    els.boardContent.appendChild(versus);
  }
}


function getCasterLifeState(caster, card = null) {
  const currentLife = Number(caster?.life ?? 0);
  const maxLife = Number(caster?.maxLife ?? card?.stats?.life ?? 0);
  return currentLife < 5 ? 'low' : (currentLife > maxLife ? 'bonus' : 'normal');
}

function renderCasterStats() {
  const playerId = LOCAL_PLAYER_ID;
  const player = state.players[playerId];
  const caster = ensureCasterRuntime(playerId);
  if (!player || !caster) return;
  const card = getCasterCardForPlayer(playerId) || CARD_LIBRARY[caster.cardId] || null;
  const weapon = card ? getWeaponProfile(card) : null;
  if (els.casterAtk) {
    els.casterAtk.innerHTML = `${weapon?.icon ? `<img src="${weapon.icon}" alt="${weapon.label || 'Ataque'}">` : ''}<span>${caster.atk ?? card?.stats?.atk ?? 0}</span>`;
  }
  if (els.casterDef) {
    const currentLife = Number(caster.life ?? 0);
    const maxLife = Number(caster.maxLife ?? card?.stats?.life ?? 0);
    const lifeState = getCasterLifeState(caster, card);
    els.casterDef.classList.remove('life-low', 'life-bonus', 'life-normal');
    els.casterDef.classList.add(`life-${lifeState}`);
    els.casterDef.innerHTML = `<img class="life-factor-icon caster-life-factor-icon" src="${LIFE_FACTOR_ICON_ASSET}" alt="Vida"><span id="casterLifeValue">${currentLife}/${maxLife}</span>`;
    els.casterLifeValue = els.casterDef.querySelector('#casterLifeValue');
  }
  if (els.casterCast) els.casterCast.textContent = player.castQueue.length ? 'Casteando' : 'Libre';
  if (els.casterState) {
    const available = Number(caster.specialCounters || 0);
    const progress = Number(caster.specialCounterProgress || 0);
    const counterColor = getPlayerElementColor(playerId);
    els.casterState.style.setProperty('--caster-counter-domain-color', counterColor);
    els.casterState.style.setProperty('--caster-counter-mix', `${Math.round(44 + (Math.max(0, Math.min(1, progress / CASTER_SPECIAL_COUNTER_DAMAGE_THRESHOLD)) * 42))}%`);
    els.casterState.classList.toggle('counter-ready', available > 0);
    els.casterState.classList.toggle('counter-charging', available <= 0 && progress > 0);
    els.casterState.classList.toggle('counter-empty', available <= 0 && progress <= 0);
    els.casterState.innerHTML = `<img src="${CASTER_SPECIAL_COUNTER_ASSET}" alt="Counter especial"><span id="casterCounterValue">${available > 0 ? `x${available}` : `${progress}/${CASTER_SPECIAL_COUNTER_DAMAGE_THRESHOLD}`}</span>`;
    els.casterCounterValue = els.casterState.querySelector('#casterCounterValue');
  }
  if (els.casterPureMeter) els.casterPureMeter.innerHTML = renderPureElementMeterHtml(caster, { compact: true });
  if (els.casterWins) els.casterWins.textContent = `WINS ${Number(state.matchWins?.[playerId] || 0)}`;
  renderCasterPostureHuds();
  ensureCasterPostureHudTicker();
}

function renderOpponentCasterHud() {
  const playerId = getOpponentId(LOCAL_PLAYER_ID);
  const player = state.players[playerId];
  const caster = ensureCasterRuntime(playerId);
  if (!player || !caster || !els.opponentCasterHud) return;
  const casterDef = getCasterDefinition(caster);
  const elementId = getCasterDomainId(caster) || player?.domainId || player?.elementId || 'oscuridad';
  const card = getCasterCardForPlayer(playerId)
    || (casterDef?.cardId ? CARD_LIBRARY[casterDef.cardId] : null)
    || CARD_LIBRARY[caster.cardId]
    || createInfoEntityCard({ id: caster?.cardId || caster?.id || `kasterJ${playerId}`, name: getCasterDisplayName(caster, `Kaster J${playerId}`), type: 'kaster', artImage: getCasterArtImage(caster), elementId });
  const weapon = card ? getWeaponProfile(card) : null;
  const elementColor = getPlayerElementColor(playerId);
  const domain = DOMAIN_ART_DB[elementId] || DOMAIN_ART_DB.oscuridad;
  const currentLife = Number(caster.life ?? 0);
  const maxLife = Number(caster.maxLife ?? card?.stats?.life ?? 0);
  const lifeState = getCasterLifeState(caster, card);
  const available = Number(caster.specialCounters || 0);
  const progress = Number(caster.specialCounterProgress || 0);

  els.opponentCasterHud.style.setProperty('--opponent-caster-color', elementColor);
  els.opponentCasterHud.style.setProperty('--caster-turn-color', elementColor);
  els.opponentCasterHud.dataset.elementId = getCasterDomainId(caster) || player.elementId || '';
  const isOpponentTurn = state.activePlayer === playerId;
  els.opponentCasterHud.classList.toggle('is-active-turn', isOpponentTurn);
  els.opponentCasterHud.dataset.activeTurn = isOpponentTurn ? '1' : '0';
  const opponentName = getCasterCompactDisplayName(caster, 'Kaster rival');
  if (els.opponentCasterBg) {
    els.opponentCasterBg.src = getElementBackgroundForCard(card, elementId);
    els.opponentCasterBg.alt = `Fondo de ${opponentName}`;
  }
  if (els.opponentCasterArt) {
    els.opponentCasterArt.src = getCasterArtImage(caster);
    els.opponentCasterArt.alt = opponentName;
  }
  if (els.opponentCasterSkin) {
    els.opponentCasterSkin.src = getElementSkinForCard(card, elementId);
    els.opponentCasterSkin.alt = `Skin ${domain.elementLabel}`;
  }
  if (els.opponentCasterName) els.opponentCasterName.textContent = opponentName;
  if (els.opponentCasterPureMeter) els.opponentCasterPureMeter.innerHTML = renderPureElementMeterHtml(caster, { compact: true });
  if (els.opponentCasterAtk) els.opponentCasterAtk.innerHTML = `${weapon?.icon ? `<img src="${weapon.icon}" alt="${weapon.label || 'Ataque'}">` : ''}<span>${caster.atk ?? card?.stats?.atk ?? 0}</span>`;
  if (els.opponentCasterLife) {
    els.opponentCasterLife.classList.remove('life-low', 'life-bonus', 'life-normal');
    els.opponentCasterLife.classList.add(`life-${lifeState}`);
    els.opponentCasterLife.innerHTML = `<img class="life-factor-icon caster-life-factor-icon" src="${LIFE_FACTOR_ICON_ASSET}" alt="Vida"><span>${currentLife}/${maxLife}</span>`;
  }
  if (els.opponentCasterCast) els.opponentCasterCast.textContent = player.castQueue.length ? 'Casteando' : 'Libre';
  if (els.opponentCasterWins) els.opponentCasterWins.textContent = `WINS ${Number(state.matchWins?.[playerId] || 0)}`;
  if (els.opponentCasterCounter) {
    els.opponentCasterCounter.style.setProperty('--caster-counter-domain-color', elementColor);
    els.opponentCasterCounter.style.setProperty('--caster-counter-mix', `${Math.round(44 + (Math.max(0, Math.min(1, progress / CASTER_SPECIAL_COUNTER_DAMAGE_THRESHOLD)) * 42))}%`);
    els.opponentCasterCounter.classList.toggle('counter-ready', available > 0);
    els.opponentCasterCounter.classList.toggle('counter-charging', available <= 0 && progress > 0);
    els.opponentCasterCounter.classList.toggle('counter-empty', available <= 0 && progress <= 0);
    els.opponentCasterCounter.innerHTML = `<img src="${CASTER_SPECIAL_COUNTER_ASSET}" alt="Counter especial"><span>${available > 0 ? `x${available}` : `${progress}/${CASTER_SPECIAL_COUNTER_DAMAGE_THRESHOLD}`}</span>`;
  }
  renderCasterPostureHuds();
  ensureCasterPostureHudTicker();
  if (els.opponentCasterHud.dataset.bound !== '1') {
    els.opponentCasterHud.dataset.bound = '1';
    els.opponentCasterHud.addEventListener('click', event => {
      if (event.target.closest('button')) return;
      openKasterInfo(getOpponentId(LOCAL_PLAYER_ID));
    });
  }
}


function activateHattoriNativeAbilityFromCasterHud() {
  const playerId = Number(LOCAL_PLAYER_ID || 1);
  if (!isHattoriCaster(playerId)) return false;

  const realtime = isRealtimePlayStyle() && Boolean(state?.realtime?.active);
  if (!canActivateHattoriNativeAbility(playerId, { allowOffTurn: realtime })) {
    const pure = getCasterPureElement(playerId);
    const eligible = getHattoriAbilityEligibleUnits(playerId).length;
    if (pure < HATTORI_ABILITY_PURE_COST_PER_TARGET) {
      log(`Ansatsu no Kokuin necesita ${HATTORI_ABILITY_PURE_COST_PER_TARGET} Elementos puros por objetivo.`);
    } else if (!eligible) {
      log('Ansatsu no Kokuin necesita al menos una invocación física aliada válida en arena.');
    } else {
      log('Ansatsu no Kokuin no está disponible en este momento.');
    }
    renderCasterWidePanel();
    return true;
  }

  void beginHattoriAbilitySelection(playerId, {
    allowOffTurn: realtime,
    fromCasterHud: true,
  });
  return true;
}

function renderCasterWidePanel() {
  const playerId = LOCAL_PLAYER_ID;
  const player = state.players[playerId];
  const caster = player?.caster;
  if (!player || !caster) return;

  const casterDef = getCasterDefinition(caster);
  const elementId = getCasterDomainId(caster) || player?.domainId || player?.elementId || 'oscuridad';
  const card = casterDef?.cardId && CARD_LIBRARY[casterDef.cardId]
    ? CARD_LIBRARY[casterDef.cardId]
    : createInfoEntityCard({
        id: caster?.cardId || caster?.id || `kasterJ${playerId}`,
        name: getCasterDisplayName(caster, `Kaster J${playerId}`),
        type: 'kaster',
        artImage: getCasterArtImage(caster),
        elementId,
      });
  const domain = DOMAIN_ART_DB[elementId] || DOMAIN_ART_DB.oscuridad;
  const casterName = getCasterCompactDisplayName(caster, `Kaster J${playerId}`);
  if (els.casterWidePanel) els.casterWidePanel.style.setProperty('--caster-turn-color', getPlayerElementColor(playerId));

  if (els.casterWideBg) {
    els.casterWideBg.src = getElementBackgroundForCard(card, elementId);
    els.casterWideBg.alt = `Fondo de ${casterName}`;
  }
  if (els.casterWideArt) {
    els.casterWideArt.src = getCasterArtImage(caster);
    els.casterWideArt.alt = casterName;
  }
  if (els.casterWideSkin) {
    els.casterWideSkin.src = getElementSkinForCard(card, elementId);
    els.casterWideSkin.alt = `Skin ${domain.elementLabel}`;
  }
  if (els.casterWideName) els.casterWideName.textContent = casterName;
  if (els.casterPureMeter) els.casterPureMeter.innerHTML = renderPureElementMeterHtml(ensureCasterRuntime(playerId), { compact: true });
  if (els.casterWideTag) els.casterWideTag.hidden = true;
  if (els.casterEnemyZoneWarning) {
    const inEnemySide = isCasterInEnemySide(playerId);
    els.casterEnemyZoneWarning.hidden = !inEnemySide;
    els.casterEnemyZoneWarning.classList.toggle('visible', inEnemySide);
    els.casterEnemyZoneWarning.title = 'Tu Kaster está en el lado rival. Haz clic para ver por qué recibe daño y no puede kastear allí.';
  }
  if (els.casterWideDomain) {
    els.casterWideDomain.innerHTML = '';
    els.casterWideDomain.setAttribute('aria-hidden', 'true');
  }

  const casterCardShell = els.casterWidePanel?.querySelector?.('.caster-card-shell');
  if (casterCardShell) {
    casterCardShell.classList.remove('caster-native-ability-clickable', 'caster-native-ability-ready', 'caster-native-ability-unavailable');
    casterCardShell.setAttribute('role', 'button');
    casterCardShell.setAttribute('tabindex', '0');
    casterCardShell.setAttribute('aria-label', 'Abrir información y Habilidad de tu Kaster');
    casterCardShell.title = 'Clic para abrir tu Kaster y usar su Habilidad cuando esté disponible';
  }

  // v9.17 · El HUD aliado se comporta igual que el rival: siempre abre el
  // modal del Kaster. Desde ese modal se presenta/activa su Habilidad nativa.
  if (els.casterWidePanel && els.casterWidePanel.dataset.localCasterInfoBound !== '1') {
    els.casterWidePanel.dataset.localCasterInfoBound = '1';
    els.casterWidePanel.addEventListener('click', event => {
      const counterNode = event.target.closest('#casterState');
      if (counterNode) {
        const pending = state.pendingCasterDefense;
        if (pending && Number(pending.defenderId) === Number(LOCAL_PLAYER_ID) && pending.allowSpecialCounter) {
          event.preventDefault();
          event.stopPropagation();
          settlePendingCasterDefenseSafely('special-counter', 'hud-counter-click');
          return;
        }
      }
      if (event.target.closest('button')) return;
      openKasterInfo(Number(LOCAL_PLAYER_ID));
    });
    els.casterWidePanel.addEventListener('keydown', event => {
      if (!['Enter', ' '].includes(event.key)) return;
      if (!event.target.closest('.caster-card-shell')) return;
      event.preventDefault();
      event.stopPropagation();
      openKasterInfo(Number(LOCAL_PLAYER_ID));
    });
  }

  // El indicador COUNTER del HUD funciona como botón durante la ventana de
  // reacción si existe al menos un Counter especial disponible.
  if (els.casterState) {
    const pending = state.pendingCasterDefense;
    const counterReadyNow = Boolean(pending
      && Number(pending.defenderId) === Number(playerId)
      && pending.allowSpecialCounter
      && Number(ensureCasterRuntime(playerId)?.specialCounters || 0) > 0);
    els.casterState.classList.toggle('special-counter-action-ready', counterReadyNow);
    els.casterState.setAttribute('role', counterReadyNow ? 'button' : 'status');
    if (counterReadyNow) {
      els.casterState.setAttribute('tabindex', '0');
      els.casterState.title = 'Counter especial disponible · clic para anular esta fuente de daño';
    } else {
      els.casterState.removeAttribute('tabindex');
    }
  }

}

function cellCenter(row, col) {
  const cached = ROK_RENDER_GEOMETRY_CACHE;
  const boardRect = cached?.boardRect || els.boardContent.getBoundingClientRect();
  const gridRect = row >= 9
    ? (cached?.allyRect || els.allyGrid.getBoundingClientRect())
    : (cached?.enemyRect || els.enemyGrid.getBoundingClientRect());
  const localRow = row >= 9 ? row - 9 : row;
  return {
    x: ((gridRect.left - boardRect.left) + ((col + 0.5) / 9) * gridRect.width) / boardRect.width * 100,
    y: ((gridRect.top - boardRect.top) + ((localRow + 0.5) / 9) * gridRect.height) / boardRect.height * 100,
  };
}

function isInside(row, col) { return row >= 0 && row < 18 && col >= 0 && col < 9; }

function hasSpawnMarkerAt(row, col) {
  for (const id of [1, 2]) {
    const markers = state.players[id].spawnMarkers || [];
    if (markers.some(marker => marker.row === row && marker.col === col)) return true;
  }
  return false;
}

function isCastPlacementBlocked(row, col) {
  return isCastPlacementBlockedForPlayer(row, col, null);
}

function isOccupied(row, col) {
  for (const id of [1, 2]) {
    const p = state.players[id];
    if (p.caster && p.caster.row === row && p.caster.col === col) return true;
    if (p.guardians.some(g => !isUmbralFugazPortalGuardian(g) && g.row === row && g.col === col && g.active)) return true;
    if (p.units.some(u => u.row === row && u.col === col)) return true;
  }
  return false;
}


function isHiddenOpponentUnitForPlayer(viewerPlayerId, ownerPlayerId, unit) {
  return isInvocationHiddenFromPlayer(viewerPlayerId, ownerPlayerId, unit);
}

function getHiddenOpponentUnitAtForPlayer(row, col, playerId) {
  if (!playerId) return null;
  const enemyId = getEnemyPlayerId(playerId);
  return (state.players[enemyId]?.units || []).find(unit =>
    unit.status !== 'restoring'
    && unit.row === row
    && unit.col === col
    && unitHasActiveFactor(unit, 'hidden')
  ) || null;
}

function isOccupiedForPlayer(row, col, playerId = null) {
  // Una pieza sigue ocupando físicamente su casilla, pero una invocación rival
  // con Oculto no puede convertir el mapa de movimientos del oponente en un
  // detector de posición. Para ese jugador la casilla se ofrece como libre y,
  // justo antes de entrar, la unidad oculta se desplaza sin revelar dónde estaba.
  for (const id of [1, 2]) {
    const p = state.players[id];
    if (p.caster && p.caster.row === row && p.caster.col === col) return true;
    if (p.guardians.some(g => !isUmbralFugazPortalGuardian(g) && g.row === row && g.col === col && g.active)) return true;
    if (p.units.some(u => {
      if (!u || u.status === 'restoring' || u.row !== row || u.col !== col) return false;
      if (playerId != null && isInvocationHiddenFromPlayer(playerId, id, u)) return false;
      return true;
    })) return true;
  }
  return false;
}

function hasSpawnMarkerAtForPlayer(row, col, playerId = null) {
  // Los puntos de respawn/restauración siempre reservan su coordenada para
  // CASTEO. En Tiempo Real solo son transparentes para la locomoción normal;
  // esa excepción de movimiento se resuelve en isMovementDestinationBlockedForPlayer().
  for (const id of [1, 2]) {
    const markers = state.players[id].spawnMarkers || [];
    if (markers.some(marker => marker.row === row && marker.col === col)) return true;
  }
  return false;
}

function isCastPlacementBlockedForPlayer(row, col, playerId = null) {
  return isOccupiedForPlayer(row, col, playerId) || hasSpawnMarkerAtForPlayer(row, col, playerId);
}

function isStructureMovementBlockedAt(row, col) {
  // Estructuras/guardianes siguen siendo paredes reales: bloquean ruta y destino.
  for (const id of [1, 2]) {
    const guardians = state.players[id]?.guardians || [];
    if (guardians.some(g => !isUmbralFugazPortalGuardian(g) && g.active !== false && !g.destroying && g.row === row && g.col === col)) return true;
  }
  return false;
}

function isMovementTransitBlockedForPlayer(row, col, playerId = null) {
  // Ruta intermedia: ignora invocaciones, Kasters, respawn y tokens temporales.
  // Solo las estructuras bloquean siempre.
  return isStructureMovementBlockedAt(row, col);
}

function isMovementDestinationBlockedForPlayer(row, col, playerId = null) {
  // Tiempo real: el Nexo es atravesable y no reserva físicamente la casilla.
  // Se puede pasar y también TERMINAR encima de él. Solo otra pieza real bloquea.
  if (isRealtimePlayStyle()) {
    return isOccupiedForPlayer(row, col, playerId);
  }

  // Manual conserva la regla histórica: el punto de restauración reserva casilla.
  return isOccupiedForPlayer(row, col, playerId) || hasSpawnMarkerAtForPlayer(row, col, playerId);
}

function isMovementStepBlockedForPlayer(row, col, playerId = null, remainingMovesBeforeStep = 1, isFinalStepOverride = null) {
  if (isMovementTransitBlockedForPlayer(row, col, playerId)) return true;

  // v9.55 · Cada paso lógico es una ocupación real de casilla. Antes, si a una
  // Invocación le quedaban varios puntos de movimiento, una casilla ocupada podía
  // tratarse como simple "tránsito" y la ficha llegaba a compartir coordenada con
  // otra Invocación hasta el paso siguiente. Eso queda prohibido en Manual,
  // Por Turnos y Tiempo Real. Oculto conserva su excepción: el rival no lo ve y
  // displaceHiddenOpponentIfNeeded() resuelve el cruce sin apilar las fichas.
  if (isOccupiedForPlayer(row, col, playerId)) return true;

  const isFinalStep = isFinalStepOverride === null
    ? Number(remainingMovesBeforeStep ?? 1) <= 1
    : Boolean(isFinalStepOverride);
  if (!isFinalStep) return false;

  // Para el destino final se conserva además la regla propia de Nexo/respawn en
  // Manual. En RT los Nexos siguen siendo atravesables/no físicos.
  return isMovementDestinationBlockedForPlayer(row, col, playerId);
}

function isMovementPlacementBlockedForPlayer(row, col, playerId = null) {
  // Compatibilidad: cuando otra parte del juego pregunta por bloqueo de movimiento
  // sin contexto de ruta, se interpreta como destino final.
  return isMovementDestinationBlockedForPlayer(row, col, playerId);
}

function chooseHiddenDisplacementCell(incomingPlayerId, hiddenUnit, impactRow, impactCol) {
  const rivalCaster = state.players[incomingPlayerId]?.caster;
  const cells = getCellsInRadius(impactRow, impactCol, 1, false)
    .filter(cell => isInside(cell.row, cell.col))
    .filter(cell => !isOccupied(cell.row, cell.col) && !hasSpawnMarkerAtForPlayer(cell.row, cell.col, null));
  if (!cells.length) return null;
  return cells.sort((a, b) => {
    const da = rivalCaster ? distance(a.row, a.col, rivalCaster.row, rivalCaster.col) : 0;
    const db = rivalCaster ? distance(b.row, b.col, rivalCaster.row, rivalCaster.col) : 0;
    if (da !== db) return da - db;
    return Math.abs(a.col - impactCol) - Math.abs(b.col - impactCol);
  })[0];
}

function displaceHiddenOpponentIfNeeded(row, col, incomingPlayerId) {
  const hiddenUnit = getHiddenOpponentUnitAtForPlayer(row, col, incomingPlayerId);
  if (!hiddenUnit) return false;
  const enemyId = getEnemyPlayerId(incomingPlayerId);
  const destination = chooseHiddenDisplacementCell(incomingPlayerId, hiddenUnit, row, col);
  const viewerOwnsHiddenUnit = Number(LOCAL_PLAYER_ID) === Number(enemyId);
  if (!destination) {
    if (viewerOwnsHiddenUnit) log(`${CARD_LIBRARY[hiddenUnit.cardId]?.name || 'Invocación oculta'} no encontró una casilla libre para reposicionarse.`);
    return false;
  }
  const oldLabel = coordLabel(hiddenUnit.row, hiddenUnit.col);
  hiddenUnit.row = destination.row;
  hiddenUnit.col = destination.col;
  if (viewerOwnsHiddenUnit) {
    log(`${CARD_LIBRARY[hiddenUnit.cardId]?.name || 'Invocación oculta'} se reposiciona desde ${oldLabel} a ${coordLabel(destination.row, destination.col)} para conservar Oculto.`);
  }
  refreshSmokeZoneEffects();
  return true;
}

function coordLabel(row, col) {
  // Numeración simple por grid: A1 inicia arriba-izquierda en CADA grid.
  const localRow = row >= 9 ? row - 8 : row + 1;
  const localCol = String.fromCharCode(65 + col);
  return `${localCol}${localRow}`;
}

function totalCost(cost) { return Object.values(cost || {}).reduce((a, b) => a + (Number(b) || 0), 0); }

const INVOCATION_COST_TOTALS = {
  naitoSutoka: 0,
  ninjaOjoDeBuho: 3,
  ninjaOdaNoKage: 3,
  samuraiAkari: 3,
  samuraiToyotomiHideyoshi: 3,
  samuraiBushiHonorable: 2,
  samuraiShiroNoBushi: 4,
  samuraiShinraHitokiri: 6,
  samuraiKaguya: 0,
  samuraiNobunagaOda: 4,
  samuraiKarunobuTaicho: 3,
  samuraiTakedaShingen: 4,
  miyamotoMusashi: 7,
  samuraiBushiInquebrantable: 3,
  samuraiBushiIniciado: 1,
  samuraiOSenseiUeshiba: 3,
  samuraiRegenteKishimoto: 3,
  ninjaSaqueadorNovato: 1,
  ninjaJunkaiButai1: 1,
  ninjaJunkaiButai2: 1,
  ninjaIchikawaGoemon: 3,
  ninjaKurayami: 7,
  ninjaMinokageNoKurai: 5,
  ninjaNaitoSutoka: 5,
  ninjaKurokagiButai3: 4,
  ninjaYasuganaHattori: 5,
  // Kiara · la distribución se deriva del costo total con la regla dominio + aleatorio.
  kiaraFaroleraUmbral: 0,
  kiaraNeruSusurroUmbral: 0,
  kiaraNaelVigiaMente: 2,
  kiaraSeyranGeometraUmbral: 3,
  kiaraEdranCustodioArcano: 3,
  kiaraMaerynArconteMente: 7,
};

function getInvocationTotalCostControl(card) {
  if (!card || getCardTypeId(card) !== 'invocation') return null;
  if (!Object.prototype.hasOwnProperty.call(INVOCATION_COST_TOTALS, card.id)) return null;
  return Math.max(0, Math.round(Number(INVOCATION_COST_TOTALS[card.id]) || 0));
}

function distributeInvocationCostByTotal(card, total) {
  const amount = Math.max(0, Math.round(Number(total) || 0));
  if (!amount) return {};
  const elementId = getCardElementId(card);
  // Regla de costo por total:
  // 1 => 1 base, 2 => 2 base, 3 => 2 base + 1 aleatorio,
  // 4 => 3 base + 1 aleatorio, 5 => 3 base + 2 aleatorios,
  // 6 => 4 base + 2 aleatorios, 7 => 4 base + 3 aleatorios,
  // 8 => 5 base + 3 aleatorios, 9 => 5 base + 4 aleatorios, y continúa alternando.
  const fixedBaseByTotal = { 1: 1, 2: 2, 3: 2, 4: 3, 5: 3 };
  const fixedBase = Object.prototype.hasOwnProperty.call(fixedBaseByTotal, amount)
    ? fixedBaseByTotal[amount]
    : Math.max(0, Math.min(amount, Math.floor(amount / 2) + 1));
  const random = Math.max(0, amount - fixedBase);
  const cost = { [elementId]: fixedBase };
  if (random) cost.random = random;
  return cost;
}

function getNormalizedCardCost(card) {
  const controlledInvocationTotal = getInvocationTotalCostControl(card);
  if (isCatalystCard(card)) {
    const randomCost = getCatalystRandomCostTotal(card, controlledInvocationTotal);
    return randomCost > 0 ? { random: randomCost } : {};
  }
  if (controlledInvocationTotal != null) return distributeInvocationCostByTotal(card, controlledInvocationTotal);
  const rawCost = card?.cost || {};
  const normalized = {};
  Object.entries(rawCost).forEach(([key, value]) => {
    const amount = Math.max(0, Number(value) || 0);
    if (!amount) return;
    normalized[key] = (normalized[key] || 0) + amount;
  });
  return normalized;
}

function getCardTotalCost(card) {
  const dynamicAmount = Math.max(0, Number(card?.dynamicCost?.amount || 0));
  if (dynamicAmount > 0) return dynamicAmount;
  return totalCost(getNormalizedCardCost(card));
}

function getCardCostEntries(card) {
  const cost = getNormalizedCardCost(card);
  const elementId = getCardElementId(card);
  const ordered = [];
  if (cost[elementId]) ordered.push([elementId, cost[elementId]]);
  Object.entries(cost).forEach(([key, value]) => {
    if (key === elementId || !value) return;
    ordered.push([key, value]);
  });
  return ordered;
}

function getCardCostSummary(card) {
  const elementId = getCardElementId(card);
  const elementLabel = (ELEMENTS.find(el => el.id === elementId)?.label) || elementId;
  return getCardCostEntries(card).map(([id, amount]) => {
    if (id === 'random') return isCatalystCard(card) ? `${amount} aleatorio universal${amount === 1 ? '' : 'es'}` : `${amount} aleatorio${amount === 1 ? '' : 's'}`;
    if (id === elementId) return `${amount} ${elementLabel}`;
    const label = (ELEMENTS.find(el => el.id === id)?.label) || id;
    return `${amount} ${label}`;
  }).join(' + ') || '0';
}


function getEffectiveCardCost(card, playerId = null) {
  // Costos reales de la carta. El dominio del Kaster no convierte Fuego en Luz ni viceversa.
  const baseCost = getNormalizedCardCost(card);
  const reduction = getDespliegueAnticipadoCostReduction(card, playerId);
  return reduction > 0 ? reduceCostObjectByAmount(baseCost, reduction) : baseCost;
}

function getEffectiveCardCostEntries(card, playerId = null) {
  const cost = getEffectiveCardCost(card, playerId);
  const elementId = getCardElementId(card);
  const ordered = [];
  if (cost[elementId]) ordered.push([elementId, cost[elementId]]);
  Object.entries(cost).forEach(([key, value]) => {
    if (key === elementId || !value) return;
    ordered.push([key, value]);
  });
  return ordered;
}

function getEffectiveCardCostSummary(card, playerId = null) {
  const cost = getEffectiveCardCost(card, playerId);
  return Object.entries(cost).map(([id, amount]) => {
    if (id === 'random') return isCatalystCard(card) ? `${amount} aleatorio universal${amount === 1 ? '' : 'es'}` : `${amount} aleatorio${amount === 1 ? '' : 's'}`;
    const label = (ELEMENTS.find(el => el.id === id)?.label) || id;
    return `${amount} ${label}`;
  }).join(' + ') || '0';
}


